UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Disarming Axe Throwers [PH]', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 6 Edged Throwing Axes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Zandalari Edgetossers to the north are known for becoming fierce Pterodactyl riders and axe throwers. Even now, they train the Pterodactly Hatchlings to become ravenous beasts.nnPlease, dispatch of some of the Edgetossers and bring back some of their throwing axes so they cannot be used against us.', `QuestDescription`) WHERE `ID` = 32468;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Urging on Hatchlings [PH]', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Frighten 12 Pterodactyl Hatchlings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Pterodactyl Hatchlings being trained by Zandalari to the north are not yet the violent and savage beasts they are to become.nnI believe we should save these creatures before the trolls corrupt them. If you could just frighten them off, perhaps some of them will be spared an unfortunate fate.', `QuestDescription`) WHERE `ID` = 32469;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Plundering Profferings [PH]', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 15 Plundered Profferings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While the Zandalari perform live sacrifices, they will not offend their gods by sacrificing a life without also sacrificing offerings of food, treasure, and other items of value.nnRecover some of the offerings from cairns in the Troll Town to the north so we might delay their sacrifices further.', `QuestDescription`) WHERE `ID` = 32470;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Apple Crushing [PH]', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Crush 20 apples.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The troops love cider. Hard cider. Before we can make any, we need to get all these apples crushed. Mind giving us a hand - or a foot - and crushing some of the apples in that vat behind me?', `QuestDescription`) WHERE `ID` = 32471;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Karabor!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Chronalis, then fly into Karabor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Draenor will not be a friendly place for someone like you. There are far too many orcs here, and I know your kind has a history with the orcs.$b$bNo, if you\'re looking for a friendly face here on Draenor, you\'ll need to find the draenei.$b$bHop on my back. I will take you to the draenei temple of Karabor.', `QuestDescription`) WHERE `ID` = 33028;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Call of War', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Kaati\'s Letter to Faran at Teluuna Observatory.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you are reading this letter, it likely means that I am dead. Please deliver this to my son, Faran, at Teluuna Observatory.$B$B$BDearest Faran and Elsa,$B$BI have fallen in the line of duty while defending the Temple of Karabor.$B$BPlease know that I love you both with all of my heart. My spirit will watch over you for the rest of your days. Be strong, love one another, and live this life to the best of your ability.$B$BI am so proud of you both.$B$BLove,$B$BYour Mother', `QuestDescription`) WHERE `ID` = 33071;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Memory of Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Dancing Ember at the ring of fire.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The obsidian chip is hot to the touch, but strangely, can be held with no fear of being burned.>$B$BOn its surface is etched a picture - a rectangular stone with a hole cut through the middle, surrounded by a ring of flames.$B$BThere is just such a stone in the fields to the north.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Starmancer Heidii at The Arbitum in Shadowmoon Valley.', `QuestCompletionLog`) WHERE `ID` = 33074;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Demons Among Us - Alliance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Ginni Gingerlips to craft a Shadowmoon orc disguise.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have the cloth and leather, we can craft a fitting disguise for our infiltration mission.$B$BGo speak to Ginni Gingerlips. She has proven herself quite capable in the realm of... errr... garment design.', `QuestDescription`) WHERE `ID` = 33079;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Brute Beatdown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Mokrik Blackfingers, Rukah the Machinist, and Gar Steelcrush.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This Iron Horde has no honor.$b$bTheir leaders spit on us and laugh as we do their bidding.$b$bMany of my brothers and sisters have died at their hands.$b$bIt is time to send these savages to an early grave.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Laabru at the Gar\'mak Quarry in Shadowmoon Valley.', `QuestCompletionLog`) WHERE `ID` = 33150;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fight for Freedom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Give weapons to Enslaved Draenei and kill Iron Horde orcs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Iron Horde keeps us here against our will. They control us with fear and aggression.$b$bIt pains me to see my people subjugated like this.$b$bAll we need to stand up to these beasts is hope... and a large weapon.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Laabru at the Gar\'mak Quarry in Shadowmoon Valley.', `QuestCompletionLog`) WHERE `ID` = 33154;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Task: Destroy Iron Horde Banners', `LogTitle`) WHERE `ID` = 33155;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To the Defense of Karabor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with [FLIGHT MASTER], then report to Akama at the rear entrance to Karabor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Get your bad self to Karabor, you $cy little $r-muffin.', `QuestDescription`) WHERE `ID` = 33253;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Task: Trapped Critters', `LogTitle`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Free the Frostwolves being held by the Grimfrost ogres.', `QuestDescription`) WHERE `ID` = 33330;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Iron Tide', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Arnokk the Burner and 10 Iron Horde troops within Karabor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The majority of Karabor\'s defensive troops are dealing with the main battle front, just west of here. We must not ignore our flanks while dealing with that assault.$b$bOne of the enemy leaders, Arnokk, is directing the mayhem on this side of the temple. Take him out, along with as many of his orcish followers as you can stomach.$b$bOnce you\'ve finished, meet me in front of the temple.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'The orc is fixated on fire.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Arnokk the Burner', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Report to Prophet Velen at the front side of Karabor.', `QuestCompletionLog`) WHERE `ID` = 33463;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'From Over the Walls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Dislodge 6 Blackrock Grappling Hooks near Karabor\'s outer walls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Karabor is falling. The Iron Horde will not stop this assault until every last one of us is dead and cold on the ground.$b$bI don\'t know about you, but I don\'t plan on letting that happen.$b$bNow, there must be something we can do to prevent them from scaling the walls...', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Report to the staging area near Karabor\'s western entrance.', `QuestCompletionLog`) WHERE `ID` = 33464;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Iron Horde in Karabor', `LogTitle`) WHERE `ID` = 33496;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unexpected Assault', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Bonechewer Orcs and direct $2oa Auchenai to safety in the Court of Souls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thank the Light you\'re here. The Bonechewer orcs have invaded!$B$BWe\'ve dealt with the occasional raid before, but they\'ve never attacked Auchindoun with such numbers before.$B$BWe arrived as quickly as we could to respond to the threat, but the local guard had already fallen. We cannot afford to lose more men!$B$BKill all of the Bonechewer you can and help consolidate our forces back to our defensive line. The Bonechewer must not be allowed to step foot in Auchindoun!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Exarch Maladaar at the Auchindoun North Gate in Talador.', `QuestCompletionLog`) WHERE `ID` = 33509;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Save Auchenai Caretakers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Direct 6 Auchenai Caretakers to safety in the Court of Lights in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was fortunate enough to be delivering a report to the Exarch when the demons attacked, but the rest of my brethren were out tending to the Court of Lights!$B$BWe caretakers are not the fighters of our order. Go to the court northwest of here and help direct them to safety.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Levixus at the Auchindoun North Gate in Talador.', `QuestCompletionLog`) WHERE `ID` = 33521;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Desperate Times', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ride to the Tomb of Lights with Exarch Maladaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have heard of the orcs you saw in the tomb before... this is not good news.$B$BIf they seek the key to Auchindoun, we must stop them from obtaining the remaining key fragments. Nyami was right; the fragments are no longer safe where they lay.$B$BThere\'s no time to waste. We will ride together to the Tomb of Lights and secure them ourselves.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Exarch Maladaar at The Tomb of Lights in Talador.', `QuestCompletionLog`) WHERE `ID` = 33547;
UPDATE `quest_template` SET `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '[DNT] Log Description', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[DNT] Quest Description', `QuestDescription`) WHERE `ID` = 33634;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Insatiable Swarms', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $oa Podlings at Kuuros Farm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Something has spurred the podlings that live in the nearby forest to come here. They are scaring the talbuk, eating the crops, and slaughtering my people!$B$BI led refugees from Tuurem here in search of safety from the Iron Horde, and now we have to contend with these foul creatures!$B$BPlease, you must help us! I need to attend to my wife\'s wounds and guide her to safety. Meet me inside the farm proper towards the back when their numbers have been culled back.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Beldos at Kuuros Farm.', `QuestCompletionLog`) WHERE `ID` = 33638;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Talbuk Roundup', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue 4 Talbuk at Kuuros Farm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My father, Karmaan, owns this farm, and our main livestock are talbuk. One of the podlings must have opened the gate to their pen and they all escaped!$B$BThe little terrors could have slaughtered them in the cage, but they like to hunt their prey. I\'m afraid that if I stay out here much longer, I\'ll be their next meal!$B$BWill you round up the talbuk and bring them here? I can\'t get them myself, and I can\'t let my dad find out about this!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Luuco at Kuuros Farm.', `QuestCompletionLog`) WHERE `ID` = 33656;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Iron Missive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Burn the Iron Horde Supplies and the Iron Horde Camp.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The missive outlines a plan to pollute Elekk Acres to ruin the Draenei food supply while their leader, Thokk, sends a force from a camp on the hill to the northwest to slaughter the remaining refugees.>$B$B<If you burn their supplies here and their forward camp with the torches they left here, you can buy precious time to organize a defense against the imminent attack!>', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Beldos at Kuuros Farm in Talador.', `QuestCompletionLog`) WHERE `ID` = 33658;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'That\'s No Podling', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Bloodthrasher.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<This leaf appears to have come from a plant hydra. The refugee sightings Beldos mentioned must have been true!>$B$B<If one got to the farm, the draenei refugees would stand no chance. Killing it now would buy valuable time for the refugees to reach safety.>$B$B<It must still be at the nearby podling den to the west.>', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Bloodthrasher', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Beldos at Kuuros Farm.', `QuestCompletionLog`) WHERE `ID` = 33686;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demons Among Us - Horde', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Thamuun\'s Letter to Thalia at Teluuna Observatory.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you are reading this, it means I have fallen in battle. As my last request, please deliver this letter to Thalia at Teluuna Observatory.$B$B$BDearest Thalia,$B$B$BYou have always been my best friend, ever since we were children growing up in Tuurem.$B$BI have always been too afraid to tell you my feelings, but I cannot leave this world without finally speaking the truth.$B$BThalia, I love you with all my heart.$B$BI shall wait for you in the next world. I will for eternity for you.$B$BLove,$B$B$BThamuun', `QuestDescription`) WHERE `ID` = 33707;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Karmaan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Karmaan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You saw iron horde fighting the podlings!? That must be why the podlings are attacking here; they\'ve been displaced!$B$BUnfortunately, they likely followed me and the other refugees from Tuurem to here. Light help me, I\'ve doomed us all.$B$BWe should go tell Karmaan about this. If the iron horde is nearby, podlings might be the least of our problems.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Karmaan at Kuuros Farm.', `QuestCompletionLog`) WHERE `ID` = 33733;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Thing in the Cave', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay the Thing in the Cave, then loot its Dreadful Heart.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The note reads as follows:$b$b"It cannot be defeated. No matter how many troops we send at it, it seemingly cannot be destroyed.$b$b"We have lost too many lives as it is. I refuse to send another orc after that thing. Instead, we will establish a guard station outside the cave\'s mouth to keep it from getting out."', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return the Dreadful Heart to Ovuun the Dunewalker at your caravan in Gorgrond.', `QuestCompletionLog`) WHERE `ID` = 33766;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Survivalist\'s Way', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Glowworm Silk and $2oa Razorfang Teeth in The Arbitum in Shadowmoon Valley.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was tracking the Iron Horde\'s movements through the Iron March when I was spotted by one of their chimera riders.$B$BI was able to fight off their kill squad, but I\'m too injured to keep going. Stranger, I must obtain as much recon as possible to aid in Karabor\'s defense.$B$BIf you can bring me silk from the worms and a handful of teeth from the rays at the lake nearby, I can operate on my wounds and fashion a bandage that ought to hold long enough for me to finish my mission.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Kyresh near The Arbitum in Shadowmoon Valley.', `QuestCompletionLog`) WHERE `ID` = 33781;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keeping the Balance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Snapgrip in The Arbitum.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Look at these teeth, friend. These stress markings suggest that the crocolisk are being subjugated by one of their own. When a crocolisk female grows large enough, she exerts dominance over her kin.$B$BIt is my duty as a hunter to ensure balance is restored to these creatures as thanks for their sacrifice for my own life.$B$BTrack down the beast and slay her while I tend to my wounds. She is likely at the far end of the arbitum.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Snapgrip', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Kyresh near The Arbitum in Shadowmoon Valley.', `QuestCompletionLog`) WHERE `ID` = 33782;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Kuuros Farm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Beldos at Kuuros Farm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Many refugees from Tuurem have made their way to Kuuros Farm east of here.$B$BIf you are able, please venture there and find Beldos. He led the refugees there from Tuurem and will be the best point of contact.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Beldos.', `QuestCompletionLog`) WHERE `ID` = 33783;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Signs of a Struggle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ruffle through the backpack near the bloody journal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Judging by the markings, it appears to be a journal kept by a Shadowmoon orc.$B$B<Hagra disappeared last night. She is the fifth in as many nights. Why do they only vanish at night?>$B$B<I will find out. Tonight I wait for whatever manner of beast stalks our village.>$B$B<I will bring the beast\'s head to Rulkan, and return my kin to their homes.>$B$BPerhaps the beast\'s head is in one of the bags in the debris up ahead?', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Break your bonds and speak to Rok\'nar.', `QuestCompletionLog`) WHERE `ID` = 33817;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Laabru\'s Rebellion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Laabru at the Gar\'mak Quarry in Shadowmoon Valley.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Laabru wouldn\'t listen. He killed one of the guards and they dragged him off to one of their tents.$b$bThey are going to kill him for sure!', `QuestDescription`) WHERE `ID` = 33822;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Plight of the Worgen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Soothpetal Flowers and $2oa Frog Eyes and bring them to Tess Greymane in Twilight Glade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'King Greymane, my father, has fallen ill! Every day he\'s worse, losing control over his mind, becoming... feral. He\'s bedridden in Stormwind as we speak, and he isn\'t the only one.$B$BKrennan Aranas found what he thought might be the cure in Outland, but it was corrupted beyond recognition. I need to find the cure before he loses every bit of his humanity!$B$BHemma, one of my guards, is sick as well. I need you to collect some soothpetal flowers and frog eyes. We have to try something.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Tess Greymane at Twilight Glade in Twilight Glade.', `QuestCompletionLog`) WHERE `ID` = 33840;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Goren, Goren, Gone!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy 15 Goren Stonechewers and their leader, Pastrok within the Jorune Quarry.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s uncommon to see goren in Talador. We need to get a handle on this situation before it spreads and we lose all of our precious gems.$b$bThe only answer is to dispose of the creatures, and quickly!$b$bIt is imperative that you kill the leader too! If you don\'t they will just continue to come back.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Pastrok', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Crystal-Shaper Attica outside of the Jorune Quarry.', `QuestCompletionLog`) WHERE `ID` = 33875;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'No Miner Left Behind', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue 8 Jorune Miners from within the Jorune Quarry.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In all of my years working the quarry I have never seen goren in this number. They came on so quickly, we had no time to react.$b$bNow the quarry has been weakened from their tunneling and eating. it\'s only a matter of time before the whole thing collapses.$b$bI refuse to leave anyone to die in there with those things! Please help me, $r. Save as many of my miners as you can.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Foreman Raluum outside of the Jorune Quarry.', `QuestCompletionLog`) WHERE `ID` = 33878;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power Shards', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Shard of Souls in the Tomb of Souls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know what the Bonechewer are after.$B$BAuchindoun is protected by a powerful barrier, which can only be disabled using an ancient key. No being could ever hope to penetrate it.$B$BThe Auchenai, my people, split the key into three shards long ago and hid each piece outside the mausoleum walls. We guard those shards with the same zeal as Auchindoun itself.$B$BGo into the Tomb of Souls and retrieve the key from Soulbinder X. The shards are no longer safe.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Soulbinder Nyami at the Auchindoun North Gate in Talador.', `QuestCompletionLog`) WHERE `ID` = 33907;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Origin Unknown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Voidborne Errants in Waning Crescent. Afterwards, shut down the portal in Waning Crescent.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'For my first field assignment, I would say I\'m doing quite well!$B$BI\'ve discovered a strange portal in this cave that has unleashed a number of equally strange void creatures, and there\'s no clear reason why! Fascinating, isn\'t it?$B$BScientific inquiry aside, these things may be benign right now, but at the rate they\'re pulling energy in that won\'t last long.$B$BI need you to take them out, send their essences back to... wherever it is they came from, and shut down that portal!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Field Researcher Alduuri in Shadowmoon Valley.', `QuestCompletionLog`) WHERE `ID` = 34055;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[DEPRECATED] Keeping Calm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Kaduz in the Cave of Spirits below Palemoon Village and rescue him from Ner\'zhul\'s agent.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My husband, one of our shaman, went to the ritual cave just below the village to seek the advice of our ancestors.$B$BJust before you arrived I heard sounds of fighting coming up from there. I fear that one of Ner\'zhul\'s agents has attacked him!$B$BPlease, will you go find him and return him home safely?', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Harbinger of Revenge', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Dulga in Palemoon Village.', `QuestCompletionLog`) WHERE `ID` = 34059;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Search For Drogguk', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Drogguk in the Iron March.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Drogguk has taken it upon himself to watch the Iron Horde\'s movement to ensure they do not find our village.$B$BIt has been two days and he has not yet returned. If you are willing, I would ask that you seek him out and bring him home. His family worries.$B$BHe tends to make his post roughly southeast of here.', `QuestDescription`) WHERE `ID` = 34064;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return To Sender', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return the Subdermal Tracking Device.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This tiny tracking device is used to collect biological data. It appears to have been fastened to a dart and fired from long range.$b$bAfter closely examining the device, you are able to trace the signal to a receiver nearby. The information contained within could be important; it\'s probably a good idea to find the owner and return it.', `QuestDescription`) WHERE `ID` = 34080;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[DEPRECATED] Keeping Calm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Dulga in Palemoon Village.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<These beads must belong to Kaduz, the shaman you rescued. They are engraved with the name "Dulga".>$B$B<He said to meet him in nearby Palemoon Village. You will surely find both Kaduz and Dulga there.>', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Dulga in Palemoon Village.', `QuestCompletionLog`) WHERE `ID` = 34084;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'They Have My Son', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Key to Corki\'s Cage and set him free.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Please, $p! Can you help me. I received a ransom note from a very corrupt and uncouth orc within the ranks of the Iron Horde.$b$bHe has my son!$b$BHe made sure to include a number of graphic words to describe what would happen if the ransom is not paid. Clearly he thinks my people conjure gold from the nether. And if I try to rescue him myself, both of us will be killed in the process.$b$bCan you go to Gron\'mar for me and rescue my son?$b$bHis name is Corki.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Arechron in your Garrison.', `QuestCompletionLog`) WHERE `ID` = 34213;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Threat We Can\'t Ignore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Plant the Underwater Explosives on the Iron Horde battleship.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ishnu-alah, $n. I trust that Khadgar and Mathias have adequately briefed you on this situation here in Grommar. Time is of the essence, so I will be brief.$b$bThe Iron Horde presence here represents an immediate threat to the safety of Shadowmoon Valley. Grommar has been receiving supplies and reinforcements via the harbor for some time now.$b$bThe most concerning of these reinforcements are the battleships docked in the harbor. Place these explosives on the nearest battleship undetected and report back.', `QuestDescription`) WHERE `ID` = 34299;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mutation Station', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist Grulk in destroying the Mutation Lab by administering the Mutation Serum to him.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Grulk very weak...barely stand.$b$bGrulk not always look this way. Grulk once was orc...Iron Horde make Grulk mutant. Grulk angry at Iron Horde...so Iron Horde lock Grulk in cage...hurt Grulk.$b$bGrulk HATE Iron Horde...Grulk want SMASH them...make them PAY!$b$bTake serum...use on Grulk to make Grulk strong! Help Grulk SMASH Iron Horde!', `QuestDescription`) WHERE `ID` = 34304;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tearing Up Talador', `LogTitle`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, we have a bit of a problem.$bWe found a location in Talador to set up an outpost but the team that was sent to begin construction have been arguing with each other on what to build. This situation could really put a setback in our plans unless it\'s dealt with swiftly.$b$bTake a gryphon to Talador and speak with Foreman Eksos before this gets any worse.', `QuestDescription`) WHERE `ID` = 34532;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Open the Portal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'xxxxx', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'xxxxxx', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'xxxxxx', `QuestCompletionLog`) WHERE `ID` = 34637;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One Step Ahead', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Vindicator Maraad in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, Vindicator Maraad took Yrel and Thaelin Darkanvil just up to the road from here to track the Iron Horde\'s forces in the forest.$B$BThey are already at work formulating a strategy to stop their operations. They await your arrival on the cliffs to the northwest.', `QuestDescription`) WHERE `ID` = 34684;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lurking in the Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Shadowmoon Disrupters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There are reports of Shadowmoon clan members lurking around the ruins by the shore.$b$bThis is a popular spot for young lovers to gaze at the stars and confess their affection for each other.$b$bAs you can see we are not a village of warriors.$b$bI will pay you handsomely if you go to the ruins and make sure the Shadowmoon orcs keep their distance.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Hara Bloodfury at Exile\'s Rise.', `QuestCompletionLog`) WHERE `ID` = 34845;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prepare for Battle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 30 Blackrock Weapons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There\'s nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde.$b$bIt\'s time to turn this unarmed group of prisoners into an army.', `QuestDescription`) WHERE `ID` = 35005;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'UNUSED', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '[PH] asdf', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[PH] Now that we\'re somewhat safer and the texts are returned go report back to the High Ravencaller. We will continue our prayers here.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', '[PH] asdf', `QuestCompletionLog`) WHERE `ID` = 35008;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Skulltaker\'s Revenge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Fungal Lurchers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The others... gone or wandered into the haze.  It called to me as well but I am too strong.  I chose to kill until they crushed my body.  I haven\'t killed enough of them yet $p, not enough!  Go.  Kill more of them and tell my hunt leader that I don\'t go alone into the dark.', `QuestDescription`) WHERE `ID` = 35017;
