UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prepare for Battle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 30 Blackrock Weapons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There\'s nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde.$b$bIt\'s time to turn this unarmed group of prisoners into an army.', `QuestDescription`) WHERE `ID` = 35019;
