UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mysterious Pod', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Glowing Red Pod to Grulkor at Crimson Fen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This pod is similar to the ones growing on or near the bodies around here, except this one is pulsating weirdly.  Grulkor might know more about this.', `QuestDescription`) WHERE `ID` = 35021;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Krikka and Vakora Tracking', `LogTitle`) WHERE `ID` = 35028;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Welcome to Gorgrond', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow the Wildwood Wash to Naielle\'s Watch.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Gorgrond is one of the most untamed landscapes in all of Draenor.$b$bOnly the most skilled of rangari venture this deep into the wilds.$b$bIt is their camp we are heading for. If you wish to travel ahead, it can be found down this path and to the right.$b$bMaraad and I shall follow after you momentarily. We still have some logistics to work out before we leave the landing.', `QuestDescription`) WHERE `ID` = 35033;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cordana Summon', `LogTitle`) WHERE `ID` = 35044;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In Ared\'s Memory', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Miall inside of Fort Wrynn in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My master has gone on to the Light, but I will continue his work.$b$b<Miall looks to Ared >$b$bShanai ortar, Ared.$b$bI will have his body sent to Auchindoun. For now, show me this artillery tower of yours.', `QuestDescription`) WHERE `ID` = 35045;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dropping Bombs Tracking', `LogTitle`) WHERE `ID` = 35047;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lumber Mill', `LogTitle`) WHERE `ID` = 35049;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rescue Rangari', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Rangari Rajess, Rangari Kolaan, and Rangari Jonaa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Many of our rangari have not been accounted for. It would seem the followers of Iyu have taken captives.$b$bWe will continue to search the area for survivors.$b$bIn the meantime, follow the Wildwood Wash west toward Highpass and look for any signs of our rangari comrades.$b$bOur people are stout and capable survivors. You may find more than you expect. Have them stay near the road and we will follow as soon as this... dwarf creature... has fixed his mechanical vessel.', `QuestDescription`) WHERE `ID` = 35050;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mage Tower Complete', `LogTitle`) WHERE `ID` = 35051;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lost Mole Machines', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Missing Mole Machine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Few people know the Blackrock clan better than Dark Iron dwarves.$b$bSo after Tanaan, we sent a bunch of mole machines to Gorgrond to build a listenin\' post to keep an eye on them.$b$bMe own mole machine got way off course an\' I got separated. It didn\'t take long to figure out all the other mole machines got off course as well.$b$bAccordin\' to the readin\'s in me tank, a mole machine surfaced somewhere way to the west of here.$b$bMind scoutin\' ahead while we get this tank operational?', `QuestDescription`) WHERE `ID` = 35055;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Flag - Horned Skull', `LogTitle`) WHERE `ID` = 35056;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette XP reward - Frostfire', `LogTitle`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This quest is a placeholder until Task 67719 is complete.', `QuestDescription`) WHERE `ID` = 35057;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Along the Riverside', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Vindicator Yrel at Yrel\'s Watch.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Vindicator Yrel has taken most of our forces north. She\'s establishing a forward base along the Skysong River.$B$BShe\'ll want to know that we\'re almost ready to move against Grommashar.$B$BI\'m sure she can also use your help dealing with the Warsong orcs at Lok-rath.', `QuestDescription`) WHERE `ID` = 35059;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Need An Outpost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Drafting Table to craft a Lumber Yard or a Sparring Arena.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, we\'ve gathered enough materials to build an outpost that will support our mission against the Iron Horde.$b$bHow shall we proceed?$b$bA lumber yard would be valuable for gathering resources in the dense overgrowth to the south, and in confronting the plant monstrosities that defend it.$b$bOn the other hand, a sparring arena would provide us the brutish forces we\'d need to push through the magnaron wastelands to the north.$b$bWhen you\'re ready, make your choice on the table.', `QuestDescription`) WHERE `ID` = 35063;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sparring Arena', `LogTitle`) WHERE `ID` = 35064;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Harvester Has Come', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Harvester Ommru.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is what happens when one stands in the path of a genesaur. And where a genesaur walks, the botani follow.$b$bI saw one entering our shelter cave along the northern side of the camp.$b$bIt is commanding the podlings to gather the corpses of our fallen brethren and must be stopped.$b$bI must tend to our wounded, and gather supplies for our departure.$b$bIf you are serious about being a hero, venture into the cave and slay this botani.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'He is a weapon of the genesaur, Iyu.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Harvester Ommru', `PortraitGiverName`) WHERE `ID` = 35065;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Jawless Skulker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mak\'jin wants you to collect 10 Jawless Skulker Eggs from Gorgrond.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need to stock the garrison pond with local fish.  I need you to search the waters in Gorgrond for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.', `QuestDescription`) WHERE `ID` = 35071;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blackwater Whiptail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mak\'jin wants you to collect 10 Blackwater Whiptail Eggs from Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need to stock the garrison pond with local fish.  I need you to search the waters in Talador for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.', `QuestDescription`) WHERE `ID` = 35074;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Defungination', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the QR58 Flame Blaster to destroy 20 Spore Pustules.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Have you seen the fungus out there in the water? It\'s growing faster than a baby ravasaur from Un\'goro, and if we don\'t get it under control, the Gearworks is gonna be ruined like our last village.$b$bUncle Krixel used to tell me to burn away the red fungus because that\'s what makes it grow so fast.$b$bYou could help us out by taking a flame blaster and clearing out some of those spores down in the shallows.', `QuestDescription`) WHERE `ID` = 35077;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spore-be-Gone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate 6 Spore-be-Gone Turrets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We got an emergency!$b$bA bunch of spore drifters have infested the shore and tore up our Spore-B-Gone turrets.$b$bWe\'re caught with our armor off here! If we don\'t get those turrets back online then those spores are going to float right in to town and then we\'ll have another Pinchwhistle Point on our hands!$b$bWe need to get out there and manually activate them.$b$bWell? Are you in?', `QuestDescription`) WHERE `ID` = 35079;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Mother Lode', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet up with Kimzee Pinchwhistle at the Wreck of the Mother Lode.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hey we got ourselves a crisis here! Our zeppelin "The Mother Lode" crashed onto the south mountain range.$b$bIt was supposed to only be on an observation mission, what could have happened?$b$bWe got to get down there quick and I\'m going to need your help on this.$b$bAre you with me?', `QuestDescription`) WHERE `ID` = 35080;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clearing Out Before Cleaning Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Crimsonwing Wasps.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here\'s the situation.$b$bWe need to get this salvage operation moving ASAP, but the ship went down right in the middle of the wasp nests.$b$bThe ugly bugs are all over the place, and I can\'t call my team in here to start work until they\'re taken care of.$b$bGo kill as many of \'em as you can and I\'ll cut you in on some of the haul.', `QuestDescription`) WHERE `ID` = 35081;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Getting the Crew Back Together', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Revive 6 Injured Crewmen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh wow, the debris is all over the mountainside! The survivors won\'t make it if we don\'t do something quick. They need healing NOW!$b$bHere, take my bandages and go patch them up.', `QuestDescription`) WHERE `ID` = 35082;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Skimming Off the Top', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Volatile Oil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That flying machine is our ticket out of here but its fuel tank is bone dry!$b$bWe\'re right next to the oil fields but with the infected out there we don\'t have time to run a line up here so we need to improvise.$b$bThe oil creatures moving next to the pumps out there are full of a highly potent mixture that I can drop right into the tank. Grab some of that oil for me and we\'ll be one step closer to getting out of here.', `QuestDescription`) WHERE `ID` = 35089;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Right Parts for the Job', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the G-14 Buster Rocket near Broken Shredders to retrieve Serviceable Gears.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Uncle Krixel\'s a tough one but he won\'t be going anywhere on foot with his leg broken.$b$bHe has a flying machine he brought from Azeroth that can fly us out of here. Problem is, the engine\'s busted.$b$bI\'ll need some parts to fix the thing. My car\'s wasted but those broken shredders just outside of town should have what we need. We don\'t have time to break them down by hand so just use this rocket launcher and blow \'em apart. Anything that survives the blast should be strong enough to use on the engine.', `QuestDescription`) WHERE `ID` = 35090;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sporicide', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Spore Shamblers in Pinchwhistle Point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s revolting, absolutely disgusting, infuriating even!$b$bI\'m talking about seeing those spore creatures walking around Pinchwhistle Point.$b$bWhile I\'m working on the machine here how about you go out and kill off some of those spore creatures? I\'ll feel a bit better knowing there are less of those things moving around.', `QuestDescription`) WHERE `ID` = 35091;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unleashed Steel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Morketh Bladehowl inside of Vol\'jin\'s Pride in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thank you... boss.$b$bI won\'t let you down! I didn\'t even try to sneak one of those low quality blades here that one of your peons placed right next to the cage. Which by the way was a pretty terrible idea and that thing should be moved before you get anyone less honorable in here.$b$bEnough talk, lets check this place out!', `QuestDescription`) WHERE `ID` = 35102;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Good Doctor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue Dr. Hadley Ricard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our expedition biologist has been kidnapped by podlings!$b$bWe came to Nagrand to explore, to slay the mightiest of beasts, and test our mettle alongside the great Hemet Nesingwary.$b$bAs soon as we arrived, Hemet\'s hunting prowess was needed to combat the Warsong. Rather than sit around twiddling our thumbs, we decided to continue the expedition!$b$bWe were exploring Spiteleaf Thicket when podlings ambushed us! In the chaos, Dr. Hadley Ricard was taken captive.$b$bPlease, we can\'t just leave him there!', `QuestDescription`) WHERE `ID` = 35146;
