UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trouble at the Overwatch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Rangari Eleena at Mar\'gok\'s Overwatch.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ya know, we sent a couple o\' scouts ta check out those big, smelly, \'civilized\' ogres at Mar\'gok\'s Overwatch.$B$BHaven\'t heard from \'em in a bit. Matter o\' fact, not since I saved yer bacon up at Telaar.$B$BHave some time ta ride over there and check up on \'em, $g boyo:girly;?', `QuestDescription`) WHERE `ID` = 35148;
