UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ship Salvage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa crates of Drudgeboat Salvage.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, we are running low on supplies.$b$bMaybe we can salvage materials from that ship you arrived on?$b$bAt the rate folks are coming through the portal we are going to be out of everything by sundown... or moondown?$b$bI\'m still getting used to this place.', `QuestDescription`) WHERE `ID` = 35166;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lost in Nagrand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Mankrik\'s girlfriend, Olgra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hey, $g mister:lady;, could you help me?$B$BThere\'s this girl I know. Her name\'s Olgra. Her and her parents went back to Wor\'var yesterday. Only, they never got there and no one\'s seen them.$B$BIf you\'re heading back out, would you look for her?$B$BShe\'s kinda my girlfriend.', `QuestDescription`) WHERE `ID` = 35167;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pale Moonlight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Gnaw Bloodseeker and $2oa Pale Devourers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are getting strange reports of an orc attack on a nearby draenei settlement called Eventide Landing.$b$bI\'m hearing these particular orcs are unlike any we have encountered before.$b$bThey seem... sickly, and are pale in color.$b$bThe locals could use our help, commander. This seems like the perfect opportunity to test our garrison\'s capabilities.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Gnaw Bloodseeker', `PortraitGiverName`) WHERE `ID` = 35174;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keeping it Together', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Shelly, find Assistant Brightstone, and check the Garrison Cache.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So much work to do... I don\'t even know where to start.$b$bMaking sure this garrison is operational is not an easy task.$b$bShelly still hasn\'t reported back to me, my assistant Brightstone and her crew are who knows where, ugh... I\'m so caught up I haven\'t even had time to check our cache for resources.$b$bIf I were a mage, do you think I could use mirror images to do all of this at once?', `QuestDescription`) WHERE `ID` = 35176;
