UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Preventing the Worst', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place $1oa Firebombs within Pinchwhistle Point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Have you seen all the fungus on the buildings in Pinchwhistle Point? It\'s only a matter of time \'til it releases enough spores to infest the whole coastline!$b$bThe remaining infected that are in Pinchwhistle Point will be too far gone for us to save later on, so let\'s do the right thing and put them out of their misery and prevent an even worse outbreak.$b$bI made some firebombs that will burn the fungus down, but I\'ll need you to place them while I set up the detonator.$b$bAre you up for it?', `QuestDescription`) WHERE `ID` = 35211;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Deeproot', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Thaelin Darkanvil at Deeproot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Since yer all set up to take on trees and bushes now, I need ta ask for a favor.$b$bI came to Gorgrond in search of an expedition of me fellow Dark Irons that were headed this way. Sadly I lost \'em.$b$bI am goin\' south to look for them. Thing is, south is nothing but botani, podlings, giant trees, and other mean, angry plants.$b$bYer lumber camp resources would be mighty appreciated. If ya help me look for me friends I swear we\'ll help ya in any way we can.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Thaelin Darkanvil at Deeproot.', `QuestCompletionLog`) WHERE `ID` = 35212;
