UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Firing the Mayor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Mayor Nurg Boltsnap.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The bottle has a large stopper in it with the label "Property of Mayor Nurg Boltsnap."$b$bAs you gaze at the bottle you hear the sound of heavy machinery coming from the nearby marshland. $b$bAn investigation would be prudent. If the mayor has turned he will also need to be put down.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Mayor Nurg Boltsnap', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Rivett Clutchpop in Venture Cove.', `QuestCompletionLog`) WHERE `ID` = 35222;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ogre Diplomacy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Ango\'rosh in the Ango\'rosh Ruins.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ogres are ogres. Spirits or not, the Ango\'rosh are not different.$B$BEven with their ritual books, they won\'t relinquish their power to you until you prove yourself.$B$BI\'ve fought ogres my entire life, and there\'s only one way to earn that.$B$BKilling them outright.$B$BThe more Ango\'rosh spirits and their pets as you take out while you\'re there, the more respect you\'ll command among them.', `QuestDescription`) WHERE `ID` = 35227;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Firing the Mayor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Mayor Nurg Boltsnap.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ever since this zombie outbreak began I haven\'t seen the mayor at all. If he is infected then we could be in for a huge problem if he can escape out of town. Damn, we could be in for another zombie outbreak even!$b$bWe got to find him and make sure he doesn\'t escape! He used to ride in his custom shredder down on the shore line before the fungus started covering up everything. You might find him down there.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Mayor Nurg Boltsnap', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Rivett Clutchpop in Venture Cove.', `QuestCompletionLog`) WHERE `ID` = 35228;
