UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bled Dry', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free the slaves from the 2 Bleeding Hollow Cages in Heartblood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The draenei spits out his last words.>$b$bThey kept us in cages. They... drain our blood, for... rituals...$b$b<He coughs violently.>$b$b...many left --$b$b    -- my... people...$b$b<The draenei dies.>', `QuestDescription`) WHERE `ID` = 35240;
