UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Follow that Hotrod!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Kimzee Pinchwhistle in Pinchwhistle Point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Miss Kimzee is one tough nugget but Pinchwhistle Point is too dangerous for her to handle alone. It\'ll be a catastrophe for morale if our boss gets infected.$b$bI need to get these crewmen back to the Gearworks so I need you to go and make sure she is alright.$b$bHer uncle\'s place is the tower just on the other side of the oil fields; I think you should look for her around there.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Kimzee Pinchwhistle in Pinchwhistle Point.', `QuestCompletionLog`) WHERE `ID` = 35285;
