UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'What\'s Theirs is Ours', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Shadow Hunter Ukambe at Admiral Taylor\'s Garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I found somethin\' else while I was scoutin\', boss.$B$BDa Alliance have a garrison just across da way, and der been no movement in or out of da place in a good while.$B$BDis be a golden opportunity to sack da place and bolster your coffers, commander.$B$BWhat do ya say? We do it together.', `QuestDescription`) WHERE `ID` = 35295;
