UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Called to the Throne', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Commune with the furies at the Throne of Elements.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was far from here in Talador when the voice called out to me.$b$bI looked around but found myself alone. Again, I heard the voice as if it were a breeze in my mind.$b$b"You are needed at the throne," it whispered.$b$bThe voice called itself Kalandrios, and it guided me to this place.$b$bI had never been here before, nor had I yet beheld these furies with my eyes; yet this feels strangely familiar to me as if it happened long ago in a forgotten dream.$b$bWe should greet the furies and hear them out.', `QuestDescription`) WHERE `ID` = 35331;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nobundo Sends Word', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Vindicator Nobundo at the Throne of Elements.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your presence has been requested at the Throne of Elements, $n.$b$bVindicator Nobundo has heard the call of the furies upon the wind and made the journey to commune with the elements.$b$bI know not what the intentions of the furies are, but they are revered as noble and powerful spirits by the orcs.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Nobundo.', `QuestCompletionLog`) WHERE `ID` = 35332;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: The Egg of Varasha', `LogTitle`) WHERE `ID` = 35334;
