UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'That Pounding Sound', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Pairs of Leatherhide Ears from Leatherhide clefthoof.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander. The rangari and I were just discussing the merits of various \'hunting\' approaches.$B$BI assured her that the SI:7 are well-equipped to deal with any situation, even ones out in the wild.$B$BShe seems to think that we don\'t know what we\'re doing when it comes to bringing down game in \'her land.\'$B$BWe\'re not going to let her get away with saying that, right? Let\'s take down some clefthoof.', `QuestDescription`) WHERE `ID` = 35337;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shooting the Breeze', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Breezestrider Horns from Breezestrider talbuk.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Kia and I are having a spirited debate over who kills more efficiently: SI:7 or rangari.$B$BCare to get in on the wager, commander?$B$BI\'ve been focusing on talbuk because of their fierce majesty. They truly encapsulate the grandeur of Nagrand as any native of Draenor knows.', `QuestDescription`) WHERE `ID` = 35338;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Parting Favor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Spectral Essences from restless spirits inside the garrison and use them to convince Alice Finn of her fate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I don\'t know what happened. My crew and I must have been the first to fall.$B$BMy wife, the innkeeper, is in the same stupor you found me in. I can feel it... and there are others with her.$B$BPlease, give the townsfolk peace and show their essences to my wife. That should bring her back from that cold abyss.', `QuestDescription`) WHERE `ID` = 35339;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Young Alchemist', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Abatha at the Verdant Mire.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I learned a little about alchemy from my aunt. If you want to know more, though, you should speak with my cousin Abatha. She was apprenticing under my aunt before she passed away.$b$bAbatha lives near the Verdant Mire with her father and sister.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Find Abatha.', `QuestCompletionLog`) WHERE `ID` = 35343;
