UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Warsong Threat', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Steal the Warsong Attack Plans.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The attack plans are scrawled onto the parchment in thick, black ink and bound in rough leather.>$b$bTo all outrider stations:$b$bThe warlord has commanded that all outriders prepare for a full assault upon the Alliance invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts.$b$bBlood and glory shall be ours as we trample the Alliance invaders beneath our feet!$b$bThe warlord commands and the Warsong obey! Lok\'tar ogar!', `QuestDescription`) WHERE `ID` = 35386;
