UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Attack of the Iron Horde', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Ironmarch Grunts.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We received reports of the Dark Portal turning red right before the attack. They call themselves the Iron Horde, yet they seem to have no affiliation with the Horde we know.$b$bTheir army is extremely well equipped, and their numbers appear to be unending.$b$bThey have already taken Nethergarde Keep. Our troops on the frontlines could use your help, $c.', `QuestDescription`) WHERE `ID` = 35460;
