UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mementos of the Fallen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Strumner\'s Sword, Keri\'s Mug, and Krolan\'s Shield.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There were so many of them. The guards couldn\'t stop them... nobody could stop them. So many souls stripped of their bodies by those savages.$b$bWe must not forget those that gave their lives to try and defend Nethergarde. Please, if you find any mementos of the fallen, bring them back to me.', `QuestDescription`) WHERE `ID` = 35494;
