UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lost Lumberjack', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Frenna within Tangleheart.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Me friend was in the mole machine wit\' me. Good ol\' Frenna tried to make the best of it by writin\' all o\' her observations down in a journal.$b$bPenny here wants me to tell ya where she is. I cannae say for sure, but she was followin\' me outta here and I don\'t think she made it.', `QuestDescription`) WHERE `ID` = 35505;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Wood', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Ancient Growth Sap from botani or ancients within Tangleheart.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I found this dwarf, Thuldren, runnin\' out of Tangleheart like his boots were on fire.nnSays his mole machine showed up here and he barely made it out alive. And another called Frenna might still be inside.nnOne useful thing he told me is that the creatures in there have sap that can be used to grow things real fast.nnBy the way, I\'m gonna go lookin\' for Thuldren\'s mole machine. Find me in Tangleheart when you\'re done.', `QuestDescription`) WHERE `ID` = 35506;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Chapter I: Plant Food', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy $1oa Pollen Pods.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There are strange, glowing objects within Tangleheart, seemingly pollinated by a variety of stinging creature.nnThe botani sometimes collect whatever the pods produce. I can\'t be sure what it is, but it might be dangerous to us.nn- Frenna', `QuestDescription`) WHERE `ID` = 35508;
