UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Chapter III: Ritual of the Charred', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Ancients.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have seen a strange ritual performed by ancients. They step into fire, burning the leaves from their branches and charring their bark.nnI call it the Ritual of the Charred. If we want to weaken the ancients, we can get rid of them before they become even stronger.nn- Frenna', `QuestDescription`) WHERE `ID` = 35524;
