UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'News from Spires of Arak', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Bodrick Grey at your garrison in Shadowmoon Valley.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you were gone, a rather shady looking human arrived at the outpost asking for you. He said he worked for... Grey was it?... and had some information regarding Spires of Arak that you would be interested in.nnHe was heading back to your garrison and asked that I passed along the message, and so I have.nnAnd before you go, thank you for all you\'ve done for us here, truly. You and your army have turned the tides of a war that you could have just as easily walked away from. We will not forget.', `QuestDescription`) WHERE `ID` = 35554;
