UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rangari in the Red', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Khaano near the Crimson Fen in Gorgrond.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Gorgrond is a very dangerous place and I\'ve sent scouting squads out to investigate various regions.$b$bI\'ve sent one squad to the marsh called the Crimson Fen and they\'ve not come back yet.  I\'d like you to find the missing squad and get a report if possible.', `QuestDescription`) WHERE `ID` = 35666;
