UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'I Drew Aggro...culture', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Thaelin Darkanvil at the Wildwood Wash.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$p? Boy am I glad to see ya.$b$bI was tryin\' ta ditch that genesaur when I stumbled across this rangari camp.$b$bNext thing I know, the ground is creepin\' up and spittin\' out all sorts of angry plants.$b$bI barely made it out of me tank before that genesaur threw it like it was an empty beer mug.$b$bI\'m gonna make my way back to the road an\' look fer me tank.$b$bI\'ll see ya there when yer done.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Thaelin Darkanvil at the Wildwood Wash.', `QuestCompletionLog`) WHERE `ID` = 35828;
