UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azeroth\'s Last Stand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Iron Horde Missive from one of the Iron Horde at the base of the Dark Portal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Countless times you have battled against impossible odds and unspeakable evil - and returned the victor. Now, once more, you have answered the call of duty, prepared to risk your life to save the world that you love - our world.$B$BYou are Azeroth\'s last hope, $n.$B$BWhile the challenges that stand before us are daunting, there is no other that I would trust to lead this mission.$B$BThe enemy at the front may have the information we need to win this war. Seek and destroy!$B$BGo now, $n! For Azeroth!', `QuestDescription`) WHERE `ID` = 35933;
