UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Archmage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar at Khadgar\'s Tower in Zangarra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The amorphous blob of arcane energy appears to be giving people a tour of your garrison.>$b$bCommander $n! I was sent here to summon you.$b$bArchmage Khadgar has a very urgent favor to ask. He is gravely concerned about additional threats this world may hold for Azeroth, and he will need your assistance pursuing them. Please see him at his tower, east of Talador, in the Zangarra swamp.$b$bThis will not take long.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Archmage Khadgar at Khadgar\'s Tower in Zangarra.', `QuestCompletionLog`) WHERE `ID` = 35988;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Khadgar\'s Task', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Khadgar within his tower in Zangarra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This world poses many dangers to our own. Chief among them is the Iron Horde - your garrison and the full might of your army is directed at this foe. But for myself I have a different target in mind.$b$bGul\'dan.$b$bHere, make yourself comfortable. Have some mana strudel. I will share my plan as I create your ring...', `QuestDescription`) WHERE `ID` = 35989;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Core of Flame', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire a Core of Flame from Gug\'rokk in the Bloodmaul Slag Mines [Heroic only.]', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Compared to Azeroth, Draenor is a young world. The primal forces that shaped and bent the land are still accessible - if you know where to look.$b$bI need you to find for me a Core of Flame. The Bloodmaul Ogres have been known to use these to bend molten furies to their will, but you and I can find a much better use for one.$b$bEnter the Bloodmaul Slag Mines and acquire one from Gug\'rokk. He won\'t need it anymore after you kill him.', `QuestDescription`) WHERE `ID` = 35990;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Core of Iron', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Core of Iron from the engine of the Grimrail Depot train [Heroic only.]', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There\'s no point in getting a Core of Flame without any way to focus its power. Somehow, the goblins figured out how to do it - the technology is used in the "Iron Star" engines that the Iron Horde is using extensively throughout Draenor. We\'re gonna need the biggest engine core that we can find.$b$bOur best bet is to derail one of their trains and crack open the engine compartment. I suggest a raid on the Grimrail Depot...', `QuestDescription`) WHERE `ID` = 35991;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Core of Life', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Core of Life by slaying Yalnu in the Everbloom [Heroic only].', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Scrying for a living being is a very specific kind of magic, and if we want to search the whole of Draenor for Gul\'dan, we\'re going to need a very powerful living reagent.$b$bThe answer lies with the plant life of Draenor itself. There is a creature known as a "genesaur" who is the closest we can get to the primordial creatures who shaped all life on this world.$b$bOne of our Kirin-Tor outposts has been overrun in Gorgrond, and a genesaur named "Yalnu" was spotted. Kill it, and bring its heart to me!', `QuestDescription`) WHERE `ID` = 35992;
