UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azuka Bladefury', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Bodrick Grey at your garrison in Shadowmoon Valley.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Agent Springslip is dead. A fire smolders inside a large wound where his heart used to be.$b$bFlipping through a report you find on his corpse you are able to piece together some basic information. Azuka has betrayed the ogres, she has killed Ugbright and taken his power for herself.$b$bYou should report this information to Bodrick at once.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Bodrick Grey at your garrison in Shadowmoon Valley.', `QuestCompletionLog`) WHERE `ID` = 36095;
