UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[PH] Lumber Mill Rank 01 Alliance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 100 pieces of Timber from around Draenor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[PH] FIND TIMBER', `QuestDescription`) WHERE `ID` = 36153;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spires of the Betrayer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Pure Solium Band from High Sage Viryx in Skyreach.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have much to ask of you, $n, but before we begin I must ensure that you develop yourself to your full potential. I can help.$b$bI\'d like to create a link between us, an artifact that will enhance your power and allow me to track your progress. How do you feel about amulets? No? A ring? I\'ve got it.$b$bMy contacts among the arakkoa outcasts tell of a band of pure solium. Right now it\'s in the talons of High Sage Viryx high atop Skyreach. Bring me that ring, $n - you and I have much better uses for it.', `QuestDescription`) WHERE `ID` = 36157;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Draenor\'s Secret Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather 4986 Apexis Crystals for Archmage Khadgar. Crystals can be found amongst creatures in the most dangerous parts of the world.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Since we\'re going to be working so closely together, I\'d like to upgrade that ring of yours. Ancient magics are the key: apexis crystals, the leftover remains of an earlier arakkoa civilization! They can be found among the most dangerous creatures around the world.$b$bCollect 4986 crystals for me.$b$bDon\'t look at me like that. I\'m a mage. I did the math. I need exactly 4986 crystals. 4985 is inadequate. 4987 is of course absurd.$b$bFour thousand, nine hundred eighty-six. Go!', `QuestDescription`) WHERE `ID` = 36158;
