UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'News from Nagrand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Bodrick Grey at your garrison in Shadowmoon Valley.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Welcome back, $gsir:mam;.nnOne of Bodrick\'s men delivered a message about a caravan being dispatched for Nagrand. He\'s awaiting your approval on a new outpost.nnI\'ve been hearing whispers around camp about Nagrand. They say it\'s Warsong territory. They might need your help $gsir:mam;.', `QuestDescription`) WHERE `ID` = 36606;
