UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'My Very Own Fortress', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather 2000 Garrison Resources and then use the Architect Table to select your Town Hall and upgrade your garrison to Tier 3.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Boss! Guess what?! I finally got that new larger draft paper in that I ordered when we first came here. And ya know what larger draft paper means?nnIt means I can draw a bigger fortress!nnAnd if I can draw it, I can certainly make it! Making\'s the easy part, as long as you\'ve got a few thousand stones and logs lying around.nnSo whada\'ya say, boss? Shall we get building?', `QuestDescription`) WHERE `ID` = 36614;
