UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on Magnarok', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the stone monstrosities at Magnarok in Frostfire Ridge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north.nnIf we strike at them at their home, we should be able to force them back. It\'s risky, but it may be our best move. While you\'re there, see if you can recover any of our supplies.', `QuestDescription`) WHERE `ID` = 36697;
