UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'They Came From Above', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Crystal-Shaper Barum near Aruuna in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Please, traveler, I need your help.$B$BAruuna, my home, has been destroyed by the arakkoa. They swooped down from their spires and killed anyone who tried to escape. My family... did not make it out.$B$B My brother Barum stayed behind to find his daughter amidst the chaos. I beseech you, please, go to Aruuna and find Barum.$B$BHe is the only family I have left.', `QuestDescription`) WHERE `ID` = 36843;
