UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pinchwhistle Gearworks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Dungar Longdrink to secure a flight to the Pinchwhistle Gearworks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, a goblin courier arrived this morning.$b$bHe mentioned that he is from a settlement in the Spires of Arak called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster.$b$bIf we can earn their trust it\'ll be worth the effort. Head down there and see what sort of assistance we can provide.$b$bI\'ve already spoken to the flight master and he\'s set up a special flight to get you out there.', `QuestDescription`) WHERE `ID` = 36861;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pinchwhistle Gearworks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Bron Skyhorn the Wingman to secure a flight to the Pinchwhistle Gearworks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, a courier arrived this morning.$b$bHe said he\'s from a goblin settlement in Spires of Arak called the Pinchwhistle Gearworks. They\'ve asked for our assistance with some sort of ecological disaster.$b$bWe\'re spread thin but if we can earn their trust then we might be able to gain a valuable ally.$b$bHead down there and see what sort of assistance we can provide. I\'ve already spoken to the flight master and he\'s set up a special flight to get you out there.', `QuestDescription`) WHERE `ID` = 36862;
