UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'DEPRECATED', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 2 Stone Hunks O\' Gargoyle from Carrion Gargoyles in the Eastern Carrion Fields.  Return to Lord Bevis when the task is complete.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You there... you look the fighting type.  I want some sweet Revenge on the Scourge that killed my family.  Go get me 2 Stone Hunks O\' Gargoyle so that I can throw them on the ground and stomp on them violently until they are mashed into itty bitty pebbly bits. $b$bYes. Go. Kill.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to .', `QuestCompletionLog`) WHERE `ID` = 36873;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warlord of Draenor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Enemy Players in Player versus Player combat to earn 20 Broken Bones then place an offering at the Altar of Bones to Earn a Conqueror\'s Tribute.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Durotan...$B$B<Raza\'kul spits.>$B$BHe cowers behind the white flag of peace, relying upon diplomacy to win over our sworn enemies.$B$BEnemies that have taken our homes and driven us from our ancestral lands.$B$BThere is only one way to deal with the draenei and their newfound alliance of cowards - blood for blood.$B$BJoin me in crushing our enemies. Together we will flood this hallowed ground with the bones of the Alliance and earn tributes fit for a warchief!$B$BReturn here when your bloodthirst is sated.', `QuestDescription`) WHERE `ID` = 36874;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warlord of Draenor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Enemy Players in Player versus Player combat to earn 20 Broken Bones then place an offering at the Altar of Bones to Earn a Conqueror\'s Tribute.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Exarchs do nothing but squabble amongst themselves over petty issues while our people are slaughtered in their homes by orc filth. If they will not raise a fist of defiance against our enemies, I will.$B$BI wish to join your Alliance and rid this world of Horde. ALL HORDE - "Iron" or otherwise.$B$BThis Altar of Bones that I stand upon represents glory in battle against our Horde enemy. Place an offering upon it and earn a conqueror\'s tribute worthy of your unrelenting bloodthirst.$B$BKill. Them. All.', `QuestDescription`) WHERE `ID` = 36876;
