UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dark Portal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar at the foot of the Dark Portal in Blasted Lands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, is it? I\'m glad you\'re here. We can use every able-bodied $c that we can get.$b$bI am assembling a coalition of Azeroth\'s strongest to step through this Dark Portal and stop the Iron Horde invasion. This may be the only way to save Azeroth.$b$bWill you join us?', `QuestDescription`) WHERE `ID` = 36881;
