UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'From Within', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Kor\'vas Bloodthorn on Faronaar at Vanquish Point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A few of our demon hunters, Kor\'vas Bloodthorn and Cyana Nightglaive, took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within.nnI haven\'t heard from them in a while.nnIt would be best if you could find and lead them to success. Agreed?', `QuestDescription`) WHERE `ID` = 36920;
