UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arakkoa Exodus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Azik in Spires of Arak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I assume you\'re familiar with the arakkoa, commander? Great, flying birdfolk. Extremely territorial.nnSome, however, have withered wings - a disease, maybe. They seem to be outcast from arakkoa society. You find them now and then, squatting in forgotten ruins or peddling trinkets on the roadside.nnIt seems the Iron Horde has incited the arakkoa by moving into their lands, and the outcasts are fleeing in droves.nnWe should make contact with these outcasts - they could have valuable information.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Azik in Spires of Arak.', `QuestCompletionLog`) WHERE `ID` = 36951;
