UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ogre Ancestry', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect an Ogre Family Tree from the Bloodmaul Slag Mines.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lunk no like fight, want to learn. You help Lunk learn?$B$BFind Lunk ancestors. Lunk have many question. Where Lunk come from? Why Lunk Lunk?$B$BLunk stay here. Small ogres mean, big ogres meaner.', `QuestDescription`) WHERE `ID` = 37142;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Budd\'s Gambit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Very Shiny Thing from the Iron Docks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Listen, I don\'t know how I got here, but I have it on good authority that there is an entire island made of shiny things and it\'s just off of the coast a ways.$B$BAll we have to do is hop in the water and swim out there, then we can load up our pockets and swim back! I\'m just going to rest up and do some stretching before heading out.$B$BDon\'t try and stop me!', `QuestDescription`) WHERE `ID` = 37145;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Go Fetch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Nightmare Bell from Auchindoun.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now THIS is a savage land worthy of my level of heroism!$B$BOh, hello, I did not see you standing there, staring at me. Perhaps you have noticed that every piece of my armor is an ancient relic, forgotten by time.$B$BAs you have properly surmised, an adventurer of my stature does not have time to complete the menial requests I am given daily. I must remain here, yelling aloud to the trade district so that others may witness my heroicness and be inspired.$B$BToday I require a Nightmare Bell, do find one.', `QuestDescription`) WHERE `ID` = 37146;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sky Dancers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Bottled Windstorm from Skyreach.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, $n, and I thank you for your hospitality.$B$BThe Shado-pan have sent several warriors to aid against the Iron Horde, however we can. We are few, though, and they are many.$B$BThe arakkoa in the south are both beautiful and deadly. They appear lighter than air, their attacks a deadly dance that flits from opponent to opponent.$B$BThe winds are on their side, as the four winds lighten the steps of my own allies. Bring me a sample of their winds, if you are able. It will surely aid us.', `QuestDescription`) WHERE `ID` = 37147;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Oralius\' Adventure', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Spire Flamefly in Upper Blackrock Spire.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Me n\' Winky, off on adventures again! This is the life, I tell ye. No burning air to breathe, an\' plenty of ogres to kill!$B$B<Oralius rubs his belly.>$B$BWe did leave a bit of a mess back there in the Blackrock Spire, though. A whole mess of these iron-plated orcs and some proto-dragons marched right on up from the south and took it over.$B$BOl\' Winky, he couldn\'t take the guilt. Went on back by himself he did, to stop them!$B$BOr... to JOIN them! Winky, ye two-timing son of an orc. Ye\'ve got to stop him!', `QuestDescription`) WHERE `ID` = 37148;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Void-Gate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find a Void-Gate Key in the Shadowmoon Burial Grounds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My \'master\' is an idiot, but you look like you\'ve got some smarts in that oddly-shaped head.$B$BListen up, the Twisting Nether is a chaotic abyss, and things work differently there. I\'ve felt some disturbances, and they don\'t bode well for any of us.$B$BYes, there are things happening here, in Draenor, that are causing ripples in the nether. No, don\'t try to wrap your head around how that works, you\'ll only hurt yourself.$B$BIt\'s simple: bring me a Void-Gate Key, and maybe I can stop the bad things.', `QuestDescription`) WHERE `ID` = 37149;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'For the Birds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find a Tiny Peachick Hatchling in The Everbloom.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hi! Have you ever held a peachick hatchling?$b$b<Without warning, Mylune grabs both of your hands and then stuffs a tiny chirping bird in them.>$b$bIsn\'t it so small and light and downy? Like you\'re holding a beaky peepy lil\' CLOUD! It\'s so adorable you can\'t help but hug it and cuddle it and stuff regurgitated food in its teeny-tiny mouth.$b$b$n, the plantfolk in the Everbloom are turning peachicks into monsters before they can grow into beautiful swans. Or whatever they grow into. Please help them!', `QuestDescription`) WHERE `ID` = 37150;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cold Steel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find an Iron Autocannon in Grimrail Depot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you know what I want? What everyone who came through that portal wants. Every soldier running from a world that didn\'t understand us, didn\'t need us. I want that world to love us as much as we love it.$B$BBut we don\'t really belong there, not anymore. War is part of us, and we can\'t go back. To everyone back there, we\'re expendable.$B$BThe only thing that makes me feel better now is the feel of a cold iron cannon in my hands, pointed at the enemy.$B$B<Keeshan stares into his mug of ale.>', `QuestDescription`) WHERE `ID` = 37151;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cro\'s Revenge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Giant Ogre Head from the Bloodmaul Slag Mines.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'HA! The fruit vendor was so cunning, but I, Cro Threadstrong, am even MORE cunning. I have come back into the past to defeat the ogre army before that fruit vendor can turn them against me!$B$BBring me the head of a big, strong ogre from the old slag mines, and I will have crushed the fruit vendor before a single apple has even grown!$B$BCAN YOU HEAR ME, FRUIT VENDOR? I WILL HAVE MY VICTORY!', `QuestDescription`) WHERE `ID` = 37152;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Time-Lost Vikings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Olaf\'s Shield from the Bloodmaul Slag Mines.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oi, barely made it out of that place!$B$BWe came through the portal to help, and the next thing you know, we\'re prisoners in the Bloodmaul Slag Mine. It was brutal! We were shackled for days, and covered in filth.$B$BAnd they took my SHIELD!', `QuestDescription`) WHERE `ID` = 37153;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Cure For Death', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Soulweave Vessel from Auchindoun.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, and my thanks for the warmth of this inn and your hospitality.$B$BAs you can see, this malady of death continues to plague me. My studies on Azeroth and in Northrend met with little luck, and all of my leads ran dry.$B$BI have come to Draenor in the hope of finding something, anything, to go on. My first pilgrimage will be to Auchindoun, a house where souls are put at ease.$B$BIf you should head there yourself, do let me know if you should happen upon anything of interest.', `QuestDescription`) WHERE `ID` = 37154;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Brass Compass', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Brass Compass at the Iron Docks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, commander. I have come on a mission directly from the captain.$B$BAboard any vessel on Azeroth that\'s manned by at least one orc, you\'ll hear sea shanties sung about a device capable of navigating the broad, rough ocean of Draenor. The orcs used it to keep their heading true in the choppiest of storms.$B$BPerhaps it\'s just an old sea tale, but this one chance to find that kind of prize has the captain willing to part with some fine treasure.', `QuestDescription`) WHERE `ID` = 37155;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Soulcutter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Soulsever Blade from Auchindoun.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Don\'t look at me! Who do you think you are?$B$BYou and I are on the same side, you know. The necromancers here, we have to kill them. All of them.$B$BDon\'t you agree?$B$BOf course you do, and you can help me accomplish this goal. Find a Soulsever Blade in that hovel where the necromancers have holed up like rats. It has... special properties... that will aid us against the undead.', `QuestDescription`) WHERE `ID` = 37156;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Feeling A Bit Morose', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a barrel of Horribly Acidic Solution from the Iron Docks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So many years of waking up as a spirit, reanimated by some unseen force time and again, has left one with certain desires - the comforting, velvet blackness of death being chief amongst them.$B$BOne will, however, settle for the lesser prize of a solution capable of removing the scuff marks that the commander\'s wonderful compatriots left behind in the dining hall in their woefully short stay in Karazhan, whereupon they barely had enough time to irreparably damage the priceless furniture.', `QuestDescription`) WHERE `ID` = 37157;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gloriously Incandescent', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Sun Crystal in Skyreach.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I did not come here to fight, I have seen too many die already. I have killed so many with my own hands.$B$BI have come to seek the light, and redemption.$B$BThe arakkoa of this land worship the sun as I do. But they are a violent, isolationist, and decadent race, who seem to derive a different message than my own people. This troubles me.$B$BBring me one of their Sun Crystals. I wish to see this light.', `QuestDescription`) WHERE `ID` = 37158;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aviana\'s Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect some Pristine Plumage in Skyreach.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The arakkoa are creatures of the sky, and are thus within the domain of the great Aviana.$B$BI have been sent to procure a feather, that we may parley with them through the language of the winds. We will extend an invitation of peace, and a place on the Great Bough.$B$BWould you aid us in this quest? The feather must come from an arakkoan of nobility. You will find them in the place known as Skyreach.', `QuestDescription`) WHERE `ID` = 37159;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cleaving Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find an Iron Limbcleaver in Grimrail Depot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I, Gamon, have come through the dark portal to cleave many orc skulls. Yet my weapon has not kept pace with my rage, and is nicked and dull.$B$BFind me a new weapon - one that is good for removing Hellscream limbs.', `QuestDescription`) WHERE `ID` = 37160;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Family Traditions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Finkle\'s Improved Skinner in Blackrock Spire.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'He ran off with it! Oh what am I going to do, what am I going to DO?$B$BMy son, and my knife, they ran off to Blackrock Spire! Well, the knife didn\'t run, I suppose. That doesn\'t matter!$B$BYou\'ve got to get it back! Yes, the knife! You\'ve got to get me back my knife!$B$BGo! Now! Stop talking!', `QuestDescription`) WHERE `ID` = 37161;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Damsels and Dragons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Shed Proto-Dragon Claw.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What ho, squire $n! Forgive my lips, as they bear gravest news. Dragons have taken up stinking residence within the hallowed halls of Blackrock Spire!$B$BThese great wyrms hold a distressed damsel in their scaly graspers. Her name is Zaela, they say. Such a beautiful name!$B$BAs my squire, it is your Light-given duty to adventure yourself into this spire and procure evidence of these dragons, lest I waste my heroism on a dragonless quest.', `QuestDescription`) WHERE `ID` = 37162;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shadowy Secrets', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Dark Parchment from the Shadowmoon Burial Grounds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Though the Lich King has been defeated, we are no closer to unlocking the secrets of the Frozen Throne than we were when jousting pointlessly at the Argent Tournament. Bolvar remains resigned to his fate.$B$BPerhaps there is something here, though, that can aid us. Ner\'zhul was not always the Lich King, you know. Once, he was a mere orc dabbling in dark powers beyond his comprehension.$B$BFind whatever you can of his early studies, and we may have our answers.', `QuestDescription`) WHERE `ID` = 37163;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Huntresses', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Silver-Lined Arrow from the Shadowmoon Burial Ground.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I do not wish to come out of the shadows, but I mean you no harm. My purpose here is my own secret to keep, I simply needed a warm place to bed down for the night.$B$BI can see that you are not the type to be easily swayed into leaving. Very well, perhaps you can aid me in my search.$B$BI am looking for someone, it is not important who. All you need to know is that I will reward you for any sign of high elven weaponry that you should come across.', `QuestDescription`) WHERE `ID` = 37164;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cenarion Concerns', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Strangely-Glowing Frond from Everbloom.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ey mon!$B$BDe Cenarion Circle sent Zen\'kiki out here ta check out dem primals. I woulda been here sooner, but I had a little bit o\' trouble gettin\' my flight form ta work, mon.$B$BDe plants in dis place... I can hear dem talk. Dey be yellin\' all the time. Angry an\' violent yellin\'.$B$BWould ya bring Zen\'kiki back a leaf from dis Everbloom place dey be talkin\' about? Maybe I can figure out what dey want.', `QuestDescription`) WHERE `ID` = 37165;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Titanic Evolution', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect an Overgrown Artifact from The Everbloom.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ah, hello! Do not look so surprised! Did I not also brave the dangers of the Mogu\'shan Vaults? I am more sturdy than I look!$B$BI have learned many things of this wonderful place in history already. Did you know that, just like on our world, the titans once came to this place?$B$BAt least, that is what I believe! Surely there are signs of the titans\' presence here, even now. Should you find one, I would very much like to see it!', `QuestDescription`) WHERE `ID` = 37166;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'And No Maces!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Huge Crate of Weapons in Grimrail Depot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There are far too many bright-eyed young rogues being sent through this portal and off to war. If I\'m going to start up my academy again, some of them have got to survive this little excursion.$B$BWhile I\'m here, I figured I might as well use the opportunity to gather some supplies for my grand opening. You can\'t start a business without plenty of daggers, after all.$B$BGrab me a crate of weaponry from the Grimrail Depot, there should be plenty lying around. I\'ll have something nice for you.', `QuestDescription`) WHERE `ID` = 37167;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Craig\'s Test Quest Again!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Get Omar some cloth', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'An honorable person gives me cloth', `QuestDescription`) WHERE `ID` = 37175;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'For The Children!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Miniature Iron Star from Upper Blackrock Spire.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Wait, wait! Don\'t attack me! I\'ve changed!$B$BReally, I\'ve turned over a new leaf, I promise. I haven\'t said "DOOOOOOM!" in months! All I care about now is saving the poor little orphans of Azeroth, whose parents have been taken by this tragic war.$B$BThat\'s why I\'m here! Why, with just a single Miniature Iron Star, I could provide clean water and power for all of the orphans of Azeroth! And no one could stop me!$B$BSo, what do you think, sweetcheeks? Want to help ol\' Milhouse save the orphans?', `QuestDescription`) WHERE `ID` = 37179;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Critical Path', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Dungar Longdrink to secure a flight to Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde\'s fleet is already en route from Gorgrond to Shattrath on the west coast.$B$BTalador will fall if we don\'t reinforce them. I took the liberty of dispatching Foreman Eksos, who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.', `QuestDescription`) WHERE `ID` = 37183;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Taking the Fight to Nagrand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lieutenant Balfor at the caravan in Nagrand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, good to see you. With the fall of the rangari base at Telaar, Vindicator Yrel, recommended that we establish a new foothold in Nagrand.$b$bI\'ve taken the liberty of dispatching some of our men and supplies. Rangari D\'kaan\'s already reporting that the outpost is nearly complete. He asked me to let you know they are ready for you.$b$bA gryphon is waiting to catch you up with the latest caravan shipment whenever you\'re ready, $g sir:ma\'am;.', `QuestDescription`) WHERE `ID` = 37184;
