UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sanketsu, The Burning Blade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Sanketsu, the Burning Blade, to Lieutenant Thorn at your garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it.$B$BPerhaps someone at your garrison would be interested in seeing this weapon.', `QuestDescription`) WHERE `ID` = 37191;
