UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cymre Brightblade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Cymre Brightblade in a pet battle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I found some interesting artifacts on a recent dig, and I\'d love to put them through their paces to see how they would have performed in their native cultures.  Don\'t suppose you have anything small and furry that can put up a fight?', `QuestDescription`) WHERE `ID` = 37201;
