UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'They Came From the Sea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Head of Fathom-Commander Zarrin, and slay $2oa of his naga troops.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'re looking for Prince Farondis?$b$b<The ghostly elf narrows her eyes warily.>$b$bI can take you to Farondis... but first things first. These naga attacked suddenly. They take orders from one called Zarrin, in the low hills to the west.$b$bHelp me take Zarrin\'s head, and you\'ll have my ear.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Slay him and the naga he commands!', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Fathom-Commander Zarrin', `PortraitGiverName`) WHERE `ID` = 37256;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Our Very Bones', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Pilfered Night Elf Bones.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You seek the Tidestone of Golganneth?$b$bYes, I know where it lies. It is in a place to which I prefer not to return.$b$bYou may be of use to me. In the midst of this naga attack, those horrid fish-men flopped their way onto my lands and raided our graveyards. They steal the bones of our ancestors, and indeed, the very bones of my people.$b$bHelp me bring some solace to my people. Then I shall tell you more about the Tidestone.', `QuestDescription`) WHERE `ID` = 37257;
