UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dead Do Not Forget...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place 10 Ancient Snarlpaw Skulls in the Boneseer\'s Cauldron.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Many years ago my family and I were slain in this very spot.$b$bThe saberon you see around you are descended from the tribe that murdered my village. Long have I waited, here in this forgotten place, to see justice brought to the saberon for their crimes.$b$bThe Snarlpaw chief is a boneseer, a saberon who divines the future using the remains of the dead.$b$bCollect the ancient skulls of the Snarlpaw ancestors and place them in the boneseer\'s cauldron.$b$bLet their own bones fill their cauldron for once!', `QuestDescription`) WHERE `ID` = 37318;
