UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Feast of the Spires', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Eat a Feast of the Spires at Southport.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, I prepared a great feast for ye right over there. You should be have a bite o\' two before you be go out fer the day.$B$BTrust me, it\'s good fer ya!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Kolrigg Stoktron at Southport.', `QuestCompletionLog`) WHERE `ID` = 37417;
