UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Proving Grounds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lieutenant Thorn to enter the Proving Grounds, and then complete a Bronze trial.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings commander.$b$bWord of your exploits has made its way back to Trial Master Rotun, and he has humbly requested to see your prowess in person. Fighting in his proving grounds would be an excellent way to spread your reputation to the farthest reaches of the Alliance, and beyond.$B$BIf you\'re interested in proving yourself, talk to me to enter Trial Master Rotun\'s Proving Grounds.', `QuestDescription`) WHERE `ID` = 37433;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Proving Grounds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Warmaster Zog in your garrison to enter the Proving Grounds, and then complete a Bronze trial.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hail commander.$b$bWord of your exploits has made its way back to Trial Master Rotun, and he has requested to see your prowess in person. Fighting in his proving grounds would be an excellent way to spread your reputation to the farthest reaches of the Horde, and beyond.$B$BIf you\'re interested in proving yourself, talk to me to enter Trial Master Rotun\'s Proving Grounds.', `QuestDescription`) WHERE `ID` = 37434;
