UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Blood of Demons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Fel Blood from any demon on the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time has come to make contact with the Master\'s soul. It is somewhere in the endless expanse of the Twisting Nether. Luckily, so is Mardum.nnSuch a thing is not unheard of, but it will be exceedingly difficult, even here. In addition to what the matron mother had us gather, we need a great deal of demon blood.nnLike, a lot of it!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Head downstairs on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 37447;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Simple Plan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Hear Mathias Shaw\'s plan and then cast your vote.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Like many dreadlords, Detheroc cannot help but gloat. He was careless and I overheard many of his plans while I was held captive.nnWith your leave, I would like to underscore the gravity of the situation in Stormwind. The fate of Azeroth hangs in the balance.nnBut for all of that, I have a simple plan: get \'em.', `QuestDescription`) WHERE `ID` = 37448;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Revelations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Nightglaive the Traitor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m not going to let Cordana Felsong get away with this. There is no way in hell I am going to let that warden witch turn my people.nnAs for Nightglaive... I will NOT suffer a traitor to live!nnAre you with me, $n?', `QuestDescription`) WHERE `ID` = 37449;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Saving Stellagosa', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain Lykill\'s Key and free Stellagosa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'During the fighting, of all things, I saw a blue drake swoop in and attack the demons. I couldn\'t believe my eyes. I\'d heard that the Blue Dragonflight had gone extinct.nnThe Legion managed to bring the drake down, but not until after she\'d killed a score of them. She was magnificent. Last I saw, they were dragging her in the direction of the southern camp.nnWe should see if she\'s still alive. A dragon could prove a powerful ally.', `QuestDescription`) WHERE `ID` = 37450;
