UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Walk of Shame', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort Prince Farondis around the edge of Nar\'thalas.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The echoes of Nar\'thalas still haunt me, and I cannot bear the pain of this accursed town any longer. I may still be able to get you closer to the Tidestone, however.$b$b<Farondis\' eyes narrow in newfound determination.>$b$bWe will need to skirt around the edge of town. Follow me.', `QuestDescription`) WHERE `ID` = 37467;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into the Academy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the halls of the Nar\'thalas Academy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The sunken structure on the other side of this bridge was once called Nar\'thalas Academy: the center of magical studies in all of Azeroth. You should have seen her in her full splendor.$b$bThe Tidestone should be locked up within. I dare not enter, but you - my champion - you go with my blessing.', `QuestDescription`) WHERE `ID` = 37468;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Tidestone: Shattered', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the $1oa Tidestone Shards.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I suppose you can go in, then.$b$bThe shattered pieces of the Tidestone of Golganneth are contained within the academy\'s eastern wing. Even as curator, I cannot attest to their condition, as I have not been in to inspect them in many millennia.$b$bOh, young $n? Please do not touch anything.', `QuestDescription`) WHERE `ID` = 37469;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Head of the Snake', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Athissa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Those naga have the Tidestone shards, $n. They will soon be dragging them into their watery holes, away from our reach.$b$bIt would be wise to take out their leaders before that happens.', `QuestDescription`) WHERE `ID` = 37470;
