UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nar\'thalas Still Suffers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Athissa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'They have not forgiven me. I cannot blame them.$b$bPast crimes aside, I am still their prince. Even in death, I will do what I can to protect my people.$b$b$n. Act as my champion. Find and defeat the creature that leads this naga attack against the people of Nar\'thalas. After all these years, you - |5$r $c, of all things - may be the instrument of my redemption.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Tidemistress of the Hatecoil', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Athissa', `PortraitGiverName`) WHERE `ID` = 37486;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Rather Long Walk', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Elder Aldryth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m concerned for Elder Aldryth. He went out for a walk about ten thousand years ago, and he has not returned.$b$bWith these naga attacking, I fear he may be in danger!$b$bIf you dare venture out into the fray, do look out for our court elder.', `QuestDescription`) WHERE `ID` = 37492;
