UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Under Cover of Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Taoshi when you\'re ready for Fleet Admiral Tethys to arrange your transport to Stormwind City.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are off to Stormwind. Tethys will sneak us by water beneath the old barracks under cover of darkness tonight.nnThe rest will be up to you, Mathias, and myself. We will have to stealth through Stormwind and confront Detheroc at SI:7.nnAre you ready to do this, $n?', `QuestDescription`) WHERE `ID` = 37494;
