UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Infiltrating Shipwreck Arena', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infiltrate Shipwreck Arena and find Okuna Longtusk.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The giants at Shipwreck Arena are very fond of smashing ships that sail too close to shore. They take the sailors prisoner and use them for their own amusement.nnI suppose it will be easy for you to infiltrate the place. It\'s breaking out that will be the difficult part.', `QuestDescription`) WHERE `ID` = 37496;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trailing the Tidestone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort Prince Farondis to the Ruins of Nar\'thalas.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your quest for the Tidestone... it intrigues me. More than that, it suits my needs quite well. I have been in need of a champion for a very, very long time.$b$bIt is decided, then. I shall join you.$b$bWe will have to head east, through Nar\'thalas.$b$bShall we depart?', `QuestDescription`) WHERE `ID` = 37497;
