UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Boss Whalebelly\'s in Charge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Boss Whalebelly.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Great, let\'s get started! If we\'re going to break everyone out of here, you need to pose as a pit fighter like the rest of us. They won\'t just let you run around anywhere you want in here.nnFirst thing you need to do is present yourself to Boss Whalebelly. The giants may run this place, but as far as posing as one of us, Whalebelly\'s in charge.nnHe\'s speaking with his goons just to the south.', `QuestDescription`) WHERE `ID` = 37507;
