UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sternfathom\'s Champion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Sternfathom as his new pitfighter.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Since you defeated Ooker Dooker, there\'s a pit fighter spot open on Sternfathom\'s team. You should go establish yourself as his champion. That way, the giants won\'t think twice about why a stranger is suddenly coming and going as $g he:she; pleases.nnMeanwhile, I\'ll start to sow some chaos so that we can strike at Prince Oceanus.', `QuestDescription`) WHERE `ID` = 37510;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Primals Invasion! BETA', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Repel the Primals invasion of your garrison.$B$B(Speak with Sergeant Crowler again to begin)', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The plants seem different today. Grass blades bend against the wind and catch on my boots. Twice this morning a tree branch struck my helmet as it fell.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Sergeant Crowler in your garrison.', `QuestCompletionLog`) WHERE `ID` = 37512;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Iron Horde Approaches... BETA', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Sergeant Crowler.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There\'s smoke on the horizon... The Iron Horde is coming.', `QuestDescription`) WHERE `ID` = 37515;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Haunted Halls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the academy\'s west wing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now, what was it you wanted? You\'re here to see the Tidestone of Golganneth? Hah! Ho ho ha ha haa!$b$bHooo my.$b$bNo, only the academy\'s headmistress has the keys to that chamber, and she hasn\'t opened the door in... oh, I\'d say about ten thousand years.$b$bYou\'d best be off to class, now. Go on, then! Into the west wing with you!', `QuestDescription`) WHERE `ID` = 37518;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vileclaw\'s Claw', `LogTitle`) WHERE `ID` = 37520;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on the Gorian Proving Grounds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the ogre forces at the Gorian Proving Grounds in Nagrand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The ogres at the Gorian Proving Grounds are rousing champions to turn against our forces in Nagrand.nnA decisive assault on their training grounds should prevent them from mustering the forces they need to stand against us, and will help remind them that we are not an enemy they want to make.', `QuestDescription`) WHERE `ID` = 37523;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on the Gorian Proving Grounds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the ogre forces at the Gorian Proving Grounds in Nagrand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The ogres at the Gorian Proving Grounds be rousin\' champions to turn against our forces in Nagrand.nnA decisive assault on their training grounds should prevent dem from musterin\' the forces dey be needin\' to stand against us, and will help remind them that we are not an enemy they want to be makin\'.', `QuestDescription`) WHERE `ID` = 37524;
