UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Let Sleeping Giants Lie', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Giants\' Stash of Weapons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'re going to need a diversion to get close to Prince Oceanus. Are you thinking what I\'m thinking?nnSee Sleepy Dhow over there? He\'s guarding all of the weapons the giants take from our shipwrecks. We can use those weapons to arm the rest of the pit fighters that are held in the caves.nnAll you have to do is get past that giant without waking him.', `QuestDescription`) WHERE `ID` = 37528;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Save Yourself', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Farondis and hear his account of how he saved you.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Of course I couldn\'t sit back and let them just cart you away.$b$bI will explain everything.', `QuestDescription`) WHERE `ID` = 37530;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking - See Closed Chest', `LogTitle`) WHERE `ID` = 37531;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[UNUSED]Rolling With the Tidestone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Tidestone Shards to Senegos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Before I forget, $n: the Tidestone shards. They are yours to protect now.$b$bBring them back to your dragon. The people of Azsuna stand behind you.', `QuestDescription`) WHERE `ID` = 37532;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Morale Booster', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Get the Fighter Chow from Ooka Dooker', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Things may look good from where you\'re standing, but, we\'re losing. However, do not fret, my little $r friend. You can help.nnListen closely. Ooka Dooker, Ooker\'s sister, is back over yonder in the champions\' cave making her world famous Fighter Chow. It\'ll do the trick and boost our team\'s morale.nnAll you have to do is to convince her to hand it over.', `QuestDescription`) WHERE `ID` = 37536;
