UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'No Time for Tryouts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver a beatdown to Ooker Dooker.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We don\'t have time for you to go through a lengthy set of tryouts. But, fighting in the arena is our best chance at getting you in good with the giants.nnThat kind-hearted giant over there that\'s losing against Bilgerudder is Sternfathom. If you were to defeat his hozen champion, you\'d make yourself a spot on his team.nnLooks like Ooker Dooker\'s taking a rest between bouts. Now\'s the time to deliver a good ol\' monkey beatdown.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Send this guy packing so that you can take his place on Sternfathom\'s team.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Ooker Dooker', `PortraitGiverName`) WHERE `ID` = 37542;
