UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demon Souls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Trap $1oa demon souls on the Faronaar Front.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I need to extract information about the Burning Legion from these foul creatures. But living, the demons are almost impossible to break.nnHowever, like you, I wield a powerful artifact -- the Scythe of Souls.nnTake one of my soul gems. If you place it next to a demon\'s corpse, it will rip the \'soul\' out. Then, we will see if the scythe can get them to talk.', `QuestDescription`) WHERE `ID` = 37653;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maritime Law', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Looper Allen near the ship that\'s run aground on the east side of Mak\'rana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Good $g sir:madame;, a moment of your time. My fellow salvors and I could not help but notice yon ship that ran aground in the storm last night.nnA pity about its crew.nn<Mr. Shackles makes empathetic gestures.>nnStill, the law\'s the law. The maritime code is quite clear on the matter. If you find yourself out that way, would you mind terribly checking in on my acquisitions scout, Looper? I would have expected him back for tea some time ago.', `QuestDescription`) WHERE `ID` = 37654;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel Machinations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free $1oa Demon Hunters from Soul Harvesters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My force wiped out the demons\' forward base here. But, an imp mother and her brood took the rest of my demon hunters hostage, including Cyana Nightglaive.nnWe need to free the Illidari and destroy the Burning Legion.', `QuestDescription`) WHERE `ID` = 37656;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Making the World Safe for Profit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa gilblin and/or makrura at Mak\'rana and slay their leader, Queen Kraklaa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Might I ask a small favor, my friend? These creatures in the tide pools to the east are starting to frighten me. Our efforts to trade with them have been rebuffed at every turn with aggression. This is not good; neither for running a business, nor for profit.nnSadly, I must admit the time for talk has come to an end.nnMight you be willing to serve as my representative in dealing with the denizens of Mak\'rura and their "queen"?nnI can assure you that your efforts will be rewarded commensurately.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Slay the queen and deal with anything or anyone that gets in your way.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Queen Kraklaa', `PortraitGiverName`) WHERE `ID` = 37657;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Reignite the Wards', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Reignite the 3 demon wards.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demons are weakening my defenses. They must be far more powerful than what we\'ve faced before.nnWill you help me to reignite the wards to keep the Legion from overrunning our position here?', `QuestDescription`) WHERE `ID` = 37658;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Captain\'s Foot Locker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate the Captain\'s Chest below decks on the Queen\'s Reprisal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I don\'t care what you do, mate. But, if you get caught, you didn\'t see me.nnI wasn\'t here.', `QuestDescription`) WHERE `ID` = 37659;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Scythe of Souls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Work with Allari the Souleater to compel information from the demon souls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Let\'s head to the other side of the stand. We will release the demon souls one by one and get the answers that we seek concerning Lord Illidan.nnThe Scythe of Souls will ensure that we do.', `QuestDescription`) WHERE `ID` = 37660;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Picking a Fight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill demons until Vaultwarden Umbral appears and kill him. Then, set Mathias Shaw free.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'They\'re coming, $n!nnI will get to work unlocking these fel-magic chains from the cage.nnYou keep the Legion at bay.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Master Mathias Shaw in the Chamber of Shadows.', `QuestCompletionLog`) WHERE `ID` = 37666;
