UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hit the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy 3 Ancient Tomes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The librarian speaks in shushed tones.>$b$bOne problem with maintaining such a large arcane library is that the books often pick up an errant enchantment and start darting about on their own. These overmagicked books need to be destroyed before they cause any further damage.$b$bIf you encounter any of these exasperating essays, please put them down. Quietly.', `QuestDescription`) WHERE `ID` = 37678;
