UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Garrison Campaign: In the Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Council Nightblades within Lion\'s Watch.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I need your help. Iskar has gone missing. I have reason to believe he has followed the remnants of the Sethekk who have been gathering here in Tanaan. I\'ve been investigating and... what was that?$b$b<Reshad\'s voice drops to a whisper>$b$bThere is movement in the shadows, we are being watched!$b$bTake these vials, they form a gas with a terrible smell when the liquid comes in contact with the air. Smells terrible, they won\'t be able to resist it. Use them to drive our watchers out of hiding.', `QuestDescription`) WHERE `ID` = 37687;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Garrison Campaign: In the Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Council Nightblades within Vol\'mar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I need your help. Iskar has gone missing. I have reason to believe he has followed the remnants of the Sethekk who have been gathering here in Tanaan. I\'ve been investigating and... what was that?$b$b<Reshad\'s voice drops to a whisper>$b$bThere is movement in the shadows, we are being watched!$b$bTake these vials, they form a gas with a terrible smell when the liquid comes in contact with the air. Smells terrible, they won\'t be able to resist it. Use them to drive our watchers out of hiding.', `QuestDescription`) WHERE `ID` = 37688;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Imposter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Grapple up the Lion\'s Rest cliffs, sneak through Stormwind City to the SI:7 courtyard, and then kill Detheroc.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Detheroc has SI:7\'s finest snipers on all of the rooftops. We can\'t mount up and we can\'t fly. There are grapple points above so that we can move up the cliff. nnWe\'ve also setup hay bales to hide in along the likely routes to SI:7. We just need to stealth in and kill Detheroc.nnOnce we get up there, we\'ll separate to increase the chances of at least one of us making it through the city.nnGood luck, $n.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Taoshi in the Chamber of Shadows.', `QuestCompletionLog`) WHERE `ID` = 37689;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Those Who Remember', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Nightwatcher Idri in the Drowned Gardens.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The ghostly elves, to the south, once had the Pillar of Creation known as the Tidestone of Golganneth.$b$bTheir great city of Nar\'thalas was destroyed an eon ago. The city\'s ruler, Prince Farondis, fell with the city. You small ones die so easily.$b$bIf anyone knows where the fragments rest, it will be the ghost of the prince. Seek out his people.', `QuestDescription`) WHERE `ID` = 37690;
