UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Magister of Mixology', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Arcane-Infused Eggs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you must know, I\'m a connoisseur of drinks... specifically, arcane-infused spirits. Cocktail mixing is alchemy, and as everyone knows, alchemy is magic.nnMy latest drink must be more exotic than anything I\'ve conjured before. I already have most of what I need. But there are a couple of items left on the list.nnNotice the herons down in the lagoon? As with many of the creatures on Azsuna, the magic coursing through the island permeates them.nnTheir eggs will do nicely.', `QuestDescription`) WHERE `ID` = 37727;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Presentation is Everything', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Six Eyes of Gangamesh.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The eggs will provide the \'oomph\' to my drink\'s character. But there\'s another element, and this must not be underestimated!nnPresentation.nnNow, you could go with your standard olive skewered on a toothpick. Maybe a carrot stalk stuck slapdash out of a glass.nnBut then, you wouldn\'t be me.nnNo, my friend. What MY drink needs to sell it visually comes from a one-of-a-kind creature. I\'m only going to serve it once and so my drink deserves something unique.nnThe eyes of Gangamesh are what I need.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Magister Garuhod wants all six of this beast\'s eyes to top off his latest, greatest cocktail.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Gangamesh', `PortraitGiverName`) WHERE `ID` = 37728;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pop Quiz: Advanced Rune Drawing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Trace an arcane rune, a fire rune, and a frost rune.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Still aching to get into the headmistress\' study, eh? I suppose I can let you in... as long as you prove that you\'ve been studying.$b$bProper rune formation is essential when it comes to spellcasting. If you can draw a rune, you can cast a spell.$b$bI will provide outlines for you. You can simply use your feet to trace the runes.', `QuestDescription`) WHERE `ID` = 37729;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Headmistress\' Keys', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Tidestone Vault Key from Elya Azuremoon, the Academy Headmistress.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have a suspicion you are avoiding your studies - but I can see you\'re anxious to see the Headmistress.$b$bVery well! Headmistress Azuremoon can be found up ahead, though I doubt she will enjoy being interrupted.', `QuestDescription`) WHERE `ID` = 37730;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prince Farondis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet up with Nightwatcher Idri at the Crumbled Palace.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m glad to see that my doubts in you were unfounded.$b$bYou seek Prince Farondis? Follow me. I will show you to the prince\'s hall.', `QuestDescription`) WHERE `ID` = 37733;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dressing With Class', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Nar\'thalas Academy Hat, Robes, Wand, and Spellbook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now stop right there. Look at you! You look like you just walked in off of the street. Where are your robes and hat?$b$bAnd don\'t tell me you\'ve entered the academy without your wand and spellbook.$b$bFreshmen.$b$bPut yourself together, and maybe then I will consider letting you enter the academy.', `QuestDescription`) WHERE `ID` = 37736;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trials of Khadgar: Iron Maidens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Iron Maidens encounter, with the following conditions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Defeat your enemies with greater skill to earn the favor of Khadgar - and with it, greater rewards!', `QuestDescription`) WHERE `ID` = 37749;
