UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Walled City: Brackenspore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Brackenspore in Highmaul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If it ain\'t one threat, it\'s another - I swear this light-forsaken world would try to eat us alive even without no Horde to fight.$b$bBrackenspore, ancient walker of the deep, was drawn from the waters near Highmaul by the presence of the Iron Horde. That thing is already spreading like a disease, $n. Ye got to put it down!$b$bTravel to Highmaul and defeat Brackenspore before he gets too powerful to stop.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Brackenspore', `PortraitGiverName`) WHERE `ID` = 37766;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Slagworks: Heart of the Mountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Heart of the Mountain at the Blast Furnace in Blackrock Foundry.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Blackrock warriors use weapons forged in cursed fire by the breath of a creature o\' pure flame: The Heart o\' the Mountain. Let\'s disarm \'em, $gboy:lass;! Destroy that infernal creature, and the Blackrock won\'t have enough heat to fuel their Blast Furnace.$b$bTravel to Blackrock Foundry and defeat the Heart o\' the Mountain.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Heart of the Mountain', `PortraitGiverName`) WHERE `ID` = 37769;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Black Forge: Kromog', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Kromog in Blackrock Foundry.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Yer garrison scouts report that blackrock miners dug up a magnaron, and that the filthy beast has begun helpin\' those brutes churn out their infernal machines. They call it "Kromog."nnTravel to Blackrock Foundry and slay that fiend!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Kromog', `PortraitGiverName`) WHERE `ID` = 37770;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Iron Assembly: Admiral Gar\'an', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Admiral Gar\'an in Blackrock Foundry.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '"If ye want to topple a wall, start with the foundation." It\'s an old Dwarf saying. If we take out the Iron Horde\'s leadership, the whole thing tumbles.$b$bGar\'an is the Admiral o\' the Iron Horde fleet and first of the so-called "Iron Maidens." She, along with her lieutenants, Marak, and Sorka, have dominated the seas of Draenor.$b$bNo more, $n. Travel to Blackrock Foundry and defeat Admiral Gar\'an.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Admiral Gar\'an', `PortraitGiverName`) WHERE `ID` = 37771;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Death to Amethon!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve a Humming Draenite Spike from Amethon above Kuuro\'s Claim in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Foreman Eksos down in your Talador outpost figures he has the answer for why there\'s been so much seismic activity recently.$B$BSee, there\'s this giant, ah... earth fury, I think they\'re called, and it\'s covered in these powerful crystals in a cave up above Kuuro\'s Claim. The crystals hum real loud and we think it\'s driving the fury crazy!$B$BProblem is, nobody\'s got the firepower to take the thing down so we can examine a sample. Think you could lend us a hand, commander?', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Amethon', `PortraitGiverName`) WHERE `ID` = 37773;
