UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure Contract: Gutrek\'s Cleaver', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the ogres in the Broken Precipice for clues regarding Goldspade\'s discovery.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In Nagrand, the ogres tell of an ancient weapon called Gutrek\'s cleaver. I would very much like to study it.nnA goblin treasure hunter by the name of Val Goldspade discovered the whereabouts of the weapon. Unfortunately, this goblin has gone missing somewhere in the Broken Precipice - probably after a run-in with the locals.', `QuestDescription`) WHERE `ID` = 37788;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Auchindoun', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Teron\'gor in Auchindoun.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, Gul\'dan\'s favored agent Teron\'gor has infiltrated Auchindoun in Talador and has already taken to devourin\' the countless souls within. We mustn\'t let this nefarious warlock gain any further strength.$B$BEnter the holy mausoleum o\' Auchindoun and rout Teron\'gor and the rest o\' the Shadow Council before more damage is done.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Teron\'gor', `PortraitGiverName`) WHERE `ID` = 37796;
