UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'UNUSED: Test Race: 1 Marker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Run through the arch, hit the blue marker, then return to the Ironelf games camp.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Run through the arch...$BGet to the blue marker... then return$B$BGood luck!', `QuestDescription`) WHERE `ID` = 37812;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Welcome to the Darkmoon Races', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Run through the Darkmoon Races Start Banner, hit the Blue Post, then return to the Darkmoon Races Start Banner.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So this is your first race, eh? Don\'t worry - it\'s easier than it looks. Let me break it down for you...nnRun through that big  banner there. That starts everything. Then, follow the smaller banners until you see a big, blue Post. Hit that, then return here.nnYou\'re scored on your time, so finish as fast as you can! And watch out for those electrified tripwires. They\'ll slow you down if you run through them. Good luck!', `QuestDescription`) WHERE `ID` = 37819;
