UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Light Be With You', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Yrel at the Coliseum of Light near the Temple of Karabor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve done everything I\'ve asked, $n. I believe we can apply one final enchantment to your ring. But... we must be cautious. Last time I augmented your ring I killed you. (Sorry.) It will take a divine act to empower you further.$b$bFortunately, you\'ve made some powerful allies during your time here. Travel to the Temple of Karabor, where Yrel is waiting for you. With the blessing of a Naaru your ring will become as powerful and unique as - well, as you yourself. Go to Karabor. You\'ve earned it.', `QuestDescription`) WHERE `ID` = 37839;
UPDATE `quest_template` SET `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Drek\'Thar at the Throne of the Elements in Nagrand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve done everything I\'ve asked, $n. I believe we can apply one final enchantment to your ring. But... we must be cautious. Last time I augmented your ring I killed you. (Sorry.) It will take an act of ancient magic to empower you further.$b$bFortunately, you\'ve made some powerful allies during your time here. Seek out Farseer Drek\'Thar at the Throne of Elements in Nagrand. There you can receive the blessing of the elements and safely unlock your ring\'s final form. Go, hero! Claim your reward!', `QuestDescription`) WHERE `ID` = 37840;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Yaeger-367', `LogTitle`) WHERE `ID` = 37842;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Death of the Eldest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Leyworms to obtain $1oa Crackling Leyworm Cores, then drop them into Senegos\'s pool.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I will do what I can to stabilize him, but I will need your help.$b$bThe small amount of energy he has left is coming from the mana pool he rests in.$b$bFollow the whelplings\' lead. Dropping ley crystals into the pool gives him a bit of energy - buying him a few more breaths.$b$bThey seem to be getting the crystals from inside that cave to the north.', `QuestDescription`) WHERE `ID` = 37853;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Last of the Last', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the Azurewing Whelplands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need help.$b$bSince the fall of Deathwing, we dragons have lost nearly all of our power. To make matters worse, we can no longer bear eggs.$b$bMy whelplings are the last of the last.$b$bI need you, champion. Help defend my whelplands, and I swear to you, the blues will be at your side when you need them.', `QuestDescription`) WHERE `ID` = 37855;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Withered', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa withered in the Azurewing Whelplands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The withered are the worst kind of pest. They capture our whelplings, knock them unconscious, and then drink whatever mana they can from the helpless babes.$b$bNormally our drakes and keepers would fend them off. Today, it looks like we may need your help.', `QuestDescription`) WHERE `ID` = 37856;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Runas Knows the Way', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Allow Runas to escort you.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I wish to make it up to you for whatever I did that made you want to kill me.$b$bHmm... your dragon complains about being weak. I know why. Runas can fix it, my friend.$b$bOne of my kind, Ael\'Yith, pulls ley energy from the very ground of Azsuna. I can take you to the location of his mana siphons.$b$bIt\'s not too late to undo the harm the others have done. You\'ve done well to trust me.', `QuestDescription`) WHERE `ID` = 37857;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stellagosa', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Stellagosa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Something is wrong, $n.$b$bI sent Stellagosa to assist you, but I can no longer sense her.$b$bPlease, go out there and find out what\'s happened to my granddaughter.', `QuestDescription`) WHERE `ID` = 37858;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Consumed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find a Dim Ley Crystal, then revive $2oa Mana-Drained Whelplings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The whelpling is alive, but unconscious. One of the withered must have already drained it of mana.>$b$b<You\'ve already learned that exposed ley crystals contain a small amount of magical energy. Perhaps you can use one to revive some of the whelps.>', `QuestDescription`) WHERE `ID` = 37859;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'You Scratch My Back...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Release the whelplings on each of the Mana Collector Pylons in Zarkhenar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Much better. I knew I could count on you, my friend. Allow me to return the favor.$b$bI know how you can destroy the large mana collector pylons. We shall save your dragon yet!$b$bThe pylons only work against ground targets, yet they\'re defenseless from above. Send your whelplings at them, my friend. The whelplings can fly where we cannot.$b$bTrust me.', `QuestDescription`) WHERE `ID` = 37860;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nightborne Prince', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Ael\'Yith.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Senegos is focused.>$b$bI sense it now. In the ruined building, to the east. One of these cretins must have tapped deep into the ley line.$b$bI suspect he will be heavily defended, $n. Once again, the well-being of my brood is in your hands.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'He\'s been pestering you from atop his ruins. Maybe it\'s time to pay him a visit...', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Ael\'Yith', `PortraitGiverName`) WHERE `ID` = 37861;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Still Alive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Stellagosa to take a ride back to Azurewing Repose.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Wait, what was it that I heard? Was it... "feast on the dragons"? We must check on grandfather, right away!$b$bLet me know when you\'re ready to depart.', `QuestDescription`) WHERE `ID` = 37862;
