UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Invasion of Tanaan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Khadgar and then speak to Draka to start the invasion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is done! By your command we have built our first ship and can run our naval operations from here.$b$bNow that we have our transport, we can let Durotan and that Archmage of yours know that we are ready to kick off an invasion of Tanaan. Speak with them at the docks to embark.', `QuestDescription`) WHERE `ID` = 37889;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Obstacle Course', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find any information on the forces deployed in the area and meet with the scouts afterwards.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is strange that these docks were abandoned by the Iron Horde, but up ahead our scouts report trouble.$b$bA set of Bleeding Hollow scavengers is busy looting the abandoned buildings to the northwest.$b$bFurther down the road orc cultists are doing... something... near the Dark Portal.$b$bWe should try to recover any orders or information as to what is going on here, then meet with our scouts further in...', `QuestDescription`) WHERE `ID` = 37890;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on Ironhold Harbor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don\'t cut off the flow of supplies then we risk losing control of our plans in Tanaan.nnA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.', `QuestDescription`) WHERE `ID` = 37891;
