UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clearing the Docks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Iron Horde orcs and $2oa ogron.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our salvage team thought these here docks would be abandoned, but they\'re crawlin\' wit\' remnants of the Iron Horde. Gul\'dan\'s cronies are convertin\' anyone they can and evacuatin\' everyone to Tanaan Jungle.$b$bCommander, if yeh can clear this place out, my team can salvage some of this equipment.$b$bPlus, ev\'ry orc yeh kill here is one less ta worry about in Tanaan!', `QuestDescription`) WHERE `ID` = 37921;
