UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Runas the Shamed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Runas the Shamed.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I fell so quickly, $n. I am not as strong as I once was. We truly do need your help.$b$bOne of these disgusting creatures ran off with several of the whelplings. I heard him called by name:$b$bRunas.$b$bI will survive. Home is not far. You still have strength, though. Slay this Runas before he does any more damage to our brood.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Runas the Shamed', `PortraitGiverName`) WHERE `ID` = 37957;
