UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hunger Returns', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 4 Charged Mana Jewels.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Runas looks antsy.>$b$bI can help you, and I very much want to help you, but I\'m a bit distracted. Look at all that raw, unfiltered, mouthwatering mana...$b$b<Runas slaps his own face.>$b$bNo! NO! You must stay in control!$b$bI simply need to clear my head. Yes, that\'s it. A few of my depraved brethren carry small mana jewels around with them in case they need a quick burst of energy. Find a few for me? Then I will show you how to get your ley line back.', `QuestDescription`) WHERE `ID` = 37959;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leyline Abuse', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Iskhaneth and Tyndrissen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These monsters are pulling mana directly out of the ground. This explains why not even my mana pools can dull my pain.$b$bI worry about my brood. Without the power of the ley lines, we are nothing. At this rate, I may not even be able to help you with your Tidestone.$b$bLook for their mana siphons, and punish the cowardly nightfallen elves that are using them.', `QuestDescription`) WHERE `ID` = 37960;
