UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Feasting on the Dragon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa withered in Azurewing Repose.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You killed their leader, so they came here? Understandable. These creatures crave only one thing - magic - and they can sniff it out from leagues away.$b$bWithout a leader, they will soon wither and die. Our only recourse in the meantime is to put as many as possible down before they take these dragons with them!', `QuestDescription`) WHERE `ID` = 38014;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'On the Brink', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Radiant Ley Crystal or your healing spells and abilities to resuscitate wounded dragons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This many withered threaten to wipe our brood out completely!$b$bQuickly, $n! Crack off a ley crystal and heal any wounded drakes you can find out on the battlefield.$b$bI will do what I can to keep these whelplings safe and healthy.', `QuestDescription`) WHERE `ID` = 38015;
