UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Royal Summons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Royal Summons and follow Sky Admiral Rogers through the portal to Stormwind Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well met, $p. I have come on behalf of King Anduin Wrynn.$B$BMy crew is preparing for a special mission, and the king would like you to join us. Please review this official summons and, if you are satisfied, return with me to Stormwind Harbor.$B$B<Rogers hands you a sealed envelope.>', `QuestDescription`) WHERE `ID` = 38035;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplies From the Skies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Skyfire First Aid Kits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Are you feeling alright? Say \'ah.\'$B$B<Mishka attempts to depress your tongue with a damp twig.>$B$BSorry... we are in desperate need of medical supplies here. The infirmary on the Skyfire was well-stocked, but it\'s all scattered to the winds now.$B$BAnything you can salvage from the wreck will save lives!', `QuestDescription`) WHERE `ID` = 38036;
