UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bleeding the Bleeding Hollow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Bleeding Hollow at Zeth\'Gol in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bleeding Hollow provide significant reinforcement to the Iron Horde in Tanaan. From their home in Zeth\'Gol they relentlessly pursue our scouts, disrupt our operations, and gather more power for Gul\'dan\'s magic.nnWe should consider a direct raid on Zeth\'Gol to make them pull back their forces across the valley. This should give us some breathing room... for a time.', `QuestDescription`) WHERE `ID` = 38044;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bleeding the Bleeding Hollow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Bleeding Hollow at Zeth\'Gol in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bleeding Hollow provide significant reinforcement to the Iron Horde in Tanaan. From their home in Zeth\'Gol they relentlessly pursue our scouts, disrupt our operations, and gather more power for Gul\'dan\'s magic.nnWe should consider a direct raid on Zeth\'Gol to make them pull back their forces across the valley. This should give us some breathing room... for a time.', `QuestDescription`) WHERE `ID` = 38045;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle At The Iron Front', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Aid the Alliance and Horde assault at The Iron Front in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'General, our troops are currently engaged in a conjoined assault at the Iron Front. The fight has been raging for some time now, and casualties are high.$b$bReport to the Iron Front and lend your strength to the war effort. I have no doubt that your presence on the battlefield will inspire the soldiers to victory!', `QuestDescription`) WHERE `ID` = 38046;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle At The Iron Front', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Aid the Alliance and Horde assault at The Iron Front in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The war against the Iron horde rages on.$b$bNot far from here at The Iron Front, our warriors are engaged in mortal combat with the enemy. They fight tenaciously and with great fury, but the losses have been severe.$b$bGo to The Iron Front and show the enemy that we will not falter in this war.$b$bShow them that we fight as wolves!', `QuestDescription`) WHERE `ID` = 38047;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle At The Iron Front', `LogTitle`) WHERE `ID` = 38051;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Boarded!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Forsaken Bat-Riders or Forsaken Deathstalkers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Glad to see you survived the crash. Unfortunately, so did most of the enemy\'s boarding party.$B$BJust the thought of those monsters setting foot on my ship makes me sick. Wipe them out, $p. For my crew... For King Wrynn...$B$BFor the Alliance!', `QuestDescription`) WHERE `ID` = 38052;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault and Battery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the Transponder Battery from Dread-Rider Malwick.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need to report our position to the Alliance navy ASAP!$B$BI am building a new transponder to send a distress signal, but I need a battery from the Skyfire\'s communications console.$B$BYou\'ll find the console at the top of the ship - I just hope those undead haven\'t put their creepy, bony fingers on it yet!', `QuestDescription`) WHERE `ID` = 38053;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle At The Iron Front', `LogTitle`) WHERE `ID` = 38054;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Lost Legion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate the missing 7th Legion Dragoons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The heroic men and women of the 7th Legion stayed at the front of the ship to fight off storm drakes while the crew evacuated.$B$BNone of them have returned.$B$BPlease find them, $p!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Knight-Captain Rhodes.', `QuestCompletionLog`) WHERE `ID` = 38057;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lightning Rod', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Charge the Transponder by absorbing Storm Drake lightning attacks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Overspark\'s tiny hands move like lightning, affixing coils and tubes to the device before cramming it into a parachute pack.>$B$BPut this on.$B$BJust up the hill you\'ll find the front half of the Skyfire - and the big nest of storm drakes it crashed into! We can use the energy from those drakes to charge the transponder.$B$BYou\'ll have to incite them, of course, but the device should draw most of the power.$B$BThe probability of you being electrocuted is well within acceptable parameters!', `QuestDescription`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Tinkmaster Overspark', `PortraitTurnInName`) WHERE `ID` = 38058;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pins and Needles', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Release $1oa 7th Legion Dragoons from static fields.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hngghh!$B$BNope, can\'t stand yet. It\'s all pins and needles.$B$BSmall fries like this are usually no problem for the 7th, but we weren\'t prepared for their electrical attacks. Before I knew it, I was trapped in some kind of static field. Couldn\'t move a muscle until you came along.$B$BMy comrades were carried deeper into the cave. Get \'em out before they become whelp chow!', `QuestDescription`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Mishka', `PortraitTurnInName`) WHERE `ID` = 38059;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Signal Boost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Skyfire Propeller to broadcast a distress signal, then hold out until help arrives.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Skyfire\'s starboard propeller came to rest on the cliffs overlooking our camp - we\'re gonna use it like a big antenna and push our distress signal so far that even Mekkatorque\'s alarm clock could pick it up!$B$BUnfortunately, it might attract some unwanted attention.$B$BWe\'re braced for enemy contact down here at the camp - fire up that signal and be ready to defend the antenna!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Tinkmaster Overspark', `PortraitGiverName`) WHERE `ID` = 38060;
