UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Archdruid of the Claw', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Steelclaw Vale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Near the southern edge of our forest you will find Sleeper\'s Barrow.$B$BThere, Archdruid Koda Steelclaw and her dedicated disciples carry out their sacred duty to observe the Emerald Dream.$b$bFind disciple Rylissa Bearsong in Steelclaw Vale and notify her of the crisis in the Grove of Cenarius.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Rylissa Bearsong at Steelclaw Vale.', `QuestCompletionLog`) WHERE `ID` = 38142;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Awakening the Archdruid', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Awaken the Archdruid of the Claw.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now, we must focus our efforts on waking Archdruid Steelclaw.$B$BShe and our druid brethren slumber in the barrow dens to the south.$B$BWith the furbolgs quelled, we can pass safely to the entrance.$B$BGo and awaken the Archdruid. I pray to Elune that we are not too late.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Archdruid Koda Steelclaw in the Sleeper\'s Barrow.', `QuestCompletionLog`) WHERE `ID` = 38143;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Demons Below', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 8 Darkfiend Intruders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Something, someone, intended us to never awaken. I sense their presence is still here in the barrow.$B$B<Koda takes a moment to stand.>$B$BMy body is weak from deep slumber.$B$BIf you would aid us, clear our barrow of any enemies.', `QuestDescription`) WHERE `ID` = 38144;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Out of the Dream', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Awaken $1oa Druids of the Claw.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Malfurion Stormrage... A name I have not heard in centuries.$B$BHe was teacher to many of us. If he seeks my audience, I cannot refuse.$B$BI will go to the Grove of Cenarius, but first, we must awaken the rest of my clan. They slumber with no way of waking.$b$bA mysterious force of great power is at work against us.$B$BI am still too weak from my hibernation. Please, stranger, go and free them from their dreams.', `QuestDescription`) WHERE `ID` = 38145;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Chieftain\'s Beads', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Elder Sookh at Smolderhide Thicket.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The ceremonial beads, decorated with shells and feathers, are worn by the clan\'s chieftain.$B$BPerhaps Elder Sookh would be interested in seeing these.', `QuestDescription`) WHERE `ID` = 38146;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Entangled Dreams', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Morphael.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I sense powerful magic emanating from deep within the barrow.$B$BWhatever is down there weaves a powerful spell, entangling us within our dreams.$B$BI am still too weak, but your skills are quite impressive, hero. I can see why Malfurion puts his trust in you.$B$BGo and eliminate the source of this magic.', `QuestDescription`) WHERE `ID` = 38147;
