UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on Stonefury Cliffs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines.nnShadow Hunter Rokhan has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.', `QuestDescription`) WHERE `ID` = 38176;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on Magnarok', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the stone monstrosities at Magnarok in Frostfire Ridge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north.nnIf we strike at them at their home, we should be able to force them back. It\'s risky, but it may be our best move. While you\'re there, see if you can recover any of our supplies.', `QuestDescription`) WHERE `ID` = 38177;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on the Iron Siegeworks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge.nnA strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.', `QuestDescription`) WHERE `ID` = 38178;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on the Everbloom Wilds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Botani forces in the Everbloom Wilds in Gorgrond.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place.nnRokhan has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the jungles of Gorgrond, giving us more room to maneuver around them.', `QuestDescription`) WHERE `ID` = 38179;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on the Broken Precipice', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the ogron forces at the Broken Precipice in Nagrand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them.nnMost of these ogron appear to be coming from the Broken Precipice, deep in western Nagrand. If we\'re to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.', `QuestDescription`) WHERE `ID` = 38180;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on Mok\'gol Watchpost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Warsong force at Mok\'gol Watchpost in Nagrand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Warsong raiders out of Mok\'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We\'ve warned travelers not to stray out alone, but many don\'t listen.nnIf we were to launch an assault on Mok\'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.', `QuestDescription`) WHERE `ID` = 38181;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on Darktide Roost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There\'s been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don\'t stop them at the source, we\'ll quickly lose control of the roads and be pushed back into our outposts.nnThe most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should be able to stop their operation cold.', `QuestDescription`) WHERE `ID` = 38182;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on Socrethar\'s Rise', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Sargerei forces at Socrethar\'s Rise in Shadowmoon Valley.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar\'s Rise in southern Shadowmoon Valley.nnSocrethar\'s disciples pose a threat all over Draenor. We must not allow them to gain a foothold so far from our reach.', `QuestDescription`) WHERE `ID` = 38183;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on Lost Veil Anzu', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu.nnRokhan has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.', `QuestDescription`) WHERE `ID` = 38184;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on Pillars of Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Shadowmoon forces at Pillars of Fate in Shadowmoon Valley.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak.nnRokhan is concerned at their proximity to key choke points leading into Shadowmoon Valley, and has put out a request that we thin their forces as soon as possible.', `QuestDescription`) WHERE `ID` = 38185;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on Skettis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the arakkoa forces at Skettis in Spires of Arak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads.nnGuards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.', `QuestDescription`) WHERE `ID` = 38186;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missive: Assault on Shattrath Harbor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Sargerei forces at Shattrath City in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Shattrath City is in the hands of Sargerei forces under the leadership of the once Exarch, Socrethar.nnThe Shadow Council forces in the eastern portion of the city are gaining in power through the aid of demons from the Nether, and need to be culled before they become a threat to all of our operations.', `QuestDescription`) WHERE `ID` = 38187;
