UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Challiane Vineyards', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the 3 parts of the Nightrose recipe.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Please, outsider, help me.$b$bMy recipe for Nightrose wine was to be the toast of Queen Azshara herself. But before I could make it, the vile vintners took it from me and locked me away.$b$bPlease, recover my recipe so that I might bring it to Lady Challiane and earn the queen\'s favor.', `QuestDescription`) WHERE `ID` = 38203;
