UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Get a Clue', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the Ruins of Kra\'nak for clues.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Aktar mentioned that in the ruins he\'s seen Sethekk, ogres, even demons, but no sign of Iskar.$b$bWe\'re going to have to go in there if we\'re to find any clues and I\'d prefer someone strong like yourself to lead the way.$b$bWell, what do you say?', `QuestDescription`) WHERE `ID` = 38213;
