UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Ascension', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Reshad in the Ruins of Kra\'nak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You skim through the pages of the tome, most of them filled with notes on the nature of shadow and illusion. On the last pages you discover a journal:$B$BI continue to search for a cure to the curse of Sethe. If Terokk was restored I would not be in this situation. Damn Reshad!$B$BI was contacted by an orc that identified himself as Gul\'dan. He has a cure for the curse! I must travel to Tanaan to search for the location of this "cipher" of his.$B$BTake this information to Reshad.', `QuestDescription`) WHERE `ID` = 38223;
