UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Death to the Witchmother', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Magula.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The numberless years of my life have been dedicated to learning and perfecting the arts of healing and restoration.$b$bNothing in this world pains me more than taking a life, traveler.$b$bIt is with a heavy heart that I must commission the death of Magula, the leader of the harpies that threaten this grove.$b$bMay her death save the lives of more noble beings.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Magula', `PortraitGiverName`) WHERE `ID` = 38225;
