UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Minion! Kill Them!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Fulfill your part of the deal with Daglop.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Per your contract you will help me gather supplies for a perfectly harmless ritual.$b$bI need feathers, and horns. Lots of horns. See those shadowrunners, prowlers and heron over there in the Olivian Veil? They should have lots of both.$b$bOh! And I need olives. Lots of olives. One for each finger.$b$BMinion! Let\'s ride!', `QuestDescription`) WHERE `ID` = 38232;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Event: Inscribed Ruin Found', `LogTitle`) WHERE `ID` = 38234;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Solid as a Rock', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue Marnor Lorleaf, Erwind Mistfen and Del\'thanar Sagewood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Cenarius requires me?$b$bI shall depart as soon as I am able, but I mustn\'t leave while my druids are in danger. A vile harpy coven has emerged and seeks to claim my grove as their own.$b$bThese vermin inflict a petrifying disease which, given time, will destroy the infected.$b$bWhile I wish for all of my followers to be cured, it is crucial that my elder disciples survive to protect the grove in my absence.$b$bIf you would assist us, find my disciples and rouse them from this terrible state.', `QuestDescription`) WHERE `ID` = 38235;
