UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'This IS In My Contract.', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Daglop complete his ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To perform my ritual I need to use a special cave I have prepared at Gloombound Barrow.$b$bMeet me there and I will "give" you your reward. Hee hee.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Tehd\'s Master-Before-Last', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Sharazaan', `PortraitGiverName`) WHERE `ID` = 38237;
