UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Totemic Call', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Nightmare Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I heard the others talking earlier. I may know the cause of their fear.$B$BThey say the Chieftain has a mysterious totem. It gives him power, and fearful visions.$B$BIf you destroy the totem, the madness will end.', `QuestDescription`) WHERE `ID` = 38246;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on the Ruins of Kra\'nak', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Shadow Council forces at the Ruins of Kra\'nak in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Shadow Council have recruited the Sethekk and other power hungry Arakkoa to their service. Our allies in the Order of the Awakened have tracked them to a ruin in the west of Tanaan where the Shadow Council is instructing them in the use of fel magic.nnWe must strike at them before they can master their diabolic powers.', `QuestDescription`) WHERE `ID` = 38250;
