UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on the Ruins of Kra\'nak', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Shadow Council forces at the Ruins of Kra\'nak in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Shadow Council have recruited the Sethekk and other power hungry Arakkoa to their service. Our allies in the Order of the Awakened have tracked them to a ruin in the west of Tanaan where the Shadow Council is instructing them in the use of fel magic.nnWe must strike at them before they can master their diabolic powers.', `QuestDescription`) WHERE `ID` = 38252;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Garrison Campaign: War Council', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with King Varian Wrynn inside the Town Hall of your garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your garrison is in an uproar. King Varian Wrynn himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle.$b$bThe King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'King Wrynn is waiting for you.', `PortraitGiverText`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with King Varian Wrynn inside the Town Hall of your garrison.', `QuestCompletionLog`) WHERE `ID` = 38253;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Derailment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Explosive Charges and a Detonator.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Several orcs have spoken out since Gul\'dan assumed control. Some were taken prisoner. Among them is an engineering prodigy: Solog Roark, "The Iron Shipwright." He designed these docks as well as the great dreadnaughts of the orcish fleet. If my scouts are right, he\'s in that prison train as we speak... And he may be ready to defect!$b$bGather explosives and meet with Yrel at the train to the southeast!', `QuestDescription`) WHERE `ID` = 38254;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Train Gang', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the detonator to blow open the prison train, and convince Roark to join your cause.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These rangari will surround and cover the train car. Hit the detonator to blow open the doors.$b$bI will try to talk Roark into joining our cause. He\'s a genius around a drydock and our best hope for building a shipyard.$b$bIf it doesn\'t work, we must be prepared to kill him. The last thing we need is someone rebuilding another Iron Fleet...', `QuestDescription`) WHERE `ID` = 38255;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hook, Line, and... Sink Him!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use a Blackrock Grapple to reach Knar\'s bunker. Slay him to obtain Roark\'s Shipyard Blueprints.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can build you a shipyard. And not some wasteful piece of over-engineering like this place.$b$bBut I\'m going to need my blueprints. My work was confiscated when Gul\'dan turned this harbor over to Admiral Knar.$b$b<Roark spits.>$b$bGul\'dan\'s green poison courses through Knar\'s veins. He\'s calling the shots from on high. We\'ll need to grapple up there to take him out.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Admiral Knar', `PortraitGiverName`) WHERE `ID` = 38256;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Need a Shipwright', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Iron Docks and speak with Exarch Naielle. Your Garrison Flight Master can provide transport.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Iron Horde - or whatever Gul\'dan is turning them into - has fallen back and fortified the entrance to Tanaan. A direct assault will take a heavy toll.$b$bHowever, the sea lanes are open. If we attack by both land and sea, Gul\'dan\'s Horde will have no quarter. $n, it\'s time to build a shipyard!$b$bWe\'ll need to source local resources. Travel to the Iron Docks, where a small Alliance reclamation force is already waiting. Gather what equipment you can, and find us a shipwright capable of building a fleet!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Travel to the Iron Docks and speak with Exarch Naielle. Your Garrison Flight Master can provide transport.', `QuestCompletionLog`) WHERE `ID` = 38257;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nothing Remains', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report back to King Wrynn at the Town Hall in your garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Nothing is left for me here. My old clanmates have turned into foes, and Gul\'dan is desecrating what remains of my people.$b$bYou and your allies from Shattrath still have some fight left. If you pledge to depose Gul\'dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor!$b$bLet your people know I am coming.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Report to King Wrynn at the Town Hall in your garrison.', `QuestCompletionLog`) WHERE `ID` = 38258;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'All Hands on Deck', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather materials and construct a Level 1 Shipyard for your garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Let\'s put this "Iron Shipwright" of yours to work, commander. If we\'re to pull off your plan to assault Tanaan from both land and sea, we\'ll need to get some docks operational as soon as possible. Work with Roark and build the Alliance a shipyard!$b$bLast I saw, Roark was northwest of the garrison, near Eventide Landing.', `QuestDescription`) WHERE `ID` = 38259;
