UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Friends Above', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Reshad at Atkar\'s Post.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Iskar disappeared and now the Shadow Council is at our throats. These can\'t be unrelated events. We need to go to the last place he was seen, the ruins of Kra\'nak.$b$bI\'ve asked a friend to set up a camp nearby. I say we head there to continue our search.', `QuestDescription`) WHERE `ID` = 38267;
