UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Finding the Killer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate the slayer of Bleeding Hollow near Zeth\'Gol.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With this map, you have pinpointed the origin of the attacks. It is time to see who or what is behind the attacks, and if they are a possible ally.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with the slayer at Zeth\'Gol in Tanaan Jungle.', `QuestCompletionLog`) WHERE `ID` = 38270;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Following the Bloody Path', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Ariok to the cave.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The ones I kill... they speak of a cave. Sacred to the Bleeding Hollow. Kilrogg could be there - I am going.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Ariok outside the Bleeding Hollow cave in Tanaan Jungle.', `QuestCompletionLog`) WHERE `ID` = 38271;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Bleeding Hollow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Reach the bottom of the Bleeding Hollow.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The cave pulls me. It keeps angry spirits near. Kilrogg has done magic here. You help me understand...', `QuestDescription`) WHERE `ID` = 38272;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spirits of the Bleeding Hollow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Enraged Blood Spirits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is clear the cave is protected by powerful ghosts, ancestors of the Bleeding Hollow.nnWhatever is down there, it will be easier to deal with if many of the spirits were dealt with first.', `QuestDescription`) WHERE `ID` = 38273;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Eye of Kilrogg', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Eye of Kilrogg and perform the scrying ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you wish to know what Kilrogg and his new master intend, you will need his eye. After the ritual all chieftains place their eye under the protection of the ghosts of the Bleeding Hollow in the next chamber.nnGo and locate the Eye of Kilrogg in the vault. The other chieftains will not stand with us, and will fight you for it.nnThen place it on the ritual mark nearby to get your answers.', `QuestDescription`) WHERE `ID` = 38274;
