UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: Wrath of Azshara', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Eye of Azshara, then defeat Warlord Parjesh and the Wrath of Azshara. The Eye of Azshara is a dungeon so be certain to gather some friends to undertake this perilous journey.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Warlord Parjesh ran into the magical vortex just ahead. He has returned to an island off the shore to the southeast where Queen Azshara is staging more of her forces.nnThe queen is beyond angry because we opposed her. Even now, she is summoning up a monstrosity known as her Wrath to exact revenge for our defiance and drown the Broken Isles.nnYou must defeat the Wrath of Azshara before the queen lets it loose to destroy us all!', `QuestDescription`) WHERE `ID` = 38286;
