UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Critters of Draenor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Erris the Collector in a pet battle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I love collecting pets, and I\'ve picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we\'ll both learn a few new tricks.', `QuestDescription`) WHERE `ID` = 38299;
