UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Val\'sharah', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Malfurion Stormrage at Lor\'lathil in Val\'Sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[PH] Go through the portal in Dalaran and meet Malfurion Stormrage in Val\'Sharah.', `QuestDescription`) WHERE `ID` = 38304;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cenarius, Keeper of the Grove', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Malfurion Stormrage at Lorlathil in Val\'Sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, hero.$b$bWelcome to Val\'sharah. It has been an age since I have set foot in these precious woods. Too long...$b$bOur work here is simple. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras\' Tomb and thwarting the Legion.$b$bYou have many treacherous tasks in front of you. Consider your visit here a brief respite.$b$bCome, this will not take long.', `QuestDescription`) WHERE `ID` = 38305;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Warchief Beckons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Read the Royal Summons and follow Nathanos Blightcaller through the portal to Durotar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, $p. I am here on behalf of Lady Sylvanas Windrunner. I should hope you recognize the name.$B$B<Nathanos thrusts a sealed envelope into your hand.>$B$BRead it and follow me.$B$BYou can read, can\'t you?', `QuestDescription`) WHERE `ID` = 38307;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eyes in the Overlook', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the SI:7 Intel from Spymaster Knockwhistle in Blackbeak Overlook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alliance personnel from the Skyfire were spotted parachuting into Blackbeak Overlook.$B$BI was unable to confirm numbers or positions during my flyover, but I did see parachutes tangled in treetops and a LOT of ravenbears on the ground.$B$BIf anyone is up there, they must be laying low and keeping an eye on us.$B$BI have posted a rider at the top of the overlook to keep watch while I press forward into Stormheim.$B$B- Liza Cullen, Dread-Rider - 1st Wing', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Cullen must have left this report for Nathanos before heading off on another mission.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Dread-Rider Cullen', `PortraitGiverName`) WHERE `ID` = 38308;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Content Perk: The Light Reveals', `LogTitle`) WHERE `ID` = 38309;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Content Perk: Righteous Strength', `LogTitle`) WHERE `ID` = 38310;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Content Perk: Call of the Highlord', `LogTitle`) WHERE `ID` = 38311;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Grapple a Day', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Pick up a Stormforged Grapple Launcher and meet Lorna Crowley outside the wall of Hrydshal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So these trials are what will get us the Aegis, and the next one is on the top of that mountain? That may prove problematic.nnThe only way I see up the mountain is through that vrykul city, and the gates are shut tight. We should be able to grapple over, though. If you don\'t have a launcher, I managed to wrangle a spare from one of these vrykul.nnI\'ll scout ahead and see if I can find a good spot to get in.', `QuestDescription`) WHERE `ID` = 38312;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Hidden Demon', `LogTitle`) WHERE `ID` = 38314;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azsuna - Treasure 014 - Fel Collector', `LogTitle`) WHERE `ID` = 38316;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Masters of Disguise', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Spymaster Illandris and Spymaster Shwayder.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<You scan over Knockwhistle\'s report.>$B$B"My chute caught a piece of shrapnel. Made a rough landing in a ravenbear nest. Luckily, a bunch of eggs broke my fall.$B$BLost sight of Illandris and Shwayder. Both are masters of disguise, and I am confident they can remain undetected.$B$BWill continue to monitor the enemy\'s activity. Just need to clean all the yolk off my cloaking device. Hope the mother\'s not around...', `QuestDescription`) WHERE `ID` = 38317;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'No Wings Required', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the top of the ridge and use the Stormforged Grapple Launcher to launch over the wall at Hrydshal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you\'ve got the launcher, we should be able to infiltrate the city. It looks like there\'s a good spot to grapple onto on the wall just past us. There\'s a vantage point on top of this ridge.nnOnce we\'re in, I\'ll try to slip past the guards and get a look at the mountain path. I\'d appreciate if you could make some distractions for me. If all goes well, I\'ll meet up with you in the upper city.nnGood luck!', `QuestDescription`) WHERE `ID` = 38318;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure: The Blade of Kra\'nak', `LogTitle`) WHERE `ID` = 38320;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Grove', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Malfurion Stormrage at the Grove of Cenarius in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that my grove is safe, I can turn my attention to the threat you speak of.$B$BTo hear of Cenarius\' plight is disturbing indeed. Tell Malfurion that I shall meet him at the Grove.', `QuestDescription`) WHERE `ID` = 38322;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Grove', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Malfurion Stormrage at the Grove of Cenarius in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Forgive me, $r. Archdruid Moonclaw\'s fall is a terrible blow...$b$bMalfurion must be informed of what has transpired here. Inform him of Thaon\'s fate and of the return of Xavius.$b$bMake haste, friend. I fear this may be the greatest threat Val\'sharah has ever faced.', `QuestDescription`) WHERE `ID` = 38323;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Accessories of the Cursed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Cursed Bones in Helheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Wait! Before ye go rushin\' off, we might want to be gettin more than just seaweed. nnYe see, these vrykul also be carrying bones with them - worn all over like jewelry. If ye can get yer hands on some of the bones they got lyin around, it\'ll add to the disguise.nnSo what ye waitin for?', `QuestDescription`) WHERE `ID` = 38324;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Havi\'s Test', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Toss ingredients from the Basket of Root Vegetables, Barrel of Crabs, and Hearty Vrykul Grains into Havi\'s Stewpot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I could sense your power the moment you arrived in this land. You carry great purpose and a heavy task.nnKnow that the Aegis of Agrammar rests in the high halls of the All-Father. Only if you prove your valor, can you claim it against your foe.nnMany trials must you face for this, but first I must know your strength. My stew is incomplete, and my old bones couldn\'t carry the ingredients up the hill. nnYou look like you have a good arm. Will you help an old man finish his stew?', `QuestDescription`) WHERE `ID` = 38331;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Ranger Lord', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Nathanos Blightcaller.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Good to see you survived the wreck. Nathanos made it as well, though his face is now even uglier than before.$B$BHe took a group of rangers north to look for Sylvanas - nobody has seen her since the battle.$B$BHe asked me to send you his way if you ever woke up.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Report to Nathanos Blightcaller.', `QuestCompletionLog`) WHERE `ID` = 38332;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Drake Wrestler', `LogTitle`) WHERE `ID` = 38333;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure: Jewel of Hellfire', `LogTitle`) WHERE `ID` = 38334;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Built to Scale', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Storm Drake Scales from the Stormwing drakes in Hrydhsal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The vrykul around here seem to use scales from these drakes to fashion their armor. $B$BIf you were able to gather enough material from the local drakes, you may be able to make something useful out of it.', `QuestDescription`) WHERE `ID` = 38337;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Little Kelp From My Foes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa pieces of seaweed from Kvaldir Mistcallers and Soulflayers in Helheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m not sure what yer doin\' here, but ye have my thanks. If ye want to get any further, though, ye\'ll need to get past that foul dog, Guarm.nnI\'ve tried meself a few times, and I think I have a plan. If we can get some of the seaweed these kvaldir wear, we might be able to trick the mutt. Guarm\'s mean, ye see, but not too smart.nnWhat do ye say? Think ye can take on a few kvaldir?', `QuestDescription`) WHERE `ID` = 38339;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Another Way', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Gunnlaug Scaleheart in Hrydshal, then climb to the top of the tower.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well, the bridge option is out. You still got that grapple launcher handy?nnIt looks like we can get across from the top of that tower over there. First thing\'s first, though, we\'ll need to deal with the big ugly sitting out front.nnYou take point.', `QuestDescription`) WHERE `ID` = 38342;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Raze Hel', `LogTitle`) WHERE `ID` = 38343;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mystery Notebook', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return the notebook to Krom Stoutarm in Ironforge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This book has seen better days. Not much can be made out between the waterlogging and the apparent animal bites, but you can make out some sort of Ironforge-based drinking game scoring system involving a dwarf named Krom Stoutarm.', `QuestDescription`) WHERE `ID` = 38344;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stealth by Seaweed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Kvaldir Disguise to sneak by Guarm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There! The disguise be complete!nnDon\'t mind the smell, there. It\'s probably better that we smell like the kvaldir, as well. Though I have a feeling I\'ll be needin a priest to get this stench out once we\'re gone.', `QuestDescription`) WHERE `ID` = 38347;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unlock "Silvermoon"', `LogTitle`) WHERE `ID` = 38348;
