UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bringing the Bass', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Bass Blaster, Laz-Tron Disc Reader, Phonic Amplifier, S.P.R.K. Capacitor, and a Cord of Ancient Wood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s a bit quiet around here, in between the invasions and all.nnYou\'re in luck though, Commander! I can fix that, and boost morale among your troops all at the same time.nnAll you need to do is bring me a few items from around Draenor, and I\'ll fill your garrison with music. I\'ll even throw in a few music rolls from my own collection to get you started!nnWhat do you say?', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Fix "Smallie" Biggswrench', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Fix "Smallie" Biggswrench', `PortraitTurnInName`) WHERE `ID` = 38356;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Side Effects May Include Mild Undeath', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Volatile Bears or Volatile Sailors.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Exposure to this particular "byproduct" is quite nasty.$B$BRapid cell degeneration quickly reduces the subject to a shambling husk incapable of any reason or thought beyond a violent, throbbing hatred for the warmth of life.$B$BAs you might imagine, the local fauna have been affected by the spill. Oh, and most of the crew as well...$B$BAnyway, good luck!', `QuestDescription`) WHERE `ID` = 38357;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pump it Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Fill the Containment Unit with Volatile Waste.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Black Rose was a seafaring laboratory for the Royal Apothecary Society. Naturally, we had some volatile... "byproducts" onboard.$B$BRegrettably, one such substance was released during our skirmish with the Alliance gunship. As you can see, it is taking quite a toll on the coast.$B$BThe R.A.S. must remedy this situation before we press further inland.$B$BPlease take a containment unit and fill it with waste - for us to dispose of properly at a later time, of course.', `QuestDescription`) WHERE `ID` = 38358;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Val\'sharah - Treasure 003 - Lorlathil - twh', `LogTitle`) WHERE `ID` = 38359;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Windrunner\'s Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the wreckage of the Windrunner and the nearby coastline for signs of Sylvanas.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Finding Sylvanas is our only priority!$B$BWe will cover more ground if we split up. I will lead a team into the hills above the enemy\'s camp while you search the wreckage itself for any signs of the crew.$B$BOnce we\'ve cleared the high ground, I will meet you at the far end of the beach.', `QuestDescription`) WHERE `ID` = 38360;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wrath of the Blightcaller', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa 7th Legion Paratroopers or Skyfire Gryphon-Riders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Alliance dogs have bitten off more than they can chew. They have attacked the Banshee Queen, and invoked the wrath of her champion!$B$BLike my bow, my axes, and my hounds, you will be an agent of vengeance. Pile the bodies high, $c, and know that I am doing the same. When next we meet, I expect to see blood upon your hands.', `QuestDescription`) WHERE `ID` = 38361;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Grim Trophy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Head of Thane Wildsky.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It would seem Sylvanas does not wish to be followed - by us or anyone else.$B$BHer will is her own, it is not my place to question. Only to obey.$B$BIn the hills nearby, a gryphon master is preparing to take flight, no doubt to pursue our queen from the sky. My rangers are lying in wait - we need only to close our jaws around him.$B$BI will have his head when this is over.', `QuestDescription`) WHERE `ID` = 38362;
