UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Search for the Highlord', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover Tirion Fordring and the Ashbringer from the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tirion is fading away on that infernal shore... and the Ashbringer with him! We must not waste another moment.$B$BGive the word and we\'ll set off. We\'re ready when you are.', `QuestDescription`) WHERE `ID` = 38376;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Emerald Queen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Malfurion when ready.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, you have returned. Good.$b$bI have counseled with the other archdruids and concluded that Cenarius\' condition is merely a symptom of a much greater problem. Your experiences in Moonclaw Vale make that clear.$b$bWe need help.$b$bThere is one who can bring understanding to these events. With Thaon gone, we must ask that you aid us in reaching out to the Lady of Dreams.', `QuestDescription`) WHERE `ID` = 38377;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Hivequeen Zsala', `LogTitle`) WHERE `ID` = 38380;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Archdruid of Lore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Elothir in Thas\'talah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Elothir resides in the ancient grove Thas\'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore.$b$bSeek him out and tell him that he is desperately needed here.', `QuestDescription`) WHERE `ID` = 38381;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Archdruid of the Vale', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Thaon Moonclaw.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deep within our forest lies Moonclaw Vale.$b$bThere you will find a reclusive group of feral druids charged with the protection of Val\'sharah from any that would seek to disrupt the balance of nature.$b$bThese druids are led by Thaon Moonclaw, the most fierce of the Archdruids.$b$bSeek him out. Let him know that Cenarius is in need of his aid.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Thaon Moonclaw in the Moonclaw Vale.', `QuestCompletionLog`) WHERE `ID` = 38382;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Stormheim - Treasure 019 - Helheim - ZTO', `LogTitle`) WHERE `ID` = 38383;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nature\'s Call', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Aranelle in Lorlathil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What vile power is this?!$b$bA curse with the strength to paralyze a demigod? Unimaginable!$b$bQuickly, $n, you must gather the archdruids of the forest. With their help, we can summon Ysera. She will surely know what horror has overtaken my mentor.$b$bI will remain here and lend Cenarius what aid I can.$b$bReturn to Lorlathil and speak with Aranelle. She will know the archdruids\' whereabouts.$b$bAnd please, friend, make haste...', `QuestDescription`) WHERE `ID` = 38384;
