UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Weather the Storm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Climbing Treads, an Oiled Cloak, and an Enchanted Lodestone from Hrydshal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve been doing some nosing around, and it looks like these vrykul are making regular trips up the mountain themselves. They\'ve got some specialized gear for it, so while we\'re here we should take some.nnI\'d recommend finding some climbing treads to keep your grip on the slopes, as well as an oiled cloak to keep the rain out. Also, it looks like they carry enchanted lodestones, which seem to keep the lightning at bay. You should probably grab one of those, too.', `QuestDescription`) WHERE `ID` = 38405;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bottled Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take Okuna\'s Message to Lady Irisse.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<You\'ve found a message in a bottle on the corpse. It\'s a request for aid from someone named Okuna Longtusk. Okuna claims that he and his fellow shipmates are being held prisoner by sea giants.nnMaybe if you show the note to the ghost of Lady Irisse at the Crumbled Palace, she can point you in the right direction?>', `QuestDescription`) WHERE `ID` = 38407;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Impalement Insurance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Grapple on top of the walls in Hrydshal and dismantle 7 Tideskorn Harpoon Launchers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve got bad news. Those harpoon launchers up on the walls might cause us some problems. nnThey can\'t get at us down here, but once you start climbing that path, they\'re likely going to try to skewer you.nnIf you use that grapple launcher, you should be able to get on top of the walls and dismantle them. Watch out for the drakes, though!', `QuestDescription`) WHERE `ID` = 38410;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Executor Riloth', `LogTitle`) WHERE `ID` = 38411;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Above the Winter Moonlight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Grapple across from the tower and climb to the top of the mountain path.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You should have a good vantage from this tower to grapple over to the mountain path. I can\'t help you once you\'re across, but you should be able to take it all the way up to the top. nnI hope you\'re able to find what you need from the dragons up there. Who knows what the God-King has done to them.', `QuestDescription`) WHERE `ID` = 38412;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wings of Liberty', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free Aleifir, Hrafsir, Erilar and Hridmogir in Thorim\'s Peak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When the Felskorn assaulted the nest, the Thorignir fought bravely to save our brood. But their demonic allies proved too much, and many of us were captured.nnEven now they work to corrupt my brothers and sisters to turn them to their side. nnPlease, outsider, free them from this fate!', `QuestDescription`) WHERE `ID` = 38413;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Heart of a Dragon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and rescue the mother of the Thorignir brood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Through brute force and corruption, the God-King has taken the power you seek, but there may be hope for you and the Thorignir, $C.nnWith the aid of fel powers such as I\'ve never seen, the Felskorn are corrupting our young and seeking to enslave the Thorignir. Their leader, a demon of great power, has captured our mother and seeks to bend her to the God-King\'s will.nnFind her and free her from the demon\'s grasp - only then might the Thorignir regain our power and grant you aid.', `QuestDescription`) WHERE `ID` = 38414;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Garrison Campaign: Onslaught at Auchindoun', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Liadrin at Auchindoun in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your ally, Liadrin, has sent a missive requesting aid near Auchindoun. The Sargerei have made a new assault there and breached something important. It is no coincidence this happened after Gul\'dan\'s ascendancy. We will watch the front here, commander.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Liadrin at Auchindoun in Talador.', `QuestCompletionLog`) WHERE `ID` = 38415;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secrets of the Sargerei', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate and stop the source of corruption underneath Auchindoun.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Auchenai have been reporting for some time that something was... wrong... with Auchindoun. They were never able to find a reason. Suddenly the Sargerei attacked and blew open a hole into a subchamber.nnCorruption leaks from that hole, we need to stop it.', `QuestDescription`) WHERE `ID` = 38416;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Sargerei Menace', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Sargerei.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'An attack such as this was unexpected. They have deployed heavily and it will take me some time to marshal enough forces to root them out.nnAny Sargerei you can slay will make retaking this area much easier commander.', `QuestDescription`) WHERE `ID` = 38417;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azsuna - Treasure 018 - [The Greenway]', `LogTitle`) WHERE `ID` = 38419;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Garrison Campaign: Onslaught at Auchindoun', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Yrel at Auchindoun in Talador.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Auchenai have sent me an urgent missive - Auchindoun is in jeopardy again! The Sargerei have renewed their assault  and breached the underhalls. I sense the hand of Gul\'dan is behind this.$b$bGather your things and meet me in the Court of Souls West of Auchindoun at once!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Yrel at Auchindoun in Talador.', `QuestCompletionLog`) WHERE `ID` = 38421;
