UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Invasion of Tanaan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Khadgar at your shipyard and then speak to Yrel to begin the invasion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is done! By your command we have built our first ship and can run our naval operations from here.$b$bNow that we have our transport, we can let Yrel and Archmage Khadgar know that we are ready to kick off an invasion of Tanaan. Speak with them at the docks to embark.', `QuestDescription`) WHERE `ID` = 38435;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Obstacle Course', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find any information on the forces deployed in the area and meet with the scouts afterwards.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our landing was unopposed. Why are these docks all but abandoned?$b$bThe rangari scouts up ahead report trouble. Bleeding Hollow scavengers are looting some abandoned buildings to the northwest, and an encampment of warlock cultists lurk near the Dark Portal. Let\'s find out what we can and meet up with our scouts.', `QuestDescription`) WHERE `ID` = 38436;
