UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Journey to the Repose', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar at the Azurewing Repose.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'For now, the Illidari can hold the line against the Legion. We will return later to help them drive the Legion from the upper reaches of Faronaar. You and I must concentrate on the Pillars of Creation if the Tomb of Sargeras is to be resealed.nnYour saving of Stellagosa is fortuitous. Surely if anyone knows where a Pillar of Creation is, it will be her grandfather, Senegos.nnThe Azurewing Repose is to the northeast. I will meet you there, $n.', `QuestDescription`) WHERE `ID` = 38443;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In, Through, and Beyond!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Fel Defense Cannon covering the gate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Gul\'dan seems to have concentrated his defenses on this chokepoint. The guns up ahead are unlike anything we\'ve seen before - they\'re empowered with fel energy.$b$bOur enemies think this pass is impregnable. Let\'s prove them wrong, commander! If we can break through, the terrain ahead will make an excellent stronghold. Destroy that cannon!', `QuestDescription`) WHERE `ID` = 38444;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Assault Base', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Establish your assault base in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you were playing with fel fire, I\'ve located the perfect position for an assault outpost.nnFollow me and we can get this base started!', `QuestDescription`) WHERE `ID` = 38445;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Commander in the Field!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Get reports from various scouts in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This battle will be won, but it will be hard fought. Our rangari did manage to get a few scouts out to the rest of the jungle though.$b$bPerhaps it is best you collect this intelligence yourself and see what this jungle holds for us all.', `QuestDescription`) WHERE `ID` = 38446;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on the Temple of Sha\'naar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Sargerei forces at the Temple of Sha\'naar in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Up in the hills of Tanaan Jungle, the Sargerei have converted a once-sacred temple into a den of demonic summoning.nnWe must attack them now, before their rituals complete. The longer we delay, the stronger our enemy grows.', `QuestDescription`) WHERE `ID` = 38449;
