UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Garrison Campaign: The Bane of the Bleeding Hollow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect tracking maps to find the location of the killer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, now that we\'ve had time to get scouts all over the jungle we have heard some news near Zeth\'Gol.nnIt appears that somebody else has a vendetta against the Bleeding Hollow and has been... hunting... them. Their hunters are closing in on the assassin.nnYou know what they say about "the enemy of my enemy..." We should collect their tracking maps and try to find the killer first!', `QuestDescription`) WHERE `ID` = 38453;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Frenzied Furbolgs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 8 Smolderhide furbolgs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I would help you seek audience with the Archdruid, but we have a difficult situation on our hands.$B$BThe nearby furbolgs have gone into a frenzied rage.$B$BFor days, it has been all we can do to protect our grove from their aggression.$B$BThey have cut off our access to the barrow dens, where the Archdruid and our clan sleep in the Emerald Dream.$B$BIn order to awaken them, we must first get past the furbolg.', `QuestDescription`) WHERE `ID` = 38455;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Putre\'thar', `LogTitle`) WHERE `ID` = 38457;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Garrison Campaign: The Warlock', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the warlock at Vol\'mar in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, you have a visitor. One of Gul\'dan\'s warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur.nnI suggest you speak with him immediately.', `QuestDescription`) WHERE `ID` = 38458;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Ancient Trials', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Havi near Aggramar\'s Vault.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<As the raven stares into your eyes, an odd voice fills your mind.>nnI know who you are, champion, and I know what you seek.nnCome to me, if you think yourself truly worthy.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'This strange old vrykul seems to know you somehow...', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Havi', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Havi near Aggramar\'s Vault.', `QuestCompletionLog`) WHERE `ID` = 38459;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Let\'s Make A Deal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Sign Daglop\'s contract.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hey there!$b$bYou seem like a gullib- er... um... "intelligent" type.$b$bI propose a deal.$b$bI need a minion to be my muscle to help me acquire a few special... "ingredients" for a ritual.$b$bIn exchange, I\'ll give you my former master to do with whatever you demon-slaying types do with demons.$b$bIf you are interested, just sign here. In blood, please.', `QuestDescription`) WHERE `ID` = 38460;
