UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Breaching the Barrier', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Black Candle, the Tome of Protection, and the Shadowblade at the Fel Forge and bring them to Oronok.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The ritual site is already prepared, and it is protected by a barrier... one that I created. I can destroy the barrier, but I will need three items currently in use at Forge Camp Vengeance.nnIf you can get those ritual items, I will meet you at the Corrupted Refuge and remove the barrier. Even if it kills me.', `QuestDescription`) WHERE `ID` = 38462;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Cipher of Damnation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Get Oronok and your ally to destroy the barrier, then stop Gul\'dan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy.nnGul\'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.', `QuestDescription`) WHERE `ID` = 38463;
