UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Will of the Thorignir', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Lorna Crowley outside of Hrydshal to begin the trial of the Thorignir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In the summit of storms the dragons await. Born of the gods, they will test your will. nnThey roost above Hrydshal, where their children serve the Drekirjar. But they are no allies to man or vrykul, and so you must earn their blessing as they see fit.nnA friend of yours awaits in Hrydshal, no doubt searching for the answers you now possess. Go to her, and together, you will test your might against the storm!', `QuestDescription`) WHERE `ID` = 38473;
