UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Strange New Ores', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 10 Leystone Ore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You smell that, smith? Ahhhh... that there\'s the smell of opportunity.$b$bDalaran\'s taken us to some strange new shores, filled with mysterious metals. I\'m tethered to my shop here, but you... you\'ve got the freedom to explore and mine at will.$b$bBring me something interesting, and we\'ll see what we can make with it.', `QuestDescription`) WHERE `ID` = 38499;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leysmithing Mastery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Alard Schmied\'s recipes in your Blacksmithing recipe list to build some Handcrafted Leystone Gauntlets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well, now that we have the flux we can put it to work and see how it goes. Why don\'t you take a crack at it this time and make some gauntlets for me. I\'ll observe your work... from a distance.', `QuestDescription`) WHERE `ID` = 38500;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hatecoil Hammerwork', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Masterwork Hatecoil Breastplate and a pair of Masterwork Hatecoil Pauldrons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There may be a way to jump-start our research into leystone.$b$bI\'ve heard reports of naga camps down in Azsuna. If they\'ve been in Azsuna for long enough, their smiths have certainly started experimenting with leystone themselves.$b$bBe on the lookout for some leystone armor on the naga... ideally something more elaborate than a bracer.', `QuestDescription`) WHERE `ID` = 38501;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Methods of the Nightfallen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain an Ancient Sentry Construct Memory Core.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have a theory, $n.$b$bHave you encountered the nightfallen elves of Azsuna? They descend from the Highborne, and the accomplishments of Highborne smiths are legendary.$b$bThese fallen elves do a bit of arcane tinkering, crafting sentries to patrol their camps.$b$bBring me a memory core from one of their constructs. Who knows what manner of smithlore might lie within!', `QuestDescription`) WHERE `ID` = 38502;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Stormheim - Treasure 020 - Helheim - ZTO', `LogTitle`) WHERE `ID` = 38503;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shrine of the Bear Twins', `LogTitle`) WHERE `ID` = 38504;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Engineers: Not COMPLETELY Useless', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Ancient Sentry Construct Memory Core to Timofey Oshenko in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Unfortunately, I have no idea how to access any information within this core. But I know someone who does.$b$bHead over to "Like Clockwork", the engineering shop three doors down from here. Timofey Oshenko owes me a favor. He should be able to extract the memory out of the core.', `QuestDescription`) WHERE `ID` = 38505;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Chicken Scratch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Ancient Highborne Data Printout to Professor Pallin in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I think I have just the thing to extract the information from this core for you.$b$b<Timofey loads the core into the hopper of a clearly goblin-made machine, then covers his ears.>$b$bYou may wish to avert your eyes, blacksmith.', `QuestDescription`) WHERE `ID` = 38506;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secrets of Leysmithing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Leysmithing Guide to Alard Schmied in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I could spend hours poring over the details of this fascinating manuscript!$b$b...is what I would say if this weren\'t the simplest of tasks for someone of my skill level. It\'s about something called "Leysmithing". Here.$b$b<The gnome scribbles down a translation on the back of the scroll.>$b$bThere it is, word-for-word. Bring me something interesting next time.', `QuestDescription`) WHERE `ID` = 38507;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shrine of the Bear Twins - Reward', `LogTitle`) WHERE `ID` = 38508;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Stormheim - Treasure 021 - Helheim - ZTO', `LogTitle`) WHERE `ID` = 38509;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Stormheim - Treasure 021 - Helheim - ZTO', `LogTitle`) WHERE `ID` = 38510;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Stormheim - Treasure 022 - Helheim - ZTO', `LogTitle`) WHERE `ID` = 38511;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Oakleaf', `LogTitle`) WHERE `ID` = 38512;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Highmountain Smiths', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Barm Stonebreaker in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I think we\'ve gone as far as we can go with what I know, $n.$b$bThe tauren of Highmountain must have some smiths among their ranks. See if you can find out how to further progress our leysmithing abilities from them.', `QuestDescription`) WHERE `ID` = 38513;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'You Are Not Worthy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your blacksmithing skill to craft a pair of Leystone Gauntlets for Barm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You wish me to teach you how to strengthen your crafts? We do not simply share the secrets of our trade with outsiders who ask for them.$b$bWe do, however, respect craftsmanship and discipline.$b$bLet\'s see your hammerwork. Our greenhorn trainees use those small anvils over there. Craft your best pair of gauntlets so I may judge your work.', `QuestDescription`) WHERE `ID` = 38514;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nature Provides', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 10 Foxflower.$b$bIf you are not an herbalist, you can purchase Foxflower on the Auction House, or you can obtain it from another player.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is interesting, it says that leystone reacts violently with anything it views as a contaminant. Our foreign-mined flux was enough to cause the small explosion.$b$bLocal ingredients, however, have learned to coexist with leystone. Up in Highmountain, an herb called foxflower grows that can be turned into a suitable flux.$b$bGo and gather some foxflower that we can turn into a usable flux.', `QuestDescription`) WHERE `ID` = 38515;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Stormheim - Treasure 022 - Helheim - ZTO', `LogTitle`) WHERE `ID` = 38516;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tayla\'s Rescue', `LogTitle`) WHERE `ID` = 38517;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'From One Master to Another', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go back to Alard in Dalaran and share what you\'ve learned from the Tauren.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now young one, go back to your master$bin Dalaran and continue to practice your swing. We\'ll always be here if you wish to come back and learn more.', `QuestDescription`) WHERE `ID` = 38518;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grayheft', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain Grayheft, Ancient Hammer of the Highmountain Tauren from Kubrul within the Deep Roads cavern.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our tribe regularly crafts legplates out of leystone. I will share our pattern with you... if you do me a favor.$b$bMy father fell to the drogbar several years ago, and they took his hammer as a trophy. That hammer was in my family for countless generations. Now, it languishes in the hands of the vile drogbar, Kubrul.$b$bI would very much like to have it back.', `QuestDescription`) WHERE `ID` = 38519;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tayla\'s Rescue - Reward', `LogTitle`) WHERE `ID` = 38521;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Not Just Weapons and Armor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft 4 Hard Leystone Bars and 24 Hard Leystone Nails.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You know, we aren\'t just limited to armorsmithing and weaponsmithing. I regularly make chisels for the scribes, crucibles for the alchemists, and even thimbles for the tailors.$b$bThey should sew in full plate gauntlets if they\'re really all that worried about their poor little thumbs.$b$bAnyhow, I have a recipe I think an adventurer like you might be interested in. Let\'s try it out.', `QuestDescription`) WHERE `ID` = 38522;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leystone Hoofplates', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Approach Mei Francis in Dalaran while mounted to have your Leystone Hoofplates fitted.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here, bring these hoofplates to Mei Francis, down at the mounts and pets store, to get your mount properly shod.$b$bI\'ll share the pattern when you return.', `QuestDescription`) WHERE `ID` = 38523;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felsmith Nal\'ryssa', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Felsmith Nal\'ryssa in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Word has been circulating in smithing circles about a pair of Illidari blacksmiths that have been doing exciting work out on the demon-infested front lines of Suramar. I\'d follow up myself, but anything described as "demon-infested" is a little too exotic for my tastes.$b$bI just make the armor. I prefer not to wear it.$b$bYou, though... you could follow up on this tip. Be on the lookout for Nal\'ryssa. From what I hear, she\'s a hell of a smith.', `QuestDescription`) WHERE `ID` = 38524;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Part of the Team', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa demons within Felsoul Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'re a blacksmith?$b$b<The elf looks down at your hammer.>$b$bStill working in leystone, are you? I might be able to help you out.$b$bAlliances out here are hard-won. You\'ve got a pretty face, but that\'s no guarantee that you aren\'t working for the demons. I can\'t afford to trust you yet.$b$bDon\'t come back until you\'re caked in demon\'s blood. Then we\'ll talk smithing.', `QuestDescription`) WHERE `ID` = 38525;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Smith Under Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Felsmith Nal\'ryssa\'s instructions to craft Leystone Boots.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You lack recipes for boots?$b$bWhat, were you trained by a tauren or something?$b$bHurry up, then. We probably have a few minutes before the demons attack again. Here\'s a pattern - show me your work.', `QuestDescription`) WHERE `ID` = 38526;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nal\'ryssa\'s Technique', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 60 Leystone Ore and 60 Felslate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Listen, $c. We need smiths like you to carry on the traditions of the Illidari, should we fail in our crusade against the Legion. You are ready to learn.$b$bBring me materials. Lots of them. When you return, we will have much to discuss.', `QuestDescription`) WHERE `ID` = 38527;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leystone\'s Potential', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Felsmith Nal\'ryssa\'s technique to craft a set of Masterwork Leystone Armguards.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As I\'m sure you\'ve deduced, all of the leystone recipes you know can be improved.$b$bBy learning to harness leystone\'s true potential, you can reduce the amount of material you use and still yield an equivalent result. Here, I\'ll show you.$b$bWe\'ll start, as one does, with the humble bracer. This particular piece of armor benefits from the addition of brimstone runes. See for yourself.', `QuestDescription`) WHERE `ID` = 38528;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Stormheim - Treasure 023 - Weeping Bluffs - ZTO', `LogTitle`) WHERE `ID` = 38529;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Firmament Stone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Barm Stonebreaker in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When working with felslate and demonsteel, one must use special equipment. Specifically, an anvil hard enough to withstand the energy given off when felslate is hammered.$b$bUrael and I no longer possess such an anvil. But your friends, the Highmountain tauren, do.$b$bGain access to the Firmament Stone, their sacred anvil, and we can start working with demonsteel again.', `QuestDescription`) WHERE `ID` = 38530;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leystone Mastery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Thala Steeltotem to purchase a Leystone Armor Stand, then hang all eight pieces of Leystone Armor on it.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Smiths that seek access to the Firmament Stone must first prove complete mastery over leystone.$b$bCraft an entire set of Leystone Armor, then submit it to me for inspection. Thala can provide you with an armor stand.', `QuestDescription`) WHERE `ID` = 38531;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maw of Souls: Hammered By The Storm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Maw of Souls and recover an Ancient Vrykul Hammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your hammer looks weak, and would probably break upon striking the Firmament Stone.$b$bThe vrykul master blacksmiths of old were known for the strength of their hammers. The only way to get our hands on such a hammer would be to go where vrykul go when they die. To the Maw of Souls.$b$bThe goddess that resides over that realm is named Helya. She hoards the trinkets they bring for her own desires.$b$bDefeat her and you may be able to acquire such a hammer.', `QuestDescription`) WHERE `ID` = 38532;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tribal Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report back to Felsmith Nal\'ryssa in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'First, however, you\'ll need proper patterns for demonsteel armor. While access to the stone is earned through hard work and perseverance, access to our recipes is limited to the trusted members of our tribe.$b$bPerhaps you should seek another smith if you wish to discuss demonsteel patterns.', `QuestDescription`) WHERE `ID` = 38533;
