UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lord Hal\'shara\'s Tomb', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raid the tomb.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The tomb, I\'ve found it.', `QuestDescription`) WHERE `ID` = 38552;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Invasion Point: Devastation', `LogTitle`) WHERE `ID` = 38557;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'See Ya Later, Oscillator', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Crystal Oscillator.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Those jawless mooks are actually trying to salvage parts from our ship! They can\'t possibly appreciate superior gnomish technology... Perhaps its shiny nature is appealing to their simple inclinations.$B$BIn any case, I need a crystal oscillator for our new transponder. It\'s the shiniest part of the whole system, they\'re bound to have it set aside somewhere!', `QuestDescription`) WHERE `ID` = 38558;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Worthy of the Stone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Muirn Ironhorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have nothing more to prove to me, $n. Your training is complete.$b$bOnly a very small herd of smiths have earned the right to the Firmament Stone. You should speak with Muirn Ironhorn, who maintains vigil over our sacred stone. He will tell you what to do next.', `QuestDescription`) WHERE `ID` = 38559;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Garrison Campaign: The Bane of the Bleeding Hollow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect tracking maps to find the location of the killer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, now that we\'ve had time to get scouts all over the jungle we have heard some news near Zeth\'Gol.nnIt appears that somebody else has a vendetta against the Bleeding Hollow and has been... hunting... them. Their hunters are closing in on the assassin.nnYou know what they say about "the enemy of my enemy..." We should collect their tracking maps and try to find the killer first!', `QuestDescription`) WHERE `ID` = 38560;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Garrison Campaign: The Warlock', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the warlock at Lion\'s Watch in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, you have a visitor. One of Gul\'dan\'s warlocks just walked up to the base and surrendered. He says he has information of a terrible event that is about to occur.nnI suggest you speak with him immediately.', `QuestDescription`) WHERE `ID` = 38561;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secrets of the Sargerei', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate and stop the source of corruption underneath Auchindoun.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Auchenai have been reporting for some time that something was... wrong... with Auchindoun since Teron\'gor\'s original assault. Now suddenly the Sargerei attacked and blew open a hole into one of the underhalls.nnCorruption leaks from that breach. We must investigate!', `QuestDescription`) WHERE `ID` = 38562;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Flower-Pickers and Potion-Quaffers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Linzy Blackbolt and Kuhuine Tenderstride to secure a work order for Foxflower Flux.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we know the foxflower flux is safe to use, we can start stocking it. That being said, I don\'t particularly feel like picking flowers. Do you feel like picking flowers? Didn\'t think so.$b$bGo talk to the alchemists and herbalists across the way. I\'m sure we can set up some sort of work order arrangement.', `QuestDescription`) WHERE `ID` = 38563;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Sweet Bargain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find a frost mage in Dalaran to chill your quenching trough.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Reading over this research, I found an interesting method that I\'d like you to try.$b$bThe method would require us to chill the metal to sub-freezing temperatures during the pre-tempering phase. Simple water quenching won\'t do.$b$bGood thing you can\'t walk two steps in this city without bumping into a frost mage! See if you can recruit one for the shop, $n.', `QuestDescription`) WHERE `ID` = 38564;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Sargerei Menace', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Sargerei.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This attack surprised our defenders. Forces are marshalling to push them out, but it will take some time for them to arrive.nnAny Sargerei you can slay will make retaking this area much easier commander.', `QuestDescription`) WHERE `ID` = 38565;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A United Force', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Establish the Order of the Silver Hand using the Libram of Ancient Kings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The paladins of Azeroth must stand united behind a single leader. With Tirion\'s passing, you are the one most worthy to wear the mantle of Highlord.$B$BIf you agree to accept this duty, inscribe your name into the Libram of Ancient Kings and I will address the masses on your behalf.$B$BThe Order of the Silver Hand is reborn, with you as its champion!', `QuestDescription`) WHERE `ID` = 38566;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Garrison Campaign: War Council', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Warchief Vol\'jin inside the Town Hall of your garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your garrison is in an uproar. Warchief Vol\'jin himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle.$b$bThe Warchief is ready for you inside your Town Hall. It would be wise not to keep him waiting...', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'The Warchief awaits.', `PortraitGiverText`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Warchief Vol\'jin inside the Town Hall of your garrison.', `QuestCompletionLog`) WHERE `ID` = 38567;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Need a Shipwright', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Iron Docks and speak with Sammy Fivefingers. Your Garrison Flight Master can provide transport.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Whatever be left of da Iron Horde be fallin\' back ta Tanaan Jungle, where Gul\'dan is turnin\' them into sumthun\' even worse. A frontal assault be suicide.$b$bBut da seas be open. If we attack by both land an\' sea, Gul\'dan got ta fall back somewhere. $n, it be time ta build a shipyard!$b$bWe need local resources. Go to da Iron Docks. Gazlowe\'s boys are already there. Gather any equipment ya find, and see if ya can recruit us a proper Horde Shipwright!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Travel to the Iron Docks and speak with Sammy Fivefingers. Your Garrison Flight Master can provide transport.', `QuestCompletionLog`) WHERE `ID` = 38568;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clearing the Docks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Iron Horde orcs and $2oa ogron.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need to get control of this situation. We thought these docks would be all but abandoned. Instead, Gul\'dan has ordered the Iron Horde to retreat to Tanaan, and many are using this harbor to make their getaway.$b$bWe need to clear a path for your salvage team. Lay waste to them! Every foe we slay here is one less convert for Gul\'dan\'s wretched demon-worshipping army.', `QuestDescription`) WHERE `ID` = 38569;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Derailment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Explosive Charges and a Detonator.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Some orcs have spoken out against Gul\'dan, and they\'ve been taken prisoner. One of them is what you\'d call an engineering prodigy: Solog Roark, "The Iron Shipwright." This guy\'s good. Designed all these docks, as well as the big dreadnaughts you fought around Shattrath.$b$bIf my scouts are right, he\'s in a prison train as we speak... And I betcha he\'d be willing to defect!$b$bGather up some explosives and meet Durotan next to the train to the south.', `QuestDescription`) WHERE `ID` = 38570;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Train Gang', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the detonator to blow open the prison train, and convince Roark to join your cause.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My warriors will surround and cover the train car. Hit the detonator to blow open the doors.$b$bI will speak to Roark and convince him to defect to our cause. He built all of this - he\'s our best hope for building a shipyard of our own.$b$bIf this doesn\'t work, execute him on the spot. The last thing we need is someone rebuilding the Iron Fleet.', `QuestDescription`) WHERE `ID` = 38571;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hook, Line, and... Sink Him!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use a Blackrock Grapple to reach Knar\'s bunker. Slay him to obtain Roark\'s Shipyard Blueprints.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can build you a shipyard. And not some wasteful piece of over-engineering like this place.$b$bBut I\'m going to need my blueprints. My work was confiscated when Gul\'dan turned this harbor over to Admiral Knar.$b$b<Roark spits.>$b$bGul\'dan\'s green poison courses through Knar\'s veins. He\'s calling the shots from on high. We\'ll need to grapple up there to take him out.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Admiral Knar', `PortraitGiverName`) WHERE `ID` = 38572;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nothing Remains', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report back to Vol\'jin at your garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Nothing is left for me here. My old clanmates have turned into foes, and Gul\'dan is desecrating what remains of my people.$b$bYou and your Frostwolf allies still have some fight left. If you pledge to depose Gul\'dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor!$b$bLet your people know I am coming.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Report to Vol\'jin at your garrison.', `QuestCompletionLog`) WHERE `ID` = 38573;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'All Hands on Deck', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Construct a Level 1 Shipyard for your garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Let\'s put dis "Iron Shipwright" ta work, commander. If we ta take Tanaan from both land an\' sea, we gonna need a shipyard. Work wit\' Roark an\' make it happen!$b$bHe be surveyin\' tha land along tha road west of Frostwall.', `QuestDescription`) WHERE `ID` = 38574;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Meet at Light\'s Hope', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Join the other paladins at Light\'s Hope Sanctum beneath Light\'s Hope Chapel in Eastern Plaguelands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With you on our side, I know the Legion will fall! But before we march on the Broken Isles, we must put Highlord Tirion to rest.$B$BThere is but one place suitable for a paladin of his caliber... Light\'s Hope Sanctum, a secret bastion of the Light hidden beneath our chapel.$B$BPaladins the world over are on their way to the ceremony. I know Tirion would want you there most of all.', `QuestDescription`) WHERE `ID` = 38576;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Battle for the West', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Iron Front and speak with Durotan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our base is barely built and already the Iron Horde sets up defenses against us. Still the plan worked and we fight on two fronts.$b$bI have received word that Durotan has finally breached the western gates as well, but is bogged down in a pitched battle. You should go see the situation for yourself.', `QuestDescription`) WHERE `ID` = 38577;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Message of Terrible Import', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Vault of the Earth and speak with Lagar the Wise.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your scout... he got me out of that hellish place. Fel orcs surprised us out in the jungle and dragged us up the mountain. They tortured us... killed all but me. I fear one of us may have given up our secret before the end.$b$bI must ask you to go to the home of our order. Speak with Lagar, my leader, tell him... tell him Gul\'dan knows.', `QuestDescription`) WHERE `ID` = 38578;
