UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Battle for the West', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Iron Front and speak with Exarch Maladaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our base is barely built and already the Iron Horde sets up defenses against us. Still the plan worked and we fight on two fronts.$b$bI have received word that Exarch Maladaar has finally breached the western gates as well, but is bogged down in a pitched battle. You should go see the situation for yourself.', `QuestDescription`) WHERE `ID` = 38581;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Old Friends', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 50 Corrupted Creatures in Moonrest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I sense a powerful dark presence here, $n, but it is not of Xavius. This feels too familiar.$B$BI sense a druid\'s touch here, a druid twisted by the shadow of the Nightmare.$B$BWe must deal with this threat if we are to find Xavius. I will take to the skies and lend you my aid.$B$BFind this corrupted druid and cut down his tainted and twisted plants.', `QuestDescription`) WHERE `ID` = 38582;
