UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on the Throne of Kil\'jaeden', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Shadow Council at the Throne of Kil\'jaeden in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil\'jaeden. Make no mistake; This is the most dangerous region in Tanaan.nnGather together a war party and assault the Throne of Kil\'jaeden before the Legion gains a foothold here!', `QuestDescription`) WHERE `ID` = 38585;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on the Throne of Kil\'jaeden', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Shadow Council at the Throne of Kil\'jaeden in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil\'jaeden. Make no mistake; This is the most dangerous region in Tanaan.nnGather together a war party and assault the Throne of Kil\'jaeden before the Legion gains a foothold here!', `QuestDescription`) WHERE `ID` = 38586;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on the Throne of Kil\'jaeden', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Shadow Council forces at the Throne of Kil\'jaeden in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil\'jaeden. Remember the first war, we know the destruction the legion can cause if they are unchecked.nnHead to the Throne of Kil\'jaeden and let\'s put an end to this invasion before it can begin.', `QuestDescription`) WHERE `ID` = 38587;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on the Throne of Kil\'jaeden', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault the Shadow Council forces at the Throne of Kil\'jaeden in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Shadow Council are summoning their demonic masters upon a mountain they are calling the Throne of Kil\'jaeden. We know the destruction the legion can cause if they are left unchecked.nnHead to the Throne of Kil\'jaeden and let\'s put an end to this invasion before it can begin.', `QuestDescription`) WHERE `ID` = 38588;
