UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Malfurion\'s Fury', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Ysera to search for Malfurion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The loss of Cenarius to the nightmare is a devastating blow to us all.$b$bThough Malfurion\'s rage is justified, his hatred of Xavius has burned for centuries and I fear that his blind rage will be used as a weapon against him.$b$bMay Elune guide us in our search for him, lest we have yet another friend to mourn today.', `QuestDescription`) WHERE `ID` = 38595;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'TRACKING Nightmare 02', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Botanist Darkgrove', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '(PH)nDarkgrove has run out of places to hide. Now it is time to finish him off.$B$BIf we stop him now, there may be hope for this valley yet.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Ysera', `QuestCompletionLog`) WHERE `ID` = 38596;
