UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Infrastructure Improvements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place $1oa G-X3 Telemetry Beacons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$G Sir : Ma\'am;, we built a vehicle to take ya up to the Throne of Kil\'jaeden but whenever we try a test flight the navigation system goes crazy!$b$bIn my expert opinion it\'s \'cause of that crazy demon magic the Iron Horde is playing around with up there.nnIf you could travel up there and place these telemetry beacons we can program the vehicle and give you a stable flight all the way up.nnJust be sure to have some friends with you, the demons up there look especially vicious!', `QuestDescription`) WHERE `ID` = 38599;
