UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Setting the Signal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place $1oa Pentangulate-o-tron 2000s.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$G Sir : Ma\'am;, we built a vehicle to bypass the Horde camp and take you to the Throne of Kil\'jaeden! There\'s one problem, the concentrated fel energy up there is causing the navigation system to go haywire!nnI\'ll need you to place some sensors along the edge of the summit. With them in place we can stabilize the flight controls.nnJust be sure to have some friends with you, the demons up there look especially vicious!', `QuestDescription`) WHERE `ID` = 38603;
