UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Burning Importance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Save yourself by completing a Timewalking Dungeon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Champion, you would not believe the horrors I have seen. The timeline is twisting and your fate is dire. Causality bends at its very knees, and in this dire future you kneel to the Betrayer himself, Illidan Stormrage. Venture into the past and save yourself, but beware - your powers are as they were then.', `QuestDescription`) WHERE `ID` = 38633;
