UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Temple of Elune', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lyanis Moonfall at the Temple of Elune.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Cenarius is in danger.$b$bIf his condition is not reversed soon, he will be lost to the Nightmare that threatens the Emerald Dream. To spare him that fate, we must have the Tears of Elune - the same relic you were sent here to retrieve.$b$bElune\'s temple is not far. Go there. Find Lyanis. Show her my seal and instruct her to release the tears into your custody.$b$bHurry, $n. Time is short.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Lyanis Moonfall at the Temple of Elune.', `QuestCompletionLog`) WHERE `ID` = 38641;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vrykul Longboat', `LogTitle`) WHERE `ID` = 38642;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Village in Peril', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Mayor Heathrow at Bradensbrook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The corpse of Darcy Heathrow lies before you pierced by several arrows and knife wounds.$b$bIn one hand she clutches a note, written with a feeble hand, that reads:$b$b"The dead march on Bradensbrook.$b$bHelp us, please!"', `QuestDescription`) WHERE `ID` = 38643;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Farmsteads', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Check on the Heathrow house, Granny Marl\'s farm, and the Radcliffes\' fishing dock.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Forgive us, stranger. Mayor Heathrow has been under a lot of stress recently.$B$BI can\'t blame him: his own daughter, Penelope, has been missing for two days.$B$BIn fact, we could use information on several farmsteads to the south: Mayor Heathrow\'s house, Granny Marl\'s farm, and the Radcliffes\' dock. Can you go check on the situation out there?$B$BHelp us, and perhaps the mayor\'s heart will soften.', `QuestDescription`) WHERE `ID` = 38644;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Children of the Night', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Risen Assassins, Black Rook Falcons, or Risen Hounds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I am no enemy to these people, but there is no convincing them of that.$B$BTheir village has come under attack by some very old friends of mine. Friends who are no longer... living.$B$BThere\'s no telling who or what controls them, but in life these noble soldiers would never engage in such acts. That\'s a mystery for another time.$B$BFor now, help me earn the trust of these villagers. Strike down the Black Rook enemies who are terrorizing their citizens.', `QuestDescription`) WHERE `ID` = 38645;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Sight For Sore Eyes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Granny\'s Flare Gun to mark 6 Black Rook Falcons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you see those ravenous birds flying above my farm? Vicious creatures are spreading their filth an\' eatin\' my crops.$B$BI\'d get rid of them with my trusty gun, but my eyesight\'s gone downhill.$B$BTake this flare gun and mark them for me.$B$BOnce I get my sights on them, I\'ll make \'em scatter.', `QuestDescription`) WHERE `ID` = 38646;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'For the Corn!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 5 Barrels of Corn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve got a full summer\'s corn harvest just sittin\' out in the field. I need some muscle to bring it in before the night elf raiders can destroy it.$B$BGet out there and bring me those crops, and I\'ll reward you handsomely.$B$BThe folks back in town need this food, and I sure as heck ain\'t eating rats for another winter.', `QuestDescription`) WHERE `ID` = 38647;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Orders', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Commander Jarod Shadowsong at Bradensbrook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The letter is written in midnight ink:$B$B"A demon invasion is imminent, but as long as the fires of Black Rook Hold blaze, we shall protect kaldorei lands. Kill any intruders who stand in our way."$B$B- K.R."$B$BPerhaps Jarod Shadowsong will want to see this.', `QuestDescription`) WHERE `ID` = 38648;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Silence in the City', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Chief Telemancer Oculeth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is a troubling silence from Suramar City this day.$b$bOculeth just informed me that the teleporter to the Waning Crescent has gone dark. He is not able to reach Vanthir, nor am I.$b$bWhile I am hesitant to believe something dire has happened, I do feel this warrants investigation.$b$bSpeak with Oculeth and see if he can transport you to the Waning Crescent. We need to find out what happened.', `QuestDescription`) WHERE `ID` = 38649;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Giant Raptor', `LogTitle`) WHERE `ID` = 38654;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Root Cause', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Corrupted Root Samples.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The massive roots of Shaladrassil are spreading a horrible corruption throughout the forest.$b$bIf we are to save Val\'sharah, we will need to find a way to stop the encroachment of the world tree.$b$bIf you bring me enough corrupted root samples, I may be able to discover their secrets.', `QuestDescription`) WHERE `ID` = 38655;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mark of the Demon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return the Demonic Emblem to Isoraen Nightstar at the Temple of Elune.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demonic rune glows in your hand, emanating dark power. A single word, inscribed in demon tongue, glows coldly... $b$b...GRAVAX...', `QuestDescription`) WHERE `ID` = 38656;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure: Swamp Sword', `LogTitle`) WHERE `ID` = 38657;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tears for Fears', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Tears of Elune.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tears of Elune are a sacred artifact, protected by my order for thousands of years. I tell you this so that you may understand the gravity of your request.$b$bThat said, Ysera is noble and wise and I trust in her guidance. You will find the tears in a vault at the eastern edge of the temple grounds.$b$bProceed with caution though, as that area has been overrun by demons.', `QuestDescription`) WHERE `ID` = 38662;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Die is Cast', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Ysera at the Grove of Cenarius.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thanks to your efforts the temple is safe, for now.$b$bBut the Tears of Elune are stolen and Shaladrassil, the world tree that once protected this land, is now an instrument in the hands of our enemy. The Emerald Dream itself is being overrun by Nightmare.$b$bThe hearts of our people falter, their faith tested like never before. Return to Ysera with my report, $n, such as it is.$b$bI shall plead with Elune with what time I have left here. May we somehow yet prevail.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Ysera at the Grove of Cenarius.', `QuestCompletionLog`) WHERE `ID` = 38663;
