UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Our Last Hope', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Maiev Shadowsong in the Illidari Cellblock.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your jailor, Maiev Shadowsong, stands outside the open door to your cell. The leader of the Wardens has just finished removing your bonds.nnIn the distance, you can hear sounds of battle. The unmistakable stench of the Burning Legion wafts through the air.', `QuestDescription`) WHERE `ID` = 38668;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Our Last Hope', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve your new warglaives.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Vault has fallen to the Burning Legion.nnIt pains me to say it, but all is lost, but for one glimmer of hope... YOU. Believe me when I say, I did NOT want to have to do this. However, it would seem I have no choice.nnHelp me, demon hunter, and I will grant you your freedom.', `QuestDescription`) WHERE `ID` = 38669;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Goredome 2', `LogTitle`) WHERE `ID` = 38670;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lost in Retreat', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve 5 Shadowfen Heirlooms in Shadowfen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Is this the end?$b$bOur beloved Malfurion. I saw him in the Dreamer\'s clutches, but Ysera was... changed. Twisted.$b$bShaladrassil, our mighty world tree, is corrupted beyond recognition.$b$bWe were forced to flee our home without our belongings. Some were heirlooms, sacred to us. Return them to me if you can, $c, I beg you.', `QuestDescription`) WHERE `ID` = 38671;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Breaking Out', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free both Altruis the Sufferer and Kayn Sunfury.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We cannot fight our way out of the Vault alone.nnTwo of your allies, Kayn Sunfury and Altruis the Sufferer, are imprisoned within this room. nnFree them with haste. Their strength will be of great use to us.', `QuestDescription`) WHERE `ID` = 38672;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Heart of the Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Track Malfurion\'s path through the Nightmare.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know only that my husband is somewhere deeper in this twisted forest.$b$bHe is still alive, but it remains to be seen if he is whole.$b$b<Tyrande\'s expression hardens into a scowl as she peers at you.>$b$bElune herself cannot protect Xavius if he is not.', `QuestDescription`) WHERE `ID` = 38675;
