UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Reading the Leaves', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Corrupted Petals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, my friend. You must succeed where I have failed. You must find our dear Malfurion.$b$bAs the Nightmare consumes my thoughts, I hear the voices of these twisted trees. I must cling to sanity long enough to aid you.$b$bVenture into Ash\'theran and bring me Corrupted Petals from the fallen denizens there.$b$bWith them, I might find your Archdruid while my mind is still my own.', `QuestDescription`) WHERE `ID` = 38684;
