UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Close Enough to Touch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search for Malfurion within Shala\'nir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'He is near, $n, I can feel it.$b$bWe must scour this place in search of my husband. I fear if we do not find him soon it will be too late.$b$bYou have been courageous throughout our search. I know you will not fail me now, $n.$b$bThank you, and please hurry.', `QuestDescription`) WHERE `ID` = 38687;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel Infusion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infuse yourself with 100 energy from fallen demons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So many years of imprisonment has left us weak.nnThe Vault is overrun with demons.  Kill them and gather their souls to regain your strength.', `QuestDescription`) WHERE `ID` = 38689;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise of the Illidari', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free 8 Illidari Prisoners.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Look down there. We are vastly outnumbered.nnWe will need more allies on our side if we are to escape from here intact. Free the other Illidari imprisoned within the cells of this chamber.nnWe will need everyone to escape this place alive.', `QuestDescription`) WHERE `ID` = 38690;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Jarod\'s Mission', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Jarod Shadowsong at Ravencrest Mausoleum.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Since Maiev chased after Gul\'dan at the Vault of the Wardens, her sisters among the Wardens have been searching far and wide for her whereabouts.$B$BWith so few Wardens remaining, I volunteered to join the search. I hope I will find sign of her within Black Rook Hold.$B$BThe fortress will be well guarded, and I will need help to break through. Help me find her, and I will reward you handsomely.', `QuestDescription`) WHERE `ID` = 38691;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Answering Aggression', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 12 of Elisande\'s Forces in the Waning Crescent, Starcaller Retreat, and Siren\'s Vigil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I weep for the Nightborne this day.$b$b<Silgryn gestures out the door.>$b$bElisande demonstrates the ultimate disdain for her people. So many lives... wasted!$b$bAll to relay a message: This is what happens to those who defy her.$b$b$n, my friend, we must answer her. We must show her that she cannot slay her people without retribution.$b$bFight back, $n.', `QuestDescription`) WHERE `ID` = 38692;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Regroup', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escape Siren\'s Vigil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These people may be able to hold out here, but I know for certain that we cannot.$b$bEvery moment we spend here places them in danger of Elisande\'s forces retaliating against us.$b$bWe need to move. We need to find a place to regroup and recover.$b$bFollow me. I think I know how we can get out of here.', `QuestDescription`) WHERE `ID` = 38694;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crackdown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the events of the Waning Crescent.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thalyssra is right to be concerned!$b$bThe network has not responded to my attempts to re-establish connection with the Waning Crescent. I do not know what happened, but given the circumstances I believe it prudent to investigate in person.$b$b$n, would you do the honors? I will send you as close to the Waning Crescent as I can.', `QuestDescription`) WHERE `ID` = 38695;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Bleeding Hollow Horror', `LogTitle`) WHERE `ID` = 38696;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Sword of Truth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place Fal\'shathil on the ground, then defeat Black Rook night elves within its holy light.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lord Ravencrest\'s army rises from the dead, but I believe they are controlled by Gul\'dan\'s will.$B$BTake this - Lord Ravencrest\'s blade, Fal\'shathil. It was known for a unique, magical quality. Those who gazed upon its mirrored blade found themselves unable to deny the truth.$B$BTake the blade and plant it in the ground. Attack the night elven ghosts near its light. Once they are weakened in its presence, perhaps they will regain their senses.', `QuestDescription`) WHERE `ID` = 38697;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Competitive Exorcise', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 15 Burning Legion invaders in 10 minutes or less.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Think you\'re good at sending demons back to the hell from whence they came? Show me!nnI once bagged 15 in under 10 minutes. Do better than that and there\'ll be brew money waitin\' for ya.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Sedona Ironshot', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Sedona Ironshot', `PortraitTurnInName`) WHERE `ID` = 38699;
