UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Urgent Gathering', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather Travard and Orik Trueheart, then meet Lord Maxwell Tyrosus at Krasus\' Landing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A critical decision must be made, $n.$B$BThe Legion devastated our forces at the Broken Shore. The mightiest army this world has ever known was reduced to cinders in moments.$B$BWe must gather those with the conviction to save our home. Travard of Tyr\'s Guard and Orik Trueheart have each made plans to do just that, but we must not let them walk alone.$B$BI ask that you seek them out and guide them to Krasus\' Landing so that we may make this decision together.', `QuestDescription`) WHERE `ID` = 38710;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Warden\'s Signet', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Warden\'s Signet to Jarod Shadowsong.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The night elf was carrying a signet engraved with the crest of the Wardens.$B$BThe band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner\'s finger.', `QuestDescription`) WHERE `ID` = 38711;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Houndmaster Ely', `LogTitle`) WHERE `ID` = 38712;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maiev\'s Trail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the forge, the saber pens, and the guard tower.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The fortress grounds are just up ahead. There is a large area to search, but if we split up, I believe we can cover a lot of ground.$B$BSearch the prison cages, the forge, and the guard tower for any signs of Maiev. I will check the upper ramparts and meet you on the other side of the keep.', `QuestDescription`) WHERE `ID` = 38714;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Rook\'s Guard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Kester Farseeker, Trelan Shieldbreaker, and Starlys Strongbow.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Black Rook Hold is not the same place I knew. Its walls have crumbled, a ghostly echo of its former glory.$B$BIf Lord Ravencrest has returned, then surely he will have his former officers at his side.$B$BKester Farseeker, captain of the guard.$B$BTrelan Shieldbreaker, peerless master of maces.$B$BStarlys Strongbow, who could split arrows while blindfolded.$B$BIf we stand any chance of entering the tower itself, they must be eliminated.', `QuestDescription`) WHERE `ID` = 38715;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Hold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Warden\'s Signet to Jarod Shadowsong.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Inside the chest, hidden amongst various knickknacks, is a signet engraved with a unique crest.$B$BThe band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner\'s finger.', `QuestDescription`) WHERE `ID` = 38716;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Prison', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Araxxas and collect the Prison Keys.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I did not come this far to lose her in the final moments.$B$BMaiev must be in the cells beneath Black Rook Hold.$B$BI scouted above, and the entrance to the prison is guarded by a fearsome jailor.$B$BI will sneak past and take out the guards inside. Defeat Araxxas, take the keys, and then meet me within.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'He holds the master key.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Araxxas', `PortraitGiverName`) WHERE `ID` = 38717;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Kur\'talos Ravencrest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Examine Ravencrest\'s Sigil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lord Ravencrest was a fearless leader, a seasoned commander, a man of integrity and honor, a teacher, and a protector of his people.$B$BMalfurion, Illidan, Tyrande, and I... we were still young when he helped shape our destinies.$B$BThe sigil of his house was legendary. Observe, for a moment, the sigil over his former resting place and I shall tell you more of his legacy.', `QuestDescription`) WHERE `ID` = 38718;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Illidari Freedom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free Sirius Ebonwing, Cassiel Nightthorn, and Asha Ravensong.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The Illidari demon hunter is bleeding from several ghastly wounds. It appears he was left here to die.>$B$BWithin the prison are three of my... <cough>... comrades.$B$BWe were taken by surprise while scouting the area.$B$BI am not long for this world, but please, save them.', `QuestDescription`) WHERE `ID` = 38719;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'No Reason to Stay', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Evacuate survivors in the Waning Crescent and Siren\'s Vigil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Elisande\'s purge of the Waning Crescent came so swiftly that few could react. Many of my people are dead or taken.$b$bSome may have endured this atrocity. We need to make sure they are not left behind.$b$bI need you to search the houses nearby for any survivors. See that they flee before they are discovered. Reassure them that there is no reason to stay. $b$bNot here, not while Elisande\'s insanity reigns.', `QuestDescription`) WHERE `ID` = 38720;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lieutenant of the Tower', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Desdel Stareye.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All of your instincts were correct. Gul\'dan raised Lord Ravencrest, and his ghostly army, from beyond the grave. Now, they serve the Legion, protecting secrets within the tower.$B$BAlthough Ravencrest commands from above, Lieutenant Desdel Stareye operates the prisons.$B$BHe tormented me these past few moons, but I did not yield.$B$B<Maiev runs a finger along her curved blade.>$B$BHis life must be ended.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Second-in-command to Lord Ravencrest.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Lieutenant Desdel Stareye', `PortraitGiverName`) WHERE `ID` = 38721;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stop Gul\'dan!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Vault of the Betrayer, kill Crusher and Sledge, and take their fel power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'After his defeat at the Black Temple, we brought Illidan\'s lifeless body here, to be interred forever within the Vault of the Wardens.nnGul\'dan has found his way through our defenses and is trying to steal the Betrayer\'s corpse.nnEven in death, Illidan\'s body can be used by the Burning Legion. Gul\'dan CANNOT succeed.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Stop him if you can.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Gul\'dan', `PortraitGiverName`) WHERE `ID` = 38723;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Brotherly Love', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Maiev Shadowsong in Black Rook Prison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Maiev will be somewhere in the prison. I found her discarded armor on my way here.nnLet\'s split up to search the cells more quickly.$B$BWe must find her.', `QuestDescription`) WHERE `ID` = 38724;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into the Foul Creche', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet up with Kor\'vas Bloodthorn at the Foul Creche.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One of the demons that I interrogated revealed a particularly juicy bit of information. Apparently, there\'s an imp mother in the volcano that scribes Legion secrets.nnKor\'vas has gone out to find that demon and bring those secrets back for us.', `QuestDescription`) WHERE `ID` = 38725;
