UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stop the Bombardment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Legion Devastators.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Jace\'s wards are not going to hold out much longer. We need someone to go out there and make sure those Legion devastators are destroyed.nn<Kayn pointedly looks at you with his spectrally-enhanced vision.>', `QuestDescription`) WHERE `ID` = 38727;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Keystone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Brood Queen Tyranna and take the Sargerite Keystone. Then, join the others down-below in the portal chamber.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Brood Queen Tyranna is just ahead in the command chamber. The others already charged in. She has the Sargerite Keystone in her possession.nnFinally, the object of all our sacrifice is at hand.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Take the Sargerite Keystone from her corpse!', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Brood Queen Tyranna', `PortraitGiverName`) WHERE `ID` = 38728;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Black Temple', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Sargerite Keystone to activate the Fel Portal and return to the Black Temple.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Quickly, $n, use the Sargerite Keystone.nnWe must get back to the Black Temple before it is too late!', `QuestDescription`) WHERE `ID` = 38729;
