UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fate of Val\'sharah', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defend the Temple of Elune.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Malfurion, my love.... My heart breaks for him, but I cannot follow where he goes.$b$bI have sworn myself to Elune, my goddess, to defend her temples and lands with all that I am. I cannot stand by while my order is in danger.$b$bMay she keep you in her graces, Malfurion.$b$b<Tyrande turns away, eyes glistening with tears.>', `QuestDescription`) WHERE `ID` = 38743;
