UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Demon\'s Trail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Malfurion Stormrage.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Malfurion is nearby. I can sense him..$b$bSearch the summit of Andu\'talah while I continue to scour the forest.$b$bBe swift, $n. Time is of the essence!', `QuestDescription`) WHERE `ID` = 38753;
