UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Set Them Free', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Several of your demon hunters are in trouble. Get the Soulwrought Key to set them free.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Cyana went down to the Molten Shore. She was going to help some of the demon hunters who came in through the gateway ahead of us. Instead, she got herself into trouble.nnThis inquisitor revealed they\'re being held prisoner by some new type of demon called a \'jailer\'. The thing sucks the souls out of its victims. I doubt they can hold out much longer.', `QuestDescription`) WHERE `ID` = 38759;
