UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Enter the Illidari: Shivarra', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Feed a powerful soul into the Legion Gateway Activator and then use it to summon in your Shivarra forces.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our Shivarra demonesses are waiting at the Black Temple. It\'s a gamble bringing them here... they used to be part of the Burning Legion after all. But, they are some of the most powerful in Lord Illidan\'s arsenal.nn<Jace looks at you for a long moment.>nnI have a feeling that the ultimate sacrifice is going to have to be made in order to summon them in.', `QuestDescription`) WHERE `ID` = 38765;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Before We\'re Overrun', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Doom Commander Beliash and take his power for your own.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The doomguard commander and his queen must be dealt with. His eredar are summoning in a huge number of reinforcements.nnWe need to put an end to him before the Legion overruns our new foothold up in the volcano!nnAs an added benefit, you can steal his demonic power.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'This is the Legion leader in the lowlands below the volcano. Take his power for youself.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Doom Commander Beliash', `PortraitGiverName`) WHERE `ID` = 38766;
