UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leystone Deposit Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Leystone Deposit Sample to Mama Diggs in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This ore looks like nothing you\'ve seen before.$b$bA mystical sheen moves through the metal in complex, unpredictable patterns. Your trainer in Dalaran would certainly like to see this.', `QuestDescription`) WHERE `ID` = 38777;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Turn the Keys', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the Runestones within the Runewood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My roots wither... my branches die...nnThe Bonespeakers, they seek to silence the Runewood.  The runestones are the key...nnTurn the stones... release my bonds...', `QuestDescription`) WHERE `ID` = 38778;
