UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leystone Seam Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Leystone Seam Sample to Mama Diggs in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This ore has clearly absorbed some of the latent ley energies within the Broken Isles. It is cool to the touch, and reflects light in odd, playful angles.$b$bYour trainer in Dalaran should analyze this.', `QuestDescription`) WHERE `ID` = 38784;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Living Leystone Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Living Leystone Sample to Mama Diggs in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is no normal leystone. It is much livelier, shimmering in complex, enthralling patterns. It is easy to stare at.$b$bYour trainer in Dalaran would certainly like to have a look at this.', `QuestDescription`) WHERE `ID` = 38785;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where Respect is Due', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mine for leystone $1oa times while using Ronos\'s Glass Pick.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Leystone is a sensitive ore. Our smiths can coax great power out of it, but as miners, we must treat it with respect, or else its power will retreat inward.$b$b<The tauren hands you what appears to be a GLASS mining pick.>$b$bThe next time you mine some leystone ore, use this pick. It will break if you strike too hard. THIS is the respect that leystone requires.', `QuestDescription`) WHERE `ID` = 38786;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Legend of Rethu Ironhorn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Ronos Ironhorn to learn the tale of Rethu Ironhorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A long, long time ago, a tauren by the name of Rethu entered this land. His exploits paved the road that all miners walk.$b$bIf you wish to learn more about mining, you must first learn about Rethu.', `QuestDescription`) WHERE `ID` = 38787;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure: Magic Brazier', `LogTitle`) WHERE `ID` = 38788;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rethu\'s Journal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Torn Journal Page to Ronos Ironhorn in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tucked in between a few pieces of rubble, a scrap of paper catches your eye.$b$bMining carefully, you uncover the tattered remains of an old scroll. The tauren handwriting is archaic, but one word catches your eye:$b$b"Rethu".', `QuestDescription`) WHERE `ID` = 38789;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rethu\'s Pick', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Battered Mining Pick to Ronos Ironhorn in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This seam has been mined before - it bears the telltale diagonal ruts of a miner\'s pick.$b$bLooking down, that pick now lays on the ground - handle broken, pick-point dulled with use and years.$b$bCarved into the haft is a familiar name:$b$b"Rethu"', `QuestDescription`) WHERE `ID` = 38790;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rethu\'s Horn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Chunk of Horn to Ronos Ironhorn in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The corpse of the rocky beast yielded an unusual treasure: a battered chunk of tauren\'s horn.$b$bIt is clearly very, very old, but something about its color and curve reminds you of Ronos Ironhorn at the Ironhorn Enclave.', `QuestDescription`) WHERE `ID` = 38791;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rethu\'s Lesson', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report your encounter to Ronos Ironhorn in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You... miner... let me see your pick a moment.$b$b<The tauren spirit eyes your mining equipment.>$b$bYou remind me of myself, when I once walked this land. Savor these moments, miner. They cannot last forever.$b$b<With a bow, the spirit disappears.>', `QuestDescription`) WHERE `ID` = 38792;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rethu\'s Experience', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report your encounter to Ronos Ironhorn in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Miner... you... you know who I am?$b$bI see. That is good. My tribe continues to honor its roots.$b$bIf you return to the land of the Ironhorn tribe... let them know that they are looked upon with pride.', `QuestDescription`) WHERE `ID` = 38793;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rethu\'s Sacrifice', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report your encounter to Ronos Ironhorn in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Miner... speak with me a moment. I haven\'t much time in this place.$b$bI see you fight for your ore. I believe that is the most noble way to obtain your stone. It gives the land a fighting chance.$b$bStill, one mustn\'t be callous with their own life. Dig too deep, and the land will overcome you. No stone is worth the price I paid.$b$bBut that is a tale for another day...', `QuestDescription`) WHERE `ID` = 38794;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felslate Deposit Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Felslate Deposit Sample to Mama Diggs in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is one nasty-looking stone.$b$bYour trainer in Dalaran should see this.', `QuestDescription`) WHERE `ID` = 38795;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felslate Seam Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Felslate Seam Sample to Mama Diggs in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This ore is remarkably heavy. More disturbingly, it seems to darken and hiss at your touch.$b$bPerhaps your mining trainer in Dalaran has some insights.', `QuestDescription`) WHERE `ID` = 38796;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Living Felslate Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Living Felslate Sample to Mama Diggs in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your miner\'s instinct is kicking in. Chunks of the infernal\'s corpse appear to be usable.$b$bStill, there must be a way to extract more ore from the demon\'s body. Perhaps your mining trainer in Dalaran will know how.', `QuestDescription`) WHERE `ID` = 38797;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Shred of Your Humanity', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Allow Felsmith Nal\'ryssa to place three shards of felslate in your body.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To mine for felslate is to seek the very blood of demons. To improve at it, you must become part demon yourself.$b$bWhy the dirty look? You said it yourself: you\'re willing to make sacrifices.$b$bLuckily for you, I\'m an expert in this area. I won\'t put you in any danger, as long as you trust me.$b$bAre you ready?', `QuestDescription`) WHERE `ID` = 38798;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkheart Thicket: Nal\'ryssa\'s Sisters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Darkheart Thicket and find Lyrelle\'s Signet Ring.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was not the only miner in my family. I was the youngest of four sisters.$b$bI say "was" because the other three are gone.$b$bTwo of them went too far. They overloaded their bodies with felslate and succumbed to the will of Sargeras. They are more demon than elf, now.$b$bThe third, I have not heard from in quite some time. The last I heard, she was investigating the Darkheart Thicket.$b$bI fear she may have fallen, too - one way or the other.', `QuestDescription`) WHERE `ID` = 38799;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rin\'thissa\'s Eye', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Ore-Bound Eye to Felsmith Nal\'ryssa in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oddly enveloped within the felslate deposit is a humanoid eye.$b$bIt quivers with life. You get the sense that it would blink at you if it had an eyelid.$b$bA mining expert should take a look at this.', `QuestDescription`) WHERE `ID` = 38800;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lyrelle\'s Right Arm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Severed Arm to Felsmith Nal\'ryssa in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You blink and rub your eyes, but they do not deceive you. This is a woman\'s arm, completely enveloped within a felslate seam.$b$bThe arm is bloodless, but still twitches. Fel-colored streaks remain where veins once were.$b$bFelsmith Nal\'ryssa will certainly want to see this.', `QuestDescription`) WHERE `ID` = 38801;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ondri\'s Still-Beating Heart', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Ore-Choked Heart to Felsmith Nal\'ryssa in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What at first looked like another chunk of felslate is, in fact, a humanoid heart, encrusted in rock and filled not with blood but a vile, demonic substance.$b$bIt does not appear to belong to the beast you carved it out of... it seems that the infernal was holding it like a keepsake. Luckily your mining pick didn\'t hit it straight on.$b$bFelsmith Nal\'ryssa will want to see this.', `QuestDescription`) WHERE `ID` = 38802;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rin\'thissa', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Summon and defeat Rin\'thissa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My sister Nal\'ryssa has her claws in you, doesn\'t she?$b$bThat weakling doesn\'t know the first thing about mining. She was always too afraid to take the leap. True knowledge comes only from the Great One, the God of Fel and Flame.$b$bYou want to truly learn how to mine? Come to Suramar\'s northwestern corner, and speak my name:$b$bRin\'thissa.', `QuestDescription`) WHERE `ID` = 38803;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lyrelle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Summon and defeat Lyrelle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Look at you, miner. Still held back by the limitations of your fragile, decaying flesh.$b$bTo truly become one with the demon-tinged rocks of these lands, you must shed your skin and submit to a darker power.$b$bJoin us, miner. Bring your feeble body to Felsoul Hold, and speak my name:$b$bLyrelle.', `QuestDescription`) WHERE `ID` = 38804;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ondri', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Summon and defeat Ondri.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You are nothing compared to me. You think yourself hardened, experienced... heroic, even. Hah!$b$bYou have no idea what I\'ve been through. The tortures I\'ve endured, the sacrifices I\'ve made. All for the sake of my trade!$b$bYes, I\'m a miner, just like you. Want to learn what I have to teach? Come to the Crimson Thicket in Suramar, and speak my name:$b$bOndri.', `QuestDescription`) WHERE `ID` = 38805;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Infernal Brimstone Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Infernal Brimstone Sample to Mama Diggs in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This ore. Smells. Horrible. It combines the odor of sulfur with all the worst parts of a rotting corpse.$b$bSomeone will probably want it for something.$b$bMaybe your mining trainer in Dalaran will take it off of your hands.', `QuestDescription`) WHERE `ID` = 38806;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Infernal Brimstone Analysis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the reports from Mama Diggs\' apprentices in Icecrown, Deepholm and Twilight Highlands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to mine Infernal Brimstone, we first need to understand the way in which ore comes into being. I currently have three of my apprentices doing research on different ores around the world.$b$bFind Forinn Stoneheart in Deepholm, Rhol Landers in Twilight Highlands and Krul Rockhorn in Icecrown and collect any information they\'ve gathered on the ore at those locations.', `QuestDescription`) WHERE `ID` = 38807;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bjornharta', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Engorged Bear Hearts from Voracious Bears in the Runewood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The afterlife leaves the dead hungry for the delicacies of their former lives. For the vrykul kings, none such offering is prized more than Bjornharta - a celebratory feast of an engorged bear heart. nnThe bears of the Runewood eat well, and have long been prized for their tender meat. Hunt them and find a suitable heart of offer to the ancient rulers. They will not be able to resist such an offering.', `QuestDescription`) WHERE `ID` = 38808;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure: Mushroom Barrel', `LogTitle`) WHERE `ID` = 38809;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dreaming Fungus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Soulcaps in the Runewood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So an outsider would seek to be judged by the ancient rulers of the vrykul? Curious, this. Know that they will not take to your presence kindly, stranger.nnIf you are so hasty to meet judgment, you can call them forth with a ritual of wakening. To complete this ritual, you will require an aromatic to burn and an offering to present.nnA plant grows in the Runewood that will make a suitable incense. Gather it, and I will instruct you further.', `QuestDescription`) WHERE `ID` = 38810;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Judgment Day', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Receive judgment from the ancient vrykul rulers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have proven resourceful thus far, stranger. As promised, I will instruct you on the ritual of wakening.nnFirst, you must place the offering directly atop the grave of the ruler you wish to awaken. Burn the incense so that its aroma wafts over the grave. If your offering is adequate, the ruler will rise, and you may ask your judgment.nnTake care, outsider. The dead vrykul kings will not enjoy being awakened from their slumber.', `QuestDescription`) WHERE `ID` = 38811;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Shadowthrash', `LogTitle`) WHERE `ID` = 38812;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Orders for Your Captains', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Brief your Illidari captains on where to attack the Burning Legion within the volcano.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All that is left is to deliver your orders to our Illidari captains. The mightiest of the Legion\'s forces have arrayed themselves within the volcano. But, they will not remain on the defensive for long.nnWe must strike first and we must strike hard.nnOnce we destroy them, we can fly up to the command ship, defeat Brood Queen Tyranna, and take the keystone for our own. Lord Illidan will be pleased.', `QuestDescription`) WHERE `ID` = 38813;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure: Mystical Staff', `LogTitle`) WHERE `ID` = 38814;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Waking the Shieldmaiden', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Rune of Reformation to return Ashildir\'s spirit to her bones.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the rituals disrupted and her bones returned, we may be able to wrest Ashildir from the grasp of these Bonespeakers.nnDeeper within Haustvald, the mystics possess a special altar that can reunite the body and spirit of a fallen warrior. With this, we may be able to return Ashildir\'s spirit into her bones, and out of the grasp of these foul mystics.nnGo outsider, I will rally her guard.', `QuestDescription`) WHERE `ID` = 38815;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Breaking the Bonespeakers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 15 Bonespeaker vrykul or their allies in Haustvald.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The crimes of these ritualists must not go unpunished, but we cannot be their executioners. The rune magic they practice grants them untold power over the dead.nnYou, however, are not dead, and I can sense great power from you. Take the fight to these heretics, and show Ashildir that you are truly worthy of her judgment!', `QuestDescription`) WHERE `ID` = 38816;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Regal Remains', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Ashildir\'s Bones in Haustvald.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So you seek the judgment of the queen of the Valkyra? This must be your fault!nnThe Bonespeakers of Haustvald have committed an atrocity and stolen Ashildir\'s bones. They must have done this to keep an outsider from completing the trials. You must not let this stand!nnEnter Haustvald and retrieve her remains. I hope, for your sake, that Ashildir is in a forgiving mood.', `QuestDescription`) WHERE `ID` = 38817;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Final Judgment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Runeseer Faljar in Haustvald.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In my fragmented state, I captured glimpses of a hero meting out justice to the corrupted mystics of Haustvald. I see now, this hero was you, $c. nnI know you seek my judgment, but my spirit is still fragmented. As we speak,  Runeseer Faljar is calling upon dark, forbidden magics in an attempt to banish my spirit to Helheim. If he succeeds, your trial will be lost.nnMy connection here is fading. Go, there is little time!', `QuestDescription`) WHERE `ID` = 38818;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Their Numbers Are Legion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Wage war upon the Brood Queen\'s Court and the Burning Legion within the greater Inferno Peak area.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Yes, those devastators must be silenced, but there\'s also a great deal more to be done.nnDespite the odds, we\'re counting on you. The Brood Queen\'s primary leaders are in control of the volcano. They must be killed. We must smash the Legion and do anything else necessary to achieve absolute victory.', `QuestDescription`) WHERE `ID` = 38819;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Captain Grok\'mar', `LogTitle`) WHERE `ID` = 38820;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure: The Commander\'s Shield', `LogTitle`) WHERE `ID` = 38821;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure: Arcane Wand', `LogTitle`) WHERE `ID` = 38822;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Runes that Bind', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Ritual Stones to stop the rituals binding Ashildir\'s spirit in Haustvald.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The stone tablet here describes a ritual where a powerful spirit can be broken into weaker pieces by binding them to special runestones. It looks like the Bonespeakers may be using this very ritual to weaken the spirit of Ashildir.nnIt may be impossible to summon her with her spirit so weakened. The rituals must be stopped.', `QuestDescription`) WHERE `ID` = 38823;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blazing Crusader', `LogTitle`) WHERE `ID` = 38825;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Art of Demonsteel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Work with Muirn Ironhorn to craft a Demonsteel Bar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Firmament Stone is one of the few anvils beneath the sky that can tolerate the hammer strikes necessary to craft demonsteel.$b$bHere, I will show you.$b$bTwo parts leystone, one part felslate. No heat, no tempering, just pure strength and finesse.$b$bTry it. I will coach you.', `QuestDescription`) WHERE `ID` = 38833;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into the Fray', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the lead demon hunter at Illidari Stand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely.nnCome, let\'s put that weapon of yours to use. I\'ll figure out our next move while you crush the Legion.', `QuestDescription`) WHERE `ID` = 38834;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aktar\'s Post', `LogTitle`) WHERE `ID` = 38836;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Mordvigbjorn', `LogTitle`) WHERE `ID` = 38837;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Enraged Earthservant', `LogTitle`) WHERE `ID` = 38838;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Done with Waiting', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the southern cliffs of Val\'sharah and speak to Makra Knifewhisper.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mom got a message and said blood called for blood. She told me to wait here while she went out, but it\'s been two weeks since then. I\'m tired of waiting.$B$BI\'ll stay home if you go find her. She said she was going to the cliffs far to the south.', `QuestDescription`) WHERE `ID` = 38839;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fishy Business', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 3 Murktide Wavecallers on the southern coast of Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Makrura are massing down by the shore, and far too many of them seem to practice water magic.$B$BI think once they\'ve got enough spellcasters, they\'re planning to summon a massive wave.', `QuestDescription`) WHERE `ID` = 38840;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Die, Fish-People', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Intact Murktide Tails to Makra Knifewhisper on the southern cliffs of Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Makrura are massing down by the shore, and far too many of them seem to practice water magic. I think they\'re planning to summon a massive wave.$B$BAlso, I\'ve come a long way, and I\'m out of supplies. I\'m so hungry, I could eat almost anything. Even the makrura you kill. Just cut the heads off first.', `QuestDescription`) WHERE `ID` = 38841;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Faerie Fracas', `LogTitle`) WHERE `ID` = 38842;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rally the Wilds Buff Received', `LogTitle`) WHERE `ID` = 38844;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unused', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Oronok Torn-heart at Oronok\'s Farm in Shadowmoon Valley wants you to listen to his story. Speak to Oronok to begin hearing his story.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Oronok adjusts his posture and stands to his full height.>$B$BI had to be sure, $n. And to be sure, I had to test you. Please excuse the little masquerade. I am as much a farmer as you are $g female:male;. Which is to say, not at all.$B$BIf you are to recover the Cipher of Damnation, you will need to listen to what I have to tell you. When you are ready, let me know and I will tell you the story.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'The Cipher of Damnation - History and Truth', `AreaDescription`) WHERE `ID` = 38845;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Berserker', `LogTitle`) WHERE `ID` = 38847;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fate of Tirion Fordring', `LogTitle`) WHERE `ID` = 38850;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Favor for Mr. Shackle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free Cleave Thunderhill, Gentle Rosh, and Grace the Green.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Throm\'ka, $c. My name is Seska. I represent a... trading company. As you can see, I\'ve fallen victim to these giants and their naga allies.nnThree of my associates were also captured while surveying this cove. I\'m certain that my employer, Mr. Shackle, would be most grateful if you could procure their release.', `QuestDescription`) WHERE `ID` = 38857;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Val\'sharah - Treasure 019 - Lunarwing Shallows - twh', `LogTitle`) WHERE `ID` = 38861;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thieving Thistleleaf', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Stolen Lunarwing Eggs in the Lunarwing Shallows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Why the Thistleleaf are collecting the Lunarwing eggs is anyone\'s guess, but you can be sure it\'s not to give them a loving home.$b$bSaylanna Riverbreeze will know what to do with these.', `QuestDescription`) WHERE `ID` = 38862;
