UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Highmountain Tauren', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Ronos Ironhorn in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ye\'ve brought me a bit of interesting rocks to look at, $n. I\'ve got a special assignment for ye, if ye\'re up for it.$b$bI hear stories about these tauren, up in Highmountain, who claim mastery over minin\'. I don\'t know if they\'re as talented as you or me, but they\'ve been minin\' leystone longer.$b$bPay \'em a visit. See what they have to say.', `QuestDescription`) WHERE `ID` = 38888;
