UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Not Dead Yet!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Nitro-Electric Jumpstarter to resurrect 5 Gadgetzan Bruisers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'They\'re not dead yet! A little nitro here, a jolt of electricity there... we can bring \'em back! And then, they can pay me! Whaddya say, $n? Wanna go into business with me?', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Nurse Heartwrench', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Nurse Heartwrench', `PortraitTurnInName`) WHERE `ID` = 38890;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scouting Report', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Goblin Intel from any Steamwheedle Scout in Tanaris.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We were supposed to meet back here, and then sneak back to Gatgetzan. That was hours ago, $n! The others fanned out across all of Tanaris to gather intel.nnAnything you can find will help in the defense of Gadgetzan. Keep your eyes open, $n!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Clink Fleetfoot', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Clink Fleetfoot', `PortraitTurnInName`) WHERE `ID` = 38892;
