UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tearing down the Legion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 15 Legion Invaders while piloting a vehicle during a Tanaris invasion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A piece of paper is tacked to the controls. On it is a tally of demons slain by the previous pilot.nnYour ego demands satisfaciton.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Aircraft Dashboard', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Aircraft Dashboard', `PortraitTurnInName`) WHERE `ID` = 38896;
