UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Felsmiths', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Felsmith Nal\'ryssa in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ye have a knack with this felslate, $glad:lass;. Best ship ye off to someone who knows the stuff better than I.$b$bThe Illidari have a knack with all things demonic, really, and I\'ve heard about a few miners who\'ve set up shop out near the demons in Suramar.$b$bPay \'em a visit. See what they have to teach ye.', `QuestDescription`) WHERE `ID` = 38901;
