UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Broken Shore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take Saurfang\'s spare mount to the Broken Shore and fight alongside him to restore your honor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Fear not, $n. I\'m angry, but I don\'t chase my own death.$b$bWe will fly in and scout the ideal point of attack. The demons are still drunk on their victory, but we will put a swift end to their revelry!$b$bTake my spare mount and we will fly to the Broken Shore. There we will bring honor to our dead.', `QuestDescription`) WHERE `ID` = 38904;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keepers of the Hammer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Mayla Highmountain at Thunder Totem in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Highmountain Tribes had intended to pledge our allegiance to your forces. We know war has come with the Burning Legion.$b$bHowever, we have been betrayed from within and must now ask for your aid.$b$bA great relic, the Hammer of Khaz\'goroth, was stolen from our people by the vile drogbar.$b$bWe need your help in recovering it.', `QuestDescription`) WHERE `ID` = 38907;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Get to High Ground', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Jale Rivermane to Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is no accident that Dargrul attacked the Rivermane in force. It is their farms and their pastures that supply food for the region.$b$bPlease, get Jale to Thunder Totem. With luck, Mayla will have reinforcements to send to the area.$b$bWe will rally the survivors here and follow as quickly as we can.', `QuestDescription`) WHERE `ID` = 38909;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rocs vs Eagles', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Save $1oa Captive Great Eagles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'High Crawliac has taught her witches how to curse our beloved eagles into the vile rocs you see assaulting the valley.$b$bThere is no way to break this curse once it has taken hold.$b$bWe will take to the skies and do battle with the rocs, but we need your help on the ground.$b$bHead north through Darkfeather Valley and release any eagles that you find.$b$bEvery eagle you save is one less roc we must kill later.', `QuestDescription`) WHERE `ID` = 38910;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Rivermane Tribe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Jale Rivermane at Earthmother\'s Bounty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What has happened here requires more time than I have to explain. In short, our tribes have scattered in the wake of the attack that left the Hammer of Khaz\'goroth in the hands of the barbaric drogbar.nnEven now the drogbar are raiding the Rivermane tribe, and I have too few braves left to send to their aid. nnWe need a hero. Please, go to Earthmother\'s Bounty and lend what aid you can.', `QuestDescription`) WHERE `ID` = 38911;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Bloodtotem Tribe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Oakin Ironbull at Cliff\'s Edge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bloodtotem are led by Torok, a volatile but useful tauren chieftain. He is wary of outsiders, but I believe you have already met an emissary to their tribe--Oakin Ironbull--whom you rescued at Riverbend.nnUse that small thread and you may be able to bring the Bloodtotem back into the fold. Highmountain needs them if we are to defeat the drogbar and reclaim the Hammer of Khaz\'goroth. Be on your guard, $n.', `QuestDescription`) WHERE `ID` = 38912;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Skyhorn Tribe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Lasan Skyhorn at Skyhorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Skyhorn people are some of the greatest pathfinders and hunters this world has ever known.$b$bThey are a proud people, but should be willing to listen to reason.$b$bIf the roads feel unsafe, you may ask any flight master in Highmountain to fly you there.$b$bPlease, $p, go to their leader Lasan and remind him that only together, we are Highmountain.', `QuestDescription`) WHERE `ID` = 38913;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle of Snowblind Mesa', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Journey to Snowblind Mesa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your timing is fortunate. Our forces at Snowblind Mesa report seeing the Underking above ground.$b$bWhat is more, he is lightly guarded, and has the hammer with him. Thanks to your efforts, we can meet them in battle.$b$bMeet us at Snowblind Mesa and let us take the fight to Dargrul together.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Mayla Highmountain at Snowblind Mesa.', `QuestCompletionLog`) WHERE `ID` = 38915;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secrets of Highmountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Spiritwalker Ebonhorn at the southern bluff of Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mayla\'s father, Ulan, was our last high chieftain. He was slain trying to stop the Underking from seizing the Hammer of Khaz\'goroth.$b$bI have watched Mayla all her life and can tell you she has both the courage and the strength to wear the mantle of High Chieftain.$b$bShe needs only our help to realize it herself.$b$bWill you meet us at the city entrance along the southern bluff? There is a ritual that might help, but we will need your aid to survive it.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Spiritwalker Ebonhorn at the southern bluff of Thunder Totem.', `QuestCompletionLog`) WHERE `ID` = 38916;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Littlefur', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Littlefur at Smolderhide Thicket.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Stranger, I beseech you! My once peaceful brethren are now cursed with insatiable wrath.$B$BMy nephew and I tried to leave against the Chieftain\'s wishes. The clan wrested him from me, and would have torn me apart if I did not flee.$B$BHe is trapped in the village, and I fear the worst.$B$BGreat $c, please save him. I am too old and too weak to do it myself.', `QuestDescription`) WHERE `ID` = 38922;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ashran Dominance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the enemy faction at the event locations in Ashran and slay their leader within their base.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Grand Marshal Tremblade leads the Alliance forces in Ashran.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Grand Marshal Tremblade', `PortraitGiverName`) WHERE `ID` = 38923;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Continue the Domination', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Alliance at the event locations in Ashran and kill Grand Marshal Tremblade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Grand Marshal Tremblade leads the Alliance forces in Ashran.', `PortraitGiverText`) WHERE `ID` = 38924;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Continue the Domination', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won\'t put up with their aggression.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Volrath leads the Horde forces in Ashran.', `PortraitGiverText`) WHERE `ID` = 38926;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle Hardened', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Win 3 Rated Battleground matches.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Defeat your opponents on the battlefield and you will be rewarded.', `QuestDescription`) WHERE `ID` = 38927;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle Hardened', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Win 3 Rated Battleground matches.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Defeat your opponents on the battlefield and you will be rewarded.', `QuestDescription`) WHERE `ID` = 38929;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Equipment Blueprint: Bilge Pump', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return the blueprints to a Naval Equipment Specialist at your garrison shipyard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This appears to be a blueprint for some sort of naval equipment.  We should take it back to our Shipyard and see if someone can decipher it.', `QuestDescription`) WHERE `ID` = 38932;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Logistical Matters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Lord Grayson Shadowbreaker.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I think we are ready to... reintroduce ourselves to the Legion on the Broken Isles.$B$BLord Grayson Shadowbreaker has volunteered to help coordinate our forces on the ground. You should speak with him immediately, Highlord.', `QuestDescription`) WHERE `ID` = 38933;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Silas\' Secret Stash', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Silas\' Secret Stash.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A great Darkmoon prize do you now seek, but be ye warned, it is not for the meek.nnYour very first clue to send you on this caper, you will find printed on the back of this paper.', `QuestDescription`) WHERE `ID` = 38934;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'His Name Was... Stormstout', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The land is ripe with rumors of an unusual pandaren monk whose power was matched only for his appetite for brew.$b$bHe was traveling with his young niece who\'s mouth seems to get them into a lot of trouble.$b$bThe locals say these two were headed to the Valley of the Four Winds. You should meet him! Just... watch out for that right hook.', `QuestDescription`) WHERE `ID` = 38935;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Road to Kun-Lai', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel through the Veiled Stair to Binan Village.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lorewalker Cho has sent word that several of your companions survived the conflict in the Jade Forest and have been moved to Kun-Lai Summit to seek healing.$b$bThey need your help if they are to survive!$b$bTo reach Kun-Lai Summit, travel to the Valley of Four Winds and look for the High Road Grummle that can be found at the base of the Veiled Stair along the North-western border.$b$bThey can guide you the rest of the way.', `QuestDescription`) WHERE `ID` = 38936;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unused - Wraith Zapper', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Zap 7 Wraiths near the haunted manor on the hill in western Bradensbrook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I came here to exorcise the manor. Unfortunately it\'s haunted by a wizard, and he\'s summoned quite a few wraiths to bolster his power.$B$BI\'m no match for them, but perhaps you are. My gun can harvest the wraiths\' ectoplasmic energy. Then we can turn it against him.$B$BBy my estimates, you\'ll need to zap 7 wraiths before the gun is fully charged. Here, take it.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Wilhelmina Eckrdige in Bradensbrook.', `QuestCompletionLog`) WHERE `ID` = 38937;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unbearable', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the Shivering Ashmaw Cub in southern Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Not far away, a bear cub looks to be in some distress. Perhaps you should investigate?', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Investigate Shivering Ashmaw Cub', `AreaDescription`) WHERE `ID` = 38938;
