UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sew It Begins', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Shal\'dorei Silk. You can find Shal\'dorei Silk on humanoids within the Broken Isles, obtain some from a fellow adventurer, or you may visit the Auction House and buy some.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Every time Dalaran takes us to a new shore, I get anxious over what types of fabric and cloth we might find below.$b$bThreads imbued with magic? Something demonically-tinged?$b$bUgh, I hope it\'s not FURS again.$b$bYou\'re an adventurer... and tailor to boot. Head on down there and see what you can scrounge up!', `QuestDescription`) WHERE `ID` = 38944;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'This Should Be Simple... Right?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a Handcrafted Silkweave Robe on Tanithria\'s Finishing Bench. You can find the pattern in your tailoring pattern list. You can find the materials for the pattern in her shop.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have plenty of silk patterns that we can put this cloth to work on.$b$bHelp me to prepare the materials, $n. We\'re going to put this cloth to good use and make you a new robe.', `QuestDescription`) WHERE `ID` = 38945;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Consult the Locals', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find a tailor in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Whoever wove this fabric CAN\'T have intended it only for belts and shoulderpads. There must be some way to sew thread into this material.$b$bHead on down to Azsuna and try to find a tailor. We need to sew if we\'re going to do any real tailoring.', `QuestDescription`) WHERE `ID` = 38946;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Runic Catgut', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa pieces of Runic Catgut.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Let me guess... thread troubles? Mm-hm.$bI suspected as much. My people weave sumptuous silks, but those silks can be fickle about the types of thread they\'ll accept.$b$bShal\'dorei silk has a bit of ley energy woven right into it. You need something that\'s learned to coexist with the ley energies of this land.$b$bI\'m talking about owlcats, my good friend! They have what you need. You\'ll find them amongst the ruins of Llothien.', `QuestDescription`) WHERE `ID` = 38947;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hard Times', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Stained Silken Robe and a set of Hatecoil Wristwraps.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When I worked at the tailoring guild in Suramar, I would usually work off of a pattern. Something that inspired me.$b$bUnfortunately, I\'ve run into streak of bad luck, and I\'m ashamed to say that I no longer have my patterns.$b$bThe naga sorceresses in the lagoon to the west, however, have expertly-sewn wristwraps. And the nightfallen to the north wear robes that we can use... if you can pry one from their greedy clutches.', `QuestDescription`) WHERE `ID` = 38948;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'So You Think You Can Sew', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a Rune-Threaded Silkweave Robe and a set of Rune-Threaded Silkweave Bracers at Lyndras\' Finishing Table. You can find the patterns in your tailoring pattern list.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Very good, I think we\'re ready to begin.$b$b<Lyndras steals a glance at your powerful weapon. A look of hunger washes over his face before he shakes it off and continues.>$b$bLet\'s prepare our materials and make the robe and bracers that you so rightfully deserve!', `QuestDescription`) WHERE `ID` = 38949;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wayward Tailor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Lalla Brightweave in Dalaran, and ask her to summon Lyndras.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Might I ask a favor, $n?$b$bAs I am recently without a home, shop, family, or friends, I was wondering if you might show me your floating city? I must admit, I am VERY curious about the place. I\'ve also heard good things about their tailoring shop.$b$bI have no way of getting there myself, but certainly such a magical city has SOMEONE who can summon me.$b$b<Lyndras looks at you with hopeful apprehension.>', `QuestDescription`) WHERE `ID` = 38950;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Needle Need', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Spritethorns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This shop has almost everything we need. Unfortunately, the quality of your sewing needles is lacking.$b$bI do know where you can get better needles. The sprites of Val\'sharah are covered with spines which, fortuitously, are perfect for the type of sewing we need.$b$bI hate to be such a prickler stickler, but these needles really will make a difference.', `QuestDescription`) WHERE `ID` = 38951;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Meticulous Precision', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Spritethorns to Tiffany Cartier in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The needles are sharp, but look at them closely. Some have a curve to them, others have a spur hanging off the side. Look at this one... it\'s got a ninety-degree crook in it! I have no desire to sew around a corner.$b$bTiffany Cartier in the jewelcrafting shop has a good eye for this sort of thing. Bring these needles to her, and she\'ll straighten them out.', `QuestDescription`) WHERE `ID` = 38952;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Advanced Needlework', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Make an Embroidered Silkweave Robe on Tanithria\'s Finishing Bench. You will need to gather the materials in her shop.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve already learned the patterns for bracers, belts, epaulets, and of course, robes. Unfortunately, your technique was wasteful... you need a better method.$b$bThat\'s where our needles come in.$b$bHere, I\'ll show you how to improve the process of these patterns.', `QuestDescription`) WHERE `ID` = 38953;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where\'s Lyndras?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Lyndras.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That\'s strange. Lyndras was here one moment, and then he ran off the next. He had such a strange look on his face.$b$bPerhaps we should track him down.', `QuestDescription`) WHERE `ID` = 38954;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sew Far, Sew Good', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a Silkweave Bag. You will need to gather materials inside the Dalaran tailoring shop.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your tailoring skill really is impressive and, although I don\'t have my patterns with me, I do have some patterns memorized. One of those patterns is for a simple bag.$b$bFollow my lead, $n.', `QuestDescription`) WHERE `ID` = 38955;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where\'s Lyndras Again?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Lyndras in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh dear.$b$bHe had just promised you that he wouldn\'t wander off, and then he did it again!$b$bI\'m starting to think that this Lyndras character might be a bit too impetuous for my tastes.$b$bPlease, go find him, before he gets into any more trouble.', `QuestDescription`) WHERE `ID` = 38956;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Taking Inspiration', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Runed Breeches.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I wish I had more patterns to share, but my notebook was lost along with my shop. We\'ll need to come up with some patterns on our own.$b$bI\'ve been thinking about the leather breeches that the Stormheim vrykul wear. They\'re certainly much thicker and heavier than anything we could sew, but their embellishing runework is quite impressive.$b$bIf I had a few pairs, perhaps I could re-imagine this runework on a more... refined garment.', `QuestDescription`) WHERE `ID` = 38957;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Right Color', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Helsquid Ink.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your assistance, $n, if you have a moment.$b$bI\'ve been attempting to reproduce a pattern for footwear that I spotted a while back, but I\'m having trouble getting the right color for my dye. Our black dye is too dark, our blue dye is too bright, and mixing the two doesn\'t look right.$b$bThe color I\'m looking for is more of a squid-ink blue. If, in your travels, you come across any dyes of this color, would you do me the favor of bringing some to me?', `QuestDescription`) WHERE `ID` = 38958;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Left Behind', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather Lyndras\' Pinking Shears, his Box of Measuring Tools and his Threading Needles from where you first met him in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I do truly want to help you work on your tailoring, but without my patterns or my supplies, there isn\'t much more I can do save for teaching you what little I remember.$b$bIf my memory still serves true, you\'re just missing a good pattern for some gloves and a hood.$b$bThe first thing I need you to do is grab a few things from where you first met me. Here\'s what I need...', `QuestDescription`) WHERE `ID` = 38959;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lining Them Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Bear Furs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Since you\'re heading to Azsuna, you may as well gather some lining for our projects.$b$bThe bears of Azsuna are known for how soft, yet durable their fur is.$b$bHunt them in the woods around Llothien and bring their fur back with you.', `QuestDescription`) WHERE `ID` = 38960;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: The Depraved Nightfallen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Eye of Azshara, defeat the Wrath of Azshara and recover the Heart of the Storm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to craft the gloves, we\'ll require a special item. This will be no easy task to recover it, $n.$b$bThe naga of Azsuna are said to be hard at work trying to summon a terrible creature into this world.$b$bThe creature\'s heart holds immense energy that we can use to channel into the gloves, making them incredibly powerful.$b$bI need... I mean, we need that heart if we are to produce a suitable pair of gloves for someone of your presence.', `QuestDescription`) WHERE `ID` = 38961;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Path to Suramar City', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist the nightfallen of Suramar until you discover a way to move safely amongst the elves of Suramar City.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I recall Lyndras mentioning a guild of tailors within Suramar City. Perhaps they could further our understanding of how to utilize this new cloth.$b$bUnfortunately from what I\'ve heard, they\'ve sided with the demons and anyone opposed to them is to be killed on sight.$b$bYou must find a way to move safely within the confines of their city if we\'re to continue our research.', `QuestDescription`) WHERE `ID` = 38962;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Final Lesson?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Create a Handcrafted Silkweave Hood on Tanithria\'s Finishing Bench. You will need to gather the materials in her shop.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have everything we need, let\'s work on the hood.$b$bAfter we\'re finished, we\'ll move onto the gloves.', `QuestDescription`) WHERE `ID` = 38963;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where\'s Lyndras Now?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go the alchemy shop across the street.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lyndras couldn\'t have gone very far. I mean, we\'re floating a thousand feet over the sea. $b$bI heard some commotion across the way this morning near the alchemy shop. I pray that wasn\'t Lyndras.$b$bCould you please go over there and make sure?', `QuestDescription`) WHERE `ID` = 38964;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on Violet Hold: Into the Hold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go into Violet Hold and find out what happened to Lyndras.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With Lyndras being locked up in Violet Hold, you feel responsible for him and must discover the truth behind his actions.$b$bPerhaps if you were able to speak with him, you could find a way to have him released from the hold and put back into your custody.$b$bGo into Violet Hold and find out what happened to Lyndras.', `QuestDescription`) WHERE `ID` = 38965;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secret Silkweaving Methods', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft some Masterwork Silkweave Bracers.$b$bYou will need to gather materials from the Dalaran tailoring shop and blacksmithing shop.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Okay, done mourning! Let\'s look through his stuff.$b$b<Tanithria takes a moment to leaf through Lyndras\' journal. Her eyes open wide.>$b$bOur friend has been keeping secrets from us. Look at this! Every single one of the recipes he\'s taught us can be improved.$b$bLet\'s start simple, with some bracers. I can supply most of the materials, but you\'ll have to talk to Alard Schmied in the blacksmithing shop to get this powdered brimstone.', `QuestDescription`) WHERE `ID` = 38966;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nightborne Connection', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Leyweaver Tytallo in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you\'re able to disguise yourself, you should go to Suramar City and try to find this guild of tailors.$b$bGood luck, $n, and try not to get caught.', `QuestDescription`) WHERE `ID` = 38967;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Proof of Loyalty', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa withered within Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Tytallo listens as you recount what happened with Lyndras.>$b$bI see. You sound almost... sympathetic to the wretch.$b$bThe nightfallen are liars and thieves. ALL of them. Lyndras included.$b$bI will not tolerate a student that has any respect or sympathy for those... things. And have you witnessed what they turn into at the depths of their depravity?$b$bIf you want to get on my good side, do not return until you are covered in the blood of the withered.', `QuestDescription`) WHERE `ID` = 38968;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Master of Silkweave', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Purchase a Shal\'dorei Mannequin from Leyweaver Mithrogane, then craft an entire set of silkweave armor and place them on the mannequin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While Tytallo is busy exacting withered genocide, it falls on me to take care of the more mundane aspects of training.$b$bWe\'re going to need to see how talented you are.$b$bCraft an entire set of silkweave armor for me. Leyweaver Mithrogane can provide you with a proper mannequin for displaying it.', `QuestDescription`) WHERE `ID` = 38969;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Queen\'s Grace Loom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Teleportation Crystal in the Leyweavers\' Hall, then speak with Leyweaver Azayna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Great power comes only with sacrifice. Even the most masterful tailor can only do so much with silkweave. To improve your patterns any further, bargains must be made.$b$bYou are prepared, $n, to learn about working with Imbued Silkweave.$b$bUse the teleportation crystal behind me, and speak with Azayna, the leader of our order.', `QuestDescription`) WHERE `ID` = 38970;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Exotic Textiles', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Fel Inscribed Shroud.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m risking my life and career to be here, tailor.$b$bI\'ve been curious about demonic cloth, and my attempts to obtain some through approved means have been met with resistance.$b$bI simply must see this cloth for myself.$b$bI don\'t wish to disrupt Azayna\'s pact with the demons, but you - you can attack the demons without drawing attention to our guild.$b$bI\'m particularly interested in a particular demon\'s set of robes. Bring me a scrap, and I\'ll teach you what I know.', `QuestDescription`) WHERE `ID` = 38971;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: The Right Question', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Hymdall in the Halls of Valor and recover his loincloth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One might ask what a leyweaver is doing standing over a dead vrykul\'s body. But such questions only stir up trouble.$b$bInstead let us ask what can be learned from those who have passed on. A question like that promotes progress.$b$bI assume you\'re here to learn from me, the pattern for Imbued Silkweave pants, yes?$b$bIf that\'s true, then I\'ll need something from one who has passed on. In the Halls of Valor the great guardian, Hymdall resides.$b$bBring me his loincloth and I will teach you my pattern.', `QuestDescription`) WHERE `ID` = 38974;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Inspire Me!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a Brown Linen Robe, a White Woolen Dress, a Simple Black Dress, a Frostwoven Robe, and a Spiritmend Robe while standing near Leyweaver Mithrogane.$b$bIf you do not know a pattern, you can learn it from tailoring trainers in major cities.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I am, and always will be, a student of robemaking and dressmaking. You can keep your gloves, belts, and cloaks. Nothing beats a good robe.$b$bI\'ll share my pattern for an imbued silkweave robe with you if you can teach me some of the robe and dress patterns you\'ve learned along your tailoring journey.', `QuestDescription`) WHERE `ID` = 38975;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG: Undying Silkweave Bracers Crafted', `LogTitle`) WHERE `ID` = 38976;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG: Undying Silkweave Cinch Crafted', `LogTitle`) WHERE `ID` = 38977;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG: Undying Silkweave Epaulets Crafted', `LogTitle`) WHERE `ID` = 38978;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG: Undying Silkweave Slippers Crafted', `LogTitle`) WHERE `ID` = 38979;
