UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG: Undying Silkweave Hood Crafted', `LogTitle`) WHERE `ID` = 38981;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG: Undying Silkweave Pantaloons Crafted', `LogTitle`) WHERE `ID` = 38982;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG: Undying Silkweave Robe Crafted', `LogTitle`) WHERE `ID` = 38983;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Your Orders, General?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Tanaan Planning Map in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'General, your forces in Tanaan Jungle await your orders. Travel to the Planning Map there to issue your commands.$b$bFor the Horde!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Go to the Tanaan Planning Map in Tanaan Jungle.', `QuestCompletionLog`) WHERE `ID` = 38989;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Call of Icecrown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your Death Gate ability to travel to Icecrown and obtain the Blades of the Fallen Prince.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<A powerful presence again touches your thoughts.>$b$bI have ordered your brethren to Icecrown to prepare for the coming conflict, but I have a more important fate in mind for you. You, $n, will be the hand of our vengeance!$b$bUse the Death Gate to return to Acherus and I shall reveal your role in this.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'The Lich King', `PortraitGiverName`) WHERE `ID` = 38990;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'First Mission Sent', `LogTitle`) WHERE `ID` = 38993;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'TRACKING Encounter Botanist', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Botanist Darkgrove', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '(PH)nDarkgrove has run out of places to hide. Now it is time to finish him off.$B$BIf we stop him now, there may be hope for this valley yet.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Ysera', `QuestCompletionLog`) WHERE `ID` = 38994;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unused', `LogTitle`) WHERE `ID` = 38995;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Your Orders, General?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Yrel at Lion\'s Stand in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Exarch Yrel has sent word from Lion\'s Watch in Tanaan Jungle that your forces stand ready for their new orders.$b$bFor the Alliance!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Yrel at Lion\'s Stand in Tanaan Jungle.', `QuestCompletionLog`) WHERE `ID` = 38996;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Don\'t Need No Library Card', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Tomes of Chaos from bosses in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If history is any indication, Gul\'dan is training a whole generation of warlocks to marshal against us. If we act fast, we can stem the tide and make things easier on ourselves.$b$bAs you and your fellow heroes venture into the depths of the Hellfire Citadel, seek out Tomes of Chaos from Gul\'dan\'s lieutenants.$b$bThey\'re dangerous, so don\'t read any of them. Not even the pictures.$b$b<Khadgar shudders.>$b$bESPECIALLY the pictures.', `QuestDescription`) WHERE `ID` = 39000;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cooking the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Gul\'dan\'s Library of Chaos to Cordana at Zangarra and ensure they are destroyed.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, we\'ve got to destroy these tomes. Many of them have actual tortured souls bound into the pages, so we can\'t just burn them. Cordana will know what to do.$b$bTake these books to my tower in Zangarra and give them to Cordana. Let me know when the deed is done.', `QuestDescription`) WHERE `ID` = 39003;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkness Incarnate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Hunt down and engage Gul\'dan within the Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have one final task before us, $n. We must defeat Gul\'dan and unravel his plans for this world.$b$bI have no reward to offer you - I have given you everything I can.$b$bCome. When you and your allies are ready, we march on Hellfire Citadel... and end this.', `QuestDescription`) WHERE `ID` = 39004;
