UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Invasion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 7 Black Rook Assassins in Bradensbrook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Once, this area was peaceful and prosperous. Then we saw the first bad omens: strange ailments, spoiled crops, and the like. Now ghosts attack us from that castle across the river, and undead assassins slay our fishers so as to cut off the village\'s food supply.$B$BWe\'re the last family living this close to the castle, but we daren\'t retreat: this river is the best route for fishers to bring their hauls in to town. Please, will you take the fight to these undead?', `QuestDescription`) WHERE `ID` = 39011;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grumpy', `LogTitle`) WHERE `ID` = 39015;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unused - The Fish Must Flow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 6 Stolen Fish from the Black Rook Assassins and Black Rook Lieutenants in Bradensbrook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our village is running low on food, and undead spies from Black Rook Hold have started targeting our fishers.$B$BIt\'s a surgical move, hitting our people and our food supply all at once.$B$BHelp us out and send those ghosts a message. Pare down their forces and bring back the food they\'ve stolen.', `QuestDescription`) WHERE `ID` = 39016;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise to the Occasion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Highlord Darion Mograine within Acherus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Lich King made a wise choice in giving you that weapon, $n.$b$bYou\'ve proven your strength and cunning on countless occasions and it is time that you have a position fitting for your accomplishments.', `QuestDescription`) WHERE `ID` = 39017;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Archmage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar at Khadgar\'s Tower in Zangarra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Khadgar has a very urgent favor to ask. He is gravely concerned about additional threats this world may hold for Azeroth, and he will need your assistance pursuing them. Please see him at his tower, east of Talador, in the Zangarra swamp.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Archmage Khadgar at Khadgar\'s Tower in Zangarra.', `QuestCompletionLog`) WHERE `ID` = 39018;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Archmage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar at Khadgar\'s Tower in Zangarra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Archmage Khadgar at Khadgar\'s Tower in Zangarra.', `QuestCompletionLog`) WHERE `ID` = 39019;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Burning Path Through Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 5 Timewalking dungeons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.', `QuestDescription`) WHERE `ID` = 39020;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Frozen Path Through Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 5 Timewalking dungeons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.', `QuestDescription`) WHERE `ID` = 39021;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Archmage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar at Khadgar\'s Tower in Zangarra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Archmage Khadgar at Khadgar\'s Tower in Zangarra.', `QuestCompletionLog`) WHERE `ID` = 39022;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Archmage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar at Khadgar\'s Tower in Zangarra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.$b$bThis will not take long.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Archmage Khadgar at Khadgar\'s Tower in Zangarra.', `QuestCompletionLog`) WHERE `ID` = 39023;
