UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grasp of the Underking', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue Jale Rivermane, Warbrave Oro, and Oakin Ironbull.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If we have one good fortune in this it is that Dargrul has no knowledge of how to use the hammer.$b$bHe keeps thinking of the hammer as a weapon instead of a tool of creation.$b$bEven so, he has imprisoned our tribesman in fists of stone summoned from the earth. Our weapons have proven useless against this magic.$b$bYou might have power enough to break these fists. Can you help?', `QuestDescription`) WHERE `ID` = 39025;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Drogbar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Drogbar in Riverbend.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It wasn\'t enough for Dargrul to just destroy this village. He has also sent his Stoneraiders to take what is left.$b$bPlease champion, prove to my people that you are the hero I foresaw.$b$bSlay enough of these Stoneraiders that it breaks their resolve.', `QuestDescription`) WHERE `ID` = 39026;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dargrul and the Hammer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Confront Dargrul the Underking.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are about to follow a drogbar into a cave, something we warn our children never to do.$b$bEven so, several of our warbraves have already followed Dargrul inside.$b$bCome, join us in battle and let us reclaim the Hammer of Khaz\'goroth.', `QuestDescription`) WHERE `ID` = 39027;
