UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Call to Battle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Win 4 Battleground matches.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.', `QuestDescription`) WHERE `ID` = 39040;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Arena Calls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Win 10 Arena Skirmish battles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This alignment of the stars is a dire sign, stirring bloodlust and calling warriors to battle to the death in close quarters. Arena masters turn a tidy profit during these days, likely not understanding why their stands are overflowing. Amidst the excitement, great rewards do await those brave, or foolhardy, enough to venture into the arena....', `QuestDescription`) WHERE `ID` = 39041;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bitestone Enclave', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay drogbar in the Bitestone Enclave.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is an old drogbar enclave that we used to trade with. Now it is a base of operations for their raids.$b$bI need more time to gather what is left of our warbraves. Go, enter the enclave, and slay any you find in there.$b$bBuy us the time we need to gather our strength.', `QuestDescription`) WHERE `ID` = 39043;
