UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Illidari', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Altruis the Sufferer at Krasus\' Landing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Altruis requests that you meet him at Krasus\' Landing at once.$B$B<Kor\'vas leans in close, her voice an urgent whisper.>$B$BYou must hurry. The Legion has eyes everywhere.', `QuestDescription`) WHERE `ID` = 39047;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Demolitionist', `LogTitle`) WHERE `ID` = 39048;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye On the Prize', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Inquisitor Baleful and take his power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This demon has proved less than useful. I have been using the Scythe of Souls on it, but so far, it has resisted my inquiries. We will see how long that lasts.nnI have a different idea...nnThere is a fresh inquisitor demon ahead. They are horrific fel casters who see through their floating eyes and specialize in dark pacts. If you steal its power, Jace Darkweaver could use some of it in his ritual to spy on the Legion.nnBetter yet, you will gain its power by ripping it from its smoking corpse.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Steal his essence and become more powerful.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Inquisitor Baleful', `PortraitGiverName`) WHERE `ID` = 39049;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Meeting With the Queen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the ritual to spy upon the Legion leaders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We can use some of that essence to complete my ritual. You\'ll be able to spy upon the Legion leaders and see what they\'re planning.nnUse the nether crucible and complete the ritual.', `QuestDescription`) WHERE `ID` = 39050;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'By Any Means', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gain entrance to the Violet Hold and interrogate Taldath the Destroyer to find out the location of the traitor Varedis.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need to figure out what rock Varedis is hiding under - the only way we\'re going to do that is by getting inside this prison.$B$BDo what you must.', `QuestDescription`) WHERE `ID` = 39051;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shipbuilding', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Learn the blueprints and destroy the evidence.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there.$b$bLet\'s make sure these don\'t fall back into the hands of the Iron Horde. Memorize these blueprints, $c, and then destroy the evidence. Let me know when you are done.', `QuestDescription`) WHERE `ID` = 39054;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ship Shape', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Yanas to begin construction on a transport ship.  Once complete, add it to your collection of ships.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have the blueprints, let\'s get started on our first ship, a transport!  Speak to me when you are ready to begin construction.', `QuestDescription`) WHERE `ID` = 39055;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Naval Commander', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Merreck Vonder in your Shipyard and complete a Naval Mission.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have come a long way in a short time on this shipyard, $n.  Now it\'s time to run our first naval mission and control the seas of Draenor!$b$bI will need to setup shop from a high vantage point to plan out these seafaring missions.  Meet me near the shipyard entrance and we can get started.', `QuestDescription`) WHERE `ID` = 39056;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Command of the Seas', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Upgrade to a Level 2 shipyard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Gul\'dan wasted no time integrating his Shadow Council minions into every rank of the Iron Horde. The naval fleet that once owed loyalty only to Grommash is now his to command. If we want to fight back, we\'re going to need more than just a couple of transport ships. We must build an arsenal.$b$bWe need your expertise, commander. Upgrade your dockyards and create a fleet capable of dominating the seas!', `QuestDescription`) WHERE `ID` = 39057;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Critters of Draenor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Erris the Collector in a pet battle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I love collecting pets, and I\'ve picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we\'ll both learn a few new tricks.', `QuestDescription`) WHERE `ID` = 39058;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Catch a Banshee', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Genn Greymane in Greywatch.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The strange-talking vrykul said I might be able to meet you here. I have orders from Greymane.  It seems he may have a lead on Sylvanas\' location.nnHe\'s set up a camp near the base of the mountain. We\'ve run into some troubles, though. It looks like the Horde may have homed in on our position.nnWe could use your help. You can take my gryphon. Just speak to me when you\'re ready to leave.', `QuestDescription`) WHERE `ID` = 39059;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Combustible Contagion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Burn the Forsaken Blight Caches near Greywatch.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is true that we may have a lead on Sylvanas. Though I want nothing more than to get my hands on the Banshee Queen, the situation here at Greywatch requires immediate attention.nnYesterday, a regiment of guards returned with word of Forsaken forces in the woods. Several of them bore signs of a blight, similar to the one we endured in Gilneas. It would appear these Forsaken seek to unleash this blight upon Greywatch.nnSeek out their caches and destroy them, before the blight overtakes us!', `QuestDescription`) WHERE `ID` = 39060;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Whispers from the Dark', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Forsaken Scouting Orders from Dread-Rider Stalkers and Dread-Rider Plaguebringers near Greywatch.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We still have little knowledge of the Horde\'s activities in the region, but I\'m hoping you can help change that.nnLately the woods have been crawling with Sylvanas\' agents. The few we have taken out carried orders from her Dark Rangers, who are no doubt in command of her forces here.nnWhile you\'re on the hunt, keep an eye out for any scouting orders. They may help us pinpoint Sylvanas\' objective in the area.', `QuestDescription`) WHERE `ID` = 39061;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Skold-Ashil', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Commander Lorna Crowley in Crowley\'s Overlook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have her now! According to these reports, Sylvanas\' forces are after something in Skold-Ashil - a vrykul town not far from here. We must make our way there and track her down.nnI had previously dispatched Commander Lorna Crowley and a detachment of Gilneas Brigade to scout the position. Meet up with her there and find out what Sylvanas is after.nnMeanwhile, I will muster the fleet to assault their outpost. We will have justice if I have to reduce their camp to rubble!', `QuestDescription`) WHERE `ID` = 39062;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shielded Secrets', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Examine 6 Engraved Vrykul Shields in Skold-Ashil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s obvious at this point that the Horde wants something in Skold-Ashil. Unfortunately we still don\'t know what they\'re after.nnWe think the secret lies with the shieldmaidens here, so we need to find out more about them. Some early scouting revealed that they have a method of carving their shields to tell their stories. nnGo into the city and find as many of these shields as you can. With luck, we will find what Sylvanas seeks.', `QuestDescription`) WHERE `ID` = 39063;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Upgrading The Fleet', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 1000 garrison resources, 1000 gold and complete 15 naval missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have been doing a great job out there commander.  However, we are going to need more experience and resources to upgrade this shipyard.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!', `QuestDescription`) WHERE `ID` = 39067;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Naval Domination', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 2500 garrison resources, 2500 gold and complete 25 naval treasure missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our naval domination continues!$b$bHowever, we are going to need even more experience and resources to take this shipyard to the next level.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!', `QuestDescription`) WHERE `ID` = 39068;
