UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Becoming the Ascendant', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek the blessings at the four shrines in the temple at Skold-Ashil, then commune with the statue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our course is now clear. We must enter the vault and prevent Sylvanas from obtaining the power to create more Val\'kyr. nnThe entrance is barred, which is likely what has kept her out so far, but you may have already uncovered the key to this barrier.nnYou must become the next ascendant.nnComplete the rites as depicted on the shields and take down the barrier to the vault. I will send word to Greymane of our findings - he will wish to confront Sylvanas himself.', `QuestDescription`) WHERE `ID` = 39092;
