UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shriek No More', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Rotbeak along the Bradensbrook, and collect the beast\'s head.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Papa loved this village. He\'d never hear of leaving, even in these dread times.$B$BBefore he died, he told me what attacked him: a monstrous falcon we call Rotbeak.$B$BYou\'re fighting these undead, aren\'t you? Will you avenge my father? If so, you can find the beast northwest of here, patrolling our western route to the sea.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Rotbeak', `PortraitGiverName`) WHERE `ID` = 39117;
