UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ending the New Beginning', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Confront Sylvanas in the Vault of Eyir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Banshee Queen is here! I\'d recognize those tainted arrows anywhere.nnThis is the moment we have been fighting for. Sylvanas will answer for her crimes against Varian Wrynn and the Alliance!nnTo arms!', `QuestDescription`) WHERE `ID` = 39122;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lion Stalkin\'', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Hunt Pinerock Stalkers and Prowlers in Pinerock Basin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The hills are crawlin\' with lions that stalk their prey from afar. These big cats will pounce at anything that catches their eye, including |5$r. nnWhile most would fall to such a formidable predator, anyone in my huntin\' party would be able to best those beasts.nnProve you\'ve got what it takes by taking down a few of those stalkers.', `QuestDescription`) WHERE `ID` = 39123;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moose Shootin\'', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Hunt Pinerock Elderhorn in Pinerock Basin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Highmountain is home to wildlife that can\'t be hunted anywhere else in the world. Tell me, $n, have you ever laid eyes on a moose before? nnThe roaming Elderhorn may look like gentle giants, but only a fool would underestimate their strength. nnThey should prove to be a good challenge, even for someone as experienced as you.', `QuestDescription`) WHERE `ID` = 39124;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demon Destroyer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Doomcaller, Sneermaw, and Grinchain', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demons spreading this corruption must be dealt with. Kill their generals and their plans will unravel.nnI have a gift for you. This horn was given to me by Odyn himself, use it to strike down all that stand in your way.nnThe gods will surely smile upon you if you thwart the advances of Legion.', `QuestDescription`) WHERE `ID` = 39125;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Beyond the Wall', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Taran Zhu at the Longying Outpost in Townlong Steppes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We received word the Shado-Pan have begun a counter attack in to Townlong Steppes. It sounds like they are going after the root of the yaungol invasion.$b$bThe pandaren have not traveled in force in to Townlong for thousands of years. The Shado-Pan are strong and brave, but they are also proud and few. They will need help from heroes like yourself. Can you travel through the Gate of Winter\'s Blossom in the northwest? Find the Shado-Pan leaders and lend your help and experience?', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Taran Zhu at the Longying Outpost in Townlong Steppes.', `QuestCompletionLog`) WHERE `ID` = 39127;
