UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Possessions of Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek those who may offer insight into the origins of the shard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Echoes of a thousand worlds swirl in the palm of your hand. Its true value lies in the eye of the beholder.', `QuestDescription`) WHERE `ID` = 39131;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'No Time to Talk', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy $1oa Enraged Ambershard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Dargrul has sent his pets to do battle with us.$b$bWe need to crush these elementals before their rage swarms into Thunder Totem.', `QuestDescription`) WHERE `ID` = 39133;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wrathshard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Wrathshard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Underking has used the Hammer of Khaz\'goroth to render the mountainside into a weapon against us. The hammer is a tool for creation, not a weapon for his amusement!$b$bEven now, his crystal servant, Wrathshard, is driving these elementals out of the mountain down upon my people.$b$bWe must hold the bridge against this onslaught.$b$bEnter the cave, find Wrathshard, and send him back to his master in pieces.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Summoned by the drogbar to destroy Thunder Totem.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Wrathshard', `PortraitGiverName`) WHERE `ID` = 39134;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unused', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Kiranys Duskwhisper at the haunted manor in Bradensbrook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve charged up the gun. Now it\'s time to use it. Go and confront the ghostly wizard Kiranys Duskwhisper, and drive him out of Bradensbrook.', `QuestDescription`) WHERE `ID` = 39136;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Testing a Theory', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Bloodstone on an Imprisoned Imp.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that the Bloodstone has fed, I hope to use its power to bend the will of demons that would otherwise not be so easily controlled.nnOf course, this is all theory. I have never witnessed the direct effect of the Bloodstone\'s power on a demon. This is where you come in.nnI have procured a few imps that should make suitable test subjects. Use the Bloodstone on them and report back to me with your findings.', `QuestDescription`) WHERE `ID` = 39142;
