UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Village in Peril', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Mayor Heathrow at Bradensbrook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Another outsider? Some bloke named Jarod just went off to our village down the road claiming he might be able to help us with our problem.$b$bIf you\'re here to help as well, then you best speak to the Mayor.$b$bJust know this is a bad time, and he\'s got an itchy trigger finger.', `QuestDescription`) WHERE `ID` = 39149;
