UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dreadwake\'s Dilemma', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 10 Greywatch Saboteurs or Infiltrators in Greymane\'s Offensive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The situation has taken a dire turn, $n. We were unprepared for Greymane\'s sudden assault, with only a token force left behind at Dreadwake\'s Landing, and we are paying the toll.nnThe beach is now swarming with worgen infiltrators, and if the cannons breach our defenses, they will likely swarm in on us. We\'re spread too thin here to take the fight to them, but you could change that.nnWipe them out.', `QuestDescription`) WHERE `ID` = 39153;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Skold-Ashil', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with the dark rangers in Ranger\'s Foothold, outside of Skold-Ashil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thanks to your initiative, $c, the situation at Dreadwake\'s Landing is under control. We have no time to rest on our laurels, however - Sylvanas\'s mission must still be carried out.nnThe dark rangers are heading up operations in Skold-Ashil from the tower overlooking the river junction. Seek them out there, and see if you can aid in completing this task.', `QuestDescription`) WHERE `ID` = 39154;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Becoming the Ascendant', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek the blessings at the four shrines in the temple at Skold-Ashil, then commune with the statue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It would seem that the engravings depict a rite of ascension, which allows the shieldmaidens to enter the vault. I believe we can use this to our advantage.nnYou must become the next ascendant.nnGo to the temple and perform the rites. Should you need to wade through the corpses of the shieldmaidens to do so, then so be it. nnFind me when you have completed this task, and we will take the vault for the Horde!', `QuestDescription`) WHERE `ID` = 39155;
