UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gems of the Apexis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Sun-Sage Chakkis in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Listen, boss. I know you\'re a jewelcrafter. It\'s OK, I totally understand - I like money, too!$b$bI heard some of them bird fellas talking about some new gem-cuttin\' device they got up in Tanaan. I\'d be interested in checkin\' it out myself, but I\'ve got this whole shipyard mess to deal with right now.', `QuestDescription`) WHERE `ID` = 39175;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mastery Of Taladite', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Apexis Gemcutting Construct.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You - you are a gemcutter, no? You have the look of it in the twitch of your knuckles, in the focus of your eyes.$b$bI\'ve been looking for something specific out here in Tanaan. We did not find it in our excavations in Arak... but the Apexis did not only dwell in Arak.$b$bWhat I am looking for is a storied Apexis construct that specialized in cutting gems. Be on the lookout, jewelcrafter. Such a marvel could benefit the both of us.', `QuestDescription`) WHERE `ID` = 39176;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ruined Construct', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Repair the Apexis Gemcutter Construct by inserting 1000 Apexis Crystals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<It is in disrepair, but it is not broken. More than anything, the construct appears to be in need of re-energizing.>$b$b<A slot on the backside of the machine lies open, waiting to accept... whatever the Apexis used as a source of energy.>', `QuestDescription`) WHERE `ID` = 39177;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moose on the Loose', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the antlers of the cursed ancient spirit, Morashu.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There\'s been chatter around the hunters\' lodge about a crazed moose that is terrorizing the basin. nnI\'ve never laid eyes on the beast myself, but they say its antlers are illuminated with magic. nnWhere other lesser hunters have tried and failed, you will prevail, and collect me a one-of-a-kind trophy!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Morashu', `PortraitGiverName`) WHERE `ID` = 39178;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloodstone Bandit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover Kira\'s Bloodstone from Narashi Spitescale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Something of personal value has been taken from me, and my work here cannot continue until I get it back.nnTo most it would appear to be an ordinary stone, but it is so much more than a simple rock - it lives and breathes!nnThe nearby naga have been snatching anything with any sort of magical significance, my stone included. Fortunately, they do not know how to access its power.nnReturn my stone to me, and I will consider your request for help.', `QuestDescription`) WHERE `ID` = 39179;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Zangarmarsh', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Cenarion Circle\'s main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it\'s become a large and fairly autonomous body.$B$BThe expedition\'s leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.', `QuestDescription`) WHERE `ID` = 39180;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Zangarmarsh', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Cenarion Circle\'s main expeditionary force in Outland is known as the Cenarion Expedition.  Though it began as a small venture controlled directly by the Cenarion Circle, it\'s become a large and fairly autonomous body.$B$BThe expedition\'s leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost.  Report to her at the Cenarion Refuge in eastern Zangarmarsh.  Take the main path to the west and it will lead you directly there.', `QuestDescription`) WHERE `ID` = 39181;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Terokkar Forest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have lost contact with the druids of the Cenarion Thicket$B$BThe Warchief has commanded any able bodies of the Horde to venture into Terokkar Forest and discover what has happened.$b$bThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.', `QuestDescription`) WHERE `ID` = 39182;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Immaculate Critical Strike Taladite', `LogTitle`) WHERE `ID` = 39183;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Immaculate Haste Taladite', `LogTitle`) WHERE `ID` = 39184;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Immaculate Mastery Taladite', `LogTitle`) WHERE `ID` = 39185;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Immaculate Multistrike Taladite', `LogTitle`) WHERE `ID` = 39186;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Immaculate Stamina Taladite', `LogTitle`) WHERE `ID` = 39187;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Terokkar Forest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with one of the druids at the Cenarion Thicket in Terokkar Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have lost contact with the druids of the Cenarion Thicket$B$BThe King has commanded any able bodies of the Alliance to venture into Terokkar Forest and discover what has happened.$b$bThe thicket can be found by heading northwest through Terokkar Forest from Zangarmarsh.', `QuestDescription`) WHERE `ID` = 39188;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Legacy of the Icebreaker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deal with Magnar Icebreaker.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The greatest warrior should wield the greatest weapons. Long ago a great king, Magnar Icebreaker, wielded weapons crafted from a scale of the mightiest dragon in the land. He should be here, but he is not. Instead he languishes in his tomb.nnHis son, Hruthnir, is here. He will lead you to the tomb. If Magnar can be saved, do so. Either way, return with his weapons.', `QuestDescription`) WHERE `ID` = 39191;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Forge of Odyn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Forge of Odyn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This Forge has been working for longer than your race has existed; we might know a few things. Your weapon is powerful, it will take my personal forge in order to work it.nnWe can work the artifact to provide various improvements, provided you have enough experience with it. Let\'s give it a try shall we?', `QuestDescription`) WHERE `ID` = 39192;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gems of the Apexis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Sun-Sage Chakkis in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander! I\'ve noticed you have been keeping up with your jewelcrafting, despite all of this war going on. I find that to be most admirable.$b$bI overheard some of the arakkoa discussing a gemcutting device that they believe is located within Tanaan Jungle. They got their information from one named "Chakkis."$b$bJust thought you might be interested.', `QuestDescription`) WHERE `ID` = 39195;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Nagrand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Captain Kroghan at Garadar in Nagrand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Warchief has asked for any able bodied champions of the Horde to ride to the aid of Garadar.$B$BThe home of the Mag\'har, lies to the south, in Nagrand. Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake.$B$BReport to Captain Kroghan there and offer him what assistance you can. Garadar must not fall!', `QuestDescription`) WHERE `ID` = 39196;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Nagrand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Warden Moi\'bff Jill at Telaar in Nagrand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The King has requested you represent him with the Kurunai settlement of Telaar in Nagrand.$b$bSeek out Warden Moi\'bff Jill upon arrival.', `QuestDescription`) WHERE `ID` = 39197;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Blade\'s Edge Mountains', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Thunderlord Stronghold in the Blade\'s Edge Mountains and speak with Nekthar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Warchief is calling for champions to put an end to the ogre threat in Blade\'s Edge Mountains. Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Nekthar know of our plight. Any help he can spare would be most welcome.', `QuestDescription`) WHERE `ID` = 39198;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Blade\'s Edge Mountains', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Kialon at Sylvanaar in the Blade\'s Edge Mountains.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Alliance forces of Sylvanaar in the Blade\'s Edge Mountains require reinforcements.$b$bThe King has asked for any able bodied members of the Alliance to journey to the mountains along the northern border of Zangarmarsh.', `QuestDescription`) WHERE `ID` = 39199;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Netherstorm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Rocket-Chief Fuselage at Area 52.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours.$b$bThe Warchief feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael\'thas.$b$bArea 52 can be reached by following the northeastern road of Blade\'s Edge Mountains until you see the world crumbling away into the Twisting Nether.', `QuestDescription`) WHERE `ID` = 39201;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Netherstorm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Rocket-Chief Fuselage at Area 52.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The goblins of Area 52 in Netherstorm have called for assistance from any able bodied champions willing to provide them the support they need in their endevours.$b$bThe King feels their position and aid in the region will provide a tactical advantage against the nearby forces of Kael\'thas.$b$bArea 52 can be reached by following the northeastern road of Blade\'s Edge Mountains until you see the world crumbling away into the Twisting Nether.', `QuestDescription`) WHERE `ID` = 39202;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Dragonblight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the Image of Archmage Aethas Sunreaver at Agmar\'s Hammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Warchief wishes to reinforce the Horde\'s presence at Agmar\'s Hammer in the Dragonblight.$b$bThe fortress is a vital staging point for our assault on Icecrown and pivotal to containing the chaotic magic energies being released throughout the land.$b$bReport to Archmage Aethas Sunreaver.', `QuestDescription`) WHERE `ID` = 39203;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Dragonblight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the Image of Archmage Modera at Stars\' Rest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Volunteers are needed to aid the Silver Covenant forces in the Dragonblight as they attempt to counter the chaotic arcane energies that threaten to rip the land apart.$b$bThose skilled in fighting dragons and undead are greatly welcome.$b$BThose willing to answer the call should report to Archmage Modera at Stars\' Rest in Dragonblight.', `QuestDescription`) WHERE `ID` = 39204;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warchief\'s Command: Grizzly Hills', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve received a request for help from our base in the Grizzly Hills. Go to see Conqueror Krenna.$B$BShe\'s attempting to secure all of the natural resources. Just watch your back around her. The word is that she\'s aggressive even for an orc.$B$BYou can reach her by traveling east from Dragonblight.', `QuestDescription`) WHERE `ID` = 39206;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hero\'s Call: Grizzly Hills', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills. All in hopes of finding an alternate route into Icecrown.$B$BLieutenant Dumont, stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?', `QuestDescription`) WHERE `ID` = 39207;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Zul\'Drak', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Stefan Vadu at Ebon Watch in Zul\'Drak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our death knight allies in Zul\'Drak are in need of heroes to aid them in securing the troll lands from the scourge.$b$bThose willing to aid should travel to the southwestern camp of Ebon Watch and speak with Stefan Vadu there.', `QuestDescription`) WHERE `ID` = 39208;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sholazar Basin', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin. His expedition has not been heard from since.$b$bMonte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn\'t returned, either.$b$bVolunteers are needed to mount an expedition to find the missing expedition. Monte\'s flying machine was last seen in the Wildgrowth Mangal south of the Suntouched Pillar in Sholazar Basin.', `QuestDescription`) WHERE `ID` = 39209;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Magical Kingdom of Dalaran', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Archmage Celindra at The Violet Gate in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Kirin Tor have moved their city here to Northrend.$B$BNo longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest.$B$BThey believe you to be ready for your journey to the city. Look for the teleportation crystal in Crystal Song Forest.$B$BWhen you arrive, seek out Archmage Celindra.', `QuestDescription`) WHERE `ID` = 39210;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sholazar Basin', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Archmage Pentarus when you\'re ready to leave for Sholazar Basin. When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hemet Nesingwary was last heard from leading an expedition into the jungle depths of Sholazar Basin. His expedition has not been heard from since.$b$bMonte Muzzleshot is a pilot who was dispatched to provide them supplies, but he hasn\'t returned, either.$b$bArchmage Pentarus in Dalaran is standing by with a flying machine to take you to the last known location of Monte Muzzleshot.', `QuestDescription`) WHERE `ID` = 39212;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Eye of Odyn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Eye of Odyn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time to begin the war in Azeroth. We have prepared a tool for you to direct your warriors and your own operations from here. It is called the Eye of Odyn. nnIf you will follow me, I will take you to it, and someone that will help you use it.', `QuestDescription`) WHERE `ID` = 39214;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ready to forge Tracking Bit', `LogTitle`) WHERE `ID` = 39216;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Don\'t Hate, Excavate!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Harrison Jones in Ashran wants you to investigate the deepest part of the Ashran Excavation, The Breach.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well $n, the good news is that our excavation team breached a chamber below right outside some sort of vault. The bad news is that the Horde were there too. Go down there and take a look.', `QuestDescription`) WHERE `ID` = 39217;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pits of Mannoroth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Kormrok in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In the Hellfire Citadel, they work to corrupt a magnaron with fel energy within the Pits of Mannoroth.nnIf you delve into the fel pools of that place, be on your guard.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Kormrok', `PortraitGiverName`) WHERE `ID` = 39221;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maw of Souls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Gorefiend in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Falling into the heart of the mausoleum in Auchindoun, Teron\'gor gorged upon hundreds of draenei souls, becoming a bloated abomination in the process. nnNo longer recognizable as an orc, Teron\'gor gave up his old name and has taken on the mantle of Gorefiend.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Gorefiend', `PortraitGiverName`) WHERE `ID` = 39225;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Temple of Tyranny', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Tyrant Velhari in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her.nnPurge this Eredar of darkness.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Tyrant Velhari', `PortraitGiverName`) WHERE `ID` = 39228;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Destructor\'s Rise', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Mannoroth in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We believed we were done with Mannoroth, at least for a time. But Gul\'dan is more powerful than we had predicted.nnMannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Mannoroth', `PortraitGiverName`) WHERE `ID` = 39231;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Black Gate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Archimonde in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have heard rumors that one of the strongest of the eredar could soon enter this world through the Black Gate.nnIf these rumors are to be believed, it could even be Archimonde the Defiler. Should he arrive uncontested, Draenor itself is likely to fall.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Archimonde', `PortraitGiverName`) WHERE `ID` = 39232;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Don\'t Hate, Excavate!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Belloc Brightblade in Ashran wants you to investigate the deepest part of the Ashran Excavation, The Breach.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'At last $n, you\'ve arrived and not a moment too soon. Quick, go down into the mine and take a look at what we\'ve discovered. You may run into some Alliance down there. It is a minor inconvenience that is easily remedied.', `QuestDescription`) WHERE `ID` = 39233;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Peak Urgency', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Mathias Shaw in the sewers beneath Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$B$BBYou\'ve been summoned by Master Mathias Shaw of SI:7. He\'s waiting for you in the depths beneath Dalaran. Be wary - there have been reports of disappearances in those sewers.', `QuestDescription`) WHERE `ID` = 39234;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Buba', `LogTitle`) WHERE `ID` = 39235;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Let\'s Get To Work', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Solog at the dry docks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that the shipyard is complete, we need to get busy making ships!  Solog ran off to the dry docks, why don\'t you meet him down there?  He said he had a plan.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Find Solog Roark at the dry docks.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Solog Roark', `PortraitGiverName`) WHERE `ID` = 39236;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shipbuilding', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Learn the blueprints and destroy the evidence.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The first thing we need to start building ships is a blueprint. With your help, I grabbed some of the best ones from the Iron Docks before we broke out of there.$b$bLet\'s make sure these don\'t fall back into the hands of the Iron Horde. Memorize these blueprints, $c, and then destroy the evidence. Let me know when you are done.', `QuestDescription`) WHERE `ID` = 39241;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ship Shape', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Solog to begin construction on a transport ship. Once complete, add it to your collection of ships.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You want to take the fight to Gul\'dan? You need a transport! Speak to me when you are ready to begin construction.', `QuestDescription`) WHERE `ID` = 39242;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Naval Commander', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Rolash Wavechaser at your shipyard and complete a Naval Mission.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'re a natural at this, $n. You\'ve got the salt in your veins. Now it\'s time to run our first naval mission and control the seas of Draenor!$b$bYou will want a high vantage point to plan out these seafaring missions.  I know a good spot just up the path behind us. Meet me near the shipyard entrance and we can get started on our first mission.', `QuestDescription`) WHERE `ID` = 39243;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Upgrading The Fleet', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 1000 garrison resources, 1000 gold and combat 15 naval missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have been doing a great job out there commander.  However, we are going to need more experience and resources to upgrade this shipyard.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold more ships!', `QuestDescription`) WHERE `ID` = 39245;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Naval Domination', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 2500 garrison resources, 2500 gold and complete 25 naval treasure missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our naval domination continues!$b$bHowever, we are going to need even more experience and resources to take this shipyard to the next level.  Once we reach our goals, we can upgrade the capacity of the shipyard to hold even more ships!', `QuestDescription`) WHERE `ID` = 39246;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hunt', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Twinblades of the Deceiver from Varedis Felsoul in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This hunt is yours to lead, $n - a select few Illidari will join you to make sure Varedis meets his end.$B$BThe rest of us must stay behind; a small team will have the best chance of making it to his hold undetected.$B$BWe will meet you at Krasus\' Landing to see you off when you are ready.', `QuestDescription`) WHERE `ID` = 39247;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pits of Mannoroth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Kormrok in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In the Hellfire Citadel, they\'re corruptin\' a magnaron with fel energy in the Pits o\' Mannoroth.nnIf ye delve into the fel pools of that place, be on yer guard.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Kormrok', `PortraitGiverName`) WHERE `ID` = 39250;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maw of Souls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Gorefiend in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Falling into the heart o\' the mausoleum in Auchindoun, Teron\'gor gorged upon hundreds o\' draenei souls, becoming a bloated abomination in the process. nnNo longer recognizable as an orc, Teron\'gor gave up his old name and has taken on the mantle of Gorefiend.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Gorefiend', `PortraitGiverName`) WHERE `ID` = 39253;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Temple of Tyranny', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Tyrant Velhari in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tyrant Velhari was once a promising vindicator, but has turned to Shadow for reasons known only to her.nnPurge this Eredar of darkness.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Tyrant Velhari', `PortraitGiverName`) WHERE `ID` = 39256;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Destructor\'s Rise', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Mannoroth in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We believed we were done with Mannoroth, at least for a time. But Gul\'dan is more powerful than we thought.nnMannoroth is nearly back in this world. His bones have been seen within the citadel, and he must be destroyed before he can reach his full power.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Mannoroth', `PortraitGiverName`) WHERE `ID` = 39259;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Black Gate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Archimonde in Hellfire Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve heard rumors that one o\' the strongest eredar might enter this world through the Black Gate soon.nnIf these rumors are to be believed, it could even be Archimonde the Defiler. If he arrives unchallenged, Draenor itself is likely to fall.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Archimonde', `PortraitGiverName`) WHERE `ID` = 39260;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Illidari', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Kayn Sunfury at Krasus\' Landing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Kayn requests that you meet him at Krasus\' Landing at once.$B$B<Kor\'vas leans in close, her voice an urgent whisper.>$B$BYou must hurry. The Legion has eyes everywhere.', `QuestDescription`) WHERE `ID` = 39261;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Give Me Sight Beyond Sight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Jace Darkweaver and then use your Spectral Sight ability to scan the cave for hidden demons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Jace Darkweaver swears that for a split second he sensed a demonic presence up and behind us. He took some of our forces up to the cave just to the southeast to investigate.nnThey found nothing in the cave, but he is certain that something is amiss.nnWould you lend him your guidance, and more importantly, your spectral sight?', `QuestDescription`) WHERE `ID` = 39262;
