UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Poisoned Crops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the drogbar Poison Idols.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'After driving us from the farmland and infesting our crops with insects, the drogbar placed wicked totems that further poison our harvest.nnI can only hope that if you destroy them, we\'ll be able to heal the land using Jale\'s water magic.nnThank you for coming to help us, $n. We are but simple farmers and fishermen, and have little prowess in combat.', `QuestDescription`) WHERE `ID` = 39272;
