UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Strange Tools', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Yanas Seastrike at the dry docks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are well on our way to building our first ship, but unfortunately, I am not the orc for the job.  I have no idea how to work with these human tools.  Your shipwright, Yanas Seastrike, is going to take over from here on out.$b$bI will be here at the dry docks if you need anything from me.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Speak with Yanas Seastrike at the dry docks.  His shipbuilding work is renowned.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Yanas Seastrike', `PortraitGiverName`) WHERE `ID` = 39276;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spray and Prey', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Bug Sprayer on drogbar in Whitewater Wash.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bug Sprayer you recovered from Ormgul the Pestilent seems like it could give us an advantage against the drogbar and their insects.nnSpray the Drogbar with their own alchemy and watch their insects turn against them.', `QuestDescription`) WHERE `ID` = 39277;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Missing Manifest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Mr. Knuckles\' missing shipment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The water-proofed manifest contains some form of code for the most part, hiding the contents of the actual manifest. In the corner is a hastily scrawled note for a Mr. Knuckles. "Shipment attacked, got away but boat is sinking. Get here before they do."$b$bThere are coordinates after that which lead to the sunken boat. Mr. Knuckles is definitely the kind of person you want owing you a favor, not the other way around.', `QuestDescription`) WHERE `ID` = 39278;
