UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Gruesome Task', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve 5 Severed Heads from the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So here\'s the scoop, $n. One of our agents has found an entrance to the portal world where Sargeras is keeping his personal felhound. We can\'t strike at him directly, but he\'s imbued a lot of power into this creature.$B That\'s the good news.$B$B The bad news, however, is outright gruesome. He\'s been feeding this monster on the brains of our allies, and that\'s all it will eat. As horrifying as it is, there\'s a fresh supply of corpses at the Broken Shore. Head down and get them.', `QuestDescription`) WHERE `ID` = 39286;
