UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Marketeering', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Zhang Yeoh in your garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ya did us a real solid today, $n. Boss Goya says you\'re big stuff in dese parts and we should keep an eye on --- uh, I mean we should be good buds. She\'s sent a repre... repre... del-e-g... um, a Black Market person to your garrison.$b$bGo say hi and stuff, and make sure to speak loudly when you plan what you\'re gonna do next.', `QuestDescription`) WHERE `ID` = 39299;
