UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Empty Nest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place the eagle eggs in the empty nest above the eastern entrance to Rockcrawler Chasm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve taken an inventory of the eggs you recovered. Some among the bunch may still have a chance to hatch.nnThey will need to be returned to an empty nest, and with any luck, an eagle will claim the eggs as her own and watch over them once again.nnThere is a nest just outside the entrance, on a rocky ledge above the cave.nnBe careful, $n. The eggs are very delicate.', `QuestDescription`) WHERE `ID` = 39305;
