UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bring the Reinforcements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Angar Steelbellow and choose which reinforcements to bring to Tanaan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, Commander! With all of the fighting concentrated here in Tanaan, we\'ve got the breathing room to divert some of our resources from nearby outposts to help make headway.$B$BJust let me know which reinforcements to call, and I\'ll get them here on the double!', `QuestDescription`) WHERE `ID` = 39313;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bring the Reinforcements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Fraggs and choose which reinforcements to bring to Tanaan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hey there, Commander. You know, with all of the fighting concentrated here in Tanaan, we\'ve got plenty of extra supplies just sitting around in our nearby outposts.$B$BYou just give me the order and I\'ll make sure some of them get sent our way!', `QuestDescription`) WHERE `ID` = 39315;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trapped Tauren', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free the captured Rivermane tauren.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The drogbar just rounded up those of us that they could and led them to a cave near here.nnIf you act quickly, I think they can still be saved. I know not what purpose they have for capturing our people.nnI shudder to think of it... in the deep places, the darkness rules.', `QuestDescription`) WHERE `ID` = 39316;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Siege of Crawliac', `LogTitle`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[ph] Defend the bluffs!', `QuestDescription`) WHERE `ID` = 39317;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nursing the Wounds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Windmaster Julan and help extinguish the fires on Skyhorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know why Mayla sent you. But as you have seen, the drogbar are not the only threat to Highmountain.$b$bI will not send forces to support until we deal with the minions of High Crawliac.$b$bIf you want to help, find my shaman. He was supposed to be dispersing these fires that are ravaging my village.$b$bHe was last seen heading for his spirit lodge to the south just before these Cinderwitches descended on us.', `QuestDescription`) WHERE `ID` = 39318;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Three', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Ragi the Hexxer, Agara Deathsong, and Ugla the Hag.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When High Crawliac seized control of the harpies she placed 3 powerful and deadly witches in charge of the covens under her command.$b$bThese witches must die. Feel up for the challenge?$b$bHead into the Haglands behind me and find these three evil creatures.$b$bWe will cover you from the air and give your prey no sky to retreat.$b$bLook for us higher up the mountain, should you survive.', `QuestDescription`) WHERE `ID` = 39321;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Witchqueen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay High Crawliac, the Witchqueen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time has come to assault High Crawliac, the Witchqueen.$b$BYou should know that one does not become queen of the harpies through kindness.$b$bThis creature has killed, betrayed, and tormented countless tauren, harpies, kobolds, and anything else she had to in order to secure her position as queen.$b$bCome, friend, let us finish this.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Queen of the harpies.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'High Crawliac', `PortraitGiverName`) WHERE `ID` = 39322;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moozy\'s Sojourn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Moozy downriver in Whitewater Wash.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My son! They took him! My wife and I split up to look for him. She went upriver and I went downriver.nnLeave me, please, and find Moozy... I might be okay... If you find Moozy, please bring him to my wife upriver.', `QuestDescription`) WHERE `ID` = 39323;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Through the Portal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Demonic Gateway to enter the Hound\'s Portal World.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here\'s the good news: you\'re halfway there. Sorry you had to do that, but necessity is the mother of invention. See that portal down there? That\'s where the Hound lives. Get through it and find out what\'s going on in there.', `QuestDescription`) WHERE `ID` = 39324;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Get Your Mix On', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deucus Valdera in Dalaran wants you to craft some new potions. Merchant Patricia Egan in the alchemy shop can help you learn how.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Let\'s see... potion stains on your tabard, crushed herbs on your boots... I know a fellow alchemist when I see one!$b$bWe will do good work together, the two of us. I trust you\'re not averse to learning new tricks.$b$bBe sure to use my state-of-the-art alchemy table. I built her myself!', `QuestDescription`) WHERE `ID` = 39325;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missing Shipments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Alchemist Deucus Valdera in Dalaran wants you to locate supplies lost near the water in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we\'ve gotten to know each other, perhaps you can lend me a hand.$b$bMy weekly supply shipment was lost when my longtime courier--you know, old whatsername--was shot out of the sky over the shores of Azsuna. Surely a hardy sort like you could retrieve my lost goods.', `QuestDescription`) WHERE `ID` = 39326;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'There\'s a Scribe for That', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Runewritten Tome to Professor Pallin in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Fine! I admit, even my considerable intellect can\'t translate the strange tome you discovered. No doubt the water smears made it illegible.$b$bSay, one of those dimwitted scribes down the block owes me a favor. This sort of busywork is just his cup of tea.', `QuestDescription`) WHERE `ID` = 39327;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ancient Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Observe Deucus Valdera as he attempts one of the vrykul recipes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The tome contains a wealth of ancient vrykul recipes! Why, I could be the first alchemist in untold ages to craft one! How fortunate for you, friend $n, that you are here to bear witness to my greatness!$b$bAwful kind of that Svena person to die and leave her book for us, eh? Silly vrykul...', `QuestDescription`) WHERE `ID` = 39328;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Dormant Burner', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Purchase a Depleted Leyflame Burner from Hobart Grapplehammer and bring it to Deucus Valdera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve heard that someone over in the engineering shop is selling a burner that might be usable. You could likely negotiate a fairer price than I could!$b$bThe shop is just across the street. I\'ll make a note on your map for you.', `QuestDescription`) WHERE `ID` = 39329;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ley Hunting', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to key locations in Azsuna and use the Depleted Leyflame Burner to collect ley energy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The leyflame burner you brought me is useless! This is why I never trust an engineer...$b$bThe burner needs to be charged in areas that resonate with ley energy before it can be used to craft our newfound alchemy recipes.$b$bLucky for us, Azsuna is rich with such power.', `QuestDescription`) WHERE `ID` = 39330;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: Put a Cork in It', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Eye of Azshara and retrieve the Advanced Corks for Deucus Valdera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A thought occurred to me recently, $n. The naga have been known to hoard all manner of potions, so they might have the sort of corks we need.$b$bIn my educated opinion, I believe the best place to start searching is around the Eye of Azshara!$b$bTry not to waste your time in there dealing with the naga\'s goings on, just look for some replacement corks.', `QuestDescription`) WHERE `ID` = 39331;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Furbolg Firewater', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire skins of Smolderhide Firewater from the furbolg camp in Val\'sharah. Bring them back to Deucus Valdera in Dalaran so he can make use of the corks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh! I recognize these corks you brought me, $n. I recently acquired several from a furbolg tribe in Val\'sharah. They need sturdy corks to keep a tight seal on that potent firewater they brew.$b$bWe need more firewater potions--the corks would make an ideal addition to our alchemy table!', `QuestDescription`) WHERE `ID` = 39332;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Imprecise Burette', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Uncalibrated Malloric Burettes to Deucus in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here are your burettes. Should you ever be in the need of anything else, don\'t hesitate to ask.$b$b<Ms. Xiulan holds up the hair and continues to chuckle to herself.>', `QuestDescription`) WHERE `ID` = 39333;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thanks for Flasking', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the repaired Dual-Chambered Mixing Flask to Deucus Valdera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here is your flask, good as new. A fair trade for those potions.$b$bBe a little more careful with your breakables next time!', `QuestDescription`) WHERE `ID` = 39334;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Neltharion\'s Lair: Potent Powder', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire Precipitating Powder in Neltharion\'s Lair and bring it to Deucus Valdera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve heard rumors that the ancient drogbar collected powder from the residue of dragon\'s breath. If it\'s true that Neltharion\'s Lair lies somewhere below us, it seems a likely source.$b$bGo there and try to find a replacement for my powder.', `QuestDescription`) WHERE `ID` = 39335;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Need More Powder!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain Katterin\'s Alchemy Kit from Katterin the Blistered in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The substance you brought me appears to be precipitating powder, a highly volatile reagent used by the vrykul in their recipes.$b$bThere are rumors that a vrykul elder named Katterin has built up quite a store of this powder. A substance this dangerous needs to be in our hands, not hers!', `QuestDescription`) WHERE `ID` = 39336;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Forlorn Filter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with a Temple Priestess at the Temple of Elune to see if you can acquire some Shaldorei Silk.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Next on the list of things to replace are my filters. Now I\'m sure you\'ve concluded that an alchemist of my caliber uses only the finest of tools when mixing my potions.$b$bThe elves at the Temple of Elune in Val\'sharah use Shaldorei silk to craft their robes. Perhaps they\'d be willing to part with some for my filters.', `QuestDescription`) WHERE `ID` = 39337;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return the Filter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return the Mended Shaldorei Silk to Deucus Valdera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What was torn has now been mended. I hope you put this Shaldorei silk to good use.$b$bNow, run along.', `QuestDescription`) WHERE `ID` = 39338;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Fragile Crucible', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Fragile Demonsbreath Crucible to Deucus Valdera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have customers asking for alchemist stones, but I\'m unable to make any until I replace my crucible.$b$bIn order to create a new one, we\'ll need a few things, but first we\'ll need a proper container. Something that can be augmented to withstand a demon\'s breath.$b$bThere\'s a place in Suramar which the Legion has occupied. There surely must be a device there we can take that will be suitable for our needs.', `QuestDescription`) WHERE `ID` = 39339;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lining the Crucible', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Blood of Sargeras, $2oa Felhide, $3oa Felwort, and $4oa Yseralline Seeds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The first step in making this crucible useful is to restore the lining of its interior. That\'s going to require supplies you\'ll either gather yourself or obtain through trade with fellow adventurers.$b$bFelwort and yseralline seeds are familiar to herbalists.$b$bFelhide is obtained through skinning.$b$bBlood of Sargeras can be found all over the Broken Isles.', `QuestDescription`) WHERE `ID` = 39340;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vault of the Wardens: Demon\'s Bile', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a Skaggldrynk, then go to the Vault of the Wardens and bathe the crucible in the bile of Grimoira.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The key to a crucible like this is that it must be bathed in the foulest of fel energy. I hate to say it, but the most efficient method of accomplishing such a feat is to subject it to the bile of a demon.$b$bYes, I said the bile of a demon. Ready to get to work?$b$bIn the Vault of the Wardens, such a demon exists. An imp mother by the name of Grimoira.  The door to her room is sealed by an invisible lock.$b$bI\'d suggest bringing some Skaggldrynk with you. Use it when you get to her door.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Make sure to bring some skaggldrynk to get into her room.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Grimoira', `PortraitGiverName`) WHERE `ID` = 39341;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Price of the Black Market', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Silver Hair of Khadgar, a Blood of Sargeras, $3oa Kaldorei Ginger Wine and $4oa Moist Azsunian Feta.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I may have what you\'re looking for, burettes you say? Not a very common item.$b$bFor that, I require a moderate favor. Nothing too big, just a few things really.$b$bA silver hair from a high-ranking archmage... the blood of a titan, and, oh... some wine and cheese.$b$bWhat?! I have appetites that need satiating.', `QuestDescription`) WHERE `ID` = 39342;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bendy Glass Tubes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Bendy Glass Tubes to Deucus Valdera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You find tubing formed from a bendable sort of glass. It appears as though Grimoira was using it to suck out the insides of her victims.$b$bIts magical properties, however, would seem ideal for use on an advanced alchemy table.', `QuestDescription`) WHERE `ID` = 39343;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Going Underground', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'See Ms. Xiulan about acquiring some new burettes for Deucus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'re so close to replacing all my equipment, $n. In order to make flasks again, we need to be able to precisely measure each ingredient.$b$bFor that, we need to replace my burette assembly. Unfortunately, burettes aren\'t easy to come by. We may be able to procure some though through other means by...$b$b<Deucus looks around and beckons you closer.>$b$bGoing underground, so to say. As in, the Black Market.$b$bGo see Ms. Xiulan. Mum\'s the word.', `QuestDescription`) WHERE `ID` = 39344;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Calibration Experts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Uncalibrated Malloric Burettes to skilled alchemists for calibration.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It will take the cooperation of several highly skilled sorts to calibrate these burettes for a variety of substances.$b$bChemist Emmara is an old friend from the Undercity who has helped me with similar endeavors.$b$bThunder Bluff smells like a barn to me, but Jana Winterhoof is an alchemist with exacting standards.$b$bAnd while I\'d never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair.', `QuestDescription`) WHERE `ID` = 39345;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Testing the Calibration', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Test the Malloric Burettes\' calibration by crafting a variety of potions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you have the burettes calibrated, it\'s time to test them out! The only way to be sure is by crafting a sufficient quantity of a variety of potions.$b$bGlamorous work? No, but the most important reagent in alchemy is a bit of elbow grease!', `QuestDescription`) WHERE `ID` = 39346;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Channeling Our Efforts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Alard Schmied about the list of things you need done.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While it\'s no secret my time is more valuable than... well, anyone\'s, I fear I must step in and help to replace my decoction conduit.$b$bYou will also play a crucial part in this, $n, as my liaison with the blacksmiths. The thought of getting soot on my robes curls my toes.$b$bHere\'s a list of what we\'ll need done. Meanwhile I\'ll be out gathering the rest of what\'s needed.', `QuestDescription`) WHERE `ID` = 39347;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: The Prime Ingredient', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Eternity Sand from Heroic: Halls of Valor, craft a Flask of Ten Thousand Scars and return both items to Alard in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This first ingredient can only be obtained by visiting the next realm. Fortunately for us, there\'s a gate in Stormheim that can take you there.$b$bIn the Halls of Valor, there is a sand that\'s used for polishing their architecture. Eternity Sand, it\'s called. I\'ll need an ample amount of it as the base for the new glass.$b$bThis ingredient won\'t be easy to work with either. I\'ll need something to keep me going, you know, keep my stamina up.', `QuestDescription`) WHERE `ID` = 39348;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Hold: Heavy, But Helpful', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve some Sabelite Sulfate from Heroic: Black Rook Hold, craft a Flask of the Countless Armies and return both items to Alard in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The next ingredient on the list will supposedly add strength to the mix, according to Deucus. I\'ve heard of it before, but haven\'t really used it.$b$bIt\'s called Sabelite Sulfate, and it\'s said the elves of Black Rook Hold use it in their blacksmithing.$b$bSomething like that won\'t just be lying around. You may have to delve deep into the hold to find it.$b$bAnd due to its weight, I may need a concoction of yours to compensate, something to give me a bit more strength.', `QuestDescription`) WHERE `ID` = 39349;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maw of Souls: A Hope in Helheim', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve a crate of Dragur Dust from Heroic: Maw of Souls, craft a Flask of the Seventh Demon and return both items to Alard in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'For this last ingredient, well...$b$b<Alard begins pondering for a moment, then nods his head.>$b$bYes, that\'s the only way. For this last one, you\'ll need to go to the land of the damned, Helheim.$b$bWell, not there exactly, but aboard the boat that ferries the dead across the Maw of Souls. Upon that boat may be the final ingredient we need.$b$bIt\'s called Dragur Dust. Keep an eye out for it.$b$bAlso, one needs to be quick when adding this ingredient. I\'ll need something to heighten my reflexes.', `QuestDescription`) WHERE `ID` = 39350;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Emerald Nightmare: Rage Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Emerald Nightmare and acquire Nythendra\'s Heart. Bring it to Alard in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have all the ingredients assembled, we need one last thing.$b$bThe fire of my forges burn hot, but not hot enough to work these ingredients into glass. For that, we need more heat. The heat of a dragon, to be exact.$b$bI\'m aware of one that has emerged from the Emerald Dream in a corrupted state. Corrupted or not, a dragon\'s heart burns with enough heat to melt the strongest of materials.$b$bBring me its heart and you\'ll have your conduit.', `QuestDescription`) WHERE `ID` = 39351;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Extinguishing the Sentinels', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Extinguish the three Sentinels.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve made it. See that camp there? They\'ve got some Legion Sentinels hiding in there, set to notify Sargeras any time his pet pooch gets hungry or craves attention. Shut them down.', `QuestDescription`) WHERE `ID` = 39352;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Test - New', `LogTitle`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Test', `QuestDescription`) WHERE `ID` = 39353;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wisp in the Willows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Guide the Wisp through the Hidden Pools to grow $2oa trees.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Wisps are the spirits of our night elven brethren who have become one with the forest. But their minds and the way they perceive things are very different than in life.$b$bYou should bond with this little one. See through its eyes as it travels to the hidden pools and grows some trees.', `QuestDescription`) WHERE `ID` = 39354;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Equipment Blueprint: Trained Shark Tank', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return the blueprints to a Naval Equipment Specialist at your garrison shipyard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This appears to be a blueprint for some sort of naval equipment.  We should take it back to our Shipyard and see if someone can decipher it.', `QuestDescription`) WHERE `ID` = 39355;
