UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Equipment Blueprint: Ammo Reserves', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return the blueprints to a Naval Equipment Specialist at your garrison shipyard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This appears to be a blueprint for some sort of naval equipment.  We should take it back to our Shipyard and see if someone can decipher it.', `QuestDescription`) WHERE `ID` = 39370;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Witches of the Sky', `LogTitle`) WHERE `ID` = 39371;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Witch of the Wood', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Witch of the Wood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You saved me at Riverbend not long ago. It is the reason I vouched for you as emissary to this tribe, and the only reason you\'re alive here now. I consider my debt to you paid.nnYou must prove yourself to the Bloodtotem chieftain before he will speak with you.nnWithin the forest is the Witch of the Wood, a harpy mother who recently descended into this territory. If you are able to defeat her and show her carcass to the Bloodtotem, they might allow you an audience with Torok.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Witch of the Wood', `PortraitGiverName`) WHERE `ID` = 39372;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hags of a Feather', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Hag Feathers from Witchwood Hags in the Witchwood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The drogbar you freed me from were unusually aggressive. The tribe in the nearby caves seems to be apart from the rest of them, but that didn\'t stop the Bloodtotem from going on the offensive just in case, capturing some of their number.nnThat move left the woods exposed to the harpies, however. Your help dealing with these witches would not go unnoticed by Torok. Bring back their feathers as proof of death.', `QuestDescription`) WHERE `ID` = 39373;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Audience with Torok', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Torok Bloodtotem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I should warn you that Torok is easily displeased and is hateful of outsiders. Be on your guard.nnWe will seek an audience with him at his tent at the Cliff\'s Edge. As the Rivermane Emissary here, I am afforded some protection against aggression, but they have made no such promises about you.', `QuestDescription`) WHERE `ID` = 39374;
