UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rock Troll in a Hard Place', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Navarrogg to meet him at a safe location.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We should leave this place while we have a chance. The Bloodtotem are amassing at their village to the north, and I believe they intend to kill my people.nnLet me know when you are ready to go, and I can take us to a safe place quickly.', `QuestDescription`) WHERE `ID` = 39381;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Perrexx the Corruptor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Perrexx the Corruptor in the Moonclaw Vale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Look around you, $c. Corruption has befouled my valley. If Malfurion requires my presence to summon Ysera the Awakened, then I will surely aid him, but not until I have purged these demons from my lands.$B$BPerrexx the Corruptor is just ahead. Help me slay this fiend.$B$BStand by my side, and together we can rout these satyrs and their brethren.', `QuestDescription`) WHERE `ID` = 39382;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dishonored', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Xandris the Dishonored.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Xandris the Dishonored was among the first to betray his brethren and accept the curse of Xavius.$B$BDuring the great war, it was he who led the slaughter of many of my dearest friends.$b$bThe last time I met him on the battlefield he fled. Help me to finally dispense justice on this foul being.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Xandris the Dishonored', `PortraitGiverName`) WHERE `ID` = 39383;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Corruptor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Kagraxxis the Corruptor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Xandris has been slain, but there are others that must be dealt with if my grove is to be saved.$b$bDuring the great war, Kagraxxis took great pleasure in corrupting the lands he once called home.$b$bWere it not for the foolish mercy of my fellow druids, I would have slain him myself.$b$bFind the demon and bring justice upon him.$b$bI must entrust this task to you alone, for I sense an even darker presence here... one that requires my personal attention.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Kagraxxis the Corruptor', `PortraitGiverName`) WHERE `ID` = 39384;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Gift for Greymane', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Plant 3 Gilnean Heavy Explosives onto the hull of Greymane\'s ship and detonate them at a safe distance.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It looks like the Gilnean infiltrators brought some heavy ordnance to the fight. It\'s likely they intend to use them on the walls of Dreadwake\'s Landing.nnIf these could be rigged to Greymane\'s ship, it could make for a decisive end to his assault on the outpost.', `QuestDescription`) WHERE `ID` = 39385;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Procuring a Prototype', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Razik Gazbolt at Icepine Point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If Addie\'s going to be a more permanent member of the huntin\' party, then she\'ll need some specialty gear for someone her size.nnMy munitions expert should have some ideas about what kind of weapon would best suit a gnome.nnStop by his camp and let him know that I\'ll be needin\' a prototype soon.', `QuestDescription`) WHERE `ID` = 39386;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Skies of Highmountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lasan Skyhorn at the base of Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When you are ready, join me at the base of Thunder Totem.$b$bI would be honored to have you at my side as my tribe once again swears its allegiance to the young Mayla.$b$bTogether, we are Highmountain!', `QuestDescription`) WHERE `ID` = 39387;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moonclaw\'s Wisdom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Thaon Moonclaw in his den.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our quick action today has stopped this aggression and saved my valley. As you requested, I will join Malfurion in the Grove of Cenarius.$B$BStill, there is much about these satyrs that I wish to tell you. This information would be most valuable to you.$B$BPlease meet me in my den before departing.', `QuestDescription`) WHERE `ID` = 39388;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'It Hungers for Blood', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Let the Bloodstone feed on the blood of demons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Bloodstones contain a great deal of power that can only be awakened once they are fed. nnYet this stone does not feast on fish and cakes. It hungers for blood; the more powerful, the better.nnThere\'s an infestation of demons just east of here. I need you to nourish my stone with their blood, so that I may unlock its power.', `QuestDescription`) WHERE `ID` = 39389;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Mysterious Text', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Runewritten Tome to Deucus Valdera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You found a water-logged tome near the bones of a massive creature. Written in an unfamiliar language, the book is adorned with runes and alchemical symbols. Perhaps another alchemist would be able to tell you more.', `QuestDescription`) WHERE `ID` = 39390;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pet Rocks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Navarrogg\'s pets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I raise creatures born of the earth to help defend myself and my people. When I was captured, I ordered them to stay behind at our home, but they are often disobedient and likely tried to follow me.nnIf they did, I fear the Bloodtotem may have captured them, or worse. In my current state, I can\'t muster the strength to find them. If you find them, it would be much appreciated.', `QuestDescription`) WHERE `ID` = 39391;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bear Huntin\'', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Bristlefur Pelts within the Fields of An\'she.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'They say a single hair from the back of a bristlefur bear is sharp enough to cut a dwarf\'s beard. But if the fur doesn\'t kill ya, the maul will.nnSome lesser hunters have been a meal for those bears. nnShow me you\'re more than a snack and bring me back a few of those bristlefur pelts.', `QuestDescription`) WHERE `ID` = 39392;
