UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Cipher of Damnation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Get Oronok and your ally to destroy the barrier, then stop Gul\'dan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your ally and I will remove this barrier now, though it will take a greater part of our strength. What lies beyond will not be easy.nnGul\'dan will have empowered an elemental lord with the Cipher, driving it insane. He will use it to destroy the link between the elements and Draenor. If you destroy that elemental, we could recover the Cipher.', `QuestDescription`) WHERE `ID` = 39394;
