UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Destroying the Competition', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Construct a Destroyer in your Shipyard and send it on a naval mission.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One battle does not win the war, Commander.nnThat Transport isn\'t gonna hold up long against this Iron Horde navy.  We are going to need another ship.  Lucky for us, a local smuggler has supplied us with the plans we need to build Destroyers.  We should construct one of these ships immediately!', `QuestDescription`) WHERE `ID` = 39401;
