UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stories of Battle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 verses of Ashilvara from Priestesses of Eyir in Skold-Ashil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The writings carried by the priestess appear to be the first part of an epic poem describing the history of Ashildir, the ancient queen of the Valkyra. nnIf Ashildir has a connection to the shieldmaidens here, you may be able to use that to your advantage. nnThe answer to her involvement likely lies within the remaining text.', `QuestDescription`) WHERE `ID` = 39405;
