UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rating Razik', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Hemet Nesingwary at his Highmountain retreat.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hemet is expecting an update on how my munitions research and development is going.nnI\'m sure you\'ll be happy to tell my boss that my latest creation worked flawlessly!nnYou can find him at his camp near the hunters\' lodge.', `QuestDescription`) WHERE `ID` = 39417;
