UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hex-a-Gone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Hexweaver Akara.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The harpies are relentless in their pursuit to control the basin. They are able to craft bags of foul magic as quickly as we can destroy them.nnThe Skyhorn cannot gain the upper hand as long as their hexweaver lives. She must be stopped.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Hexweaver Akara', `PortraitGiverName`) WHERE `ID` = 39419;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Xavius Event TRACKING', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Botanist Darkgrove', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '(PH)nDarkgrove has run out of places to hide. Now it is time to finish him off.$B$BIf we stop him now, there may be hope for this valley yet.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Ysera', `QuestCompletionLog`) WHERE `ID` = 39420;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shipyard Report', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to your shipyard in Lunarfall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander!  We have received reports from the shipyard that things are getting serious.  Can you head back to Lunarfall and check in with Merreck?  Every ship we build gives us another advantage over Gul\'dan\'s new Horde.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Return to your shipyard and meet with Merreck.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Merreck Vonder', `PortraitGiverName`) WHERE `ID` = 39422;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shipyard Report', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to your shipyard in Frostwall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander!  We have received reports from the shipyard that things are getting serious.  Can you head back to Frostwall and check in with Rolosh?  Every ship we build gives us another advantage over Gul\'dan\'s new Horde.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Return to your shipyard and meet with Rolash.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Rolosh Wavechaser', `PortraitGiverName`) WHERE `ID` = 39423;
