UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stonedark Crystal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Navarrogg\'s Stonedark Focus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Without my crystalline focus, my powers are weak. Those who captured me took it, and I know not where it is now.nnI\'m sure one of the Feltotem has it. If you find it, please return it to me.', `QuestDescription`) WHERE `ID` = 39425;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blood Debt', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Torok Bloodtotem at Torok\'s Bluff.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have proven a much greater ally than the Bloodtotem ever were. With my focus crystal, my wounds are healed. I fear Frag was too far gone to revive.nnTorok and his Bloodtotem will suffer for what they have done to us. Let\'s pay them a visit before they can mount an attack against the cave of my people.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Torok Bloodtotem', `PortraitGiverName`) WHERE `ID` = 39426;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Eagle Spirit\'s Blessing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Receive the Eagle Spirit\'s blessing at Spiritwatch Point in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The spear is linked to a spirit called Ohn\'ahra. It has been tradition for us to speak with her and receive her blessing before going after the spear. She may also impart some knowledge.nnIf you would accompany me to Spiritwatch Point, I will summon the Eagle Spirit and ask for its blessing in the coming fight.', `QuestDescription`) WHERE `ID` = 39427;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Satyr Line TRACKING', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Botanist Darkgrove', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '(PH)nDarkgrove has run out of places to hide. Now it is time to finish him off.$B$BIf we stop him now, there may be hope for this valley yet.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Ysera', `QuestCompletionLog`) WHERE `ID` = 39428;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assaulting the Haglands', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Crawliac Harpies and $2oa Skywhisker Loyalists in the Haglands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Proceed on foot into the Haglands and slay any harpies you find.$b$bQuell their numbers!$b$bWe will provide air support and force your prey to the ground where you can deal with them.$b$bShow these witches the fury of your... well... your "you."', `QuestDescription`) WHERE `ID` = 39429;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Flasking for a Favor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Barm Stonebreaker at the Ironhorn Enclave in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You know, this mixing flask didn\'t suffer terrible damage. I\'m positive it can just be repaired.$b$bI\'m no expert in glass repair, but I\'ve heard of someone who is--a tauren by the name of Barm Stonebreaker. He\'s a smith by trade, but those who know him say he was born to work glass.$b$bThose tauren don\'t work for free, so you may be in for some work yourself.', `QuestDescription`) WHERE `ID` = 39430;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mending the Filter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Try to find the whereabouts of a tailor in Val\'sharah who can help you mend the silk.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Bringing back the cloth in such a manner would not be beneficial to Deucus.$b$bPerhaps there\'s a tailor here in Val\'sharah who\'d be willing to mend it for you.$b$bThe priestess who helped you earlier may know of such a person.', `QuestDescription`) WHERE `ID` = 39431;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unknowable Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Fel-Corrupted Apexis Fragment from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The one they call Gul\'dan has ruined his own people, and now seeks to ruin what remains of mine as well. The fallen outcasts at Kra\'nak have already pledged themselves to Gul\'dan in a false promise of a return to the skies. He has given the most powerful of his minions the power of the Apexis, but twisted in a way that I cannot explain. Bring one of these fragments to me.', `QuestDescription`) WHERE `ID` = 39432;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unseen Influence', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Fel-Corrupted Apexis Fragments from any Treasure or from any Rare or Rare Elite creature in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The corruption in the Apexis has begun to affect many of my people. We are so accustomed to the power it grants us that more succumb to the whispers every day. You must bring me more samples so I can free my people from yet another curse.', `QuestDescription`) WHERE `ID` = 39433;
