UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crystal Fury', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Gelmogg.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A drogbar stonecaster known as Gelmogg entered our sacred water caverns and aims to draw its power into himself.nnWe must destroy him before he gets too powerful.nnHe is in the upper caverns.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Gelmogg', `PortraitGiverName`) WHERE `ID` = 39487;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Balance of Elements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover $1oa Empowered Crystals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The drogbar place their foul crystals in our cave to absorb the magic within, and then they collect them when they are saturated with power.nnWe must recover the crystals so the magic might dissipate and be suffused back into the waters, or else the drogbar will find ways to corrupt the magic to their own purposes.', `QuestDescription`) WHERE `ID` = 39488;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Invading Spelunkers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Drogbar Manathirsters or Violent Crageaters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The drogbar and their earthen furies have overrun the cavern. They\'re perverting the magic within and destroying the elementals that have forever dwelled in this place.nnLet\'s work together to remove them from this sacred cave.', `QuestDescription`) WHERE `ID` = 39489;
