UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden No More', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Fel Lord Caza and take his fel power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you\'ve uncovered the demons, I can sense them, too. Specifically, I sense a very powerful fel lord deeper in the cave. You need to grab his power while you still can.nnIf you can deal with their leader, we will take care of the rest of his forces in that cave.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Take his power and keep your army at the Illidari Foothold from being ambushed.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Fel Lord Caza', `PortraitGiverName`) WHERE `ID` = 39495;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Flow of the River', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Angler Creel in Whitewater Wash.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We can leave Farmer Maya in charge of the farmland now that the greatest threat has been reduced.nnBut we aren\'t out of hot water just yet, $n. The fisheries are just as important as our fields, and they are in even greater danger than the farm if what Angler Creel says is true.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Angler Creel', `PortraitGiverName`) WHERE `ID` = 39496;
