UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'High Water', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Jale Rivermane at Riverbend.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Riverbend! Is that what the Underking said?$b$bThat is my home and the place where we store our winter supplies. We must make it there at all speed and warn them.$b$bMeet me there.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Jale Rivermane at Riverbend.', `QuestCompletionLog`) WHERE `ID` = 39498;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Well of Souls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Soul Remnants from Gorefiend in Hellfire Citadel on Normal difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you defeat Gul\'dan\'s minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let\'s say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.', `QuestDescription`) WHERE `ID` = 39499;
