UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fel Spire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Fel Essences from Mannoroth in Hellfire Citadel on Normal difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul\'dan works his dark magic, wouldn\'t it? But while demonic power fills the halls, my magic cannot penetrate to such heights.$B$BIf only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....', `QuestDescription`) WHERE `ID` = 39502;
