UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloodied Blades of Zeth\'Gol', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Bleeding Hollow Ritual Blades from Bleeding Hollow orcs in Zeth\'Gol.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Them Bleeding Hollow orcs do blood magic - like voodoo but it hurt more. They cut their own flesh. Most of \'em carry curved ritual blades for carvin\' themselves up.$b$bBring me them blades, commander. We can turn their power against \'em.', `QuestDescription`) WHERE `ID` = 39509;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Little Wetwork', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Iron Horde Naval Manifests from forces in Ironhold Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What be left of the Iron Horde is comin\' to Tanaan through Ironhold Harbor. If we knew who was comin\' and when, we could use our shipyard to cause some chaos.$b$bGo to Ironhold Harbor and fish up some intelligence!', `QuestDescription`) WHERE `ID` = 39510;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blood of Fallen Brothers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Vials of Fel Blood from fel orcs throughout Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Orcs that drink Gul\'dan\'s poison turn into fel beasts. Soulless savages.$b$bLady Liadrin an\' the Blood Knights think maybe there be a way back. They be wantin\' samples of blood from freshly turned orcs. Get their blood, $n!$b$bYou be findin\' fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil\'jaeden is where you find the most.', `QuestDescription`) WHERE `ID` = 39511;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secrets of the Shadow Council', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Shadow Council Missives from shadow council representatives in the Ruins of Kra\'nak or the Throne of Kil\'jaeden.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Gul\'dan be growin\' his Shadow Council like a spider spin a web. But some of this new blood, they not so smart. They write down the secrets but don\'t burn \'em.$b$bCatch his minions out in the open and bring their secrets back to me! You find them workin\' with the arakkoa in da Ruins of Kra\'nak or atop the Throne of Kil\'jaeden.', `QuestDescription`) WHERE `ID` = 39512;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Disarming Sha\'naar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Unrefined Draenic Crystals from the mines located within the Temple of Sha\'naar in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Draenei at the Temple of Sha\'naar would mine these mountains for perfect crystals used to channel their magics. Now demons be lootin\' the place. We gotta keep those crystals out of demonic hands, commander!$b$bAttack the mines behind the temple and grab them crystals.', `QuestDescription`) WHERE `ID` = 39513;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Harnessing Their Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Wargronn Harness from an Iron Wargronn at the Iron Front in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ol\' Grommash Hellscream found a way to weaponize the gronn. Vol\'jin wants to know how.$b$bTravel to the Iron Front and kill one of them big beasties, then bring back its war harness. You might be needin\' help.', `QuestDescription`) WHERE `ID` = 39514;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vengeance Will Be Mine!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Teach the Vengeance specialization to your assembled demon hunters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be.nnQuickly, $n, teach us what you have learned.', `QuestDescription`) WHERE `ID` = 39515;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cry Havoc and Let Slip the Illidari!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Teach the Havoc specialization to your assembled demon hunters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be.', `QuestDescription`) WHERE `ID` = 39516;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel Secrets - Havoc Spec Tracking Event', `LogTitle`) WHERE `ID` = 39517;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel Secrets - Vengeance Spec Tracking Event', `LogTitle`) WHERE `ID` = 39518;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demonslayer of Tanaan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $oa demons in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Look to the north, $c. The sky is turning a sickly green. Gul\'dan\'s summoning portals are not yet at full strength, but already the stench of demon is on the wind.$b$bSlay them, $n. Destroy as many beasts as you can before they find a way to Azeroth. The Temple of Sha\'naar is infested, as is the Throne of Kil\'jaeden, although you may find others wandering about the jungle.', `QuestDescription`) WHERE `ID` = 39519;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ashran Dominance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Alliance at the event locations in Ashran and kill Grand Marshal Tremblade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Grand Marshal Tremblade leads the Alliance forces in Ashran.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Grand Marshal Tremblade', `PortraitGiverName`) WHERE `ID` = 39520;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Continue the Domination', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Alliance at the event locations in Ashran and kill Grand Marshal Tremblade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Grand Marshal Tremblade leads the Alliance forces in Ashran.', `PortraitGiverText`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Angry Zurge in the Horde base inside Ashran.', `QuestCompletionLog`) WHERE `ID` = 39521;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Continue the Domination', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won\'t put up with their aggression.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Volrath leads the Horde forces in Ashran.', `PortraitGiverText`) WHERE `ID` = 39523;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Slay Them All!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 200 enemy players.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Find them, hunt them, kill them. Teach our enemies a lesson they\'ll never forget.', `QuestDescription`) WHERE `ID` = 39524;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Slay Them All!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 200 enemy players.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Horde encroachment cannot be tolerated. Dwindle their numbers to the ground!', `QuestDescription`) WHERE `ID` = 39525;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pressing the Attack', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 2 bonus objective areas within Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We got Gul\'dan\'s minions on the run, commander! If you be feelin\' it, we should put some pressure on some of his other strongholds as well.', `QuestDescription`) WHERE `ID` = 39526;
