UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tooth and Claw', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Tanaan Jungle Teeth from the various wildlife within Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Beyond the meager shelter of these fortress walls, the jungle closes in. Can you feel it? That is the untamed wilderness, $c, calling forth our primal instincts. There is no better way to feel alive than to court death.$b$bJoin me in the hunt, $n! Collect teeth from the wild beasts. The ravagers in Thornmire, the raptors in Zorammarsh - even the sea creatures along the strand and the little podling plants themselves all have teeth. Bring them to me!', `QuestDescription`) WHERE `ID` = 39529;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Forgening', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Master Smith Helgar in the Forge in Valhallas.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your new weapon is very powerful, but my smiths have mastered crafting over thousands of years. Speak to Master Smith Helgar and see what improvements can be made.', `QuestDescription`) WHERE `ID` = 39530;
