UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bringing Down the Iron Horde', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $oa Iron Horde orcs in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ever since the fall of Blackrock Foundry, Gul\'dan has been turning the Iron Horde into... something worse. The orcs who once flocked to Grommash\'s banner, through either fear or thirst for revenge, are now embracing the fel.$b$bWade into the battlefields of Tanaan and lay waste to Gul\'dan\'s forces. Orc or fel orc makes no difference. Gut what remains of the Iron Horde!', `QuestDescription`) WHERE `ID` = 39532;
