UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rumble in the Jungle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the three arena champions of Fangri\'la.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Dem fancy cat-men gotta be shown who is da boss \'round dese parts. Kill all their champions, and ya will earn da respect of all creatures in da jungle.nnY\'gonna need dese totems to draw dem out.', `QuestDescription`) WHERE `ID` = 39565;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Search for Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Look for ancient relics  on the shoreline of Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you were out gallivanting, did you notice any lost relics around Azsuna? My sources tell me there are treasures to be found. These rumors merit investigation!', `QuestDescription`) WHERE `ID` = 39566;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloodied Blades of Zeth\'Gol', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Bleeding Hollow Ritual Blades from Bleeding Hollow orcs in Zeth\'Gol.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bleeding Hollow clan is infamous for their blood rituals. The brutes carve sigils into their flesh and create potions from the blood of their strongest warriors.$b$bThe curved ceremonial blades they use have a power all their own. Gather some of these for me. We will deprive them of these weapons and learn something about our enemy at the same time.', `QuestDescription`) WHERE `ID` = 39567;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Little Wetwork', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Iron Horde Naval Manifests from forces in Ironhold Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The shattered remnants of the Iron Horde pour into Tanaan through Ironhold Harbor. If we knew more about their fleet we could dispatch countermeasures from your shipyard in Shadowmoon.$b$bPerhaps you could gather some naval intelligence for our cause?', `QuestDescription`) WHERE `ID` = 39568;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Breaking Their Fel Bonds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Vials of Fel Blood from fel orcs throughout Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Gul\'dan\'s fel poison turns already ferocious orcs into hateful, vicious creatures with no soul. But were he here to guide us, Prophet Velen wouldn\'t give up on the whole race. If you could find samples of their blood, maybe we can reverse the process?$b$bYou\'ll find fel orcs all over Tanaan, but the Iron Front, the Fel Forge, and the Throne of Kil\'jaeden are the most densely populated.', `QuestDescription`) WHERE `ID` = 39569;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secrets of the Shadow Council', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Shadow Council Missives from Shadow Council representatives in the Ruins of Kra\'nak or the Throne of Kil\'jaeden.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Gul\'dan has been building a spy network for himself - the so-called "Shadow Council". As they struggle to control Tanaan, the Shadow Council has grown careless. Their members are out in the open, recruiting arakkoa at the Ruins of Kra\'nak or summoning demons at the Throne of Kil\'jaeden.$b$bFind members of the Shadow Council and acquire any intelligence they were foolish enough not to destroy!', `QuestDescription`) WHERE `ID` = 39570;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Disarming Sha\'naar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Unrefined Draenic Crystals from the mines located within the Temple of Sha\'naar in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Draenei at the Temple of Sha\'naar would mine these mountains for perfect crystals to power our arcane devices. Sadly, the temple is lost to us - we have been betrayed by the Sargerei.$b$b$n, it is imperative that you venture into those mines and secure those crystals before the Sargerei use them in their demonic rituals. If you must kill our former brothers and sisters, so be it.', `QuestDescription`) WHERE `ID` = 39571;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moozy\'s Adventure', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Moozy to Sella Waterwise at Whitewater Wash.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Moozy is floating down the river and must be reunited with his mother.>', `QuestDescription`) WHERE `ID` = 39572;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Harnessing Their Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Wargronn Harness from an Iron Wargronn at the Iron Front in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have always believed that the primal creatures of Draenor could not be tamed. And yet, the Iron Horde found a way to weaponize the gronn. It would be to our advantage to learn how.$b$bVenture to the Iron Front, slay a Wargronn, and retrieve its harness. You may want to find help.', `QuestDescription`) WHERE `ID` = 39573;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pressing the Attack', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 2 bonus objective areas within Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Gul\'dan\'s minions are on the run, commander! If you have the strength, now would be an opportune time to press forward and assault some of his other strongholds.', `QuestDescription`) WHERE `ID` = 39574;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Path of Huln', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Spiritwalker Ebonhorn on the Path of Huln.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Armies are vital to the success of a war. But so are symbols.$b$bFor our people, few things make for a better symbol than the blessings of our most eldest ancestors.$b$bMayla must walk the Path of Huln.$b$BThe path is dangerous, and she may only bring two people with her: a spiritwalker to guide her and a champion to protect her.$b$bWill you be the champion?', `QuestDescription`) WHERE `ID` = 39575;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Echoes of Deathwing', `LogTitle`) WHERE `ID` = 39576;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Ancient Secret', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist Spiritwalker Ebonhorn in Neltharion\'s Vault.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Before Mayla may be pronounced High Chieftain, there is one more vision she must see. I wish to show you as well.$b$bIt is an ancient secret, handed down along the Highmountain bloodline. I ask for your discretion in keeping it that way.', `QuestDescription`) WHERE `ID` = 39577;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Titanic Showdown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and aid the spirit of Huln Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The tale of Huln did not end with him acquiring the Hammer of Khaz\'goroth.$b$bNo. For that part, we must venture deeper into this cavern. A final brazier awaits us ahead.$b$bCome, let us see what happened next.', `QuestDescription`) WHERE `ID` = 39578;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Backdoor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escape the Vault.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This will take Mayla some time to adjust to.$b$bThat being said, we should return to Thunder Totem.$b$bJust south of here is a tunnel that should take us through the old drogbar slave enclave and then to an opening beyond.$b$bWe keep a small Skyhorn outpost there to watch and ensure nothing enters or leaves this vault without us knowing about it. They should be able to fly us back.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Mayla Highmountain at Obsidian Overlook.', `QuestCompletionLog`) WHERE `ID` = 39579;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The High Chieftain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Mayla Highmountain at Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I understand what Ebonhorn has been trying to tell me for a while now.$b$bOur people do not need a hammer, we need a leader. One willing to stand against any threat, even if they are terrified to do so.$b$bAnd between you and me, I am definitely terrified, but resolved.$b$bLet us return to Thunder Totem and prepare ourselves for war.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Mayla Highmountain at Thunder Totem.', `QuestCompletionLog`) WHERE `ID` = 39580;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demonslayer of Tanaan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $oa demons in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Demons! Hate \'em!$b$bGul\'dan is spinning up more summoning portals with each passing hour. There\'s only one way to stem the tide, $n.$b$b<Parvink smashes her gauntleted fist against her open palm.>$b$bSmash \'em!$b$bThe Temple of Sha\'naar is a good place to start, or head up to the Throne of Kil\'jaeden if you\'re looking for a real challenge.', `QuestDescription`) WHERE `ID` = 39581;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tooth and Claw', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $oa Tanaan Jungle Teeth from the various wildlife within Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These wimps lugging wood around the jungle keep talking about how dangerous it is. You know, between the ravager den to the south or the raptors that stalk Zorammarsh - hey, even the beach creatures or podlings have teeth!$b$bWhat do you say you and I do a little hunting? Collect teeth from wild beasts. The bigger the beast, the more teeth. Meet me back here and we\'ll compare our haul!', `QuestDescription`) WHERE `ID` = 39582;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bringing Down the Iron Horde', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $oa Iron Horde orcs in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ever since we humiliated \'em at Blackrock Foundry, the Iron Horde has been on the run. Gul\'dan is converting them all into fel orcs, but I ain\'t scared. A bloodlusting orc is twice as strong but twice as stupid.$b$bHey! Let\'s wade into the battlefields of Tanaan and lay waste to as many orcs as we can. Orc or fel orc - doesn\'t matter to me.', `QuestDescription`) WHERE `ID` = 39586;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'They Will Pay With Blood', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Feltotem Tauren.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The tauren go too far. I did not escape their outpost for fear that they would attack the cave and slaughter my people.nnIt looks like they planned to do it all along. Slay some of the Feltotem. Thin the herd.', `QuestDescription`) WHERE `ID` = 39588;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ahead of the Game', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the heads of the Gutspill, Rumblehoof, and Felskorn champions in Valley of the Sword.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The watcher Yotnar keeps the vault, and he is a fickle one. Challengers come from far and wide seeking the trials, but the watcher chooses not to see.nnIf you wish to catch his eye, show him you are worth being seen.nnSome of these challengers await in camps throughout the Valley of the Sword. Bring their heads to Yotnar, so that he may see them, and you.', `QuestDescription`) WHERE `ID` = 39590;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Trial of Valor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Power up the archive device and view the holographic record for the Trial of Valor in the Terrace of the Watchers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To seek the Aegis of Aggramar, a champion must complete three great trials before riding into glorious battle through the Gates of Valor. Here you will find the knowledge of the trials you must seek out, as well as the first challenge you must face.nnAbove us, adorning the central plateau, you will find the archive for the Trial of Valor. Seek it out, and learn where your path leads.', `QuestDescription`) WHERE `ID` = 39591;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Trial of Will', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Power up the archive device and view the holographic record for the Trial of Will in the Terrace of the Watchers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Upon the highest point of the plateau above, you will find the archive device for the Trial of Will. Seek it out to learn what awaits you in Thorim\'s Peak. nnBe on your guard, outsider. The one called Skovald has left behind many of his army, and they will no doubt be unfriendly.', `QuestDescription`) WHERE `ID` = 39592;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Shattered Watcher', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the pieces of Yotnar\'s body from the Terrace of the Watchers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When your adversary - the one called Skovald- completed his first trial, he used his ill-begotten powers to sunder my physical body.nnI cannot allow a contender to pass through the vault while I remain unwhole. nnHis forces have no doubt scattered my pieces through the plateau which they currently desecrate. Bring them back to me, so that I may properly guide your trial.', `QuestDescription`) WHERE `ID` = 39593;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Trial of Might', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the archive device to learn about the Trial of Might.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I owe you my gratitude for helping make me whole again, outsider. It is clear that you are worthy to take on the trials. nnGo now into the vault. There you will find the archive for the first trial you must undertake.nnI will meet you inside.', `QuestDescription`) WHERE `ID` = 39594;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blood and Gold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 7 Challenger\'s Tributes from Valley of the Sword.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The challengers gathered in the Valley of the Sword have brought with them offerings to the watchers of the vault. nnIt might be a good idea to take some of these offerings with you to help in appeasing Yotnar.', `QuestDescription`) WHERE `ID` = 39595;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Val\'sharah - Vale - Vignette: Perrexx - TRACKING - twh', `LogTitle`) WHERE `ID` = 39596;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Blessing of the Watchers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Yotnar to receive the blessing of the watchers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As is your due for passing the Trial of Might, I will grant you the blessing of the watchers. nnFurthermore, to aid you in your trials to come, I will bestow upon your artifact the power of the vault\'s keeper. May it serve you well in your time of need.nnSpeak to me when you are ready to receive this gift.', `QuestDescription`) WHERE `ID` = 39597;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'I Sunk Your Battleship', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Vindicator Krethos at Lion\'s Watch in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde.nnWe have heard reports from Tanaan that a new Alliance faction can supply us with the plans to build battleships.  Head out there as soon as you can and investigate!', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Find Vindicator Krethos at Lion\'s Watch in Tanaan Jungle.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Vindicator Krethos', `PortraitGiverName`) WHERE `ID` = 39601;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where\'s Lyndras: Sewer Sleuthing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the sewers for clues as to where Lyndras has gone.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Linzy said that Lyndras escaped down into the sewers of Dalaran. Surely there must be a clue down there as to his whereabouts.$b$bHopefully he hasn\'t caused any more commotion amongst the citizens of Dalaran.', `QuestDescription`) WHERE `ID` = 39602;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'I Sunk Your Battleship', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Shadow Hunter Denjai at Vol\'mar in Tanaan Jungle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, we must expand our fleet if we hope to stand a chance against the Iron Horde.nnWe have heard reports from Tanaan that a new Horde faction can supply us with the plans to build battleships.  Head out there as soon as you can and investigate!', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Find Shadow Hunter Denjai at Vol\'mar in Tanaan Jungle.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Shadow Hunter Denjai', `PortraitGiverName`) WHERE `ID` = 39604;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where\'s Lyndras: Downward Spiral', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Continue following Lyndras\' trail.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Flitz mentioned a manhole near Violet Hold, perhaps that would be the best place to pick up Lyndras\' trail.', `QuestDescription`) WHERE `ID` = 39605;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasures of Deathwing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defend Brann Bronzebeard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Neltharion\'s Vault? Well why didn\'t that spiritwalker just say so?$b$bWhen we were jumpin\' into the cavern I thought I saw a chamber up high that might have what we are after.$b$bHave a look around this place while I see if I can\'t find a way up.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Brann Bronzebeard in Neltharian\'s Vault.', `QuestCompletionLog`) WHERE `ID` = 39606;
