UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Calibration Experts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Uncalibrated Malloric Burettes to skilled alchemists for calibration.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It will take the cooperation of several highly skilled sorts to calibrate these burettes.$b$bMyshalla Streambreeze in Feralas has demonstrated admirable attention to detail.$b$bI loathe Ironforge, but a resident named Krimple Proxmeasure is known for his precision.$b$bAnd while I\'d never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair... mostly.', `QuestDescription`) WHERE `ID` = 39645;
