UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where Are the Children?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Save 6 Kidnapped Children.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The children have gone missing!$B$BThat horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them!$B$BOur scouts have spotted him over in Frostfire Ridge.', `QuestDescription`) WHERE `ID` = 39648;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Menacing Grumplings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 8 Grumplings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The grumplings are horrid creatures. They\'re the ones doin\' the dirty work for Grumpus.$B$BIf you\'re able to remove the threat I\'m sure rescuing the children won\'t be much of a problem.', `QuestDescription`) WHERE `ID` = 39649;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grumpus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Grumpus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One of Draenor\'s oldest stories is the legend of Grumpus.$B$BThe story tells of a mean-spirited brute that would come in the night, in the dead of winter, and kidnap children that misbehaved. Back at his lair, he would present them with awful toys, and use their tears to spawn his minions.$B$BBut Grumpus is no legend, he\'s real and he\'s taken our children! Please, you have to slay him!', `QuestDescription`) WHERE `ID` = 39651;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where Dragons Rule', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Vethir to fly to the top of Thorim\'s Peak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thanks to your help, Thrymjaris was able to escape the clutches of that vile demon. She bid me wait for you, so that I could take you to her once you had finished dispatching your foes.nnShe has gathered our brood at the top of Thorim\'s Peak to prepare for a counterattack. nnWould you join us?', `QuestDescription`) WHERE `ID` = 39652;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Odyn and the Valarjar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Danica to see Odyn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Fear not, mortal, you are not dead. I was directed to collect you before your demise by Odyn himself.nnI will take you to Odyn now, follow me.', `QuestDescription`) WHERE `ID` = 39654;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'If At First You Fail, Try Again!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Yanas Seastrike at the dry docks and build another Destroyer.  Once the Destroyer is complete, send it on a new mission.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Looks like that Submarine had a bit more firepower than we thought!  They used First Strike to hit us before we even saw it coming.nnLosing ships is a part of naval battles, Commander.  Luckily, we were prepared for this exact sort of situation.  Speak with Yanas down at the dry docks, he should be able to help us quickly produce another Destroyer.  Head back here when the ship is complete, we will have a new mission ready for you.', `QuestDescription`) WHERE `ID` = 39655;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wolf Pack Attack', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Shoot the Critter Hand Cannon near wolf packs so that they scatter, allowing the packleaders to be singled out.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s time to attack the pack! I\'ve preloaded the hand cannon. All you have to do is point and shoot.nnThe critters should survive the blast and hit the ground running. The howlers will be distracted by the critters, allowing you to focus on killing the packleaders.nnHappy hunting!', `QuestDescription`) WHERE `ID` = 39656;
