UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lifespring Cavern', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Jale Rivermane at Lifespring Cavern.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The drogbar have taken over my cavern. It is where we Rivermane practice our water magic and get much of the purest healing water in Highmountain.nnMeet me there and we will cleanse that sacred place of these dark-dwellers.', `QuestDescription`) WHERE `ID` = 39661;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'On Felbat Wings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Grab a felbat from Illidari Whitemoon and fly up to the Fel Hammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time. We have dealt the Legion\'s forces a crippling blow from which they will never recover.nnQuickly, let us mount up and take the fight to Tyranna\'s command center.', `QuestDescription`) WHERE `ID` = 39663;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A True Naval Commander', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Install the Blast Furnace equipment on your ship and complete the Naval Blockade mission.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Yes!  Those are the blueprints I misplaced when I was fishing last week.  These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships.  This should let us break the naval blocade and expand our control of the Draenor seas.', `QuestDescription`) WHERE `ID` = 39665;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Equipping Our Fleet', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Salty Jorren at the docks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war.  Find Salty Jorren down at the docks, he should be able to help us out.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Find Salty Jorren on the docks.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Salty Jorren', `PortraitGiverName`) WHERE `ID` = 39666;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where\'s Lyndras: Leyflame Larceny', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ask the Violet Hold guards about Lyndras.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The guards here must have seen Lyndras come through. The trail of ley dust isn\'t exactly hard to miss either.$B$BPerhaps one of the guards knows what became of Lyndras.', `QuestDescription`) WHERE `ID` = 39667;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'What Horrible Presents!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy 5 Unusual Gifts.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That mean old Grumpus has amassed a collection of odd gifts. He\'s deliberately trying to crush the spirit of children everywhere by giving out the worst presents imaginable.$B$BTake this spirit bomb. Toss it on some of Grumpus\'s unusual gifts and take them out for good!$B$BWe\'re in this together, $n. Now go and save the spirit of the holiday!', `QuestDescription`) WHERE `ID` = 39668;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Critter Scatter Shot', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Catch rabbits in Sunfrost Glade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The howlers in these hills travel in packs. Three against one isn\'t a fight I want to pick.nnLuckily those wolves are no match for my engineering skills! I just put the finishing touches on the prototype of a device that will help scatter the pack. All I need now is some ammo...nnSnatch me some rabbits from the meadow south of here, and I\'ll let you be the first to try out the hand cannon.', `QuestDescription`) WHERE `ID` = 39670;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Guards and Criswold', `LogTitle`) WHERE `ID` = 39671;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'If At First You Fail, Try Again!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Solog Roark at the dry docks and build another Destroyer.  Once the Destroyer is complete, send it on a new mission.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Looks like that Submarine had a bit more firepower than we thought!  They used First Strike to hit us before we even saw it coming.nnLosing ships is a part of naval battles, Commander.  Luckily, we were prepared for this exact sort of situation.  Speak with Solog down at the dry docks, he should be able to help us quickly produce another Destroyer.  Head back here when the ship is complete, we will have a new mission ready for you.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Find Solog Roark at the dry docks.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Solog Roark', `PortraitGiverName`) WHERE `ID` = 39674;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Equipping Our Fleet', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Kronk Rustspark at the docks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander, our fleet is going to require some custom naval equipment if we hope to stand a chance in this war.  Find Kronk Rustspark down at the docks, he should be able to help us out.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Find Kronk Rustspark at the dry docks.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Kronk Rustspark', `PortraitGiverName`) WHERE `ID` = 39675;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A True Naval Commander', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Install the Blast Furnace equipment on your ship and complete the Naval Blockade mission.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Yes!  Those are the blueprints I misplaced when I was fishing last week.  These instructions match my prototype equipment one for one. Take this Blast Furnace and install it on one of our ships.  This should let us break the naval blockade and expand our control of the Draenor seas.', `QuestDescription`) WHERE `ID` = 39676;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Between the Hammer...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Saris\' Hammer back to his shop.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I fear that my spirit will remain bound to this place unless I am made whole again.$b$bLong ago, I discovered a cave near the coast behind Black Rook Hold. I explored the cave only to find an abominable creature that attacked me, causing me to drop my hammer as I fled.$b$bI need that hammer back if I am to be at peace.', `QuestDescription`) WHERE `ID` = 39680;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Properties of Leystone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Observe Alard as he attempts to work with the leystone ore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve never seen anything like this "leystone" ore. It\'s light, like mithril, but it carries much more of a magical energy... more even than saronite or elementium.$b$bLet\'s try making something with it. How about a nice pair of gauntlets?', `QuestDescription`) WHERE `ID` = 39681;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grand Theft Felbat', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ride a felbat to the upper vault.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You heard what Maiev said. We need to get out of here.nnThere is an elevator shaft at the far end of these caverns. Let us make our way there.', `QuestDescription`) WHERE `ID` = 39682;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Forged in Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Immolanth and take his power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. nnSomehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long.nnThe demon\'s power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining.nnI believe that person could be you, $n.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Immolanth is full of pure, coalesced fel power.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Immolanth', `PortraitGiverName`) WHERE `ID` = 39683;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Beam Me Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Break Glazer\'s shield.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To the east is an intricate prison chamber designed to contain the beholder, Glazer.$B$BIt began malfunctioning shortly after the breach.$B$BYou will need to rotate the mirrors in the room to focus an energy beam onto the creature. Otherwise, we cannot break through Glazer\'s impenetrable shield.nnHurry. Altruis went ahead to assist the others, but we are losing the fight.', `QuestDescription`) WHERE `ID` = 39684;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Frozen in Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the Countermeasures in the Vault of Ice.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Wardens kept all kinds of dangerous monsters locked up within this Vault. Now that Gul\'dan\'s forces have breached the walls, it\'s proving rather... inconvenient.nnMany of our forces are occupied with containing a fearsome magma destroyer in the southern chamber. With us freshly awoken from stasis, we don\'t have the means to take it down. However, we might be able to reactivate the room\'s containment field.nnGo join up with Kayn. Do whatever it takes to seal that chamber!', `QuestDescription`) WHERE `ID` = 39685;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'All The Way Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ride the elevator to the Hall of Judgment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Kor\'vas went ahead to meet up with Kayn and Altruis.nnStep onto the elevator when it arrives, and meet them in the Hall of Judgment above.', `QuestDescription`) WHERE `ID` = 39686;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Between Us and Freedom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Bastillax and take his power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The last of our survivors have fought their way into the final chamber ahead.nnOnly one obstacle stands between us and the vault\'s exit - the leader of this demon invasion, Bastillax.nnKill him, take his power, and claim our freedom.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'He guards the vault exit.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Bastillax', `PortraitGiverName`) WHERE `ID` = 39688;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Illidari, We Are Leaving', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archmage Khadgar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms.n nHowever, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion.nnI only ask that you come with me. Further instructions await you on the other side.', `QuestDescription`) WHERE `ID` = 39689;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Illidari, We Are Leaving', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archmage Khadgar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms.n nHowever, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion.nnI only ask that you come with me. Further instructions await you on the other side.', `QuestDescription`) WHERE `ID` = 39690;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Call of War', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Jace Darkweaver in Stormwind Keep.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Welcome to Stormwind, the heart of the human kingdom. But today, sorrow grips this bastion of the Light.$b$bKing Varian Wrynn has fallen in battle, leaving the crown to his son Anduin.$B$BThe leaders of the Alliance have gathered to pay their respects. No doubt they will have need of your unique skills.$b$bYou will find the king upon the throne of Stormwind Keep, attended by one of your fellow Illidari. I am needed in Dalaran.$b$bGood luck, $p.', `QuestDescription`) WHERE `ID` = 39691;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Call of War', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to the Warchief.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Welcome to Orgrimmar, the Horde\'s seat of power.$B$BEnter Grommash Hold straight ahead, and make your introduction to Warchief Vol\'jin.$B$BHe is expecting you.', `QuestDescription`) WHERE `ID` = 39692;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Between Us and Freedom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Bastillax and take his power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The last of our survivors have fought their way into the final chamber ahead.nnOnly one obstacle stands between us and the vault\'s exit - the leader of this demon invasion, Bastillax.nnKill him, take his power, and claim our freedom.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'He guards the vault exit.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Bastillax', `PortraitGiverName`) WHERE `ID` = 39694;
