UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Master vs. Commander', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the legendary shipyard missions until you defeat the Master\'s Call and acquire a Draenic Sea Chart.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve been doing a little digging - or whatever you call digging in naval terms. Snorkeling?$b$bGul\'dan has sent his most powerful flagship on a scouting mission to the four corners of Draenor. He is mapping out all the oceanic ley-line conjunctions. This is information that I could use to upgrade your ring... But in Gul\'dan\'s hands, it could be catastrophic.$b$bScramble the fleet, $n! Hunt down his infamous flagship, "The Master\'s Call," and steal that map before they complete their mission. Hurry!', `QuestDescription`) WHERE `ID` = 39697;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Making the Rounds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Lady Sylvanas Windrunner and prepare her ship to set sail.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you can see, we have spared no expense in showing our support of your great quest.$B$BFinal preparations are being made - come, walk with me.', `QuestDescription`) WHERE `ID` = 39698;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ironhorn Leysmithing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather scrap metal around the Ironhorn Enclave. Then use the Greenhoof\'s Anvil and Forge to craft a Scrapmetal Handguard, a Scrapmetal Palmplate, a Scrapmetal Cuffplate, and $4oa Scrapmetal Fingerplates.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I sense great strength in you, yet you refuse to wield it. We Ironhorn use double the metal of any normal blacksmith to craft our wares.$b$bThere is also a technique in how you hammer such quantities of leystone that I will instruct you on.$b$bUse our scrap metal and hammer out the pieces for a gauntlet. I will weld the pieces together when you are finished.', `QuestDescription`) WHERE `ID` = 39699;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Legend of Black Rook Hold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Black Rook Hold and search for Saris Swifthammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, have you heard of Saris Swifthammer?$b$bHe was a legendary blacksmith amongst the elves of Black Rook Hold. I wonder if any of his research still exists.$b$bI want you to travel there and see if you can discover anything about Saris, or see if he left anything we can research here at my shop.', `QuestDescription`) WHERE `ID` = 39702;
