UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where Are the Children?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help save the children.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The children have gone missing!$B$BThat horrible Grumpus has been making his way throughout Draenor, snatching up children. Please save them!$B$BOur scouts have spotted him over in Frostfire Ridge.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Missing children rescued.', `QuestCompletionLog`) WHERE `ID` = 39714;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Menacing Grumplings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Remove the grumpling threat.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The grumplings are horrid creatures. They\'re the ones doin\' the dirty work for Grumpus.$B$BIf you\'re able to remove the threat I\'m sure rescuing the children won\'t be much of a problem.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Grumpling threat removed.', `QuestCompletionLog`) WHERE `ID` = 39715;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Smashing Squashlings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 6 Growing Squashlings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bonefleet once raided trading ships traveling the waters of Draenor. One such ship carried farming supplies intended for Elodor.$B$BNow, they use these supplies to sow their plague into our earth. From the putrid mounds sprout vegetative horrors. These abominations must be destroyed, before they can spread across the landscape.', `QuestDescription`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Izzy Hollyfizzle', `PortraitTurnInName`) WHERE `ID` = 39716;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scouting Mission Complete', `LogTitle`) WHERE `ID` = 39717;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Paradise Lost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar at Krasus\' Landing in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Khadgar was planning an expedition to Azsuna - you should seek him out at Krasus\' Landing in Dalaran immediately.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Lord Grayson Shadowbreaker', `PortraitGiverName`) WHERE `ID` = 39718;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mutiny on the Boneship', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Bonerender.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Each year, around this time, there is a strange surge of spiritual energy across Draenor. Beckoned by this phenomenon, a ghastly fleet of undead pirates emerges from the mist. We call it the Bonefleet.$B$BThe Bonefleet is led by a savage pirate known as Bonerender. He seeks nothing more than the complete destruction of all of the living of Draenor.$B$BSeek out Bonerender and defeat him, before he sails back into the mist once again.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Captain Bonerender', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Izzy Hollyfizzle', `PortraitTurnInName`) WHERE `ID` = 39719;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Foul Fertilizer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy 8 kegs of Dread Fertilizer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bonefleet wants nothing more than to spread their undead curse onto dry land. Like a sickness, it will slowly overtake the landscape if left unchecked.$B$BThe stench of undeath permeates the barrels of fertilizer they use to sow their dread crops. They are the source of the spreading plague, and must be destroyed.', `QuestDescription`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Izzy Hollyfizzle', `PortraitTurnInName`) WHERE `ID` = 39720;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Culling the Crew', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy 12 Boneship crew members.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If we\'re going to protect Draenor from the Bonefleet menace, we\'ll need to thin out the crew.$B$BSee to a swift reduction in their numbers, and we might just push them back into the sea for another year.', `QuestDescription`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Izzy Hollyfizzle', `PortraitTurnInName`) WHERE `ID` = 39721;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Forging New Strength', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Imbue your weapon with a new power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Even the most nefarious Legion lords fear your presence on the battlefield. Yet they are relentless, fashioning ever more terrible horrors and fiends in hopes of countering your might.$B$BHighlord, we must augment your power to maintain our edge over the enemy.$B$BThe altar before you holds within it the essence of the countless heroes of the Light buried in these sacred halls. Place your weapon upon the altar and imbue it with new strength.', `QuestDescription`) WHERE `ID` = 39722;
