UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '...And the Anvil', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Black Rook Breastplates from the elves of Black Rook Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you truly wish to see my work then you\'ll have to go and retrieve it as my shop has been raided of everything I\'ve made.$b$bThe breastplates of the Black Rook soldiers were one of my greatest accomplishments. They\'re light, yet strong and offer great mobility$b$bRelinquish my cursed brethren of their breastplates and bring them back to me. I will explain the finer points of how I made them upon your return.', `QuestDescription`) WHERE `ID` = 39726;
