UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Tranquil Forest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archmage Khadgar on Krasus\' Landing in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Khadgar sent word about Val\'sharah not long ago. It sounds like he has good news.$B$BYou should meet him on Krasus\' Landing in Dalaran as soon as you are able.', `QuestDescription`) WHERE `ID` = 39731;
