UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Lone Mountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Warbrave Oro at Krasus\' Landing in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our sources tell us that a Highmountain tauren emissary has recently arrived in Dalaran. We don\'t know his intentions, but his people could be an invaluable contact in the region.$B$BKhadgar is greeting the emissary at Krasus\' Landing in Dalaran - you should seek him out.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Lord Grayson Shadowbreaker', `PortraitGiverName`) WHERE `ID` = 39733;
