UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Ring Unbroken', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Aid the shaman of the Earthen Ring at the Maelstrom. Stormcaller Mylra will fly you there from Krasus\' Landing in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our defeat at the Broken Shore was decisive. The Burning Legion has a foothold on Azeroth, and the best of our armies are retreating in tatters.$b$bThe elders of the Earthen Ring have called an emergency council near the heart of our world - the Maelstrom. $n, your triumphs throughout Azeroth and Draenor are the stuff of legend. We need you more than ever.$b$bJoin me at the Maelstrom. Stormcaller Mylra will be flying there shortly - find her at Krasus\' Landing here in Dalaran.', `QuestDescription`) WHERE `ID` = 39746;
