UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Sound Plan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your first assault point on the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion still believes us crippled from the Broken Shore. They think we are unable to fight back.$B$BLet\'s prove them wrong.$B$BWe\'ve been hard at work mapping out the Broken Isles, learning everything we can about each region for our imminent assault.$B$BOnce you\'ve had a chance to peruse the map, you should leave for Dalaran at once and charge into the maw of the beast.$B$BWe will end this madness for good. Light help us all.', `QuestDescription`) WHERE `ID` = 39756;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keeping Your Edge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Grand Master Siegesmith Corvus in Acherus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, Deathlord. The blades you hold, while magnificent, have much untapped potential. As you harvest the souls of your enemies their power will continue to grow.$b$bGrand Master Corvus has studied new techniques that may be of use to you, $gmy lord:my lady;.$b$bYou can find him working the forges on the upper level.', `QuestDescription`) WHERE `ID` = 39757;
