UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Advanced Runecarving', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Soul Forge to empower your Artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve been working for many years to improve the forges. This weapon will be the perfect demonstration of the Soul Forge, their latest design!nnWe can take your artifact to the forge and shape it to make use of the power it contains, provided you\'ve fed your weapon enough souls first. Let\'s give it a little try, eh?', `QuestDescription`) WHERE `ID` = 39761;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Feltotem Warlock', `LogTitle`) WHERE `ID` = 39762;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'For Whom the Fel Tolls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Fel Energy Cores from Wyrmtongue Minions in Suramar. Bring them back to Matthew in Dalaran when you are finished.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Matthew eyes you up and down, growling slightly>$b$bYou wish me to help you understand this rock? First you do something for me.$b$bThe legion has brought many of its fel machines to conquer this world. Those machines are powered by cores filled with fel energy. And those cores are carried by the lowliest of their minions for distribution.$b$bBring me some cores and I\'ll give you the information you need.', `QuestDescription`) WHERE `ID` = 39763;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shiny, But Deadly', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Soul Chambers from kobolds within Mucksnout Den.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Soulkeeper Uriah and I were transporting demon prisoners to Allari in Azsuna when our caravan was attacked by kobolds.nnThose mindless vermin made off with the soul chambers that house our demonic captives.nnThe crystals may be shiny, but they\'re also deadly. If they are damaged in any way, the demons trapped within may escape.nnHead into the cave nearby and recover the soul chambers before it\'s too late.', `QuestDescription`) WHERE `ID` = 39764;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wax On, Wax Off', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the Skull of Bossing Around from the Bluewax Skullcaptain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve been dead for centuries without having my grave so disturbed... The leader of the local kobolds has stolen my skull from my grave and wears it upon his head!nnHe\'s down in the cave below, but a gate blocks your path from retrieving it directly. Kobolds know their leadership by the skulls they wear, and they are unintelligent enough to believe you their leader if you have one yourself.nnKill one of their Skullcaptains and recover his Skull of Bossing Around, and they may let you into the cave.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Bluewax Skullcaptain', `PortraitGiverName`) WHERE `ID` = 39765;
