UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sleigh and Snowfighters', `LogTitle`) WHERE `ID` = 39767;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Candle to the Grave', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Bluewax Graverobbers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These kobolds are taking advantage of the attacks against the Skyhorn tribe. They disturb our graves and steal anything they can get their paws on.nnI can do nothing to stop them! Please rid this sacred burial ground of the kobold.', `QuestDescription`) WHERE `ID` = 39768;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Gates of Wax', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the Bluewax Gatekeeper and see if he will let you in to meet the Candleking.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Go talk to the Bluewax Gatekeeper and see if he will let you through to the Candleking. If you can get through by donning the skull, the smell will be worth it.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet the Bluewax Gatekeeper.', `QuestCompletionLog`) WHERE `ID` = 39769;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Voice of Thunder', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Temple of the White Tiger and prove yourself worthy to wield the weapons of storm!', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The White Tiger has prepared a series of challenges for everyone who wants to possess the weapons of the storm.$b$bNow you know of their power - these are the very artifacts that Ra-den himself wielded during the age of the Titans.$b$bCome! I have led arena teams to victory across three continents. With me in your corner, you cannot lose!', `QuestDescription`) WHERE `ID` = 39771;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Can\'t Hold a Candle To You', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover Oenia\'s Skull from the Candleking.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Okay guess you can go say hi to Candleking now.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'The Candleking', `PortraitGiverName`) WHERE `ID` = 39772;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Soulkeeper\'s Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Soulkeeper Uriah within Mucksnout Den.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Soulkeeper Uriah was injured in the kobold attack, but insisted on venturing further into the cave to recover the stolen soul shards. He told me to wait here with our remaining supplies until he returned, but I fear the worst.nnPlease find Uriah. He is the only one who knows how to trap the demons.', `QuestDescription`) WHERE `ID` = 39773;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demon Detainment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Weaken demons so Apprentice Rosalyn can trap them within a soul chamber.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demons that escaped must be detained. Killing them is not an option. Uriah was entrusted to deliver the prisoners to Allari for interrogation, and I will not let him fail.nnI\'ve seen Uriah trap many demons. It seems... complicated, but I think I can pull it off. I\'ll just need you to subdue them first.', `QuestDescription`) WHERE `ID` = 39774;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stormforged Grapple Launcher', `LogTitle`) WHERE `ID` = 39775;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle Worms', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Naxa, Arxas, and Xist.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Snowmane Village behind us was caught completely off guard by the scale of this attack. I will hold the drogbar line here so the civilians have time to prepare their evacuation.$b$bThe drogbar are using worms to burrow their way to the surface and deploy their troops.$b$bI am giving you command of our forces. Use them to slay these worms and cut off enemy reinforcements.', `QuestDescription`) WHERE `ID` = 39776;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Buy Us Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Mightstone drogbar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need time to evacuate Snowmane Village. Can you take the fight to these Mightstone drogbar and cull their numbers?$b$bI will direct my healers to get everyone that is unable to fight to safety.', `QuestDescription`) WHERE `ID` = 39777;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Underking', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assault Dargrul the Underking.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mayla already chased the Underking into his cave. That is something we tell our children never to do.$b$bReckless child, but hey, who wants to live forever? Let us join her in battle.', `QuestDescription`) WHERE `ID` = 39780;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Neltharion\'s Lair', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the Hammer of Khaz\'goroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I will direct my people to clear a path through this rubble and assault Dargrul\'s forces directly.$b$bIt will be a ruse.$b$BNavarrogg proposed a plan that I believe has merit. He knows of a side entrance that might lead directly to Dargrul.$b$bMuster what allies of yours you can and strike at them through this side passage. Recover the Hammer of Khaz\'goroth before that villain brings the mountain down on top of us.$b$bWe will provide the distraction you need to get a shot.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'He wields the stolen Hammer of Khaz\'goroth.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Dargrul the Underking', `PortraitGiverName`) WHERE `ID` = 39781;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Exiled Shaman', `LogTitle`) WHERE `ID` = 39782;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle Pet - Terky', `LogTitle`) WHERE `ID` = 39783;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Beastmaster Pao\'lek', `LogTitle`) WHERE `ID` = 39784;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Stone Cold Gamble', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Stonefang\'s Jaw from Stonefang in Stonescar Gorge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The second target is a basilisk called Stonefang that lives off the bank of the nearby river. nnI put a bigger wager on him, so if you can take him out I\'ll make sure you get a cut.nnI\'ll need his jaw to verify the kill. Hurry, before those tauren get him first!', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'A massive basilisk terrorizing the vrykul of Stormheim.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Stonefang', `PortraitGiverName`) WHERE `ID` = 39786;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rigging the Wager', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Lure down and defeat Spitefeather to collect Spitefeather\'s Beak in the Stormtorn Foothills.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Care to help settle a bet, chum?nnThose tauren are Skyhorn, and they fancy themselves big-time hunters. I bet them a pretty penny that they wouldn\'t be able to take out some of the biggest beasts in Stormheim.nnIf you take em out before they do, I\'ll split the wager. Deal?nnThe first is a big eagle nesting in the foothills. They call him Spitefeather. You can bait him with some meat, but he\'s up pretty high, so you\'ll need a grapple gun to get there. I think there\'s one of them layin around here...', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'A giant eagle that hunts the Stormtorn Foothills.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Spitefeather', `PortraitGiverName`) WHERE `ID` = 39787;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Runewood\'s Revenge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 8 Bonespeaker Runeaxes and 8 Bonespeaker Carvers in the Runewood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bonespeakers...they are corrupt... hungry for power.nnCut them from my woods...', `QuestDescription`) WHERE `ID` = 39788;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eating Into Our Business', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 10 Duskpelt worg in Amberfall Mesa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings traveler! You are welcome to rest at our camp, but if you plan on sticking around a while, I have a proposition for you.nnAs you can see, the land here has been very good to us, providing a great natural bounty. Lately, however, the worg have become problematic, and are thinning the herds to unacceptable levels.nnI can\'t take care of them all, so I will offer a bounty for every worg slain in the mesa. Return to me when you have culled their pack a bit.', `QuestDescription`) WHERE `ID` = 39789;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Infernal Brimstone Theory', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the brimstone sample to Matthew Rabis in the Underbelly.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve gone through all the research ye gathered for me and I\'ve come up with a theory. As we know, the ore in this world develops over time, through pressure and environmental changes.$b$bBut the Infernal Brimstone ye gave me had its growth accelerated through demonic magic, much like the saronite of Icecrown.$b$bIf we\'re wantin\' to test this out, we\'ll have to get the help of some magic-users.$b$bTake this brimstone back and go see Matthew Rabis. He may know how to breathe life into it.', `QuestDescription`) WHERE `ID` = 39790;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lay Them to Rest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Branch of the Runewood to send 8 weakened Restless Ancestors back to the earth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I would ask a favor, outsider.nnAs you step through the graves of ancient heroes, you will no doubt come across spirits of the restless dead, agitated by the Bonespeakers misdeeds. They must be returned to the earth where they are buried, so that they may be judged as well.nnTake this bough - it carries with it the essence of the Runewood. Channel its power into a weakened spirit, and it will return to rest.', `QuestDescription`) WHERE `ID` = 39791;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Stack of Racks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Meaty Racks of Musken Ribs from Stout Highland Runehorns in Jotunnwood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So while we\'re waiting here, maybe you could fetch us up some grub. Them tauren were runnin low on meats, so I\'m sure they\'d be thankful to have more.nnI hear that musken ribs are the specialty here.  The wild musken here are too lean for any good meat, but across the river there are some nice fat ones. Maybe you should check those out!nnDon\'t worry, I\'m pretty sure there aren\'t any dragons over there...', `QuestDescription`) WHERE `ID` = 39792;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Only the Finest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 18 Patches of Fine Goat Hair from Silvertail Mountain Goats in Nastrondir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Say, you\'re a pretty good hunter, eh? Maybe you could help these tauren out by stocking them with some rare furs. I\'m sure they\'d appreciate it when they got back!nnI hear that Stormheim goat hair can be woven into all kinds of things. The rarest are from the silver-tail goats. I think I saw some in that mountain over there.nnWhy don\'t you go and fetch some? I\'m sure them tauren would pay you handsomely!', `QuestDescription`) WHERE `ID` = 39793;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lord Maxwell Tyrosus Slotted', `LogTitle`) WHERE `ID` = 39794;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vindicator Boros Slotted', `LogTitle`) WHERE `ID` = 39795;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Haustvald', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Vydhar in the Runewood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your next steps are clear, your feet know the way. Follow them to Haustvald and meet your fate!nnIt is the tree you seek, the heart of the mystic Runewood. He will offer guidance, and probably leaves.', `QuestDescription`) WHERE `ID` = 39796;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aponi Brightmane Slotted', `LogTitle`) WHERE `ID` = 39797;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lady Liadrin Slotted', `LogTitle`) WHERE `ID` = 39798;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Our Next Move', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your order\'s first assault point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Have you seen the fog that surrounds us? The chill winds of Acherus have provided us with a perfect concealment from the prying eyes of the Legion!$b$bUnder cover of this fog we\'ve been able to send out scouting teams who\'ve put together a fairly comprehensive map of the Broken Isles.$b$bChoose where we shall begin our assault. You, of course, shall have the honor of spearheading our efforts, but the rest of the Ebon Blade will follow your lead.', `QuestDescription`) WHERE `ID` = 39799;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Greymane\'s Gambit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete Greymane\'s mission aboard the Skyfire.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Skyfire is prepared to make way to Stormheim. Should we become engaged, I will require my best fighters on the front line.nnThis includes you, $c.', `QuestDescription`) WHERE `ID` = 39800;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Splintered Fleet', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete Sylvanas\' mission to bring the fleet to Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Preparations have been made, and we are ready to set sail.nnWe must strike out at once. Do not dally, or you will be left behind.', `QuestDescription`) WHERE `ID` = 39801;
