UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Trials Continue', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Havi in Valdisdall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Havi\'s voice continues in your head as the raven stares on>nnIf valor you seek, then to the bones you must speak! nnBut first you must prepare!', `QuestDescription`) WHERE `ID` = 39803;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Speaking of Bones', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Havi butcher the moose and learn about your next trial.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Trial of Valor will be your next test, and test you it will!nnBut only a fool fights on an empty stomach. Are you a fool, outsider?nnNo? Then lend these old bones a hand and butcher the moose for our meal. I will spin you a tale of rocks, trees and spirits.', `QuestDescription`) WHERE `ID` = 39804;
