UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Thassarian', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Welcome your new knight.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deathlord, I\'ve found our wayward knight. He wishes to return to the Ebon Blade, in particular he wishes to speak with you himself.$b$b<Mograine turns and nods to a nearby guard.>$b$bHe should be here momentarily.', `QuestDescription`) WHERE `ID` = 39816;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Brimstone\'s Secret', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Tell Mama Diggs what you learned from Matthew.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you were gathering what I asked of you, I did a little testing on the brimstone. It reacted rather violently when I channeled onto it. Careful casting went into making the creature from whom you took this.$b$bUnless you have a host of demon spell-casters at your disposal, recreating such a creature would be impossible.$b$bThat\'s all I have to tell you. Go now and leave me before my hunger takes over.', `QuestDescription`) WHERE `ID` = 39817;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Nazgrim', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Welcome your new knight.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deathlord, I\'ve found our wayward knight. He wishes to return to the Ebon Blade, in particular he wishes to speak with you himself.$b$b<Mograine turns and nods to a nearby guard.>$b$bHe should be here momentarily.', `QuestDescription`) WHERE `ID` = 39818;
