UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hellfire Citadel: Hellfire and Brimstone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather a group and storm Hellfire Citadel once more. Defeat Archimonde and recover the Infernal Codex.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When Khadgar\'s group stormed Hellfire Citadel, they faced many foes that commanded demons, but none more powerful than Archimonde himself.$b$bPerhaps there\'s somethin\' on his corpse that can answer the final questions of unlocking the mystery of this brimstone.', `QuestDescription`) WHERE `ID` = 39830;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Plans and Preparations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Siouxsie the Banshee.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your weapon is stronger than ever, but it will need many more souls in order to reach its true potential.$b$bSiouxsie has been collecting reports from the scouts, she will direct you to our enemies and their screaming souls will empower your weapon further.', `QuestDescription`) WHERE `ID` = 39832;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Unworthy Task', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search among the caged vrykul in Helheim for one who can help your escape.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This place is Helheim, the realm of the unworthy dead. Here, the spirits of the dishonorable spend eternity in an endless futile battle, always seeking glory but never able to attain it.nnWe should not be here.nnWe must find a way out. I will scout ahead - you should try and release some of these captive spirits here. Perhaps one may have some answers for us.', `QuestDescription`) WHERE `ID` = 39837;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fire!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Camille Kleister\'s Water Buckets to put out the fire.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You! Adventurer! Give us a hand! The wagon\'s caught fire!', `QuestDescription`) WHERE `ID` = 39838;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mysterious Dust', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Trader Caelen, Professor Pallin, and Deucus Valdera about the Mysterious Dust.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Nearly everything in the wagon was obliterated by the fire. All that remains is a small pile of dust.$b$bThe cart belonged to Trader Caelen. Perhaps he knows more about what happened.$b$bAs for the dust - either the inscription trainers or the alchemy trainers might have some insight.', `QuestDescription`) WHERE `ID` = 39839;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Council\'s Approval', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Khadgar in Dalaran, and ask for permission to build an Obliterum Forge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Those results certainly were disappointing. Calcination is a tricky process, better reserved for alchemists and blacksmiths. Still, I thought we\'d get more than a measly TWO GRAINS of obliterum.$b$bFor a more efficient reaction, we\'ll need a special forge, and to get that...$b$b...we\'ll need permission from the Council of Six.', `QuestDescription`) WHERE `ID` = 39840;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Friends in Low Places', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Oxana Demonslay in the Underbelly.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My contact is one Oxana Demonslay. She has declined invitation to Dalaran proper, preferring to stay in the sewers of the Underbelly.$b$bIf there is anybody on this rock that knows how to properly build an Obliterum Forge, it is her.$b$bOh, and watch your back while you\'re down there, $n.', `QuestDescription`) WHERE `ID` = 39841;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One Mage\'s Trash', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find a vial of Alchemical Flame, a roll of Spellbound Insulation, and a Decommissioned Calefactor.$b$bThese items can only be obtained while the Dalaran Sewer Guards are off duty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can help you build your forge. I can even supply the metal for it. I do, however, require a few more... difficult-to-acquire components.$b$bI need an alchemical heat source, some sort of insulator, and a calefactor. I\'m certain that all of these can be found here in the Underbelly... if the guards are looking the other way.', `QuestDescription`) WHERE `ID` = 39842;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Muck Stops Here', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 20 vials of Spellsludge.$b$bSpellsludge can be found on the powerful Underbelly creatures that appear while the Dalaran Sewer Guards are on duty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'For my next project - sticking the forge\'s components to one another - I need a magical adherent. And I\'ve found that the built-up sludge of Dalaran\'s sewers works perfectly for just that.$b$bIt cakes up on the feet, boots, and slithering bellies of Dalaran\'s more long-lived residents. Scrape some off and bring it here.', `QuestDescription`) WHERE `ID` = 39843;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cold Hard Coin', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Sightless Eyes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I am not interested in gold. Your aboveground currencies have little use down here.$b$bI am, however interested in Sightless Eyes. I will gladly accept some as payment for my services.', `QuestDescription`) WHERE `ID` = 39844;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Obliterum Forge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Finalize the construction of the Obliterum Forge in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The components of the forge are assembled and, as I understand it, Archmage Karlain has secured a location for us to begin construction: aboveground, near the blacksmith.$b$bCome back and visit sometime, $n.', `QuestDescription`) WHERE `ID` = 39845;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Dalaran - Treasure 001 - Burnt Cart', `LogTitle`) WHERE `ID` = 39846;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sign This', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Sign Professor Pallin\'s contract.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ah, a fellow scribe!$b$bYou don\'t look too dim, so how \'bout you and I work together in an effort to discover what we can about the Broken Isles?$b$b(That\'s the big mass of islands we\'re floating over.)$b$bHowever! I never agree to a partnership without getting all the requisite legalities out of the way. Sign this for me and we\'re in business.', `QuestDescription`) WHERE `ID` = 39847;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Desperate Bargain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Confront Helya and ask to be freed from Helheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It looks like your friend didn\'t make it. A pity, but we must move on.nnYou\'ll want to plead our case to Helya. She is the ruler here. I would accompany you, but I\'m afraid I wouldn\'t help your case.nnMeet me when you are finished. I will see if I can find the whereabouts of my shieldmaidens.', `QuestDescription`) WHERE `ID` = 39848;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Light the Way', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Helheim Waylight from Bloodbeard in Helheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Helya must think her challenge unwinnable. We will show her different.nnI am unsure what she did, but Helya has weakened you somehow. I have seen similar effects on my shieldmaidens, and now they are trapped by Helya\'s minions.nnI may know a way, however. The Kvaldir ships carry special lanterns bound to this place to navigate through the fog. It is said that the light of these lanterns can release bonds of the spirit.nnThere is a kvaldir ship nearby. See if you can find one there.', `QuestDescription`) WHERE `ID` = 39849;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sundered', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and release the Fragment of Will, Fragment of Might, and Fragment of Valor in Helheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I imagine the power of your weapon will be what allows us to defeat Geir, but right now you are too weak for the confrontation. We must reclaim the missing pieces of your spirit.nnHelya must have scattered them throughout her realm to keep them from you. If you can find them, shine the lantern and they should be set free.nnBe careful, though. It is unlikely that Helya left your spirit fragments unguarded.', `QuestDescription`) WHERE `ID` = 39850;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Allies in Death', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Release 8 Drowning Valkyra in Helheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our power alone may not be enough to fight the behemoth, Geir. Fortunately, Faljar was kind enough to send our allies into Helheim with us.nnEarlier, I had discovered several of them being tortured by the elemental forces of Helheim. You may think the dead can\'t drown, but with Helya\'s power, this is not the case. nnI could not release them then, but now that you possess the waylight, you may be able to.nnSeek them out and free them from an eternity of suffering!', `QuestDescription`) WHERE `ID` = 39851;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Victory is Eternal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Geir in the Eternal Battlefield in Helheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is no more cause for hesitation. Now is the time to strike.nnWe will defeat this foul behemoth and meet Helya\'s bargain. The path out of Helheim awaits, outsider. nnPrepare yourself.', `QuestDescription`) WHERE `ID` = 39853;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Paid in Lifeblood', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Confront Helya and leave Helheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have fulfilled Helya\'s bargain. Now, we see if she will keep to her word.nnWhen you are ready, we should proceed to the throne. If you have any other business here, I would suggest finishing it now.nnI will follow your lead, outsider.', `QuestDescription`) WHERE `ID` = 39855;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Wraithtalon', `LogTitle`) WHERE `ID` = 39856;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Eternal Nemesis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Ashildir and inform her of Helya\'s challenge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Helya\'s voice echoes in the sky above the altar>nnYou say that you do not belong here among the unworthy, outsider, but your spirit fragments so easily. How am I to know you speak the truth? nnI cannot, so you must show me.nnBring yourself to the eternal battlefield and face my champion. If you manage to defeat him, then I may grant you a pardon.', `QuestDescription`) WHERE `ID` = 39857;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Dreadbog', `LogTitle`) WHERE `ID` = 39858;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Note-Eating Goats', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover Addie\'s manuscript from Sated Hillstriders within Pinerock Basin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve followed Hemet on all his expeditions from Stranglethorn to Nagrand to... Nagrand again, taking notes on his grand adventures and turning them into timeless literary tales.nnBut my heart is really in the hunt. I want nothing more than to put down the pen, and pick up a rifle!nnHemet promised to teach me how to hunt once I finish his latest novel, but the goats around here ate my first draft!nnI have no hope of becoming a hunter if my manuscript isn\'t recovered.', `QuestDescription`) WHERE `ID` = 39859;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rite of Blood', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the Rite of Blood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oakin Ironbull vouches for you. He\'s capable, for a Rivermane. You also brought with you proof of your own strength, albeit rather inconclusive proof.nnBefore we allow you to move freely within our territory, you must complete the Rite of Blood, which you have already begun. If you succeed--and I doubt you will--talk to me.nnEnter the depths of the cave. Defeat whatever foe appears and return to me.', `QuestDescription`) WHERE `ID` = 39860;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tying Up Loose Ends', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Aludane Whitecloud at Krasus\' Landing to secure a flight to Val\'sharah. Speak to Malfurion Stormrage after you arrive in Lorlathil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Malfurion Stormrage managed to make landfall in Val\'sharah and has already taken care of things there. It seems our fortune is finally turning around!$B$BHe\'s waiting for you as we speak in Lorlathil. Life is so magical when everything goes according to plan.', `QuestDescription`) WHERE `ID` = 39861;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Siegebrul', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Siegebrul Olgrul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Worms do not like battle or the surface. They only go where their master tells them.$b$bSo, when in war, kill the master.$b$bSiegebrul Olgrul is the master of worms for the Mightstone drogbar who attack us from the north.$b$bSlay him.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'The Mightstone Leader', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Siegebrul Olgrul', `PortraitGiverName`) WHERE `ID` = 39862;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trial By Fel Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a set of Imbued Silkweave Bracers, Dreadleather Bindings, Gravenscale Armbands, and Demonsteel Armguards.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The substance you hold is something that we call "obliterum". We had theorized its existence, but until now, we had never actually been able to produce any.$b$bYou say this came from a fire? Of COURSE! Calefaction! Why hadn\'t I thought of that sooner?$b$bWe\'ll need to reproduce these results before we take any further action. I know it\'s asking a lot, but I\'ll need you to get me some more high-quality armor, in a variety of styles.', `QuestDescription`) WHERE `ID` = 39863;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stormheim', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Nathanos Blightcaller at the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Nathanos Blightcaller, Champion of the Banshee Queen herself, sent for you in Dalaran.$B$BHe should be waiting for you in the Violet Citadel. It sounded urgent.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Lord Grayson Shadowbreaker', `PortraitGiverName`) WHERE `ID` = 39864;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Tiny Scarecrow Costume', `LogTitle`) WHERE `ID` = 39865;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scout Harefoot', `LogTitle`) WHERE `ID` = 39866;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'I\'m Not Lion!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a hunting trophy from the lion that Ellias claims to have seen in Pinerock Basin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve hunted many exotic beasts in my day, but I\'ve never seen a lion like the one I encountered while scouting the basin.nnThe beast\'s amber eyes locked on mine, luring me closer. I was helpless to this predator\'s enchanting gaze. It was only when the lion pounced did the stupor break.nnI\'ve told Hemet of this magical beast, but he laughs. I\'m not lying, $n! The lion exists.nnIf you find the beast, bring me a trophy of your kill, and I\'ll reward you handsomely.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Rashar', `PortraitGiverName`) WHERE `ID` = 39867;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Neltharion\'s Lair Heroic Reward Quest', `LogTitle`) WHERE `ID` = 39868;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Toll for the Soul', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Helya and free the Valarjar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[PH] As foretold, you have arrived... Helya is foolish to think I\'ll let her ferry me into Helheim. Odyn has already smiled upon me, my soul belongs in Valhallas. nnMake no mistake, I am not a prisoner. Before my death Odyn appeared to me in the form of a raven. He praised my battles in life and gave me a quest no vrykul could refuse. The Helerjar arrived... and I let them slay me.nnPrisoner-- nay, I am a liberator, sent by Odyn to free the souls of Valarjar.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Helya', `PortraitGiverName`) WHERE `ID` = 39869;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Soulthirster', `LogTitle`) WHERE `ID` = 39870;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Huntress Ellandryn', `LogTitle`) WHERE `ID` = 39871;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Beastly Boxer', `LogTitle`) WHERE `ID` = 39872;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'I Have a Bad Feeling About This', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate Navarrogg\'s suspicions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have no reason to trust me. My cousins led by Dargrul have gone mad with power.nnBut I ask you to investigate something. I have a feeling something terrible is about to befall Highmountain, and that Torok and his Bloodtotem are going to be responsible.nnIf you don\'t believe me, look for yourself at the northern side of Cliff\'s Edge.', `QuestDescription`) WHERE `ID` = 39873;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Some Enchanted Evening', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Ildine Sorrowspear inside the enchanting shop in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Welcome! It\'s nice to see familiar faces returning to Dalaran. You might remember Ildine, Vanessa, and me from Northrend. $b$bArchmage Starsinger is in charge of the shop, but he\'s away on Kirin Tor business at the moment. He\'s a fine fellow... mostly.$b$bYour arrival is fortunate. We\'ve run into a problem that we\'d love to solve before the archmage returns. Interested in lending a hand?', `QuestDescription`) WHERE `ID` = 39874;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Last Few', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Create $1oa Enchant Ring - Word of Versatility vellums for Ildine. You can acquire vellums from a scribe, or from the Auction House.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you can see, $n, we\'re hard at work producing enchants for the battle against the Legion. Since you\'re here, we could really use your help wrapping up one of our orders.$b$bIf you could, acquire some vellums and start enchanting them with Versatility. Here, I\'ll teach you the formula.', `QuestDescription`) WHERE `ID` = 39875;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Helping the Hunters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the crate of vellums to Jace Darkweaver in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now, while I continue to fill the rest of our orders, I\'d really appreciate it if you would deliver these vellums to Jace Darkweaver down in Azsuna.$b$bHe and the other demon hunters have been fighting back the Legion for quite some time and could use this as quickly as possible.$b$bThanks, $n!', `QuestDescription`) WHERE `ID` = 39876;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In the Loop', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the enchanting vellums on $1oa Demon Hunters at the Illidari Stand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We could use your help down here, $n. Some of our hunters would benefit greatly from having those vellums applied to their rings right now.$b$bHere take a few. I\'ll give the rest to one of my other soldiers to hand out.$b$bMy hunters probably won\'t stop to let you apply the enchants, so you\'ll just have to do your enchanting even if they\'re in the midst of battle.', `QuestDescription`) WHERE `ID` = 39877;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thunder Struck', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Guron Twaintail in Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve made contact with a potential source of new enchantments down in Highmountain. The tauren of Thunder Totem command the spirits to imbue items with great power.$b$bSeek out an enchanter named Twaintail and see if he will share his knowledge with us.$b$bTaurens are known for their sharing... right?', `QuestDescription`) WHERE `ID` = 39878;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Strong Like the Earth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Enraged Ambershards and collect $b$1oa of their Ambershard Crystals. Bring them back to Guron in Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There are many types of spirits in this world, $n. Some benevolent, some troubled.$b$bThey all resonate with different reagents which we use to enchant our armor. One such reagent are the crystals of the ambershards.$b$bThey are a violent creature born of the earth and have recently been disturbed by the drogbar. However, disturbed or not, the crystals they bear are of great use to my people for enchantments. Bring me some and I\'ll show you what I mean.', `QuestDescription`) WHERE `ID` = 39879;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Waste Not', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Crystal Fissure and search for discarded armor. Disenchant the armor and bring back $1oa Thunder Dust to Guron.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While fighting the ambershards for their crystals, you may come across enchanted armor from our fallen braves. The ambershards care not for such things, but our tribe does not believe in letting anything go to waste.$b$bI\'d like you to retrieve our braves\' armor and disenchant them into the components from which they were imbued.$b$bBring me back the reagents so my tribe may use them to enchant new armor.', `QuestDescription`) WHERE `ID` = 39880;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fey Enchantments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Nalamya near the Temple of Elune in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The new dusts and crystals we\'ve found in these lands are fascinating, as I\'m sure you\'ve already surmised. I\'m positive we can expand their usefulness to more of our armor.$b$bI\'d like you to go back out into the field and talk to a dryad in Val\'sharah. Apparently she may be able to clue us into some enchantments for shoulder pieces.$b$bHer name is Nalamya. You\'ll find her near the Temple of Elune.', `QuestDescription`) WHERE `ID` = 39881;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkheart Thicket: The Glamour Has Faded', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Arch-Druid Glaidalis in the Darkheart Thicket and recover Nalamya\'s Book of Enchantments.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I once taught the night elves how to enchant their armor to strengthen themselves against the evils of this land. One elf in particular garnered my favor.$b$bArch-Druid Glaidalis is his name. He now resides in the forest known as the Darkheart Thicket, plotting to undo this world with this awful blight.$b$bBefore his betrayal, I gave him my book of enchantments to study. I would very much like it back.$b$bI trust you with this task, enchanter. Bring my book back to me.', `QuestDescription`) WHERE `ID` = 39882;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cloaked in Tradition', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take Guron\'s Journal to Nalthanis in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have seen the ways of the tauren of Thunder Totem... speaking with the spirits, gathering from the land, and letting nothing go to waste. These are potent forces crucial to your quest to aid the Broken Isles.$b$bHere, take this journal back to your enchanter friend. It contains the lessons I have imparted unto you.$b$bPerhaps it will serve to help the greater cause of defeating the Legion.', `QuestDescription`) WHERE `ID` = 39883;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'No Longer Worthy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill night elves within the grounds of Black Rook Hold and collect their Enchanted Raven Sigils. Disenchant the sigils and bring back $1oa Raven Dust to Nalamya as proof of their defeat.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The elves of Black Rook Hold have decided to turn their backs on us. They stay inside their keep, attacking any outsider who dare try to enter.$b$bSuch behavior is intolerable... especially after all the help they\'ve received from my folk and the others of this land.$b$bI want you to do me a favor, $n. Take their enchanted sigils and reduce them to dust. Bring me back the dust as proof of your deeds.', `QuestDescription`) WHERE `ID` = 39884;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Led Astray', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Black Rook Hold in Val\'sharah and slay Trelan Shieldbreaker and Starlys Strongbow.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The night elves are no fools, but the elves of Black Rook follow their commanders with blind loyalty. I\'ve no doubt that the blame for their apathy rests heavily upon their commanders.$b$bI know of two of their leaders, who as we speak continue to command their troops to do nothing against the blight encroaching upon my home.$b$bGo to Black Rook Hold and slay Trelan Shieldbreaker and Starlys Strongbow. Let them be an example for those who can help, but wish to remain cowardly.', `QuestDescription`) WHERE `ID` = 39889;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cursed, But Convenient', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Enchantress Ilanya at the Crumbled Palace in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I need you to return to Azsuna at once, $n. I\'ve only just heard of an enchantress within the Crumbled Palace who knows of many rare enchantments.$b$bGo to her and see what you can learn at once.', `QuestDescription`) WHERE `ID` = 39891;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'DEPRECATED: The Ringer', `LogTitle`) WHERE `ID` = 39896;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Enchanting Home', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate Tigrid\'s home in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The more I learn about the Broken Isles, the more convinced I am that it is a land of wonders!$b$bIldine and I were just discussing rumors of a dwelling in Stormheim that was once the home to a vrykul enchantress called Tigrid. It is said the site is perfectly preserved, and her enchantments were so potent that they persist to this day!$b$bInvestigating the home might uncover valuable knowledge, $n.', `QuestDescription`) WHERE `ID` = 39903;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: Revenge of the Enchantress', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve Tigrid\'s Enchanting Rod from the Halls of Valor and return it to her in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'For many centuries, even after death, I was capable of weaving enduring enchantments. But since the theft of my enchanting rod by a greedy king, I can barely sustain the little magic I have left.$b$bIf you can recover my enchanting rod from the god-king\'s ghost, I will reward you in kind.', `QuestDescription`) WHERE `ID` = 39904;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ringing True', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Nalthanis in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While your presence here would continue to be of value to us, your master in Dalaran has called for you.$b$bI\'d like to thank you again for all you\'ve done for us. My hunters have been reminded that they\'re not alone in this war.', `QuestDescription`) WHERE `ID` = 39905;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prepping For Battle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft an Enchant Cloak - Word of Strength vellum, an Enchant Ring - Word of Critical Strike vellum and an Enchant Ring - Word of Mastery vellum for Alynblaze.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To earn my mark, $c, you must first prove yourself in battle to me. There is a naga I wish to kill, but I am not strong enough to slay him.$b$bBefore we go into battle together, I need your help as an enchanter to become stronger. I\'m sure by now you have a bevy of enchantments in your repertoire.$b$bMake some for me so that I may become strong enough again to make a difference in this world.', `QuestDescription`) WHERE `ID` = 39906;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Elven Enchantments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Nalthanis in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have earned the marks of my most trusted companions. You have also returned my love to me.$b$bI am fortunate to have met you, $n.$b$bNow return to your master and let him know of what you have learned.', `QuestDescription`) WHERE `ID` = 39907;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Druid\'s Debt', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Merrus\' Idol of the Paw, Idol of the Claw and Idol of the Moon and return them to him at the Crumbled Palace.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to grant you my mark, $c, I must first be made strong enough to come to your aid should you need it.$b$bWithin the ruins of Nar\'thalas, my idols sit dormant. As I\'ve said, I\'m not strong enough to get them myself.$b$bBut you are strong, I can sense it. Strong enough to take on those honor-less naga who plague my home.$b$bFind my idols and return them to me. Do this and I will grant you my mark.', `QuestDescription`) WHERE `ID` = 39910;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sentinel\'s Final Duty', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Fathom-Commander Eksis. Return to Alynblaze at the Crumbled Palace when you are through.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that I\'m stronger, it\'s time to test your mettle, and mine. As I mentioned earlier, there is a powerful naga I wish to kill.$b$bHis name is Fathom-Commander Eksis. He was responsible for slaying many of my kin before he retreated into hiding, commanding his troops from the shadows.$b$bI\'ve finally discovered his whereabouts in a cave just east of here. Let us bring vengeance upon him for my lost brothers and sisters.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'A fierce naga who has moved up the ranks and gained the title of Fathom-Commander.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Fathom-Commander Eksis', `PortraitGiverName`) WHERE `ID` = 39914;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Turnabout Betrayal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat demons at the Felblaze Ingress. Take their Fel-crusted Runes and disenchant them into $1oa Dust of Foul Lies. Return to where you met the Fallen Priestess when you are done.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Enchantress Ilanya remembers me?$b$b<The satyr pauses to wipe a tear away.>$b$bI made a fool\'s bargain ten millennia ago. I learned of the queen\'s alliance with the Legion and betrayed my heart to join their side. I was transformed into a monstrosity, only to die in battle against the mortals.$b$bNow the Legion returns, but I linger as an impotent spirit. Be my vessel and slay the demons ahead of us. Take their demonic runes and render them to dust.', `QuestDescription`) WHERE `ID` = 39916;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Absent Priestess', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Enchantress Ilanya at the Crumbled Palace in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'After my betrayal, I never thought I could bear to look upon my love again. But thanks to you, $n, I can at last return.$b$bGo and speak to Enchantress Ilanya. I will let her know that you are worthy of my mark.', `QuestDescription`) WHERE `ID` = 39918;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'On Azure Wings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to the dragon Kharmeera at Azurewing Repose in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have some exciting news of my own to report, $n. Ildine and I had an excursion to Azsuna and made contact with the blue dragons at the Azurewing Repose.$b$bOne of the dragons, Kharmeera, is an enchanter who expressed interest in working with you to perfect some of our enchantments.$b$bI understand you were just down there working with the elves, but if you wouldn\'t mind returning, Kharmeera would enjoy working with you too.', `QuestDescription`) WHERE `ID` = 39920;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Neltharion\'s Lair: Rod of Azure', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve a Skystone Rod from Dargrul the Underking in Neltharion\'s Lair, a Radiant Zephyrite from Ozruk in The Stonecore and a pile of Ancient Arkhana from Scholomance.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Before we can begin though, there is a small favor I need to ask of you. I\'m rather ashamed about this matter, to be honest, but it must be done in order for us to work together.$b$bWhen I was summoned to this land, I hadn\'t been given a chance to collect my things. Most importantly, I left behind my enchanting rod.$b$bInstead of retrieving it I believe it would be much simpler to reconstruct it.$b$bHere\'s what we\'ll need...', `QuestDescription`) WHERE `ID` = 39921;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Down to the Core', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Power Cores from Oldus, Or\'ell, Olmoore, and Oll\'ison. Bring them back to Kharmeera when you have all four.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The ring enchantments you know now are good, but I know of better ones that exist. That is to say, I know of stronger enchantments that would be suitable for rings.$b$bAccording to legend, there are four constructs whose cores were imbued with magical enchantments. These constructs now patrol the streets of Suramar City.$b$bIf you were to gather some friends and defeat these constructs, you could take their cores for us to study.', `QuestDescription`) WHERE `ID` = 39923;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Emissary Azathar Looted', `LogTitle`) WHERE `ID` = 39925;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lord Malus Looted', `LogTitle`) WHERE `ID` = 39926;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wingterror Ikzil Looted', `LogTitle`) WHERE `ID` = 39927;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Uther\'s Spirit Honored', `LogTitle`) WHERE `ID` = 39928;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Uther\'s Spirit Honored', `LogTitle`) WHERE `ID` = 39929;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Uther\'s Spirit Honored', `LogTitle`) WHERE `ID` = 39930;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Smashing Herbs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Roseate Pigments and $2oa Sallow Pigments. Pigments are obtained by milling herbs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that the formalities are out of the way, let\'s have you do something actually useful.$b$bOn the islands below, there\'s a plethora of new and exotic herbs that we\'ve yet to experiment with.$b$bI\'d like you to get some of those herbs and create some new pigments from them. Once you have enough, come back to me and I\'ll see what you\'ve come up with.', `QuestDescription`) WHERE `ID` = 39931;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fish Ink', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Mak\'rana Oil, $2oa Hatecoil Naga oil, and $3oa Salteye Oil, then combine them into a Piscine Pigment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You know, herbs aren\'t the only ways to obtain ink. Other materials can be inkified.$b$bSlightly related! I\'ve been tinkering with the idea of creating my own type of Darkmoon card. Surely if those troggish carnival people can do it, then so can I.$b$bTo do so, we\'ll need some special reagents. Go down to Azsuna and collect some oils for me, then mill them into a suitable ink.', `QuestDescription`) WHERE `ID` = 39932;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Card Shark', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Hearthstone Cards at the Legerdemain Lounge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have the pigment, but we still require one more ingredient.$b$bVisitors at the Legerdemain Lounge will often play card games, and occasionally their cards are discarded. Go see if you can find some loose cards that players may have gotten rid of between matches.', `QuestDescription`) WHERE `ID` = 39933;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Our New Allies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Azsuna and find Allari the Souleater.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Have you seen those demon hunters yet? I\'m not entirely sold on their allegiance to our cause, but while we have them, we may as well exploit them.$b$bEverybody needs glyphs, you know.$b$bGo see what you can discover about them. Azsuna is as good a place as any to start.$b$bPerhaps my genius has worn off on you and you\'ll be able to create your own recipes based on what you learn.', `QuestDescription`) WHERE `ID` = 39934;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Price of Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa demons at Illidari Strand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You wish to learn what it is to be a demon hunter? That may take some time.$b$bThe first thing you can do is fight alongside us. Battle the demons with us and observe how we use their strength against them.$b$bReturn to me when you are finished.', `QuestDescription`) WHERE `ID` = 39935;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Inscription of the Body', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Baric Stormrunner near the Ley-Ruins of Zarkhenar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves. That is the purpose of marking our skin the way we do.$b$bUp to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. Go to him and learn how we keep our demons at bay.', `QuestDescription`) WHERE `ID` = 39936;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Opposites Repel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Ley Dust from the nightfallen and withered in the Ley-Ruins of Zarkhenar, then mix it into a Ley Pigment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There\'s a balance that must be struck, $n, when becoming a demon hunter. In order to maintain that balance, we must infuse ourselves with opposite forces of nature.$b$bFel energy is counteracted by arcane energy. We mark our bodies with arcane runes to keep our fel forces in check.$b$bYou are a scribe, yes? Then you should have no trouble mixing a suitable ley pigment from the ley dust on the creatures in the ruins up ahead.', `QuestDescription`) WHERE `ID` = 39937;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Containing the Demon Within', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist Baric in completing the ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have all the essential pieces, let\'s begin the ritual.$b$bI\'ll instruct you on how to help me. It is pivotal that you follow my instructions when I give them, or the ritual will fail.', `QuestDescription`) WHERE `ID` = 39938;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scribal Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Zaria Shadowheart near the Felblaze Ingress in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We do not simply fight the demons, $n. We observe them.$b$bOne of my best demon hunters, Zaria Shadowheart, is currently gathering intel on the demons in Felblaze Ingress.$b$bGo to her. She will teach you what she has learned from the demons invading that region.', `QuestDescription`) WHERE `ID` = 39939;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Runes of Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Study $1oa Fel Power Runes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Look closely, scribe, and you may learn. As the demons spread out over a region, the more clever ones will inscribe runes upon the ground. The fel taint pervades this entire hillside, but the corruption is darkest around these runes, disallowing anything pure to grow ever again.$b$bStudy these runes.', `QuestDescription`) WHERE `ID` = 39940;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Control is Key', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the crystal protecting Overseer Felorax, then slay him.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We demon hunters ritualistically remove our eyes in order to see the demons more clearly.$b$bDown below, a demon commander walks amongst his troops, unseen by normal eyes. He keeps the chaos in order, as we must keep our chaos in check.$b$bDestroy his warding crystal, then slay him.', `QuestDescription`) WHERE `ID` = 39941;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aethrem Crystal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Aetherem Crystal to Professor Pallin in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Most aethril has a sharp crystalline fiber in the center of the bloom, but this one is particularly well-developed.>$b$b<Professor Pallin would be interested in seeing this.>', `QuestDescription`) WHERE `ID` = 39942;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Burdens of Hunting', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report back to Professor Pallin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is nothing more I have to teach you, scribe. The Illidari stand behind you in the battle against the Legion.', `QuestDescription`) WHERE `ID` = 39943;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mysterious Messages', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the tablets to Nicholo Swiftfuse in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The woman at the archaeology shop just dropped off some tablets to be deciphered. Any fool can see they\'re written in ancient vrykul, but I lent my codex to one of my students, so I\'m unable to decipher them here.$b$bHis name is Nicholo Swiftfuse, and he is in Stormheim. Let him know that if he fails to decipher them, his apprenticeship shall be terminated.$b$bThat is all.', `QuestDescription`) WHERE `ID` = 39944;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Runes Within the Ruins', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Ancient Vrykul Rune Tablets within Haustvald.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Unfortunately, Pallin\'s codex isn\'t complete. There are many symbols here that simply cannot be deciphered with what we\'ve learned.$b$bLooks like we\'ll need to go and collect more tablets down in the area that the vrykul call Haustvald.', `QuestDescription`) WHERE `ID` = 39945;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Right Tool for the Job', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire a Runic Bone Knife.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'From what little I have been able to decipher, I know that the tablets are created using a special carving tool.$b$bIf we had one of those tools, along with a complete codex, we could easily create our own tablet.$b$bThat would also serve to prove that my deciphering of their language has been successful.$b$bRetrieve one of those tools for me, $n.', `QuestDescription`) WHERE `ID` = 39946;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Not So Complex?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist Nicholo with the creation of a rune tablet.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alright, I believe I\'ve finished adding the missing entries into the codex. And we have the machete... err, knife.$b$bAll that\'s left is to make our own tablet and verify my other suspicion about these tablets:$b$bI believe that they\'re not just simple texts, but a sort of magical device.', `QuestDescription`) WHERE `ID` = 39947;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Ink Flows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the contracts to Raethan in the Underbelly.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I need you to make a quick delivery for me.$b$bYes, I\'ve learned by now that such trivial tasks are beneath your skills... but I\'m rather busy right now and we both know my time is much more important than yours.$b$bDeliver these contracts to Raethan, the Guard Captain in Dalaran\'s Underbelly.', `QuestDescription`) WHERE `ID` = 39948;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Once a Scribe Like You', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Inkrot and obtain the Stolen Shadowruby.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These sewers are something of a... "settling place" for many who can\'t cope with the stresses of regular Dalaran life. Take, for example, the target of this particular contract.$b$bHis name is Inkrot. He was once a scribe like you, but the stresses of dealing with the Professor drove him mad.$b$b<Raethan hands you the contract.>$b$bThis says he\'s stolen a jewel from Cartier and Co. Bring me the jewel. Whatever else you find on him is yours.', `QuestDescription`) WHERE `ID` = 39949;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Odd Trinket', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Give the Rotting Tarot Card to Professor Pallin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Wait, $n, before you leave... did you not notice this?$b$b<Raethan peels a small piece of paper from the bottom of the jewel.>$b$bThis wasn\'t reported stolen. It appears to be a card of some kind. Must be a scribe thing.$b$bPerhaps it may be of some use to you.', `QuestDescription`) WHERE `ID` = 39950;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Roseate Essence', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Roseate Essence to Professor Pallin in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The pigment milled from this flower is of an exceptionally high quality.>$b$b<Professor Pallin would be interested in seeing this.>', `QuestDescription`) WHERE `ID` = 39951;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sallow Essence', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Sallow Essence to Professor Pallin in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The felwort is reduced to a thick, clotted pigment. While all felwort-begotten pigment is somewhat offensive, this batch practically glows with a malevolent energy.>$b$b<Professor Pallin would be interested in seeing this.>', `QuestDescription`) WHERE `ID` = 39952;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: Vision of Valor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve $1oa Valarjar Rune-Sigils from the Halls of Valor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I think it\'s time for another field trip, $n. To the Halls of Valor!$b$bThe Valarjar are masters of all types of runecraft. Perhaps we can find something useful for a new recipe.', `QuestDescription`) WHERE `ID` = 39953;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mass Milling Techniques', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find The Masterful Miller\'s Manual in Dalaran\'s inscription shop.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A number of my previous students have been vocal in their displeasure regarding milling. They find the process "repetitive", "mindless", and even "painful". Have they no respect for the time-honored traditions of inscription?$b$bI suppose you count yourself among their number. Am I right? Very well. You\'ve been a fine student so far, so I suppose there\'s no harm.$b$bI have a book about mass milling somewhere around the shop here. Find it, and it\'s yours.', `QuestDescription`) WHERE `ID` = 39954;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Plot Thickens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Ironforge and look for B. Spearshaker.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Very well, I won\'t deny it. The Steamy Romance Novel is mine.$b$bI only read it for the penmanship, I assure you! He writes such curvy "B"s... and such ample "D"s!$b$bIn fact... you might benefit from a penmanship lesson. The author of these books is one B. Spearshaker. I believe he can be found in the library in Ironforge.$b$bStop reading, student. You are dismissed. And give me my book back!', `QuestDescription`) WHERE `ID` = 39955;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Legacy Passed On', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the Unfinished Steamy Romance Novel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve lost my passion, scribe. I just can\'t get into the voice o\' the characters anymore.$b$bTake a look at that unfinished book over there on the table. I can\'t seem to finish it. Maybe ye\'ll have an easier time with it.', `QuestDescription`) WHERE `ID` = 39956;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demon Ink', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Vials of Felsoul Blood and $2oa Blood of Sargeras, then mix them into Felsoul Ink.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These sigils would make for a fantastic new tarot card. Quite powerful, in fact. We simply require an ink sturdy enough to inscribe them.$b$bFortunately, I have students like you that excel at fetching hard-to-get items.$b$bFor this project, I require ink mixed from demonic blood. The blood of the demons at Felsoul Hold will serve as a suitable base. You will also need Blood of Sargeras, of course.', `QuestDescription`) WHERE `ID` = 39957;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Skin Deep', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire $1oa Stonehide Leather and $2oa Stormscales. If you are not a skinner, you may acquire them from the auction house or other players.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Welcome, $n. It\'s an honor to be working with someone of your caliber.$b$bIn order for us to begin our work together, we\'ll first need to collect some materials.$b$bThe Broken Isles are home to many strange, exotic creatures which no doubt have interesting hides to experiment with. We\'ll need scales to make mail armor with as well.$b$bGo and collect some materials for us so we may begin working.', `QuestDescription`) WHERE `ID` = 39958;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Plot Thickens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Undercity and look for F. Serbacon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Very well, I won\'t deny it. The Steamy Romance Novel is mine.$b$bI only read it for the penmanship, I assure you! He writes such curvy "B"s... and such ample "D"s!$b$bIn fact... you might benefit from a penmanship lesson. The author of these books is one F. Serbacon. I believe he can be found in the library in Undercity.$b$bStop reading, student. You are dismissed. And give me my book back!', `QuestDescription`) WHERE `ID` = 39959;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Legacy Passed On', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the Unfinished Steamy Romance Novel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve lost my passion, scribe. I just can\'t find the voice of my characters anymore.$b$bTake a look at that unfinished book over there on the table. I can\'t seem to finish it. Maybe you\'ll have an easier time with it.', `QuestDescription`) WHERE `ID` = 39960;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Embarrassing Revelation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Steamy Romance Novel to Professor Pallin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This doesn\'t appear to be an inscription textbook at all... it\'s more of a steamy romance novel. The pages are just FILLED with tawdry tales of carnality.$b$bCould it have something to do with inscription? Either way, Professor Pallin should be confronted.', `QuestDescription`) WHERE `ID` = 39961;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trouble for Okuna', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search for Okuna Longtusk.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<You open the bottle and find a message inside.>nnHelp! I need somebody... but not just anybody. I need a champion! I finally escaped the grasp of Prince Oceanus only to be hunted by his father, King Deepbeard.nnI was enjoying my freedom and decided to go fishing when that giant attacked. I\'ve been running around these islands trying to avoid that creature ever since... if anyone gets this message, please send help!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Helya', `PortraitGiverName`) WHERE `ID` = 39962;
