UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Huln\'s War - The Arrival', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat $2oa Legion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Huln Highmountain is the origin of our strength as a tribe. He bested the Legion when last they threatened our survival and unified many disparate tribes.nnLive his story, and you will know why his name imbues courage in the cowardly and sows fear in the fearless.', `QuestDescription`) WHERE `ID` = 39983;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Remnants of the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate clues to discover the fate of Tideskorn Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The journal entry appears hastily written.>$B$BI do not know what has become of my village. Ever since the mists engulfed the harbor, my kinsfolk have changed.$B$BSome have grown violent and savage, while others have fallen into madness. Many have ventured into the mists and have yet to return.$B$BIn these times, we can usually turn to our leader, Jarl Tarben. Alas, the mists have taken him as well.$B$BI do not know what will become of me. For now, I can only stay at my post and remain vigilant.', `QuestDescription`) WHERE `ID` = 39984;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Khadgar\'s Discovery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Champion! Please come to the Violet Citadel immediately.$B$BI have made a discovery that I would like to share with you before the Council of Six.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Archmage Khadgar', `PortraitGiverName`) WHERE `ID` = 39985;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Magic Message', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Examine the Arcane Anomaly in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'For the last 10,000 years, the elven city of Suramar has been sealed in an arcane barrier, much like Dalaran once was.$B$BThat barrier has come down.$B$BSince then, waves of magical energy have been emanating from the city like ripples in a pond. It was in these waves that I sensed a pattern.$B$BA spell, encrypted among the chaos.$B$BI have recreated the spell here. It\'s not dangerous, but beyond that... I have no idea what it does!', `QuestDescription`) WHERE `ID` = 39986;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trail of Echoes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Khadgar\'s Wand to find Arcane Echoes and track down First Arcanist Thalyssra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Nightborne could prove powerful allies against the Legion. We must aid this Thalyssra if we can.nnWe should be able to find her by tracking her magical echoes, the same way I found her distress call.nnI can teleport you near the location where she recorded that message. From there, you must search for ripples in the very fabric of the arcane itself.nnMy wand should do the trick. Follow the sparks it creates--they should lead you to places where Thalyssra used her magic.', `QuestDescription`) WHERE `ID` = 39987;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Huln\'s War - Stormrage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Malfurion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Eche\'ro nuzzles your hand and turns around. It looks back, beckoning you to the south.>', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Malfurion.', `QuestCompletionLog`) WHERE `ID` = 39988;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Huln\'s War - Reinforcements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defend Malfurion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle. I would speak with you on this later. It is a rare gift indeed.nnBut now, I ask for your help, Huln Highmountain. I must finish my incantations to allow dryads from beyond the veil to enter this place and lend us their aid.', `QuestDescription`) WHERE `ID` = 39990;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blessing of Cenarius', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Cenarius.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle.nnSpeak with him in the grove to the south.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet with Cenarius.', `QuestCompletionLog`) WHERE `ID` = 39991;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Huln\'s War - The Nathrezim', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Tichondrius.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I am fully occupied here organizing my troops and planning for the battle to come.nnWhile I would like to slay the Dreadlord Tichondrius myself, I will allow that honor to be yours, Huln Highmountain.', `QuestDescription`) WHERE `ID` = 39992;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Abandoned Fishing Pole', `LogTitle`) WHERE `ID` = 39993;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crab Rider Grmlrml', `LogTitle`) WHERE `ID` = 39994;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rockaway Coast Treasure', `LogTitle`) WHERE `ID` = 39995;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rockaway Coast Treasure', `LogTitle`) WHERE `ID` = 39996;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rockaway Coast Treasure', `LogTitle`) WHERE `ID` = 39997;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Drive Back the Tideskorn', `LogTitle`) WHERE `ID` = 39998;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rockaway Coast Treasure', `LogTitle`) WHERE `ID` = 39999;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A True Hunter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Prove you\'re a worthy hunter by hunting Bonebeak Hawks in Sunfrost Glade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I don\'t know why Hemet hunts with Razik. His contraptions are unreliable at best! nnA true hunter doesn\'t need gadgets to hunt. They rely on instinct, skill, and agility.nnSo tell me, $n, do you have the skills of a true hunter? Better yet, prove it.nnTake down some of the Bonebeak Hawks that circle the nearby meadow.', `QuestDescription`) WHERE `ID` = 40000;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knocking on Valor\'s Door', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Vethir in the Felskorn Camp.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Halls of Valor is your destiny to claim, but it is already in the claiming. The God-King befouls its steps with demons and wickedness.nnYour dragon allies have come to Halls\' defense, but they need your aid. The vrykul have taken the leader of the storm dragons, the one you call Vethir.nnFree your dragon friend, champion, and wash the Felskorn from the Gates of Valor!', `QuestDescription`) WHERE `ID` = 40001;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Familiar Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Jailer\'s Shard from Dravax and free Vethir from his prison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We had come to defend the Halls of Valor... I was taken from the sky...nnI cannot break free of my bindings. Find the jailer who made this cell...nnSet me free, friend...', `QuestDescription`) WHERE `ID` = 40002;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stem the Tide', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Stormforged Horn to destroy the three Felbound Portals in Gates of Valor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Skovald has profaned the Gates of Valor with his demonic allies. Among his forces his twisted mystics have conjured portals to ferry his fel allies from their blighted worlds. nnIf we wish to stem this tide, these portals must be destroyed. nnI will gather my allies. Take this horn and signal when you have found a portal, and we will strike from the skies!', `QuestDescription`) WHERE `ID` = 40003;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Break the Spine', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Garzareth, Karuas, Muorg and Ravathes in Gates of Valor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To lead his tainted forces,  the God-King has enlisted demons of great power to act as his lieutenants. If we wish to end his assault, we will need to take their leaders.nnThese demons are too powerful for most mortals to face, but with the power of Stormheim at your disposal, they will prove no match for you. nnTake them down, and shatter the spine of Skovald\'s offensive!', `QuestDescription`) WHERE `ID` = 40004;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stormheim\'s Salvation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat God-King Skovald in the Gates of Valor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It would seem that the portals we destroyed down here were not the only ones. Demons still pour in from the top of the Gates of Valor\'s edifice, summoned by the God-King himself!nnI cannot face Skovald alone. Come, champion, let us take the battle to him and end this threat!nnFor Stormheim!', `QuestDescription`) WHERE `ID` = 40005;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sylvan Falls Treasure', `LogTitle`) WHERE `ID` = 40006;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fields of An\'she Treasure', `LogTitle`) WHERE `ID` = 40007;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Only Way Out is Through', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort Thalyssra to safety.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have much to tell you, but it is not safe to speak here. I cannot hold this barrier forever.nn<Thalyssra lifts a delicate flask to her lips. Her eyes shimmer as she takes a sip.>nnIf we push through, we may find shelter up ahead.', `QuestDescription`) WHERE `ID` = 40008;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arcane Thirst', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter Shal\'Aran and find something to sate Thalyssra\'s thirst.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My people have subsisted on the Nightwell for millennia. Ancient mana is our lifeblood - without it, we become... well, you saw them out there.nn<Thalyssra holds her flask aloft, gently shaking free the last precious drops.>nnI\'m afraid I have been rather reckless today. nnAlready, my senses are dulling. Without magic to feed upon, I will turn. nnPlease... find me something to feed upon... anything...', `QuestDescription`) WHERE `ID` = 40009;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tapping the Leylines', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Explore Anora Hollow and find the Ley Station there.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The arcways were built to tap into the magical leylines beneath Suramar. As we learned to subsist on the Nightwell, the old facilities fell out of use.$B$BThis chamber is clearly receiving power from elsewhere.$B$BThere is only a trickle now, but if you can direct more leyline energy here it will help to sustain us.$B$BThe closest source is to the north, near Anora Hollow.', `QuestDescription`) WHERE `ID` = 40010;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Oculeth\'s Workshop', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Give the First Arcanist\'s Token to Chief Telemancer Oculeth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need to make contact with Chief Telemancer Oculeth, the man who developed Suramar\'s teleportation network. nnOculeth had a workshop in old Suramar, from the age before the Sundering. He may be taking refuge there.nn<Thalyssra presses a small coin into your palm.>nnIf you find him, show him this. Hopefully you see him before he sees you...', `QuestDescription`) WHERE `ID` = 40011;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Old Ally', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Arcanist Kel\'danath\'s hideout in Ambervale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was on my way to Ambervale in hopes of finding an old colleague.nnArcanist Kel\'danath was fascinated by the withered. He studied them for years hoping to calm their feral nature or even cure them.nnWhen one of his subjects escaped and ran amok in the royal gardens, Kel\'danath was ordered to cease his research and kill all withered in his possession. He refused, and was exiled.nnIf Kel\'danath lives, he is near withered. And withered are drawn to old settlements like Ambervale.', `QuestDescription`) WHERE `ID` = 40012;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aethril Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Aethril Sample to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This herb has clearly been absorbing magical energy from the land. Filaments of ley energy course from root to leaf.$b$bYour herbalism trainer in Dalaran will want to see this.', `QuestDescription`) WHERE `ID` = 40013;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spayed by the Spade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Pristine Pistil and a Stainless Stamen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The stem, leaves, and petals are dazzling, to be certain... but look at the pollination filaments, here, and the reproductive organs in the center of the bloom. They contain more energy than the rest of the plant put together.$b$bI suspect that we can more responsibly and efficiently harvest aethril by focusing on these parts.$b$bStill, it looks like this bloom has been damaged. I need undamaged parts if I\'m to be sure.', `QuestDescription`) WHERE `ID` = 40014;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ragged Strips of Silk', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Kuhuine Tenderstride about aethril and the withered.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Finely made strips of clothing, torn, tattered, and dirty: telltale signs of the withered.$b$bThe feral, degenerate outcasts of nightborne society must also be harvesting the aethril... but why?', `QuestDescription`) WHERE `ID` = 40015;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Desperation Breeds Ingenuity', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Chewed Aethril Stems from Withered in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I believe we may be able to use this clue to our advantage, $n.$b$bThe withered are notoriously thirsty for mana, and will stop at nothing to get it. Perhaps we can study how they use the aethril and use the results to improve our own harvesting methods.', `QuestDescription`) WHERE `ID` = 40016;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Slip of the Hand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Kuhuine Tenderstride about the quick-reproducing property of aethril.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you harvest the aethril, your hand brushes the flower\'s pollinating organs against one another, creating a reaction.$b$bYou may have discovered a new herbalism technique. Your trainer in Dalaran would be a good person to discuss this with.', `QuestDescription`) WHERE `ID` = 40017;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dreamleaf Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Dreamleaf Sample to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The herb is brilliantly green, paper-thin, and somewhat sticky.$b$bYour herbalism trainer in Dalaran will want to see this.', `QuestDescription`) WHERE `ID` = 40018;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Empathetic Herb', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Healthy Dreamleaf and $2oa Blight-Infested Dreamleaf.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Something is different about this dreamleaf, though. It is less than pure.$b$bI have a theory.$b$bThe wilds of Val\'sharah have been blighted by a nightmarish curse. Sensitive herbs like this may be susceptible to such a blight.$b$bI need more information before I can draw any conclusions. Find me some healthy samples and some blight-infested samples, and we can continue.', `QuestDescription`) WHERE `ID` = 40019;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Twisted to Death', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find someone in Lorlathil to teach you about the blight\'s effects on herbs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The corruption has completely taken this herb.$b$bThis blight is a mysterious force whose complexities transcend the teachings of simple herbalism. An expert in such infestation will need to tell you what\'s really going on here.', `QuestDescription`) WHERE `ID` = 40020;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One Dead Plant is One Too Many', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa satyrs within Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must exact VENGEANCE for this. While I understand the importance of the balance between the Emerald Dream and the Nightmare, this time it\'s corruption has gone TOO FAR!$b$bSatyrs. I blame the satyrs for this. Make them pay! Make them pay, and Elune will reward you with her bounty!', `QuestDescription`) WHERE `ID` = 40021;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Choked by Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Blight-Choked Herb to Wildcrafter Osme in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Another plant, killed by the blight. This one coiled so hard that it starved itself of sunlight.$b$bYou should bring it to Wildcrafter Osme in Lorlathil. He won\'t be happy.', `QuestDescription`) WHERE `ID` = 40022;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Last Straw', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Tur\'xoran\'s Summoning Stone to summon and slay Tur\'xoran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We cannot falter in our crusade against this corruption, $n.$b$bIt is our duty as heroes. As herbalists.$b$bAs hero-balists.$b$bSlaying simple satyrs will not do. We must attack their leaders. Bring this fallen herb to Shala\'nir, in the northeast. Find Tur\'xoran\'s summoning stone, and place this herb in front of it. Then... rip off his head.$b$bDo it for the plants.', `QuestDescription`) WHERE `ID` = 40023;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Foxflower Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa samples of Foxflower, then bring them to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Something about this herb catches your eye... and your nose.$b$bYour herbalism trainer in Dalaran would certainly be interested in studying some samples of this piquant new flower.', `QuestDescription`) WHERE `ID` = 40024;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Teeny Bite Marks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Nibbled Foxflower Stem to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This herb has been chewed by some of the local wildlife.$b$bWhat kind of animal would eat foxflower? A bear?$b$bPerhaps your trainer in Dalaran will know.', `QuestDescription`) WHERE `ID` = 40025;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Chase the Culprit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find out what creature has been eating Foxflower, then chase it and catch 12 Chewed Foxflower Bits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is a powerful herb, $n. Creatures will occasionally snack on some simpler herbs, but usually they avoid plants of such potency.$b$bI\'m intrigued. What kind of animal would eat foxflower? A moose?$b$bYou should investigate further. Find out what creature has been snacking on foxflower, and then see if you can wrestle some of the flowers from its mouth, before it escapes.', `QuestDescription`) WHERE `ID` = 40026;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Pied Picker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Foxflower Scent Gland to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you finish gathering the foxflower, a particular part of the bloom catches your eye.$b$bOne of the leaves has a small protuberance, right where it meets the stem. Further investigation suggests that this is where the foxflower\'s unusual smell comes from.$b$bYour herbalism trainer would be interested in seeing this.', `QuestDescription`) WHERE `ID` = 40028;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fjarnskaggl Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring $1oa Fjarnskaggl to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To one not trained in herbalism, this brambly bush might appear to be entirely useless. Your training, however, reveals this to be a very special plant indeed.$b$bYour herbalism trainer in Dalaran will want to see some more samples of this.', `QuestDescription`) WHERE `ID` = 40029;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ram\'s-Horn Trowel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Ram\'s-Horn Trowel to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The rune markings along the tool\'s grip suggest that it was left behind by a vrykul herbalist.$b$bApparently, the vrykul are also gathering this fjarnskaggl. Your trainer, Kuhuine, mentioned that she had read about this herb in the past.$b$bPerhaps she might be interested in seeing the tools that the vrykul use to harvest it.', `QuestDescription`) WHERE `ID` = 40030;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vrykul Herblore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find three vrykul Herbology books in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Kuhuine studies the trowel further.>$b$bThis is a standard digging tool. There is not much to be learned here, except...$b$b...this DOES suggest that the vrykul are still actively gathering this herb.$b$bThe vrykul likely know much more about this herb than we do. All we need to do is find out where their knowledge is stored.', `QuestDescription`) WHERE `ID` = 40031;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Missing Page', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Runed Journal Page to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The page appears to be ripped out of a larger book. It reads:>$b$b"...the Cairn of the Sea, a place long-known to be beloved by the gods.$b$bHe placed his offering of fjarnskaggl at the foot of the cairn, mouthed the words \'Herbs beget herbs\', and received the blessing he desired."$b$bThis may be related to the books you brought back to your herbalism trainer.', `QuestDescription`) WHERE `ID` = 40032;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fjarnskaggl', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 20 Fjarnskaggl to the Wind-Worn Cairn in Stormheim, then earn the Blessing of Fjarnskaggl.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There! It seems that there was a vrykul herbalist, Torgus, who brought a gift of fjarnskaggl to a seaside cairn - presumably in Stormheim - and by doing so received a blessing from his ancestors.$b$b<Kuhuine shrugs.>$b$bIt\'s worth a shot, though without knowing what you\'re getting into, you may want to bring friends with you.', `QuestDescription`) WHERE `ID` = 40033;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Starlight Rosedust', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Starlight Rosedust to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Despite all your training, the rose disintegrated in your hand.$b$bYour herbalism trainer in Dalaran will want to see this.', `QuestDescription`) WHERE `ID` = 40034;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Gentlest Touch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Attempt to harvest $1oa more Starlight Roses.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Sadly, I don\'t have any special techniques that can help you here. You\'ll simply need to practice your methods. Get back out there, and focus on a gentle touch when dealing with starlight roses.', `QuestDescription`) WHERE `ID` = 40035;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Jeweled Spade Handle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Jeweled Spade Handle to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'An immaculately carved spade handle lies beside the rose. Apparently the spade was more beautiful than it was durable, as the blade has completely fallen off.$b$bYour herbalism trainer may be interested in seeing this.', `QuestDescription`) WHERE `ID` = 40036;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Spade\'s Blade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Broken Herbalist\'s Blade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Did you notice the script along the base of the handle, $n? It says "Herbalist Tharillon," in the writing of the nightborne.$b$bThe handle does little for us, but perhaps the blade of this spade will give us some information on how to harvest the starlight rose without failing quite so often.$b$bI would start my search for it in Suramar.', `QuestDescription`) WHERE `ID` = 40037;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Insane Ramblings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Scribbled Ramblings to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Scribbled, angry phrases on a dirty scrap of vellum. One part catches your eye:$b$b     "thinks $gHE:SHE; knows how to gather herbs$b $n$N$b$N$N    steal my blade$b  slit $ghis:her; THROAT when I$b$b        just need$b      a bit more mana$b    maybe aethril, yes..."$b$bYour herbalism trainer may be interested in seeing this.', `QuestDescription`) WHERE `ID` = 40038;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tharillon\'s Fall', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 20 piles of Starlight Rosedust to Azsuna, use them to taunt Herbalist Tharillon out of hiding, then search him for information about herbalism.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'He mentions your name... his blade... aethril...$b$bI\'d say that this is absolutely from Herbalist Tharillon, and by the look of it, he may have succumbed to the plight of the nightfallen. Furthermore, if he\'s looking for aethril, he\'s probably in Azsuna somewhere.$b$bTharillon is currently our only hope for learning more about starlight roses. Seek him out, but you may want to bring friends... he likely won\'t go without a fight.', `QuestDescription`) WHERE `ID` = 40039;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felwort Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Felwort Sample to Kuhuine Tenderstride in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This herb bubbles and seethes with a foul energy. It is smooth, dry, and cool, yet somehow quite painful to touch.$b$bYour herbalism trainer in Dalaran will want to see this.', `QuestDescription`) WHERE `ID` = 40040;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felwort Analysis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Ryno Bloomfield\'s Analysis, Dani Earthtouch\'s Analysis, and Lohor\'s Analysis.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I sent felwort samples to some of my fellow herbalists, but haven\'t heard back from them yet. Could you please follow up with them and collect their analyses.$b$bRyno Bloomfield is currently working in Un\'goro Crater.$b$bDani Earthtouch is researching Freya\'s influence in Sholazar Basin.$b$bFinally, Lohor has been working in the overgrown portion of Gorgrond.', `QuestDescription`) WHERE `ID` = 40041;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Emerald Nightmare: Felwort Mastery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Emerald Nightmare and cleanse Cenarius of his affliction. Bring back anything you discover to Kuhuine in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have a theory on how we can better harvest this felwort, $n. You see, sometimes in order to understand how something comes into being, you have to work backwards.$b$bI\'ve recently heard of the corruption of one of our greatest gods, Cenarius. I have no doubt the same corruption that lives in these herbs also resides within him now.$b$bIf you were able to cleanse that corruption, find a way to understand how it works and remove it, I think we can apply that to how we harvest these herbs.', `QuestDescription`) WHERE `ID` = 40042;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hunter of Heroes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deal with Vigfus Bladewind\'s warband and claim his blades.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Helya has made a mockery of my order by creating her own "helarjar", powerful undead tasked with hunting down heroic warriors and taking their souls before my val\'kyr can claim them. Among them is her personal champion, Vigfus Bladewind, who wields stolen blades I forged myself long ago.nnHe has returned to Tideskorn Harbor with a full cargo of stolen souls to take to Helheim. Go there, kill him and his helarjar, and make the swords yours.', `QuestDescription`) WHERE `ID` = 40043;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shadows in the Mists', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Captain Sten, Sigrid, Kjell and Halvir in Helmouth Shallows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Many of the Kvaldir here in the bay are former denizens of this harbor, cursed by the sea-witch Helya to do her bidding for all time.nnThe ones you read about, they still walk the stagnant waters. They could be given respite, should a kind soul bring it to them at the tip of a blade.nnSo tell me, how kind is your soul?', `QuestDescription`) WHERE `ID` = 40044;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nature vs. Nurture', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to $1oa Swamprock Tadpoles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I appreciate murloc-kind far too much to tell you to go kill all the adults.nnWhat we should be doing is setting up the next generation to be more peaceful; Murky is the best representative for this. nnBring him to talk to the murloc tadpoles. He\'ll get them on our side.', `QuestDescription`) WHERE `ID` = 40045;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scavenging the Shallows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the Shipwreck Debris in Helmouth Shallows for Havi\'s clue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The kvaldir exist to spite Odyn, and it is here their spiteful work is done. They rob the souls of the living - the souls not yet judged - thus robbing Odyn of his champions.nnThey bring them here to transport to Helya, though the mists obscure any indications of how.nnYou seem to fare the mists well. Perhaps if you search the wreckage in the bay, the answer may present itself. You outsiders seem to have a knack for uncovering the most hidden of secrets.', `QuestDescription`) WHERE `ID` = 40046;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'I\'ll Huff, I\'ll Puff...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Pufferfish Eggs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Murky is my favorite little fella. However, in order to lead a change in the murloc population here, he needs some awesome abilities.nnThere are a lot of pufferfish around in the water, and I think that they could be a good resource for him. nnKill a few and collect their eggs for Murky.', `QuestDescription`) WHERE `ID` = 40047;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Strings of the Puppet Masters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire a Rune of Dominance from the demons at Legion Camp: Chaos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I understand you were just here to deliver the vellums, but we could use your skills as a $c. Our forces can only hold back the demon invasion, disallowing us to send anyone further into the enemy\'s camp.$b$bThe stronger of their forces stay in the back, commanding from a distance. They carry enchanted runes to keep control over the frontline demons.$b$bI would very much like to study one of these runes. Please retrieve one for me, so we may learn from it and use it against the Legion.', `QuestDescription`) WHERE `ID` = 40048;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Slime Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Feed Murky $1oa Bunches of Slimeweed by swimming through them.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Murky\'s a growing boy, he needs to eat! What better than slimeweed for a young murloc?nnThere\'s plenty of it around in the water amongst the murlocs; swim through it and feed Murky!', `QuestDescription`) WHERE `ID` = 40049;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shipwreck Cove', `LogTitle`) WHERE `ID` = 40050;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel Secrets', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Read the Tome of Fel Secrets to choose between the Havoc and Vengeance specializations.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demons made a grave error inscribing their secrets into this book. The fel energy emanating from it is potent.nnBut there\'s only enough to enact one of the rituals. After that, the book will be consumed.nnIt\'s up to you to choose which secrets we want to use against the Burning Legion.', `QuestDescription`) WHERE `ID` = 40051;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ancient Vrykul Mastered', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return the tablets and codex to Professor Pallin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here are those tablets back, along with their deciphered writing. You can take this codex back to Pallin, too. I\'ll start getting my things ready for when he calls me back to Dalaran.$b$b<Nicholo sighs.>$b$bLearn from my example, $n. If I were you, I\'d break free from Pallin\'s "requests" as soon as you can.', `QuestDescription`) WHERE `ID` = 40052;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Our New Allies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Allari the Souleater in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Student! Your fellow demon hunters in Azsuna have sent for you.$b$bI can certainly appreciate your time being spent fending off the Legion, but it doesn\'t excuse you from your studies.$b$bWhile you\'re down there, I\'d like you to come up with some new glyphs for your abilities.$b$bSurely my genius has worn off on you and you\'ll be able to create your own recipes based on what you learn.', `QuestDescription`) WHERE `ID` = 40056;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Price of Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa demons to help lessen the invasion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I see, you wish to augment your powers through script. I believe we can kill two birds with one stone then.$b$bI need help here reducing the demon threat. Perhaps some more engagement with our enemy will inspire you.', `QuestDescription`) WHERE `ID` = 40057;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Defense Symbology', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Baric Stormrunner near the Ley-Ruins of Zarkhenar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you know, $n, we demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves.$b$bUp to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. He could use your assistance with his ritual.', `QuestDescription`) WHERE `ID` = 40058;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Opposites Repel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect ley dust from the nightfallen in Zarkhenar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The ruins nearby have had an eruption of ley energies. Twisted night elves deemed "Nightfallen" are scavenging the area as we speak.$b$bCollect ley dust for me from the nightfallen in the ruins up ahead. The dust is infused with arcane energy that I\'ll need to complete my ritual.', `QuestDescription`) WHERE `ID` = 40059;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Containing the Demon Within', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist Baric in completing the ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have all the essential pieces, let\'s begin the ritual.$b$bI\'ll instruct you on how to help me throughout it. It is pivotal that you follow my instructions when I give them, or the ritual will fail.', `QuestDescription`) WHERE `ID` = 40060;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Know Your Enemy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Zaria Shadowheart near the Felblaze Ingress.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we fight the demons, we\'ve also been studying them.$b$bGreat understanding can come from gathering intel. I have a demon hunter near the Felblaze Ingress now gathering intel on the demons there.$b$bGo to her and see what she has learned from the demons invading that region.', `QuestDescription`) WHERE `ID` = 40061;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bulging Nightmare Pod', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Bulging Nightmare Pod to Professor Pallin in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The flower has folded inward, to protect itself from the nightmare energy trapped within.>$b$b<Professor Pallin would be interested in seeing this.>', `QuestDescription`) WHERE `ID` = 40062;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Control is Key', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the crystal providing protecting Overseer Felorax, then slay him.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I trust you remember why you removed your eyes?$b$bEven though we can see more clearly now, the demons have found ways to mask even their fel energies from us.$b$bA demon commander walks amongst the troops below, commanding them from the shadows. His cloak is powered by an energetic crystal.$b$bFind and destroy that crystal, then kill the commander.', `QuestDescription`) WHERE `ID` = 40063;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Woody Seed Cluster', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Woody Seed Cluster to Professor Pallin in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Attempting to mill this flower has proven more difficult than usual. Located in the bushy center of the bloom is a densely-packed cluster of seeds.>$b$b<Professor Pallin would be interested in seeing this.>', `QuestDescription`) WHERE `ID` = 40064;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fjarnsk', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Fjarnsk to Professor Pallin in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<A goopy substance seeps from the interior of the bloom. It\'s not ink... it is something else entirely.>$b$b<Professor Pallin would be interested in seeing this.>', `QuestDescription`) WHERE `ID` = 40065;
