UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fledgling Worm Guts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Worm Guts from Fledgling Rockcrawlers within Rockcrawler Chasm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The drogbar use these caves as a place to train fledgling worms.nnThe rockcrawlers are young and fairly weak, for now, but in time they will grow in size and strength. Without our intervention, the worms will morph into the monstrosities that the drogbar ride into battle.nnTheir guts are also known to be quite useful, and I have need of them. Two worms, one stone.', `QuestDescription`) WHERE `ID` = 40069;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eagle Egg Recovery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Head into Rockcrawler Chasm and recover eagle eggs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Eagles are revered by the Skyhorn tribe, but their numbers are dwindling.nnThe drogbar feed their fledgling worms eagle eggs so they\'ll grow strong enough to ride into battle. nnIf the drogbar continue to pilfer these eggs, the eagles may become extinct.nnHead deeper into the cave and recover any eagle eggs you can find.', `QuestDescription`) WHERE `ID` = 40070;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tamer Takedown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Tamer Korgrul within Rockcrawler Chasm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The drogbar will continue to breed vicious worms as long as their tamer lives. nnKorgrul is responsible for turning fledgling rockcrawlers into the monstrous siege worms that are ridden into battle.nnHead deep into the chasm and end his life, so that we may also see the end of these unnatural creatures.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Tamer Korgrul', `PortraitGiverName`) WHERE `ID` = 40071;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: Securing the Aegis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat God-King Skovald in the Halls of Valor and claim the Aegis of Aggramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Felskorn may be broken, but the head of the beast yet lives. The God-King will still vie for the Aegis if left unchecked.nnYou, who have completed trials upon trials, must not let this come to pass. You must claim the Aegis over Skovald\'s broken bones!nnThe Halls of Valor await!', `QuestDescription`) WHERE `ID` = 40072;
