UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Invasion Begins', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa demons and change the Legion banner to take control of Despair Ridge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our advance force of demon hunters is here and has engaged the Legion.nnMake our presence known. Let\'s send a shiver down every demon spine. Raise our colors with pride, $n.', `QuestDescription`) WHERE `ID` = 40077;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Heavy Burden', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the fish from Havi\'s Fish Barrel and skewer it on the spear above the fire.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With Ashildir\'s judgment, your final trial is complete. nnBut even Valhallas can wait, for now we must eat! Being dead works up quite an appetite.nnCome now, bring some of that fish to roast over the fire. It is far too heavy for me to carry.', `QuestDescription`) WHERE `ID` = 40078;
