UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Murlocs: The Next Generation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mindmeld with Murky and slay $2oa Cavemoss Clackers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time has come! Murky and his followers need a place to hide out and train--away from the mature murlocs--so that they can prepare to take over in the future.nnThere\'s a nice cave not too far away... only problem is that it\'s filled with makrura.nnThis would be a good base for the tadpoles. Murky must go show them what for!nnMindmeld with Murky in his egg and show him how it\'s done!', `QuestDescription`) WHERE `ID` = 40102;
