UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Huln\'s War - Malorne\'s Favored', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue Eche\'ro.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[In broken Common] Shan\'do ask for you. Sent Eche\'ro beast with message on rack.nnUnng Ak hear Eche\'ro sound fighting. You find beast? Give help, maybe feathered night elf be relieve.', `QuestDescription`) WHERE `ID` = 40112;
