UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Murky Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Smoldering Torch to burn 8 Decaying Corpses in Morheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You may not know, but you stand upon the grounds of Morheim, home to the greatest warriors of the land. Our deeds were great, our valor legendary. It pains me that we see such an end.nnThe creatures set upon us at nightfall. Our men fought bravely, but were vastly outnumbered. Now their corpses lie rotting in the sun, with no burial and no rites.nnThis is not an end befitting to the glorious warriors of Morheim. Make it right, and you will have our thanks.', `QuestDescription`) WHERE `ID` = 40120;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ley Line Influences', `LogTitle`) WHERE `ID` = 40121;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cenarius, Keeper of the Grove', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Malfurion Stormrage at Lorlathil in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ahh, Val\'sharah.$b$bIt has been an age since I have set foot in these sacred woods. Too long...$b$bOur work here is simple, $c. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras\' Tomb and thwarting the Legion.$b$bYou have many treacherous tasks in front of you. Consider your visit here a brief respite.$b$bCome, this will not take long.', `QuestDescription`) WHERE `ID` = 40122;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nightborne Pact', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bandage Thalyssra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Thalyssra winces and holds her abdomen.>nnNgh... I can ignore this wound no longer.nnHelp me patch this up. I will explain everything.', `QuestDescription`) WHERE `ID` = 40123;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gift of the Storm Cooldown', `LogTitle`) WHERE `ID` = 40124;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Branch of the Arcan\'dor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Thalyssra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have used the spellstone of Kel\'danath to soothe countless withered. Yet it contains merely a shade of the arcan\'dor\'s power, drawn from its slumbering seed. nn<Thalyssra holds aloft a gleaming white branch.>nnThis fell from the tree. Though it is severed, it is not dead - invisible threads of magic bind all pieces of the arcan\'dor together.nnI have enchanted this branch with a new iteration of Kel\'danath\'s charm spell. With it, you can mend the arcane essence of even more withered. Use it well.', `QuestDescription`) WHERE `ID` = 40125;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Grelda', `LogTitle`) WHERE `ID` = 40126;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Da-Nel\'s Quest', `LogTitle`) WHERE `ID` = 40127;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Repairing the Source', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'You have found a damaged power core for an arcane construct. It seems like you could repair the device.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<A glint catches your eye in the dirt. A brief excavation yields a mostly intact piece of an arcane construct\'s power core. The breaks appear to be clean, perhaps you could repair it if you find the other fragments.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Repair the power core.', `AreaDescription`) WHERE `ID` = 40129;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Washed Clean', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet the Fallen Priestess at the Nor\'Danil Wellspring. Watch as the priestess attempts the purification ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mighty though the Legion is, theirs is not the strongest power in Azeroth.$b$bThere is a place where Enchantress Ilanya and I spent many blissful hours together. The love that infuses such a place is more potent than fel magic, $n.$b$bGo to the Nor\'Danil Wellspring. Its waters can purify the fel dust you have collected... and perhaps purify me as well.$b$bI will meet you there.', `QuestDescription`) WHERE `ID` = 40130;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stonehide Leather Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Stonehide Leather Sample, along with $1oa additional pieces of Stonehide Leather, to Kondal Huntsworn in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The quality of this leather scrap appears representative of the beast hides found in the Broken Isles.$b$bYour skinning trainer in Dalaran would be interested in seeing this.', `QuestDescription`) WHERE `ID` = 40131;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In One Piece', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 20 Undivided Hides by skinning the beasts of the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your trainer looks over the hide.>$b$bThis hide is usable, but it is mournably small. You disrespect the beast by chopping it up like this, $n. You make light of the gift that it gave to you.$b$bGo out into the wilds again. Skin the leathery beasts below us, and this time, bring me hides in one piece.', `QuestDescription`) WHERE `ID` = 40132;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scrap of Pants', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Scrap of Pants to Hemet Nesingwary in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The mouth of this particular beast contained a piece of handsewn cloth. The fabric bears the word "singwa".$b$bWhile the term "singwa" is unfamiliar, it DOES happen to be the middle of the last name of a fairly notable Azerothian skinner.', `QuestDescription`) WHERE `ID` = 40133;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Highmountain Hides', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Bear Hides, $2oa Elderhorn Hides, and $3oa Saber Hides by skinning the creatures of Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So, ye\'re a skinner too, aye?$b$bThat\'s great news, $n! I don\'t think I ever knew we shared that in common.$b$bYe\'ve GOT ta see some o\'the hides we\'ve got here in Highmountain. Why, I\'d give me spare monacle just t\'get me hands on some o\'those fine, silky hides...', `QuestDescription`) WHERE `ID` = 40134;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Freedom to Roam', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Musken Hides, $2oa Lion Seal Hides, $3oa Boar Hides, and $4oa Wolf Hides.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I remember bein\' young, $n. D\'ye remember it? So much less responsibility... I could just run around as I pleased. Now, I\'m pretty much stuck with my hunting crew, here in Highmountain.$b$bThere\'re so many interestin\' creatures in the other regions o\'the Broken Isles, though. I\'ll mark yer map, you get out there and do some skinnin\'!', `QuestDescription`) WHERE `ID` = 40135;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Immaculate Stonehide Leather', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Immaculate Stonehide Leather to Kondal Huntsworn in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have been skinning for a long time now, but never have you seen a leather specimen as fine as this. Durable, pliable, beautifully colored...$b$bYour trainer in Dalaran would be VERY interested in seeing this.', `QuestDescription`) WHERE `ID` = 40136;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leather for Ske\'rit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Ske\'rit in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This hide certifies that you have learned everything about leather that I can teach you, $n. My skills have dulled since I set up shop here in town.$b$bI have a former protege who skins the creatures of Suramar. His name is Ske\'rit. His skills remain as sharp as his blade, and if there is anyone out there who can teach you, it is him.', `QuestDescription`) WHERE `ID` = 40137;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trial of the Crusader: Hides of Legend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Hide of Icehowl from the Trial of the Crusader.$b$bObtain the Hide of Occu\'thar from Baradin Hold.$b$bObtain the Hide of Horridon from the Throne of Thunder.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ya, I can train you. Ting is, I\'m still workin\' on my techniques \'ere in Suramar. In fact, you can probably help.$b$bI need ta look at a few special skins, for comparison. I need a strong white yeti pelt, a really big demon skin, and da thickest direhorn skin you can find.$b$bDo that, and I\'ll share my results with you and\' ol\' Kondal up in de city.', `QuestDescription`) WHERE `ID` = 40138;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: The Hide of Fenryr', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Hide of Fenryr by skinning Fenryr in Valhallas.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you be here, I got a favor t\'ask you.$b$bI been hearin\' whispers about one big, nasty wolf dat\'s been causin\' all kinds of trouble up in de vrykul lands. His name be Fenryr.$b$bI want his hide.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'The nigh-unkillable wolf of the vrykul\'s holy hunting grounds.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Fenryr', `PortraitGiverName`) WHERE `ID` = 40139;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ske\'rit\'s Leather Handbook', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Ske\'rit\'s Leather Handbook to Kondal Huntsworn in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'An\' wit dat, my research be done.$b$b<Ske\'rit hands you a scroll casing.>$b$bDis is what I been workin\' on here in Suramar. Bring it to Kondal, so dat he can teach it to all you other skinnahs.$b$bSince you been helpin\' so much, I put your name on it, $n. Hope you don\'t mind.', `QuestDescription`) WHERE `ID` = 40140;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stormscale Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Stormscale Sample to Kondal Huntsworn in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This scale shimmers with electrical energy.$b$bYour skinning trainer in Dalaran would be interested in seeing this.', `QuestDescription`) WHERE `ID` = 40141;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Core of the Stormscale', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Stormscale Sparks by skinning scaled creatures in the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ahh, yes. The elusive stormscale.$b$bI have seen similar scales in Northrend, and some in Skywall, but it would appear that such a scale is common here. My colleagues that specialize in mail armor will be happy to learn this.$b$bTo more efficiently harvest this type of scale, you must first understand its power. Look for broken, unusable scales on your quarry, and remove the sparks within them. Once you have seen the sparks, you will better understand the stormscale.', `QuestDescription`) WHERE `ID` = 40142;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unfinished Treatise on the Properties of Stormscale', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Unfinished Treatise on the Properties of Stormscale to Kondal Huntsworn in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tucked between the folds of this animal\'s hide, you find a scrap of paper. It appears to be a handwritten guide to harvesting stormscales, but too much of the manuscript has been lost to be of use.$b$bPerhaps your skinning trainer in Dalaran could help you find its owner.', `QuestDescription`) WHERE `ID` = 40143;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Glielle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Glielle in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One skinner makes the wilds of Azsuna her home. Her name is Glielle, and she is a night elf - or at least, she was, in life.$b$bPerhaps the scroll was hers.', `QuestDescription`) WHERE `ID` = 40144;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Under Down', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Hippogryph Scales.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can train you, though.$b$bEveryone knows about the bright stormscales on the hippogryph\'s hindquarters, but did you know that they also have a few scales beneath their feathers? You just need to know where to look.$b$b<The night elf spirit indicates a few places near the hippogryph\'s wing joints.>$b$bNow go see if you can get some on your own.', `QuestDescription`) WHERE `ID` = 40145;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seymour and Agnes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Seymour in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The other skinner - pair of skinners, to be honest - that comes to mind when you show me this scroll is a student of mine, named Seymour, and his mother Agnes.$b$bLast I heard, they were in Stormheim, hunting the storm drakes.', `QuestDescription`) WHERE `ID` = 40146;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mother\'s Prized Knife', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain Agnes\' Skinning Knife.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The other day, Mother and I were up at the top of the nearby mountain, and she threw her skinning knife at me because the view wasn\'t good enough.$b$bHer knife is still up there, somewhere. I\'d feel horrible just leaving it.', `QuestDescription`) WHERE `ID` = 40147;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Red-Eyed Revenge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Adult Squallhunters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It came out of nowhere. I was waiting for mother to finish skinning her half of the drake when the biggest storm dragon I\'d ever seen came and... and...$b$b<Seymour finds his resolve.>$b$bI want you to kill as many of them as you can. Skin them, don\'t skin them, I don\'t care. Just get revenge for mother!', `QuestDescription`) WHERE `ID` = 40148;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Drakol\'nir Must Die', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Scale of Drakol\'nir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The dragon that took Mother\'s life was named Drakol\'nir.$b$bMother always wanted to wear his scale as a pendant, but we never got a chance to skin him because I couldn\'t kill him alone, and she didn\'t care much for killing. Only skinning.$b$bYou... you wouldn\'t mind bringing it for her, would you?', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Mother would have wanted him dead.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Drakol\'nir', `PortraitGiverName`) WHERE `ID` = 40149;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Immaculate Stormscale', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Immaculate Stormscale to Kondal Huntsworn in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have been skinning for a long time now, but never have you seen a scale specimen as fine as this.$b$bYour trainer in Dalaran would be VERY interested in seeing this.', `QuestDescription`) WHERE `ID` = 40151;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scales for Ske\'rit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Ske\'rit in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your skills surpass mine, $n. I have never even SEEN a scale such as this... let alone remove one so expertly.$b$bIf you still wish to learn more, you will need to seek an even greater skinner than I. His name is Ske\'rit, and he was once my student.$b$bYou will find him in the wild areas of Suramar.', `QuestDescription`) WHERE `ID` = 40152;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Karazhan: Scales of Legend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Scale of Netherspite from Karazhan, the Scale of Sartharion from the Obsidian Sanctum, and the Scales of Garalon from the Heart of Fear.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know a ting or two about scales, but I\'m losin\' my edge. I been starin\' at stormscales so long, I be forgettin\' what de other kinds look like.$b$bI need ta look at a few special scales, for comparison. I need a nether dragon scale, a nice hot black dragonscale, and da thickest piece o\' insect chitin you can find.$b$bGotta get dese stormscales outta my head, bruddah.', `QuestDescription`) WHERE `ID` = 40153;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: The Scales of Serpentrix', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Scales of Serpentrix by skinning Serpentrix in the Wrath of Azshara dungeon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I got ta ask you a favor.$b$bI haven\'t been ta Azsuna, and I don\'t see myself leavin\' Suramar anytime soon. Problem is, dere\'s a big ol\' serpent out dere dat\'s just beggin\' ta be skinned. Just BEGGIN\' for it.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'One of the many horrible things living beneath the Thunder King\'s palace.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Serpentrix', `PortraitGiverName`) WHERE `ID` = 40154;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ske\'rit\'s Scale-Skinning Suggestions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Ske\'rit\'s Scale-Skinning Suggestions to Kondal Huntsworn in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now dat I got all dese scales, I tink I know what I need to know.$b$b<Ske\'rit hands you a few pages of handwritten notes.>$b$bHere\'s my latest findin\'s on stormscales. Bring \'em to Kondal, an\' read through em\' togethah.', `QuestDescription`) WHERE `ID` = 40155;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felhide Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Felhide Sample to Kondal Huntsworn in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This demonic hide is completely unlike any standard beast hide you are accustomed to.$b$bYour skinning trainer in Dalaran would be interested in seeing this.', `QuestDescription`) WHERE `ID` = 40156;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Unseemly Task', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Ske\'rit in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m quite impressed with what you\'ve been able to skin in these lands, felhide in particular.$b$bBut as my knowledge is limited in this area of skinning, I know of one who may have increased his skill in skinning such beasts.$b$bYou can find my old apprentice, Ske\'rit in Suramar. Ask him if he knows how to yield better results from skinning demons.', `QuestDescription`) WHERE `ID` = 40157;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkheart Thicket: Demons Be Different', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Darkheart Thicket and kill Dresaron. Skin him and bring his hide back to Ske\'rit in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh yes, I\'ve seen me fair share of demons while in dese lands. And skinnin\' dem ain\'t no easy task.$b$bTheir hides are tougher than normal animals, fibrous, see? But if you be wantin\' to make da most of their skins, den ya need to be practicin\' more.$b$bThere be a creature I\'ve heard of in da Darkheart Thicket whose hide\'s as tough as a demon\'s. When ya go ta skin him, try cutting with da grain in one even stroke.$b$bBring me his skin to show me you be picking up on what I\'m sayin\'.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Once a green drake, now engulfed in Nightmare.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Dresaron', `PortraitGiverName`) WHERE `ID` = 40158;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Emerald Nightmare: The Pestilential Hide of Nythendra', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Pestilential Hide of Nythendra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is one more demon hide to gather... but it isn\'t that of a demon. It\'s a dragon.$b$bNythendra, great green dragon, has nearly been eaten up by the Nightmare. Only a master skinner would be able to remove what bits of bug-eaten hide remain on her body.$b$bGo on then, $n. Show me what you\'ve learned.', `QuestDescription`) WHERE `ID` = 40159;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Magic Clams', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Infused Clams from Seerspine murlocs in the Murloc Shoals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The clam resonates with a arcane energy.>$B$BWhat are murlocs doing with arcane clams?$B$BPerhaps your Nightfallen allies could make use of them.', `QuestDescription`) WHERE `ID` = 40160;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tapping the Underground', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy Seerspine Conduits in the Murloc Shoals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Have you seen them, $n?$B$BThese are not ordinary murlocs. They have been drawn by the ley line that flows from Azsuna into this land. $B$BSomehow they have managed to tap into its arcane current and are tapping its power for their own devious purposes.$B$BThese disturbances must be stopped if the ley line is to remain intact.', `QuestDescription`) WHERE `ID` = 40161;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Snowblind Mesa Treasure', `LogTitle`) WHERE `ID` = 40162;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Snowblind Mesa Treasure', `LogTitle`) WHERE `ID` = 40163;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSE', `LogTitle`) WHERE `ID` = 40164;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leying with Murlocs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infuse yourself with ley energies located in the Murloc Shoals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have seen these Seerspine summon minor elementals, which is no small feat for a murloc, but their high summoner, Blargrrrl, is trying to summon Torretus from the river.$B$BI doubt a mere murloc has the capabilities to control an entity as powerful as Torrentus.$B$BBlargrrrl will be deeply entranced if he is trying such a feat. We\'ll need something powerful to halt his ritual.$B$BInfuse yourself with ley energies and return to me.', `QuestDescription`) WHERE `ID` = 40166;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Story of Huln', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Spiritwalker Ebonhorn to learn about Huln Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You work to unite the tribes. That is no small task. It has only been done once before in the history of this mountain.nnHuln Highmountain last united the tribes thousands of years ago to take on the Legion during the War of the Ancients.', `QuestDescription`) WHERE `ID` = 40167;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Swirling Vial', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Swirling Timewarped Vial to the central dome in Shattrath.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you touch the vial, your mind is flooded with memories, not all of which are your own. The most vivid is a memory of exchanging a similar vial with someone in Shattrath, with A\'dal\'s light shining behind you. Despite your best efforts however, you can\'t pinpoint when that might have been - maybe it hasn\'t been, and is yet to be?', `QuestDescription`) WHERE `ID` = 40168;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crossroads Rendezvous', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search for signs of the priestess near the Felblaze Ingress.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'An old apprentice of mine left during the war, shortly before we were all cursed.$b$bI\'ve recently heard that she\'s been seen near the Felblaze Ingress. I would very much like to speak to her once more.$b$bGo and find her. Take her journal to her and let her know that I don\'t blame her for what she did.$b$bAnd if she\'s willing, please bring her back to me.', `QuestDescription`) WHERE `ID` = 40169;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Amateur Hour', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Confront Amateur Hunters within Pinerock Basin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The hunters\' lodge has attracted a lot of amateurs who call themselves hunters. They\'re scarin\' away all the prize game with their antics.nnWhile I\'m a known expert with my rifle, I\'ve yet to manage the art of negotiation.nnHow about ya do us all a favor and tell those novice hunters to head for the hills?', `QuestDescription`) WHERE `ID` = 40170;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Unstable Prism', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the Frigid Timewarped Prism to an interested mage in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As the prism struggles to stabilize in a single time flow, it bleeds a shadowy chill, the likes of which you haven\'t felt since Northrend. Surely some mage in Dalaran would be interested in this relic.', `QuestDescription`) WHERE `ID` = 40173;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sleeping Bear', `LogTitle`) WHERE `ID` = 40175;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'From Head to Toe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a pair of Sturdy Stonehide Boots.$b$bYou will need to use Namha\'s Tanning Rack and Namha\'s Workbench, located in Legendary Leathers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve been busy, $n. And you have some new patterns in your repertoire, I see!$b$bHow about we add another?', `QuestDescription`) WHERE `ID` = 40176;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leather Lady', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Diane Cannings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'d like you to start working with my apprentices.$b$bThe first is Diane Cannings, who has focused her expertise on the softer leather armors. She\'s just not that into mail armor, like the twins are.$b$bGo talk to her about this new type of leather.', `QuestDescription`) WHERE `ID` = 40177;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vestment Opportunity', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Hideshaper\'s Vestment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While the vrykul of Northrend wore strong armor, their craftsmen always had the strongest.$b$bGo to Stormheim, search for someone who knows about leather armor, and bring their chest piece back to me.', `QuestDescription`) WHERE `ID` = 40178;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stormheim Savagery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Vrykul Leather Bindings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There\'s a land below - Stormheim, they call it - that\'s inhabited by vrykul. I remember the vrykul from my days in Northrend.$b$bWhat I remember most was how well-crafted their armor was.$b$bIf the vrykul here are as skilled as the ones in Northrend, then I\'m certain we can learn something by studying their armaments.', `QuestDescription`) WHERE `ID` = 40179;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mail Men', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Thanid Glowergold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The two dwarves behind me are the Glowergold brothers. They\'re my resident mail armor experts.$b$bWhile Ranid has decided to focus his skills towards lining his pockets, his brother, Thanid, still enjoys the crafting side of the trade.$b$bIntroduce yourself to Thanid. You may work with him to further our knowledge of turning these stormscales into something extraordinary.', `QuestDescription`) WHERE `ID` = 40180;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Bandit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa pieces of Black Rook Armor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve heard rumors of a grand castle in Val\'sharah that\'s known to house an impressive army. Surely, the armor they wear ain\'t made of sticks and hay.$b$bI\'m willing to bet they\'ve fashioned some mail armor at some point fer their troops and it\'s just sitting there, ripe for the taking.$b$bHow about ye head over there and see what ye can "borrow" from their armory.', `QuestDescription`) WHERE `ID` = 40181;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Too Good To Pass Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Black Rook Hauberk.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All types of Black Rook Hold armor are intriguing, but I\'m most interested in their chest pieces.$b$bIf ye can, try to find someone of importance there and... relieve them of their shirt.$b$bIf it makes ye feel any better, I\'ve heard they\'re all cursed, so puttin\' them out of their misery is the least ye could do.', `QuestDescription`) WHERE `ID` = 40182;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Over Your Head', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a Rough Warhide Mask.$b$bYou will need to use Namha\'s Tanning Rack and Namha\'s Workbench, located in Legendary Leathers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alright, $n, I\'d like you to assist me with creating a helm.$b$bFirst we\'ll need to shave the hides, then tan them, and finally cut them into usable pieces.$b$bFollow my lead.', `QuestDescription`) WHERE `ID` = 40183;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tauren Tanning', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Hrul Sharphoof.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Have you heard of the Highmountain tauren tribes? They\'re not unlike the tauren we know on Kalimdor.$b$bI\'ve heard they have a leatherworking master there who might be able to help us come up with some new patterns.$b$bTravel to Highmountain and see if they\'re willing to teach you how they craft their armor.', `QuestDescription`) WHERE `ID` = 40184;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shoulder the Burden', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain Lohrumn\'s Shoulderguard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'During one of our recent battles, my brother, Lohrumn, was slain. His armor was taken by the drogbar.$b$bYou would honor his memory by retrieving what has been stolen. I will make it worth your while, leatherworker.', `QuestDescription`) WHERE `ID` = 40185;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Drogbar Durability', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa drogbar to prove your worth to Hrul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are currently at war with a race known as the drogbar. We have long maintained peace with the drogbar, but lately, they have no respect for anyone but themselves.$b$bSlay them. Prove your worth as an ally of the tauren. Do this, and I will reward you with knowledge.', `QuestDescription`) WHERE `ID` = 40186;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Links in the Chain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find a leatherworking master in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well, $glad:lass;, I\'m afraid I\'m at me wits\' end with these scales. Not quite sure how to fashion the remaining pieces fer a full set.$b$bHowever, I\'ve heard that the elves of Azsuna had some great crafters in their cities. Perhaps one or two of them still exist.$b$bGo there and search fer a master. Maybe they can fill in the missing patterns fer us.', `QuestDescription`) WHERE `ID` = 40187;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Best Served Cold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Ranaris in the El\'dranil Shallows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My partner and I both fell victim to the fallout of the Sundering. We were betrayed and abandoned by a trusted friend.$b$bThat "friend" has recently appeared in the ruins to the east. His name is Ranaris.$b$bGo to and take revenge for us and I will grant you some of my wisdom.', `QuestDescription`) WHERE `ID` = 40188;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Naga Know-How', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Naga Shoulderguards.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The naga of this region wear little armor, but what they do wear is particularly durable.$b$bIf you wish to make a strong shoulder piece, I would first study the naga\'s armor and then create a pattern of similar construct.$b$bThe city nearby is overrun by naga. Slay them and bring me their armor and I will show you what I mean.', `QuestDescription`) WHERE `ID` = 40189;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hardening the Hide', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Highmountain and talk to Hrul Sharphoof.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Back to Highmountain for you, $n! I hear they know even more efficient ways to craft our patterns.$b$bWhen you get there, put in a good word for me, will ya? I\'d like to start a relationship the tauren, so I don\'t have to keep sending you back and forth.', `QuestDescription`) WHERE `ID` = 40190;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stamped Stories', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Learn from the stories of each of the tanning racks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Stamped onto the leather of the tanning racks behind me are the ancient ways of out tribe\'s leatherworkers.$b$bThey tell the stories of masters who, through perseverance - and luck, in some cases - pioneered our way of leatherworking.$b$bRead the stories and learn from them. Perhaps you\'ll find some insight on how to better your own methods.', `QuestDescription`) WHERE `ID` = 40191;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Claw of the Land', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Stalker Claws.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Personal experience has taught me to use stronger materials when crafting armor pieces. They last longer, and you don\'t need quite as many of them.$b$bFor example, I utilize the claws of the pinerock stalkers. If you acquire some for me, perhaps I can show you how better materials can increase your efficiency.', `QuestDescription`) WHERE `ID` = 40192;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Getting the Kinks Out', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go back to Celea in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now listen, $glad:lass;. Everything ye make can always be done better. I just haven\'t quite worked out the way to do it with these fancy new scales.$b$bPerhaps that ghost-like elf friend of yours can help ye. An\' if she DOES know somethin\', perhaps ye can relay that information back to us.$b$bIt would certainly go towards making the shop more lucrative.', `QuestDescription`) WHERE `ID` = 40193;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Reclaimed Cargo', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Mail Armor Shipments.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The same ship that my brother was on also carried shipments of exceptional mail armor. Knowing the giants, they probably had no use for them and left them scattered around their caves.$b$bIf you could recover those shipments and bring them here, I can explain the techniques used to fashion them. That should give you a good idea of how to improve your processes.', `QuestDescription`) WHERE `ID` = 40194;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Daring Rescue', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Taldranis in Oceanus Cove, and deliver the armor to him.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My brother, Taldranis, was on a ship headed here to Azsuna. The ship was ambushed by the sea giants and my brother was taken captive.$b$bI believe he still lives out his days in those horrible caves, slaving away for the giants. Go and free him, please.$b$bTake this with you, it may give him enough protection should you run into any trouble. And be careful not to get captured by the giants yourself.', `QuestDescription`) WHERE `ID` = 40195;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Adventuring Anxieties', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Mei Francis about her barding idea.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n! I was recently talking with Mei, the mount trader, and she asked me if it was possible to make a barding that could prevent adventurers from being dismounted.$b$bI\'d like you to go and discuss this idea with her further.$b$bReturn to me when you\'re finished. Perhaps we can solve this issue together.', `QuestDescription`) WHERE `ID` = 40196;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Necessary Materials', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Stonehide Leather.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to make this barding, we\'ll need a lot of leather. And I mean a LOT of leather.$b$bI\'ll solidify our plans on fitting the pieces together. You go gather the leather.$b$bOnce that\'s done, we can begin crafting.', `QuestDescription`) WHERE `ID` = 40197;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rats!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go into the Underbelly and recover $1oa Highmountain Leatherworking Patterns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I tell you, $n, I have the worst luck sometimes.$b$bA package recently arrived from Hrul containing leatherworking patterns, and while my back was turned, some filthy rats came in and ran off with them down into the sewers!$b$bProbably building nests with them as we speak. Please, $n, can you go down there and see if you can retrieve any of them?', `QuestDescription`) WHERE `ID` = 40198;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leather Legwork', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Get a crowbar for Thanid.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Good news, $n! Langrom\'s Leather and Links recently delivered a shipment of mail armor to me.$b$bIt\'s of the finest quality and I\'d love to show it to ye, but it seems I\'ve lost me crowbar and can\'t open the crate.$b$bIf ye could run over to their shop and grab an extra one fer me, we can get this crate opened and go over the construction.', `QuestDescription`) WHERE `ID` = 40199;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle Bonds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Lio the Lioness at the Magical Menagerie shop. Then return to Namha.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you like pets, $n? I love pets. They\'re so cute!$b$bBut what I really want is more things with which to play with them.$b$bI\'m sure Lio over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!', `QuestDescription`) WHERE `ID` = 40200;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Playthings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a prototype for the pet bed.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ok, so her ideas were a leash, a bed, and a FLAMING HOOP?!$b$bIt sounds like they want to start a circus or something. Regardless, I love all those ideas and we should get started as soon as you\'re ready.$b$bWhy don\'t you work on making the bed, and I\'ll work out the details for the flaming hoop.', `QuestDescription`) WHERE `ID` = 40201;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Final Lessons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Hrul Sharphoof in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Hrul has requested your presence. From his message it seems as though he\'s ready to impart to you all the wisdom he has gained from working with the skins of this land.$b$bI envy you, $n... but I\'m also proud to see that you\'ve gained so much respect with him.$b$bGo now, and good luck!', `QuestDescription`) WHERE `ID` = 40202;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Strength of the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return a scale of Deathwing to Hrul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you know, the durability of your armor is only as strong as the materials you use to make them.$b$bLong ago, the black dragon, Deathwing once inhabited this very mountain. In his quest for power, his body began to tear and he had creatures make metal scales to stitch his wounds.$b$bHis natural scales fell to the ground in his lair and have been there ever since. Go retrieve a scale and bring it to me.$b$bThis will take all your strength to accomplish.', `QuestDescription`) WHERE `ID` = 40203;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Evolution of the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Basilisk Hides.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we make stronger armor, the creatures we battle adapt and learn to defeat us. We in turn create better armor, and they in turn learn to defeat it yet again.$b$bFor centuries, my people have battled the basilisks of the mesas below. They have adapted to us as thoroughly as we have to them.$b$bGo, kill these basilisks and take from them their hides. Return them to me so I may show you how they have evolved.', `QuestDescription`) WHERE `ID` = 40204;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Respect for the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the four tanning racks around Highmountain and hear their stories.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We record the mistakes of the past so we can learn to avoid them in the present. However, recording history is not just about preventing missteps, but also to celebrate our successes.$b$bScattered around Highmountain at sacred locations are racks with stamped leather, much like the ones here, with stories to tell.$b$bGo to these locations, pay your respect, and learn their lessons.', `QuestDescription`) WHERE `ID` = 40205;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Debt Paid', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Celea in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now, I\'ve never heard of a ghost sending a letter before, but I\'ll be damned if\'n I didn\'t just receive one now.$b$bCelea has sent fer ye, $glad:lass;. I\'d best be on me way if I were ye. Might be bad luck to keep a spirit waiting.', `QuestDescription`) WHERE `ID` = 40206;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scales of the Arcane', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the blue dragonflight and acquire one of their scales.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In my experience, dragon scale has been the strongest material I\'ve ever had the privilege of working with. It\'s hard, durable and very little can go a long way.$b$bI wish to work with it again, $n. Being in this form, I\'m bound to this area, unable to experience the world any longer.$b$bI\'ve heard rumor of the blue dragonflight occupying parts of Azsuna. Perhaps you can speak with them and see if they can shed a scale or two.', `QuestDescription`) WHERE `ID` = 40207;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: Scales of the Sea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Eye of Azshara and obtain Warlord Parjesh\'s Hauberk.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When we first met, I spoke of the naga, and the armor they\'re able to craft. No grander armor is worn, however, than by their top warlords.$b$bOne in particular resides within the Eye of Azshara itself. His name is Warlord Parjesh, and the hauberk he wears is one of legend.$b$bRepel his forces, and obtain his armor. Do this, and I will teach you more of the Azsunian way of leatherworking.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'A fierce warrior who commands legions of naga.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Warlord Parjesh', `PortraitGiverName`) WHERE `ID` = 40208;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scales of the Earth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Axetail Basilisk Matriarch Scales.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While leather armor is strong on its own, integrating scales into the design is what truly sets it apart.$b$bThe type of scales you use will determine how many you\'ll need to fully protect the wearer. And one of the strongest type of scales are basilisk scales.$b$bA fully matured basilisk has the strongest of course. Near the village of Llothien is a basilisk den. Kill the matriarch and return her scales to me.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Beware her tail. It\'s as sharp as a dragon\'s fang.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Axetail Basilisk Matriarch', `PortraitGiverName`) WHERE `ID` = 40209;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Time Well Spent', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Tell Namha of your time with the night elves in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Unfortunately, $n, you have learned all that I have to teach. I am pleased we were each able to achieve our goals in this partnership.$b$bGo now and share what you\'ve learned with your allies in Dalaran. I\'m sure they\'d be eager to share in your training.', `QuestDescription`) WHERE `ID` = 40210;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demon Flesh', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search for a master leatherworker in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Something we haven\'t really explored yet, $n, are the creatures of Suramar. Specifically, the demons.$b$bNow I certainly don\'t praise what they are, but you can\'t ignore the fact that some of their creatures have especially tough hides.$b$bWe could take a lesson from the demon hunters and use those hides to our advantage against the demons. I\'ll be damned though if I know the first thing about working with demon hide.$b$bPerhaps there\'s someone in Suramar who can help...', `QuestDescription`) WHERE `ID` = 40211;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wrong End of the Knife', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill the traitor leatherworkers, Feorias, Tallian, and Syana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There he is! The man that isn\'t there! He\'s... he\'s...$b$bWait... no, I\'m sorry. My thoughts, they\'re just all over place lately. Ever since my exile, things have been a bit fuzzier than normal.$b$bIf you wish to learn from me before I completely lose my mind, then do me a favor, and kill those traitors who sided with the demons and exiled me.', `QuestDescription`) WHERE `ID` = 40212;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hounds Abound', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Fel Hound Corpses.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ll invite him to tea. That\'ll show him! He\'ll see the leather doll and say, "When did SHE get here?!"$b$bI mean... sorry, $n. My mind goes to strange places. You want to know about the demons, the ones with durable hides?$b$bBefore I was exiled I saw such beasts roaming our cities. Fel hounds, they are called. Slay them and bring me their corpses.$b$bWe can discuss their hides afterwards.', `QuestDescription`) WHERE `ID` = 40213;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel Tanning', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a pair of bracers for Stalriss using the tanning rack.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Listen, you. I\'m not sure when the crazy side of me will come out again, so let\'s make our time together short.$b$bYou want to learn how to make armor to rival the demons? Follow my instructions and you\'ll have an excellent grasp on the procedures.', `QuestDescription`) WHERE `ID` = 40214;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mounting Made Easy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Capture the Great Northern Elderhorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I\'m glad you\'re here. I confess: I\'ve been working on a secret project behind your back. Behold: the Stonehide Leather Harness! Now, we simply need to find a mount worthy of such a piece of art.$b$bThe vrykul sing songs of a snow-white elderhorn with endless stamina. Find it, place the harness on it, and tame it.', `QuestDescription`) WHERE `ID` = 40215;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Hunter at Heart', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Addie learn to hunt by killing wildlife in Pinerock Basin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Addie\'s one heck of a writer, but I\'ve never seen her hold a rifle. She\'s keen on learning how to hunt, but who\'s ever heard of a gnome hunter? nnYou seem to have a knack dealin\' with amateurs, so maybe you\'d be willin\' to let the gnome tag along on a hunt? She could learn a thing or two by shadowing someone with your skill.nnYa best start off with some small game. We don\'t want the lass to get discouraged.', `QuestDescription`) WHERE `ID` = 40216;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Offering of Ammo', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the Quiver of Arrows to Hemet Nesingwary at Nesingwary\'s Retreat.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The mountains have seen many new travelers pass through their valleys, some without an understanding of our traditions.nnOur leaders have turned their focus to more pressing matters, but Losro and I cannot ignore the recent arrival of hunters in the nearby basin.nnThey hunt with guns and gadgets, forgoing the experience of hunting with a bow and arrow.nnWhile I know that some will remain stuck in their ways, perhaps an offering of arrows will encourage these outsiders to hunt the way we always have.', `QuestDescription`) WHERE `ID` = 40217;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Debt Repaid', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Ritssyn Flamescowl.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have a few urgent matters to take care of, but soon after I will make my way to Dreadscar Rift and aid you with your summoning.nnYou should warn Ritssyn to keep his distance. I\'ll be there to repay my debt to you, not to speak to the hypocrite who chose the council over his friends.', `QuestDescription`) WHERE `ID` = 40218;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In Defiance of Deathwing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness 3 Visions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It was in this place, ages ago, that Huln Highmountain challenged the great Deathwing.$b$bToday we shall re-live moments of that day through the eyes of our ancestors.$b$bFor this next part of the spirit journey, we must seek out the three braziers set down many ages ago so that those who would follow in the footsteps of Huln might witness his deeds.', `QuestDescription`) WHERE `ID` = 40219;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thorny Dancing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat $1oa Thistleleaf Thorndancers in the Lunarwing Shallows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Thistleleaf sprites have gone completely mad.$b$bI suspect they are being manipulated by some very mischievous Thorndancers.$b$bPlease, friend of the forest, seek out these seductive troublemakers and bring peace to the shallows.', `QuestDescription`) WHERE `ID` = 40220;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spread Your Lunarwings and Fly', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Save 8 Trapped Lunarwings in the Lunarwing Shallows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These poor faerie dragons are being tortured!$B$BWhat\'s worse, when the thistleleaf become bored they ensnare their victims to continue their torment later.$b$bThis behavior is simply unacceptable.$B$BPlease free any trapped Lunarwings you can find.', `QuestDescription`) WHERE `ID` = 40221;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Imp Mother\'s Tome', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Tome of Fel Secrets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'See this giant cave? There\'s a terrifyingly powerful imp mother inside.nnBut that\'s not the good part. The good part is what she has.nnApparently, she\'s some kind of keeper of fel secrets. She\'s in there performing profane Legion rites and scribing them into a book.nnWe need that power! We need her tome!', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Steal her Tome of Fel Secrets so that you and your Illidari can become more powerful.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Prolifica', `PortraitGiverName`) WHERE `ID` = 40222;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 DH-Mardum - Small Treasure Chest 008', `LogTitle`) WHERE `ID` = 40223;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hammer in the Deep', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Therazane\'s Portal to travel to the Crumbling Depths. Accompany Stormcaller Mylra and Thrall to recover the Doomhammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Thrall listens intently.>$b$bYou found it! The Doomhammer fell to the Crumbling Depths... But the Legion remains a step ahead of us. If we hurry, we can follow the demon Geth\'xun and retrieve the hammer before any more of this realm is corrupted.$b$bTherazane will open a portal directly there. Let\'s go!', `QuestDescription`) WHERE `ID` = 40224;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Ring Reforged', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Nobundo and take your place as the head of the Earthen Ring.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Speak with Nobundo, and take your place around the circle, $n. The Earthen Ring will rise again, with you as its leader!$b$bWithin these stones stands the legendary Heart of Azeroth, which we can use as a base of operations. Perhaps the power of your artifact can unseal the hidden chambers...', `QuestDescription`) WHERE `ID` = 40225;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bad Intentions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Thaedris Feathersong in Tel\'anor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Suramar is lost.$b$bOur leaders struck a dark bargain, accepting the Legion as our allies. We were meant to be heroes, guardians - the people resting here. We are not like them any more. I cannot live with them.$b$bBut cut off from the Nightwell, we wither and devolve into a mindless existence. An existence without release or dignity, as you can see even here...$b$bI rejected both of these options and found myself here. I will find a third way.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Speak with Thaedris Feathersong.', `AreaDescription`) WHERE `ID` = 40227;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scout It Out', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Irewing after sending up a flare, signaling his location.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve proven that a gnome can shoot a rifle, and that\'s no easy feat, but a true test of Addie\'s skill will be to see if she can track down an elusive beast.nnRumor has it that a ravenous roc circles the basin, cursed by harpy magic, but no one\'s seen the beast up close.nnTake this flare, and shoot it into the sky once you\'ve spotted the roc. When we see the signal, the huntin\' party will rush in and help bring down that magnificent bird!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Irewing', `PortraitGiverName`) WHERE `ID` = 40228;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Step into the Dark', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Navarrogg at Stonedark Grotto.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the threat to my people quelled, I believe it is time to introduce you to my kin.nnMeet me at Stonedark Grotto, and you will see where we live.', `QuestDescription`) WHERE `ID` = 40229;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Oh, the Clawdacity!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mindmeld with Murky and defeat Clawdayshus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The leader of the Cavemoss makrura, Clawdayshus, has been ordering raids into the Cavemoss village to steal the young for snacks.nnThis isn\'t going to do at all. In order to prove their power, Murky and the tadpoles must destroy him as well!nnThis is a job for murlocs.nnMindmeld with Murky in his egg and show him how it\'s done!', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'The most audacious makrura by the sea.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Clawdayshus', `PortraitGiverName`) WHERE `ID` = 40230;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Brood Queen\'s Court: Count Nefarious', `LogTitle`) WHERE `ID` = 40231;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Brood Queen\'s Court: King Voras', `LogTitle`) WHERE `ID` = 40232;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Brood Queen\'s Court: Overseer Brutarg', `LogTitle`) WHERE `ID` = 40233;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Brood Queen\'s Court: General Volroth', `LogTitle`) WHERE `ID` = 40234;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Abrogator Arbitrator', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kluk\'kluk wants you to bring him $1oa Apexis Crystals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Da bums in Highmaul refuse to see dey are on da way out. Me, I\'m gettin\' while da gettin\' is good. Da sooner youse bring me a bunch of Apexis Crystals, da sooner I can get off dis stupid island. Da amount required is very precise!', `QuestDescription`) WHERE `ID` = 40235;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dawning Light', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Accompany Fearsome Jang and await the masters\' announcement.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It was a miracle that you were able to survive, $n. It is with great sorrow that I have to say that Grand Master Hight was not so lucky. His spirit now rests with the ancestors.$b$bNow we must look to a new leader for our order, our broken temple. I have spoken with the other masters and we are all of one mind on this.$b$bWe all agree that new leader should be you, $n. You have shown strength, wisdom, courage, and kindness beyond measure.$b$bWalk with us to the temple and we will announce our decision.', `QuestDescription`) WHERE `ID` = 40236;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Work Work Stoppage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring $1oa Apexis Crystals to the Renegade Ironworker.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve had enough! The working conditions in the Foundry are intolerable with all the fire and the ogron and the flames and the fire elementals and infernos and marauding adventurers! But especially the heat.$b$bI\'ve had enough! Me and the boys are going to start a work stoppage but we need to hire some security muscle and the only goon from Highmaul I could get to agree to the job only takes payment in Apexis Crystals.', `QuestDescription`) WHERE `ID` = 40237;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Grim Equation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the three Soul Coffers on the Shattered Fields.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'They were waiting for us when we crashed. It was all we could do to establish our small outpost.$b$bEven now they drain the souls of our fallen to fuel their attacks.$b$bDestroy their soul coffers. Free our comrades and let them join the Light.$b$bWhen you have finished, find Y\'mera in the field. She has been sorely missed, but she will not have fallen. Of this I am certain.', `QuestDescription`) WHERE `ID` = 40238;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Looted Blacksmith Defender\'s Cache', `LogTitle`) WHERE `ID` = 40240;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle Bonds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Serr\'ah at the Magical Menagerie shop. Then return to Namha.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you like pets, $n? I love pets. They\'re so cute!$b$bBut what I really want is more things with which to play with them.$b$bI\'m sure Serr\'ah over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!', `QuestDescription`) WHERE `ID` = 40241;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mellok, Son of Torok', `LogTitle`) WHERE `ID` = 40242;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Break Weapon Racks', `LogTitle`) WHERE `ID` = 40243;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'That Guy in the Costume', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Tamara and fly to Shipwreck Cove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Aye, when we were out huntin\' on the coast, we ran into this ridiculous lad in in a costume. He says he\'s tryin ta blend in with the murlocs... but I\'m pretty sure he\'s just not right in the head.nnOne of ours stayed behind to keep an eye on him when we headed back to camp... mind checkin\' it out?nnYe can ask Tamara over there for a ride.', `QuestDescription`) WHERE `ID` = 40244;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Looted Tailoring Defender\'s Cache', `LogTitle`) WHERE `ID` = 40245;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Looted Leatherworking Defender\'s Cache', `LogTitle`) WHERE `ID` = 40246;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Asking a Favor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ask Khadgar for a source to power the Legion communicator.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Caria Felsoul was one of our best... before she answered the Legion\'s foul call.$B$BShe now wields the Aldrachi Warblades - the soul-rending armaments of the ancient race\'s greatest champion, who fell only to Sargeras himself.$B$BWe sent a party to track Caria down, but we have not heard from them in some time. Jace has nearly repaired a Legion communicator so we can make contact - we need only a power source.$B$BCould you ask Khadgar for assistance? Our friends in this world are few.', `QuestDescription`) WHERE `ID` = 40247;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vengeance Will Be Ours', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Aldrachi Warblades from Caria Felsoul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We aren\'t going to get our forces anywhere near the Broken Shore without getting knocked out of the sky.$B$BI think it best if you handle this matter yourself - there are none among us more capable on the field of battle.$B$BSave Allari and her men if you can, but the Aldrachi Warblades will do far more for this war than warm bodies.', `QuestDescription`) WHERE `ID` = 40249;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Suramar - Demon Hunter Daily - Choice Reward Summary - 1', `LogTitle`) WHERE `ID` = 40250;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Kethrazor', `LogTitle`) WHERE `ID` = 40251;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stormheim - Adventure Mode - Leystone Slab Tracking Quest', `LogTitle`) WHERE `ID` = 40252;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stop Gul\'dan!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Vault of the Betrayer, kill Crusher and Sledge, and take their fel power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'After his defeat at the Black Temple, we brought Illidan\'s lifeless body here, to be interred forever within the Vault of the Wardens.nnGul\'dan has found his way through our defenses and is trying to steal the Betrayer\'s corpse.nnEven in death, Illidan\'s body can be used by the Burning Legion. Gul\'dan CANNOT succeed.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Stop him if you can.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Gul\'dan', `PortraitGiverName`) WHERE `ID` = 40253;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Forged in Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Immolanth and take his power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. nnSomehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long.nnThe demon\'s power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining.nnI believe that person could be you, $n.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Immolanth is full of pure, coalesced fel power.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Immolanth', `PortraitGiverName`) WHERE `ID` = 40254;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Between Us and Freedom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Bastillax and take his power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The last of our survivors have fought their way into the final chamber ahead.nnOnly one obstacle stands between us and the vault\'s exit - the leader of this demon invasion, Bastillax.nnKill him, take his power, and claim our freedom.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'He guards the vault exit.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Bastillax', `PortraitGiverName`) WHERE `ID` = 40255;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Between Us and Freedom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Bastillax and take his power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The last of our survivors have fought their way into the final chamber ahead.nnOnly one obstacle stands between us and the vault\'s exit - the leader of this demon invasion, Bastillax.nnKill him, take his power, and claim our freedom.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'He guards the vault exit.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Bastillax', `PortraitGiverName`) WHERE `ID` = 40256;
