UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demon Hunter Choice 3', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'PLACEHOLDER', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'PLACEHOLDER', `QuestDescription`) WHERE `ID` = 40261;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Touch of Magic', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Sprinkle Arkhana on dormant objects in Tigrid\'s house.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I always took great pride in my home... and my enchantments. Now it seems both have fallen into ruin.$b$bI can sense the power of a potent enchanter in you, $n. If you would but sprinkle a bit of magic dust on my once-enchanted belongings, I\'m sure you can bring them to life again.', `QuestDescription`) WHERE `ID` = 40265;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Lost Advisor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Cliffthorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You may as well assist me while you are here. I require a potion to be made, one that will set things right.$b$bI must conserve my energy until my task is finished, lest I become like these miserable wretches scrabbling at the cobblestones. There is coin in it for you, since I will not be needing it soon.$b$bThe harpies around here cannot resist cliffthorn. It is what drew them to Tel\'anor in the first place. $b$bYou should find plenty just outside this building.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect Cliffthorn.', `AreaDescription`) WHERE `ID` = 40266;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Unexpected Message', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Discover Archmage Modera\'s message by using the Glowing Resonate Crystal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ah, Felo\'melorn. I am familiar with this weapon. nnFor ages the Council of Tirisfal attempted to recover the blade. Its control over the primal forces of fire would be devastating in the wrong hands. nnAs luck would have it, an associate of mine, Archmage Modera has recently uncovered some information on this artifact. This crystal contains a message from her.nnI suggest you start your search there. The portal over there will bring you back to the city.', `QuestDescription`) WHERE `ID` = 40267;
