UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Path of Atonement', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archmage Modera\'s associate at the Dalaran Crater within Hillsbrad Foothills', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Felo\'melorn, the runeblade of the kings of Quel\'Thalas. It was said to harness the very essence of flame and after being reforged by Kael\'thas could even stand against the legendary Frostmourne.$b$bWe thought that the blade was lost with Kael\'thas\'s death but an associate of mine has a lead on where it may be located.$b$bWe need every advantage we can get and with Felo\'melorn in your hand the Legion surely will tremble!$b$bAh, our company is here.', `QuestDescription`) WHERE `ID` = 40270;
