UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Maelstrom Beckons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate the Ancient Elemental Altar and imbue your artifact with a new power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Can you feel it, shaman? Here, in the heart of Azeroth, where earth and wind and waves clash together - it is as if one can speak directly with the world.$b$bThe artifact you wield houses great power but even greater potential. Carry it below and seek out the ancient elemental altar overlooking the fury of the maelstrom. From there, you can commune with Azeroth and imbue your artifact with even greater abilities. Do so, and then share with me what you have learned!', `QuestDescription`) WHERE `ID` = 40276;
