UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lyana Darksorrow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Soul Harvester.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<A captive demon hunter floats in stasis in front of you; her soul slowly draining into the harvester crystal.>nn<In order to release her from stasis, you will need to destroy the soul harvester.>', `QuestDescription`) WHERE `ID` = 40297;
