UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tools of the Trade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve burial objects for Thaedris.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I used to visit here before the barrier was raised. While the ruling council and the Grand Magistrix argued and politicked I watched the caretakers  perform their rituals and venerate the dead.$b$bI would honor the spirits here one last time. I am headed to the tombs. If some of the sacred oils, burial shrouds, or incense survived the ages then bring them to me.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Retrieve burial objects for Thaedris.', `AreaDescription`) WHERE `ID` = 40300;
