UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Last Chapter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Encyclopedia Botanica.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The next step of my journey requires a tome, but I find that I am still unable to idly sit by as this place continues to fall into disrepair.$b$bI will tidy up the memorials while you go fetch me the tome. It is called the Encyclopedia Botanica and you can find it in the library near the main plaza.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Find the Encyclopedia Botanica.', `AreaDescription`) WHERE `ID` = 40306;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Glaive Circumstances', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve Lyana Darksorrow\'s glaives.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I came here on a mission to slay the demon eredar, Azoran. During my infiltration, I was shot down from my felbat and captured.$b$bI\'m not going to mince words, $n. Azoran plans to use the Burning Legion command ship to destroy Dalaran.$b$bTo stop him, I will need my warglaives that were lost during my fall from the sky. I would retrieve them myself, but I\'m still weakened from my imprisonment.$b$bSearch for the warglaives on the northern side of the crater, where I was shot down.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Retrieve Lyana Darksorrow\'s glaives.', `AreaDescription`) WHERE `ID` = 40307;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fragments of Memory', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve 15 Tel\'anor Mementos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The beautiful elven burial urn is shattered carelessly on the ground. It was clearly handled roughly, but not scratched by the talons of the harpies.>$b$b<You find a trail of shards leading towards a cave. Those responsible are certainly within. Thaedris would be interested in the relics and their safe return.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Retrieve 15 Tel\'anor Mementos.', `AreaDescription`) WHERE `ID` = 40308;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shipwrecked Captive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Shipwrecked Captive in a pet battle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I spent my life playing the pet in other peoples battles. Now it\'s my time to be the pet tamer! Best part of being dead is I can do this forever!', `QuestDescription`) WHERE `ID` = 40310;
