UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'End of the Line', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Thaedris at the upper landing of Tel\'anor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I cannot call Suramar my home any more, and I refuse to become a withered abomination. There is no place for me anymore, don\'t you understand?$b$bWe only need one last ingredient to complete the elixir. You will help me, won\'t you?', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Speak with Thaedris Feathersong.', `AreaDescription`) WHERE `ID` = 40315;
