UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Final Ingredient', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Latara\'s bow.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The potion is complete, $n. Soon our journey will be over. There is one last thing I would have you do for me, then you shall have your reward.$b$bMy wife\'s bow was kept here, but I have not been able to find it after searching everywhere. There is potent magic in it.$b$bI fear one of the restless spirits may have taken it, but it would take a powerful force to pick up an item such as this. Be careful.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Retrieve Latara\'s bow.', `AreaDescription`) WHERE `ID` = 40319;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Band of Blood Brothers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Katarine, Fjolrik, and Stokalfr in Muddledeep Cavern.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You are the one that Toryl was bellowing about? Perhaps you can help me.$B$BWhen I set out to search for Throndyr, I was not alone. Three vrykul loyal to Throndyr also accompanied me. As you can plainly see, I now stand alone.$B$BFind my kin, $n.$B$BI cannot bear to think that they also share Throndyr\'s fate.', `QuestDescription`) WHERE `ID` = 40320;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Feathersong\'s Redemption', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay the Cliffclutch Matriarch.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I must confess I was not entirely honest with you, $n. I meant to drink the potion and join my wife.$b$bAnd even she was taken from her rest... I cannot fail her again. I must live and do what I can to stop this coming storm to be worthy of joining her.$b$bCome, young one. Let us take care of the harpy matriarch and restore Tel\'anor to its former glory. We cannot let this poison go to waste, eh?', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Slay the Cliffclutch Matriarch.', `AreaDescription`) WHERE `ID` = 40321;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloodhunt Highland Treasure', `LogTitle`) WHERE `ID` = 40322;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cave of the Blood Trial Treasure', `LogTitle`) WHERE `ID` = 40323;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arcane Communion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Feed Theryn 300 Ancient Mana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All of Kel\'danath\'s experiments to connect with the withered failed, and some even made them more dangerous.nnUntil he found Theryn.nnHis arcane essence - the very soul of the shal\'dorei - had been touched by something special. But what? nnBy weaving my arcane essence together with Theryn\'s, I can create an empathic bond. This communion will bare his soul to us all - or what\'s left of it. nnWe need only to feed him mana, and lots of it, in order to begin.', `QuestDescription`) WHERE `ID` = 40324;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scenes from a Memory', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Thalyssra complete the arcane communion with Theryn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Theryn is at the mercy of his own mind. Whatever we find in there, it may be difficult to control.nnI will need your help to sort through the visions, so be ready for anything.nnWith any luck, we will discover what makes Theryn special. And... whether there is anything left of who he used to be.', `QuestDescription`) WHERE `ID` = 40325;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scattered Memories', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Inspect $1oa pages of Kel\'danath\'s Notes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<As your fingers trace the elegant symbols on the page, a voice dictates the words in your mind.nnIt seems the nightborne have elevated even simple note-taking to a sorcerous art.nnArcanist Kel\'danath was definitely working in this area. There must be more of his notes scattered around.>', `QuestDescription`) WHERE `ID` = 40326;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Testing the Metal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort Taldranis to safety.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alright, if we\'re going to get out of here, we\'re going to have to maneuver around the naga and the sea giants.$b$bThe naga probably won\'t pose much trouble for someone of your skill, but those sea giants are strong beyond belief.$b$bJust get me out of this cave safely and I can find my own way home.$b$bHopefully this armor Celea made for me will protect me long enough to see this through.', `QuestDescription`) WHERE `ID` = 40327;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Fate Worse Than Dying', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Open $1oa Soul Engine Cages.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When the Burning Legion takes a prisoner, it is not an act of mercy.$b$bWhile death is the destruction of the mortal body... if you are captured by the Legion, they will seek to destroy your soul.$b$bThe Burning Legion uses sacrificial souls to power their demonic machinations of war. The soul engine is where the harvested souls are collected and stored.$b$bThough countless have already perished in the soul engine, you may yet save those still alive inside.$b$bHurry and release them before it is too late!', `QuestDescription`) WHERE `ID` = 40328;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle Pet Tamers: Warlords', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 5 pet battle trainers in Draenor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have proven yourself before but the wilds of Draenor are on another level. Defeat tamers in the wilds to prove your pet battle supremacy: Cymre Brightblade in Gorgrond, Vesharr in Spires of Arak, Tarr the Terrible in Nagrand, Taralune in Talador, Gargra in Frostfire Ridge, or Ashlei in Shadowmoon Valley. You can also defeat a visiting tamer: Erris the Collector or Kura Thunderhoof in your garrison.$B$BBy defeating them will show your dominance in Draenor.', `QuestDescription`) WHERE `ID` = 40329;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bite of the Sashj\'tar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Sashj\'tar Fangs from Sashj\'tar naga in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If I had been by Throndyr\'s side when he fought the naga, he might still be alive.$B$BThese serpents will regret the day that they decided to slither from their watery hole!$B$BKilling them is not enough. No! I will honor Throndyr with a necklace of naga fangs!', `QuestDescription`) WHERE `ID` = 40331;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Beach Bonfire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 6 Driftwood in Azuregale Bay and build a funeral pyre for Jarl Throndyr.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do not let... my body lie in... the mud.$B$BSet my flesh... aflame.', `QuestDescription`) WHERE `ID` = 40332;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spiritwind Summit Treasure', `LogTitle`) WHERE `ID` = 40333;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fisherman\'s Tonic', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Axetail Eyes from Axetail Basilisks, a Sashj\'tar Air Bladder from Sashj\'tar Naga, and a Sample of Siren Blood from Siren Naz\'jul in Azuregale Cove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you detest these serpents as much as we do, I ask that you continue the fight against them.$B$BThat will mean fighting them in their watery domain. I don\'t see any gills on you, so we\'re going to have to concoct an old tonic used by vrykul fishermen.$B$BThe ingredients are plentiful around here, taken that you do not mind picking through entrails.', `QuestDescription`) WHERE `ID` = 40334;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sashj\'tar Accord DISABLED', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Show the stone tablet to Toryl.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<This stone tablet appears to be a contract between Tidemistress Sashj\'tar and King Forgalash.$B$BAs far as you can decipher, the naga are recruiting the sea giants on behalf of Queen Azshara.>', `QuestDescription`) WHERE `ID` = 40335;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Turning the Tidemistress', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Construct a Makeshift Ballista and kill Tidemistress Sashj\'tar in the Sashj\'tar Ruins.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tidemistress has fallen back to the elven ruins and is licking her wounds.$B$BHer guard is undoubtedly protecting her. To best her, you will have to break her defenses.$B$BConstruct a ballista using the parts that you salvaged and end her once and for all.', `QuestDescription`) WHERE `ID` = 40336;
