UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Candle of Command', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Sit upon the Throne of Ordering Around and give orders to kobolds that approach.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You no come in yet! Give orders to other kobold on Throne of Ordering Around if you want in, then maybe we talk.', `QuestDescription`) WHERE `ID` = 40339;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Alard Schmied Greeting Seen', `LogTitle`) WHERE `ID` = 40340;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Throne of the Tides: Azshara\'s Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Throne of Tides and acquire Sharas\'dal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Wavespeaker Adelee tracked Sharas\'dal to the Throne of Tides within the Abyssal Maw, then disappeared. $n, if we go after her, we are almost certainly walking into a trap.$b$bBut the elements are with us, my friend. The naga will not expect a shaman of your caliber!$b$bSwim to the Throne of Tides to the Northwest, within the Abyssal Depths. I will join you once you are inside. Let\'s find our missing shaman and get that artifact!', `QuestDescription`) WHERE `ID` = 40341;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Surprise the Sashj\'tar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 12 Sashj\'tar Champions or Sashj\'tar Deep Witches in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The naga are preoccupied with recruiting the sea giants for Queen Azshara\'s battles in other lands.$B$BNow is the time to strike!', `QuestDescription`) WHERE `ID` = 40342;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Magni/Eitrigg Meetup Seen', `LogTitle`) WHERE `ID` = 40343;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Burn the Candle at Both Ends', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ensure that all of the kobold jobs are done.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Why you come back already? Have to wait until jobs are done or I no let you through!nnGo back to Throne of Ordering Around and make sure they finish!', `QuestDescription`) WHERE `ID` = 40345;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pilfered Provisions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Pilfered Provisions from shipwrecks in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The sea giants are sifting through the shipwrecks looking for treasure. Anything of value that can be found would be better off in the hands of the vrykul.', `QuestDescription`) WHERE `ID` = 40346;
