UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bubble Trouble', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a piece of Needle Coral and then rescue 5 Captured Vrykul in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$C! The sea giants have already eaten half of my kin.$B$BWe are helpless in these accursed bubbles. I beseech you to get us out of here.$B$BTake heed. These bubbles are strong. You will need something that is extremely sharp to pierce them.', `QuestDescription`) WHERE `ID` = 40364;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Turtle Powered', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 7 Shimmering Snapper Scales.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to locate and purify the source of the corruption I am going to need an elemental focus.$b$bThe turtles around here have developed scales that can focus and amplify their innate magics. Bring back some snapper scales and we will have these waters purified in no time!', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect 7 Shimmering Snapper Scales.', `AreaDescription`) WHERE `ID` = 40368;
