UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Purge the Unclean', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the corruption in the Azurefall Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you feel it in the air, $r? The stage is set for us to make things right.$b$bWhile you were busy I was able to track down the elder elemental that rules these waters. Its name is the Azurefall Guardian and it resides within the channels below Tel\'anor.$b$bTake the ritual focus, it should help you during the battle.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Defeat the corruption in the Azurefall Guardian.', `AreaDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Use the Cleansing Ritual Focus to find the source of the corruption!', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Azurefall Guardian', `PortraitGiverName`) WHERE `ID` = 40370;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A New Direction', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose between Kayn and Altruis.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, as leader of the Illidari in Lord Illidan\'s absence, you must choose your second-in-command.nnKayn or Altruis. You can only choose one.nnThe chosen shall become your personal champion, and their ideology will color our decisions for the Illidari going forward. No matter who is chosen, our mission remains unchanged.nnIf you need a reminder of our past, gaze into the Pool of Judgment. Remember the sacrifices that forged us into demon hunters. Speak to me when you are ready to choose.', `QuestDescription`) WHERE `ID` = 40373;
