UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Enter the Illidari: Ashtongue', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Summon in your Ashtongue forces by activating the Legion Gateway.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lord Illidan has placed you in charge. Now, we just need the rest of our Illidari attack force.nnThere are three Burning Legion gateways ahead. Activate them and our Illidari will pour through from the Black Temple.nnLike most Legion constructs, the gateways are powered by souls. I think we have provided enough to activate this first one, don\'t you? Let us bring in our Ashtongue forces.', `QuestDescription`) WHERE `ID` = 40378;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Enter the Illidari: Coilskar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Feed a soul into the Legion Gateway Activator and then use it to summon in your Coilskar forces.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The next gateway\'s down on the Molten Shore. Our Coilskar forces are waiting at the Black Temple on the other side.nnPersonally, I wouldn\'t have chosen to bring our naga allies. But, their leader did swear fealty to Lord Illidan. I suppose we\'ll see.nnWe\'ll have to find a way to power the gateway\'s activator. Like this last gateway, it runs on souls.nn<Allari the Souleater grins as Sevis says this.>', `QuestDescription`) WHERE `ID` = 40379;
