UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Needs of the Hunters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Emmarel Shadewarden in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The eagle appears to have a message for you:n$B|cFF660000             To: $n|r$b$bThe time has come to strike back at the Legion.$b$bMeet me at Hunter\'s Reach in Dalaran as soon as you can.$B$B|cFF660000             |r-Emmarel Shadewarden', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Emmarel Shadewarden in Dalaran.', `QuestCompletionLog`) WHERE `ID` = 40384;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Spear in the Shadow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Hunt down Highmountain\'s Bane.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Many years ago, a corrupted nightsaber hunted my people. Our chieftain, Dorro Highmountain, took Talonclaw and pursued the beast, but never returned.$b$bI have heard tales of a fearsome nightsaber that now stalks the mists of Stormheim. My brother and I believe this to be our ancient foe.$b$bThe weapon must be there too! If we kill the beast and reclaim the spear, it will be of great use against the Legion.', `QuestDescription`) WHERE `ID` = 40385;
