UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Huln\'s War - Shadowsong', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Jarod Shadowsong in the battlefield.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Someone with whom I believe you are familiar commands in the battlefield below.nnJarod Shadowsong speaks highly of you, and has requested that you join him in battle.nnHe has plans to put an end to this fight.', `QuestDescription`) WHERE `ID` = 40388;
