UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Take Me To Your Leader', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Khadgar in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I am glad you are here, $n.$b$bThis... Khadgar, the archmage who found my message, has called a meeting.$b$bHe wishes to meet us at the entrance to the city as soon as possible.$b$bWill you accompany me? I have the strangest feeling that he will not be alone.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Meet with Khadgar in Suramar.', `AreaDescription`) WHERE `ID` = 40391;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Marksman', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the hippogryph from Krasus\' Landing down to the Broken Shore and meet with Vereesa Windrunner.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Time is of the essence! If Alleria and Thas\'dorah are in Legion hands, it is only a matter of time until both are forfeit.$b$bIf you are ready, head to the Broken Shore to meet with Ranger-General Windrunner.$b$bShe has lent her personal hippogryph to fly you down to the surface.', `QuestDescription`) WHERE `ID` = 40392;
