UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clandestine Operation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Vereesa Windrunner.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have long been a trusted hero of the Alliance, $n. And like the rest of us, you have endured many hardships to reach this point.$b$bNow, I must ask even more of you. Will you hear me out?', `QuestDescription`) WHERE `ID` = 40400;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Way Back In', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the smuggler.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I must get back into Suramar.$b$bI was exiled unfairly! I cannot live out here like this. I need the Nightwell\'s energies...$b$bI saw a message carved into a wall a few days ago. There is someone in the Water Gardens who can smuggle people into the city.$b$bIt said "We shall drink of the Well again."$b$bI cannot survive a confrontation with the guards again. Will you go in my stead? Once I am back in the city I can repay you.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Find the smuggler.', `AreaDescription`) WHERE `ID` = 40401;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clandestine Operation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Listen to Vereesa Windrunner\'s tale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you well know, I have opposed the Horde at many turns. The orcs have taken... so much from me. From my family.$b$bYet I have witnessed your deeds firsthand, $n. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point.$b$bNow, I must ask your help. Will you hear me out?', `QuestDescription`) WHERE `ID` = 40402;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clandestine Operation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Listen to Vereesa Windrunner.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is no small matter for me to seek the aid of a blood elf. Your leaders have turned their backs on the sacrifices made by my family and so many others.$b$bYet I have witnessed your deeds firsthand, $n. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point.$b$bNow, I must ask your help. Will you hear me out?', `QuestDescription`) WHERE `ID` = 40403;
