UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Weapons of Legend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select an artifact weapon to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our gathering has identified several weapons of immense power. In the right hands, these holy artifacts give us a fighting chance against the Legion.$B$BWe cannot pursue all of them at once. We risk too much if we spread ourselves that thin. We must agree on where our efforts are best focused.$B$BThat is why I asked you here, $n. As one of our greatest champions, you must be our voice of reason and decide our next move.', `QuestDescription`) WHERE `ID` = 40408;
