UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azoran Must Die', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Azoran in Felsoul Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You won\'t have much time before the Legion is aware of your presence on the ship.$b$bWhen the alarm is raised, countless Burning Legion forces will attempt to board the ship through this portal.$b$bI will not let them succeed.$b$bI will guard this portal from enemy reinforcements until you return. It is up to you to slay Azoran and lay waste to his ship.$b$bWe don\'t have much time... you must attack swiftly and without mercy.', `QuestDescription`) WHERE `ID` = 40412;
