UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Well Spent Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Tell Namha of your time with the tauren in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your respect for our ways has earned you all the knowledge we have to teach. Go now, $n, and spread our ways to those who fight against the legion.$b$bPerhaps it will help to turn the tide in this war for our world.', `QuestDescription`) WHERE `ID` = 40415;
