UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Tanaan!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Warchief Vol\'jin inside the Town Hall of your garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Congratulations on your recent advancement to level 100!$b$bIt is vital that you set your focus on Tanaan Jungle and establish a foothold there, before you are distracted with other matters.$b$bThe Warchief is ready for you inside your Town Hall. It would be wise not to keep him waiting....', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Warchief Vol\'jin inside the Town Hall of your garrison.', `QuestCompletionLog`) WHERE `ID` = 40417;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Tanaan!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with King Varian Wrynn inside the Town Hall of your garrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Congratulations on your recent advancement to level 100!$b$bIt is vital that you set your focus on Tanaan Jungle and establish a foothold there, before you are distracted with other matters.$b$bThe King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with King Varian Wrynn inside the Town Hall of your garrison.', `QuestCompletionLog`) WHERE `ID` = 40418;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rescue Mission', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel through the portal and rescue Alleria Windrunner.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demon has told us how to open a portal to the world where he says Alleria is being held. You and I can go through and see if there is any truth to his claims.$b$bIn case it\'s a trap, Magus Solgaze has given me a portal stone to get us back to Dalaran.$b$bThis demonic magic is anathema to the mage, so we must move quickly. I\'m ready when you are, $n.', `QuestDescription`) WHERE `ID` = 40419;
