UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Desperate Journey', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow the lamp posts to take Iadreth to Astoril.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The city\'s entrances are under heavy guard. He must have another way.$b$bThanks to this wine I am strong enough to make the journey to him. I fear that I will not be able to defend or run if I come under attack.$b$bYou will accompany me, $r. You and this Astoril are my only chance at surviving now. $b$bI remember when I was leaving the city that there were lamps guiding me here. We should be able to retrace our steps by following them.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Take Iadreth to Astoril.', `AreaDescription`) WHERE `ID` = 40424;
