UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Final Preparations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover 6 stashed supplies.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We will need supplies for our trip into Suramar. We cannot exactly stop for refreshments at the gate with you two in tow, can we?$b$bThe water gardens were a place to socialize and relax. Before the patrols arrived it was rather trivial to hide some mana wine for later retrieval.$b$bThat\'s where you come in. Fetch some supplies and bring them to your friend, then meet me at the ruins north of the city. We will be ready to depart soon.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Recover 6 stashed supplies.', `AreaDescription`) WHERE `ID` = 40469;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Quality of Life', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Iadreth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I am afraid, $n. We\'re so close to home, so close to salvation...$b$bAstoril says he knows the rest of the way through and can get us there safely. I believe him, but you\'ve come this far to see us safe. Will you see this through to the end?', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Follow Iadreth.', `AreaDescription`) WHERE `ID` = 40470;
