UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSEME_40501', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infiltrate Bladefury\'s Command with Garona\'s help. Use her talents to eliminate guards without being seen. Locate Iron Horde intelligence and then spy on Gul\'dan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If Garona\'s intelligence is correct, Gul\'dan will be inside this Iron Horde compound. With Garona\'s help, slip inside, gather any info you find, and learn what Gul\'dan intends to do.$b$bThe guards are on high alert. Garona can "liquidate" individual guards for you, but she must not be seen! You will have to choose your targets carefully and pick your way through the bastion undetected. Don\'t let anyone sound the alarm.$b$bIf things get too hot, I\'ll teleport you to safety. At least... I\'ll try.', `QuestDescription`) WHERE `ID` = 40501;
