UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Walk With the Spirits', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Spiritwalker Ebonhorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The spiritwalker you saved from Riverbend has been insufferable since his arrival. He is insisting on showing you the ways of our people so that you better understand what is to come.$b$bHe is a strange one, even by spiritwalker standards.$b$bEven so, only a fool would discard his insight. Please, go to speak with him when you get a moment.', `QuestDescription`) WHERE `ID` = 40515;
