UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fallen Lion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver King Varian\'s letter to King Anduin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I haven\'t left the deck of this ship since we got back. The fleet must be made ready for war. Don\'t know where we will be needed, but when the call comes, we\'ll be ready.$b$bTruth be told... I welcome the distraction. The others are paying their respects to Varian, but I... I cannot bring myself to face that casket. To face his son.$b$bVarian gave me a letter he wrote to Anduin. Please, take it to him on my behalf.', `QuestDescription`) WHERE `ID` = 40517;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Battle for Broken Shore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take Captain Russo\'s ship to the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your warship awaits at the end of the dock, $n. May your weapon bring you many kills today.nnThe Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.', `QuestDescription`) WHERE `ID` = 40518;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Legion Returns', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Check in with Recruiter Lee at Stormwind Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Heroes of the Alliance, I write to you in Azeroth\'s darkest hour. From the maw of hell, the burning armies of the Legion have returned.nnOur fleets depart for the Broken Isles at once. As a grand lance, we will pierce the Legion\'s lines and drive them back to the nether that spawned them.nnYour ship awaits in the Stormwind Harbor, make haste.', `QuestDescription`) WHERE `ID` = 40519;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To See the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Bottle of Airspark, Mu\'sha\'s Tears, and Darkshard Crystal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I would like for you to experience firsthand what Huln Highmountain was able to accomplish in a single battle during the War of the Ancients.nnTo do so, I will need very specific ingredients. They are not too difficult to obtain--you can find all of them near Thunder Totem.', `QuestDescription`) WHERE `ID` = 40520;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest - W1 - Demon Attack Complete', `LogTitle`) WHERE `ID` = 40521;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fate of the Horde', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Grommash Hold and learn the fate of the Horde.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is a wonder any of our troops survived that bloodbath on the Broken Shore. If not for Lady Sylvanas...$B$BHigh Overlord Saurfang has been asking for you at Grommash Hold. He will not say why... but he was insistent that I send you to him.', `QuestDescription`) WHERE `ID` = 40522;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Facet-nating Friends', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Introduce yourself to Timothy Jones and Sminx Glasseye.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Excuse me, $gsir:madam;. Are you sure you\'re in the correct shop? We only deal in the finest of jewels here.$b$bAhh, I see... you\'re a fellow lapidary. Then perhaps we can work together.$b$bIntroduce yourself to my associates, so they\'re aware of who you are and what you may have to offer.', `QuestDescription`) WHERE `ID` = 40523;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Familiar Ring to It', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Shrine of Aldiir near the Crumbling Palace in Azsuna and read about its legend.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n! Let\'s talk bling. I\'m looking for a ring.$b$bSee, the elves down in Azsuna were some fine master jewelcrafters back in the day... or so they say. The books all talk about a ring called the "Band of Farondis". Can\'t hurt to ask around for it.$b$bLet\'s head to Azsuna. Bet I\'ll get there sooner!', `QuestDescription`) WHERE `ID` = 40524;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Getting the Band Back Together', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the three pieces of the Band of Farondis and bring them back to Timothy Jones.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I like our dynamic, $n. You\'re the muscle with all the hustle! And I\'m the brains who entertains!$b$bI think this next task is all on you. Try to find that ring, or whatever the murlocs left of it.', `QuestDescription`) WHERE `ID` = 40525;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Finishing Touches', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Timothy\'s Gem Vise to obtain a Cut Skystone.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well, I\'ve managed to repair the ring, but the gem still needs work.$b$bSay... you\'re a gemcutter, $n. You\'ve got the tools, so cut those jewels!', `QuestDescription`) WHERE `ID` = 40526;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Finishing Touches', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Timothy\'s Gem Vise to obtain a Cut Deep Amber.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well, I\'ve managed to repair the ring, but the gem still needs work.$b$bSay... you\'re a gemcutter, $n. You\'ve got the tools, so cut those jewels!', `QuestDescription`) WHERE `ID` = 40527;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Finishing Touches', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Timothy\'s Gem Vise to obtain a Cut Azsunite.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well, I\'ve managed to repair the ring, but the gem still needs work.$b$bSay... you\'re a gemcutter, $n. You\'ve got the tools, so cut those jewels!', `QuestDescription`) WHERE `ID` = 40528;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Truly Outrageous', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Gem Chips for Tiffany Cartier. Gem chips can be acquired through Prospecting raw ore or purchased off the auction house.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ore prospecting is our primary method of gem acquisition. And while prospecting... you\'re bound to find small, unusable gem chips.$b$bMany gem shops simply discard the small gem chips they find, but we here at Cartier & Co. let nothing go to waste.', `QuestDescription`) WHERE `ID` = 40529;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Eye for Detail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Visit the patrons of the jewelcrafting shop in Dalaran and report back to Tiffany.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, if there\'s one thing I despise, it\'s slander. A rumor is spreading that one of my recent commissions is a fake.$b$bWe need to quell these rumors as quickly as possible.$b$bI need you to visit the customers I recently worked for and examine their gems. If your claim of being a jewelcrafter is true, then you will be able to spot a fake gem from a mile away.$b$bHere\'s the list of my patrons. Return immediately if you find any truth to these rumors.', `QuestDescription`) WHERE `ID` = 40530;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Swift Vengeance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Harold Winston in Dalaran\'s Underbelly.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I swear, when I find him...$b$b<Tiffany catches your eye and regains her composure.>$b$b$n, I need you to track down my FORMER associate, Harold Winston. I doubt he\'s gotten far, given our location.$b$bWhen you find him, I would like you to recover the stolen property and return it to me.$b$bUse any means necessary. And don\'t worry about Ms. Moore\'s jewels, I\'ll redeliver a fresh supply to her personally.', `QuestDescription`) WHERE `ID` = 40531;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Making the Cut', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a Deadly Deep Amber using the Tiffany\'s cutting tool.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Seeing as how you\'ve been quite a reliable resource, I\'m willing to teach you how to cut a Deadly Deep Amber.$b$bWe\'ll be using my cutting tool to do this, so whenever you\'re ready, go ahead and sit yourself in front of it.', `QuestDescription`) WHERE `ID` = 40532;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Making the Cut', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a Quick Azsunite using the Tiffany\'s cutting tool.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Seeing as how you\'ve been quite a reliable resource, I\'m willing to teach you how to cut a Quick Azsunite.$b$bWe\'ll be using my cutting tool to do this, so whenever you\'re ready, go ahead and sit yourself in front of it.', `QuestDescription`) WHERE `ID` = 40533;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Making the Cut', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a Masterful Queen\'s Opal using the Tiffany\'s cutting tool.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Seeing as how you\'ve been quite a reliable resource, I\'m willing to teach you how to cut a Masterful Queen\'s Opal.$b$bWe\'ll be using my cutting tool to do this, so whenever you\'re ready, go ahead and sit yourself in front of it.', `QuestDescription`) WHERE `ID` = 40534;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Raising the Drogbar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Lasune Starblade in Val\'sharah as to the whereabouts of the jewelcrafting master.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Word travels fast around Dalaran, $n. And the latest word is that there\'s a master jewelcrafter somewhere in Val\'sharah.$b$bI want you to go down there and find this master.  Perhaps they have designs that can help bolster business here at the shop.$b$bI\'ve heard the name "Lasune Starblade" tied to these rumors. She might be a good place to start looking.', `QuestDescription`) WHERE `ID` = 40535;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bruls Before Jewels', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Protect Jabrul while he finds harpy necklaces and escort him back to the nearby night elf camp.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So, you wish to learn what Jabrul knows about jewels?$b$bWell, Jabrul needs your help. Before we leave this place, Jabrul still needs harpy necklaces.$b$bKeep those harpies off of Jabrul while he takes their necklaces and Jabrul will reward you with his knowledge.', `QuestDescription`) WHERE `ID` = 40536;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lapidary Lessons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a Well-Cut Maelstrom Sapphire using Tiffany\'s cutting tool.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s good to see you again, $n.$b$bIt seems we\'ve both been busy since last we spoke. I have something that you may be interested in.$b$bA recent shipment of rare jewels called maelstrom sapphires have finally arrived here at the shop.$b$bI came up with a beautiful design for them and would like to show you how to cut them into something useful.', `QuestDescription`) WHERE `ID` = 40538;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden Intentions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a set of Diamond Lockpicks for Clive Cozen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Word on the street is, yer a reliable resource for getting things done, let\'s say, discreetly.$b$bSo here\'s the job. I need a new set of lock picking tools. But not just any old lock picks will do.$b$bI need something special, something that won\'t break if ye apply too much pressure.$b$bI\'m thinking a set of diamond lock picks might do the trick. That would be lock picks made out of diamond, not the ones shaped like a diamond.$b$bLook, ye in or what?', `QuestDescription`) WHERE `ID` = 40539;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Come at Me, Brul', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Jabrul in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I received a... well, what can only be constituted as a "letter", carved into a piece of flat rock.$b$bThat jewelcrafting master you found in Val\'sharah has sent for you. He said he\'s in Stormheim currently.$b$bWhen you see him, would you be so kind as to inform him that we don\'t wish to receive any more of his requests for your presence. They just make a mess.', `QuestDescription`) WHERE `ID` = 40540;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Charge Within', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Conducting Jewel on the corpses of $1oa Squallhunter storm drakes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Before Jabrul shares his designs with you, he needs you to help him with a special project.$b$bJabrul has a jewel that can trap storm energy. The more lightning it traps, the brighter it shines.$b$bJabrul thinks the storm drakes\' power would be better spent in his jewel than terrorizing the skies of Stormheim.$b$bDon\'t you?', `QuestDescription`) WHERE `ID` = 40541;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eyes of Nashal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Eyes of Nashal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deadly eye of prophecy... a good choice. Before we can cut, though, we need gems.$b$bHere stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need.$b$bAscend the statue, take its jeweled eyes, and return them to Jabrul.', `QuestDescription`) WHERE `ID` = 40542;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eyes of Nashal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Eyes of Nashal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Quick dawnlight... a good choice. Before we can cut, though, we need gems.$b$bHere stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need.$b$bAscend the statue, take its jeweled eyes, and return them to Jabrul.', `QuestDescription`) WHERE `ID` = 40543;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eyes of Nashal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Eyes of Nashal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Masterful shadowruby... a good choice. Before we can cut, though, we need gems.$b$bHere stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need.$b$bAscend the statue, take its jeweled eyes, and return them to Jabrul.', `QuestDescription`) WHERE `ID` = 40544;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aww Scrap!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Crate of Guns down to Filgo Scrapbottom in the Underbelly.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s a catastrophe! No, even worse, a conspiracy!$b$bI heard the Legion was back again, and I thought to myself, "Hobart, now\'s your time to shine."$b$bI made us enough guns to blow those demons back to the beginning of time!$b$bBut then we get here, and what happens? Everyone just happens to "find" all these ancient artifacts to fight the demons with!$b$bLong story short, I have too many guns and need to get rid of \'em.', `QuestDescription`) WHERE `ID` = 40545;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mysteries of Nature', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover a piece of Dragon Glass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Jabrul wants to show you his special crystals. Nobody knows what they do. Very mysterious.$b$bIf you want to learn how to make one, Jabrul would be happy to show you.$b$bHigh in the mountains live storm drakes. They blast the cliffs with their lightning breath and sometimes blast so hard, they turn the rock to crystal.$b$bGet a piece of that crystal and bring it back to Jabrul.', `QuestDescription`) WHERE `ID` = 40546;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Dalaran, With Love', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Crate up Jabrul and mail him to the Cartier & Co Fine Jewelry shop.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Jabrul was thinking that he\'d like to come up to Dalaran and discuss jewel designs with the masters.$b$bBut Jabrul doesn\'t know how to get up to it. Jabrul did have an interesting idea that might work.$b$bIf you mailed Jabrul to Dalaran, then surely he\'d arrive safe and sound.', `QuestDescription`) WHERE `ID` = 40547;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Jabrul Needs You', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Jabrul in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hello $n,$b$bJabrul needs your help with something. Could you please come to Azsuna and find Jabrul?$b$bThank you,$b$bJabrul', `QuestDescription`) WHERE `ID` = 40556;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG: Clive Cozen Leave', `LogTitle`) WHERE `ID` = 40557;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Socket to Me', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain all 6 components from around the world. Refer to Tiffany\'s notebook for reference on where to acquire each piece.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You admire the contraption sitting on the counter. There\'s a button on it, but pressing it seems to warrant no response.$b$bTiffany tells you that it\'s an old toy box, but the crystal components are all broken.$b$bIf you were to find new ones, she could repair it and teach you how to make one for yourself.', `QuestDescription`) WHERE `ID` = 40558;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Hold: The Raven\'s Wisdom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Black Rook Hold and locate a book on jewelcrafting and bring it to Timothy Jones in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I\'ve been hearing a lot of talk about Black Rook Hold from our friend here, about a room which contains volumes of texts on just about every type of craft there is.$b$bI\'m willing to bet there\'s a book in there on jewelcrafting that could come in handy for us.$b$bGo there and bring me back anything you find. I\'ll share a sweet new design I came up with you when you return.', `QuestDescription`) WHERE `ID` = 40559;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maw of Souls: Spiriting Away', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Maw of Souls and bring back the Ring of the Fallen to Timothy Jones in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What I\'m about to ask you to do is no easy task, $n.$b$bI need you to die. But, you\'ll be able to come back of course! $b$bThere\'s a ship, the Naglfar, that ferries souls from this world to the next. It\'s said that an ancient treasure called the Ring of the Fallen rests in the bowels of that ship.$b$bYou know me, $n, and nothing catches my interest more than a sweet looking ring.$b$bFind a way onto that boat and bring me back that ancient treasure.', `QuestDescription`) WHERE `ID` = 40560;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: Jewel of the Heavens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Odyn in the Halls of Valor and bring back his ring to Timothy Jones in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Queens and kings wear the best rings! And I\'ve heard that a certain king of gods has made his presence available.$b$bIn the Halls of Valor, the ruler Odyn has treasures unlike anyone in existence. If you happen to go there, try and... obtain, let\'s say, one of his rings for me.$b$bI doubt he\'ll just hand it over, so you may have the fight of a lifetime in store.', `QuestDescription`) WHERE `ID` = 40561;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Personal Touch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Nightborne Loupe, a Custom Jewelry Order, and $2oa Nightborne Jewelry Cases.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, great to see you again. It feels like forever since last we spoke.$b$bWe\'ve received some information about a group of jewelcrafting nightborne in Suramar that are doing fantastic things with necklaces. I\'d like to take a look at some of their gems.$b$bAnd their designs.$b$bAnd... a new loupe might be nice, too. I hear the city inspectors carry them.', `QuestDescription`) WHERE `ID` = 40562;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shoe Shine Kit Tracking Quest', `LogTitle`) WHERE `ID` = 40564;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSEME', `LogTitle`) WHERE `ID` = 40565;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkheart Thicket: Enter the Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter Darkheart Thicket and Slay the Shade of Xavius.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We could not save Ysera, but we did prevent her from destroying the temple.nnNow I can finally turn my attention to my husband.nnI do not know what fate he suffers now. I only know that if we stand any chance of saving him, you must go now.nnFollow Xavius into the Nightmare and find Malfurion.nnPlease, save my husband if you can.', `QuestDescription`) WHERE `ID` = 40567;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fury of the Storm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 10 Felskorn vrykul in Thorim\'s Peak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Felskorn who ravage my brood were once Drekirjar - a tribe with whom we shared an ancient pact. Now, under the influence of the God-King, they forsake their oaths and strike at the forebears of their coveted drakes.nnThey should answer for this slight.nnAwaken your fury, $c, and take the battle to them!', `QuestDescription`) WHERE `ID` = 40568;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Legend of the Sands', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Li Li Stormstout.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Nothing! There is next to nothing in our records about this weapon!$b$bI\'ve checked and re-checked, and can find barely a shred of a tale. This can only mean that the story comes from a land outside Pandaria.$b$bLi Li Stormstout is young, but she is the most traveled on the entire isle except for you. If anyone might know of this weapon, it is she.', `QuestDescription`) WHERE `ID` = 40569;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into The Heavens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Fists of the Heavens.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This stone is saturated with elemental power, possibly the remnant of the magic used against Irmaat!$b$bIf you went outside and held the stone aloft, it should unleash the stone\'s essence as a mighty whirlwind. So potent a windstorm could carry you and your companion all the way to Skywall!$b$bIf the hand blades of Irmaat, the Fists of the Heavens, are as powerful as the old tales say, they would certainly be found there.', `QuestDescription`) WHERE `ID` = 40570;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkheart Thicket Heroic Reward Quest', `LogTitle`) WHERE `ID` = 40571;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkheart Thicket Normal Reward Quest', `LogTitle`) WHERE `ID` = 40572;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nightmare Lord', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Inform Thaon Moonclaw of the return of Xavius.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You arrived just in time, friend.$b$bKagraxxis was moments away from sacrificing me to his master... I was certain I would perish.$b$bI am grateful, but we are not out of danger yet... Xavius has returned.$b$bThe Nightmare Lord is here in Val\'sharah, personally orchestrating the corruption of this land. My captor revealed as much to me before I was to be sacrificed.$b$bWe must find Thaon Moonclaw and inform him before it is too late!', `QuestDescription`) WHERE `ID` = 40573;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Golganneth Shrine Cleansed', `LogTitle`) WHERE `ID` = 40574;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Paying Respects', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 8 Disturbed Apparitions or Disturbed Spectres.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All I see is despair.$b$bLook, $r. The grounds are overwhelmed with these wraiths, spirits of those interred here. Something has made them angry and they are lashing out. I can feel their pain.$b$bI will go look for remaining relics, and there is a tomb I must see. It is too late for these unfortunate souls. Please defeat any you find and return them to the rest they deserve.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Slay Disturbed Apparitions or Disturbed Spectres.', `AreaDescription`) WHERE `ID` = 40578;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Weapons of Legend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select an artifact weapon to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As the greatest warrior in these halls, you require a great weapon to do both your will and mine. I have looked down on Azeroth and found artifacts worthy of your hands.$b$bI leave it to you to choose which artifact you wish to seek out and wield against the Legion.  We will recover the others in time.', `QuestDescription`) WHERE `ID` = 40579;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Protection Chosen', `LogTitle`) WHERE `ID` = 40580;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fury Chosen', `LogTitle`) WHERE `ID` = 40581;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arms Chosen', `LogTitle`) WHERE `ID` = 40582;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Witnessed Drake Lift Crystal', `LogTitle`) WHERE `ID` = 40584;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thus Begins the War', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your order\'s first assault point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion thinks you are dead. It will be quite the surprise when you punish them for that assumption!$b$bThis allows us to see all across the Broken Isles and assign warriors to various tasks.$b$bOnce you\'ve taken a look, you should choose your first area of operation. I\'ve already picked out the best spots!', `QuestDescription`) WHERE `ID` = 40585;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Following the Curse', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden\'s Camp in Deadwind Pass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Very well. I suppose an introduction is in order. I am Revil Kost, priest of the Light and a seeker of lost artifacts. I\'ve dealt with the Dark Riders before, and have returned to rid this place of them.nnThe Riders are elusive, but I may have a clue to their whereabouts. In our previous confrontation, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they were before.nnCome with me to Ariden\'s camp. I will explain on the way.', `QuestDescription`) WHERE `ID` = 40588;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Second Valarjar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Welcome your new valarjar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Whatever your feelings towards him, he is still one of the finests warriors on Azeroth. He has led battles from the front, advised Warchiefs, and mixes excellent martial prowess with tactical calm. You can trust his judgment as well as his axe. Speak with him yourself.', `QuestDescription`) WHERE `ID` = 40591;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demons Among Us', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Protect Stormwind Keep from the Legion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The king is wise to focus on the Legion\'s threat, $n. Even now, the demons move against us.$b$bThe Illidari will aid the cause of the Alliance. We believe they have set their sights on key locations around Azeroth. In fact, they could already be in your midst!$b$bI sense they are close...', `QuestDescription`) WHERE `ID` = 40593;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Justice Rains from Above', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bomb the forces of the Understone Breach', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Kill now, grieve later!$b$bHere, champion, take flight with one of my war eagles. Use the powers bestowed upon you by our united tribes and help us rain destruction down on these drogbar.$b$bLet us clog that new doorway to their lair with the bodies of their own!', `QuestDescription`) WHERE `ID` = 40594;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Dalaran - Timothy Jones - (UNUSED)', `LogTitle`) WHERE `ID` = 40595;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Azsuna - Timothy Jones - (UNUSED)', `LogTitle`) WHERE `ID` = 40596;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thunder Totem Treasure', `LogTitle`) WHERE `ID` = 40597;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Highmountain - Vignette - Pinerock Basin - Highmountain Beastmaster See Treasure (JLW)', `LogTitle`) WHERE `ID` = 40601;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seeking the Valkyra', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Ashildir at the Vault of Eyir in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We simply cannot risk another catastrophe like that; we have to protect the Heart against fel energy before we continue our work.$B$BThe mighty Ashildir has proven willing to aid those who she deems worthy, and her master just may be able to help us protect the Heart.$B$BYou should seek her out at the Vault of Eyir in Stormheim. I\'ll meet you there.', `QuestDescription`) WHERE `ID` = 40603;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Disturbing the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search around Ariden\'s Camp for clues leading to the Dark Riders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner.nnHelp me search the camp. Let\'s see if we can find something to lead us to the Dark Riders.', `QuestDescription`) WHERE `ID` = 40604;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keep Your Friends Close', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Elthyn Da\'rai at the Illidari camp atop the plateau in Orgrimmar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion is bold indeed to strike at the Horde\'s stronghold! You aided our defense, but now I have a more important task for you.$b$bIt seems the demon hunters will play a crucial part in this war... but I still don\'t trust them. You will be my envoy to the Illidari. Learn what they know. Study their techniques. If they betray us, we\'ll use their own knowledge against them.$b$bTheir camp lies atop the plateau in the city. Go. Nathanos and I will clean up this mess.', `QuestDescription`) WHERE `ID` = 40605;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Point the Way', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the compass mentioned in the journal in Ariden\'s Camp.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Though the journal devolves into dark ramblings written in hurried scribbles, one entry stands out:nn"Ulthalesh. The name rings in my head. I can hear it calling, but where?nn"The spirits... the very land here is tied to it. It is no wonder we would so often get lost in this place. The forces pull my compass point in every direction...nn"Perhaps if it had a stronger pull, the compass could show the way..."', `QuestDescription`) WHERE `ID` = 40606;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demons Among Us', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Learn what Allari the Souleater sees.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Look around. What do you see?$B$B<Allari glares at something over your shoulder.>$B$BThe Legion has already infiltrated the Horde... even now, they are among you.$B$BWe must protect your Warchief.$B$BWhen you are ready to see what lies beneath the veil, say the word.', `QuestDescription`) WHERE `ID` = 40607;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Mark', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Prove your worth to the Valarjar, then receive the Mark of the Valkyra from Eyir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your blade is powerful, but it has not yet met its full potential. The all-powerful Odyn in the Halls of Valor can bestow upon you his strength.$B$BIn order to seek this blessing, you must bring him a worthy tribute. I know where you may obtain such a gift, but in order to retrieve it you must first receive the mark of the Valkyra.$B$BProve yourself worthy of our mark, champion, then you may enter the Vault of Eyir- the goddess will guide you from there.', `QuestDescription`) WHERE `ID` = 40608;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Highmountain - Vignette - Windripper Peak - Taurson - Tracking Quest Credit - See Treasure (JLW/RKS)', `LogTitle`) WHERE `ID` = 40609;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Highmountain - Vignette - Worm Treasure - Tracking Quest Credit - See Treasure (JLW/RKS)', `LogTitle`) WHERE `ID` = 40610;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fate of Deadwind', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Attune Ariden\'s Compass at the sites of restless spirits around Deadwind Pass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The journal mentions a "stronger pull" for the compass. If the spirits of this place are indeed tied to it, they may serve as the pull we need.nnI\'ve come upon several locations in the pass where restless spirits tend to appear. Perhaps if you show the spirits there the compass, they may be able to help point it in the right direction.nnYou seek these locations out. I\'ll continue on to Karazhan and see if I can find anything leading to the Dark Riders.', `QuestDescription`) WHERE `ID` = 40611;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Highmountain - Vignette - Amateur Hunters - Tracking Quest Credit - See Treasure (JAP)', `LogTitle`) WHERE `ID` = 40612;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maw of Souls: Retrieving the Svalnguard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Svalnguard and defeat Helya in the Maw of Souls on Mythic difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Svalnguard was once Odyn\'s shield; it is said that it hid the Halls of Valor from the endless darkness below his realm.$B$BHelya, who was cast from the shining halls long ago, stole the Svalnguard and keeps it on her accursed ship, the Naglfar.$B$BYou must board the Naglfar, defeat Helya, and retrieve the Svalnguard - it will make a worthy tribute for Odyn.', `QuestDescription`) WHERE `ID` = 40613;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Feast Fit for Odyn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire flank meat from Thunderhoof in Stormheim, Spinesever\'s spine in Highmountain, and a steak from Leytusk in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is customary in the Halls of Valor to feast after battle is finished. Presenting a truly glorious feast to Odyn from beasts worthy of his throne will show him your determination to earn his blessing.$B$BAcquire flank meat from Thunderhoof in Stormheim, Spinesever\'s spine in Highmountain, and the finest cut of steak from Leytusk in Azsuna. They will make a feast worthy of the great battle to come.', `QuestDescription`) WHERE `ID` = 40614;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: Odyn\'s Blessing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain Odyn\'s blessing in the Halls of Valor on Mythic difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You are ready, $c.$B$BTravel to Odyn\'s shining halls and offer the feast on the altar just inside. Mighty Odyn will then set his gaze upon you - you must pass the ancient trials of the Valarjar under his watch.$B$BOnly then will you receive Odyn\'s blessing.', `QuestDescription`) WHERE `ID` = 40615;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest - W1 - Saw Leader Die', `LogTitle`) WHERE `ID` = 40616;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Turn Around, Nighteyes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Lilryia Dawnwind find Nighteyes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Stranger, you must help me!$b$bNighteyes, my old friend... he was scouting ahead and I heard him cry out a warning. I tried to run after him, but in my carelessness I stepped in this trap.$b$bHe\'s so close, just on the other side of this ridge. Please find him!', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Help Lilryia Dawnwind find Nighteyes.', `AreaDescription`) WHERE `ID` = 40617;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Weapons of Legend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your first artifact weapon to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Three weapons... three worthy paths.$b$bAcquiring one such artifact will be the first step in battling the Legion. The weapon will grow in power as you wield it, so you must choose the one which will be the focus of your efforts, $n.$b$bAfter a time, you will be able to pursue the other weapons. But you must decide which to seek first.', `QuestDescription`) WHERE `ID` = 40618;
