UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aman\'thul Shrine Cleansed', `LogTitle`) WHERE `ID` = 40622;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dark Riders', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Dark Riders in the Karazhan Catacombs and claim Ulthalesh.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There\'s a sewer grate along the edge of the river leading to catacombs underneath Karazhan. I\'ve never paid it much attention, but it could be where the spirits are directing us.nnTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.', `QuestDescription`) WHERE `ID` = 40623;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Different Source', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find a Fel Deconstructor for Kyrtos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I need you to fetch me something.$b$bI think I might be on the verge of a breakthrough of a new source of magic, but I require tools. $b$bI can no longer access my workshop, but I have seen the smaller demons below using tools. Bring me one of their tools and I can save our people.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Find a Fel Deconstructor for Kyrtos.', `AreaDescription`) WHERE `ID` = 40625;
