UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shattered Ashbringer', `LogTitle`) WHERE `ID` = 40630;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Take Me To Your Leader', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Khadgar in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I am glad you are here, $n.$b$bThis... Khadgar, the archmage who found my message, has called a meeting.$b$bHe wishes to meet us by the entrance to the city as soon as possible.$b$bWill you accompany me? I have the strangest feeling that he will not be alone.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Meet with Khadgar in Suramar.', `AreaDescription`) WHERE `ID` = 40632;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Off To Adventure!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Li Li in Ramkahen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh I\'d love to go see if that story is true! But Pops is too busy stuffing his gut and being a grouch to let me go do any real exploring. He even told me that I can\'t leave the village unless I have a guardian!$b$bIs Pops for real? I can protect myself just fine!$b$bSay, would you be my guardian? Please, get me away from this boredom and you will totally be my hero!', `QuestDescription`) WHERE `ID` = 40633;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thunder on the Sands', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Nader and search his body for clues.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know the tale of Irmaat well. It is said that his home was the ancient city of Ahmtul, long buried under the desert sands.$b$bRecently a strange storm has appeared over the ruins. What\'s more, I am told that an elemental called Nader has attacked my people in nearby lands.$b$bThese events must be related.$b$bFind this Nader and put an end to him. Make sure to search his body for clues as to what is behind this.', `QuestDescription`) WHERE `ID` = 40634;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sashj\'tar Slayer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 12 Sashj\'tar naga in Azuregale Cove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I cannot believe that Throndyr is gone.$B$BBy the horns on my head, we shall have revenge for all of the pain that the Sashj\'tar have inflicted on us!$B$BPress forward, $n. Kill them! Kill them all!', `QuestDescription`) WHERE `ID` = 40635;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prepare To Strike', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select an artifact weapon to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Burning Legion took us by surprise at the Peak of Serenity. We will not allow them to do so again!$B$BWe have trained hard, but we need weapons capable of destroying this great evil if we are to have any chance of success.$b$bOur scrolls speak of several weapons that should prove suitable, but we are unable to decide which one to pursue first.$b$bThe choice, Grand Master, is yours.', `QuestDescription`) WHERE `ID` = 40636;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Proof of Honor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Toryl in Jandvik.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Brandolf breathes heavily.>$B$BThis cave will be my final resting place, $n.$B$BFind Toryl. Tell her of what happened here today.$B$BTell all of Jandvik that I died defending our village...', `QuestDescription`) WHERE `ID` = 40637;
