UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Power! Get The Power!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Fel Essence for Kyrtos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I need more power. I need more!$b$bI can control the energies, and they are enough to sustain me. For now.$b$bI will not end up withered, like those weaklings.$b$bGo out into Felsoul Hold and slay the demons. Bring me their essence and make it quick!', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect 8 Fel Essence for Kyrtos.', `AreaDescription`) WHERE `ID` = 40642;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Summons From Moonglade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Hamuul Runetotem at the Moonglade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Your presence is requested at Moonglade at once.$b$bWe are preparing for a ritual of great importance and will require your assistance.$b$bI will meet you there, so please come with haste.', `QuestDescription`) WHERE `ID` = 40643;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dreamway', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist with the ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The preparations for the ritual are now complete.$b$bCome with me, $n, I will guide you to the ceremony.', `QuestDescription`) WHERE `ID` = 40644;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To The Dreamgrove', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go through the portal to the Dreamgrove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The portal to the Dreamway is open and it is here where our paths must part. The Moonglade remains vulnerable to the attacks of the Burning Legion and I must ensure it is well defended.$b$bI\'m entrusting you with the mission to Val\'sharah, $n. Archdruid Greathoof is the leader of the druids there. He is wise in the old ways and will provide us invaluable assistance.$b$bThe Dream can be dangerous so I will send Keeper Remulos to guide you. Meet with him upon the other side.', `QuestDescription`) WHERE `ID` = 40645;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Weapons of Legend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select an artifact weapon to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I agree with Keeper Remulos. To confront and defeat the Legion, we will need weapons of legendary power.$B$BAmong the history of our kind, there have been four weapons of renown.$B$BTell me, which weapon would you pursue first?', `QuestDescription`) WHERE `ID` = 40646;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'When Dreams Become Nightmares', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Emerald Dream and obtain the Claws of Ursoc.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have Ursol\'s blessing, we can safely pass the magical wards and reach the claws\' resting place!$b$bNow, we must pass into the Dream. Lay down before the Shrine of Ursol and drink of the moonwater you brought earlier and your spirit will drift off into the dream.$b$bBe careful, the Dream can be a dangerous place.', `QuestDescription`) WHERE `ID` = 40647;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Meet with Mylune', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Mylune.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It would seem we are fortuitous that you seek G\'Hanir this day, $n - the dryad Mylune arrived not long ago from the sacred shrine where the staff has been guarded for many centuries.$B$BFew are privy to its hidden location within the roots of Shaladrassil, but you have certainly earned that right.$B$BSpeak to Mylune when you are ready to depart - I saw her last just east of here up the hill.', `QuestDescription`) WHERE `ID` = 40649;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Zen\'tabra', `LogTitle`) WHERE `ID` = 40650;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Seed of Ages', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Imbue your weapon with power by assigning an artifact point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These weapons were crafted with ancient magic. The true power of your artifact lies in its ability to grow in strength. The more you use it, the stronger it will become.$B$BNow that you have attuned your weapon to the Seed of Ages you can use its magic to unlock additional attributes in your weapon.$B$BUse it now, and unlock your weapon\'s potential.', `QuestDescription`) WHERE `ID` = 40651;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Word on the Winds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Skylord Omnuron.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time that we turn our attention to matters in the Broken Isles.$B$BSkylord Omnuron has gathered information on events from all over the Isles. If we are presented with any opportunity to strike against the Legion he will know of it.$b$bGo and see if he has anything available.', `QuestDescription`) WHERE `ID` = 40652;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Making Trails', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your order\'s first operational area.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Burning Legion threatens the life of Azeroth, but the nightmare threatens its very soul. We must remove both threats if our world is to survive.$b$bThis map will allow us to track the developments all across the Broken Isles and respond to threats as they arise. Our forces are limited for now, so we should focus our efforts where they will be the most effective.$b$bOnce you\'ve taken a look, you should choose where we shall begin.', `QuestDescription`) WHERE `ID` = 40653;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Druids of the Claw', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Yaris Darkclaw.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A new ally has joined our ranks. His name is Yaris Darkclaw, a skilled trainer among the Druids of the Claw.$B$BGo speak to him now.', `QuestDescription`) WHERE `ID` = 40654;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Li Li', `LogTitle`) WHERE `ID` = 40655;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Road to Fel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather 10 Fel-Infused Plates for Kyrtos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'An early step to understanding how magic works is to understand and study materials made using that magic. That was how I made my breakthrough on warlock soul crystals, after all. $b$bThe wyrmtongue minions in this pit hammer plates into their structures for support and maintenance. Those will be a good starting point. Fetch me some, my faithful assistant!', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect 10 Fel-Infused Plates.', `AreaDescription`) WHERE `ID` = 40657;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest - W1 - See Demon Attack', `LogTitle`) WHERE `ID` = 40658;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seeing Stars', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Sea Stars from Elder Trenchwalkers in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You think those naga are good sport, little rabbit?$B$B<Stokalfr chuckles.>$B$BI would savor the chance to do battle with one of those barnacle-crusted behemoths.$B$BIf you want to impress me, bring me the stars from their heads. I might consider you a true $c then.', `QuestDescription`) WHERE `ID` = 40659;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Protect the Home Front', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Open your map to find an active Legion invasion in Kalimdor or Eastern Kingdoms. Go to the invasion site and stop the demons!', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion hasn\'t just invaded this city. Their evil is spreading across Azeroth, threatening the far corners of our world.$b$bWe must seek them out and stop them, everywhere their darkness touches.$b$bWe\'ve dispatched scouts around the world to watch for Legion activity. As invasions arise, we\'ll mark the locations on your map.$b$bMake them suffer, $n!', `QuestDescription`) WHERE `ID` = 40661;
