UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Discovery Requires Experimentation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Felfire Spines from Felfire Basilisks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can sense residues of magic all over you. You will be useful.$b$bI must study how the demon bodies can handle the fel energies in such large quantities. I have plenty of flesh to sample, but there must be something...$b$bGo retrieve some spines from the nearby basilisks so that I may analyze their magical residues. No sense in both of us getting our hands dirty, is there?', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect 8 Felfire Spines.', `AreaDescription`) WHERE `ID` = 40683;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Tome of Blighted Implements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Calydus to choose which artifact you will pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The book you carry is the key to your friends\' salvation, and to your absolute power! It holds within information about many relics too dangerous to the Legion to leave unchecked.nnRead, friend. And decide which of these artifacts you will use to strike Jagganoth down!', `QuestDescription`) WHERE `ID` = 40684;
