UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One Small Step for Magic', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Kyrtos and assist him with his ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time to embrace the future.$b$bI have mastered every magic known to our kind. I will master this one.$b$bBy applying the principles of arcane magic it is fairly trivial to control the primitive fel energies within the material you have given me. I need to move to live prey next.$b$bLet us start with a small summoning. Defeat the creature for me and watch how a true scholar works!', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Assist Kyrtos with his ritual.', `AreaDescription`) WHERE `ID` = 40694;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Purity of Form', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Forge of the Roaring Mountain to imbue your artifact with a new power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Master, we have discovered a new technique that allows one with great focus to shape Chi within magical objects. This technique should allow you to considerably improve the abilities of your new weapon.$b$bThis technique requires a great deal of focus so we are limited to only a single upgrade for now, but that will have to do.', `QuestDescription`) WHERE `ID` = 40698;
