UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Priestly Matters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Attend the secret meeting at Faol\'s Rest in Tirisfal Glades.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$GMaster:Mistress; $n, I come at the behest of one who seeks to organize a stronger resistance to the Legion threat.$b$bIf you would meet him at Faol\'s Rest in Tirisfal Glades, he will guarantee both your safety and an opportunity to play a pivotal role in the conflict.', `QuestDescription`) WHERE `ID` = 40705;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Legend You Can Hold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select an artifact weapon to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To face the trials ahead, you require a weapon that can enhance your considerable abilities. I have learned of a few possibilities that you might consider.$b$bYou must decide which weapon to pursue first. I have the utmost confidence in your decision.', `QuestDescription`) WHERE `ID` = 40706;
