UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blade in Twilight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Stop the ritual and acquire Xal\'atath, Blade of the Black Empire.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have been working with Moira Thaurissan to infiltrate the Twilight\'s Hammer cult. We\'ve learned of an ancient and powerful Old God relic, a blade used at various points in history to wreak havoc.$b$bMoira\'s double agent informs us a new leader is rising, and plans to cement his ascension using this weapon in an unholy ritual. You must find him, stop the ritual, and seize the artifact.$b$bWe will meet in Dalaran afterwards.', `QuestDescription`) WHERE `ID` = 40710;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azsuna - Treasure 019 - [Ley Line Tower]', `LogTitle`) WHERE `ID` = 40711;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power Possessed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Calydus in The Underbelly in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was wrong about you, warlock. Your assistance against the Dark Riders has proven a great service to the Light. Perhaps I should not be so quick to judge.nnNevertheless, you have allowed me to fill my purpose in returning these artifacts to their rightful owners. As for Ulthalesh, I can think of no safer place than in your care. nnMay it serve you well against the Legion, warlock.', `QuestDescription`) WHERE `ID` = 40712;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Black Tome', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Black Tome.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have made a great discovery, $n.$b$bThere is a powerful warlock in the Soul Engine, in possession of a powerful tome. It contains forbidden secrets to summoning the most powerful of demons.$b$bEven the Legion is afraid to call on these fel lords, but now I possess knowledge beyond theirs.$b$bFetch me the tome and I will never want for magic again.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Obtain the Black Tome.', `AreaDescription`) WHERE `ID` = 40713;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Call To War', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Duke Lankral at Krasus\' Landing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<A chilling thought brushes your mind.>$b$bHear me, $n.$b$bThe Legion has returned. They hope to control us, to bend us to their will. Fools - they only walk back within reach of our blades.$b$bYour brethren within Dalaran have begun to gather at Krasus\' Landing. Go, meet with Duke Lankral and all will be explained.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'The Lich King', `PortraitGiverName`) WHERE `ID` = 40714;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Pact of Necessity', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select an artifact weapon to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have an unexpected ally in this war, $n, and we\'re going to need every advantage we can get to defeat the Burning Legion.$b$bThe Ebon Blade will serve as the Lich King\'s arm as long as the Scourge is confined to Northrend. In return for our assistance, our ally has offered to assist in obtaining powerful weapons for the strongest of our knights. Weapons powerful enough to end the Legion once and for all!$b$bYou are one of our best, $n. I want you to decide which weapon you would like to seek out.', `QuestDescription`) WHERE `ID` = 40715;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Sixth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Ritssyn Flamescowl in the Circle of Wills beneath Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, warlock. I speak on behalf of the Council of the Black Harvest.$b$bWith the Legion invasion upon us, it is painfully clear that our only hope is to grow stronger. The council plans to tap into the Twisting Nether and call forth more powerful demon allies. The ritual is ready, but we are short one number.$b$bNo doubt you have heard of the fate that befell Kanrethad Ebonlocke.$b$bYou will be his replacement. Do you accept?', `QuestDescription`) WHERE `ID` = 40716;
