UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arganax', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and slay Arganax in Lorlathil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A satyr known as Arganax has infiltrated the village of Lorlathil in Val\'sharah. I believe that Arganax has disguised himself as one of the local residents.$b$bUse the demon Eye of Azzorok on the villagers in Lorlathil. If there is a demon disguised as a local, the Eye of Azzorok will reveal their true identity.$b$bUncover the demon infiltrator Arganax, and slay him without mercy.', `QuestDescription`) WHERE `ID` = 40725;
