UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'All Along the Waterways', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 3 Duskwatch Orbitists.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve noticed some wandering eyes, lately.nnI am more than happy to continue delivering the goods to Vanthir, but it is getting increasingly dangerous to do so. nnThe Duskwatch that walk the bazaar are by far the most observant.nnFind and slay the Orbitists so that I may deliver the goods safely.nnI will follow behind with the shipment.', `QuestDescription`) WHERE `ID` = 40727;
