UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The New Blood', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the summoning ritual with the Council of the Black Harvest in the Circle of Wills in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time to begin the ritual, warlock. Be prepared, for the summoning we perform today will be more challenging than any you have known or seen before.$b$bAre you ready?', `QuestDescription`) WHERE `ID` = 40729;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Redistribution', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire 20 Bottles of Arcwine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I would imagine you thought I would simply have wine to deliver.nn<Deline chuckles.>nnIf it were that easy, his people would not be starving.nn<Her expression becomes serious.>nnThese... loyalists, shall we say, enjoy abundance. They dance to the Magistrix\'s whims and so they have all that they need.nnThere is no Arcwine shortage. The Magistrix created one to keep us in line.nnThey will not miss a few bottles. They have plenty.nnSearch the square and bring as much as you can carry back.', `QuestDescription`) WHERE `ID` = 40730;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Heart of the Dreadscar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Jagganoth and take his heart to the Seat of the Overlord in Dreadscar Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Friend has the artifact! Now Jagganoth does not stand a chance!$b$bQuickly, you must go back to Dreadscar Rift! You may still be able to save your friends from Jagganoth\'s vengeance.$b$bIf you take the heart of the overlord, his army will be yours to command!', `QuestDescription`) WHERE `ID` = 40731;
