UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dead and the Damned', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Dalaran and fly upon Zeomus to Darkstone Isle. While there, travel through the Demon Portal, find Baron Sliver, and obtain the Maw of the Damned.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<A powerful mind again touches your thoughts.>$b$bGorelix the Fleshripper is a monstrous demon. The butcher of a thousand worlds, he has exterminated countless races with his axe, the Maw of the Damned.$b$bA group of Ebon Blade was dispatched to slay him but they have gone missing. You will succeed where they failed.$b$bYou will not be alone in this, I\'ve sent Baron Sliver ahead to assist you.$b$bGo, obtain the Maw of the Damned and ensure that Gorelix is no more.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'The Lich King', `PortraitGiverName`) WHERE `ID` = 40740;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 DH-Mardum - Small Treasure Chest 011', `LogTitle`) WHERE `ID` = 40743;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Ancient Recipe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 6 Harpy Talons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Suramar is... was... an intellectual\'s dream.$b$bWe studied everything in there, from alchemy and the arts to the very nature of magic itself. How could we be so foolish as to accept them in?$b$bLook at me, lost in the clouds again when there is much to be done. My work requires some fairly difficult ingredients, $r. Perhaps you would help me procure them?$b$bI am going to need some harpy talons. Crushed into a powder, they will be a potent reagent.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect 6 Harpy Talons', `AreaDescription`) WHERE `ID` = 40744;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shift Change', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Hide in the basket and wait for the guard to appear. Follow the guard to their destination.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is as good a chance as we are going to get to rescue Verene\'s daughter.nnHere is how this is going to work. nnYou are going to wait here for the guard to pass by on their way to their guard shift. Look for something to hide in.nn<Silgryn marks a spot on your map.>nnYou will know the guard by their bright red armor.nnFollow closely, but not so closely that you are seen. It may be necessary to kill the guard when you reach your destination.nnThe child\'s name is Korine. Good luck.', `QuestDescription`) WHERE `ID` = 40745;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One of the People', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Vanthir in Suramar City.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time for you to enter the city proper, $n.nnI am sending you to my loyal friend Vanthir. I do hope you remember him- I can guarantee that he remembers you.nnI will not be able to accompany you, but I must stress that the disguise I have granted you is not impervious. Tread carefully, and avoid those who stare too long.nnFarewell for now.', `QuestDescription`) WHERE `ID` = 40746;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Delicate Art of Telemancy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Weathered Telemancy Beacon and Cracked Warpsleeve from Oculeth\'s Workshop.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I hadn\'t the time to gather my instruments before fleeing the palace. I came here to salvage some equipment.nnThis old workshop is actually several rooms connected by teleporter pads.nnElisande\'s goons are already scouring the place looking for me, but from here I can alter the teleporter network and keep them moving in circles.nnYou go in. I\'ll monitor your position and ensure the teleporters work normally for you.nnFind these two parts and bring them back!', `QuestDescription`) WHERE `ID` = 40747;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Network Security', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the lockdown sequence in Oculeth\'s Test Chamber.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must lock down the facility. Otherwise my esteemed colleagues from the palace could uncover my secrets, which puts any teleporters I build for you and Thalyssra at risk.nn<The inactive attunement device near Oculeth hums to life.>nnThis will take us to my secret test chamber beneath the mountain. From there we can begin the lockdown sequence and make our escape!', `QuestDescription`) WHERE `ID` = 40748;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Token of Remembrance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place 4 Bouquets of Moon Lilies.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The flower rests peacefully in your hand, glowing softly.$b$bWhile it doesn\'t appear to be growing anywhere nearby, there are small bouquets of the flower on some of the memorials around here.$b$bPerhaps laying down some flowers on the remaining graves will ease the gloom.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Place 4 Bouquets of Moon Lilies.', `AreaDescription`) WHERE `ID` = 40749;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azsuna - Treasure 020 - Olivian Rise', `LogTitle`) WHERE `ID` = 40751;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azsuna - Treasure 021 - Oracle', `LogTitle`) WHERE `ID` = 40752;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blingtron 6000', `LogTitle`) WHERE `ID` = 40753;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hiding in the Stacks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter Karazhan and search for knowledge of the Pillars of Creation with Khadgar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Magni\'s information was enlightening. It should prove handy to have a friend who has the ear of a titan.$b$bIt\'s time to head into Karazhan. Not that I need to remind you, but it can be a dangerous place. There are countless strata of spells woven throughout the tower, and the interactions of the forces within can be... unpredictable. Be on your guard.$b$bI\'ll join you inside. I need a moment to... gather my thoughts. This place holds a lot of memories for me.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Take the Tome to Archmage Modera in Dalaran above Karazhan', `QuestCompletionLog`) WHERE `ID` = 40755;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 DH-Mardum - Small Treasure Chest 012', `LogTitle`) WHERE `ID` = 40759;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Emissary', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Allari the Souleater.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As if things weren\'t unsettled enough, guests have arrived... the Illidari.$b$bThese demon hunters have been imprisoned since their master\'s fall at the Black Temple. For the Wardens to release them can only mean the peril is dire indeed.$b$bTheir delegation\'s leader, Allari "the Souleater," claims Orgimmar faces a hidden threat. I gave them leave to establish a camp within the city... for now.$B$BYou will speak with her at once. Find out whether this threat is credible.', `QuestDescription`) WHERE `ID` = 40760;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Whispers from Oronaar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the Ruins of Oronaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ethereals, the Void, a Dark Naaru... I feel they are all connected.$b$bI explored the ruins below while you and Velen were seeking the Crown. There are survivors, $n.$b$bBroken wander the cluster of buildings to our west- I cannot understand much of what they say but I suspect that their minds are not their own.$b$bIf the Void is to blame, we will need to start our investigation there.$b$bI will conduct my own search in the meantime.', `QuestDescription`) WHERE `ID` = 40761;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Zealot\'s Dues', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take Commander Domitille\'s Helm to Lothrius Mooncaller.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander Domitille represents the very essence of the Nightborne\'s corruption. Abhorrent of power not their own, enamoured with their Grand Magistrix to the point of zealotry, and focused utterly on the destruction of the Moon Guard.nnTake her helm to Lothrius as proof of her demise.', `QuestDescription`) WHERE `ID` = 40762;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Casual Redistribution', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 20 Bottles of Arcwine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lately there have been a disturbing array of changes involving our most precious resource, Arcwine. nnI imagine Thalyssra has thoroughly educated you about what happens when a Nightborne does not have access to a source of power like Arcwine.nnWith the presence of the demons came rationing. There are many who do not have enough to sustain themselves.nnBring me as much Arcwine as you can carry. I will see that it gets to the right people.', `QuestDescription`) WHERE `ID` = 40763;
