UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Kazok\'thul', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and slay Kazok\'thul in Azurewing Repose.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A rogue felhunter known as Kazok\'thul has been terrorizing Azurewing Repose in Azsuna.$b$bFelhunters feed on arcane energy and it seems that Kazok\'thul has been gorging itself on the mana from nearby Azurewing whelps.$b$bTravel to Azurewing Repose and speak with Ardonu to find the last known location of Kazok\'thul.$b$bSlay the demon and return here when your mission is complete.', `QuestDescription`) WHERE `ID` = 40776;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Balance Chosen', `LogTitle`) WHERE `ID` = 40781;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Scythe of Elune', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Valorn Stillbough in the Twilight Grove in Duskwood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have received word that Tyrande herself has authorized the release of a great artifact, the Scythe of Elune, to aid our cause. Valorn Stillbough has agreed to give up the weapon, which he has kept as part of an investigation into the cursed worgen of Duskwood.nnI believe that you, champion, will be our best hope at wielding its power without succumbing to the animal rage that ebbs within. You must go to Duskwood, and take up the scythe against our foes!', `QuestDescription`) WHERE `ID` = 40783;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Its Rightful Place', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Scythe of Elune from Valorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Though it goes against my better judgment, it is Tyrande\'s wish that the Scythe of Elune be brandished once more against the new Legion threat. It is a small comfort to see it wielded by a keeper of the balance, such as yourself.nnKnow that the last time the scythe was wielded, it resulted in great calamity. You must be vigilant to contain the bestial wrath that ebbs within. nnWith those words in your heart, take the scythe and bring its fury against our foes. May the light of Elune protect you.', `QuestDescription`) WHERE `ID` = 40784;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Foe of the Dark', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start your search for the Scythe of Elune at Manor Mistmantle in Duskwood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I cannot believe the Dark Riders found us here. Long have they hunted the scythe to sate their lust for the artifacts of Azeroth. We thought we would be protected within the grove...nnAnd now, Valorn is gone...nnYou must become the hunter, $n. Seek the Dark Riders and recover the scythe. We last encountered them near Manor Mistmantle in Duskwood. Start your search there.nnAnd $n... bring justice to Valorn. The rider must pay.', `QuestDescription`) WHERE `ID` = 40785;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Smoldering Ember', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Smoldering Timewarped Ember to Kiatke in Orgrimmar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Cold to the touch when you first reach for it, this ember bursts into flame without warning and snuffs itself just as quickly. As the stone rests in your hand, visions of fire and of dragons dance through your mind, but you can hear conversation taking place in Orgrimmar and the familiar sight of circle portals bubbles to the top.', `QuestDescription`) WHERE `ID` = 40786;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Smoldering Ember', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Smoldering Timewarped Ember to Kiatke in Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Cold to the touch when you first reach for it, this ember bursts into flame without warning and snuffs itself just as quickly. As the stone rests in your hand, visions of fire and of dragons dance through your mind, but you can hear the hustle and bustle of Stormwind and the familiar sight of circle portals bubbles to the top.', `QuestDescription`) WHERE `ID` = 40787;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Shattered Path Through Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 5 Timewalking dungeons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Destroyer\'s star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.', `QuestDescription`) WHERE `ID` = 40792;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Matter of Planning', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Master Hsu.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your weapon is stronger than ever, now is the perfect time to put it to use and take our fight to the Legion.$b$bMaster Hsu has set up a command table by the training grounds, and has collected reports from our friends and allies around all of Azeroth.$b$bWhen you are ready, Grandmaster, he should have an update prepared for you.', `QuestDescription`) WHERE `ID` = 40793;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fate of the Queen\'s Reprisal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Captain\'s Log to Lieutenant Surtees at the Greyfang Enclave on Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<This is the kind of intelligence that should be shared. Perhaps someone at the Greyfang Enclave on Dalaran will know what to do with it.>', `QuestDescription`) WHERE `ID` = 40794;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fight Begins', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your first assault point on the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Burning Legion has left a trail of ruin all across the face of Azeroth. We must strike at their bases within the Broken Isles if we are to have any hope of ending this war.$b$bI\'ve put together a map of the isles and a list of tasks that we will need to have done there.$b$bOnce you\'ve had a chance to peruse the map, you should choose where we will begin our assault.', `QuestDescription`) WHERE `ID` = 40795;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lingering on the Edge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Give Absolon 100 Ancient Mana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I h-have made... mistakes...nn<Absolon draws in a rasping breath.>nnI want to make it right... I want to live! But the madness... the WITHERING..nnI am... fading.nn<Absolon stares at you helplessly.>', `QuestDescription`) WHERE `ID` = 40796;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 DH-Mardum - Small Treasure Chest 014', `LogTitle`) WHERE `ID` = 40797;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cling to Hope', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver a letter to Absolon\'s Wife, Noressa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your kindness has inspired me, friend.nnI thought I would wander forever among the empty husks of the Withered, but Thalyssra invited me in.nnI have chosen to remain here with my people and together we will take back Suramar.nnFor now I have but one request.nnTake this letter to my wife. She should know that I still live, among other things.nnGive her the hope that you gave me.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Nightfallen Valendrel', `PortraitGiverName`) WHERE `ID` = 40798;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSE ME', `LogTitle`) WHERE `ID` = 40803;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Li Li Slotted', `LogTitle`) WHERE `ID` = 40804;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest: Dorion Fed', `LogTitle`) WHERE `ID` = 40810;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power to Survive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select an artifact weapon to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have long relied on Lord Illidan to vanquish the Legion\'s strongest warriors - many have expressed concern over our efforts without him.$B$BThankfully, their concerns may not matter much longer.$B$BWe know of two pairs of blades rumored to be more powerful than even Lord Illidan\'s that are not yet out of reach.$B$BIf we act quickly we should be able to hunt down one without forsaking our watch over the Legion\'s movements.$B$BI must defer judgment on which is most worthy of our time to you, $n.', `QuestDescription`) WHERE `ID` = 40814;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'From Within', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Kor\'vas Bloodthorn on Faronaar at Vanquish Point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our demon hunters, Kor\'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within.nnI haven\'t heard from them in a while.nnIt would be best if you could find and lead them to success. Agreed?', `QuestDescription`) WHERE `ID` = 40815;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power to Survive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select an artifact weapon to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Illidan and I may have disagreed, but he was unarguably powerful. He was pivotal in vanquishing some of the Legion\'s most powerful soldiers.$B$BHowever, that may not matter much longer.$B$BThere are two pairs of blades rumored to be more powerful than even Illidan\'s that may still be within reach.$B$BRegrettably, our numbers are too few to hunt both while maintaining our vigil over the Legion. I fear our window of opportunity is waning quickly.$B$BAs the ranking Illidari, that decision falls to you.', `QuestDescription`) WHERE `ID` = 40816;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Twinblades of the Deceiver Chosen', `LogTitle`) WHERE `ID` = 40817;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aldrachi Warblades Chosen', `LogTitle`) WHERE `ID` = 40818;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Making Arrangements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Kayn Sunfury outside the Violet Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you recall Varedis, $n? He was once our lead trainer, but fell with the Black Temple years ago.$B$B...or so we thought.$B$BKor\'vas spotted the traitor alongside the Legion... wielding glaives imbued with power unlike anything she\'d ever seen.$B$BThe Kirin Tor have an eredar lord locked away in the Violet Hold that will know where Varedis\' stronghold lies. The prison warden has agreed to consider granting us access to the fiend.$B$BTime to do some convincing.', `QuestDescription`) WHERE `ID` = 40819;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 DH-Mardum - Small Treasure Chest 015', `LogTitle`) WHERE `ID` = 40820;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Power Overwhelming', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Felblood Altar to unlock your first Artifact Trait.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Jagganoth\'s minions are now yours to command, Overlord, but there is more power to this place than just that!nnHere, at the Seat of the Overlord, you will find a special altar, formed of the pit lord\'s blood and charged with his power. This power can be transferred to your new weapon.nnApproach the altar, Overlord, and claim Jagganoth\'s power for your own!', `QuestDescription`) WHERE `ID` = 40821;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rebuilding the Council', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Resurrect Ritssyn Flamescowl in Dreadscar Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It seems that friend has caught the attention of Mephistroth. This is very bad news, as the dreadlord will surely wish to seek revenge for losing his general.nnFriend will need more than the Dreadscar to stand against him, you will need powerful warlocks such as those who were captured.nnCalydus thinks the orc still lies in the pit where you were chained. Friend must revive him, and rebuild the council!', `QuestDescription`) WHERE `ID` = 40823;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Path of the Dreadscar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Dreadscar Battle Plans to choose your first zone.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It would seem that where the council has failed, you have found untold success. These Dreadscar should prove powerful allies, but they may not be enough.nnFor now, we must look to rebuild. I will send agents out to locate the whereabouts of the captured council members, as well as any other warlocks who may be able to aid the cause.nnMeet me at the scrying pool, and we will plan our action from there.', `QuestDescription`) WHERE `ID` = 40824;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Raid Finder (1st)', `LogTitle`) WHERE `ID` = 40829;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Close Enough', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Carry Chief Telemancer Oculeth to Thalyssra in Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Oculeth\'s eyes have dulled. His voice trembles.>nnAre we... are we close?nnSo hungry...', `QuestDescription`) WHERE `ID` = 40830;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of The Uncrowned', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Read the Sealed Letter and follow the instructions within.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My masters gave me strict instructions to deliver this letter to you as quickly as possible.$B$BIts contents are for you and you alone.$B$BGood luck.', `QuestDescription`) WHERE `ID` = 40832;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Following the Curse', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden\'s Camp in Deadwind Pass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In my previous confrontation with your foe, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they once were.nnCome, we must go to Ariden\'s Camp in Deadwind Pass. I can explain its significance along the way.', `QuestDescription`) WHERE `ID` = 40834;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Disturbing the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search around Ariden\'s Camp for clues leading to the Dark Riders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner.nnHelp me search the camp. Let\'s see if we can find something to lead us to the Dark Riders.', `QuestDescription`) WHERE `ID` = 40835;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Deadwind Hunt', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow the tracks of the Nightbane worgen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Nightbane! If they are in Deadwind Pass, then they may be seeking the scythe as well.nnLet\'s split up and try to track them down. We\'ll see where their trail leads...', `QuestDescription`) WHERE `ID` = 40837;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dark Riders', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Dark Riders and claim the Scythe of Elune.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This sewer grate leads to the catacombs underneath Karazhan. I\'ve never paid it much attention, but it seems to be where the Nightbane are being drawn to.nnTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.', `QuestDescription`) WHERE `ID` = 40838;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Final Shadow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take your seat in the Council of Shadows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You walk in the halls of the Uncrowned. We are the slayers of kings, the downfall of empires, the unseen blades that write the true history of this world.$B$BSeated before you are the Shadows, the council which aims the blades of the Uncrowned wherever our will demands.$B$BWe have brought you here today with an offer. Take your seat as the final Shadow and help us lead the Uncrowned.$B$BWhat do you say?', `QuestDescription`) WHERE `ID` = 40839;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Worthy Blade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select a weapon to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'For quite some time, we\'ve been looking for someone who can operate outside these halls.$B$B$n, you are the answer to that search. You will be the blade in the dark that vanquishes our foes.$B$BIn order to do so, you require weapons capable of striking down the Legion\'s best.$B$BGreymane, Tethys, and Valeera each have devised plans to obtain weapons worthy of the tasks to come. I suggest you hear each out before proceeding.', `QuestDescription`) WHERE `ID` = 40840;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Kingslayers Chosen', `LogTitle`) WHERE `ID` = 40842;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dreadblades Chosen', `LogTitle`) WHERE `ID` = 40843;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fangs of the Devourer Chosen', `LogTitle`) WHERE `ID` = 40844;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Friendly Accord', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Fleet Admiral Tethys aboard the Crimson Veil in Booty Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'d like to offer ya an accord.$B$BThe Dread Admiral Eliza wields a pair of cursed blades that have made her the scourge of the south seas. She also stole one of me best ships - the Horizon\'s Edge - and has it anchored off the shore of Azsuna as we speak. $B$BIf you help me take back me ship, then her cursed blades are yours.$B$BNow, assuming that sounds agreeable, meet me aboard the Crimson Veil. We have her docked right in Booty Bay - not a cheap arrangement.', `QuestDescription`) WHERE `ID` = 40847;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dreadblades', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Capture the Horizon\'s Edge and obtain the Dreadblades.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can promise ya a safe journey to Eliza\'s position, but once we\'re there... well, we both know there be no guarantees.$B$BThe plan is simple. We\'ll take the Crimson Veil as close as we can get her without being seen and disembark from there.$B$BOnce we\'re ashore, we\'ll board the Horizon\'s Edge, bribe her mutinous crew to hand it over, and hunt down Eliza and her legendary blades wherever she may be.$B$BJust say the word when yer ready.', `QuestDescription`) WHERE `ID` = 40849;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prisoners of Greystone', `LogTitle`) WHERE `ID` = 40850;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest', `LogTitle`) WHERE `ID` = 40853;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Endless Possibilities', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Fel Reaver Husk back to Didi the Wrench in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Say, since you\'re down here, I have something that you might be interested in.$b$b<Filgo points over to a husk lying in the junk behind him.>$b$bI found that thingy down in Azsuna, just lying on the beach. I\'m sure with a little tinkering, an engineer like you could probably get it up and running in no time.$b$bMight even be useful against the Legion. Kind of like fighting fel with fel, heh!', `QuestDescription`) WHERE `ID` = 40854;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Our Man in Azsuna', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Fargo Flintlocke in Azsuna near the Felblaze Ingress.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Yikes! OK. This thing is missing a LOT of parts.$b$bWhy don\'t you go hunt down some new gears or whatever while I do what I can to its existing frame?$b$bA colleague of ours, down in Azsuna, may be able to help out here. His name\'s Flintlocke.$b$bFetching parts should keep him out of trouble. Just don\'t let him BUILD anything.', `QuestDescription`) WHERE `ID` = 40855;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'It\'ll Cost You', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Fel Reaver Arm and a Fel Reaver Leg from within the Felblaze Ingress.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If yeh need demon parts, oh aye, this place is right teeming with them fel buggers.$b$bYer bound ta find what\'yer lookin\' fer probably near them portals they\'ve got jus\' sou\'east of \'ere.', `QuestDescription`) WHERE `ID` = 40856;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bits and Pieces', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Brann Bronzebeard in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So many artifacts to catalogue, and never enough time.$b$bGood to see you again, $n. Brann Bronzebeard and the Explorers\' League are in Stormheim right now and could use your help tracking down an ancient titan relic.$b$bBrann can fill you in on the details when you arrive.', `QuestDescription`) WHERE `ID` = 40857;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Missing Pieces', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Head back to Didi the Wrench in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Yeh seem ta \'ave everything yeh need. Head back to Didi now wit\' yer supplies and giv\'er a slap on tha back from me!', `QuestDescription`) WHERE `ID` = 40858;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Latest Fashion: Headguns!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Fel Critters using Flintlocke\'s Headgun Prototype.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So Grapplehammer\'s got hisself a whole lotta extra guns, right? Glorious! An\'it got me ta thinkin\', "What if we put \'em on our heads?"$b$bHear me out!$b$bSee, yer hands are already busy with yer current weapons, but what\'s yer head doin\'? It\'s just sittin\' there LOOKIN\' at stuff. That\'s me plan. Weaponize yer head!$b$bYou, me lucky $glad:lass;, can test it out. Strap this on. Now, go blast some fel-tainted critters down below. Blammo!', `QuestDescription`) WHERE `ID` = 40859;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Resupplying the Line', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the Crate of Ammunition to Fargo Flintlocke in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I need you to make a delivery for me.$b$bFlintlocke\'s sent word from Val\'sharah stating that they\'re out of bullets.$b$bI sent him down there with enough ammo to cut the planet in half, but Flintlocke goes through ammunition the way you or I go through... air. Go help him out!', `QuestDescription`) WHERE `ID` = 40860;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In My Sights', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover $1oa Deployable Bullet Dispenser Parts around Moonrest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I used up all me bullets on a wee invention of mine. I call it: Tha Deployable Bullet Dispenser!$b$bOh aye. It shoots in-der-scriminantly wit\'out all that messy and time-consumin\' "aiming" or "thinkin\'" that us people-folk are wont ta do.$b$bWe had deployed quite a few of \'em east o\' here when this swarm of plants came a\'thrashin from tha trees.$b$bI didn\'t \'ave time ta go back an\' get me turrets. Would ye mind gettin\' them back fer me? Or at least, what\'s left of \'em?', `QuestDescription`) WHERE `ID` = 40861;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'All Charged Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Flintlocke\'s Gunpowder Charges to kill $1oa Shimmering Oleanders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If yer gonna wander inta these woods, ye\'ll be wantin\' somethin\' with some punch. These plants are a might grabby.$b$bI\'ve got me special explosive charges here that should send those fertilizer mutations back to the dirt.$b$bTake \'em with yeh and give them viney beasties a what-fer!', `QuestDescription`) WHERE `ID` = 40862;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Always the Last Thing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find a suitable power source for Didi\'s design and deliver it to her. Then, see if her new battery actually works.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well, I\'ve worked out all the kinks. Added a few nuts and bolts, and fitted a new housing for the power core.$b$bProblem is, none of the batteries I have here seem to work. I think we\'re gonna have to fashion somethin\' new together.$b$bI\'m gonna need your help, $n. Let\'s start by trying a charged gem from the jewelcrafting shop down the way.', `QuestDescription`) WHERE `ID` = 40863;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Modular Modifications', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Create a Reaves Module: Snack Distribution Mode. Then summon Reaves and install it into him.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we got this baby running, let\'s give it some cool abilities.$b$bWhen I was fixing Reaves up, I installed a module port onto his motherboard. This will allow us to upload anything we want.$b$bI\'ll teach you one of my module designs and you install it on Reaves.', `QuestDescription`) WHERE `ID` = 40864;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'It\'s Not Rocket Science', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Fargo Flintlocke in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I need you to help me track down Flintlocke again.$b$bI sent him to Stormheim to gather some materials for an invention of mine and he hasn\'t been back for days. I\'m not worried about Flintlocke, but I DO fear for Stormheim.$b$bSee if you can find him!', `QuestDescription`) WHERE `ID` = 40865;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Shell, You Say?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay murlocs to collect  $1oa of their shells for Fargo Flintlocke.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know ol\' Hobart sent me down \'ere to acquire \'is precious murloc glass thingies, but I have designs of me own!$b$bI\'ve seen those murlocs carrying interesting lookin\' shells that would go perfectly into me music box I\'ve been workin on.$b$bYa lead the charge an\'a I\'ll be right behind ya.', `QuestDescription`) WHERE `ID` = 40866;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bubble Baubles', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Murloc Trinkets from around their camps.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ol\' Hobart wanted me ta gather up these shiny, glass trinkets the murlocs carry around, but those bloody buggers ain\'t willin\' to jes\' hand \'em over!$b$bI tried the dip-ler-matic approach, but I don\'t speak murloc, so I just end up shootin\' \'em.$b$bMaybe you might have better luck gettin\' them baubles.', `QuestDescription`) WHERE `ID` = 40867;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wibbly-Wobbly, Timey-Wimey', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the Murloc Trinkets to Hobart Grapplehammer in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I gotta finish up \'ere, so why don\'tcha take those trinkets back to Hobart fer me.$b$b\'Sides, I\'ma thinkin\' he likes ya more than me.', `QuestDescription`) WHERE `ID` = 40868;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fire and Forget', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Test out the Prototype Pump-Action Bandage Gun on Wounded Kirin Tor Guardians in Dalaran. Use the gun to calibrate it when needed.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'They say, "When life gives you lemons, make lemonade." Well, life gave me a butt-load of guns.$b$bSo I\'ve been figuring out ways to turn these guns into useful tools.$b$bMy latest modification is a gun that shoots bandages! Imagine it, you\'re on the battlefield, you see your ally go down, you pull out your bandage gun, shoot him with it and bam, he\'s back in the fight!$b$bI just need you to test it first and make sure it\'s safe.', `QuestDescription`) WHERE `ID` = 40869;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Here Comes the BOOM!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Get Didi\'s fireworks back from the children in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, they stole all my fireworks, the little scamps.$b$bYou didn\'t see them? I was just on the verge of creating a new module for Reaves when these kids came in here and ran off with my fireworks.$b$bI need them back if I\'m going to finish what I\'m working on. Can you go get them back for me?', `QuestDescription`) WHERE `ID` = 40870;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '\'Locke and Load', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Fargo Flintlocke in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Flintlocke\'s been looking for you, $n. I think he needs your help again.$b$bI sent him out to test out a couple of new inventions of mine back down in Azsuna. Look for him on the shoreline west of Oceanus Cove!', `QuestDescription`) WHERE `ID` = 40871;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Going Out With a Bang', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Gunshoes to skim across the water while picking up $1oa pieces of Gunpack Debris.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While I was, eh, testin\' out this new flight pack fer Hobart, it sorta exploded an\' sent me flyin\' back over \'ere.$b$bYou can see all the pieces out there in tha water.$b$bNow, I\'ve got these boots \'ere that Hobart gave me to test out too, but they\'re not quite me size.$b$bI figure we could kill two birds with one stone and \'ave ye test \'em out while pickin\' up the broken bits of the pack.$b$bMind tha sharks while yer out there.', `QuestDescription`) WHERE `ID` = 40872;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keep Yer Powder Dry', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Barrels of Gunpowder and return them to Fargo in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So while we\'ve got all tha parts for tha pack again, I\'m afraid I\'m all outta gunpowder.$b$bThis is the worst thing ta ever happen ta me.$b$bBut there\'s hope. Just o\'er to tha north are caves filled with crashed ships. Chances are them sea giants crashed one or two ships with cannons. And cannons mean gunpowder, sweet gunpowder.$b$bSearch their caves fer sum powder an\' bring it on back.', `QuestDescription`) WHERE `ID` = 40873;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'I\'d Do It Myself, But...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Hatecoil Slavemasters in the Oceanus Cove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If yer headed over ta tha sea giant caves, do me a favor give those slimy naga a right bludgerin\'.$b$bThey done run oft with me rogue friend an\' I figure some revenge is in order.$b$bI\'d do it meself but ol\' Hobart would give me wut-fer if I abandoned his stuff.', `QuestDescription`) WHERE `ID` = 40874;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Going to Waste', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Lowping in the sea giant caves, shave his head, and make a copy of the schematic that\'s tattooed there.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Me wee rogue friend Lowping were$bgnome-napped by them dirty naga when we got \'ere. He\'s gone! They drug him right oft toward tha cove!$b$bBut \'ere\'s tha real issue. He \'ad a schematic on \'im fer one of me greatest inventions.$b$bAnd by "on \'im," I mean I tattooed it to tha top o\' his head. FOR SAFETY!$b$bWhen ye find \'im, jes shave \'is head and make a quick copy o\' tha design.', `QuestDescription`) WHERE `ID` = 40875;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '\'Locke, Stock and Barrel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Hobart in Dalaran and inform him of Flintlocke\'s work.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well that jes\' about wraps up me work \'ere. I\'ll start packin up an\'ead back ta Dalaran.$b$bIf yeh wouldn\'t mind, could yeh tell Hobart \'ow things went down \'ere? Maybe leave out tha bits with tha explodin\', tha drownin\', an\' tha gettin captured an\' what not.$b$bYer a proper friend, $n!', `QuestDescription`) WHERE `ID` = 40876;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: Trigger Happy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Runestone of Vitality from Odyn in the Halls of Valor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to complete my latest invention, I need a special relic known as the Runestone of Vitality.$b$bOdyn, king of the Halls of Valor is known to use it to breathe life into his constructs.$b$bWhat I\'m asking is no easy task, but I need to take the runestone from Odyn and bring it back to me.', `QuestDescription`) WHERE `ID` = 40877;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on Violet Hold: Cheating Death', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft $1oa Failure Detection Pylons. Go to the Violet Hold and recover a Plasmatic Laser Bolt and return everything to Didi the Wrench in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hobart was showing me a copy of a design you found, and it got me to thinking of a new module for Reaves.$b$bUnfortunately I didn\'t have the materials required to test it.$b$bCould you make me a couple Failure Detection Pylons?$b$bI\'ll also need a plasmatic laser bolt. You should be able to find one in the Violet Hold.', `QuestDescription`) WHERE `ID` = 40878;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'It\'s On With Automatons', `LogTitle`) WHERE `ID` = 40879;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Short Circuit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the inventor of Blingtron.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While I\'ve got you here, I was wondering if you could track something down for me.$b$bI\'m sure you\'re familiar with a Blingtron, yes? Well, I started askin\' around, and it seems no one really knows where the design for it came from. One rumor does pop up more than others, though:$b$bArea 52.$b$bInterested in a field trip?', `QuestDescription`) WHERE `ID` = 40880;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Oil Rags to Riches', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Didi the Wrench in Dalaran and show her the items you\'ve found.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Didi will be very interested in reading the journal you found as well as examining the circuit design.$b$bYou should return to her as soon as you can.', `QuestDescription`) WHERE `ID` = 40881;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Court of Stars: Revamping the Recoil', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go into the Court of Stars and recover the Arcanic Compressor for Hobart.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, you\'ll be very excited to hear that I\'ve been working on a newer, better version of those goggles that Flintlocke rigged up.$b$bThe ones I\'ve designed have double the power, but unfortunately they also have double the recoil. I\'m afraid if you use them, they\'ll break your neck.$b$bBut I found a solution. Deep inside Suramar City lies a magical mechanism that will reduce the recoil to practically nothing.$b$bRecover that mechanism for me and we\'re in business!', `QuestDescription`) WHERE `ID` = 40882;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fate of the Guard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the corpses of Nyellus Starweaver, Galar\'thus Rivertree, and Kailea Windfeather and perform funereal rites for them.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Thalrenus looks you over.>nnYou are not one of them.nnThe Nightborne came to our gates hours after the shield over Suramar fell. We thought them friends, despite our long separation.nnWe were wrong.nnThey poured into our stronghold and began the slaughter. We were unprepared. Though we fought, we were beaten.nnThe keep is lost. Our leaders have perished and their corpses lay in the streets.nnFind them, give them their final rites.nnWhile you search, look for survivors. Help them if you can.', `QuestDescription`) WHERE `ID` = 40883;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hammer of Khaz\'goroth Actived', `LogTitle`) WHERE `ID` = 40888;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tidestone of Golganneth Activated', `LogTitle`) WHERE `ID` = 40889;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Tears of Elune', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the central teleporter in Dalaran and then place the Tears of Elune in the Portrait Room.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tear of Elune floats effortlessly, glistening in an ethereal pillar of moonlight.', `QuestDescription`) WHERE `ID` = 40890;
