UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fresh Meat', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Fresh Fel-Flesh.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This crater is infested with felfire basilisks.$b$bThey may not be the most cunning of creatures, but they are as vile and dangerous as any demon.$b$bHowever, they may yet prove useful to us. Slay the basilisks, but return to me with chunks of their fel-infused flesh.$b$bI have plans to make use of their freshly carved flesh...', `QuestDescription`) WHERE `ID` = 40898;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Burden Borne', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Arch Druid Greathoof in the Dreamgrove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your assistance against the Dark Riders has proven a great service to the Light. Though our beliefs may separate us, I know that we share one goal.nnYou have allowed me to fill my purpose in returning these artifacts to their rightful owners, and for this I am thankful. As for the Scythe of Elune, I can think of no safer place than in your care. nnMay it serve you well against the Legion, $n.', `QuestDescription`) WHERE `ID` = 40900;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grimwing the Devourer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Grimwing the Devourer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have my thanks for rescuing me from captivity, $c.$b$bHowever, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion.$b$bIf you wish to continue with me, I need proof of your strength.$b$bGrimwing the Devourer is the strongest of the felbats and a suitable test of skill. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears.$b$bReturn to me with her head and I will not doubt your ability.', `QuestDescription`) WHERE `ID` = 40901;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Suramar - Treasure 002 - Fel Breach - AJB', `LogTitle`) WHERE `ID` = 40902;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shadow of the Defiler', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Consult the keepers of Moonglade to see if they can shed any light on the nature of the Remnant of Chaos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Crimson energy swirls within this disturbing object, which seems to have slightly different contours each time your gaze returns to it.$B$BIts power is utterly foreign, unlike anything you have seen in Draenor or during your battles with the Legion. Perhaps the keepers of Moonglade, back on Azeroth, might have some insight into its nature.', `QuestDescription`) WHERE `ID` = 40904;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lieutenant Strathmar', `LogTitle`) WHERE `ID` = 40905;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Serpents from the Deep', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Toryl outside of Jandvik.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hail, $c.$B$BMy village of Jandvik has fallen under siege by a group of naga called the Sashj\'tar.$B$BNormally I would not seek out the help of an outsider, but we are facing an enemy that we are incapable of defeating.$B$BMany powerful elven relics can be found in the ruins around Jandvik. In exchange for your help, you will have your just rewards.$B$BDo we have an accord?', `QuestDescription`) WHERE `ID` = 40906;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Removing Obstacles', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Calder and Eynar in Jandvik.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$C! Interested in earning some coin?$B$BThe jarl of Jandvik is missing and two headstrong whelps are vying to take over leadership. I should be the next jarl, not them!$B$BI want you to enter Jandvik and defeat Calder and Eynar in mortal combat.$B$BI would not normally put my trust in an outsider, but this situation requires the aid of someone like you. Jandvik would condemn me if I were caught with their blood on my hands.$B$BMeet me in the center of Jandvik when the deed is done.', `QuestDescription`) WHERE `ID` = 40907;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Jarl Come Back Now', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Jarl Throndyr in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You seem to follow my commands well, $n. Perhaps I can use you again.$B$BJarl Throndyr, the leader of Jandvik, has been missing for some time now. I assume that he has fallen in battle to the invading Sashj\'tar naga, but I must know for certain.$B$BFind out what has become of him.$B$BDo this task for me and I can assure you that my vrykul will not harm you.', `QuestDescription`) WHERE `ID` = 40908;
