UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel Bent for Leather', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Felbat Hide Scraps for Kyrtos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ah, my faithful assistant. I have just the task for you.$b$bAs you have seen, fel power permeates living tissue and can easily be coaxed out.$b$bAlso, these damned bats are driving me to my wits\' end. There is an opportunity to kill two bats with one blade, it seems. Your blade.$b$bTake this crystal. It should rip those hellions from the sky and into your waiting arms.$b$bYou may as well bring back their hides, if only to shut up that fellow in the corner for a few moments.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect 100 Felbat Hide Scraps for Kyrtos.', `AreaDescription`) WHERE `ID` = 40919;
