UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Infused with Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the altar to imbue your artifact weapon with a new power.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The weapon you hold will strike a potent blow against the Legion... but the demons are relentless. Just as your battle tactics grow and evolve, so must your weapon.$b$bThe altar before you courses with ancient magic, and is alive with the skill and dedication of the hunters who have used it through the ages.$b$bPlace your artifact upon it, and over time you will awaken the full potential of your weapon.', `QuestDescription`) WHERE `ID` = 41047;
