UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Desperate Plea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with High Overlord Saurfang at Krasus\' Landing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Saurfang has not been the same since our loss at the Broken Shore. Though he led well and slew many, he has taken our defeat hard.$b$bI fear he is determined to return to the Broken Shore. Will you speak to him?', `QuestDescription`) WHERE `ID` = 41052;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Altar of the Eternal Hunt', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Altar Keeper Biehn inside the Trueshot Lodge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you\'ve rallied hunters from across Azeroth together, it\'s time to turn your attention to the battle against the Burning Legion.$b$bWithin the Trueshot Lodge is the Altar of the Eternal Hunt. It is an ancient relic alive with old magic, and I believe it can be used to infuse your weapon with even greater might.$b$bGo inside the lodge and speak to Altar Keeper Biehn, who can instruct you in its use.', `QuestDescription`) WHERE `ID` = 41053;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Love Lost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Tyrande Whisperwind at Starsong Refuge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Malfurion, my love...$b$bIn vision I saw him, enraged and then distressed, and now lost beyond my mind\'s reach.$b$b$R, I know we have little reason to trust one another, but I will not turn away your help.$b$bIf you value the sanctity of this world, you will come with me.', `QuestDescription`) WHERE `ID` = 41054;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Primal Payback', `LogTitle`) WHERE `ID` = 41055;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Love Lost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Tyrande Whisperwind at Starsong Refuge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Malfurion, my love...$b$bIn vision I saw him, enraged and then distressed, and now lost beyond my mind\'s reach.$b$bHe is strong, but the horrors that have befallen this land are all-consuming.$b$bI must find him, and you must help me!$b$bGather your wits, $r, and follow me.', `QuestDescription`) WHERE `ID` = 41056;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Primal Payback', `LogTitle`) WHERE `ID` = 41057;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: Odyn\'s Cauldron', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Odyn\'s Cauldron from the Halls of Valor, then pass Odyn\'s trial.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your actions in Stormheim were courageous. I thank you for avenging me, and for helping my apprentice, Aegira. I can think of none better to inherit my knowledge.$B$BWith you, I will share the secret to my Storm Brew. The true strength of the brew comes from Odyn\'s Cauldron, which can be found in the great hall just ahead.$B$BYou have my blessing to borrow it. Good luck in your journey ahead, $n.', `QuestDescription`) WHERE `ID` = 41059;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unbridled Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the Fel Hammer and rally your Illidari forces.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord.$B$BThankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!', `QuestDescription`) WHERE `ID` = 41060;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spoils of Victory', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Have Battlelord Gaardoun show you what your forces obtained.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Fel Hammer will be a fine home for our kind, but it is what we found within its depths that is the true prize of our conquest.$B$BBattlelord Gaardoun and his Ashtongue have it closely guarded - you should have him show you.', `QuestDescription`) WHERE `ID` = 41062;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cursed Forge of the Nathrezim', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Cursed Forge of the Nathrezim to empower your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Even as we speak, the Legion\'s dark masters fashion new horrors in hopes that they might destroy us - especially you.$B$BYou must increase your own power as well.$B$BThe Cursed Forge of the Nathrezim, our greatest treasure from taking the Fel Hammer, waits in the chamber ahead. You can use it to further empower your blades and maintain our edge over the enemy.', `QuestDescription`) WHERE `ID` = 41064;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hunter\'s Gaze', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Empowered Nether Crucible to gaze upon the Burning Legion\'s forces in Azeroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, before you lies your nether crucible - more powerful than any we\'ve crafted before.$B$BThe souls of the hundreds of slain demons in Mardum have provided us with enough power to directly observe the Legion on Azeroth.$B$BWhat we have uncovered so far has been... unsettling. Gaze into the pool and see for yourself.', `QuestDescription`) WHERE `ID` = 41066;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Time is of the Essence', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Kayn Sunfury.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you can see, there is little time to spare - the Legion\'s armies already encroach on our world.$B$BKayn has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.', `QuestDescription`) WHERE `ID` = 41067;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Direct Our Wrath', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your first assault point on the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must seal the Tomb of Sargeras at all costs or the flow of demons will never cease.$B$BUntil then, we must do what we can on the ground to alleviate their foothold before it grows further.$B$BThis citadel was created to spearhead Legion invasions on other worlds - we can use its navigation systems to plan our assault.$B$BI think you would agree that none would be better suited to lead our charge than you.', `QuestDescription`) WHERE `ID` = 41069;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spoils of Victory', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Have Battlelord Gaardoun show you what your forces obtained.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In conquering this citadel we obtained something that I think would be of great use to you.$B$BGaardoun\'s men have it well-guarded just below - I suggest you have him show you.', `QuestDescription`) WHERE `ID` = 41070;
