UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Mage\'s Weapon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Appendix of Azerothian Artifacts to choose an artifact to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is decided, then.nnThe foundation of the Tirisgarde\'s strength lies in the ancient artifacts wielded by its champions. Your first task will be to retrieve one such artifact.nnThe master appendix of this library lists every artifact known to the Council of Tirisfal. There should be a few choices in there worth looking into.nnI will leave it to you to choose which to pursue.', `QuestDescription`) WHERE `ID` = 41085;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Peaceful World', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 World Quests.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Word has reached us that the Legion is advancing on the Broken Isles.$B$BThey beset us from all sides, and if we do not stand strong, they will spill over into the rest of Azeroth.$B$B$n, we need your help more than ever. Lend your strength to those defending at the front. We cannot fail here.', `QuestDescription`) WHERE `ID` = 41086;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Storm Brew', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take Tak-Tak\'s kite to the Ridge of Laughing Winds, help Chen Stormstout & Aegira make the Storm Brew, and defeat the Burning Legion\'s forces.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Grandmaster, the Legion is attacking the Wandering Isle!$B$BWe sent defenders up to the Ridge of Laughing Winds, but they can\'t hold for long.$B$BOur only chance is to finish making the Storm Brew. Chen and Aegira have already gone up to the Chamber of Whispers, but they are under heavy attack as well.$B$BSpeak to Tak Tak and take a kite up to join them at once!', `QuestDescription`) WHERE `ID` = 41087;
