UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hatchlings of the Talon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Aviana to receive her blessing, then complete her challenge by collecting Emerald Globes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, hatchling. Do you wish to soar amongst the clouds as my children do?nn<Aviana chuckles - a clicking, crow-like noise.>nnVery well, receive my blessing and we shall see how developed your wings are.', `QuestDescription`) WHERE `ID` = 41094;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Critical Crops', `LogTitle`) WHERE `ID` = 41095;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Time is of the Essence', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Altruis the Sufferer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you can see, there is little time to spare - the Legion\'s armies already encroach on our world.$B$BAltruis has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.', `QuestDescription`) WHERE `ID` = 41096;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shard of Vorgos', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Shard of Vorgos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'According to the wyrmtongue servant, there is a portal that will take you into the Burning Legion command ship. However, the portal is locked to those without the keys.$b$bThe first key shard is held by an Ered\'ruin known as Vorgos. He resides within the Fel Breach, which is at the end of the Arcway.$b$bSlay Vorgos and place the key shard into its position next to the portal.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect $1oa Shard of Vorgos.', `AreaDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Vorgos possesses one of the keys to the Lightbreaker. We must take it from him.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Vorgos', `PortraitGiverName`) WHERE `ID` = 41097;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shard of Kozak', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Shard of Kozak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demon leading the operation in Felsoul Hold is an eredar named Azoran. In order to get to him, we will need to open a portal to the Burning Legion command ship.$b$bAzoran has a demon jailer in his service known as Kozak the Afflictor.$b$bKozak the Afflictor holds one of the key shards necessary to open a portal to the ship. He can be found in the prison quarters known as the Halls of the Eclipse in the lower portion of Felsoul Hold.$b$bSlay Kozak and place his key shard next to the portal.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Find Kozak the Afflictor and claim his key to the Legion ship.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Kozak the Afflictor', `PortraitGiverName`) WHERE `ID` = 41098;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Direct Our Wrath', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your first assault point on the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tomb of Sargeras is the Legion\'s primary entrance into our world - it must be destroyed.$B$BNo easy task, but until we have the means to do so we must do what we can to stop their invasion.$B$BThe Legion used this citadel to spearhead invasions on other worlds - we can use its navigation systems to plan our own assault against them.$B$BYou, of course, must take the honor of first breaking ground on their territory, but we will soon follow.', `QuestDescription`) WHERE `ID` = 41099;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Swap Didis', `LogTitle`) WHERE `ID` = 41100;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Sword of Kings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Strom\'kar, the Warbreaker and deal with Zakajz.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The first king of the humans, Thoradin, performed many acts of heroism and valor. While on a personal quest near the end of his reign, he stumbled upon the tomb of my brother Tyr... and the grave-prison of the monstrosity he died fighting. Thoradin unintentionally awoke the beast and gave his life to keep it from escaping.nnIt is Thoradin\'s sword, Strom\'kar, that has kept the monster at bay. Retrieve it and finish what Tyr and Thoradin started. Kill Zakajz the Corrupted.', `QuestDescription`) WHERE `ID` = 41105;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Wilds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Zen\'tabra and Naralex, and direct them to the ritual site.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Beating the Legion requires us to strike quickly and unexpectedly.$b$bWe have discovered a Dreamway by which we can travel through the Emerald Dream itself. Though only a short walk through the Dream, it will allow us to cross vast distances on Azeroth and even access the ancient home of all druids, Val\'sharah.$b$bMalfurion is preparing the ritual to open the Dreamway. I need you to summon Zen\'tabra and Naralex to his side.$b$bOnly by combining our efforts can we hope to succeed.', `QuestDescription`) WHERE `ID` = 41106;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bad Apples', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Shadowbloom.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That fruit over there? That\'s a pale imitation to what I can grow.$b$bBut that accursed Daglir somehow manages to gain the favor of the courts, so we must dine on mediocrity!$b$bWe must teach Daglir a lesson for stealing my crop, but we must be discreet.$b$bOutside the shield grows a purple flower called Shadowbloom. Fetch some for me and we\'ll make sure that he pays dearly for his insolence!', `QuestDescription`) WHERE `ID` = 41107;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rain Death Upon Them', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 50 Nightborne.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Aboard the hippogryph you now possess a unique opportunity. It is time for the Nightborne to regret letting you live.', `QuestDescription`) WHERE `ID` = 41108;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Waiting for Revenge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mount a Hippogryph.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Volatile Spell Focus hums with energy as you hold it. Handle with care! nnOnly with this item in your possession will the Hippogryphs allow themselves to be mounted.', `QuestDescription`) WHERE `ID` = 41109;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Waiting for Revenge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mount the Hippogryph.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Hippogryph eyes you curiously, searching your hands.', `QuestDescription`) WHERE `ID` = 41110;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rain Death Upon Them', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 50 Nightborne.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The hippogryph before you presents a unique opportunity. It is time for the Nightborne to regret letting you live.', `QuestDescription`) WHERE `ID` = 41111;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Great Akazamzarak', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place the Sizeable Pouch of Gold in Akazamzarak\'s tip bucket.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is a goblin who is a master of portals and teleportation by the name of Akazamzarak. His talents have gone mostly unnoticed, however, since he mostly uses them for chicanery.nnHe is, what you would call, a street performer.nnFortunately for us, he is performing in the streets of Dalaran, grifting coins from the unenlightened masses.nnTake this bag of gold. See if you can convince him to change vocations.', `QuestDescription`) WHERE `ID` = 41112;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Only Way to Travel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Meryl Felstorm in the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Portals? Teleportation? You bet I can help you out with that! I mean, how do you think I pull the rabbit out of...nn...um, you didn\'t hear that.nnAnyway, I can help you move your mages around, if the price is right. Heck I can even teach those combat mages a thing or two. Ever been on the receiving end of an exploding bunny? It ain\'t pretty!nnFor starters, let me whip up a portal to take us to this hall you\'re talking about.', `QuestDescription`) WHERE `ID` = 41113;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Champion\'s Return', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Teleport to the Hall of the Guardian and return to Meryl Felstorm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can sense the power of the artifact you hold. It will do well against the Legion as it is, but we have the ability to unlock its power even further. nnYou must return to the Hall of the Guardian. You can use the incantation I taught you before to pass through the runes.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Meryl Felstorm', `PortraitGiverName`) WHERE `ID` = 41114;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Chen Stormstout', `LogTitle`) WHERE `ID` = 41115;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Artifacts - Shaman - Puzzle Room - Treasure - DGK', `LogTitle`) WHERE `ID` = 41116;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seen Thalrenus Iceblock Shenanigans', `LogTitle`) WHERE `ID` = 41117;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hunt', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Twinblades of the Deceiver from Varedis Felsoul in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You must lead this hunt, $n - a small force will join you to ensure Varedis meets his end.$B$BYou must try to make it into Varedis\' hold undetected; the less time you spend in Legion territory the better.$B$BMeet at Krasus\' Landing when you are prepared to leave.', `QuestDescription`) WHERE `ID` = 41119;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Making Arrangements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Altruis the Sufferer outside the Violet Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you remember Varedis? He was once our lead trainer at the Black Temple, but fell early in the siege.$B$B...or so we thought.$B$BKor\'vas spotted the traitor amongst the Legion wielding glaives imbued with power unlike anything she\'d ever seen.$B$BThe Kirin Tor have an eredar lord interred in the Violet Hold that will know where Varedis\' base of operations is. The hold\'s warden has agreed to consider granting us access to him.$B$B<Altruis smirks.>$B$BTime to play the friendly diplomat.', `QuestDescription`) WHERE `ID` = 41120;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'By Any Means', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gain entrance to the Violet Hold and interrogate Taldath the Destroyer to find out the location of the traitor Varedis.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need to find out Varedis\' location from the eredar inside this prison - the kind warden and his men here are all that stand in our way.$B$BWe\'ll take them on together if need be - whatever it takes.', `QuestDescription`) WHERE `ID` = 41121;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mists Take You', `LogTitle`) WHERE `ID` = 41122;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Artisan\'s Mark', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain Lespin\'s Signet Ring.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You there! Do you have a moment?$b$bI need you to meet with my friend in the Promenade and retrieve a signet ring. I would send my oaf of an apprentice, but he is not finished with the simple task I gave him.$b$bI am expecting a guest at any moment and I simply must have it before he arrives. Can you help me, friend?', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Obtain Lespin\'s Signet Ring.', `AreaDescription`) WHERE `ID` = 41123;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Tirisgarde Reborn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Receive your new title from Meryl Felstorm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tirisgarde is reformed.  It is time we begin our mission in earnest.nnThe order will need leaders, and though I may be an experienced mage,  I am no strategist. You have proven yourself capable, in both your past exploits and present. nnWill you take on this challenge, $n?', `QuestDescription`) WHERE `ID` = 41124;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unlocked Potential', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Forge of the Guardian to unlock the first trait for your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In ancient times, the Forge of the Guardian was used to channel the power of the Council of Tirisfal into one mage, creating a Guardian. But this is not its only use.nnIt also serves as a font of arcane energy which can be used to manipulate and empower the artifacts of this world. nnThis power will allow us to gain the upper hand against the dreadlord and the Burning Legion, and I ask you to be the first to tap into it.', `QuestDescription`) WHERE `ID` = 41125;
