UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fall of the King', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place the Jandvik Banner on the Sea Giant King\'s island to draw him out and defeat him.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All that remains is the Sea Giant King.$B$BPlace our banner upon his beach and draw him out of the sea. Once he has revealed himself, use the trident to wound him.$B$BThere is a derelict boat that washed up on the shore. Use that to quickly get to the king\'s island.$B$BGird your loins, $n. This fight will not be easy.', `QuestDescription`) WHERE `ID` = 41137;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Feeding Shal\'Aran', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Examine the Leyline Feed in Shal\'Aran with Arcanist Valtrois.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With leyline energy feeding in from Anora, this chamber can begin to awaken.$B$BIt will be a slow process, and we must take care to mask this activity from our enemies, a process which itself requires enormous effort and focus.$B$BFurthermore, there is the conundrum of actually consuming the mana in this form. A stream too weak is not enough to provide sustenance - too powerful and it would vaporize us.$B$BThere is much work to be done yet. For now, let us examine the feed.', `QuestDescription`) WHERE `ID` = 41138;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Key Is Around Here Somewhere...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Reinforced Cage Key.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well aren\'t ye a sight fer sore eyes!$b$bIt\'s no use tryin\' to bust open this cage, this one needs a key!$b$bNow, I know what yer thinkin\', "How is it possible that the Burnin\' Legion could capture a dwarf as mighty as ol\' Angus here."$b$bYe can rest easy knowin\' I let myself be captured. I\'m here to rescue a dear friend o\' mine, an\' gettin\' captured was the only way!$b$bI had the key in me pocket... but it musta\' fell out.$b$bIt\'s  errm... around here somewhere.$b$bA felhunter ate it a wee while back...', `QuestDescription`) WHERE `ID` = 41139;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Search and Rescue!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Brambley Morrison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve got to find Brambley before it\'s too late!$b$bOl\' Brambley an\' I have been fightin\' side by side since the Third War. When the Burnin\' Legion invaded, we didn\'t think twice about coming to the Broken Isles.$b$bFightin\' is what we do best!$b$bDuring the battle ol\' Brambley got caught too deep an\' got himself captured. Now we\'ve got to rescue him!$b$bLast I saw, the demons were keeping him in a prison cell not far from here... let\'s go!', `QuestDescription`) WHERE `ID` = 41140;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Conjuror\'s Duty', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map to choose your first zone.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I don\'t know about you but I\'m ready to get this show on the road. This place is nice and all, but it\'s a bit stuffy.nnI\'ll see what I can do to get some more mages in this group of yours. You go ahead and check the map over there. It\'ll help you plan your first moves.', `QuestDescription`) WHERE `ID` = 41141;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Suramar - Vignette: Khory - twh', `LogTitle`) WHERE `ID` = 41142;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mglrgrs Of Our Grmlgrlr', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '????', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mlrg...mglrmlr...$b$bGmlrgmlr mglrml gmlrg! Mlrgrlgr!$b$b<Mrgrglilgrl points at the trail of spiderwebs leading out of the ruin.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', '????', `AreaDescription`) WHERE `ID` = 41143;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the River', `LogTitle`) WHERE `ID` = 41144;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Water of Life', `LogTitle`) WHERE `ID` = 41145;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Elegant Design', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Convince Lady Anastae to give you the Gemcutter\'s Tome.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Amateur merchants complain about supply and demand. Masters create their own.$b$bYou have done well retrieving the last two pieces I requested, but they are baubles compared to this.$b$bYour target is the Lady Anastae, and she has something very valuable of mine: A design for a masterwork gem cut. $b$bGo and get it from her by any means necessary, but take care. She is a master manipulator and will tell you all manner of lies.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Convince Lady Anastae to give you the Gemcutter\'s Tome.', `AreaDescription`) WHERE `ID` = 41146;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dispensing Compassion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Offer Arcwine to suffering citizens.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is much you need to learn about our city.nnFirst and foremost, Arcwine. It is the vehicle by which we imbibe the Nightwell\'s energies. Without it, we wither and die.nnPalace lackeys have seen fit to ration it, thinking this will control us. Keep us quiet, complacent.nnI would like you to look for those in need near the tavern. You will find many, but those most desperately afflicted by this rationing will be obvious.nnTake this flask. Revive them. Tend to their suffering.', `QuestDescription`) WHERE `ID` = 41148;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Re-Warding Effort', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate $1oa Arcane Wards in Ambervale.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<This small device of elegant nightborne design crackles gently with arcane power.nnKel\'danath\'s notes mention wards that keep the withered at bay. It seems he found some form of spellcasting that does not tempt their ravenous appetite for magic.nnThese may prove useful in your search for the missing arcanist.>', `QuestDescription`) WHERE `ID` = 41149;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Revil Defeated', `LogTitle`) WHERE `ID` = 41153;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dark Riders', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Dark Riders in the Karazhan Catacombs and claim Ulthalesh.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There\'s a sewer grate along the edge of the river leading to catacombs underneath Karazhan. I\'ve never paid it much attention, but it could be where the spirits are directing us.nnTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.', `QuestDescription`) WHERE `ID` = 41155;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power Possessed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Calydus in The Underbelly in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our goals have been met, warlock, and it is time we part ways.  I think I will be glad to see the last of you.nnGo on, return to your dark masters. We are done here.', `QuestDescription`) WHERE `ID` = 41156;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Corrupted Studies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Survey digsites in Stormheim and bring Brann back $1oa War of the Ancients Fragments.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Stormheim is steeped with artifacts from tha War of the Ancients. Demon artifacts ta be exact.$b$bI think these artifacts can clue us into some knowledge about their leader, Sargeras. I\'ve already found some fragments to a titan disc, but need ta find the rest of \'em.$b$bI need ya ta dig around Stormheim and see if ye can find any more fragments so we can reassemble the disc.', `QuestDescription`) WHERE `ID` = 41157;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fragments of the Fjords', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Brann Bronzebeard in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, have you seen my ledger around here? I seemed to have misplaced it when I was stowing some canopic jars.$b$bOh, nevermind. Brann Bronzebeard has sent for you though. He\'s in Stormheim continuing his research.$b$bMake your way out to him and let him know I\'m still waiting on those flayed-skin chronicles he found.', `QuestDescription`) WHERE `ID` = 41158;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Process of Elimination', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Dig around Stormheim until you find a piece of the Titan Disc.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With so many places ta dig up fragments, it\'s become quite a pain figuring out where ta look for more of the titan disc.$b$bI have a plan though. I need ye ta eliminate potential areas where the disc could exist so we can narrow down where in Stormheim it might exist.$b$bYou take part of the area an\' I\'ll take the other part. Meet back here if ye find anythin\'.', `QuestDescription`) WHERE `ID` = 41159;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Earth to Earth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover a Cardinal Stone Core, a Cardinal Earth Core, and a Cardinal Lava Core for Lunelli. Bring them back to her in Shattrath when you have all three.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'From the earth comes strength, and such strength can be imbued into weapons of power.$b$bYou have the look of one who seeks to know how to create such weapons.$b$bThere are creatures that still inhabit this dying planet who bear such strength. Bring me their cores and I shall trade you the knowledge you seek.', `QuestDescription`) WHERE `ID` = 41160;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Out of the Frying Pan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Brann in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh hello, $n. I tell you, ever since I was given this shop, it\'s been nothing but a headache. I can\'t seem to ever find what I\'m looking for.$b$bWhich reminds me, Brann Bronzebeard has sent for you. He\'s in Azsuna tracking down more pieces of whatever it is he\'s searching for.$b$bNow where\'d those pewter drinking cups go...', `QuestDescription`) WHERE `ID` = 41161;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'And Into the Fel Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Survey digsites in Azsuna and find $1oa missing Parts of the Infernal Device and bring them back to Brann.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I found something, $n. Well, a couple of things actually.$b$bFirst I found an ancient text talking about a demon who harnessed the power of the titan disc I\'ve been searching for.$b$bThen I found a device which supposedly is used to summon \'im! Only, it\'s missin\' some pieces from what I can make out.$b$bI\'m sure if we survey around Azsuna some more, those missin\' pieces are sure ta turn up.', `QuestDescription`) WHERE `ID` = 41162;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Apocalypse Bringer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Brann when you\'re ready to activate the device.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Right, well, I managed to piece the device back together.$b$bI guess I\'ll jes\' turn it on when you\'re ready and we\'ll see what happens, yea?', `QuestDescription`) WHERE `ID` = 41163;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One Step Closer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Brann in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n! I just heard that Brann Bronzebeard - that crazy, titan-obsessed dwarf - has decided to go hunting for his precious disc in Suramar.$b$bTalk about the last place you\'d want to go digging around, given the current events.$b$bI\'m sure he could use your help.', `QuestDescription`) WHERE `ID` = 41164;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Deciphering Demonology', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Crate artifacts into $1oa Restored Artifacts and find $2oa Chamber Key Fragments and bring them to Brann.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I found a piece of what appears to be a key to something. I\'m certain I can restore it if we can find the other bits.$b$bAfter that, we need to figure out what it\'s a key to. An\' I think I know how to do that.$b$bI\'ve been studying some of the artifacts I\'ve found, and they seem to be pointing to a hidden chamber. I jes\' need some more artifacts to study.', `QuestDescription`) WHERE `ID` = 41165;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Secrets', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Brann at the entrance to the secret chamber. Once inside, stay close to Brann in case anything happens.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I fixed the key and am ready to open the chamber.$b$bMeet me there when you have a chance and we\'ll discover what waits inside together!', `QuestDescription`) WHERE `ID` = 41166;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel Fragments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the crate of surveying equipment to Brann in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Brann Bronzebeard has requested that I send him more surveying equipment, but I just don\'t have the time.$b$bWould you be a dear and take this crate to him, $n? I\'d truly appreciate it.', `QuestDescription`) WHERE `ID` = 41167;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Purple Hills of Mac\'Aree', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the remaining pages of The Purple Hills of Mac\'Aree and assemble them into the final book. Return the book to Brann when you have finished.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we\'re re-supplied, we can get back ta work.$b$bI found something here that I think ye\'ll be interested in. It\'s a page of a book talking about the world of Argus. But before the demons destroyed it.$b$bAnyway, it\'s been me experience that if ye find one of something, there\'s sure ta be more of it around.$b$bKeep lookin\' around Val\'sharah for more of these pages and bring what ye find back ta me. And take the page I found with ya so ye know what yer lookin\' fer.', `QuestDescription`) WHERE `ID` = 41168;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkheart Thicket: Through the Fog', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Final Chapter of The Purple Hills of Mac\'Aree.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can\'t believe that after all that searchin\' ye did, it\'s still missing a chapter!$b$bI\'m willin\' ta bet that those satyrs got a hand on it and took it somewhere. Probably somewhere dark where no one could find it.$b$bI\'ve heard rumors of a place, the Darkheart Thicket they call it, where the strongest of the satyrs are.$b$bIf I had ta guess, I\'d say ye need to go there and look around fer it.', `QuestDescription`) WHERE `ID` = 41169;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Relic Renewed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Observe Brann as he puts the Titan Disc back together.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Very good, very good! Now that we have all the pieces, it\'s time to put this disc back together!', `QuestDescription`) WHERE `ID` = 41170;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Reliquary Calls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Tae\'thelan Bloodwatcher in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tae\'thelan of the Reliquary has asked me to send anyone who may be able to help them in Azsuna.$b$bSeeing as how you happened into my shop purely by coincidence, I thought you\'d be willing to go, $n.$b$bBack to work for me though. So much to do and so little help.$b$b<Dariness lets out a sigh.>', `QuestDescription`) WHERE `ID` = 41171;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Echoes of My Ancestors', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete $1oa Highborne Archaeology Projects.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This land holds many secrets and many artifacts of ancient times.$b$bFrom what I\'ve been able to discern there\'s an artifact of great power close to here. I just need to narrow down its location.$b$bI\'d like you to dig up more artifacts and learn what you can. When you feel you\'ve done enough research, come back to me and share your knowledge.', `QuestDescription`) WHERE `ID` = 41172;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Beacon of Hope', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the location Tae\'thelan marked on your map and survey the area until you find the artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve marked the location of the artifact on your map. It\'s in a rather hostile location, so I\'d like you to go there and find it.$b$bWhen you\'ve recovered it, bring it back to me so I can discern its power.', `QuestDescription`) WHERE `ID` = 41173;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Worth Its Weight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Tae\'thelan in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, if you were a crate of black trilobites, where do you think I would have put you?$b$b<Dariness begins looking around the shop.>$b$bOh, that reminds me. Tae\'thelan has requested your presence. He\'s onto something in Suramar and needs your help.', `QuestDescription`) WHERE `ID` = 41174;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fit for an Elven Queen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Fight your way through Suramar into the chamber that holds the crown. Inspect the crown and report your findings back to Tae\'thelan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The nightborne have dropped their shield allowing us to penetrate their city and learn their secrets.$b$bOne such secret I\'ve discovered is a crown of immeasurable power.$b$bI\'d like you to find this crown and report back to me on what it does.', `QuestDescription`) WHERE `ID` = 41175;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sifting Through the Rubble', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Survey different areas around Suramar until you find the $1oa missing Jewels of the Crown.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Then I believe it\'s clear what we must do next. Find the jewels.$b$bThey\'re bound to be here somewhere in Suramar, so we better start looking.$b$bI\'ll coordinate the search from here, while you and my assistants look for the jewels.', `QuestDescription`) WHERE `ID` = 41176;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Goblin Archaeology', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Tae\'thelan in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m not sure if you\'re in on this, but the Reliquary has commissioned the goblins to help them with uncovering artifacts in this land.$b$bI\'d like you to go and see if there\'s any validity to this rumor... and I\'d also be interested to know the results.', `QuestDescription`) WHERE `ID` = 41177;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Explosive Results', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the goblin explosives to free $1oa Artifact Fragments from their geological prisons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you may or may not have heard, I\'ve been working with the goblins on using a new way of uncovering our artifacts.$b$bAnd if you know anything about goblins, you know that I\'m talking about explosives.$b$bWe\'ve only run a few tests here at my camp, but I would appreciate your help in testing this method out in the field.$b$bI\'ve marked a location on your map that has some particularly difficult digs.', `QuestDescription`) WHERE `ID` = 41178;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'What Once Was Lost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the location marked on the map and recover the artifact in question. Use the dynamite to uncover the artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That reminds me, I found a map to a chamber that may or may not hold something of value.$b$bIt doesn\'t seem to have any power associated with it, which is why I\'m handing it over to you.$b$bHere, take some more explosives. They may help speed of the process of finding it.', `QuestDescription`) WHERE `ID` = 41179;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unspeakable Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Tae\'thelan Bloodwatcher in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I received an urgent message from the High Examiner requesting your presence.$b$bHe\'s finally found something powerful-- VERY powerful--and he wants your help in recovering it.$b$bBe careful down there, $n. Tae\'thelan can be a tad fanatical when it comes to artifacts that hold any sort of energy.', `QuestDescription`) WHERE `ID` = 41180;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Narrowing Down', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Survey Suramar and uncover $1oa Tattered Highborne Scrolls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was right about the nightborne here having objects of great power. I found an ancient text referring to such an object called the Orb of Sciallax.$b$bFrom what I recall in studying the War of the Ancients, Sciallax was a demon lord who came to Suramar and offered the elves at the time a powerful artifact in return for their servitude to the Legion.$b$bI haven\'t discovered the exact location yet as to the whereabouts, but perhaps some digging can yield us an answer.', `QuestDescription`) WHERE `ID` = 41181;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Uncovering the Orb of Sciallax', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Tae\'thelan Bloodwatcher at the entrance to the chamber where the Orb of Sciallax is held. Once inside, set the charges on the casing and recover the artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ll need to hurry before the nightborne realize what we\'re after.$b$bI\'m bringing the goblins along in case we run into any obstacles along the way.$b$bI\'ve marked the location of the entrance to the chamber the Orb resides in on your map.$b$bMeet me there as soon as you\'re ready and we\'ll claim this artifact for our own.', `QuestDescription`) WHERE `ID` = 41182;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Academic Exploration', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Tae\'thelan in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, good to see you. What do you think of my shop so far? Not too bad for just one person, huh?$b$bBy the way, High Examiner Tae\'thalan has been digging around Azsuna, and asked that I send you to see him.$b$bKnowing him, he probably thinks he\'s found yet another world-shatteringly powerful artifact.', `QuestDescription`) WHERE `ID` = 41183;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tried and True', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the remaining $1oa Azsunian Key Mold Pieces and return them to Tae\'thelan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have realized through experience that the old methods are usually the best and for good reason. I\'m done with alternate means of digging for now, and wish to focus on the right way to do things.$b$bThat being said, I believe I\'ve found a new powerful artifact and I\'ll do literally anything to have it.$b$bI\'ve uncovered a fragment that appears to be a mold for a key. I now simply need the other pieces.', `QuestDescription`) WHERE `ID` = 41184;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Keys to Success', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the mold to Alard Schmied in Dalaran and have him help you forge a new set of keys. Return to Tae\'thelan when you have the finished set.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'d like you to take the mold to the blacksmith in Dalaran. Alard, I believe his name is.$b$bHave him help you forge a new set of keys.$b$bI found some writing on the back of the mold that may hold the answer to what these keys unlock. I\'ll stay here and try to translate the text.', `QuestDescription`) WHERE `ID` = 41185;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'History of Highmountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Lessah in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Let\'s see, one... two... three... oh, hello $n. Sorry I didn\'t see you come in.$b$bThings have been hectic around here. I could really use an assistant.$b$bI do have something for you though, a fellow archaeologist named Lessah has been asking for someone to help her in Highmountain.$b$bI thought you\'d be the perfect person for the job.', `QuestDescription`) WHERE `ID` = 41186;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Surveying Student', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 20 successful surveys with Luron present.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The reason I sent for someone was that I\'ve been having trouble keeping up with my research and training my assistant.$b$bI was hoping you might be able to show him the ropes again. Get him reacquainted with surveying.$b$bJust speak with him when you\'re ready to go.', `QuestDescription`) WHERE `ID` = 41187;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Neltharion\'s Lair: Misdirected', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Neltharion\'s Lair and recover the Ancient Highmountain Artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve been looking into the history of Huln Highmountain, a legendary warrior from the War of the Ancients whom this very land is named after.$b$bAllegedly some of his personal effects were carried here after his death and have been lost in time.$b$bAfter some digging around I believe I have discovered the location of one of his artifacts to be in a place called Neltharion\'s Lair.$b$bI\'m no fighter, $n, but you are. Will you go and recover this artifact for me?', `QuestDescription`) WHERE `ID` = 41188;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A New Lead', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Lessah in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Lessah in Highmountain has been asking for you.$b$bApparently she\'s caught a lead on some ancient piece of armor that Huln Highmountain used to wear.$b$bWhen you can, make your way out to her.', `QuestDescription`) WHERE `ID` = 41189;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crystal Eyes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interact with the two different resonating stones in Highmountain. Each stone requires 3 Highmountain Ritual-Stones to activate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve delved into the caves here and have discovered many ancient writings.$b$bThe most interesting I\'ve found are resonating crystals, where the drogbar have resided. Unfortunately, they aren\'t on very good terms with the tauren here and this has hindered my research.$b$bI thought, should there be any trouble with the drogbar, that you\'d be able to handle them.$b$bI\'d like you to continue my research and discover what you can about Huln.', `QuestDescription`) WHERE `ID` = 41190;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Drogbar Deception', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the ancient necklace and bring it back to Lessah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'According to my research and the information you gave me, I\'ve isolated the location of the necklace.$b$bIt\'s deep in a drogbar cave, and I\'m willing to bet they\'re not just going to hand it over to you, $n.$b$bI need you to recover that necklace at any cost.', `QuestDescription`) WHERE `ID` = 41191;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Right Path', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Lessah in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This new shop is shaping up quite nicely, I think. Still, there\'s so much left to organize.$b$b$n, Lessah has requested your presence in Highmountain. Something about a moose?$b$bI\'m not sure to what she\'s speaking of, but as soon as you have a chance, please go see her.', `QuestDescription`) WHERE `ID` = 41192;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Laying to Rest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find $1oa Bone Fragments of Eche\'ro and return them to Lessah in Highmountain. Then observe the burial ceremony Lessah performs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If I was able to find a bone fragment in what appeared to be a random location, then that means Eche\'ro\'s bones must be scattered around Highmountain.$b$bWe must find his remains and give him the proper burial he deserved.$b$bOh, I\'m sorry, in case you weren\'t aware, Eche\'ro was Huln Highmountain\'s mount and companion.$b$bHe deserves to be honored as Huln once was.', `QuestDescription`) WHERE `ID` = 41193;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Remulos Tracker', `LogTitle`) WHERE `ID` = 41194;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leystone Basilisks', `LogTitle`) WHERE `ID` = 41196;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'You\'ve Got to Be Kitten Me Right Meow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '"Herd" 7 Lost Feathermane Kittens back home.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you were dealing with the stray Owlkitten, I took a look around.nnIt seems these curious creatures have a habit of escaping their parents\' watchful eyes - some are trapped across the road by a wandering Ettin. nnHe appears to have been... ahem... eating them.nnWe can earn Yowlon\'s blessing by bringing his children home.', `QuestDescription`) WHERE `ID` = 41197;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leystone Basilisks', `LogTitle`) WHERE `ID` = 41198;
