UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Neltharion\'s Lair: Neltharion\'s Treasure', `LogTitle`) WHERE `ID` = 41211;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Artifact XP - Cho\'Zok', `LogTitle`) WHERE `ID` = 41213;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Parts Unknown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Brambley Morrison\'s remains.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Brambley... I still canna\' believe it.$b$bI canna\' leave the lad here... not in this place... not like this.$b$bHelp me find the rest of him, so I can take his remains back home where he belongs.$b$bWe\'ll give him a proper burial... it\'s what he deserves!', `QuestDescription`) WHERE `ID` = 41214;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'They Become The Hunted', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 6 Nightborne Trappers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The trapper you slew was but one of many.$b$bThe Nightborne are subjugating the local creatures, creating a sort of pleasurable exhibit. I think we can strike them in two places at once.$b$bDescend upon these trappers, $r. Let us teach them a lesson in respecting their prey.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Slay 6 Nightborne Trappers.', `AreaDescription`) WHERE `ID` = 41215;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Survival of the Fittest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free $1oa exhibits from the Menagerie.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The collar you took from the trapper is simple, but effective. Affixing the collar to a target will make them complacent and obedient to their Nightborne masters. Lilryia was able to reverse the spell using the traps you found.$b$bThe magics in the collar can now be used to cancel out the other collars.$b$bHow about giving the Nightborne a reminder that nature always finds a way?', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Free $1oa exhibits from the Menagerie.', `AreaDescription`) WHERE `ID` = 41216;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Future of Gnomeregan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Muffinus Chromebrew in New Tinkertown.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s a victory for us every time we\'re able to help another survivor escape from the contaminated halls of Gnomeregan. $Cs like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.$B$BMuffinus Chromebrew will help oversee your training and adjustment to life on the surface. He\'s waiting for you on the stands across the road.', `QuestDescription`) WHERE `ID` = 41217;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Meet the High Tinker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Introduce yourself to High Tinker Mekkatorque in New Tinkertown.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I don\'t know if you\'ll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.$B$BMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He\'ll be with his war council beneath the tent in the center of town.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Introduce yourself to High Tinker Mekkatorque in New Tinkertown.', `QuestCompletionLog`) WHERE `ID` = 41218;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Flourishing Foxflower', `LogTitle`) WHERE `ID` = 41219;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Down to Azsuna', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar to fly down to Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, we must find a way to reseal the Tomb of Sargeras.nnI have uncovered information concerning an ancient relic, which might be the key to stopping the Legion.nnOur search begins on the ancient elven island of Azsuna. Long ago, it was where the Highborne elves of Suramar perfected their mightiest of magics. Now it is a cursed ruin.nnThe Illidari demon hunters have established a camp on the island. As they are the only people we know in the area, that is where we will begin.nnReady to take wing?', `QuestDescription`) WHERE `ID` = 41220;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Mardum', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Illidari Gateway to board the Fel Hammer in Mardum.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The gateway is fully functional, $n. Ooh, I am positively tingling with excitement!$B$BDo let Jace and the others know that we eagerly await your arrival. There\'s so much to do and ever so little time.$B$BYou will be joining us aboard, won\'t you?', `QuestDescription`) WHERE `ID` = 41221;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into The Pit!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort Angus to Felmaw Cavern in Felsoul Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The felstalker pits?!$b$bThere\'s no time to waste, $n!$b$b I canna\' tell ye what the Burnin\' Legion has planned for ol\' Brambley, but it canna\' be good!$b$bHurry! We\'ve got to find him before the Burnin\' Legion has their way with him!', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Escort Angus to Felmaw Cavern in Felsoul Hold.', `AreaDescription`) WHERE `ID` = 41222;
