UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trapping Evolved', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Arcane Traps for Lilryia.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Nightborne are using magic for everything, even trapping.$b$bNighteyes saw them at work, laying down magical snares to capture prey rather than the kind our people use. $b$bBring me their traps so that I may study their make.', `QuestDescription`) WHERE `ID` = 41230;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Apex Predator', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and slay the Nightborne keeping Su\'esh obedient.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have good news and bad news, $r.$b$bThe bad news is that they somehow managed to capture and train a Devilsaur.$b$BThe good news is that it doesn\'t seem to have a collar and is tame. I imagine it must think that one of the Nightborne in there is its master. Find the pack leader and take him out, and we will set quite a beast upon them.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Find and slay the Nightborne keeping Su\'esh obedient.', `AreaDescription`) WHERE `ID` = 41231;
