UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sowing The Seed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Plant the Seed of Ages in the Soft Soil within The Dreamgrove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your weapon is ancient and powerful but it holds the potential to be so much more.$b$bTake this seed, it is all that remains of a forest that grew tall when the world was young. Plant it within the grove to the west and allow it to take root.$b$bWith its power both it and your weapon will be far more than they are alone.', `QuestDescription`) WHERE `ID` = 41255;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blast of Spice Fish', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Toad Gizzards for Keelay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have an ingredient that will make my fruit irresistible.$b$bNot many remember the delicacy of manatrout liquor. Its pungent aroma, the unctuous mouthfeel...$b$bThe toads near the northern river concentrate this additive in their gizzards. Fetch some stomachs for me, and we will have plenty.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect Toad Gizzards for Keelay.', `AreaDescription`) WHERE `ID` = 41256;
