UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'All That Glitters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve $1oa Arcane Glowlamps.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that the shield is down, the older settlements outside the city have been on my mind.$b$bDid you know that I helped create the filigree on the arcane lamps that are used throughout the city? A simple task, one of my first...$b$bNo matter. Nostalgia is the enemy of progress. The lamps are made of material better used in my new works.$b$bThose wretched harpies probably have several decorating their nests. Bring back any you find.', `QuestDescription`) WHERE `ID` = 41307;
