UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pry It From Their Cold, Feral Claws', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve 8 Harpy Necklaces for Lespin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The shield being lowered presents a unique opportunity for new styles.$b$bFeathers, bone and other primitive materials are suddenly fashionable again. Who would have thought they could grow tired of my masterpieces?$b$bVenture out of the city and collect necklaces from the harpies on the southern cliffs. Etching my mark into them should net me a tidy profit.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Retrieve 8 Harpy Necklaces for Lespin.', `AreaDescription`) WHERE `ID` = 41320;
