UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Elements Call...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Thrall and choose the Artifact you wish to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Nobundo is right. Conventional tactics will not work against the Legion - the Broken Shore taught us that. We must scour the world for weapons to use against the Legion!$b$bThe Doomhammer is missing and must be recovered. Rehgar and Erunak have some other ideas, as well. Whatever our course, we must act immediately.$b$bSpeak with me to go over your options, but the final decision is yours!', `QuestDescription`) WHERE `ID` = 41335;
