UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Timing Is Everything', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ride an Azuregale Paddlefoot and kill 50 Sashj\'tar naga using the Sealed Powder Kegs in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Can you feel it, $n? The waters churn with approaching Sashj\'tar.$B$BYou must strike now...$B$BLeave me... Find a way to bombard the naga... with the kegs...$B$BProtect... Jandvik...', `QuestDescription`) WHERE `ID` = 41409;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dry Powder', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 5 Sealed Powder Kegs from the shipwrecks in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n... I did not expect to see you down here.$B$BThe Sashj\'tar are... rallying against Jandvik. I had a plan to... decimate them using these old powder kegs.$B$BThe naga proved more formidable to these old bones than I thought.$B$B<Fjolrik coughs out some blood.>$B$BWe haven\'t much time... to prepare.', `QuestDescription`) WHERE `ID` = 41410;
