UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hunter\'s Call', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate leads on three artifact weapons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I realize we have never met, but you will learn of my order soon enough. For now, pleasantries must wait.$b$bThe Legion has returned to Azeroth stronger than ever, and we need new weapons to fight them.$b$bI have met three individuals here in Dalaran who have leads on ancient artifacts which could prove vital in the battle to come. Acquiring these weapons demands the skills of a master hunter.$b$bSpeak to each of them and decide whom you will aid first.', `QuestDescription`) WHERE `ID` = 41415;
