UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Necessary Preparations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Fill a cup with moonwell water and obtain Leafbeard the Storied\'s blessing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'G\'Hanir is... is...$B$B<Mylune wipes her eyes, sniffling.>$B$BCorrupted! The Nightmare has risen from the depths of the dream. It all happened so fast...$B$BI was able to secret the staff here through the dream before it fell fully. It rests for now... but I fear we don\'t have much time.$B$BYou must prepare to retrieve G\'Hanir from the Dream. Draw water from the sacred moonwell on the northern edge of the grove and obtain an ancient\'s blessing.$B$BQuickly - every moment is precious!', `QuestDescription`) WHERE `ID` = 41422;
