UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sunken Foes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 6 Sashj\'tar Overseers and 6 Trenchwalker Scavengers in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tidemistress... is filling her ranks with hulking naga... and sea giants.$B$BJandvik cannot withstand... their combined might.$B$BSlaughter them... before they reach its shores...', `QuestDescription`) WHERE `ID` = 41425;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Against Their Will', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Remove Writhing Willbreakers from 6 Possessed Vrykul in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When the naga brought me down here, I saw many of my vrykul mining the sea floor. They had... squids... attached to their faces.$B$BWhatever those things are, they must be controlling my kin and forcing them to work for the naga.$B$BI do not know what will happen if you remove the squids, but I would rather my vrykul die than be slaves to the naga.$B$BSee me in Jandvik when the deed is done.', `QuestDescription`) WHERE `ID` = 41426;
