UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In Deep Slumber', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Emerald Dream and retrieve G\'Hanir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This bed will be yours for the deep slumber that will usher you into the Dream.$B$BOnce you are comfortable, drink of the moonwater you brought. I will guide you from there.$B$BQuickly, now - with every passing moment G\'Hanir slips further into darkness.', `QuestDescription`) WHERE `ID` = 41436;
