UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Join the Dreamer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Naralex deep within the Tel\'Andu Barrow Den.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m afraid I can\'t really help you actually enter the Emerald Dream - we dryads merely shift our bodies between the planes.$B$BThat\'s ok, though - Naralex has offered to help!$B$BGo to the very bottom of the Tel\'Andu Barrow Den. Naralex is already there setting things up for you.', `QuestDescription`) WHERE `ID` = 41449;
