UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trouble Has Huge Feet', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Grotesque Ettin Leather to Mardranel Forestheart.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Ettin\'s hide bears many shallow scratch marks and bite scars. It seems he had been terrorizing the local Owlcats for quite some time.nnMardranel Forestheart would be interested in this.', `QuestDescription`) WHERE `ID` = 41462;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missing Along the Way', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Kalendros Irongrove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we retreated from Val\'Sharah, our company was briefly separated by a conflict with some satyrs at the border.nnOne of our own did not make it here- Mythandros\' brother, Kalendros. I would like you to try and find him if you could.nnSearch the woods just before the bridge back into Val\'Sharah.', `QuestDescription`) WHERE `ID` = 41463;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Not Here, Not Now, Not Ever', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Satyr Horns to destroy 3 Darkfiend Totems.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I cannot, will not, accept what is happening here. My body resists me, but I will stop this.nn<He looks at you.> You will stop this.nnHere is a root of the corrupted World Tree Shaladrassil. It has somehow found its way out of the ground to this untouched place and already the Darkfiend satyrs are hard at work corrupting Suramar.nnStop them. Kill the satyrs, take their horns, drive their points through the totems.nnOnly then can we have any hope of reversing this.', `QuestDescription`) WHERE `ID` = 41464;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Estate Jewelry: A Braggart\'s Brooch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve Lespin\'s Brooch from Naltethis Springblade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Amateur merchants worry about losing face from bad products. Masters worry about losing face from bad customers.$b$bNaltethis Springblade has grown too bold for his station, and as such has lost much standing in the eyes of the city\'s elite.$b$bI sold this man a brooch, a clasp he wears on his cape. I am careful to only sell to those above my station.$b$bMy pieces never tarnish, but my name and reputation are much more fragile. Relieve him of my property before he lowers me further.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Retrieve Lespin\'s Brooch from Naltethis Springblade.', `AreaDescription`) WHERE `ID` = 41465;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Estate Jewelry: Haute Claw-ture', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and retrieve Lespin\'s \'art\' from Mornath.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'An amateur merchant looks back on their previous work as a learning experience. A master knows that some things are better left forgotten.$b$bI was... vain, centuries ago. Desperate to prove myself, I took on a bold commission.$b$bFind him and bring... it... back. You will know what I am talking about when you see it.$b$bHe resides near the villa south of this courtyard.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Find and retrieve Lespin\'s \'art\' from Mornath.', `AreaDescription`) WHERE `ID` = 41466;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Only Choice We Can Make', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Incinerate the Shaladrassil Root.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Take this torch, $n. nnWe cannot reverse the Nightmare corruption once it has taken hold. All we can hope to do is destroy its manifestations.nnIncinerate the root. Only then can we rest easy in Suramar.', `QuestDescription`) WHERE `ID` = 41467;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mistress of the Claw', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Lea Stonepaw.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The great forest guardian, Ursoc, gave his life for this world ten thousand years ago. After the guardian\'s death his claws were hidden away, safe from any who would use their power for evil.$b$bLea Stonepaw and her Druids of the Claw consider Ursoc their paragon and dedicate their lives to following in his example. If anyone would know where the claws reside, it would be Lea.$b$bShe and her Druids of the Claw reside in the Tel\'Andu Barrow Den just to the north.', `QuestDescription`) WHERE `ID` = 41468;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Irongrove Retreat', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek Mythandros at Irongrove Retreat.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have three blessings from the creatures we share this land with.nnCombined with a blessing from Elune, the moonwell will watch over this land for years to come.nnMeet Mythandros at the retreat. I am sure he would like to include you in the ritual.', `QuestDescription`) WHERE `ID` = 41469;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Redhoof the Ancient', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Mythandros and Redhoof the Ancient.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you were busy assisting the Owlcats across the river, Mythandros and Solendra ventured further to the east.nnI believe Mythandros may have found the next creature that may offer us its blessing.nnThere is a secluded glade along the river\'s bend to the Northeast. There you may find our new ally, an elderly stag named Redhoof.', `QuestDescription`) WHERE `ID` = 41473;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fertilizing the Future', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Plant 5 Lush Grass Seeds in piles of Rich Soil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Like most herbivores, our antlered friends will eat anything green enough to chew. nnHowever I have noticed that they seek these patches of dark grass, given their preference. I believe we can begin to earn their favor if we aid the forest in producing more of this most nutritious of stag food.nnI will provide you with the seeds- all you must do is locate suitable growing soil and plant them. Our magic will do the rest.', `QuestDescription`) WHERE `ID` = 41474;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prongs and Fangs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 8 Suramar Snarlers and Gloomfang.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now, $n, do not mistake me- I am a druid. I understand that nature has a balance.nnPredators must feed, and others will be hunted. I also understand that tampering with such balance has consequences.nnThat is why I have taken upon myself to walk this land and perform some... ah... calculations.nnSlay only a small number of the wolves you find, and one alpha. That should reduce their number enough to allow the Sablehorn to thrive without disrupting the flow of things here.', `QuestDescription`) WHERE `ID` = 41475;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Final Blessing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Solendra Featherdown.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My friend Solendra Featherdown went to explore the habitat of the native Nightsabers. nnNow that we have the blessings of the Feathermane and the Sablehorn it is time to seek the blessing of the Nightsabers. She is just on the other side of this glade, to the North.', `QuestDescription`) WHERE `ID` = 41478;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Natural Adversaries', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 8 Manascale Basilisks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have walked this land in the time since our arrival. Here, basilisks have emerged from the ravines to the east. They encroach upon the home of the Nightsabers.nnTo earn their blessing, I believe we should clear the way for their return.nnSlay the basilisks that have taken more than their fair share of the land, $r.', `QuestDescription`) WHERE `ID` = 41479;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Managazer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Managazer, the Basilisk Lord.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is one basilisk here who has gorged himself so thoroughly on Nightsaber flesh that he seldom leaves his cave.nnWe will use this to our advantage.nnSeek out the basilisk Managazer and use his death as an example to the others who have strayed from their home.', `QuestDescription`) WHERE `ID` = 41480;
