UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moonwhisper Rescue', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free 5 Petrified Nightsabers using Solendra\'s Gift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As a druid I understand that predation happens. Creatures that eat meat must acquire meat.nnBut this...nn<Solendra gestures angrily toward a nearby petrified nightsaber.>nnThis is just sad. Free them, $r. Take my blessing and free them from this needless torment.', `QuestDescription`) WHERE `ID` = 41485;
