UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azeroth Needs You', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your first assault point on the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We shaman under your command will aid your efforts against the Legion. You may direct our actions from here.$b$bSeek out Advisor Sevel just to the south and locate the scouting map from which you can direct your followers. We will also indicate on the scouting map various hot-spots around the Broken Isles that require your attention.$b$bAzeroth needs you, Farseer! Visit the scouting map and choose our first point of attack.', `QuestDescription`) WHERE `ID` = 41510;
