UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rendezvous with the Courier', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Courier Larkspur at Krasus\' Landing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thas\'dorah is a mighty bow indeed! The weapon was carved from a limb of Thas\'alah, the mother tree of Eversong, and infused with the magic of the Sunwell. I fought alongside its first wielder, Talanas Windrunner, during an Amani troll incursion.$b$bAh, but such tales can wait for another time.$b$bCourier Larkspear was making preparations to depart. You can meet him at Krasus\' Landing.', `QuestDescription`) WHERE `ID` = 41540;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Beastly Expedition', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Grif Wildheart at Krasus\' Landing in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know the power of Titanstrike well. The Unseen Path battled the vrykul warlord Volund as he campaigned to conquer the Broken Isles. We sought to wrest the rifle from him, but he took it to his grave.$b$bIf Volund\'s tomb can at last be opened, the artifact would be a great boon to our cause.$b$bI believe Grif Wildheart is making preparations to depart. You can meet him at Krasus\' Landing.', `QuestDescription`) WHERE `ID` = 41541;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Preparation for the Hunt', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Apata Highmountain at Krasus\' Landing in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Talonclaw is a mighty spear indeed! I first set eyes upon it when the Highmountain tauren led the members of my order up to Talon Peak to found the Trueshot Lodge.$b$bBut such tales must wait for another time.$b$bApata has been in Dalaran gathering supplies for her expedition. I imagine she\'s ready to depart by now.$b$bSeek her out at Krasus\' Landing. I know she will be eager to begin.', `QuestDescription`) WHERE `ID` = 41542;
