UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stolen Thunder', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Accompany Grif Wildheart to Shield\'s Rest Island and track down Titanstrike.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Titanstrike is in the tomb of Warlord Volund somewhere on the isle of Shield\'s Rest. It\'s a dank, sloppy mess adrift in a sea of gloom.$B$BSounds lovely, eh?$B$BI\'ve been workin\' with a vrykul guide named Prustaga. She\'ll help us break the wards keepin\' the tomb sealed.$B$BI know what you\'re thinkin\'... vrykul are trouble. But she hasn\'t taken a swing at me just yet.$B$BHuey\'ll take us down to the shore. Prustaga\'s probably found the tomb by now!', `QuestDescription`) WHERE `ID` = 41574;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felsoul Teleporter Online!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infuse the Beacon with Ancient Mana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Obtain 5 Mana Saber Hides for Lady Anastae.', `AreaDescription`) WHERE `ID` = 41575;
