UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Finding Brytag', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Brytag in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Kell barely manages to speak.>$B$BThat naga witch... has given many of my kin... to the sea giants.$B$BBrytag was... the last one I saw alive.$B$BFind him quickly.', `QuestDescription`) WHERE `ID` = 41606;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Taking a Promenade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate the scouts in the Promenade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must learn much about our long-lost kin if we are to fight them.$b$bWe dispatched one of our scouts to infiltrate the Promenade and gather intelligence. The Sentinels sent their own scout as well, hopefully she is smart enough to not get herself killed before reporting in.$b$bThey have not returned in some time, and we must suspect the worst.$b$bFind them and we shall see what we are up against.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Locate the scouts in the Promenade.', `AreaDescription`) WHERE `ID` = 41607;
