UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Seawarden', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Seawarden Largush in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Seawarden made a deal with the Tidemistress. She handed us over to him like cattle.$B$BI despise that sea giant! If I were not trapped in this bubble, I would choke the life out of him with my own two hands.$B$BIf you cross his path before I get out of here, make him regret ever making a deal with the naga!', `QuestDescription`) WHERE `ID` = 41618;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crawliac\'s Legacy', `LogTitle`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '[ph] Defend the bluffs!', `QuestDescription`) WHERE `ID` = 41622;
