UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rocko Needs a Shave', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Rocko in a pet battle.', `LogDescription`) WHERE `ID` = 41624;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Light\'s Wrath', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Kalec at the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Light\'s Wrath... a bold choice. Though if you believe you can control its energies, it could prove vital to our cause.nnRetrieving it won\'t be easy. It was last held by the Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it.nnThe dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.', `QuestDescription`) WHERE `ID` = 41625;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A New Threat', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the Azure Dragonshrine for clues regarding the current state of the Nexus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you seek the Nexus, I would warn not to rush headlong. There are strange happenings in Coldarra, and it would be best to gather some information before proceeding.nnDuring my last visit to the Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was very closely tied to Malygos\' plans during the Nexus Wars, whatever is present there may explain the current state of the Nexus.nnI cannot accompany you, but this crystal can be used to communicate with me. Good luck.', `QuestDescription`) WHERE `ID` = 41626;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Forgotten Enemy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the Ethereal Communication Device at the Azure Dragonshrine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The device still hums with power. It must have been abandoned not long ago.nnThe nearby switch appears to activate it.', `QuestDescription`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Image of Kalec', `PortraitTurnInName`) WHERE `ID` = 41627;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eyes of the Dragon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Scout out the key locations in Coldarra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You should travel at once to Coldarra in Borean Tundra, $n. There, I would recommend you scout out a few key locations and report back to me. nnI know the area well, and should be able to tell you how to proceed.nnMake haste!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Image of Kalec', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Image of Kalecgos', `PortraitTurnInName`) WHERE `ID` = 41628;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Harnessing the Holy Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Empower yourself with Unstable Holy Energy by defeating Wraths of the Light or siphoning from Breaches of Holy Energy around the foundation of the Nexus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The energy from Light\'s Wrath lashes out from within the weakened Nexus Vault.  We may be able to use this raw, chaotic energy to our advantage.nnIf we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Image of Kalec', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Image of Kalec', `PortraitTurnInName`) WHERE `ID` = 41629;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unleashing Judgment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your built up Unstable Holy Energy to destroy the Surge Needles in Coldarra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have the power you need to destroy the Surge Needles. nnAt the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Light\'s Wrath into these points of focused void, and the reaction should cause an overload, destroying the Surge Needle above.nnYou must act quickly. The Ethereum likely won\'t sit idly by as you lay waste to their machinations.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Image of Kalec', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Image of Kalec', `PortraitTurnInName`) WHERE `ID` = 41630;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nexus Vault', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Nexus-Prince Bilaal and claim Light\'s Wrath.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. nnWe have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Light\'s Wrath, I would ask that you also free my brother from their grip.nnWith the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, $n.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Image of Kalec', `PortraitGiverName`) WHERE `ID` = 41631;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Gift of Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Alonsus Faol.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have done a great thing for the blue dragons today, $n, as well as for my own peace of mind.nnNow, armed with Light\'s Wrath, I only ask that you fulfill your original goal, and take the fight to the Legion.nnI believe Alonsus Faol awaits your return. Safe travels, friend.', `QuestDescription`) WHERE `ID` = 41632;
