UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cleansing the Mother Tree', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Dreamway to travel to Mount Hyjal, then cleanse G\'Hanir in the sacred waters beneath Nordrassil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must save the Mother Tree at all costs.$B$BI believe I know a way.$B$BThe world tree Nordrassil, atop Mount Hyjal, was born from an acorn of G\'Hanir. We can use the sacred waters surrounding its roots to purify the corruption.$B$BIf we take the Dreamway to Mount Hyjal\'s summit we should have enough time to complete the cleansing ritual before G\'Hanir falls completely to the darkness.', `QuestDescription`) WHERE `ID` = 41689;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Reconvene', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Lyessa Bloomwatcher at the Circle of Spirits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You found Lyessa in the Dream, didn\'t you, Shan\'do $n? I heard you mutter her name in your slumber.$B$BThank Elune she is well.$B$BYou must seek her out - I can sense her presence even now at the Circle of Spirits above.$B$BIf ever there were one who could help us cleanse G\'Hanir, it is Lyessa.', `QuestDescription`) WHERE `ID` = 41690;
