UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Written in Stone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Spellstone of Kel\'danath.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<You bundle the notes and store them away in your pack.nnAccording to his final journal entry, Kel\'danath used something called a "spellstone" in his experiments.nnThe spellstone, if not the arcanist himself, must be nearby.>', `QuestDescription`) WHERE `ID` = 41702;
