UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Subject 16', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Theryn to Thalyssra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<It seems Theryn is still under the arcanist\'s spell. In the absence of Kel\'danath himself, a live subject could be useful in helping Thalyssra unravel his research.>', `QuestDescription`) WHERE `ID` = 41704;
