UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wormtalon Wreckage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 15 Wormtalon Harpies in Shadowfen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As if Shaladrassil\'s encroaching roots were not enough to deal with, now the Wormtalon harpies have come to take advantage of our plight. $b$bKill them, $r. They deserve nothing less for feeding on our misery.', `QuestDescription`) WHERE `ID` = 41707;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Side of the Moon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Protect Tyrande while she holds her vigil at the Ancient Moonwell.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Xavius led Ysera past here, but their destination is unclear. This twisted wickedness smothers my mind!$b$bThese refugees tell of an ancient Moonwell hidden in the ruins of their home. If it somehow resisted this corruption...$b$bI will beg of Elune a vision to give me direction. With her light, I may find my husband yet.', `QuestDescription`) WHERE `ID` = 41708;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Breaking Down the Big Guns', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 50 Harpoon Parts from Sashj\'tar Harpooners in Azuregale Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You did well against that sea witch, but not well enough.$B$BHer power far surpasses any creature that I have ever fought. To defeat her, we will need something formidable. Something that she will not expect...$B$B<Toryl grins wryly.>$B$BSomething of their own design... $B$BSalvage as many parts from their harpoon launchers as you can carry and meet me back in Jandvik.', `QuestDescription`) WHERE `ID` = 41709;
