UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Heart of the Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Track Malfurion\'s path through the Nightmare.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know only that my husband is somewhere deeper in this twisted forest. He is still alive, but it remains to be seen if he is whole.nn<Tyrande\'s expression hardens into a scowl.>nnElune herself cannot protect Xavius if he is not.', `QuestDescription`) WHERE `ID` = 41724;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Defense of Tian Monastery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Jade Forest on Pandaria, then speak to Taran Zhu at Tian Monastery. Speak to Tak-Tak west of the Temple of Five Dawns to fly there.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Chen\'s recent report indicates that Tian Monastery is under attack!$B$B$n, they need your help. Go speak to Tak-Tak west of the main temple. He can get you there quickly.', `QuestDescription`) WHERE `ID` = 41728;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Slowing the Spread', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy 3 Fel Spreaders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Reinforcements. Just what we needed! Grandmaster, the monastery is under attack.$B$BThe Legion is using a foul device known as a Fel Spreader to scorch the very earth we walk on with disgusting fel energy.$B$BDestroy those machines, and we can slow their efforts.', `QuestDescription`) WHERE `ID` = 41729;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Desperate Strike', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 20 demon attackers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Good, your timing couldn\'t have been better, $n.$B$BThese foul Legion creatures have invaded our sanctuary. They have no place here on our world.$B$BKill every demon you see, $Gbrother:sister;.', `QuestDescription`) WHERE `ID` = 41730;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Storm, Earth, and Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy 5 Fel Spikes, put out 5 Fel Fires, and destroy 5 Tainted Ale barrels.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tian Monastery is in bad shape.$B$BFelspreader imps are torching the grounds. Fel spikes radiate foul energy, corrupting the nearby earth. And fel magic has seeped into the monastery\'s ale barrels, tainting the brew.$B$BUse your abilities to snuff the flames, shatter the spikes, and destroy the tainted barrels.$B$BSigh... hundreds of years of the finest ale... ruined.$B$BI don\'t wish to hear any more of it. Just get it done.', `QuestDescription`) WHERE `ID` = 41731;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hand of Keletress', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Skola Greatsword.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demons\' leader is up ahead, taking prisoners it is said!$B$BThis dire storm, we will weather... if we fight her together!', `QuestDescription`) WHERE `ID` = 41732;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rebuilding the Order', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Iron-Body Ponshu at the Wandering Isle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'On behalf of all the students and teachers here at Tian Monastery, thank you, Grandmaster $n.$B$BYou have a difficult task ahead of you to rebuild our order, but we stand with you.$B$BLet us head back to the Wandering Isle.', `QuestDescription`) WHERE `ID` = 41733;
