UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tech It Up A Notch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Journeyman Goldmine at the Heart of Azeroth in the Maelstrom.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There are many ways to commune with the elements. In their ingenuity, the goblins have found ways to imbue their mechanical devices with the energy of elemental spirits. I do not pretend to understand. But in our hour of need, we should not hesitate to embrace a diversity of options.$b$bWe are fortunate to have at our disposal the services of the one they call "Goldmine," whose unorthodox research may significantly augment our power. He waits nearby.', `QuestDescription`) WHERE `ID` = 41740;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Troops in the Field', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Troops in the Field."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time for us to test the strength of your newly summoned Lesser Elementals. Look at the Scouting Map and send your champions and troops on a routine scouting mission.', `QuestDescription`) WHERE `ID` = 41741;
