UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Given to Corruption', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Keeper Varethos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A final favor for an old friend, perhaps? My age-old companion, Varethos, has fallen to the nightmare\'s torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour.$b$bAs with all who suffer this fate, there is no restoring him.$b$bPlease, $n, bring him peace.', `QuestDescription`) WHERE `ID` = 41749;
