UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Unlikely Ally', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Kira Iresoul in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Channeling the demonic gateway will require the assistance of someone with intimate knowledge of the Burning Legion.nnI know of such a warlock, though I imagine her blood still boils upon hearing my name. It might be best if you are the one to request her help.', `QuestDescription`) WHERE `ID` = 41759;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Kel\'danath\'s Legacy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Spellstone of Kel\'danath to charm 5 withered and send them to Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Kel\'danath discovered something incredible - the power to subdue and even control the withered.nnI will pick up where my old friend left off. We shall see to it that he did not die in vain. nnPerhaps in the end we can even find peace for the wretches who have been left to a fate worse than death.nnI will need more subjects. Take Kel\'danath\'s spellstone and use it to subdue more withered.', `QuestDescription`) WHERE `ID` = 41760;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Winter Moose Roundup', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue 4 Talbuk at Kuuros Farm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My father, Karmaan, owns this farm, and our main livestock are talbuk. One of the podlings must have opened the gate to their pen and they all escaped!$B$BThe little terrors could have slaughtered them in the cage, but they like to hunt their prey. I\'m afraid that if I stay out here much longer, I\'ll be their next meal!$B$BWill you round up the talbuk and bring them here? I can\'t get them myself, and I can\'t let my dad find out about this!', `QuestDescription`) WHERE `ID` = 41761;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sympathizers Among the Shal\'dorei', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Silgryn in the Suramar Outskirts.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Elisande\'s decision to welcome the Legion into Suramar earned her plenty of enemies, though only some of us were bold enough to openly defy her.$B$BWe have allies in the city - we just don\'t know how many.$B$BI need you to make contact with a spell-fencer by the name of Silgryn. He is loyal to our cause, and has been lying in wait since our failed coup.$B$BHe patrols the western edge of the city. Address him by name and tell him our cause is not lost!', `QuestDescription`) WHERE `ID` = 41762;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Close Enough to Touch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search for Malfurion within Shala\'nir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'He is near, $r, I can feel it.$b$bWe must search Shala\'nir for Malfurion. If we do not find him soon, I fear he will be lost to me forever.$b$bI was unsure of your worth when first we met. I know now that you will not fail me.$b$bI am... grateful.', `QuestDescription`) WHERE `ID` = 41763;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wildlife Protection Force', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Rocko in a pet battle.', `LogDescription`) WHERE `ID` = 41766;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Daring Rescue', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the demon world and rescue the missing council members.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The plan is a simple one, but it will require great effort on your part.nnKira and I will summon the demonic gateway, but you will have to enter alone and recover the missing council members.', `QuestDescription`) WHERE `ID` = 41767;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Soul Beacon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Perform a ritual of summoning to retrieve the missing council member.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have bound Shinfel\'s soul to her staff, allowing it to serve as an anchor in this world.nnWhen we perform the ritual of summoning, it will act as a beacon, guiding Shinfel through the Twisting Nether and back to our world.', `QuestDescription`) WHERE `ID` = 41768;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mad Ernie the Alchemist', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Mad Ernie the Alchemist in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If we have any hope of curing this curse, we need to know what kind of magic we\'re dealing with.nnI know of an alchemist who earned himself quite the reputation for his unconventional methods. Shunned from Gilneas long ago, I believe Mad Ernie has taken up residence in these lands.nnHis knowledge may be the first step to breaking this curse.', `QuestDescription`) WHERE `ID` = 41769;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Skies Above', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Celestos in The Vortex Pinnacle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There has been no Windlord to lead the air elementals since the death of Al\'Akir.$b$bThe realm of Skywall has been thrown into turmoil. The throne of Al\'Akir is Thunderaan\'s by right, but what remains of the prince\'s essence within Thunderfury is diminishing. If we do not move quickly, Thunderaan may be lost forever.$b$bTake the damaged Thunderfury to Vortex Pinnacle and speak with Celestos.$b$bCelestos was a loyal servant of Al\'Akir and he will share our desire to see Thunderaan reborn.', `QuestDescription`) WHERE `ID` = 41770;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recharging the Blade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Heart of Skywall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have recovered the Blessed Blade of the Windseeker, and with it you hold all that is left of the soul of Prince Thunderaan.$b$bThunderfury can be restored, but it will require a rare essence known as the Heart of Skywall.$b$bVortos, the Duke of the East Winds, possesses the heart... but he will not give it willingly.$b$bVortos must be defeated, and the Heart of Skywall must be combined with the blade.$b$bOnly then can Thunderaan return and claim the Throne of Four Winds.', `QuestDescription`) WHERE `ID` = 41771;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ascendant of Flames', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Rehgar Earthfury in the Firelands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we speak, an endless war rages for control of the Firelands. Of the two aspiring Firelords, Lord Smolderon hates mortals less.$b$bIf we help him defeat his rival and ascend to Firelord, he may unite with us in return.$b$bThe champions of the Earthen Ring have already made their way to the Firelands. Go and meet with Rehgar Earthfury and find a way to turn an old enemy into a new ally.$b$bIf anyone can succeed at this impossible task, I have faith that it is you, Farseer.$b$bMay the elements be with you.', `QuestDescription`) WHERE `ID` = 41772;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Firelord\'s Command', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the forces of Pyroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, mortal. I am Scaldius, emissary of Lord Smolderon.$b$bI have just met with others from your order. They tell me that you will bring an end to those who oppose my master. This pleases Lord Smolderon.$b$bPyroth and his minions defy my master\'s rule and so an example must be made of them. You will slay Pyroth and his champions!$b$bNothing is more humiliating than death at the hands of a mortal. Do this and Lord Smolderon will grant you audience.', `QuestDescription`) WHERE `ID` = 41773;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Great Stonemother', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Therazane in Deepholm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to unite the four Elemental Lords of Azeroth, you will need to seek out Therazane and convince her to join the cause of Azeroth.$b$bHowever, the Stonemother currently has her hands full battling a Twilight\'s Hammer resurgence in Deepholm.$b$bIf we lend Therazane our aid she may agree to unite with the Earthen Ring against the Burning Legion.$b$bJourney to Therazane\'s Throne in the heart of Deepholm. Aid her in defeating the Twilight\'s Hammer and convince her to join the defense of Azeroth!', `QuestDescription`) WHERE `ID` = 41775;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return of the Windlord', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Summon Prince Thunderaan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With Thunderfury recharged, Prince Thunderaan can now return to the physical realm.$b$bIn a moment, I will release my master\'s spirit from the blessed blade.$b$bWhen the ritual is complete, Skywall will once again have its Windlord.', `QuestDescription`) WHERE `ID` = 41776;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Destroying the Cult', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 15 Twilight\'s Hammer cultists at The Twilight Throne.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are all that stands between the Twilight\'s Hammer and their conquest of Deepholm.$b$bAzeroth cannot hope to fight the full strength of the Twilight\'s Hammer and the Burning Legion at the same time. It is up to us to put an end to their cult before they are able to fully rebuild.$b$bAccompany me into their stronghold and we shall cut through their ranks together!', `QuestDescription`) WHERE `ID` = 41777;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Firing Up the Forge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Obliterum Forge to obliterate Archmage Karlain\'s Imbued Silkweave Robes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Are you familiar with the Obliterum Forge? It can be used to destroy crafted gear, yielding valuable Obliterum. I\'m personally quite curious to see it in action.$b$bOne of my many admirers recently gifted me a set of adventuring robes, but I\'m afraid they\'re not quite my style.$b$bPlace them inside the forge and see what happens.', `QuestDescription`) WHERE `ID` = 41778;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Doom and Gloom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the ingredients Ernest needs to create an Elixir of Suspension.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Doom curses are serious business, so much so that many warlocks didn\'t deal in them for some time. nnThe magic grows stronger as time goes on, eventually leading to death. Only the caster of the curse can remove it.nnI can craft an elixir that will slow its progression, but you\'ll need to collect an assortment of ingredients first.', `QuestDescription`) WHERE `ID` = 41780;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Herding Goats', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Catch Greyhorn Goats, then return them to their pen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In case you haven\'t noticed, things are a bit hectic around here.nnMarl\'s doing a good job protecting the corn fields, but the commotion gave our goats quite the scare. They dashed out of their pen as soon as the fighting started, and are now running amuck!nnRound them up for me and I\'ll do my best to figure out how to handle the curse you\'re dealing with.', `QuestDescription`) WHERE `ID` = 41781;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To The Hills', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Fill a Vial of Moonwell Water and locate Lea Stonepaw within Grizzly Hills.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is said that a fragment of Ursoc\'s spirit, his fury and rage, remained within the claws after his death. Only those who have attained mastery of discipline have any hope of wielding them without being overwhelmed by the bear lord\'s fury.$b$b<Lea looks intently at you for a moment.>$b$bBut you are no novice, I can see that clearly.$b$bVery well, draw water from the moonwell on the northern edge of the grove then come find me. I\'ll await your arrival within the broken stump of Vordrassil in Northrend.', `QuestDescription`) WHERE `ID` = 41782;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fallen Offerings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the bodies of Frostpaw Shaman for Offerings to Ursol and return them to Lea Stonepaw within Grizzlemaw', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When the claws were sealed away, magical wards were placed to prevent anyone from reaching their location. Only the power of a demigod can give us passage through the wards, one such as Ursol, the brother of Ursoc.$b$bUrsol is a reclusive guardian and requires an offering before he will appear to us.$b$blike Ursoc, he was worshipped by the furbolg, but years of war have decimated their tribes and their shaman lay dead.$b$bSearch the bodies of the fallen for their offerings while I prepare the shrine.', `QuestDescription`) WHERE `ID` = 41783;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Borrowed Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Give the Elixir of Suspension to Shinfel Blightsworn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Don\'t let the aroma deceive you, this concoction is mostly safe for consumption.nnWhoever is afflicted should drink the entire contents of the vial, every last drop! If the elixir works, the effects should be immediate. If not, well... just tell them they drink at their own risk, alright?nnKeep in mind, this will only weaken the curse, not cure it.', `QuestDescription`) WHERE `ID` = 41784;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Finding Fizzlebang', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Lulubelle Fizzlebang in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have reason to believe that Wilfred Fizzlebang\'s sister has made her way to Stormheim.nnIf she has half his power, but at least twice his intelligence, then we just might succeed in summoning the eredar twins.', `QuestDescription`) WHERE `ID` = 41785;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Suramar - Vignette: Sea Giant King - twh', `LogTitle`) WHERE `ID` = 41786;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Someone Else\'s Mess', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Banish demons that have been irresponsibly summoned in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A confession alone won\'t be enough to clear my name. As long as those demons run amuck, people will blame their presence on me. nnSomeone needs to clean up the mess that warlock made. I\'d do it myself, but I can\'t be placed at the scene of the crime.nnYou could banish them though. That would do the trick. Use this orb on newly summoned demons to send them right back where they came from - permanently!', `QuestDescription`) WHERE `ID` = 41787;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Coercing a Confession', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the warlock that has been irresponsibly summoning demons and obtain a written confession of his wrongdoings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My location has to be kept secret, at least until I have proof of my innocence.nnThanks to the legacy of my family name, any time some miserable warlock summons demons they can\'t control, I get the blame.nnThe scene of my latest "crime" is a nearby cave, where unruly imps and other nasty demons are roaming free.nnFind the lousy warlock who\'s responsible, and get him to write a confession.', `QuestDescription`) WHERE `ID` = 41788;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Crag', `LogTitle`) WHERE `ID` = 41789;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The First Trial of Ursol', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the first of Ursol\'s trials.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion...$b$b<the glow of Ursol\'s eyes begin to shine intensely>$b$bYes... I remember clearly that day long ago when my brother fell. Countless demons fell beneath his claws until, through the overwhelming numbers of the enemy, he was overtaken. My brother was the true spirit of the bear!$b$bYou must prove to me that the spirit of the bear resides within you as well.', `QuestDescription`) WHERE `ID` = 41790;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Second Trial of Ursol', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the second of Ursol\'s trials.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ursoc never backed down from a battle, even when faced with overwhelming odds. If you would take up his claws you will show me that you possess the same courage.$b$bYour next trial will place you against an onslaught of my followers. Defeat all of the spirits and prove that you possess the courage of the bear!', `QuestDescription`) WHERE `ID` = 41791;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Third Trial of Ursol', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the third of Ursol\'s trials.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve proven to me your strength and your courage, but do you possess the ability to apply yourself when it matters most?$b$bThis final trial will reveal all.', `QuestDescription`) WHERE `ID` = 41792;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lulubelle on Loan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Ritssyn Flamescowl.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What you plan to do is pretty risky, you know? Summoning one sister would be difficult enough, but both of them at once? That\'s just asking for trouble.nnLuckily, I\'m up for the challenge. I\'ll help you and the rest of the council summon those demons, and hopefully restore pride to the Fizzlebang name.', `QuestDescription`) WHERE `ID` = 41793;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Drakestalker', `LogTitle`) WHERE `ID` = 41794;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Summoning the Sisters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel through the Demonic Gateway to reach the summoning platform and use the Bloodstone to subdue the eredar sisters once the summoning is complete.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It would be best to conduct the summoning on the outskirts of Dreadscar Rift. If things do not go as planned, at least the aftermath will be contained to a small island of land that floats above our order.$B$BOnce the sisters have been summoned, use the Bloodstone to enslave them.$B$BI\'ll let the others know it\'s time to begin.', `QuestDescription`) WHERE `ID` = 41795;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Selecting a Sixth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose who will become the final member of the council.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the demon sisters under your control, you have managed to weaken Mephistroth\'s army and gain powerful allies for the council.nnOur work is not done, however. Dreadscar Rift will remain a target as long as the Burning Legion remains.nnIf we wish to protect our new home, we must rebuild the council. Both Lulubelle and Kira have proven themselves worthy to join our ranks, though only one spot remains.nnAs First of the Black Harvest, the choice is yours.', `QuestDescription`) WHERE `ID` = 41796;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting The Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Imp Mother Dyala and train a Pack of Imps.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As her name suggests, Imp Mother Dyala is adept at summoning imps.nnWhile the council controls Dreadscar Rift, her services will be ours to use as we see fit.nnSpeak to her if you wish to train a pack of imps.', `QuestDescription`) WHERE `ID` = 41797;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting More Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Recruiter Jared.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As First of the council, you have acolytes devoted to helping any way they can. Recruiter Jared is in charge of screening candidates, only selecting those that possess the skills we desire.$B$BSpeak to him now.', `QuestDescription`) WHERE `ID` = 41798;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Gates of Valor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Chipped Titan Disc Fragments by surveying near the Gates of Valor in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ye\'d not normally know it, but the terraced entrance to the vrykul\'s Halls o\' Valor is a fine place for findin\' ancient artifacts. Problem is, the place is just a big mess with demons at the time.$b$bWell, ye\'ve not got much choice. If the disc isn\'t elsewhere in Stormheim, it most likely lies at the Gates of Valor. Good luck, $n.', `QuestDescription`) WHERE `ID` = 41802;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Asking a Favor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ask Khadgar for a source to power the Legion communicator.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Caria Felsoul was a bright student... and a Legion traitor.$B$BIn her treason she was bestowed the Aldrachi Warblades, the soul-rending blades of the Aldrachi\'s greatest champion - they say he only finally fell to Sargeras himself.$B$BWe sent a small force to find Caria, but we have not heard word since. Jace has a Legion communicator he believes we can use to reach them- we just need a power source.$B$BPerhaps you could see if Khadgar has anything we could use? I\'m afraid our allies are few.', `QuestDescription`) WHERE `ID` = 41803;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ask and You Shall Receive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Crystallized Soul from Archmage Khadgar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A Legion communicator? Hmmmm.$B$B<Khadgar pauses to think for a moment.>$B$BYou know what, I think I have something in my lockbox upstairs that is just the ticket.', `QuestDescription`) WHERE `ID` = 41804;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Key of Kalyndras', `LogTitle`) WHERE `ID` = 41805;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Jace', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Jace Darkweaver.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That crystallized soul should power your communicator long enough to reach your allies.$B$BI must urge you to be cautious, $n. If that device is of Legion origin, then you never know who among its creators might overhear your message.$B$BI\'m sure your allies eagerly await your return.', `QuestDescription`) WHERE `ID` = 41806;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Establishing a Connection', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the Legion Communicator and receive Allari the Souleater\'s report.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Jace glances at the crystallized soul.>$B$BYes, that will do nicely. Release its energy to activate the communicator - it should already be configured to contact Allari and her forces.$B$BIf Caria is out there, we will find her, and we will make her suffer for her transgressions.', `QuestDescription`) WHERE `ID` = 41807;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest: Saw Boss Cinematic', `LogTitle`) WHERE `ID` = 41812;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'DANGER: Oubdob da Smasher', `LogTitle`) WHERE `ID` = 41816;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'WANTED: Majestic Elderhorn', `LogTitle`) WHERE `ID` = 41818;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'WANTED: Gurbog da Basher', `LogTitle`) WHERE `ID` = 41819;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'WANTED: Shara Felbreath', `LogTitle`) WHERE `ID` = 41821;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'WANTED: Arru', `LogTitle`) WHERE `ID` = 41824;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'WANTED: Crawshuk the Hungry', `LogTitle`) WHERE `ID` = 41826;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'WANTED: Bristlemaul', `LogTitle`) WHERE `ID` = 41828;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Masks We Wear', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with $3oa Masqued Revelers while in costume, then speak with Ly\'leth Lunastre.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Many nightborne had pinned their hopes on Thalyssra deposing the Grand Magistrix. Since she disappeared, dissenting voices have grown silent.nnWe must spread the word, discreetly, among the populace. Ly\'leth Lunastre will be a perfect ally in this. She is a socialite with many connections, and she is no friend of the Legion.nnLy\'leth hosts a masquerade party at her estate where rumors are traded like coin - and brandished like daggers.nnLet us invite ourselves in.', `QuestDescription`) WHERE `ID` = 41834;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'WANTED: Bodash the Hoarder', `LogTitle`) WHERE `ID` = 41836;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'WANTED: Slumber', `LogTitle`) WHERE `ID` = 41838;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'WANTED: Sekhan', `LogTitle`) WHERE `ID` = 41844;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Iron Fist', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Angus Ironfist at Tideskorn Warcamp in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s time to send a rescue operation to the Gates of Valor, $n.$B$BI will prepare our troops and send them at once. We will need a sizable army to take on the massive Legion force in Stormheim.$B$BGrandmaster, go ahead whenever you are ready. I will send our forces to meet you in the field.', `QuestDescription`) WHERE `ID` = 41849;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Master of Swords', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Dravax\'s Key from Dravax, then free Sylara Shadowheart.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I got bad news fer ya - we don\'t have time to wait for reinforcements. They\'re sacrificin\' prisoners now! Every minute we wait here jabberin\' is another life on the line!$B$BFirst things first, my friend Sylara is being held captive in the camp just across the road.$B$BWe need ta free her - she\'ll be a valuable ally.$B$BWe\'ve got ta move move move!', `QuestDescription`) WHERE `ID` = 41850;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Quelling the Tide', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 16 Legion defenders at the Gate of Valor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Sylara looks at you with determined eyes.>$B$BOur friends are in danger. We will save them. Kill any Legion in the way.', `QuestDescription`) WHERE `ID` = 41851;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'No Monk Left Behind', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free 6 Tortured Prisoners.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Most of the prisoners are being held in the main camp at the Gates of Valor.$B$BOur people have been beaten and tortured, and worse still awaits for them if we don\'t save them.$B$BFind the cages within the main camp and free as many monks as you can find.$B$BI\'ll be right beside you, knocking heads and taking names!', `QuestDescription`) WHERE `ID` = 41852;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Zero to Hiro', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Steal a Storm Brew, then save Hiro.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have a favor to ask of you, $n. My good friend Hiro is still somewhere inside the main camp.$B$BOnly problem is, the Gates of Valor are swarming with the biggest, baddest, nastiest Legion creatures I\'ve ever seen. If we walk in there, we\'ll just get slaughtered.$B$BBut I\'ve seen these vrykul chugging some kind of special brew called Storm Brew. It\'s some kind of combat tonic that makes them bigger and stronger.$B$BLet\'s steal some of that drink, then storm in to save Hiro!', `QuestDescription`) WHERE `ID` = 41853;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Brick By Brick', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Iron-Body Ponshu on the Wandering Isle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Da monks be free, and we put a thorn in dat eredar lady\'s side.$B$BI\'m back wit my friends, and lookin\' forward to sleepin\' in a bed tonight.$B$BLet\'s go back ta da Wanderin\' Isle. I\'ve never been so excited ta see a turtle in my life.', `QuestDescription`) WHERE `ID` = 41854;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stand Up to Bullies', `LogTitle`) WHERE `ID` = 41855;
