UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vengeance Will Be Ours', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Aldrachi Warblades from Caria Felsoul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Caria lies in the very heart of Legion territory - they\'ll see our forces immediately if we try to launch an all-out attack.$B$BFailure is not an option.$B$BHowever, if you go alone you might be able to slip by unnoticed long enough to avoid the brunt of the Legion army.$B$BRemember, $n - this is not a rescue mission. The power of the Aldrachi Warblades could tip the scales of this war in our favor; Allari and her men are expendable if need be.', `QuestDescription`) WHERE `ID` = 41863;
