UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lady Lunastre', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Ly\'leth at the Grand Promenade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our friend Ly\'leth contacted me. She requested that you meet her atop the Grand Promenade as it overlooks the city.nnHave your disguise ready just in case, $n.', `QuestDescription`) WHERE `ID` = 41877;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Gondolier', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Make contact with the Gondolier.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I need your help.nnThe wine you so graciously distributed to the needy was the last of my reserves. Without more, these people here will risk succumbing to their thirst, and eventually becoming withered.nnI am dedicated to preventing this for as long as possible.nnThere is a woman by the name of Deline who owns and operates a small delivery service out of her gondola.nnFind her, identify yourself as my messenger, and offer your aid in acquiring the next shipment.', `QuestDescription`) WHERE `ID` = 41878;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Den of Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Make contact with Arluin Shadowblade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Placeholder: Thalyssra sends you to find Arluin Shadowblade, a deft assassin once in her employ/social circle. (whichever fits) Indicate that he would be an invaluable asset to making progress in the City with covert operations.', `QuestDescription`) WHERE `ID` = 41880;
