UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Allegiance of Flame', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Farseer Nobundo in The Heart of Azeroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My rivals lay dead and there are none within the Firelands who dare oppose my rule!$b$bAs promised, I will unite with the other Elemental Lords in the defense of Azeroth. The armies of the Firelands will scorch the battlefield with the corpses of our enemies!$b$bGo now, mortal. Tell your Earthen Ring that the Firelord himself stands with you!', `QuestDescription`) WHERE `ID` = 41888;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dazed of the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Construct a Stonehide Leather Barding.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Let\'s begin crafting this mount armor, shall we?', `QuestDescription`) WHERE `ID` = 41889;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Side of the Moon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Protect Tyrande while she holds her vigil at the Ancient Moonwell.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Xavius has been this way, but his destination is unclear. The Nightmare smothers my mind!nnThese refugees tell of an ancient Moonwell hidden in the ruins ahead.nnIf it is uncorrupted, it will give me the focus I need. By Elune\'s light, we will find my husband yet.nnMeet me at the Moonwell at once, $c.', `QuestDescription`) WHERE `ID` = 41890;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Given to Corruption', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Keeper Varethos.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A final favor for an old friend, perhaps? My age-old companion, Varethos, has fallen to the nightmare\'s torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour.$b$bAs with all who suffer this fate, there is no restoring him.$b$bPlease, $n, bring him peace.', `QuestDescription`) WHERE `ID` = 41893;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Master of Pets', `LogTitle`) WHERE `ID` = 41895;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Operation Murloc Freedom', `LogTitle`) WHERE `ID` = 41896;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Master\'s Plan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the excerpts from The Master\'s Journal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The purpose of the Twilight\'s Hammer has always been the same. They seek to bring about the end of the world. Their schemes may change, but their wicked purpose remains constant.$b$bDefeating the Twilight\'s Hammer is not simply a matter of defeating them in battle. If we are to be successful, we will need to uncover their scheme and put an end to whatever terrible plans they have created.$b$bLet us start by searching the encampment for clues as to their true purpose here.', `QuestDescription`) WHERE `ID` = 41897;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unleashing the Elements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Release the Servants of Therazane from Twilight Depths.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'According to The Master\'s journal, the Twilight\'s Hammer has discovered a method of harnessing the void to subjugate even the most powerful of elementals.$b$bThe journal specifically mentioned the children of Therazane as test subjects. Whether The Master was speaking literally or figuratively in this regard, I do not know. Regardless, we need to free these elementals and stop these dark rituals from continuing.$b$bIt appears that our journey here is going to take us deeper into the depths of darkness...', `QuestDescription`) WHERE `ID` = 41898;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Held Captive!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue 10 Twilight Slaves from the Twilight Depths.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There are prisoners here, Farseer $n, that are enslaved by the Twilight\'s Hammer.$b$bThe cultists work them to death in the depths of the mine.$b$bI cannot abide such cruel mistreatment! Let us clear a path through the mine and rescue any Twilight\'s Hammer prisoners we find, so that they may return to their homes and families.$b$bThe Twilight\'s Hammer will pay for their crimes!', `QuestDescription`) WHERE `ID` = 41899;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Promise of Earth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Advisor Sevel in the Heart of Azeroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deepholm thanks you, shaman.$b$bThe Twilight\'s Hammer has always sought dominion over my kingdom, but this latest threat was far greater than their previous efforts.$b$bFor your service to the elements of earth, I will pledge my armies to the Earthen Ring in the defense of Azeroth.$b$bI have no love for the mortal races, but this world is not the Burning Legion\'s to destroy.$b$bTell your Earthen Ring that Therazane the Stonemother stands with them!', `QuestDescription`) WHERE `ID` = 41900;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Oath of the Windlord', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Advisor Sevel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have my thanks, mortal for bringing about my rebirth. However, thanks alone would not be honorable.$b$bI know that the Earthen Ring seeks to save Azeroth from the Burning Legion.$b$bI will pledge my sword, and the armies of Skywall to the aid of Azeroth.$b$bWhen the time for battle arrives, and the Earthen Ring stands upon the battlefield against the Burning Legion, the Windlord shall stand with you.', `QuestDescription`) WHERE `ID` = 41901;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Report from Tian Monastery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Investigate Tian Monastery."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have heard from all our temples on Pandaria, except for one.$B$BWe dispatched a message by bird to Tian Monastery, but no answer has yet arrived. This silence is quite unusual.$B$BGrandmaster, I recommend that we send our champion, Chen Stormstout, to scout the situation at once.', `QuestDescription`) WHERE `ID` = 41905;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Appropriations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Lao Shu in The Laughing Crane inn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have come to lend my help to the Order of the Broken Temple.$B$BMy job is to create a solid base of operations around here. Right now, we have wounded to tend and bellies to feed. After this, we can worry about building our defenses.$B$BLao Shu is in charge of our supply inventory. Go and speak with him now in the inn.', `QuestDescription`) WHERE `ID` = 41907;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking the Tideskorn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the "Tracking the Tideskorn" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have sent scouts to search for our kidnapped allies, and our efforts may have finally paid off.$B$BThey\'ve tracked them to the vrykul homeland of Stormheim, but the unfamiliar territory has slowed our progress and we\'re in danger of losing the trail.$B$BI suggest that we send our champions immediately to assist with the tracking effort.', `QuestDescription`) WHERE `ID` = 41909;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Freya\'s Spring', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete five "Freya\'s Spring" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'First, we need water from Freya\'s Spring.$B$BOnce a year, on the first day of solstice, the sun hits the white-capped summit of the highest peak in Highmountain. The melting snow runs through a ravine and collects in a crystalline pool.$B$BSome say these waters grant eternal youth. Silly stories if you ask me, but we will need this rare, purified water for our brew.$B$BI suggest sending our champions to collect us a sample, for your skills will be needed elsewhere.', `QuestDescription`) WHERE `ID` = 41910;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Amaranthine Hops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Fleuris Asterleaf in Val\'sharah and trade 20 Stonehide Leather for 1 bag of Amaranthine Hops.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The hops for our brew must be a very specific, and they will also be hard to acquire.$B$BAmaranthine Hops only grow in the realm known as the Emerald Dream, meaning we can only acquire this ingredient from a druid.$B$BThere is one such supplier from whom I receive this item, but she may ask for something in exchange.', `QuestDescription`) WHERE `ID` = 41911;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clear the Catacombs', `LogTitle`) WHERE `ID` = 41914;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Master\'s Legacy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the Gemcutter\'s Tomb.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You work for a murderer and a thief.$b$bThat design he wants? It is called the magistrix cut, and it was perfected by my husband. He was killed by Lespin for his secret.$b$bI had him entombed in a small cave north of the city, for we could not make the trip to Tel\'anor. Buried with him is a tome that contains the secrets of the design.$b$bRetrieve the design and keep it out of his hands!', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Investigate the Gemcutter\'s Tomb.', `AreaDescription`) WHERE `ID` = 41915;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Better Future', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue $1oa Shal\'dorei Insurgents in the Grand Promenade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must move quickly, $n. I must save as many of my people as I can before the attack begins.$b$bWord has gotten out in the city that there is a safe haven with us and some no longer fear exile.$b$bVenture into the Grand Promenade, champion. Find those willing to join us and let them know it is time they made their escape.', `QuestDescription`) WHERE `ID` = 41916;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Bear Cub', `LogTitle`) WHERE `ID` = 41917;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dreamer Returns', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Arch Druid Greathoof in the Dreamgrove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Arch Druid Greathoof will be expecting word on the success of our mission, but I\'m afraid I must ask you to return alone.$b$bI can\'t rest knowing that Xavius has Lord Ursoc in his clutches. Just the thought of it makes me shake with rage! I\'ll find where he has been taken if I have to search every corner of Azeroth!$b$bOur paths will cross again, $n. Be sure of it.', `QuestDescription`) WHERE `ID` = 41918;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Shadows Reveal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to your contacts in Dalaran to acquire intel on Akaari Shadowgore\'s whereabouts.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Fangs of the Devourer are wielded by Akaari Shadowgore, one of Kil\'Jaeden\'s personal assassins. Every attempt on her life ends the same... she\'s gone before we even arrive.$B$B<Valeera scrawls a few lines on a piece of paper, then hands it to you.>$B$BBut not this time. We\'ve been working with these contacts to find Akaari so we can finally take the Fangs for our own purposes.$B$BGo to each contact and tell them "The shadows reveal." See what they know.', `QuestDescription`) WHERE `ID` = 41919;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Matter of Finesse', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Borrow a Rune of Portals from Archmage Celindra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A rune of portals?! Who does Val\'zuun think he is?$B$B<Valeera takes a deep breath.>$B$BIt\'s worth the price, but those runes aren\'t exactly easy to come by. Unless...$B$BArchmage Celindra, the Kirin Tor\'s portal master, has a study in the center of town. We rogues aren\'t particularly welcome there, nor would she simply hand a rune over even if we were...$B$B<Valeera smirks.>$B$BBut who said anything about asking?', `QuestDescription`) WHERE `ID` = 41920;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Closing In', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Confront Akaari Shadowgore in the Legerdemain Lounge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legerdemain Lounge isn\'t far from here. We have agents nearby who can secure the area.$B$BCome prepared for a fight. Akaari won\'t go down easily.', `QuestDescription`) WHERE `ID` = 41921;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Traitor!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Join Valeera Sanguinar in the Underbelly Descent.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That lying demon SCUM! I should have known.$B$BLet\'s show Val\'zuun what happens to people who dare cross the Uncrowned.', `QuestDescription`) WHERE `ID` = 41922;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fangs of the Devourer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Fangs of the Devourer from Akaari Shadowgore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you spare me I can use the rune of portals you provided to open a gateway to Akaari\'s citadel in the Twisting Nether.$B$BOf course, killing the Legion\'s master assassin in her own domain will be no simple feat, but surely the Fangs of the Devourer are worth the risk, no?$B$B<Val\'zuun smiles.>$B$BI will guide you through the citadel once you arrive, but you will have to defeat Akaari on your own.', `QuestDescription`) WHERE `ID` = 41924;
