UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tianji of the Ox', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Tianji Needs Help".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, Grandmaster. Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.$B$BThe first task is critical. Tianji, a renowned trainer in the ox school style of martial combat, was on her way to the Broken Isles when she was attacked.$B$BI suggest we send Chen Stormstout to help her. He will be uniquely suited to this task.', `QuestDescription`) WHERE `ID` = 41945;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Building Our Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Recruiter Tianji and train an Ox Initiate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our champions acquired the talents of Recruiter Tianji, a famed monk skilled in the school of the ox.$B$BShe is known for her brewmaster techniques, and is a valuable addition to the temple. She is already beginning to train a new batch of pupils.$B$BSpeak to her now and train an initiate of the ox.', `QuestDescription`) WHERE `ID` = 41946;
