UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Vindicator\'s Plea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Vindicator Boros in front of First to Your Aid in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve obtained a request from Vindicator Boros in Dalaran asking for our help.$b$bHe has recovered a soldier who escaped from the Legion! He was injured and his wounds are resisting every healing treatment available to them. Normally this would fall to an acolyte to handle, but the soldier mentioned T\'uure in his delirium! I thought the holy gem was lost!$b$bYou are strong with the Light, perhaps you can succeed where they can\'t?$b$bIf you need it, Brother Larry can provide you with a flight to Dalaran.', `QuestDescription`) WHERE `ID` = 41957;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Oh, Ominitron', `LogTitle`) WHERE `ID` = 41958;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Holdings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Warden\'s Signet to Jarod Shadowsong.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Inside the chest, hidden amongst various knickknacks, is a signet engraved with a unique crest.$B$BThe band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner\'s finger.', `QuestDescription`) WHERE `ID` = 41961;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knowledge Unlock Daily Tracking Quest', `LogTitle`) WHERE `ID` = 41963;
