UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lunarwing Liberation', `LogTitle`) WHERE `ID` = 41965;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'House Call', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Treat the wounds of Defender Barrem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I thought Barrem was lost to us after the tragedy at Broken Shore, light knows we lost far too many good soldiers just like him there.$b$bI was shocked to see he was still alive when one of our patrols arrived carrying him. They found him floating in the sea with wounds that would kill any lesser Draenei.$b$bThere is something about those wounds that resists everything we\'ve done to treat them. Please, $c, as a brother in the light I ask you to do all that you can to help him to recover.', `QuestDescription`) WHERE `ID` = 41966;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Out of the Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Darkstone Isle near the Broken Shore and search for Alora.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alora and I were were able to escape through one of the Legion\'s portals back to Azeroth but that\'s about as far as our luck got us.$b$bThe portal put us on a small isle somewhere to the west of the Broken Shore. They saw us quickly and we made a run for the protection of the water. As I attempted to leap to safety, I was wounded. But Alora... she tripped and I watched them drag her back.$b$bRescue her, please! I\'ll mark where the camp is on your map, just don\'t let her go through that ordeal again.', `QuestDescription`) WHERE `ID` = 41967;
