UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fevered Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Field Packs to the location marked on your map. Treat the Fevered Explorer when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I must be hallucinating because I swear I can see a giant statue talking to me right now.$b$bIt\'s a good thing I\'m writing this down. And this. And that. Help?', `QuestDescription`) WHERE `ID` = 41985;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSE', `LogTitle`) WHERE `ID` = 41986;
