UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blood of My Blood', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Anarys Lunastre and deliver $Ghim:her; to Ly\'leth Lunastre.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As my darling $Gbrother:sister; has demonstrated, Elisande\'s decision to bring down the shield has sown unrest among the nightborne.$B$BLoyalists and demons march together in the streets. Fear and distrust grip our hearts. Family turns against family.$B$BI will help Thalyssra stir a new rebellion, but first we must deal with Anarys.$B$BI do not wish to spill the blood of my blood - only to help $Ghim:her; see reason.$B$BAnarys is likely brooding over our father\'s memorial. Bring $Ghim:her; to me alive.', `QuestDescription`) WHERE `ID` = 41989;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Chopped', `LogTitle`) WHERE `ID` = 41990;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Twisted Ash', `LogTitle`) WHERE `ID` = 41992;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Salvation From On High', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Something unexpected has interrupted your discussion, deal with it!', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was serving aboard the airship that crashed on the way to the Broken Shore. I must have blacked out as the next thing I remember was being jolted awake. I was on a broken land and above me stood a man\'ari carrying a staff of darkened crystal. There is no mistaking it, that staff was T\'uure!$b$bAll my life I\'ve heard stories about how T\'uure flowed with the healing power of the light. Somehow the crystal has been darkened by Man\'ari. We must get it back and restore it to its pure form!', `QuestDescription`) WHERE `ID` = 41993;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Corruption', `LogTitle`) WHERE `ID` = 41995;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tangled Nightmare', `LogTitle`) WHERE `ID` = 41996;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seeker of Truth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Orik Trueheart in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You may be familiar with Orik Trueheart. He has devoted his time after the Northrend campaign to learning more about Tyr. $b$bOrik has evidence of a powerful shield crafted by Tyr long ago. With the help of the Sunwalkers, we may finally be able to seek it out.$b$bPlease speak to him immediately.', `QuestDescription`) WHERE `ID` = 42000;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aluneth, Greatstaff of the Magna', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Kalec at the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Aluneth... a powerful and dangerous weapon. If tales are to be believed, Aluneth is actually the name of a very old and very powerful arcane entity, somehow bound to a staff through ancient magic.nnWhen Aegwynn relinquished Aluneth many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away in secret. Only they would know exactly where it was taken.nnThe dragon Kalec may be our best chance. He now resides on the Council of Six.', `QuestDescription`) WHERE `ID` = 42001;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Northrend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Orik Trueheart on Shield Hill in Howling Fjord.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Naturally I\'ve done some legwork already. I believe this Gorvold is buried at Shield Hill in the Howling Fjord.$b$bTahu can help locate the grave, and with a short ritual we should have our answers!$b$bMeet us at Shield Hill in the Howling Fjord and we\'ll move on to the next step.', `QuestDescription`) WHERE `ID` = 42002;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ghostship', `LogTitle`) WHERE `ID` = 42004;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The End of the Saga', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Get the end of the story from the spirit of the saga hero.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ye should read the saga yerself, it\'s right here.nnWe\'re here to speak to the spirit of that vrykul I spoke of. Tahu Sagewind is a powerful Seer and he should be able to bring his spirit back. It will be up to us to convince him to speak.nnYou should speak with Tahu so we can get started.', `QuestDescription`) WHERE `ID` = 42005;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A New Threat', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the Azure Dragonshrine for clues regarding the current state of the Nexus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you seek the Nexus, be wary. There are strange happenings in Coldarra, and it would be best to understand them before proceeding.nnDuring my last visit to Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was integral to Malygos\' plans during the Nexus War, whatever is there may explain the current state of the Nexus.nnHere, take this image crystal. I must remain in Dalarn on Kirin Tor business, so we will speak through it. Good luck.', `QuestDescription`) WHERE `ID` = 42006;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Forgotten Enemy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the Ethereal Communication Device at the Azure Dragonshrine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The device still hums with power. It must have been abandoned not long ago.nnThe nearby switch appears to activate it.', `QuestDescription`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Image of Kalec', `PortraitTurnInName`) WHERE `ID` = 42007;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eyes of the Dragon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Scout out the key locations in Coldarra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You should travel at once to Coldarra in Borean Tundra, $n. There, I would recommend you scout out a few key locations and report back to me. nnI know the area well, and should be able to tell you how to proceed.nnMake haste!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Image of Kalec', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Image of Kalecgos', `PortraitTurnInName`) WHERE `ID` = 42008;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Harnessing the Arcane', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Empower yourself with Unstable Arcane Energy by defeating Arcane Aberrants or siphoning from Breaches of Arcane Energy around the foundation of the Nexus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The energy from Aluneth lashes out from within the weakened Nexus Vault.  We may be able to use this raw, chaotic energy to our advantage.nnIf we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Image of Kalec', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Image of Kalec', `PortraitTurnInName`) WHERE `ID` = 42009;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arcane Unleashed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your built up Unstable Arcane Energy to destroy the Surge Needles in Coldarra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have the power you need to destroy the Surge Needles. nnAt the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Aluneth into these points. The reaction should cause an overload, destroying the Surge Needle above.nnYou must act quickly. The Ethereum won\'t sit idly by as you lay waste to their machinations.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Image of Kalec', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Image of Kalec', `PortraitTurnInName`) WHERE `ID` = 42010;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nexus Vault', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Nexus-Prince Bilaal and claim Aluneth, Greatstaff of the Magna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. nnWe have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Aluneth, I ask that you also free my brother from their grip.nnWith the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, $n.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Image of Kalec', `PortraitGiverName`) WHERE `ID` = 42011;
