UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shrine of the Truthguard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Shield\'s Rest in Stormheim and claim the Truthguard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ll be flying straight to the island. My friend said that the warrior who came here before us never entered the shrine itself, since they were after one of the tombs.$b$bIf a vrykul hero couldn\'t enter the shrine, I bet it\'s still protected by Tyr\'s power. I\'m thinkin\' we have a good shot at this.$b$bMy pal Cato will meet us there. We might be needin\' the talents of a good healer!', `QuestDescription`) WHERE `ID` = 42017;
