UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dire Growth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Naralex, plant the Lasher Seed, and analyze its effects.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Naralex asks for you to join him. He is ready to analyze the sample that he brought back from Shaladrassil.', `QuestDescription`) WHERE `ID` = 42031;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sampling the Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the mission, "Sampling the Nightmare."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is still so much that we don\'t know about the Nightmare.$B$BBefore we can fight it, we must understand how it spreads.$B$BLet us send our champions to the roots of Shaladrassil in Val\'sharah, and ask them to bring back samples to study.', `QuestDescription`) WHERE `ID` = 42032;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Malorne\'s Refuge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Broll Bearmantle at Malorne\'s Refuge in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I see... it is as we have always feared. The Emerald Nightmare has found our world.$B$BWe must call upon the ancient god, Malorne.$B$BTravel southeast to the shrine at Malorne\'s Refuge. There, we druids have kept a sacred relic for thousands of years, a gift from the white stag himself.$B$BI already sent Broll Bearmantle ahead to give word of your arrival.', `QuestDescription`) WHERE `ID` = 42033;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grip of Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 5 Darkfiend Raiders, rescue Sylendra Gladesong, and examine the Altar of Malorne.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Most of the druids were able to escape, but the shrine is still swarming with enemies.$B$BThe shrine\'s leader, Sylendra  Gladesong, stayed behind to recover Malorne\'s Idol. We must go back and help her.', `QuestDescription`) WHERE `ID` = 42034;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking the Enemy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your Cat Form to follow the satyr\'s tracks.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Idol may be stolen, but there is still hope.$B$BWhile I was trapped at the shrine, I saw the satyr raiders make off with the relic. Their tracks will still be fresh.$B$BWith our heightened senses, we may still be able to pick up their trail.$B$BWe must follow their signs through the forest and recover the Idol!', `QuestDescription`) WHERE `ID` = 42035;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Idol of the Wilds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Attack 6 Darkfiend Satyr and extract information about the Idol of the Wilds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We were able to wrest a confession out of this one. We know that their leader took the idol into Moonclaw Vale, but he could be hiding anywhere.$B$BSurely one of these satyrs will know where it was taken.$B$BGet the information out of these satyrs, even if it\'s the last thing they do.', `QuestDescription`) WHERE `ID` = 42036;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gathering the Dreamweavers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve druids by completing "Gathering the Dreamweavers" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you\'ve recovered the Idol of the Wilds, it\'s time to put it to use to commune with Malorne. However, the ritual will need the combined power of many druids.$B$BSend your champions to gather the druids of our order, and tell them to meet us in Nordrassil. We will need to do this together.', `QuestDescription`) WHERE `ID` = 42037;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Broll Bearmantle', `LogTitle`) WHERE `ID` = 42038;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Sylendra Gladesong', `LogTitle`) WHERE `ID` = 42039;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Way to Nordrassil', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archdruid Hamuul Runetotem in the Emerald Dreamway.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time has come for us to use the Idol of the Wilds and commune with Malorne.$B$BThe ritual will require a great deal of power, so we have decided to convene at Nordrassil and draw upon the World Tree\'s essence.$B$BThere is no time to waste. The fastest path will be through the Emerald Dreamway. Go ahead, and we will follow.', `QuestDescription`) WHERE `ID` = 42040;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Enduring the Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 12 aberrations of Nightmare.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are under attack here, $n!$B$BCreatures of the Nightmare are spilling into the Dreamway as we speak.$B$BDestroy them. They cannot be allowed to linger, or else the Nightmare will take root here, too!', `QuestDescription`) WHERE `ID` = 42041;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Teensy Weensies!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Mylune\'s Flute to gather 15 Teensy Weensy Fae Dragons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh $n, I\'m so very very happy to see you!$B$BThe woodland critters whispered there was trouble in the Dreamway so I came immediately!$B$BThere are so very many teensy weensy little creatures that live here in the Emerald Dream, and they\'re out there, all lost and alone!$B$BWould you go out there and gather them up? You can use my flute to call them to you.$B$BThank you, brave druid!', `QuestDescription`) WHERE `ID` = 42042;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cleaning Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Cleanse 100 Nightmare Creep.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When the Nightmare spreads, it consumes the life force of all that it touches.$B$BThe more it spreads, the weaker our magic becomes.$B$BIn its early stages, before the taint has taken hold, we can still cleanse the affected areas.$B$BI will bless you with Elune\'s grace. By channeling her power, you can reverse the Nightmare\'s spread.', `QuestDescription`) WHERE `ID` = 42043;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Dying Dream', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Witherheart.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deep in the heart of the swamp lies an ancient protector of the Dreamway, Witherheart.$B$BHe was among the first defenders to battle against the Nightmare, but he has fallen to total corruption.$B$BIt pains me to say it, but we must destroy him.', `QuestDescription`) WHERE `ID` = 42044;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Communing With Malorne', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Remulos at Nordrassil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our work here is done, $n. We have successfully defended the Dreamway. It will be only a matter of time before it is restored to its former state.$B$BBut we have more important matters at hand.$B$BTake the Idol of the Wilds and go onward to Nordrassil. With any luck, they have already gathered. We will meet you there.', `QuestDescription`) WHERE `ID` = 42045;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A New Beginning', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Archdruid Rensar Greathoof at the Dreamgrove in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If Malorne is in danger, then things are even worse than I feared. It truly is up to us now.$B$BWe have very little time left. Let us reconvene in the Dreamgrove at once.', `QuestDescription`) WHERE `ID` = 42046;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Hamuul Runetotem', `LogTitle`) WHERE `ID` = 42047;
