UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Powering the Portal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 10 Shards of Nightmare from "Powering the Portal" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If Malorne is trapped in the Nightmare, we must try to save him. It may sound like a fool\'s errand, but we cannot sit by idly.$B$BThere is an abandoned portal within the Emerald Dreamway, one that we druids closed long ago because it leads to the Rift of Aln.$B$BTo infuse it with energy once again, we will need shards of Nightmare which can be found on satyr lieutenants.$B$BSend our champions to hunt and kill these enemies.', `QuestDescription`) WHERE `ID` = 42049;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Defenders of the Dream', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose an ally.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Never has our order faced such a difficult challenge. To succeed, we must rely on each other\'s strengths.$B$BHowever, we only have a few defenders to spare for the battle ahead.$B$BBroll, Sylendra, Zen\'tabra, and Mylune have all volunteered to accompany you into the valley below, but I can only spare one.$B$BWhich one will you choose to aid you in battle?', `QuestDescription`) WHERE `ID` = 42050;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Enter Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go through the Nightmare Portal in the Emerald Dreamway.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The portal to the nightmare is ready, $n. Remulos and the others have already gone ahead.$B$BThere is no telling what horrors await on the other side, $n. Good luck.', `QuestDescription`) WHERE `ID` = 42051;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The War of the Ancients', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Win the War of the Ancients.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To free Malorne, we must win the War of the Ancients. A millennia ago, this battle took the combined efforts of the greatest defenders of our world. To win now, we must do the same.$B$BGo upon the battlefield and defeat Legion foes, rescue and revive our allies, and free the innocent who have been caught in the battle. Every enemy defeated and every ally saved will help turn the tide in our favor!', `QuestDescription`) WHERE `ID` = 42053;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Archimonde, The Defiler', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Archimonde.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have turned the battle, $n! The Burning Legion is greatly weakened.$B$BOnly one task remains. Malorne is locked in battle with Archimonde, the demon that slew him ten thousand years ago.$B$BRemember, $n, we are trapped in Malorne\'s nightmare. There is no telling what will manifest here, but we MUST do something.$B$BMay Elune guide us, $n.', `QuestDescription`) WHERE `ID` = 42054;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Demi-God\'s Return', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Receive Malorne\'s blessing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Malorne\'s voice echoes in your mind.>$B$BMortal you may be, but your valor is worthy of the ancient gods.$B$BNature\'s spirit lives in you - vibrant, wild, and ferocious. I witness in you the essence of nature\'s spark - the WILL to survive.$B$BOur triumph here will be spoken of for ages to come, $n.$B$BReturn to the waking world through this portal. We will speak again when we return to the Dreamgrove.', `QuestDescription`) WHERE `ID` = 42055;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Remulos', `LogTitle`) WHERE `ID` = 42056;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crumpled Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 2 Silkweave Splints and 1 Field Pack to the location marked on your map. Treat the Injured Adventurer when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Legs broken? Check. Arm broken? Check. Writing hand broken? Nope!$b$bBut seriously, someone please send help. I\'m in so much pain right now I think I\'m about to pass o...', `QuestDescription`) WHERE `ID` = 42058;
