UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Twilight Master', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Mistress of Twilight.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is only one more thing that remains, Farseer $n. We must confront the leader of the Twilight\'s Hammer and put an end to their sinister plot once and for all.$b$bWithout their so-called master, the remaining cultists will be forced to retreat from Deepholm.$b$bOnly when The Twilight\'s Hammer has been crushed and Deepholm has been saved, will we have the support of Therazane against the demons of the Burning Legion.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Mistress of Twilight', `PortraitGiverName`) WHERE `ID` = 42065;
