UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Return of Twilight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Muln Earthfury in Deepholm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Twilight\'s Hammer has reemerged and they are building an army to overthrow my kingdom. A ludicrous fantasy on their part, but one that I cannot take lightly.$b$bI cannot offer the mortal races my aid until the threat to Deepholm has been dealt with. If you truly wish to unite the Elemental Lords to your cause, I would see you prove it.$b$bGo. Uncover the plot that the Twilight\'s Hammer is hatching and put an end to their scheme!', `QuestDescription`) WHERE `ID` = 42068;
