UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return of the Light', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Accompany Jace Darkweaver through the portal and obtain T\'uure, Beacon of the Naaru.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Excellent!$b$bThere is a gateway further down this pathway and like most Legion constructs it is powered by souls.$b$bI think the death of that Inquisitor should be just enough to activate it and open the way back to where it came from.$b$bLet\'s go see where the path takes us, shall we?', `QuestDescription`) WHERE `ID` = 42074;
