UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Masquerade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Mask of Mirror Image on Anarys Lunastre.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our family commands great respect in this city, thanks to my father. Through my network of contacts, we can organize the citizens to prepare Suramar for Thalyssra\'s return.$B$BYou must walk among the nightborne. You must earn the trust of our friends and foes alike.$B$BYou must become someone else.$B$B<Ly\'leth hands you a shimmering party mask.>$B$BPut this on Anarys.', `QuestDescription`) WHERE `ID` = 42079;
