UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In With the New', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the newly forged High-Capacity Decoction Conduit to Deucus in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well, here\'s your new conduit. Try not to break this one, I really don\'t feel like making another.$b$bOh, and tell your boss, Deucus, that he owes me big time for this.', `QuestDescription`) WHERE `ID` = 42081;
