UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Evacuate Snowmane', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Evacuate Red Skymane, Tarvim Daywalker, and Old Nefu.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'They just keep coming!$b$bAnd now my scouts report some of the drogbar have managed to sneak around our flank and are attacking Snowmane Village.$b$bGo, help the evacuation. We will hold the line here and try to buy you some time.', `QuestDescription`) WHERE `ID` = 42088;
