UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Searching the Archives', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interact with the Dreadscar Battle Plans and complete the mission "Searching the Archives".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Black Harvest archives contain an immeasurable amount of magical knowledge that has been collected from various sources over time. nnIt\'s reasonable to think that somewhere among the countless scrolls that we\'ll find something to aid us in our mission to rescue the remaining council members. nnThe search may be exhausting, but it is necessary if we plan to rebuild and face the Burning Legion.', `QuestDescription`) WHERE `ID` = 42097;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Hold: An Unclaimed Soul', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect an Unclaimed Soul from The Amalgam of Souls in the Black Rook Hold dungeon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to create the anchor, we\'ll need to link something of Shinfel\'s to an unclaimed soul.nnThe soul will act like a beacon, guiding Shinfel through the Twisting Nether, and back to Dreadscar Rift.nnShinfel\'s staff should provide us with the link we need, but the soul will be a bit harder to find. nnDwelling within Black Rook hold is an amalgam of souls, some lost and forgotten. Killing this monstrosity should provide us with the soul we need.', `QuestDescription`) WHERE `ID` = 42098;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Empowering the Soul', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Empowered Soul Shards by completing class hall missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Creating the anchor will require more power than our soul shards will be able to provide.nnDreadscar\'s troops are capable of amassing a large amount of soul shards when they defeat enemies while on missions. Once we have enough, I can harvest the supply and use them to craft the anchor.', `QuestDescription`) WHERE `ID` = 42100;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Language of the Lost', `LogTitle`) WHERE `ID` = 42101;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One Who\'s Worthy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interact with the Scouting Map and complete the missions, "One Who\'s Worthy".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If we wish to successfully summon the sisters, we\'ll need the help of a warlock who is skilled in summoning greater demons.nnWe cannot afford to lose another council member due to inexperience. nnThe Broken Isles are swarming with new blood, all hoping to make a name for themselves in this time of chaos. nnHopefully among them we can find one worthy of this council.', `QuestDescription`) WHERE `ID` = 42102;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Let it Feed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill demons throughout the Broken Isles and collect their blood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We can use the Bloodstone to control the sisters once they are in a weakened state, but first, we\'ll need to feed it.nnThe stone grows in power when consuming the blood of demons. Luckily for us, there\'s no shortage of demons to kill.', `QuestDescription`) WHERE `ID` = 42103;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Underking Comes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Evacuate Riverbend.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here, I\'m too slow to get these laggards to safety. Take my horn and sound the evacuation.$b$bWe need to get the people out of here before the drogbar arrive. The warbraves can take it from there.$b$bFor now just send them over to Spiritwalker Ebonhorn. That fool can watch over them until it is safe.', `QuestDescription`) WHERE `ID` = 42104;
