UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'On the Trail of the Great Worm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the mission "On the Trail of the Great Worm."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need the Gjallarhorn to compel the armies of Odyn\'s children to join our cause. If the great worm swallowed it, we shall dig through the very earth until we find it in its entrails!', `QuestDescription`) WHERE `ID` = 42107;
