UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To the Summit!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Highmountain Summit.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your armies have tracked the beast to the highest peak in Highmountain.$B$BIt has nowhere left to run, but it is protected by foul drogbar. You must go there yourself and slay Jorhuttam!', `QuestDescription`) WHERE `ID` = 42110;
