UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Ritual of Tides', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Perform the Ritual of Tides in the Maelstrom.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Long ago, the first Farseer of the Earthen Ring was given a vision of the elements.$b$bIn the vision she foresaw the arrival of a new Farseer, one who would lead us through a time of terrible crisis and unite the elements.$b$b$n, I believe that you are the Farseer of this prophecy, called to lead before you were ever born.$b$bThe time has come to fulfill your destiny!$b$bWhen you are ready, we will perform the Ritual of Tides and call upon Neptulon, the first of the four great Elemental Lords.', `QuestDescription`) WHERE `ID` = 42114;
