UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Silver Hand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Tyr\'s Fall in Tirisfal Glades and recover the Silver Hand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Too many know of its location, the tomb must be closed forever. First, we must reclaim the hammer.nnTyrosus has lent us a force to aid in the recovery of the hammer, and some of my order will meet us there as well, but I fear even that may not be enough. I\'m glad we\'ll have you with us.nnTake the portal to Dalaran Crater, then fly to Tirisfal Glades and meet us. I\'ve marked the location on your map.', `QuestDescription`) WHERE `ID` = 42120;
