UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Whispers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Calydus\'s portal to enter into Felsoul Hold and recover the Skull of the Man\'ari.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Felsoul Hold is not far away, but it is well defended. Very tough to get in the normal way, but Calydus can help you sneak in!$b$bThere is a portal that my kind use to haul in treasures, with it you can get in and find the skull!', `QuestDescription`) WHERE `ID` = 42125;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Archmage Omniara', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Omniara Needs Help"', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.nnThe first task is critical. Archmage Omniara, a renowned summoner, was on her way to the Hall of Guardians when she was attacked.nnSend Archmage Kalecgos to help her. He will be uniquely suited to this task.', `QuestDescription`) WHERE `ID` = 42126;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Building Our Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archmage Omniara and recruit some of her Water Elementals', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Omniara is a very powerful arcanist and her skills will be quite an asset to our order.$B$BShe is capable of summoning multiple Water Elementals at the same time! Fortunately, she has agreed to share her knowledge with us.nnSpeak to her now, and recruit her elementals.', `QuestDescription`) WHERE `ID` = 42127;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ritual Reagents', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search within Dalaran for Grave Dust, a Can of Overheated Oil, an Aged Snowplum Brandy, and a Stag Blood Sample.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Skull of the Man\'ari, oh good choice! It\'s very powerful and it\'s held by an even more powerful Dreadlord!$b$bThere is a weakness, the skull has a will of its own! If we can commune with the skull we might be able to convince it to serve you instead!$b$bWe will need reagents from the floating city before we can perform the ritual to commune with it. Dust from a fresh grave, dark oil, and a powerful alcohol catalyst.$b$bOh, and blood! I sense a beast whose blood should be perfect.', `QuestDescription`) WHERE `ID` = 42128;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Pendant of Starlight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Pendant of Starlight from Abyssal Queen Sha\'rathra, who patrols along the coast of Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To finish my work here, I will need a magical item called the Pendant of Starlight.$B$BFor centuries, the Archdruids of the Dreamgrove passed the pendant down from one guardian to the next. But one day, a naga siren used deception to take it!$B$BThis pendant stores a great amount of arcane power... power I can use to heal the grove.$B$BGet it back, and I will be very grateful!', `QuestDescription`) WHERE `ID` = 42129;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unexpected Visitors', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Listen to your unexpected visitors.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Brace yourself, $n. I am detecting a strange magic forming in the chamber. Something is projecting itself in.', `QuestDescription`) WHERE `ID` = 42131;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Last, But Not Least', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Allari the Souleater and Jace Darkweaver as your champions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I think you already know what I am going to tell you... It is well past time to make Allari and Jace your champions.nnThe two of them were instrumental in the planning and preparation for the invasion of Niskara. They have earned it and you would be hard pressed to find better champions anywhere.', `QuestDescription`) WHERE `ID` = 42132;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Same Day Delivery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Emmarel Shadewarden at Trueshot Lodge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve enchanted these weapons to counter the natural resistances that felhounds have to magic. In addition to that, the metal should splinter their scales on impact, allowing your allies to do increased damage to the demons.$B$BWhile I don\'t expect the enchantment to decay over time, you should do your best to deliver these weapons to those who will use them immediately. The longer they remain here, the more demons their power will attract.', `QuestDescription`) WHERE `ID` = 42133;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting More Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Recruiter Sampson.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our champions acquired the talents of Recruiter Sampson, an extraordinary tracker.$B$BHe has a way with animals, calling them to his side with the utmost ease. In fact, he\'s already beginning to fill the stables with animals that he has tracked and tamed.$B$BSpeak to him now.', `QuestDescription`) WHERE `ID` = 42134;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest: Chose Strategy C', `LogTitle`) WHERE `ID` = 42135;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest: Chose Strategy A', `LogTitle`) WHERE `ID` = 42136;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Yalia Sagewhisper', `LogTitle`) WHERE `ID` = 42137;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Zabra Hexx', `LogTitle`) WHERE `ID` = 42138;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Garona Halforcen and Vanessa VanCleef as your first champions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Uncrowned work behind the scenes, pulling strings here, snipping others there. It\'s a matter of making the right choices at the right time in the most elegant manner possible.nnWe have all decided that you need to recruit some Shadows to send out on our most important missions. People that you can trust, or at least that you can trust to get the job done.nnMight I suggest that you start with Garona and Vanessa? It should prove interesting if nothing else considering recent events.', `QuestDescription`) WHERE `ID` = 42139;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A More Wretched Hive of Scum and Villainy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "A More Wretched Hive of Scum and Villainy".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Word on the street is that you\'re lookin\' to recruit some more, shall we say, unsavory types?nnI know just the woman! No, not me... though, I could prolly do it. But not as well as Lonika Stillblade.nnYeah, that Lonika. The one who founded the \'School of Roguery\' in Shattrath City.nnSo, let\'s send Vanessa there out to Outland and have her make Lonika an offer she can\'t refuse. Or, you know, give her a legit job and a nicer location for her rogue academy.', `QuestDescription`) WHERE `ID` = 42140;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Summoner Morn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Morn Needs Help".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have recruited champions of our order, we can use the Scouting Map to complete vital assignments across the Broken Isles.$B$BThe first assignment is critical. Summoner Morn, a renowned master of the elementals, was on his way to the Heart of Azeroth when he was attacked.$B$BI suggest we send Stormcaller Mylra to help him. She will be uniquely suited to this task.', `QuestDescription`) WHERE `ID` = 42141;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting The Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Summoner Morn and summon a Lesser Elemental.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our champions acquired the talents of Summoner Morn, a powerful shaman.$B$BHe is known for his strong affinity with earth, and is a valuable addition to our Order. He is already beginning to requisition Lesser Elementals to our cause.$B$BSpeak to him now and train a Lesser Elemental.', `QuestDescription`) WHERE `ID` = 42142;
