UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dazed and Confused and Adorable', `LogTitle`) WHERE `ID` = 42146;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'First Contact', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Vanthir in The Grand Promenade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Time to put your new disguise to the test.$B$BYour first contact is Vanthir, a merchant from the common district. He is in the Grand Promenade today visiting one of his suppliers.$B$BTell Vanthir to pay me a visit regarding a shipment of dusk lily bulbs. He will understand.$B$BBeyond that, we will need time to prepare. You should return to Thalyssra.$B$B<Ly\'leth hands you a corked bottle of faintly glowing fluid.>$B$BGive her this, with my regards. We will call upon you soon.', `QuestDescription`) WHERE `ID` = 42147;
