UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Some Knowledge Shouldn\'t Be Shared', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 5 Empyrean Fel Tomes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I noticed that quite a few of the Empyrean Society\'s books are inscribed with fel magic. That\'s blasphemous. We must confiscate as many as we can.', `QuestDescription`) WHERE `ID` = 42149;
