UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Creator\'s Workshop', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist Mimiron.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My remote observation relay captured an astonishing amount of data from that tomb.$B$BIf we can download its memory to my core processing systems, I should be able to locate Titanstrike... and that unsavory vrykul who took it.$B$BSince you\'re here, would you mind helping out? Processing that much information might overload a few failsafe mechanisms here and there, and I know you\'re the capable sort!', `QuestDescription`) WHERE `ID` = 42158;
