UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'What Is Going On Here?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Question 5 Empyrean Society members and investigate their grounds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We don\'t know much about the Empyrean Society\'s activities here, but now that you appear to be a new recruit you should be able to ask some questions and take a look around for the strange magic Archmage Vargoth detected. nnLet\'s meet up at the rotunda on the hill.', `QuestDescription`) WHERE `ID` = 42166;
