UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Looking into the Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Perform the ritual to commune with the Skull of the Man\'ari and convince it to tell you its location.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Friend now is ready to perform the ritual!nnRemember, friend, the skull must be convinced that it is in its best interest to be in your possession. If we must force the skull into your servitude, it would be far weaker.', `QuestDescription`) WHERE `ID` = 42168;
