UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dreamweavers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete any 4 world quests in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Assist the Druids of Val\'sharah by completing 4 world quests.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Sylvia Hartshorn in Val\'Sharah.', `QuestCompletionLog`) WHERE `ID` = 42170;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Final Exit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Rune of Opening to unlock the Empyrean Society building door.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve certainly reduced the Empyrean Society\'s numbers. I don\'t think they\'ll be luring any more members to their cause for a while. nnThere\'s only one place we haven\'t investigated, and I suspect that rune we found is attuned to the door. Let\'s see what\'s inside the building.', `QuestDescription`) WHERE `ID` = 42171;
