UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Meryl Felstorm in the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tirisgarde has need of your help now that you have grown in strength, $n. Meet me in the Hall of the Guardian when you are done with your adventures.', `QuestDescription`) WHERE `ID` = 42175;
