UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mission: Elemental Diplomacy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Successfully complete the "Elemental Diplomacy" mission.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Lord of Tides has united with the Earthen Ring, but the matter of uniting the remaining Elemental Lords still remains.$b$bFor the next step of our campaign, I have organized a diplomatic mission to Skywall.$b$bThe goal of the mission is to ascertain the current political situation in Skywall, following the defeat of Al\'Akir the Windlord, and to identify any elementals who would aid our cause.$b$bThe mission is currently waiting your assignment.', `QuestDescription`) WHERE `ID` = 42184;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Never Hunt Alone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Thorim at the Temple of Storms and recover Titanstrike.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Prustaga is almost certainly on her way to the Temple of Storms, which is where I imbued Titanstrike with the Thunderspark.$B$BIf my deductions are correct, she\'ll attempt to reverse the process and infuse the spark into herself, thus attaining the godlike power she craves!$B$BHopefully Thorim isn\'t off cavorting with his hounds again. If Prustaga has the local vrykul on her side, things may get... complicated.', `QuestDescription`) WHERE `ID` = 42185;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Iron-Body Ponshu at the Wandering Isle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Iron-Body Ponshu has requested your presence.$B$BOur campaign to defend the Broken Isles is getting under way, and we need you back at the Wandering Isle.', `QuestDescription`) WHERE `ID` = 42186;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enlist Chen Stormstout and Li Li Stormstout, then speak to Master Hsu.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are still recovering from the attack at the Peak of Serenity.$B$BTo help us rebuild the order, we should enlist the greatest champions of our class to fight by our side.$B$BI know that the two Stormstouts, Chen and Li Li, would eagerly pledge to join the cause. Speak to them and recruit them as champions, then speak to Master Hsu.', `QuestDescription`) WHERE `ID` = 42187;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nobundo Awaits', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Nobundo in the Heart of Azeroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Nobundo and the other champions of the Earthen Ring have gathered down below. They are awaiting your arrival, Farseer.$b$bA great ritual is about to take place and they have requested your presence. Do not worry about your administrative duties for now, I\'ll take care of things here.$b$bNobundo is waiting for you now. May the elements be with you, Farseer.', `QuestDescription`) WHERE `ID` = 42188;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fire Mage - Flavor Event 01', `LogTitle`) WHERE `ID` = 42189;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wildlife Conservationist', `LogTitle`) WHERE `ID` = 42190;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tech It Up A Notch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Number Nine Jia.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thanks to you, the Order of the Broken Temple is gradually re-assembling.$B$BHowever, there is much more work to do. As our leader, you can determine the trajectory of our order\'s future.$B$BSpeak to Number Nine Jia. She will show you the ropes.', `QuestDescription`) WHERE `ID` = 42191;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fire Mage - Flavor Event 02', `LogTitle`) WHERE `ID` = 42192;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Gjallarhorn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Svergan Stormcloak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have proven yourself most thoroughly time and again, $n. There can be no doubt that you are the one to lead Odyn\'s armies into the final battle.$B$BYou must first obtain the Gjallarhorn so that you may signal to our allies that the end times are upon us.$B$BKing Svergan Stormcloak was the last known living guardian of the horn.$B$BSeek his spirit in the Field of Fallen Kings in Stormheim and see what you can learn.', `QuestDescription`) WHERE `ID` = 42193;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stolen Honor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Svergan Stormcloak wants you to obtain the Crown of the Forgotten King, the Stormcloak Signet and the Drakerider\'s Medallion in the Runewood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Safeguarding the Gjallarhorn was my duty, $r. I will do what is right, but first I must ask for your aid.$B$BMy family was disavowed by the mystics of our time and this grave was ransacked.$B$BI cannot find peace while my family heirlooms are in the hands of the servants of the false God-King.$B$BReturn them to me and I will aid you in finding the Gjallarhorn!', `QuestDescription`) WHERE `ID` = 42194;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Duke Hydraxis', `LogTitle`) WHERE `ID` = 42197;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Stormcaller Mylra', `LogTitle`) WHERE `ID` = 42198;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mission: Investigating Deepholm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Successfully complete the "Investigating Deepholm" mission.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order for the Earthen Ring to bring the four Elemental Lords together in an alliance against the Burning Legion, we will need to convince Therazane the Stonemother to join forces with us.$b$bTherazane has been absent from our negotiations with the elements thus far.$b$bThere have been whispers of a new threat arising from within Deepholm. If these rumors are true, she may have need of our aid.$b$bI have prepared a diplomatic mission to Deepholm to ascertain the situation. It is awaiting your assignment.', `QuestDescription`) WHERE `ID` = 42200;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Revenge, Served Cold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Dogrub the Cruel, Urgrul Skullcleaver and 8 Frostcrag Drogbar in Highmountain Summit.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My village was razed by a drogbar tribe who worships the very beast you seek. No one was spared.$B$BHelp me avenge my people and I will aid you in your quest to find Jorhuttam.', `QuestDescription`) WHERE `ID` = 42202;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ritual Bit', `LogTitle`) WHERE `ID` = 42203;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Jorhuttam', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Frostcrag Drums near Jorhuttam\'s Feeding Mound and slay Jorhuttam to obtain the Gjallarhorn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You upheld your end of your promise. I will do the same.$B$BTake these drogbar drums. Then bang on them to call upon Jorhuttam to feast.$B$BFind the Great Worm\'s feeding mound and use the drums to lure her out.', `QuestDescription`) WHERE `ID` = 42204;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Entrance Bit', `LogTitle`) WHERE `ID` = 42205;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Next Level Has Arrived', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 10 Empyrean Society members.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Empyrean Society is certainly much more dangerous than they appear. It\'s unimaginable that any mage would study fel magic -- that\'s for warlocks and the Legion!nnSince our friend, Ravandwyr, appears to be delayed, it looks like we\'ll have to deal with this ourselves. We should remove this sect so they can\'t corrupt anyone else.', `QuestDescription`) WHERE `ID` = 42206;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Firelands', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the "Return to the Firelands" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time has come to return to the Firelands. I need not tell you how dangerous this will be, Farseer.$b$bRagnaros may be defeated, but the elementals of the Firelands destroy with reckless abandon. Our presence there will surely be seen as an act of aggression.$b$bI have prepared a scouting mission to the Firelands. We should send only our very best champions to make contact with the elements there.$b$bIf the mission is successful, we may find the information we need to bring the Firelands into our fold.', `QuestDescription`) WHERE `ID` = 42208;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Freeing the Taken', `LogTitle`) WHERE `ID` = 42209;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scrolls of Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the mission, "Scrolls of Knowledge."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our troops are ready! It\'s time to test them out in the field, and I have the perfect assignment.$B$BNumber Nine Jia is a well-respected scholar. She has knowledge that can help us improve the order, however, many  of her important scrolls were left behind during the attack on the Peak of Serenity.$B$BSend our champions to retrieve these documents at once!', `QuestDescription`) WHERE `ID` = 42210;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leodrath\'s Kin', `LogTitle`) WHERE `ID` = 42211;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fire Mage - Flavor Event 03', `LogTitle`) WHERE `ID` = 42212;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: The Tidestone of Golganneth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the central teleporter in Dalaran and then place the Tidestone of Golganneth in the Portrait Room of the Chamber of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Now that you have defeated Queen Azshara\'s Wrath and have the Tidestone in hand, it is time to place it in the Portrait Room of the Chamber of the Guardian in lower Dalaran.>', `QuestDescription`) WHERE `ID` = 42213;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knocked for a Loop', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Salteye Bangles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you\'re focused on murlocs...$b$bMany murlocs are known to wear jewelry to attract a mate. I\'m willing to bet that we can use some of the same jewels they use.$b$bCollect some of their jewelry and bring it back to me. The wetter, the better!', `QuestDescription`) WHERE `ID` = 42214;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Singed Letter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Silvery Salves and 1 Field Pack to the location marked on your map. Treat the Felburned Scout when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I pray this letter makes it into the right hands. Knowing my luck, it\'ll probably wind up in the stomach of some creature.$b$bIf you\'re reading this, then please bring something to treat my burns. They really hurt. A lot.', `QuestDescription`) WHERE `ID` = 42215;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shipwrecked Sailors', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Put $1oa Queen\'s Reprisal Sailors out of their misery.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The gilblin and makrura of Mak\'rana have captured the forsaken sailors from the nearby shipwreck.>nn<It looks like the sailors are being poisoned and worse. Best to put them out of their misery.>', `QuestDescription`) WHERE `ID` = 42220;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Chief Bitterbrine', `LogTitle`) WHERE `ID` = 42221;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Empyrean Society Report', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I find it hard to believe that Archmage Vargoth would be involved with such a malevolent group! There must be a good explanation for why he\'s been here... nnRegardless, we had best return to the Hall of the Guardian and inform Meryl about what we\'ve uncovered here.', `QuestDescription`) WHERE `ID` = 42222;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scouting the Crimson Thicket', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Lilryia Dawnwind in Dawncleft.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you are heading east, there is something I would ask of you.$b$bWhile we struck camp some of our caravan left to scout around the city. Lilryia Dawnwind has been gone too long.$b$bI would be most grateful if you would go check on her safety. She said she was going to scout out the ruins of Dawncleft.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Find Lilryia Dawnwind in Dawncleft.', `AreaDescription`) WHERE `ID` = 42223;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cloaked in Moonshade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Explore Moonshade Sanctum.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I do not know what Theryn found, but I know where he found it. nnMoonshade Sanctum, to the west. Beyond the Temple of Fal\'adora. nnWhatever power altered Theryn\'s arcane essence... Whatever power allowed Kel\'danath to create a spell to soothe the withered... Its source rests there. nnI know this as surely as if I had been there myself.', `QuestDescription`) WHERE `ID` = 42224;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Breaking the Seal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Break the Seal of the Tides, Seal of the Earth and Seal of the Sky.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<As you behold the relic, Thalyssra\'s voice echoes in your mind.>nnYou found it! But it is sealed away tight.nnSearch the room for a way to break those seals.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'First Arcanist Thalyssra', `PortraitGiverName`) WHERE `ID` = 42225;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moonshade Holdout', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay a Fal\'dorei Webslinger, a Fal\'dorei Broodcaller, and a Fal\'dorei Widowmaker.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Tampering with the relic has drawn the attention of some hideous creatures from beneath Falanaar.>', `QuestDescription`) WHERE `ID` = 42226;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into the Crevasse', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Valewalker Farodin into the Falanaar Tunnels.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have protected that seed for ten thousand years. You let it fall into the hands of the fal\'dorei.$B$BI should have let you die.$B$BRepay your debt. Help me get the seed back.', `QuestDescription`) WHERE `ID` = 42227;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hidden City', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Orathiss through Falanaar Tunnels and slay her.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Orathiss has underestimated the seed. It is sapping her power - slowing her down.$B$BWe must catch her and get the seed to safety!', `QuestDescription`) WHERE `ID` = 42228;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shal\'Aran', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Thalyssra while she explores Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The chamber beyond may be the perfect hiding place, now that its guardian has been dealt with.nnCome with me.', `QuestDescription`) WHERE `ID` = 42229;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Valewalker\'s Burden', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the Fal\'adora Beacon in Temple of Fal\'adora.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The seed is awakening. Without power it will quickly wither and die.nnWe must carry the seed out of here and plant it somewhere safe.nnI am not strong enough to bear this burden. But you... you are brimming with power. I can sense it. nnPlease take the seed.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Valewalker Farodin', `PortraitGiverName`) WHERE `ID` = 42230;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Mysterious Paladin', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Travard in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It appears we have been afforded a unique opportunity.$b$bA small order of paladins has come forward claiming to know the location of Tyr\'s tomb. They say they are the protectors of his warhammer, but that the ancient weapon is now imperiled.$b$bI\'d like you to speak with Travard, their leader, to find out more about this artifact.', `QuestDescription`) WHERE `ID` = 42231;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Highmountain Tribes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete any 4 world quests in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Assist the Tauren of Highmountain by completing 4 world quests.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Ransa Greyfeather at Thunder Totem in Highmountain.', `QuestCompletionLog`) WHERE `ID` = 42233;
