UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missing Demon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Daglop in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I seem to have misplaced my imp, Daglop.$b$bIf you see him, tell him to check in.$b$bNormally I would just resummon him but I\'m worried blind Marius here will kill him first and ask questions later.$b$bNo vision, that one.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Daglop in the Olivian Veil.', `QuestCompletionLog`) WHERE `ID` = 42238;
