UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Singed Note', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Silvery Salves and 1 Field Pack to the location marked on your map. Treat the Felburned Scout when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Please, if you\'re reading this then there still may be time. I was badly burned fighting the Legion.$b$bI\'ve included a rough sketch of where I am relative to the Crumbled Palace.$b$bPlease hurry, and bring supplies.', `QuestDescription`) WHERE `ID` = 42245;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fevered Plea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Field Packs to the location marked on your map. Treat the Fevered Explorer when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can\'t take this exhaustion any longer. And the heat of this place is making me see things.$b$bPlease, if someone finds this message, look for me. And bring medicine for Light\'s sake.$b$bI think I see Deathwing coming...$b$b<The ink on the last letter falls down to the bottom of the note.>', `QuestDescription`) WHERE `ID` = 42250;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloody Note', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Silkweave Bandages and 1 Field Pack to the location marked on your map. Treat the Gravely Wounded Soldier when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m not sure how much longer I can keep pressure on this wound.$b$bIf you find this note, please bring bandages. Lots and lots of bandages.', `QuestDescription`) WHERE `ID` = 42255;
