UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Their Dying Breaths', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Cracked Ley Crystals, then use them to resuscitate the Mana-Drained Whelplings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have precious little time. As we speak, my troops are defending against an onslaught of withered elves.$b$bThese four whelplings are near death. Their lives are of the utmost importance to our flight, as they may be some of the last whelplings Senegos can rear.$b$bSome cracked ley crystals should bring them back to their senses.', `QuestDescription`) WHERE `ID` = 42271;
