UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fevered Note', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Field Packs to the location marked on your map. Treat the Fevered Explorer when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I didn\'t realize that a harpy\'s kiss was actually poisonous. Damn vixen tricked me.$b$bI know I\'m not supposed to kiss and tell, but if I don\'t get well soon, I fear this may be my end.$b$bIf someone finds this letter, please bring medical supplies and treat my sickness.', `QuestDescription`) WHERE `ID` = 42303;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloody Plea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Silkweave Bandages and 1 Field Pack to the location marked on your map. Treat the Gravely Wounded Soldier when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I hope I survive this long enough to tell the tale of when I was mauled by a bear.$b$bBut unless this letter finds its way into the proper hands, I may not have long to live.$b$bI\'m in desperate need of bandages. Please bring any you can spare.', `QuestDescription`) WHERE `ID` = 42308;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloody Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Silkweave Bandages and 1 Field Pack to the location marked on your map. Treat the Gravely Wounded Soldier when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What can I tell ya, I\'m satyr hater. Those cursed beasts slashed me up pretty good when I was trying to rescue my comrades in the Sleeper\'s Barrow. $b$bTo whomever finds this letter, make your way over to the barrow. You\'ll find me in there, hopefully still alive.$b$b-Satyr Hater', `QuestDescription`) WHERE `ID` = 42309;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fevered Letter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Field Packs to the location marked on your map. Treat the Fevered Explorer when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m stuck up on this wretched mountain, freezing to death and to boot I most definitely have the flu.$b$bIt\'s nice to be in such a cold climate with a fever, but if it doesn\'t break I\'m afraid I may be done for.$b$bTo whomever is reading this, please bring medical supplies.', `QuestDescription`) WHERE `ID` = 42323;
