UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crumpled Letter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 2 Silkweave Splints and 1 Field Pack to the location marked on your map. Treat the Injured Adventurer when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Need medical attention. Arm broken. Probably leg too. Light-forsaken drogbar!$b$bYou\'ll find me at the base of a large mountain in Highmountain. I\'m sure that narrows it down.', `QuestDescription`) WHERE `ID` = 42333;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crumpled Note', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 10 Silkweave Splints and 5 Field Packs to the location marked on your map. Treat the Injured Adventurers when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m not sure how, but we managed to survive being dropped off the mountain by harpies.$b$bWe\'re in bad shape though. Please, if someone finds this note, bring help.', `QuestDescription`) WHERE `ID` = 42334;
