UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Singed Plea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 9 Silvery Salves and 3 Field Packs to the location marked on your map. Treat the Felsoul Hold Escapees when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We just barely managed to escape, but not before they rained hell upon us with their demon fire.$b$bI suppose they assumed we\'d be consumed by their fire, but we survived.$b$bIf you find this note, bring medical supplies to soothe our burns. Maybe then we can survive a bit longer.', `QuestDescription`) WHERE `ID` = 42340;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fevered Prayer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 15 Field Packs to the location marked on your map. Treat the Fevered Val\'sharah Refugees when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Dear gods whose names I really can\'t recall, please answer my prayer and send help.$b$bOur party was attacked by satyrs and now we\'re feverishly sick and could use some aid immediately.$b$bI believe writing this note is the correct way of summoning a god...', `QuestDescription`) WHERE `ID` = 42345;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloody Letter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Silkweave Bandages and 1 Field Pack to the location marked on your map. Treat the Gravely Wounded Kirin Tor Guardian when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know cats can climb trees, so I\'m pretty convinced that this nightsaber is just waiting for me to bleed out.$b$bI\'m attaching this note to a nearby owl I\'ve nicknamed "Hooty". Hopefully he finds someone to help me.', `QuestDescription`) WHERE `ID` = 42350;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloody Prayer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring 3 Silkweave Bandages and 1 Field Pack to the location marked on your map. Treat the Gravely Wounded Moonfall Defender when you arrive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is my last will and testament. To my husband, I leave the kids, the house, and the enormous wealth I\'ve accumulated... wait, no. To my sister, I leave the kids, the house and my estate.$b$bTo my husband, I leave my eternal love. Yes, he\'ll enjoy having that more.$b$bAlso, if someone finds this and can come find me before I bleed out, I\'d appreciate some medical attention.', `QuestDescription`) WHERE `ID` = 42351;
