UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Focusing the Energies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 3 Blood of Sargeras.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In addition to shards of nightmare, we need Blood of Sargeras to reactivate the portal to the Rift of Aln.$B$BThis rare reagent can be obtained from around the Broken Isles. Rumor has it that emissaries are in search of hardened adventurers, and may offer these in reward.', `QuestDescription`) WHERE `ID` = 42365;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Bigger They Are, The Harder They Fel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist Kyrtos with his ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have had it with these small fry, assistant. Time to go straight to the top.$b$bThe tome is the key! The key to unlocking the potential within our people.$b$bDo not worry, young one. I have enough power to complete the task at hand. Let us harness fel magic and change the future.$b$bFollow me and witness the redemption of the shal\'dorei!', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Assist Kyrtos with his ritual.', `AreaDescription`) WHERE `ID` = 42366;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arkethrax', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Arkethrax.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Within the Ingress is a demon who must die.$b$bArkethrax is a creature of cunning evil. If left unchecked he will be able to use the Ingress as a staging point for targeted assaults that will decimate our forces.$b$bI, for one, have no intention of underestimating this opponent and shall join you on the battlefield when you are ready to fight him.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Commander of Felblaze Ingress', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Arkethrax', `PortraitGiverName`) WHERE `ID` = 42367;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Quantity Over Quality', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay demons in the Felblaze Ingress.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demons of Felblaze Ingress are amassing at an exponential rate.$b$bWe must cull these invaders before they have enough demons to flank our forces at Illidari Stand.$b$bWill you join us in battle?', `QuestDescription`) WHERE `ID` = 42368;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'They\'re Doing it Wrong', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place 4 Sabotaged Portal Crystals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These demon portals are terrible and sloppy. No skill or finesse in it.$B$bThis physically hurts me and I haven\'t felt real pain in decades.$b$bI "fixed" some of the Legion\'s precious Portal Stabilizer crystals.$b$BI want you to take them and "modify" their main portal in the Ingress and watch the "hilarity" ensue.', `QuestDescription`) WHERE `ID` = 42369;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wanding 101', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Practice using your wand on $1oa Wand Targets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ll start with some wand work. You have your wand with you? Good.$b$bI\'ve set up a number of targets around the hall. Use your wand to hit as many as you can.$b$bAnd no point-blank shots! That\'s cheating.', `QuestDescription`) WHERE `ID` = 42370;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Study Hall: Combat Research', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the books that Sythorne requests, then help him defeat the challenges within.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What\'s this? A new, confused student, desperately trying to win the favor of the headmistress, wandering the halls without anything to do?$b$bPerfect! I need help with my research.$b$bI\'m writing a paper on combat. Grab me some books from the shelf over there.', `QuestDescription`) WHERE `ID` = 42371;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felblaze Ingress', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Tehd Shoemaker at Felblaze Ingress.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is my mission to cover the rear guard of Illidari Stand. I have employed this warlock... thing, to assist me.$b$bHowever, the two of us are insufficient for a task that needs doing.$b$bTo the east is a mass of demons at Felblaze Ingress. These creatures have begun to open portals to summon in countless reinforcements.$b$bMeet us at Felblaze Ingress and together we can crush this fel insurgency.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Tehd Shoemaker at Felblaze Ingress.', `QuestCompletionLog`) WHERE `ID` = 42372;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vengeance for the Stonedark', `LogTitle`) WHERE `ID` = 42373;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Greeting Kits - Tracking Quest', `LogTitle`) WHERE `ID` = 42374;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye See You', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Tehd\'s Eye of Kilrogg to investigate Felblaze Ingress.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is being blind, and then there is being stupid.$b$bThis eyeless wonder next to me wants to barrel into Felblaze Ingress without preparation.$b$bBah! I say we scout it first.$b$bHere, I will provide you with an extra eye I picked up from a place better left unmentioned.$b$BEnter Felblaze Ingress, investigate the area, and try not to get poked in the eye.', `QuestDescription`) WHERE `ID` = 42375;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Inquisitor Tivos', `LogTitle`) WHERE `ID` = 42376;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Brother\'s Trail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Dragonblight in Northrend and find Galford and his Spark of Tyr.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must reclaim the Silver Hand before those with evil intent can seize it. To free it from its wards, we need relics called the Sparks of Tyr. I have one, as does my brother, Galford.$b$bHe journeyed to Northrend to seek aid from the Tyr\'s homeland, but has not returned.$b$bI must ask you to find him, and his Spark.', `QuestDescription`) WHERE `ID` = 42377;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ox\'iloth', `LogTitle`) WHERE `ID` = 42381;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Stormcaller Mylra and Duke Hydraxis.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Earthen Ring is built upon the strength and dedication of its members.$B$BIf we are to help defend this world against the Burning Legion, we will need to grow our order, and recruit skilled champions to our side.$B$BBegin by speaking to Stormcaller Mylra and Duke Hydraxis. Perhaps they would be willing to fight for us.', `QuestDescription`) WHERE `ID` = 42383;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scouting Reports', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interact with the Scouting Map and complete "Scouting Reports".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In the recent past, our order has spent a lot of time watching and waiting. With you at the helm, we\'ll be able to focus on our original calling.$B$BTake a look around us, $n. Azeroth needs us now more than ever. The same enemy that led to our formation is threatening us once again.$B$BYou should send someone to gather reports from our scouts. From there, we\'ll be able to focus our efforts where they are needed most.', `QuestDescription`) WHERE `ID` = 42384;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lending a Hand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Hudson Crawford in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our scouts reported seeing a village in Val\'sharah being attacked by undead hounds.$B$BThis is the perfect opportunity for the Unseen Path to make good on our promise to help those in need.$B$BYou should head out to Bradensbrook and see what you can do to help.', `QuestDescription`) WHERE `ID` = 42385;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rising Troubles', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Risen Hounds in and around Bradensbrook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our village is swarming with beasts risen from the dead!$B$BThe abominations never rest! They attack night and day.$B$BWe\'re doing our best to keep them at bay, but it\'s getting to be more than the townsfolk can handle. They\'re tired and losing their will to fight.$B$BAnything you can do to lessen the burden would be greatly appreciated.', `QuestDescription`) WHERE `ID` = 42386;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assassin Entrapment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Set a trap at Carlisle Cottage to catch and kill Captain Tevaris.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Black Rook invaders are still targeting our farms and homes, even though there\'s not much left to pillage.nnWe had hoped that once they cleared us out that the attacks would stop, but it seems those mindless ghouls will follow any orders given by their commander.nnWe\'d take him out ourselves, but he\'s a sneaky fella. The only way we\'re going to catch him, is if someone lays a trap. I can provide the supplies if you\'re willing to help.', `QuestDescription`) WHERE `ID` = 42387;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Urgent Summons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Emmarel Shadewarden at Trueshot Lodge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The eagle appears to have a message for you:n$B|cFF660000             To: $n|r$b$bOur scouts have returned with reports from all over Azeroth. It seems that things are much worse than they initially seemed.$b$bReturn to Trueshot Lodge as soon as you can.$B$B|cFF660000             |r-Emmarel Shadewarden', `QuestDescription`) WHERE `ID` = 42388;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Calling Hilaire Home', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Beastmaster Hilaire in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With so many in need of our help, it may be time to call in some of our scouts in the field.$B$BOne such scout is a huntress by the name of Hilaire. Although she abandoned her clan long ago to join our order, she still feels a need to watch over them.$B$BHer dedication to protect those who would shun her is admirable, but we need her here.$B$BSeek Hilaire out in Stormheim, and let her know it\'s time to come home.', `QuestDescription`) WHERE `ID` = 42389;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting Rexxar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Rexxar in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To do the most good, we need the best hunters at our side.$B$BHaving you leading the order is a great start, but we\'ll need others who share your skill and expertise if we plan on making an impact.$B$BRexxar has a reputation of being one of the greatest hunters of his time, yet he\'s never been eager to aid the Unseen Path.$B$BHe has a camp just north of here, where he and Misha live off the land. Maybe you can convince him to join our ranks.', `QuestDescription`) WHERE `ID` = 42390;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bite of the Beast', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the beast responsible for the attacks and bring its head to the mages holding Cora captive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I will not leave my post without Cora.nnA group of mages have her caged up like a beast, threatening to put her down.nnThey claim she\'s responsible for the death of one of their own, but I refuse to believe that. Cora is a loyal and obedient companion; she would never attack without my command.nnI tracked the demon that was truly responsible to this location, but it put up quite a fight before getting away. My injuries prevented me from giving chase, but I am sure that beast has left a bloody trail.', `QuestDescription`) WHERE `ID` = 42391;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Survive the Night', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Survive a night within Cliff\'s Edge according to Rexxar\'s rules.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now it\'s time to put your skills to the test.$B$BYour order seems to be a lot of watching and waiting without a lot of action.$B$BProve me wrong. Show me that I might have something in common with the Unseen Path.$B$BIf you survive a night in the wild, then I will consider joining your order.', `QuestDescription`) WHERE `ID` = 42392;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Homecoming', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Emmarel Shadewarden at Trueshot Lodge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Cora has calmed enough to make the journey back to Trueshot Lodge.$B$BYou can let Emmarel know that we are on our way home.', `QuestDescription`) WHERE `ID` = 42393;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unseen Protection', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map to send your champions and troops on "Unseen Protection" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We will not let the city of Dalaran fall.$B$BIf the Legion is planning an attack, the Unseen Path will be there to stop it.$B$BOur scouts\' most recent reports list a few other areas that sound like they could really use our help, whether they realize it or not.$B$BAs soon as you\'re able, send your hunters to take care of the threats.', `QuestDescription`) WHERE `ID` = 42394;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Signaling Trouble', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Emmarel at the top of the southern watch tower.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Long ago, we gave select leaders special flares that were only to be used in times of great need.$B$BUpon seeing the flare, the leader of the Unseen Path is supposed to head to the southern watchtower to meet with whomever lit it.$B$BI don\'t know who we\'ll face once we reach the tower, but we must move quickly.', `QuestDescription`) WHERE `ID` = 42395;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Do The Thing!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '?????', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mrglrg! Mrlglr mrgllrg.$b$b<Phin gesticulates wildly>$b$bMrlgrlg glrglmglr mrlglrg. Rglrgmrg mrglr glr. Glr! Gmrlgrmlg mrglmrgm...$b$b<Phin looks at you expectantly.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', '?????', `AreaDescription`) WHERE `ID` = 42396;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Baron and the Huntsman', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Huntsman Blake in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve received word from Khadgar that he\'s lost contact with the mages he sent to investigate the Legion\'s camps. He\'s requested our assistance in tracking them down.$B$BIf we have any hope of locating those mages, we\'ll need to find ourselves a reliable hound capable of following a scent.$B$BThere is only one such hound that I know of, and he\'s long since retired. It\'s worth it to check in with his master, Hunstman Blake, and see if old Baron still has it in him.', `QuestDescription`) WHERE `ID` = 42397;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Awakening the Senses', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Baron awaken his senses by digging up Ancient Bones within the area.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m afraid old Baron here is past his prime. His nose can\'t catch a scent the way it used to. Others told me to put him down, but I can\'t bear the thought of losing my loyal friend.$B$BBaron was always at his best when working, though. Maybe if you let him wander through these fields and dig up some old bones, it\'ll be enough to awaken his senses.', `QuestDescription`) WHERE `ID` = 42398;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ready to Work', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Emmarel Shadewarden in Trueshot Lodge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If Baron\'s ready to work, I am too.$B$BWe\'ll make our way to the hunter\'s lodge as soon as I pack up camp and get this dog fed. I\'m sure with all that digging, he\'ll have a hearty appetite.', `QuestDescription`) WHERE `ID` = 42399;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missing Mages', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Archmage Khadgar in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Archmage has already made his way to Suramar, where the missing mages were last seen.$B$BBaron ran off, too. It seems that hound is eager to work again.$B$BMeet them both near the road that leads into the city. With any luck, Baron will be about to pick up on their magical scent and find the missing mages before it\'s too late.', `QuestDescription`) WHERE `ID` = 42400;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Scent of Magic', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Baron as he tracks the scent of the mages.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is the last known location of the missing Kirin Tor. There isn\'t much evidence, other than a torn piece of cloth, which looks to be from one of our tabards.$B$BThe scrap may be small, but it should be heavy with the essence of magic. We can only hope that Baron can catch the scent and track down the mages.', `QuestDescription`) WHERE `ID` = 42401;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Requesting Reinforcements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interact with the Scouting Map and complete the mission "Requesting Reinforcements".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Many powerful factions have pledged their loyalty to the Unseen Path. It\'s time that we call on them to help us defeat Hakkar and his demon hounds.$B$BSend your champions into the field to track down these leaders and let them know we require their help.', `QuestDescription`) WHERE `ID` = 42402;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Highmountain Hunters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Hemet Nesingwary in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve just received word from our scouts that they\'ve identified some potential recruits.$B$BIt seems as though the famed Hemet Nesingwary has set up camp not too far from our lodge.$B$BWhile he isn\'t traditionally the type of hunter we\'d invite into our ranks, his experience hunting large game could come in handy.$B$BHead on over to his retreat and see if he\'s willing to aid our cause.', `QuestDescription`) WHERE `ID` = 42403;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assisting the Archmage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Emmarel Shadewarden at Trueshot Lodge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hakkar maintains an army of felhounds that feed off of magic. As long as he remains within Azeroth, no mage will be safe.$B$BHe and his hounds are immune to most spells, so I must ask for assistance in killing them.$B$BYou have proven yourself more than capable, but are you willing to help take down this demon?', `QuestDescription`) WHERE `ID` = 42404;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Informing Our Allies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archmage Khadgar, Halduron Brightwing, Vereesa Windrunner, and Shandris Feathermoon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Leaders from some of the greatest military factions are here, ready and willing to help.$B$BThey\'re currently waiting to speak with you directly, hoping to provide insight on how they can help.$B$BWith any luck, we can pull our resources and find a way to take Hakkar down.', `QuestDescription`) WHERE `ID` = 42405;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Tame the Beast', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Leyworm Bait while in Felbeast Dens to lure and trap a felhound fledgling.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deep in the heart of Faronaar are dens that are overrun with felhounds. If Hakkar is breeding those beasts, that is the place he would do it.$B$BThe bait I\'ve crafted is potent. Once you apply it, you\'ll draw the attention of nearby hounds, so only use it when you\'re close to the dens.$B$BOnce the demon has taken the bait, get it into a weakened state to make trapping easier.$B$BGood luck, $n. I hope you return in one piece.', `QuestDescription`) WHERE `ID` = 42406;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nature of the Beast', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Emmarel Shadewarden at Trueshot Lodge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'By nature, this demon is immune to magic, but it has also been bred to be resistant to physical attacks. It\'s covered in scales unlike anything I\'ve ever seen; layered and thick. I doubt that most metals will be able to pierce the demon\'s armor-like hide.$B$BUnless your entire army has weapons like yours, I suggest fighting those beasts with something that will exploit their weakness.', `QuestDescription`) WHERE `ID` = 42407;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Required Reagents', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the required crafting reagents.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Sentinels know of a trusted and talented enchanter who specializes in enchantments that affect demons.$B$BShe provides her services for free to the Sentinels, but she does require specific reagents to perform her enchantments.', `QuestDescription`) WHERE `ID` = 42408;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Loren Stormhoof', `LogTitle`) WHERE `ID` = 42409;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Rexxar', `LogTitle`) WHERE `ID` = 42410;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Beastmaster Hilaire', `LogTitle`) WHERE `ID` = 42411;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Huntsman Blake', `LogTitle`) WHERE `ID` = 42412;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Hemet Nesingwary', `LogTitle`) WHERE `ID` = 42413;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Addie Fizzlebog', `LogTitle`) WHERE `ID` = 42414;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Halduron Brightwing', `LogTitle`) WHERE `ID` = 42415;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Council is in Session', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to the Council of Six in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Vargoth\'s involvement with the Empyrean Society is troubling. However, as he has proven his loyalty to the Kirin Tor many times, we must give him the benefit of the doubt for now. nnStill, I am obligated to share our concerns with the rest of the Council. You had best travel to Dalaran and meet with them in the Violet Citadel. I will remain here to care for our old friend.', `QuestDescription`) WHERE `ID` = 42416;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bilebrain', `LogTitle`) WHERE `ID` = 42417;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Unexpected Visitor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet up with Ravandwyr.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Vargoth\'s long-time apprentice, Ravandwyr, has arrived here in the Hall of the Guardian with an urgent message from his mentor.nnHe will be waiting for you upstairs. You had best find him quickly, $n!', `QuestDescription`) WHERE `ID` = 42418;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Court of Farondis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete any 4 world quests in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Assist the Court of Farondis in Azsuna by completing 4 world quests.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Veridis Fallon in Azsuna.', `QuestCompletionLog`) WHERE `ID` = 42420;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nightfallen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete any 4 world quests in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Assist the Nightfallen of Suramar by completing 4 world quests.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to First Arcanist Thalyssra in Suramar.', `QuestCompletionLog`) WHERE `ID` = 42421;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wardens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 4 Wardens world quests.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Assist the Wardens by completing 4 world quests.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Marin Bladewing at the Isle of the Watchers.', `QuestCompletionLog`) WHERE `ID` = 42422;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Archmage Vargoth\'s Retreat', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate Archmage Vargoth\'s quarters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Vargoth has been absent for a while. You may have a look around his living quarters here in the citadel tower, $n. Kalec will escort you there.nnI will hold out hope that our esteemed colleague is merely up to his usual eccentricities.', `QuestDescription`) WHERE `ID` = 42423;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Following In His Footsteps', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ask your champions to investigate Archmage Vargoth\'s travels.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Vargoth seems to be mixed up in something dangerous, not that that\'s unusual for an archmage of his caliber and experience!nnThe Arcway Vaults may be where he\'s headed, but we should investigate all leads in order to get a better idea of what he\'s up to.', `QuestDescription`) WHERE `ID` = 42424;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Going Down, Going Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Oren\'s Rappel Point to descend into the depths and recover his lost possessions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have the necessary worm guts, I was able to fashion them into a special sort of rope.nnIt will allow you to descend from the bridge into the chasm below and recover some of my possessions that were stolen and thrown in by the Deeprock.', `QuestDescription`) WHERE `ID` = 42425;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest: Test Enabled', `LogTitle`) WHERE `ID` = 42426;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest', `LogTitle`) WHERE `ID` = 42427;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Shrine of Ashamane', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Danise Stargazer and travel to Ashamane\'s Fall in search of Delandros Shimmermoon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The mighty Ancient, Ashamane, fell in battle against the Burning Legion ten thousand years ago. To honor her sacrifice, a group of devoted druids called the Ashen forged Ashamane\'s fangs into powerful daggers.$b$bTake my signet and present it to their leader, Delandros Shimmermoon. He will know that you have my blessing.$b$bOur flight master, Danise Stargazer, can see you to the shrine.', `QuestDescription`) WHERE `ID` = 42428;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Memories of Ebonchill', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find a Reflection of the Council of Tirisfal in Dalaran City. Speak with one to receive his or her wisdom.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Is that Ebonchill you\'ve got there? Alodi\'s old staff? My my my... <Cough>$b$bIn the days of the first guardian, all the members of the Council of Tirisfal granted their powers to the young mage in the hopes that he could overcome the Legion. <Wheeze> None of them are alive today... but that staff of yours remembers.$b$bSearch the streets of Dalaran below for reflections of the former council members. Their memories may empower you as they once did Alodi. Seek them out and speak with one!', `QuestDescription`) WHERE `ID` = 42429;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fangs of Ashamane', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mount upon Ebonfang and search for the Fangs of Ashamane.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have to admit, Verstok was right. The shrine was too easy of a target for the Burning Legion to attack. Still, he\'s gone and the Fangs are with him.$b$bWe\'re going to have to track him down for you to recover the Fangs. I should come with you but I have to stay with my people should we be attacked again.$b$bHere, my companion Ebonfang has a sense of smell like no other. He will be able to guide you to wherever Verstok is hiding. Also take this shell, through it we can communicate.$b$bMay Elune guide you.', `QuestDescription`) WHERE `ID` = 42430;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Brood of Nithogg', `LogTitle`) WHERE `ID` = 42431;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Emerald Nightmare: The Emerald Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Emerald Nightmare raid on any difficulty and defeat Lord Xavius.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Lord of Nightmare, Xavius, is still out there. Cenarius is still in grave danger, deep within the Rift of Aln.$B$BSummon your greatest allies, $n. If we are to stare into the face of the Nightmare, we had best be ready.$B$BOnce you are ready, enter the Emerald Nightmare and defeat all the horrors you find there.', `QuestDescription`) WHERE `ID` = 42432;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ancient Magic', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interact with your Scouting Map and complete the mission, "Ancient Magic."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Since the Broken Isles is the epicenter of ancient night elven learning, there must be countless magical artifacts secreted away in forgotten vaults and reliquaries. We must secure them so they do not fall into the wrong hands!nnPerhaps you should send a champion in search of them.', `QuestDescription`) WHERE `ID` = 42433;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Covert Operation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Ravandwyr in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your champion discovered some sort of powerful magic emanating from the secretive Empyrean Society enclave in Azsuna. nnArchmage Vargoth asked me to request Meryl\'s aid in investigating it, but as you can see, Meryl is clearly too ill to travel at the moment. Would you be willing to go in his place?nnYou will need to prove yourself in order to gain entrance. We should be able to find something sufficient in the Hatecoil Warcamp in Azsuna.', `QuestDescription`) WHERE `ID` = 42434;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prepare To Be Assimilated', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Pearl of Arcane Wisdom and 5 Nar\'thalas Scrolls and meet up with Ravandwyr north of the Empyrean Enclave.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Empyrean Society is a dangerous cult. They claim to study all magic regardless of its source, but in reality they focus mostly on the forbidden. They will welcome you to their enclave if you bring them a magical artifact.nnThe Hatecoil naga have found the perfect gifts - a Pearl of Arcane Wisdom and scrolls from the depths beneath the Nar\'thalas Academy. You will have to convince them to part with a few.nnI will meet you on the road just north of the Empyrean Enclave.', `QuestDescription`) WHERE `ID` = 42435;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aiding Our Allies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver supplies to Meliah Grayfeather.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our Skyhorn allies could use some assistance. nnTheir ongoing war with the invading harpies has left them low on supplies. nnAnything we can give them will surely help with their efforts to rid those witches from their village.', `QuestDescription`) WHERE `ID` = 42436;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Starbuck', `LogTitle`) WHERE `ID` = 42437;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seeds of Renewal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Delandros Shimmermoon wants you to search the forests of Mistvale and obtain three Tel\'andu Seeds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Fangs of Ashamane are in danger, $n. For ten thousand years a powerful magic ward has protected them from any would-be thieves, but the ward has weakened over time and is in danger of failing. My three most trusted Ashen have the Tel\'andu seeds we need to perform the ritual of renewal,  but the woods are now crawling with demons and I fear they have fallen.$b$bNo matter what, we cannot allow the Legion to obtain the Fangs! Go and find the Tel\'andu seeds, we must hurry before the ward can be broken!', `QuestDescription`) WHERE `ID` = 42438;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aid for the Ashen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat $1oa Eredar Soul Lashers and free their captives.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Turn your eyes above and you will see the cause of our misfortune. Ever since that ship appeared the attacks have been relentless. Many of the Ashen have been captured and even now I can hear their screams of torture.$b$bPlease, go out there and rescue as many of my followers as you can. They do not deserve the fate that awaits them if left in the Legion\'s grip.', `QuestDescription`) WHERE `ID` = 42439;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Shrine in Peril', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist Delandros by removing the last of the attackers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve helped us greatly, champion. Now, it is time that you tell me what brings you here.$b$b<You mention to Delandros that Archdruid Greathoof sent you to seek the Fangs of Ashamane.>$b$bHrm... if you had told me this at the outset, I would have told you to take a walk. The Fangs are our greatest treasure, but you\'ve done a great deed for the Ashen today and I am an elf of my word.$b$bVery well, let\'s clear out the rest of these demons and you shall have your weapons.', `QuestDescription`) WHERE `ID` = 42440;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fight Night: Amalia', `LogTitle`) WHERE `ID` = 42442;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arluin Wants In (Tracking Quest)', `LogTitle`) WHERE `ID` = 42443;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Plight of the Blackfeather', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow the frightened ravenbear to the Blackfeather chieftain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The ravenbear frantically gestures and points down the path. nnIt seems he wants you to follow him.>', `QuestDescription`) WHERE `ID` = 42444;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nithogg\'s Tribute', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Intact Greatstag Antlers and 16 Pristine Eagle Tailfeathers in the Stormtorn Foothills.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It looks like the ravenbears have started gathering materials for some sort of tribute, but the storm drakes are keeping them from finishing what they started.  nnFrom the looks of it, they\'re gathering fully intact stag horns and long tail feathers from the greatstags and eagles nearby. nnIt shouldn\'t take too long to gather the rest of what they need.', `QuestDescription`) WHERE `ID` = 42445;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Singed Feathers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 8 Rampaging Squallhunters in the Stormtorn Foothills.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ca-caw! Caw caw!nn<The chieftain flaps his wings and points outside where the storm dragons attack the ravenbears of his tribe. nnIt\'s plain to see that he\'s seeking your help to save his flock.>', `QuestDescription`) WHERE `ID` = 42446;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dances With Ravenbears', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help the Blackfeather ravenbears perform their tribute ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The chieftain beckons for the ravenbears to gather the tribute and gestures toward the ritual circle outside.>nnCaw! Caw ca-caw!nn<It looks like he wants you to follow.>', `QuestDescription`) WHERE `ID` = 42447;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return of the Four Horsemen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Thassarian in Durotar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The voice of the Lich King has spoken, Deathlord, and the Knights of the Ebon Blade will obey your command.$b$bThe Four Horsemen were no ordinary death knights, they were born of pure, unholy power gifted from the Lich King to Kel\'thuzad.$b$bThis unholy power to raise the dead has now been passed to you, Deathlord. I am sure you will wield it with great conviction.$b$bThe Four Horsemen will be powerful allies against the Burning Legion... and Nazgrim is a worthy choice as the firstborn.', `QuestDescription`) WHERE `ID` = 42449;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Brawlgoth', `LogTitle`) WHERE `ID` = 42450;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Kalec\'s Plan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Kalecgos on the ridge near the Arcway Vaults.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your champion was unable to penetrate very far inside the Arcway Vaults due to the heavy legion presence around it.  Hopefully you will have better luck following Archmage Vargoth inside.nnKalecgos will be waiting for you on the ridge overlooking Felsoul Hold.', `QuestDescription`) WHERE `ID` = 42451;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Finding Ebonchill', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the forgotten stacks in the Hall of the Guardian for clues to Ebonchill\'s last known master, Arrexis.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ebonchill bears a lineage of powerful wielders dating back to its maker, Alodi. He passed it on to his favorite apprentice and so on until... the archmage Arrexis, I believe.$b$bArrexis disappeared sometime around the First War. I know nothing of his fate, but the answer may well be somewhere in this library.$b$bStart by looking around here. Whatever you find should lead us to Ebonchill.', `QuestDescription`) WHERE `ID` = 42452;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Highmountain - Treasure 103 - Medium (RKS)', `LogTitle`) WHERE `ID` = 42453;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hammer of Khaz\'goroth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the central teleporter in Dalaran and then place the Hammer of Khaz\'goroth in Aegwynn\'s Gallery.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Now that you have defeated Dargrul the Underking and have the Hammer of Khaz\'goroth in hand, it is time to place it in Aegwynn\'s Gallery in the lower chambers of Dalaran.>', `QuestDescription`) WHERE `ID` = 42454;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Alodi\'s Gems', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gain access to Alodi\'s personal bank vault in Dalaran and retrieve the Mana Gems.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Arrexis had a cadre of apprentices and subordinates to help him with the ritual, something you are currently lacking.$b$bIn older times, when magic was less understood and spells required vast amounts of mana to cast, we stored mana in gems for use in complex spells.$b$bLucky for us, I still have a few powerful Mana Gems in my vault, along with some other useful items. You merely need to go to the Bank of Dalaran and gain access.', `QuestDescription`) WHERE `ID` = 42455;
