UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Deadwind Site', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and retrieve information on the ritual from Arrexis\'s campsite near Karazhan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your research spoke of an experimental site out near Karazhan. I hope there are still materials on this ritual that will aid us there.nnYou will need to find the site and bring back anything that will help us recreate the ritual. I will dig deeper here as well.', `QuestDescription`) WHERE `ID` = 42476;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Daio the Decrepit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Fly to the Tainted Scar in the Blasted Lands and get information from Daio the Decrepit.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That text lists someone named Daio as being instrumental to the demonic ritual. They can\'t possibly mean Daio the Decrepit!$b$bI never knew he was Kirin Tor. I only know him as an elderly warlock who trains young recruits in the infernal arts. This would certainly explain his change of occupation.$b$bHe most likely holds key information for this to work. Though retired, I believe he is still out in the Tainted Scar in the Blasted Lands. You should seek him out.', `QuestDescription`) WHERE `ID` = 42477;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Mage Hunter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recreate Arrexis\' ritual in Faronaar and defeat Balaadur.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'And with that, we have what we need to recreate the ritual... however flawed it may be. It must be conducted somewhere highly visible so that word reaches our target swiftly.$b$bI\'ve heard reports that the Legion is heavily invested in the Faronaar region of Azsuna. An excellent place to begin a ritual they won\'t want us to complete.$b$bThe chances of us dying horribly are exceptionally high.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Meryl in the Hall of the Guardians.', `QuestCompletionLog`) WHERE `ID` = 42479;
