UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Put It All on Red', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Steelscale\'s Fin from Steelscale in Citrine Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All right, I\'ve got one last beasty to send you after. He\'s a bit far out, but trust me, it\'ll be worth it. This one I put a huge wager on!nnAlong the eastern coast swims a great shark the locals call Steelscale. They say his hide is near impenetrable.nnBut you\'re gonna prove them wrong, aren\'t ya chum? Bring me his fin, and those tauren will have to fork over a princely sum.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'The menace of Citrine Bay.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Steelscale', `PortraitGiverName`) WHERE `ID` = 42483;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Firstborn Rises', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise Nazgrim as a Death Knight.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'General Nazgrim was one of the finest warriors our world has known, and his loyalty was unsurpassed... even for an orc.$b$bHe deserves the peace of death, but this world cries out to be saved. The time for rest is over...$b$bCome, Deathlord... let us welcome Nazgrim into the arms of the damned.', `QuestDescription`) WHERE `ID` = 42484;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSE ME', `LogTitle`) WHERE `ID` = 42485;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Little One Lost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort Korine back to her mother Verene at the Waning Crescent.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m ready to go home now, but there are still scary men outside...nnWill you stay with me? Make sure they don\'t take me away?nnI don\'t want to go back in the cage...', `QuestDescription`) WHERE `ID` = 42486;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Friends On the Outside', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the teleporter pad and bring Vanthir\'s gift to Thalyssra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have done well for us here, but it is time for you to return to Thalyssra.nnThere is a teleporter pad nearby that has gone unused in recent years. See if you can reroute it and return to her that way.nnOh, and before you go:nn<Vanthir hands you a wrapped bottle of Arcwine.>nnTake this to her, with my thanks for sending you. Let her know that your efforts helped replenish our Arcwine supplies and reunited a mother and child.nnWe are grateful beyond measure. Farewell for now.', `QuestDescription`) WHERE `ID` = 42487;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thalyssra\'s Abode', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search Thalyssra\'s estate and collect 3 Amplifier Fragments. Combine them into an Arcane Amplifier.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you were busy in the city I reached a roadblock in my withered research. nnI feel I am close to overcoming this barrier, but I\'m afraid I cannot do so without some more advanced tools.nnI hid among my possessions an item called an Arcane Amplifier. It does precisely what its name entails.nnIt is more than likely that the Magistrix ordered my estate dismantled. If the Amplifier remains, it will be in fragments.nnRecover the whole, if you can.', `QuestDescription`) WHERE `ID` = 42488;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thalyssra\'s Drawers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search Thalyssra\'s estate and collect her belongings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thalyssra\'s ransacked estate still contains a number of items important to Thalyssra. Collect them and return them to her.', `QuestDescription`) WHERE `ID` = 42489;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Arcway: Opening the Arcway', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Advisor Vandros in the Arcway.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deep beneath Suramar is a defunct set of tunnels known as the Arcway. They were abandoned when a disaster disrupted the mana collectors operating there. nnI know not what awaits you down there, but I do know one thing.nnWe are not the only ones interested in this place. Make enough noise and one of the advisors with whom I served under Elisande is sure to appear.nnHis name is Vandros. Slay him, if you can.nnHis death will be our victory, as we deprive Elisande of one more weapon in her arsenal.', `QuestDescription`) WHERE `ID` = 42490;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Arcway: Long Buried Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire the Suramar Leyline Map from the Arcway.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Beneath Suramar City is an ancient network of tunnels known as the Arcway.nnThey were abandoned some time ago as part of the cavern became unstable. Since then, who knows?nnRegardless of what is currently down there, I believe you will find something essential to our continued success.nnLong ago my people took a thorough survey of the ley lines in and around Suramar. This they would have stored in the library in the Arcway. nnFind this map for me.', `QuestDescription`) WHERE `ID` = 42491;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'PH: Withered Scenario', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'PH', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'PH', `QuestDescription`) WHERE `ID` = 42492;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Impending Dooooooom!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the Nightborne Vault.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Millhouse attracts trouble, so he\'s sure to find Archmage Vargoth if he\'s still here. nnOh and if you do find the Nightborne Soulstone, best get it first!', `QuestDescription`) WHERE `ID` = 42493;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'More Than Just A Food Vendor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Eradicate 15 demons and give your conjured food to 10 starving prisoners.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your champions made a good dent in thinning out the enemy\'s numbers. They also discovered a number of starving prisoners who could use our help. Your Conjured Mana Pudding or Fritters will be useful in getting them up on their feet. nnYou should also dispatch as many of the remaining legion invaders back to the twisting nether as you can!', `QuestDescription`) WHERE `ID` = 42494;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ashbringer Chosen', `LogTitle`) WHERE `ID` = 42495;
