UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Finishing the Job', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assassinate Cade Shadowgaze at the Altar of Storms in Blasted Lands and search his body for information.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Garona set out to assassinate the leaders of a Legion cult some time ago. We haven\'t heard from her since.$B$BTo make matters worse, she took the Kingslayers with her. She knows they bring out the worst in her!$B$BYour best bet to find Garona is by continuing her work. Our intel points to a warlock by the name of Caden Shadowgaze inducting new recruits at the Altar of Storms in Blasted Lands. See if he has anything useful in his pockets.$b$bOnce he\'s dead, I mean.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Caden Shadowgaze', `PortraitGiverName`) WHERE `ID` = 42501;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'No Sanctuary', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assassinate Felcaller Whitley at Raven Hill in Duskwood and search his body for information.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have one other lead that may prove useful. Goes by Felcaller Whitley, another of the cult\'s elite. He\'s eluded our agents at every turn.$B$BOur latest reconnaissance report puts him somewhere in the village of Raven Hill in Duskwood. He\'s sure to have information vital to your search.$B$BYou know what to do.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Felcaller Whitley', `PortraitGiverName`) WHERE `ID` = 42502;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Codebreaker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Fel Cipher to decrypt the Coded Message and learn where you can find the cultists next.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The coded message you obtained is protected by powerful magic, rendering it indecipherable by conventional means.>$B$B<If you use the cipher you took from Felcaller Whitley you might be able to crack the code, leading you ever closer to both the cult\'s base of operations and Garona.>', `QuestDescription`) WHERE `ID` = 42503;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Unseen Blade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Garona take out the Veiled Hand cultists in Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We can\'t let Stormwind fall to the Legion, and I don\'t trust Shaw or his SI:7 goons to take care of the Hand on their own.$B$BThe two of us need to handle this while there\'s still time.$B$BThe entire city is on edge from murmurs of the cult\'s activities. They\'re as likely to turn on you as they are the cultists if you aren\'t careful.$B$BThe other Shadows spoke highly of your skills. Are you in?', `QuestDescription`) WHERE `ID` = 42504;
