UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Not A Toothless Dragon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ride with Kalecgos to the Arcway Vaults.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Arcway Vaults have been buried and untouched for thousands of years. We have the legion to thank for it being accessible once again, though I would give much for it to remain hidden.nnI think we are not far behind Archmage Vargoth\'s heels and he may yet be inside the vaults. We should make haste if we hope to intercept him.', `QuestDescription`) WHERE `ID` = 42508;
