UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Immortal Soul', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Make the Blood Offering to complete the ritual and contact the soul of Illidan Stormrage.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Illidan\'s immortal demon soul is lost somewhere in the vastness of the Twisting Nether. Contacting him risks much, the Nether is full of creatures of unimaginable power and appetites. But, it must be done if we are to move forward.nnThe ritual can be performed using the nether crucible. Make the blood offering, $n.', `QuestDescription`) WHERE `ID` = 42510;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Twisted Souls', `LogTitle`) WHERE `ID` = 42511;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Highmountain Stands', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Dargrul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That will have to do. Dargrul has come and we need every able body on the front line. Go, I will be right behind you.', `QuestDescription`) WHERE `ID` = 42512;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ashamane\'s Fall', `LogTitle`) WHERE `ID` = 42513;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archdruid Rensar Greathoof at the Dreamgrove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archdruid Rensar Greathoof has requested your presence.$B$BOur campaign to defend the Broken Isles is getting under way, and we need you at the helm.', `QuestDescription`) WHERE `ID` = 42516;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ritual of Doom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Perform the Ritual of Doom at the Summoning Platform within Dreadscar Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your research has granted you access to a very powerful ritual, one that will require the aid of a few friends if you wish to successfully summon a demon.nnThe ritual needs to be performed at the summoning platform above. nnKeep in mind, this sort of power always comes at a price. Not all who participate in the summoning will survive, so be prepared.', `QuestDescription`) WHERE `ID` = 42517;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Emmarel Shadewarden and Loren Stormhoof.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As leader of our order, other hunters will look to you for guidance. Many will be willing to pledge themselves to you, doing whatever is necessary in the name of the Unseen Path.$B$BI know of two within our ranks who are impressed with what they\'ve seen from you so far, and want to help any way they can.$B$BSeek them out, and let them ease the burden of leadership.', `QuestDescription`) WHERE `ID` = 42519;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Terrible Loss', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I would say I am surprised by this terrible turn of events, but nothing surprises me of late. It is dark times when even the most upstanding of us can fall... nnWe had best inform Archmage Khadgar of Vargoth\'s betrayal.', `QuestDescription`) WHERE `ID` = 42520;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Enemy of My Enemy...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Millhouse Manastorm.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Millhouse Manastorm has been quite vociferous about his intention to acquire the Nightborne Soulstone. If you find him, you may as well make use of him. nnHowever, he is unpredictable at best and you should always watch your back around him, $n. Use my crystal to contact me once you have located him.', `QuestDescription`) WHERE `ID` = 42521;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leader of the Illidari', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Head upstairs and take your place as the new leader of the Illidari.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Illidan has officially placed you in charge, $n. The Illidari are now yours.nnMeet me upstairs. We will let everyone know together.', `QuestDescription`) WHERE `ID` = 42522;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Making Contact', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Lenara Needs Help."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have recruited champions for our order, we can use the Scouting Map to complete vital assignments across the Broken Isles.$B$BOver the years our scouts have kept a close eye on hunters that might one day be added to our ranks. One such hunter, Lenara, was on her way to Trueshot Lodge when she was attacked.$B$BI suggest that we send Loren Stormhoof on a mission to rescue her. He may be uniquely suited to this task.', `QuestDescription`) WHERE `ID` = 42523;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting The Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Recruiter Lenara and train a troop of archers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our champions acquired the talents of Recruiter Lenara, an extraordinary archer.$B$BShe can hit the smallest of targets at extended ranges. Her arrows never miss.$B$BSpeak to her now and train a squad of archers.', `QuestDescription`) WHERE `ID` = 42524;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Troops in the Field', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Troops in the Field."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s time to send our newly trained archers out into the field. Look at the Scouting Map and send your champions and troops on a routine scouting mission.', `QuestDescription`) WHERE `ID` = 42525;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tech It Up A Notch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Survivalist Bahn in Trueshot Lodge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are very fortunate to have come across Survivalist Bahn. He spent his younger years living off the land in Pandaria, relying on the native flora and fauna to survive.$B$BHis firsthand experience with building from limited resources could really help shape Trueshot Lodge into something great.$B$BSpeak to him now and see what he can do for us.', `QuestDescription`) WHERE `ID` = 42526;
