UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Ruined Kingdom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Prince Galen Trollbane in Stromgarde.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So the Lich King has revealed the second of the Four Horsemen... it appears that not even kings may rest as the world burns around them.$b$bSo be it, Deathlord.$b$bI will send Nazgrim and Thassarian to meet you at the fallen kingdom of Stromgarde.$b$BPrince Galen Trollbane holds the key to the tomb of his father, a famous sword known as Trol\'kalar. In order to raise the king as the second of the Four Horsemen, we will need to gain entrance to the tomb.$b$bDo what you must to persuade Galen assist us...', `QuestDescription`) WHERE `ID` = 42533;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Our Oldest Enemies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 15 Witherbark Troll heads.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I will grant the Ebon Blade access to my father\'s tomb. First though, I must ask a favor.$b$bI have taken up the sword and banner of my father. I have reclaimed Stromgarde with its former citizens as my guard. Yet, one task remains.$b$bWitherbark invaders have blockaded themselves in the former mage district of the city. My men have suffered heavy losses at their vile hands.$b$bCut them down to the last! Bring me their heads and I shall give you what you seek.$b$bYou have my word as the King of Stromgarde.', `QuestDescription`) WHERE `ID` = 42534;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Death... and Decay', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Blight 10 Witherbark Supplies.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My family has fought the Witherbark trolls for generations... their presence in Arathi has always been a curse upon the land. I want to drive them out of Stromgarde for good!$b$bDestroy their supplies and we shall give them no incentive to return. Blight their supplies... or whatever it is you death knights do to defile things. I care not.$b$bJust make sure that it is done!', `QuestDescription`) WHERE `ID` = 42535;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Regicide', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain Trol\'kalar from Prince Galen Trollbane.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Galen Trollbane is a fool if he thinks that he can betray the Ebon Blade.$b$bI have had enough of his games. The fallen prince wastes our time playing the king of a ruined throne, while heroes sacrifice their lives to save this world.$b$bIf Galen Trollbane will not open the tomb of his father, then we must take the sword and do it ourselves.$b$bIf he chooses to resist, so be it.', `QuestDescription`) WHERE `ID` = 42536;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The King Rises', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise King Thoras Trollbane as a Death Knight.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'King Thoras was one of the greatest warriors this world has known.$b$bHis people loved him and his enemies feared him. He only ever spoke truth, often saying the words others were afraid to speak.$b$bKing Thoras lived a life of war and he certainly deserves the peace of death. But this is not a man who would sleep peacefully while the world around him burns.$b$bThe time has come, Deathlord, to welcome the last true King of Stromgarde into the arms of the dead and damned.', `QuestDescription`) WHERE `ID` = 42537;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest', `LogTitle`) WHERE `ID` = 42538;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cloak and Dagger', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Skull of the Innocent, the Blood of the Innocent, and make an attempt on Althea Ebonlocke\'s life in Darkshire.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The cultists seem to have a base of operations in Darkshire. At least Althea Ebonlocke is a member, but it is likely that the entire Night Watch has been compromised.>$B$B<The best course of action for now is to retrieve the dark implements for their ritual and make an attempt on Althea\'s life. Garona will have to wait.>', `QuestDescription`) WHERE `ID` = 42539;
