UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cursed to Wither', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the nightfallen that entered Leyhollow.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So Cedonu said he saw nightfallen going into Leyhollow?$b$bI don\'t like the sound of that.$b$bGrandfather seems to be holding his own, but the archmage and I will keep an eye on him. You go investigate our caves.', `QuestDescription`) WHERE `ID` = 42567;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Preparation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Garona Halforcen outside Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<With Althea\'s escape there is only one place to go: Stormwind.>$B$B<If Garona is keeping a similar pace on the cult\'s trail, she\'s bound to be making preparations to enter the city herself.>$B$B<Finding her is paramount before moving into the city.>', `QuestDescription`) WHERE `ID` = 42568;
