UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Zen\'tabra and Naralex.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion\'s defeat cannot be accomplished alone.$B$BTo win this war, we must work together, just as we did in ancient times.$B$BTo begin, we must recruit more druids to our aid. Speak to the troll Zen\'tabra and the night elf Naralex.$B$BBoth of them are accomplished druids. They will gladly defend the Dreamgrove.', `QuestDescription`) WHERE `ID` = 42583;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sister Lilith', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission "Sister Lilith".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We will need more allies on our side before we can be effective, Archdruid. A skilled dryad by the name of Sister Lilith is on her way to the Dreamgrove, but we\'ve received word that she may be in trouble.$B$BSend Zen\'tabra to her aid.', `QuestDescription`) WHERE `ID` = 42584;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting the Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Sister Lilith and recruit some Treants.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In our champions\' travels, they made contact with Sister Lilith, a fearless leader among the Laughing Sisters.$B$BShe is revered among the dryads as a seasoned warrior and a demanding teacher. She will serve as an excellent recruiter.$B$BSpeak to her now, and recruit some Treants.', `QuestDescription`) WHERE `ID` = 42585;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Glade Defense', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission,"A Glade Defense."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have a new mission that needs our attention, Archdruid. Deep in the forests of Val\'sharah, a small druidic outpost known as Shal\'doren Grove is under attack by satyrs.$B$BSend our champions to deal with this threat at once, $n. We cannot allow these satyr incursions to grow unchecked!', `QuestDescription`) WHERE `ID` = 42586;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Branching Out', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Leafbeard the Storied at the Dreamgrove in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Leafbeard is known as the Storied for good reason.$B$BIt is said that he remembers tales from before the Sundering. After examining the inscribed leaf that our champions recovered, he may be able to provide new knowledge and improvements for the grove.$B$BGo take it to him now.', `QuestDescription`) WHERE `ID` = 42588;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moozy\'s Reunion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Ethel Waterwise and reunite her with her family at the Hammer\'s Cradle in Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You will never know how thankful we are to you, $r. Because of you, Moozy and my husband are safe. I won\'t let either of them out of my sight!nnI am sorry to ask one last favor of you, but do you think you could find my mother and bring her here so she can see that her grandchild is safe?nnHer name is Ethel, and her home is on the northern bluff of Thunder Totem.', `QuestDescription`) WHERE `ID` = 42590;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette - Hannval the Butcher', `LogTitle`) WHERE `ID` = 42591;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Arcane Way', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Archmage Lan\'dalock at the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Getting into the Black Temple is going to be tricky. Following the break-in by the Council of the Black Harvest, Akama had his Sha\'tari priests erect a holy barrier. It prevents my teleportation.nnHowever, I might know a way to bypass those protections and take us directly to the Temple Summit.nnLong ago, I had a... liaison with a certain high elf wizard named Lan\'dalock. He later joined the Kirin Tor.nnIf you were to ask him very nicely, and drop my name, I am certain that he would help.', `QuestDescription`) WHERE `ID` = 42593;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Move Like No Other', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Chase down the Sneaky Imp and recover the Grimoire of Arcane Ways.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Sorry about the holographic projection... I literally need to be in two places at once these days.nnA holy barrier that protects against fel magic, you say? I have just the thing to bypass it and enable Malevolence\'s teleport.nn<The high elf rummages around in his pack, a shocked look quickly coming over his face.>nnSneaky! Look there... that imp just made off with it!', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Catch the imp and recover the Grimoire of Arcane Ways!', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Sneaky Imp', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Belath Dawnblade on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42594;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shaman Shrine - Azsuna Water 01 - DGK', `LogTitle`) WHERE `ID` = 42595;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mountainstrider Round-Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find $1oa Frightened Mountainstriders and return them to Liza Galestride\'s stable.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Stranger! You are the one I have heard of?nnWhen the kerfuffle with the drogbar happened, some of the young moose ran off!nnI can\'t chase them down or the others might wander off as well.nnCould you bring them back here?', `QuestDescription`) WHERE `ID` = 42596;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Odyn\'s Summons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Odyn in Skyhold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Odyn would like to speak to you at once, my liege.$B$BHe is convinced that as you have grown in power you are ready to take direct command of his armies and would like to begin preparations.', `QuestDescription`) WHERE `ID` = 42597;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champions of Skyhold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Ragnvald Drakeborn and Finna Bjornsdottir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You will soon command one of the greatest armies in existence, but before my own Valarjar follow your every command you must prove your ability to lead.$B$BSpeak to the two vrykul champions who ascended into these halls with you and tell them it is time for you to assume your duties as Odyn\'s chosen.', `QuestDescription`) WHERE `ID` = 42598;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tech It Up A Notch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archivist Melinda in Dreadscar Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are very fortunate to have come across Archivist Melinda. She is somewhat of an anomaly, as not many from her race choose our path. What makes her even more unique is her meticulous study of our craft. Her knowledge will be unsurpassed.$B$BSpeak to her now and seek her council. With her help, we can surely strengthen the council.', `QuestDescription`) WHERE `ID` = 42601;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Troops in the Field', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Dreadscar Battle Plans and complete the mission, "Troops in Training".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s time to send our newly trained imps out into the field. Look at the Dreadscar Battle Plans and send your champions and troops on a routine scouting mission.', `QuestDescription`) WHERE `ID` = 42602;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Information at Any Cost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Dreadscar Battle Plans and complete the mission "Information at Any Cost".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you\'ve found other warlocks that are willing to aid your cause, we can use the Dreadscar Battle Plans to complete vital assignments across the Broken Isles.$B$BIf we wish to rebuild the council, we must start by locating its missing members.$B$BLet us send Ritssyn and Calydus to interrogate the Burning Legion\'s minions. They might have information that will help us locate the missing council members.', `QuestDescription`) WHERE `ID` = 42603;
