UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Captain Stahlstrom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Eye of Odyn and complete the mission, "Captain Stahlstrom."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The souls that make it to these halls are brave, yes. That\'s why they\'re here after all.$B$BValor alone does not make for an effective army, however. You will need someone who can train those who would be valarjar to fight with discipline.$B$BHave your champions send word to Captain Stahlstrom. Unruly vrykul berserkers may not fear death, but they might fear Hjalmar Stahlstrom enough to make them follow your orders.', `QuestDescription`) WHERE `ID` = 42607;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Calydus and Ritssyn Flamescowl.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Friend is in a powerful, but lonely position. First of a council whose members are missing.$B$BFriend does not have to be alone though. Others will be drawn to friend\'s power, willing to follow if friend leads.$B$BFind those who want to help, and accept their pledge of loyalty.', `QuestDescription`) WHERE `ID` = 42608;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting the Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Captain Hjalmar Stahlstrom and train Valarjar Aspirants.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Captain Stahlstrom has arrived. It would be advisable to speak to him and see that the valarjar are armed and ready for battle.$B$BWe\'ll need more than your two champions if we\'re to win a full-fledged war against the Legion.', `QuestDescription`) WHERE `ID` = 42609;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Troops in the Field', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Eye of Odyn and complete the mission, "Troops in the Field."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our enemies\' transgressions have gone unchecked for long enough. Now that we have troops to back your champions, you would do well to send them to deal with them.$B$BOne of our own has been taken prisoner by Odyn\'s sworn nemesis, Helya. If your forces manage to bring back Einar the Runecaster alive he can aid us in using powerful runes to advance the power of your armies.', `QuestDescription`) WHERE `ID` = 42610;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Einar the Runecaster', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Einar the Runecaster.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Being a leader is not just about sending your troops to combat. You will also make decisions about how we train and improve our armies.$B$BSpeak to Einar the Runecaster and let him know how you would like development to progress.', `QuestDescription`) WHERE `ID` = 42611;
