UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ceremonial Drums', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find $1oa Large, $2oa Medium, and $3oa Small Ceremonial Drums in Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Those foolish calves!nnThey\'ve made off with our ceremonial drums again, treating them as toys... as... common drums!nnCan you help me find them? They must be scattered to all corners of Thunder Totem by now, discarded as soon as the fun dries up.', `QuestDescription`) WHERE `ID` = 42622;
