UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Unseen Blade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Garona take out the Veiled Hand cultists in Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Stormwind is too important to fall to the Legion, and I don\'t trust Shaw or his SI:7 goons to take care of the Hand on their own.$B$BThe two of us will have to handle this while there\'s still time.$B$BUse extreme caution. The entire city is on edge from murmurs of the cult\'s activities, and we\'re already kill on sight.$B$BThe other Shadows spoke highly of your skills. Are you in?', `QuestDescription`) WHERE `ID` = 42627;
