UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bolas Bastion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Coven attackers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I received word that a coven of harpies and their rocs plan to attack in force.nnThey\'ll be coming from the mountains to the north.nnUse one of the bolas launchers and I\'ll man the other.nnQuick!', `QuestDescription`) WHERE `ID` = 42630;
