UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Confrontation at the Black Temple', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Gateway to the Black Temple and confront Akama.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The book from Lan\'dalock is very enlightening. It describes a technique which will provide a simple and elegant bypass around the Black Temple\'s holy barriers.nnI will need but a moment to summon a gateway. Stand back, please.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Travel to the Black Temple and confront Akama. Convince him to join forces with you in the fight against the Burning Legion.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Akama', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Altruis the Sufferer on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42634;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Mystery of Dreyrgrot', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather 4 Ancient Dreyrgrot tablets from the pirate ships outside of Dreyrgrot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well met, good chap!nnI was on my way to study the local murlocs when I stumbled upon these most peculiar ruins. Those pirates over yonder arrived first, and it appears they\'ve unleashed some ancient evil.nnI would be remiss to let such an evil run rampant, but we should learn more of it before we proceed, lest we end up like those chaps.nnI spied the crew bringing back some tablets from the ruins. If you can bring them to me, I may be able to decipher the nature of this evil.', `QuestDescription`) WHERE `ID` = 42635;
