UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Stone of Blood', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Broketooth\'s Ruby Amulet from Captain Broketooth on the ships near Dreyrgrot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Unfortunately, we may have another problem. That mist seeping out of the ruins has affected the looting pirates. It\'s driven them quite mad.nnOnly one of them seems to be unaffected - a captainly fellow with a very fine hat.  He wears a large ruby amulet, which I believe protects him from the mist. You\'ll need it if you are to enter the tomb.nnHe may not give it up willingly.', `QuestDescription`) WHERE `ID` = 42639;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Value of Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather 7 Crates of Ancient Relics from the waters outside Dreyrgrot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This crate is filled with relics from the nearby ruins. The pirates have discarded them, likely thinking they\'re of little value.nnThe Explorer\'s League would probably appreciate if you retrieved these relics for them to study.', `QuestDescription`) WHERE `ID` = 42640;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'What the Bonespeakers Buried', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Sharp Wooden Stake to kill Blood-Thane Lucard in Dreyrgrot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Most Fascinating! It would appear that we\'re dealing with our very own vrykul vampyr!nnAll we have encountered have been of blood elven descent, but it has long been theorized that the vrykul have suffered the curse as well. It\'s too bad he\'s awake - I would dearly like a subject to study.nnOh well, guess there\'s nothing for it. Take this stake and put it through the old chap\'s heart. I\'m pretty sure that should do the trick.', `QuestDescription`) WHERE `ID` = 42641;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spilling Bad Blood', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 8 Blood-Crazed Swashbucklers in Dreyrgrot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ending the evil of the Blood Prince will be a boon to this land, but we can\'t just allow these crazed corsairs to run amok.  I\'m afraid there is no choice but to put them to the sword.nnCarry out this noble deed, my good fellow, and we will celebrate with a nice warm lager.', `QuestDescription`) WHERE `ID` = 42645;
