UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Break the Bonds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Throw Svergan\'s Belongings into the Soul Pyre and complete the Ritual of Unbinding.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bonespeaker mystics used these heirlooms to tie my soul to this world.$B$BUnder their curse, my soul could not enter the Halls of Valor. Find the soul pyre in Haustvald and throw my belongings into the flames.$B$BThe fire that bound my soul through their foul magic will be the same fire that undoes this bond!', `QuestDescription`) WHERE `ID` = 42650;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Svergan\'s Promise', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Hymdall in Skyhold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I thank you for doing this for me. I swore an oath to protect the Gjallarhorn with my life, and so I did.$B$BYou must tell Hymdall that his Gjallarhorn was devoured by the great worm, Jorhuttam!$B$BIt devoured an entire army of my men who were swallowed whole trying to fend off the beast. Find Jorhuttam and you will find the horn!', `QuestDescription`) WHERE `ID` = 42651;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ancient Exemplars', `LogTitle`) WHERE `ID` = 42652;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Akama', `LogTitle`) WHERE `ID` = 42653;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkheart Thicket: Nightmare Oak', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Nightmare Oak from Oakheart within the dungeon, Darkheart Thicket.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Blacksmith Kyriel is no stranger to the Farstriders. He has forged countless arrows for us in the past, using his knowledge of unique materials to help build better, stronger ammo.$B$BHe\'s efficient and gifted, making the most of scarce materials.$B$BUsing a single branch from a corrupted ancient, he can craft thousands of arrows.', `QuestDescription`) WHERE `ID` = 42654;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ore Under the Sea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mine Azure Ore from deposits found in the water off the coast of Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If we want to bring the fight to Hakkar, my rangers are going to need arrows and ammo that are capable of piercing the thick, magic-resistant hides of his hounds.$B$BThere\'s a versatile smith in Dalaran who does incredible work with both bows and blades alike.$B$BHe uses azure ore in his creations, which can only be found below sea level.$B$BDue to its proximity to leystone, the ore is often overlooked, but in an expert smith\'s hands, it can be smelted into something nearly indestructible.', `QuestDescription`) WHERE `ID` = 42655;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azure Weaponry', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Blacksmith Kyriel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Take the materials to Blacksmith Kyriel in Dalaran, and he\'ll use them to craft whatever weapons he can.nnAs I mentioned before, he\'s skilled and efficient, so you shouldn\'t have to wait long.nnWhen his work is complete, speak to Shandris Feathermoon about getting the weapons enchanted.', `QuestDescription`) WHERE `ID` = 42656;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Meeting in Moonclaw Vale', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Lyana Stardust in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lyana Stardust still lingers in a vale that has been overrun by demons. Despite its current start of upheaval, she refuses to abandon her home.$B$BThe strength and stubbornness she exhibits in the face of an enemy are also traits that shine through in her enchantments.$B$BWe want our weapons to be as strong and stubborn as she is.$B$BMeet her in Moonclaw Vale, and see if she can work her magic with the weapons that Kyriel has crafted for us.', `QuestDescription`) WHERE `ID` = 42657;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Delicate Enchantments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Protect Lyana Stardust while she enchants the azure weaponry.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As I\'m sure you\'ve noticed, demons have taken over the vale. Their arrival has forced many of my fellow druids to flee their homes, but I refuse to go down without a fight.$B$BDespite all this, I\'m happy to provide enchantments for your weapons, but you should know that it is a delicate process that takes time and concentration, something I have little of lately.$B$BIf you\'re willing to shelter me from attackers, I will certainly do my best to enchant your weapons.', `QuestDescription`) WHERE `ID` = 42658;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In Defense of Dalaran', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Violet Hold through Khadgar\'s portal, and defeat Hakkar the Houndmaster.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have everything we need to set the trap for Hakkar.nnArchmage Khadgar will summon a portal to the Violet Hold. Once inside, he will begin to channel his essence into the arcane vessel at your command.nnOur allies will be armed with the weapons you brought them, ready to fight when Hakkar takes the bait.', `QuestDescription`) WHERE `ID` = 42659;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vault of the Wardens: Matters of the Heart', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Felsworn Heart from Cordana within The Vault of the Wardens dungeon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have made considerable progress with the Bloodstone, thanks in part to your extensive testing.nnThe stone feeds on blood to grow in power, but its ability to control a demon comes from consuming a corrupted heart; the more powerful, the better.nnWithin the Vault of the Wardens you\'ll find someone with such a heart.', `QuestDescription`) WHERE `ID` = 42660;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Archmage Kalec', `LogTitle`) WHERE `ID` = 42662;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Archmage Kalec and Archmage Modera.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tirisgarde has been defunct for ages. To defeat the Burning Legion, we must first recruit the greatest champions of our class to fight by our side. Two powerful archmages, Archmage Kalec and Archmage Modera, have come to help us succeed. nnSpeak to them and enlist their aid.', `QuestDescription`) WHERE `ID` = 42663;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Shade of Akama', `LogTitle`) WHERE `ID` = 42664;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into Our Ranks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit the Shade of Akama and Kor\'vas Bloodthorn as your champions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We should make a show of welcoming this Shade of Akama into our ranks. It is important that the others see him treated as one of us, rather than as an outsider.nnKor\'vas Bloodthorn has proven herself invaluable, time and time again. Her skills in combat are unquestioned and unparalleled. You will find no champion better suited to destroying our enemies.nnIt is time to officially raise them up as champions.', `QuestDescription`) WHERE `ID` = 42665;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Fel Hammer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Battlelord Gaardoun on the Fel Hammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Battlelord Gaardoun asked me to retrieve you. He says there is a very important matter that he needs your help with.nnHe requests your presence back on the Fel Hammer as soon as possible.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Return to me on the Fel Hammer as soon as possible, commander.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Battlelord Gaardoun', `PortraitGiverName`) WHERE `ID` = 42666;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Preparations for Invasion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the "Preparations for Invasion" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have the Sargerite Keystone. We have most of the forces we will need. We even have a plan.nnNow we need to locate the Felsouls and prepare for an invasion of whatever demon world they\'re hiding out on.nnPlease leave it to me. If you will grant me the use of your champions, I and the Scythe of Souls will extract the information by any means necessary from the demons that we question.', `QuestDescription`) WHERE `ID` = 42669;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Altruis the Sufferer and Asha Ravensong as your first champions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The matron mother, Lady S\'theno, and I have been watching you and the rest of the Illidari. We have something of an outsider\'s perspective on things, which gives us a degree of objectivity. We have come to a unanimous recommendation: in order to keep the Illidari from splintering, you must begin to recruit champions.nnThese exalted few will aid in projecting your power beyond the confines of the Fel Hammer.nnOur unanimous recommendations for the first two are Altruis and Asha.', `QuestDescription`) WHERE `ID` = 42670;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Kayn Sunfury and Asha Ravensong as your first champions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The matron mother, Lady S\'theno, and I have been watching you and the rest of the Illidari. We have something of an outsider\'s perspective on things, which gives us a degree of objectivity. We have come to a unanimous recommendation: in order to keep the Illidari from splintering, you must begin to recruit champions.nnThese exalted few will aid in projecting your power beyond the confines of the Fel Hammer.nnOur unanimous recommendations for the first two are Kayn and Asha.', `QuestDescription`) WHERE `ID` = 42671;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Kor\'vas Bloodthorn', `LogTitle`) WHERE `ID` = 42673;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Things Gaardoun Needs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Things Gaardoun Needs".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Battlelord Gaardoun has offered to recruit more broken warriors for the cause. He just needs a few things first. He said something about the right tool for the job, or something like that.nnTime to put your new champions to the test. I\'m sure it will be a grueling mission.', `QuestDescription`) WHERE `ID` = 42677;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Hold: Into Black Rook Hold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather a group and enter Black Rook Hold to take the Raven\'s Eye from Dantalionax.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This thing is ancient. Just turning the pages risks them disintegrating in my hands.nnHere, I have found it. An entry about the Raven\'s Eye.nn<Valeera traces her finger from left to right above the page. A look of discovery comes over her features, which is quickly replaced by a frown.>nnIt says here that the last person to have possession of the eye was Lord Ravencrest himself. You are going to have to go into Black Rook Hold and take it from him.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Valeera Sanguinar in the Chamber of Shadows.', `QuestCompletionLog`) WHERE `ID` = 42678;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Broken Warriors', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Battlelord Gaardoun and train Ashtongue Warriors.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s important that we increase our numbers. Trust me, I know these things. Battlelord Gaardoun and his Ashtongue warriors are our best bet to quickly accomplish such a task.nnYou should speak with him and let him know just what kind of broken you want trained.', `QuestDescription`) WHERE `ID` = 42679;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Deciphering the Letter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Raven\'s Eye to decipher the encrypted SI:7 Letter.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have the Raven\'s Eye. Use it, $n. Decipher the SI:7 letter.nnWe must know what secrets it contains!', `QuestDescription`) WHERE `ID` = 42680;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Loramus, Is That You?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Loramus, Is That You?".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Belath Dawnblade has given us a strange scouting report from the Felblaze Ingress in Azsuna. The dreadlord, Razelikh the Defiler has returned to the world. That\'s not the odd part, though.nnStrangely, he\'s sometimes going around killing the other demons and calling himself, Loramus!nnLast we knew, our demon hunter brother, Loramus Thalipedes sacrificed himself to defeat Razelikh, whom he\'d been possessed by.nnYour champions and Ashtongue warriors need to go to Azsuna and find out what is going on.', `QuestDescription`) WHERE `ID` = 42681;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Additional Accoutrements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Additional Accoutrements".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I heard a rumor that you are going to attempt to make contact with Illidan\'s immortal demon soul in the Twisting Nether. You are going to need many magical things.nnI have taken the luxury of putting together a potential list for you. I do so hope that it proves helpful, $g handsome:gorgeous;.', `QuestDescription`) WHERE `ID` = 42682;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demonic Improvements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Listen to Loramus Thalipedes\' story and then upgrade your Class Hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Having Loramus back will work greatly to our advantage, despite the fact that he\'s trapped inside Razelikh\'s body... and also that the demon sometimes takes control.nnStill, he was one of our most powerful demon hunters. And now, he also has the knowledge of a dreadlord at his disposal.nnI think we should have him share his knowledge and wisdom with us to improve our odds in this war.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'He may look like Razelikh the Defiler, but the soul of the demon hunter, Loramus Thalipedes is actually in control of this dreadlord... mostly.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Loramus Thalipedes', `PortraitGiverName`) WHERE `ID` = 42683;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Throwing SI:7 Off the Trail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the "Throwing SI:7 Off the Trail" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'SI:7 is dogging our heels at every turn. We must make certain that they do not catch wind of what we are up to.nnTo that end, I have some suggestions for you in the form of missions. Send your champions, assign your forces, it matters little to me. The important thing is that we keep them out of Val\'sharah and away from Black Rook Hold.nnAt least until we can decipher that damned letter.', `QuestDescription`) WHERE `ID` = 42684;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Archmage Modera', `LogTitle`) WHERE `ID` = 42685;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Troops in the Field', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the mission, "Troops in the Field."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our troops are ready! It\'s time to test them out in the field.$B$BWe\'ve received word of survivors near the Broken Shore, but the area is still crawling with Legion.$B$BSend our troops quickly to help with the rescue!', `QuestDescription`) WHERE `ID` = 42687;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mrgls of Endearment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '????', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mrmlgr! Mrglr rlmgrg mlrgr! Mrlgmr...$b$b<Phin shows you a flaw on the side of the pearl.>$b$bMmlrgmlr rlmgr grlmrmlg mglrmglr. Mlrgmrl rmglr? Mlgrmglr!$b$bGmmlrgmrl mlrgmlr lrglrmgrl lrlgllrlm mglrlr grlm-grlm.$b$b<Phin makes a pinching motion with his hand.>$b$bMrlgmlgr mgrlmlgr? Mlrgmlr gmrlmglr Mrgrlilgrl.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', '????', `AreaDescription`) WHERE `ID` = 42688;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knowing Our Enemy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Kira Iresoul in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If we hope to gain the upper hand against Hakkar, we need to find out more about these hounds that he\'s breeding and pinpoint their weaknesses.$B$BI know of a warlock that studies demons extensively. Maybe she has seen some of these hounds, and knows how to defeat them.', `QuestDescription`) WHERE `ID` = 42689;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Altruis the Sufferer', `LogTitle`) WHERE `ID` = 42690;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leyworm Lure', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Leyworm Entrails from worms within Leyhollow in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Felhounds are attracted to magic, young ones especially.$B$BThey get a whiff and go into a feeding frenzy! You\'re not quite as enticing as a mage, so you\'ll need to cover yourself in something that can fool a felhound into thinking you\'re its next magical meal.$B$BLeyworm entrails should do the trick.', `QuestDescription`) WHERE `ID` = 42691;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Children of Nar\'thalas', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find three Ancient Highborne Tomes in the Ruins of Nar\'thalas.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hi! $n, right? The archmages in Dalaran said we might see you down here.$b$bMy brother and I are here on a reconnaissance mission. We\'re looking for our parents.$b$bWe\'ve lived our entire lives thinking that our family was killed in Azsuna several thousand years ago, but look around! Most of the elves here are ghosts.$b$bOlothil\'s been searching through books for clues as to why, but we could use some help.', `QuestDescription`) WHERE `ID` = 42692;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'You Never Know Until You Scry', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Hatecoil Glyptics.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to find the spirits of our family, I will need materials to scry their location.$b$bThe naga carry magical trinkets imbued with ley energy that is better-attuned to this land than anything we have in Dalaran. If I had a few of those, I could do some real scrying.', `QuestDescription`) WHERE `ID` = 42693;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Back from the Dead', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scrying Orb to determine potential locations of night elf spirits, then go rescue them.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Olothil sighs.>$b$bMy sister tries my patience sometimes.$b$bNo matter. I\'ve identified a few locations that our parents might be. I shall search in this area with Kallistia. You\'ve already helped us so much... would you help us look to the east?$b$bYou can use my scrying orb to see the locations that our ritual has uncovered.', `QuestDescription`) WHERE `ID` = 42694;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Kayn Sunfury', `LogTitle`) WHERE `ID` = 42695;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tech It Up A Notch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Chronicler Elrianne', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thanks to you, the Hall of the Guardian is gradually re-assembling.$B$BHowever, there is much more work to do. As our leader, you can determine the trajectory of our order\'s future.$B$BSpeak to Chronicler Elrianne. She will show you the ropes.', `QuestDescription`) WHERE `ID` = 42696;
