UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Technical Wizardry', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Archmage Melis.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you have your first two champions, there is an abundance of work they can do to help us.nnArchmage Melis has been hard at work getting our command room up and running. Head downstairs and ask her to show you what needs to be done.', `QuestDescription`) WHERE `ID` = 42703;
