UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: A Magical Affliction', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Fill a vial with arcane water from the Wrath of Azshara.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Vargoth\'s betrayal is an unimaginable loss to our cause, $n. We will have to deal with him, but first Meryl\'s condition has become dire. nnUnfortunately it is not an illness at all, but a magical attack of fel origin. It may be his old nemesis Kathra\'natir is behind it. We need to buy him time.nnThe Eye of Azshara contains a vast store of arcane energy from Queen Azshara herself. If we could obtain a vial of water from the Wrath of Azshara\'s body, that will sustain him for a while.', `QuestDescription`) WHERE `ID` = 42707;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Personal Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue Koltira Deathweaver from Undercity.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you have a moment, Deathlord... there is a personal matter I would like to speak with you about.$b$bSome time ago, a brother of the Ebon Blade was imprisoned beneath the ruins of Lordaeron by the Dark Lady.$b$bSylvanas has refused all attempts to negotiate his release. Now, our world faces destruction and the time for diplomacy has passed.$b$bKoltira Deathweaver cannot fight the Burning Legion in chains.$b$bSo we will break them.', `QuestDescription`) WHERE `ID` = 42708;
