UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: Cleansing the Dreamway', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 25 Rarefied Water from the naga in the Eye of Azshara, and defeat the Wrath of Azshara.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Brightwing has lots of friends. I like friends!$B$BBut you know who isn\'t Brightwing\'s friend? Scary monsters from the nightmare!$B$BThey hurt Brightwing\'s allies, and they made the grove all yucky!$B$BThis place needs to be cleansed, but I\'m all out of magic.$B$BCan you bring Brightwing some purified water to help? You\'ll have to go far, far away... to the Eye of Azshara where the naga live.', `QuestDescription`) WHERE `ID` = 42719;
