UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Friends in Cages', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Release 3 Nightborne Citizens from their captivity.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Korine stomps her foot and refuses to move.>nnThey put my friends in cages!nnMake the bad men stop hurting them! They take them out the garden and they never come back!nn<Korine gestures stubbornly toward the door.>nnI am not going home until they do!', `QuestDescription`) WHERE `ID` = 42722;
