UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sharing the Wealth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 20 Bottles of Arcwine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lately there have been a disturbing array of changes involving our most precious resource, Arcwine. nnI imagine Thalyssra has thoroughly educated you about what happens when a Nightborne does not have access to a source of power like Arcwine.nnWith the presence of the demons came rationing. There are many who do not have enough to sustain themselves.nnBring me as much Arcwine as you can carry. I will see that it gets to the right people.', `QuestDescription`) WHERE `ID` = 42725;
