UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Mlrglrmg For Grlmrgl', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '????', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mrglm, rmgrlg mrlgmrl.$b$bGrmrglmrl mlrmglrgr mlrmlgr! Rglrmgl rmglrgmlr mlmlglr mglgrgrlm - grlgmr, mlgr - lrgmlrgr rmgrmlg mlrg! Mlrgr?$b$bMrlgmrlgmrl rmglrmglr!$b$b<Pearlhunter Phin makes a stabbing motion.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', '????', `AreaDescription`) WHERE `ID` = 42728;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Challenger\'s Armaments', `LogTitle`) WHERE `ID` = 42729;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Noggenfogger\'s Reasonable Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Aethril.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh, the gall of that little green-skinned twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his "very reasonable requisition request", he is going to close off access to the crucible.nnMarin\'s asking for a hefty amount of Aethril. He said something about you recently holding a blade to his throat and that he\'s simply returning the favor.nnOf course, if you would rather, I can eliminate him.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Marin Noggenfogger in the Uncrowned Vault.', `QuestCompletionLog`) WHERE `ID` = 42730;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Working With the Wardens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the "Working With the Wardens" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As much as we might not like it, we need the aid of the Wardens if we\'re to locate the Sargerite Keystone. They took it from you when we were all imprisoned in the vault.nnWith Maiev missing, their current leader is Sira Moonwarden. On your behalf, I have agreed that we will assist them in tracking down some of the more powerful creatures that escaped from the Vault of the Wardens. In return, she will direct us to where we need to go to get the Keystone.', `QuestDescription`) WHERE `ID` = 42731;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Deadlier Warglaives', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Obliterum, which can be obtained either from your Forge of Fate in Dalaran\'s Magus Commerce Exchange or from the Auction House.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Loramus has researched a way to make our warglaives even deadlier, especially against demons.nnIf he\'s to be trusted, he says that all he needs is an amount of Obliterum. Normally, the substance is used to improve the protection of armor, but Loramus insists he can use it for our warglaives.nnI am certain we will all benefit from their increased deadliness on the battlefield.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Jace Darkweaver on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42732;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Very Special Kind of Fuel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Sovereign Souls from bosses in Legion dungeons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All Legion constructs, including the Fel Hammer, are powered by souls. If we are going to take the command center to Niskara, we are going to need some very powerful souls, indeed!nnYou are a very creative person, $n. I am certain that you will find a way to get what we need from the right sorts of creatures.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Jace Darkweaver on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42733;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into the Oculus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Archmage Khadgar when you are ready to travel to the Oculus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I fear Kathra\'natir is behind the attack on Meryl. We have little time to act. nnI suspect Archmage Vargoth\'s involvement is no coincidence. While it greatly pains me to destroy an archmage of his caliber and worse, someone I once called friend, we cannot permit his betrayal to stand unpunished. nnIt is time to follow him into the Oculus.', `QuestDescription`) WHERE `ID` = 42734;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Malace in Vrykul Land', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Grab a flight from Aludane Whitecloud and find Malace Shade in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I did some recon in Stormheim. What I discovered is that the Tideskorn are a tribe of vrykul who have been cut-off from the sea by their kvaldir brethren. Many of the Tideskorn have pledged their services to the Legion and become Felskorn.nnMalace Shade was last seen heading toward the Felskorn Warcamp. It is likely that she was captured.nnI have arranged a flight to Stormheim for you. When you are ready, you can use the gateway to travel to Dalaran and speak with Aludane Whitecloud at Krasus\' Landing.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Find this Warden in Stormheim. Last seen heading toward the Tideskorn Warcamp.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Malace Shade', `PortraitGiverName`) WHERE `ID` = 42735;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rune Ruination', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deactivate the three runestones to set Malace free.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A cage wasn\'t enough to hold me, so the vrykul ensorcelled these runestones to trap me in here. Each is powered by a different Felskorn rune.nnUnfortunately, they gave the runes to different guardians, who have all scattered to different places around Stormheim.nnSo, if Sira said that you could have your precious keystone back, you\'re first going to have to get me out of here.nnThen, we\'ll see.', `QuestDescription`) WHERE `ID` = 42736;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rune Ruination: Runeskeld Rollo', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Rollo\'s Rune.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Collect the rune from Runeskeld Rollo to deactivate this runestone.>', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Kill him and take the rune he is guarding.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Runeskeld Rollo', `PortraitGiverName`) WHERE `ID` = 42737;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rune Ruination: Runelord Ragnar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Ragnar\'s Rune.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Collect the rune from Runelord Ragnar to deactivate this runestone. If you do not already have one, obtain a grapple launcher in order to scale the walls of Hrydshal.>', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'You need his fel rune to deactivate the runestone.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Runelord Ragnar', `PortraitGiverName`) WHERE `ID` = 42738;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rune Ruination: Runesage Floki', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Floki\'s Rune.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<This runestone is entrapping Malace Shade. It can only be destroyed by using Runesage Floki\'s rune upon it.>', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Hunt down and slay Floki. Take his rune so that you can set Malace free.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Runesage Floki', `PortraitGiverName`) WHERE `ID` = 42739;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Battle for Broken Shore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the third fleet ship to the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is your vessel, $n. She\'s a fine ship, been through many a campaign. Speak with the ship\'s captain when you\'re ready to depart.nnGood luck out there. We\'ve received few reports about what\'s happening at the Broken Shore, but I\'d wager King Varian has matters well in hand.', `QuestDescription`) WHERE `ID` = 42740;
