UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where the Wildkin Are', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Owlbeasts and $2oa Undulating Boneslimes within Lostlight Grotto.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Owlbeasts are often charged with protecting places of importance to Elune. But if her influence over them wanes or is cut off, the creatures can become dangerous.nnThese wildkin, unfortunately, must be dealt with. The recent disturbances in Val\'sharah have driven these creatures to madness.nnOnce an individual is lost, there is only one way to address the problem.nnI cannot bring myself to kill one of Elune\'s creations, but I know what must be done.', `QuestDescription`) WHERE `ID` = 42747;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Emerald Sisters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue $1oa Sisters of the Moon in Lostlight Grotto.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The owlbeasts here are disconnected from Elune.nnA contingent of dryads went into their territory to find out what went wrong, but none of them have returned.nnI fear the worst, and I believe they are  in need of rescue.nnWhile I try to learn if the owlkin can be saved, I would appreciate your help in freeing any Sisters you find in the grotto.', `QuestDescription`) WHERE `ID` = 42748;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Strange Bedfellows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Malace Shade on the bridge at the Gates of Valor and then slay Lochaber.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The reason why I came out here was to capture or kill a fel lord named, Lochaber. I am no longer in a capturing mood.nnI\'ll grab my weapon and then head up to the bridge in front of the Gates of Valor. That place is a scary mess full of Felskorn vrykul and demons.nnHow do you think I got caught?nnSo, I\'d rather not go back in there. But, I think I know a way to get the demon to come out to us.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Help Malace Shade kill this fel lord and she will tell you how to recover the Sargerite Keystone.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Lochaber', `PortraitGiverName`) WHERE `ID` = 42749;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dreamcatcher', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Charge the dreamcatcher using owlbeast totems in Lostlight Grotto.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I cannot hold on for much longer...nnI brought a dreamcatcher with me. I was to use it to steal the magic from owlbeast totems.nnIt is the only way to break the barrier where they hold Keeper Remulos.nnPlease help where I have failed.', `QuestDescription`) WHERE `ID` = 42750;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moon Reaver', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Boneflux and rescue Keeper Remulos in The Undergorge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must not delay! If Keeper Remulos is in danger, he must be protected.nnWith the dreamcatcher, we should be able to enter the lair of the owlbeast Boneflux.nnIt must be defeated so Keeper Remulos can break free!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Boneflux', `PortraitGiverName`) WHERE `ID` = 42751;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vault of the Wardens: Vault Break-In', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Sargerite Keystone.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<All that is left now is to travel to the Isle of the Watchers off of southwest Azsuna. There, you will need to break back in to the Vault of the Wardens and descend down into its lowest recesses where once you were imprisoned.>nn<Within the so-called Vault of the Betrayer, where the Wardens once held Illidan\'s corpse, the Sargerite Keystone awaits.>', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Belath Dawnblade on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42752;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vault of the Wardens: Vault Break-In', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Sargerite Keystone.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Wardens made good on the deal. All that\'s left is to travel to the Isle of the Watchers off of southwest Azsuna. There, you\'ll need to break back in to the Vault of the Wardens and descend down into its lowest recesses where we were once imprisoned.nnWithin the so-called Vault of the Betrayer, where the Wardens once held the Master\'s corpse, you\'ll find Sargerite Keystone.nnGood luck, $n.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Belath Dawnblade on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42753;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Jump-Capable', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Fel Engine Injector, a Soul Configuration Matrix, a Fel Engine Ignition, and a Vile Spirit Converter.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While it is true that the Fel Hammer is powered, sadly, its jump engines are non-functional. If we are going to invade a demon world, we\'re going to have to make the command center jump-capable.nnWe need some replacement parts.nnLuckily for us, the Legion brought a couple of command centers and soul engines along with them to the Broken Isles. You will find them at Faronaar in Azsuna, and at Felsoul Hold in Suramar.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Jace Darkweaver on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42754;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: Azsunian Pearls', `LogTitle`) WHERE `ID` = 42755;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hunger\'s End', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Ael\'Yith and his construct.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I am weak. The hunger is devastating, my friend. I understand now why your dragon rests in these pools.$b$b<cough, cough>$b$bI came to warn you but... it looks like I was too late.$b$bI hear him outside now. Ael\'Yith... is... here...', `QuestDescription`) WHERE `ID` = 42756;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maw of Souls: Menace of the Seas', `LogTitle`) WHERE `ID` = 42757;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'You\'re Gonna Need A Bigger Boat!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Pull 33 Razor-Sharp Shark Teeth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Sharks. They be the biggest threat to us pirates. Well... after scurvy, ninjas, and the judicial system. Luckily, we only have to deal wit\' sharks today.nnGo pull some teeth out of their ugly faces \'n bring \'em back to me. I needs a new necklace!', `QuestDescription`) WHERE `ID` = 42758;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wanderer\'s Companion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Tak-Tak to fly to Tian Monastery and meet with the Monkey King.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Fu Zan... a wise choice. If the legends are true, its powers will be essential to our cause.$b$bWe believe that the staff possessed by the Monkey King could be fabled Fu Zan, yet no one has seen him with the weapon for over a year.$b$bThe Monkey King was last spotted at Tian Monastery. Be prepared for anything! He is known for being... less than forthcoming with his answers.$b$bTak-Tak, a hozen kite-master, is skulking around west of the temple. Speak to him without delay.', `QuestDescription`) WHERE `ID` = 42762;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dalaran Hidden Demon 01', `LogTitle`) WHERE `ID` = 42763;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Court of Stars: Wraith in the Machine', `LogTitle`) WHERE `ID` = 42764;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Trial at the Temple', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Accompany the Monkey King to the Temple of the Jade Serpent and obtain Fu Zan, the Wanderer\'s Companion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My staff was strong and mighty without peer, but since I not its master, in time it would soon disappear.$b$bThe staff was a gift from the Jade Serpent, Yu\'lon, but for only a single task. With my work finished, to her again it has passed.$b$bYu\'lon be the staff\'s keeper, holding it for those who are blessed. To her we now go now, to announce your request.', `QuestDescription`) WHERE `ID` = 42765;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Riddle of the Barrel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search for the objects the Monkey King has described in his riddle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My weapon is great when in a fight,nIt\'s even handy when you sit for a bite.nnMy favorite flask I\'ve tied on it, hanging from a cord,nThe brews within are some of the best that I\'ve ever scored.nnIf you truly seek my weapon then bring me something nice to put into my belly,nA powerful brew is what I want, something strong and smelly.', `QuestDescription`) WHERE `ID` = 42766;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Riddle of the Land', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search for the objects the Monkey King has described in his riddle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My weapon is strong but not for attacking, nProtecting the weak is what it\'s enacting.nnIn the valley are people who till the land from dawn to night,nThe fruits of their labor, you must show me tonight.nnSacks of grain are what I require,nNot just any will do, only those kissed by a fire.nnBring me what I seek.', `QuestDescription`) WHERE `ID` = 42767;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Riddle of Purity', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search for the object the Monkey King has described in his riddle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you seek my weapon? Then you better answer my question.$b$b  "I seek something curvy and bendy but with no spine,$b$b   It rushes and rushes leaving chaos behind.$b$b   Sometimes it brings life, sometimes it brings death:$b$b   A little is good, but a lot steals your breath.$b$b   It\'s as common as dirt, but this part\'s obscure:$b$b   This stuff comes from a pool that\'s known to be pure."$b$bBring me what I seek.', `QuestDescription`) WHERE `ID` = 42768;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Court of Stars: Bring Me the Eyes', `LogTitle`) WHERE `ID` = 42769;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seeking Guidance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Lord Maxwell Tyrosus at Uther\'s Tomb in Western Plaguelands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Highlord Tirion may be gone, but the Ashbringer is still out there somewhere. Its power would devastate the Legion. We must find it!$B$BI wish it were as simple as returning to where Tirion fell. It could be anywhere on that infernal landscape by now.$B$BI believe an old friend can help us find the blade. I ask that you place your faith in me and journey to Uther\'s tomb in the Plaguelands. We will seek answers there.', `QuestDescription`) WHERE `ID` = 42770;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keeping the Peace', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Exorcise $1oa spirits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The lost souls roaming the cemetery grounds have been drawn to the realm of the living in the wake of the Light\'s disturbance. In truth, they merely seek comfort... as we all do in these dark times since Highlord Tirion\'s passing.$B$BHowever, their unrest threatens the very sanctity of the tomb we have sworn to protect. If we are to restore peace here, then they must be exorcised.', `QuestDescription`) WHERE `ID` = 42771;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sacred Ground', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Purify the graveyards in Sorrow Hill.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must ensure that those buried here are never again disturbed. Their spirits\' very presence only further perturbs the Light.$B$BThis cannot continue.$B$BI must maintain this barrier to ensure none of the wayward souls enter the Lightbringer\'s resting place. If you can purify the graves themselves, this madness can finally cease.', `QuestDescription`) WHERE `ID` = 42772;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Light Reveals', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Commune with Uther the Lightbringer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We seek aid not from a living friend, but one who passed long ago.$B$BUther the Lightbringer was more attuned to the subtleties of the Light than any paladin I\'ve ever known. If we reach out to him, he may be able to help us find the Ashbringer.$B$BThe ceremony has been prepared. Approach the tomb when you are ready.', `QuestDescription`) WHERE `ID` = 42773;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hope Prevails', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Lord Maxwell Tyrosus at Light\'s Hope Chapel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tirion... still alive! We have to save him.$B$BLight\'s Hope Chapel is not far from here. We must rally our forces and leave at once for the Broken Shore.', `QuestDescription`) WHERE `ID` = 42774;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Crux of the Plan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place the Sargerite Keystone above the Scouting Map.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have Akama. Cordana Felsong has been eliminated. And, we have the Sargerite Keystone.nnEverything is falling into place.nnThe honor is all yours, $n.', `QuestDescription`) WHERE `ID` = 42775;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Two Worthies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Belath Dawnblade and Matron Mother Malevolence as your champions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As our forces grow, and our reach extends ever outward, you have need of more trusted companions to handle the most important of missions.nnThe time has come for you to elevate two worthies into the ranks of your champions. nnIt\'s my opinion that you should consider recruiting Belath and Malevolence. They have both proven themselves indispensable.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Allari the Souleater down below in the lower level of the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42776;
