UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Be Prepared', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Visit Alliance forces in Stormwind Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Allies from across Azeroth have come to Stormwind to support our efforts against the Burning Legion.nnBefore you ship out, you should pay them a visit. Every bit of preparation helps!', `QuestDescription`) WHERE `ID` = 42782;
