UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grotesque Remains', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Guviena Bladesong at the Whispering Bluffs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These grotesque remains are an amalgamation of jelly-like ooze and what appear to be dryad bones.nnGuviena Bladesong would be interested in seeing these.', `QuestDescription`) WHERE `ID` = 42786;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Deal With It Personally', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill the Devouring Darkness in Highmountain, Hertha Grimdottir in Suramar, and Theryssia in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The way I see it, the Wardens owe us for all of those years we were imprisoned. Unfortunately, their new leader, Sira Moonwarden doesn\'t agree with my assessment.nnEven though your champions have already dealt with several of their escaped bounties, she wants more. In fact, as a sign of good faith, she\'s asking that you deal with it personally.nnYou\'ll have to extinguish the flames of the kobold candles to summon forth the Devouring Darkness. The other two should be more straightforward.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Belath Dawnblade on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42787;
