UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Make Your Mark', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Sylessa, Cyrille, and Lorin and slay Overseer Durant.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you were out, I asked around.nnYou are looking for Overseer Durant. Turns out he lives near the Shimmershade Garden.nnI can help you confront him, but you will need help. There are three individuals with the necessary skills, and they serve our cause.nnTell Cyrille that the owl hoots at dusk.nnInform Lorin that the saber prowls the plaza.nnMention to Sylessa that the cruel caskmaster has breathed his last.nnThey will know what to do. nnSpeak to Vanthir when the deed is done.', `QuestDescription`) WHERE `ID` = 42792;
