UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Back in Black', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Back in Black".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Before you head into the Black Temple, we need more information. The last thing we want is for you to teleport into a trap.nnWe must discern their force structure, patrol schedule, new defenses, and what Akama eats for breakfast.nn<Belath grins.>nnI suggest you send our broken warriors to handle this. They can blend in with the rest of Akama\'s Ashtongue forces inside the temple. We\'ll get what we need to know from the ones that make it back.nnA champion handler or two can scout outside the temple.', `QuestDescription`) WHERE `ID` = 42801;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Securing Mardum', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Securing Mardum".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There has been increased demonic activity below on Mardum. There are still demons leftover down there from when we first invaded.nnTo eliminate any threat to the Fel Hammer, it\'s time that they were destroyed.', `QuestDescription`) WHERE `ID` = 42802;
