UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Green Adepts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with your Illidari recruiter, Ariana Fireheart.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As much as I would love us to finesse our way to victory, the cold, hard reality is that we need more powerful forces.nnWe are already straining Gaardoun\'s ability to recruit more broken.nnBut now that we have Ariana Fireheart, she can train new demon hunters for us.', `QuestDescription`) WHERE `ID` = 42808;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Invasion of Niskara', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the Fel Hammer\'s control console and complete the scenario, "The Invasion of Niskara".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Everything is in place. All systems are operational and we have plenty of fuel. The Fel Hammer\'s jump engines are ready.nnCaria and Varedis know that you are coming for them. Belath\'s intelligence indicates that they have retreated to the demon prison world of Niskara.nnIt\'s time to begin the invasion and finish this once and for all.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Altruis the Sufferer on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42809;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Final Offer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate whatever is happening outside of the Fel Hammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What was that? Sounds like something\'s outside.nnSomething big...nnYou\'d better get up there, $n!', `QuestDescription`) WHERE `ID` = 42810;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Meet at Light\'s Hope', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Join the other paladins at Light\'s Hope Sanctum beneath Light\'s Hope Chapel in Eastern Plaguelands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must put Highlord Tirion to rest.$B$BThere is but one place suitable for a paladin of his caliber... Light\'s Hope Sanctum, a secret bastion of the Light hidden beneath our chapel.$B$BPaladins the world over will join us for the ceremony. I know Tirion would want you there most of all.', `QuestDescription`) WHERE `ID` = 42811;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Meet at Light\'s Hope', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Join the other paladins at Light\'s Hope Sanctum beneath Light\'s Hope Chapel in Eastern Plaguelands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Before we march on the Broken Isles, $n, we must put Highlord Tirion to rest.$B$BThere is but one place suitable for a paladin of his caliber... Light\'s Hope Sanctum, a secret bastion of the Light hidden beneath our chapel here.$B$BPaladins the world have gathered below for the ceremony. They await your arrival to begin the ceremony.', `QuestDescription`) WHERE `ID` = 42812;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dalaran Hidden Demon 02', `LogTitle`) WHERE `ID` = 42813;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Important Mission', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Danath Trollbane at Krasus\' Landing in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Champion! I bear an urgent message from Danath Trollbane.$b$bHe requests that you join him at Krasus\' Landing. He has an urgent mission that requires your expertise!', `QuestDescription`) WHERE `ID` = 42814;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Broken Shore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take Danath\'s spare mount to the Broken Shore and provide assistance.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If I\'m to assist in this war, I need firsthand information. I will fly to the Broken Shore and  see the battlefield for myself.$b$bYour record as a proven commander is unquestioned, and you were there. I could use your insight.$b$bWill you accompany me to the Broken Shore? I don\'t anticipate engaging the enemy, but that close to the Fel Storm, one can never be sure.', `QuestDescription`) WHERE `ID` = 42815;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Val\'sharah Hidden Demon 03', `LogTitle`) WHERE `ID` = 42816;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Val\'sharah Hidden Demon 02', `LogTitle`) WHERE `ID` = 42817;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Scarlet Assault', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Thassarian in Scarlet Monastery.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The High Inquisitor of the Scarlet Crusade?!$b$bYou will not find High Inquisitor Whitemane listed in the annals of history alongside the names of fallen heroes.$b$bStill... despite her madness and zealotry she held a bond to the Light unmatched by even the greatest paladins.$b$bThere are few scarlet crusaders left on this world, but Scarlet Monastery is far from abandoned. The monastery now houses the most zealous and crazed crusaders the order has left.$b$bSuccess will require a full blown assault.', `QuestDescription`) WHERE `ID` = 42818;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pocket Wizard', `LogTitle`) WHERE `ID` = 42819;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'DANGER: Aegir Wavecrusher', `LogTitle`) WHERE `ID` = 42820;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Raising an Army', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise 12 Festering Ghouls from the corpses of Scarlet Crusaders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We underestimated the number of scarlet crusaders still residing in the monastery. The battle for control of the cathedral is taking too long.$b$bIt\'s time to take a more resourceful approach to the battle...$b$bRaise the fallen crusaders as ghouls and send them back into the battle against their brothers and sisters.$b$bThe Scarlet Crusade will not be able to hold back the tide of undeath for long.', `QuestDescription`) WHERE `ID` = 42821;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Scarlet Commander', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay High Commander Goodchilde.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is only one more obstacle standing between us and the tomb of Sally Whitemane.$b$bHigh Commander Goodchilde guards the path to the tomb. Although he is a zealot and a murderer, he is still a hardened knight who has dedicated his life to the eradication of our kind.$b$bHe should not be underestimated...$b$bSlay him and our work here will be nearly done.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'High Commander Goodchilde', `PortraitGiverName`) WHERE `ID` = 42823;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Zealot Rises', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise Sally Whitemane as a Death Knight.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Sometimes the line between hero and villain is nothing more than perception. As High Inquisitor, Sally Whitemane saw herself as a champion of humanity in the war against the scourge. Yet under her leadership the Scarlet Crusade slew the living along with the undead.$b$bDeath can bring a silent peace to the soul, but not for Sally Whitemane. Her death is one of regret and unrest.$b$bWe will offer her the chance to atone for her crimes. The price will be high, but I have little doubt she will pay it.', `QuestDescription`) WHERE `ID` = 42824;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Azsuna Hidden Demon 01', `LogTitle`) WHERE `ID` = 42825;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Highmountain Hidden Demon 01', `LogTitle`) WHERE `ID` = 42826;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ancient Mana Chests 01', `LogTitle`) WHERE `ID` = 42827;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moths to a Flame', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Underglow Locusts.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'No doubt you have noticed our guests.nnI have watched them for a time and seen how they are attracted to the tree. I do not know if they are harmful to our sapling, but we cannot take that chance.nnCollect a handful of the insects and bring them to me. I will examine them and determine if they are to be left alone.', `QuestDescription`) WHERE `ID` = 42828;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Make an Entrance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Ly\'leth Lunastre outside the Twilight Vineyards.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I need you to infiltrate the Twilight Vineyards and bring back something to deal with these insects.nnTo do that, you will need a way to bypass the guards that keep the orchards secure.nnLy\'leth will be able to help us there. I will arrange to have her meet you near the entrance.nnGo quickly!', `QuestDescription`) WHERE `ID` = 42829;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pest Management', `LogTitle`) WHERE `ID` = 42830;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Shal\'an', `LogTitle`) WHERE `ID` = 42831;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fruit of Our Efforts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Taste the Honeyed Infusion, Supple Nectar, and Unctuous Draught.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is my job to maintain appearances here.nn<Margaux smiles apologetically.>nnYou will have to endure a little showmanship while I walk with you through the vineyard. It is the only way to avoid suspicion.nnI will try to help you as I can, but only when it is safe to do so.nnCome with me- our first stop is the tasting pavilion. There you can sample some of our work.', `QuestDescription`) WHERE `ID` = 42832;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'How It\'s Made: Arcwine', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Margaux through the Vineyard. Exchange information where possible.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Margaux speaks in a hushed tone.>nnWhile we walk through the Vineyard, we may find time to exchange information.nnTry not to look alarmed at what you see, hm?nn<Margaux flashes a vacant, forced smile.>nnShall we press on?', `QuestDescription`) WHERE `ID` = 42833;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Intense Concentration', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Catch 15 drops of Nightwell Essence using an Energy Vessel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is a rare treat, I hope you know. Not just anyone is allowed to stand on this hallowed ground.nn<Sylverin adjusts his cuffs in a dignified fashion.>nnTo participate in the demonstration, simply take up an energy vessel and wade into the pool beside us. nnCatch the delicate dewdrops of Nightwell energy in the bowl as they fall- this is the only way one can safely manage its essence.nnOnce your vessel is full, proceed to our demonstration cask and gently pour the amalgamation into it.nnEnjoy!', `QuestDescription`) WHERE `ID` = 42834;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Old Fashioned Way', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Participate in a juicing demonstration.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you experienced the raw majesty that is Nightwell Infusion, Margaux was busy preparing another demonstration for you.nnHead across the bridge and to the left, then again across a bridge and to your right. You will find her on the juicing veranda.nnEnjoy the remainder of your tour!nn<Sylverin offers an intensely fake smile.>', `QuestDescription`) WHERE `ID` = 42835;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Silkwing Sabotage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 8 Tattered Silkwings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Moths. Who ever heard of something so... barbaric!nnThey are eating our crop and the mana wyrms do nothing to deter them.nnYou. You seem capable. Deter these creatures so we can complete our harvest on schedule.nnAhem. Please.', `QuestDescription`) WHERE `ID` = 42836;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Balance to Spare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Shadescale Flyeaters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our tour is just about over. I will let you loose to \'walk the orchard\', as is proper at this stage.nnWhile you are there, you will notice a large number of mana wyrms floating about.nnI am certain the vineyard would not miss a handful of them.nnGood luck with your insect problem, friend.nn<Margaux smiles warmly at you.>', `QuestDescription`) WHERE `ID` = 42837;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Reversal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Margaux.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Sylverin regards you uneasily.>nnI was meant to meet you and Margaux here so I could escort you from the Vineyard. nnMy mistress Margaux is never late. I fear that something terrible may have happened.nnPlease find her and make sure she is well.', `QuestDescription`) WHERE `ID` = 42838;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seek the Unsavory', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Vanthir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is just... unspeakable.nnMargaux risked everything to get these mana wyrms to us. I cannot let it end this way.nnI need you to find someone who can make this right. Someone who will do whatever it takes to see Overseer Durant slain.nnSpeak with Vanthir. I am certain he will know exactly who we need.', `QuestDescription`) WHERE `ID` = 42839;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'If Words Don\'t Work...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bribe Arluin with 800 Ancient Mana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Unless you have something worth risking my life for, I will not budge.nnVanthir must have told you that my services do not come cheap.nnLet\'s say... enough mana to sustain me for a month.nn<Arluin looks smug, as if you could never agree to this request.>', `QuestDescription`) WHERE `ID` = 42840;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Big Score', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Attack the Magistrix\'s arcwine shipment and bring Arluin his cut of the stolen goods.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m not rich in anything but information, but maybe that can be of use to someone with your skills. You helped me, now you can help yourself.nnThe Magistrix receives a daily shipment of arcwine, which travels to the palace with a heavy escort. I can share the location, provided you leave me a cut of the goods.nnOne of my men has infiltrated the group and will hold up the delivery long enough for you to strike.', `QuestDescription`) WHERE `ID` = 42841;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ancient Mana Cap 01 Kel\'danath\'s Flask', `LogTitle`) WHERE `ID` = 42842;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Maxwell Tyrosus at the Sanctum of Light.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lord Maxwell Tyrosus has requested your presence back at the Sanctum of Light.$B$BOur campaign to defend the Broken Isles is getting under way, and we need you at the helm.', `QuestDescription`) WHERE `ID` = 42844;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Blood Matriarch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enlist Lady Liadrin as a champion of the Order of the Silver Hand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I am but the first of many; you must find the holiest of paladins to champion our order.$B$BThere is one other I believe deserves such an honor - Lady Liadrin, Matriarch of the Blood Knights.$B$BGo speak to her now.', `QuestDescription`) WHERE `ID` = 42846;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Storms', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Dark Storms."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, Highlord.$B$BBeside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.$B$BThe first task is critical - the storms above the Tomb of Sargeras are intensifying. We should send our champions to keep an eye on that region, and scour the area for possible survivors.', `QuestDescription`) WHERE `ID` = 42847;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting the Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Commander Ansela and recruit a squad of Squires.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander Ansela is a grizzled war veteran and seasoned teacher. Many of our most valiant knights once trained under her.$B$BGo speak to her now, and recruit a squad of Squires.', `QuestDescription`) WHERE `ID` = 42848;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wrath and Justice', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Wrath and Justice."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A new mission requires our attention, Highlord $n. Hearthglen has come under attack by a small demon army.$B$BNo doubt, they are testing our strength... and our patience.$B$BStrength we have in bounds, but my tolerance wears thin. I suggest we send our champions and troops to deal with this threat.', `QuestDescription`) WHERE `ID` = 42849;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tech It Up a Notch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Alamande Graythorn and choose a class hall upgrade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alamande Graythorn is well known among scholars of the Light.$B$BHe has long since retired from battle, but his mind is sharp as ever. I wouldn\'t be surprised if he could take a bout or two in a duel, either.$B$BSpeak to him and see if he has any knowledge to share regarding the improvement of our order hall.', `QuestDescription`) WHERE `ID` = 42850;
