UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moist Around the Hedges', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Moist Grizzlecombs  in Grizzleweald.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These fruit appear to be food to grell.nnOld Grizzleback might appreciate it if they were removed from the village.', `QuestDescription`) WHERE `ID` = 42857;
