UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grell to Pay', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Enderkind in Grizzleweald.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The ringleader of the grell must be sent to his final rest.nnYou will know him by the white of his skin and the bite of his tongue.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Ringleader of the grell. Chief mischief maker. Violent and unpredictable. Foulmouthed.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Enderkind', `PortraitGiverName`) WHERE `ID` = 42865;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Sign From The Sky', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archmage Khadgar in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, Highlord. I have important news to share with you.$B$BDuring my expedition to the Broken Shore, I saw with my own eyes an extraordinarily luminescent object emerge from the Felstorm. It fell down towards the coast of Suramar, cutting a swath through the tempest itself!$B$BFrom it I felt an incredible surge of power, before it vanished beyond the horizon.$B$BWe need to bring news of this immediately to Archmage Khadgar.', `QuestDescription`) WHERE `ID` = 42866;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Meeting of the Silver Hand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Lady Liadrin, Vindicator Boros, Justicar Julia Celeste, Arator the Redeemer, and Aponi Brightmane.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Light\'s Heart will be safe within our order\'s walls, but it bears dark tidings.$B$BWe should gather the leaders of our order for a council.$B$BGo and speak to Lady Liadrin, Vindicator Boros, Justicar Julia Celeste, Arator the Redeemer, and Aponi Brightmane. We should seek their wisdom for the days ahead.', `QuestDescription`) WHERE `ID` = 42867;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Monkey King\'s Challenge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help the Monkey King to complete his brew.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You can roll, you can hit, even shoot flaming spit...nBut can your training you heed? Tasty brew\'s what I need!nThe goodies you\'ve gathered are what you must mix,nThe instructions to follow will come from my lips.nJust pass this final brewing lesson,nAnd I will point you to my weapon.', `QuestDescription`) WHERE `ID` = 42868;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eternal Vigil', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Glide to Illidari Redoubt off of Krasus\' Landing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Kor\'vas glances at your glaives, her eyes widening.>$B$BI\'m excited to see what those can do in person! Maybe we can spar a bit before heading out on the next hunt?$B$BWhile you were gone we built a camp just off of this landing to help us watch over the Legion\'s movements. We should head there right away - Jace needed your help with something. It sounded big!', `QuestDescription`) WHERE `ID` = 42869;
