UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Securing the Way', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your glaives to rip open a gateway to the Fel Hammer in Mardum.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was able to make contact with our forces on Mardum - they secured the Fel Hammer after our departure all those years ago and have held it ever since!$B$BMalevolence has utilized the ship\'s warp systems to transport the bulk of our forces aboard, but doing so greatly taxes what little power remains.$B$BI believe there to be a better way.$B$BYour glaives carry a piece of the power of Kil\'jaeden - you should be able to use them to open a permanent gateway to the Fel Hammer.', `QuestDescription`) WHERE `ID` = 42872;
