UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Scarlet Massacre', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 16 Scarlet Crusaders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have a single purpose here, to raise Sally Whitemane as a Death Knight of the Ebon Blade. Such is our goal and we will see it through.$b$bHowever, the Scarlet Crusade has terrorized the people of Azeroth long enough. Therefore, our work here this day will not be done until every crusader has fallen, every stone has crumbled, and every banner burned.$b$bCome, Deathlord, let us bring ruin upon the Scarlet Crusade.', `QuestDescription`) WHERE `ID` = 42882;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'All Grell Broke Loose', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Wildeyed Undergrell in Grizzleweald.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The grell are in a frenzy, attacking my brethren and destroying our village!nnPlease, stranger, help us send these wicked miscreants to the soil.', `QuestDescription`) WHERE `ID` = 42883;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grassroots Effort', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Old Grizzelback\'s Staff to destroy $1oa snarled brambles in Grizzleweald.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When I arrived at my home, the front door was barred by magical roots.nnI was able to remove them, but few of my tribe possess the necessary ability to do so themselves.nnTake my staff. Its powers will easily disentangle the obstructing roots.', `QuestDescription`) WHERE `ID` = 42884;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Highlord\'s Command', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the mission, "The Highlord\'s Command: Nemesis."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tracking down the dreadlord Balnazzar is our highest priority. Let us send defenders of our order to pinpoint his recent movements.', `QuestDescription`) WHERE `ID` = 42885;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Faronaar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Vindicator Boros along Old Coast Path.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are keeping a close eye on Legion movements at Faronaar in Azsuna.$B$BOur intel suggests that a high-ranking lieutenant, possibly the dreadlord Balnazzar himself, masterminds the attacks in that region.$B$BThis may be our chance to strike a blow at the Legion\'s leadership.$B$BVindicator Boros commands our forces at the front. He would welcome your help, Highlord.', `QuestDescription`) WHERE `ID` = 42886;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'This Is Retribution', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 20 demons in lower Faronaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Anger seethes within me like smoldering coals.$B$BOne stoke, and that anger will flare into a roaring flame.$B$BThe Legion\'s attack on Exodar was just the motivation I needed, Highlord. I\'ve watched my brethren die for the last time.$B$BNow, I will be the one who does the killing. I WILL have justice! Help me, Highlord, and slay any demons you encounter in lower Faronaar.', `QuestDescription`) WHERE `ID` = 42887;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Communication Orbs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy 3 Legion Orbs.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have important work at hand, Highlord.$B$BSpread out across the legion camp are orbs that are vital to the Legion\'s planning and strategy.$B$BDestroying them will severely damage their efforts. I will go with you, Highlord, to see this through.', `QuestDescription`) WHERE `ID` = 42888;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Way Back Home', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the beacon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hello? This is Chief Telemancer Oculeth. I see you have emerged safely!$B$BI am locking in your location as we speak. I will need you to activate the beacon on your end so we can establish a teleportation link.$b$bGot it? Good.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Activate the portal and return to Shal\'Aran.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Chief Telemancer Oculeth', `PortraitGiverName`) WHERE `ID` = 42889;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Codex of Command', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 1 Codex of Command and rescue Vindicator Boros.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Boros is in serious trouble.$B$BThe fel lord, Jarvox, guards the pit to the west. Boros is trapped in there, too.$B$BWe need to defeat Jarvox, take the Codex of Command that he carries, and rescue Vindicator Boros.$B$BI am with you, Highlord!', `QuestDescription`) WHERE `ID` = 42890;
