UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Drowned Mana', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Fish up a Drowned Mana for Conjurer Margoss.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'How did you end up out here?  Ah well, that\'s neither here nor there at this point.  What matters is that I need your help!nnI see you have some experience fishing. Think you could put that skill to use for me?', `QuestDescription`) WHERE `ID` = 42911;
