UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demonic Runes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 30 Demonic Runes from demons in the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hodir valiantly went through that demonic portal. He should\'ve earned an honorable death, but instead was taken prisoner by Legion scum.$B$BWe always imagined the battles of the end days to take place here in Azeroth, but we shall bring the fight to the enemy if it means sparing one of our own that terrible fate.$B$BHymdall thinks that with the right power source, he can reactivate and redirect to Legion\'s own gateways. Gather demonic runestones from Legion and let the final conflict begin!', `QuestDescription`) WHERE `ID` = 42918;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Scion\'s Legacy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Listen to the leaders of the council.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The leaders of the Silver Hand have gathered. Listen to their counsel.', `QuestDescription`) WHERE `ID` = 42919;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Invasion of Niskara', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the Fel Hammer\'s control console and complete the scenario, "The Invasion of Niskara".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Everything is in place. All systems are operational and we have plenty of fuel. The Fel Hammer\'s jump engines are ready.nnCaria and Varedis know that you are coming for them. Belath\'s intelligence indicates that they have retreated to the demon prison world of Niskara.nnIt\'s time to begin the invasion and finish this once and for all.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Kayn Sunfury on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42920;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Confrontation at the Black Temple', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Gateway to the Black Temple and confront Akama.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The book from Lan\'dalock is very enlightening. It describes a technique which will provide a simple and elegant bypass around the Black Temple\'s holy barriers.nnI will need but a moment to summon a gateway. Stand back, please.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Travel to the Black Temple and confront Akama. Convince him to join forces with you in the fight against the Burning Legion.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Akama', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Kayn Sunfury on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 42921;
