UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Small Favor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Ari.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Meryl\'s illness is troubling. I have seen something similar before, but I cannot think of its name...nnTalk to my friend. I call her Ari. She has lived here in the Hall of the Guardian since it was last in use. If a tome on magical afflictions is to be found here, she would know where to look.', `QuestDescription`) WHERE `ID` = 42954;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Proper Way of Things', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Siphon 50 phials of nightwell energy from the nightborne in Suramar City.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Khadgar is my friend. That he trusts you means much. nnI know of the book in which you seek, but it does not want to be found. It is old and angry and thirsts for power. We will have to convince it to emerge from hiding in the proper way. Perhaps if you bring it a gift of nightwell energy from the nightborne elves in Suramar City it will be mollified.', `QuestDescription`) WHERE `ID` = 42955;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ari\'s Package', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Ari\'s package to Archmage Khadgar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Look! It was right here under our noses. "Arcanists Guide to Rare Diseases." Sheepish thing. Most books just want to be dusted off and read from time to time. We will leave the phials of nightwell energy and it will go with you meekly enough.nnHere. I have packaged the book up for you to bring to Khadgar. I wrapped it in moth\'s wings to keep it soothed and light-hearted. And there is a gift for you. Just a small thing, really.', `QuestDescription`) WHERE `ID` = 42956;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Journey to the East', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with the Monkey King at the Temple of the Jade Serpent within the Jade Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My riddles you\'ve solved but your job is not complete.nnCome, meet me at the Jade Serpent Temple for the answers you seek.', `QuestDescription`) WHERE `ID` = 42957;
