UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Highlord\'s Command', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the mission, "The Highlord\'s Command: Holy Allies."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Good decision, Highlord. We should be bolstering our forces by increasing recruitment efforts. Let us send our champions to carry out these orders.', `QuestDescription`) WHERE `ID` = 42966;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Highlord\'s Command', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the mission, "The Highlord\'s Command: Legion Defense."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well said, Highlord. The Legion is not one individual enemy - it is a massive beast with many heads.$B$BTo defeat them, we will need to stay vigilant on all fronts.$B$BLet us send our champions to deal with the Legion incursions as they come.', `QuestDescription`) WHERE `ID` = 42967;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Highlord\'s Command', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the mission, "The Highlord\'s Command: Procuring Supplies."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You are right, Highlord. Our military efforts cannot succeed without solid logistics.$B$BThat means we need a steady supply of weapons, food, medicine, and other provisions.$B$BLet us send our champions to establish a supply line.', `QuestDescription`) WHERE `ID` = 42968;
