UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Diamond King', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go with Brann and Khadgar to Ulduar and hear Magni Bronzebeard\'s message.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Me brother Magni, once King o\' Ironforge, got changed into a diamond statue by a titan ritual. He\'s stood frozen in the belly o\' the city fer years.$b$bBut I just got word that he\'s up and around... sayin\' he knows somethin\' \'bout how to beat the Legion!$b$bLook, $n, I dunno if Magni\'s crazy, or if that\'s even really him. But if there\'s even a chance he kin help us...$b$bI\'m told he muttered the name Ulduar. That\'s where I\'m headed! I\'d be obliged if you an\' Khadgar were ta join me.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet with Khadgar outside Karazhan.', `QuestCompletionLog`) WHERE `ID` = 42970;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Controlling the Elements', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve Remnants of Fire, Water, and Air, and reach Revered status with Therazane.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Come closer, $r.$b$bRagnaros in the Firelands, Al\'Akir in his Throne of the Four Winds, and Neptulon in Throne of the Tides. They have been thorns in my hide since the world was new.$b$bProve to me your strength over the weaker elements, and I shall teach you how to display your power for all to see.', `QuestDescription`) WHERE `ID` = 42971;
