UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fate of Hodir', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Join your forces at Felblaze Ingress and Complete the Fate of Hodir scenario.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time, $n. Go to Azsuna and use the captured gateway to travel to Niskara and find Hodir.$B$BThe Legion will regret they set foot on Azeroth!', `QuestDescription`) WHERE `ID` = 42974;
