UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Servant of the Windseeker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Highlord Demitrian in Silithus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The elemental lords must be united,  but there has been no Windlord to lead the air elementals since the death of Al\'Akir.$b$bOnce, there was an heir to the Throne of Four winds named Prince Thunderaan, but the prince was defeated in the mortal realm and still awaits rebirth. Only one man holds the knowledge necessary to complete the prince\'s rebirth.$b$bThere is a servant of Thunderaan who wanders the sands of Silithus. Find him, and he will show you the way.', `QuestDescription`) WHERE `ID` = 42977;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Royal Audience', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to King Anduin Wrynn in Stormwind Keep.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n,$B$BMy father lived by the sword, as you do. He taught me that if we truly want peace for our kingdom then we must be willing to fight to preserve it, as you have fought.$B$BYou have demonstrated valor of the highest order - bravery unsurpassed in the ranks of the Alliance. Valor that must be recognized.$B$BPlease join me in Stormwind Keep at once so that you can be properly rewarded for your service.$B$B- King Anduin Wrynn', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'King Anduin Wrynn', `PortraitGiverName`) WHERE `ID` = 42978;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest: Lumenstone 2', `LogTitle`) WHERE `ID` = 42980;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Victor\'s Spoils', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise your weapon and be recognized in Stormwind Keep.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It takes a true hero to put their life on the line day after day in defense of their home so that others do not have to.$B$BYou have dutifully safeguarded the people and interests of the Alliance, never faltering in your courage or devotion.$B$BAs a small token of our appreciation for your valiance, please turn to the gathered heroes before you, raise your weapon high, and be recognized.', `QuestDescription`) WHERE `ID` = 42982;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mistral Essence', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 100 Mistral Essences from wind elementals in Vortex Pinnacle. Travel to the Vortex Pinnacle through the portal in the Heart of Azeroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To restore the Maelstrom Pillar, we will need to infuse it with the essence of air.$B$BA large quantity of Mistral Essence will be required to do this.$B$BMistral Essence can be found on many of the elementals in Vortex Pinnacle.$B$BIf you can return to me with a ready supply of elemental essence, I will be able to continue my restoration work on the Maelstrom Pillar.', `QuestDescription`) WHERE `ID` = 42983;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: The Scepter of Storms', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Scepter of Storms from Lady Hatecoil in the Eye of Azshara dungeon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The element of air can be difficult to contain. We will need a way to magically anchor it to the pillar.$B$BAir, no matter how capricious, cannot resist a good storm.$B$BIn the Eye of Azshara, the naga sorceress known as Lady Hatecoil possesses a powerful relic known as the Scepter of Storms.$B$BRetrieve the scepter, and we will use it to bind the elements of air to the Maelstrom Pillar.', `QuestDescription`) WHERE `ID` = 42984;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Royal Audience', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Report to Warchief Sylvanas Windrunner in the Undercity.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n,$B$BThose who do not stand with the Horde stand against it. You, champion, have cut down such enemies in droves.$B$BI admire your dedication. It is through you that we will rise up, more powerful than ever, and put the Alliance in their place once and for all.$B$BJoin me in the Undercity at once. Your victories must be met with due reward.$B$B- Warchief Sylvanas Windrunner', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Sylvanas Windrunner', `PortraitGiverName`) WHERE `ID` = 42985;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Enemies of Air', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 4 "Thunderaan\'s Enemies" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Windlord Thunderaan has retaken the Vortex Pinnacle, but not all of his subjects have taken to his leadership kindly.$B$BIn his kingdom there is still unrest, and it appears there are four viziers who have risen up against him: Mistius, Zeph, Alacris, and Tulmos.$B$BWe will let Thunderaan focus on the war against the Burning Legion while we send our champions to aid Skywall against its enemies.', `QuestDescription`) WHERE `ID` = 42986;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Victor\'s Spoils', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise your weapon and be recognized in the Undercity.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We will never be dominated so long as you stand at the front of our lines. Together we will slaughter anyone who stands in our way.$B$BYou have sacrificed as much as any in the name of the Horde. I will not let your dedication go unnoticed.$B$BFace your fellow champions, $n. Face them, and be recognized.', `QuestDescription`) WHERE `ID` = 42987;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Worldmender', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 World Quests.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The elements have gathered, and though the Firelands have yet to unite with us, we have more strength on our side than ever before.$B$BHowever, the war with the Burning Legion still rages, and for now we must turn our gaze to the Broken Isles.$B$BWhen we have dealt sufficiently with the immediate threats of the war, we will turn our attention to uniting the Firelands to our cause.', `QuestDescription`) WHERE `ID` = 42988;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ma\'haat the Indomitable', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Ma\'haat the Indomitable in Deepholm to acquire a Fossilized Egg. He will require 5 Blood of Sargeras in trade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to imbue the Maelstrom Pillar with the essence of earth, we will need one of the rarest fossils found on Azeroth - an egg.$B$BThe Egg of Gaiath is no ordinary egg; it contains the remnants of an unborn earthen primal, perfectly preserved in stone. There may be a means by which to revive it, but more on that later.$b$bFirst, we must find that egg!$B$BThe Earthen Ring has heard of an ancient being who possesses such an item, but he will require payment in blood!', `QuestDescription`) WHERE `ID` = 42989;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Neltharion\'s Lair: The Earthen Amulet', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Earthen Amulet from Dargrul the Underking in Neltharion\'s Lair.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That you were even able to acquire the Egg of Gaiath  is an incredible feat in itself, but the next step may well be impossible. Still... it is our only hope.$B$BFor the ritual to work, we will need to awaken the latent elemental energy resting inside of this egg.$B$BThere is an item that just may have the ability to do this - a relic known as the Earthen Amulet, rumored to have been created by Loken himself.$B$BIt was lost many ages ago, and has fallen into the hands of Dargrul the Underking.', `QuestDescription`) WHERE `ID` = 42990;
