UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blessed Blade of the Windseeker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate the lost blade of the Windseeker.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So the Earthen Ring wishes to resurrect my master?$b$b<Highlord Demitrian laughs maniacally.>$b$bI knew this day would come! At last, humanity understands the power of the Windseeker!$b$bWhen Prince Thunderaan was slain at the hands of treacherous mortals, his soul was trapped within the sacred blade Thunderfury.$b$bTo resurrect my master you will need to find his sword and return it to Skywall. Last I heard, the betrayer who stole my master\'s sword traveled to the Broken Isles to fight demons.', `QuestDescription`) WHERE `ID` = 43002;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Janai', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Elementalist Janai at the Heart of Azeroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Ma\'haat the Indomitable speaks to you with a low, rumbling voice.>$b$bHere... is the Egg of Gaiath. It is yours now.$b$bGo... in peace.', `QuestDescription`) WHERE `ID` = 43003;
