UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Chamber of Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lord Jorach Ravenholdt in the Chamber of Shadows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lord Jorach Ravenholdt sent me out to find you, $n. He wants your counsel on some matter of importance.nnHe requests your presence back at the Chamber of Shadows.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Return to me in the Chamber of Shadows at your earliest convenience.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Lord Jorach Ravenholdt', `PortraitGiverName`) WHERE `ID` = 43007;
