UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The School of Roguery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lonika Stillblade and train a Gang of Bandits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Great! Sounds like she\'s already settled in. That\'s good, cuz we already need some fresh meat for the grinder.nnYou should mosey over an\' see if she\'s got any thieves just lying around takin\' up space.', `QuestDescription`) WHERE `ID` = 43013;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Big Bad Wolfe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "The Big Bad Wolfe".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve heard of Winstone Wolfe, right? Of course you have. Who hasn\'t?nnSo, while you were off gabbin\' with the headmistress, Lord Ravenholdt graced me with his presence. In the flesh. I didn\'t think he ever came out of that chamber.nnAnywhoodles, he more than suggested, in that way of his, that we send Garona, Vanessa, and our new merry gang of bandits off to have a little chat with The Wolf at Ravenholdt Manor.nnJust make sure they\'re nice and civil, or that\'s the last we\'ll see of them.', `QuestDescription`) WHERE `ID` = 43014;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'What Winstone Suggests', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Winstone Wolfe.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If anyone can improve the way things run around here, it\'s Winstone Wolfe. I tell ya, the man is a miracle-worker!nnNow that he\'s workin\' for us, shall we pick his brain an\' see what he suggests?', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'The Wolf is here to solve problems for us. He\'s brilliant and charming with an extra helping of deadly piled on top.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Winstone Wolfe "The Wolf"', `PortraitGiverName`) WHERE `ID` = 43015;
