UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Further Training', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike abilities 10 times each.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You may be the Grandmaster, but mastery must be maintained through discipline.$B$BTo achieve perfect harmony, you must continue your training.$B$BI would like to see your form in practice, $n. Go out and use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike. Through discipline, we find greatness.', `QuestDescription`) WHERE `ID` = 43062;
