UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ulduar\'s Oath', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ask Hymdall to sound the Gjallarhorn and request Thorim\'s assistance.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was once leader of all of the titanforged keepers of Azeroth.  We were charged by the Titans themselves to protect the world.$B$BOnce I gave up on the post of Prime Designate, I gave up any measure of influence over the other keepers.  Not even my own son, Thorim, is bound to heed my commands.$B$BThe Gjallarhorn comes from a time before our falling out, however.  A time of an ancient oath of honor.$B$BLet us invoke that oath -- I am certain Thorim will answer the call.', `QuestDescription`) WHERE `ID` = 43090;
