UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Raven\'s Eye', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Listen to Valeera\'s tale of the Raven\'s Eye.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is imperative that we decipher the SI:7 letter. We must uncover the secrets that it holds before it is too late. But, our best code breakers have yet to make a dent in the cypher.nnHowever, we now know that the myth is in fact reality. The Raven\'s Eye truly exists.nnShall we tell the others?', `QuestDescription`) WHERE `ID` = 43249;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Off to Court', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet up with Valeera Sanguinar at Ravencourt in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Ravencourt of Black Rook Hold is where we begin our search. It is the ancestral home of Lord Kur\'talos Ravencrest, night elven hero of the War of the Ancients. Some of my own ancient ancestors are interred in its cemetery.nnMeet me there and make sure that you are not followed. SI:7 is very good at what they do. We have to be better.', `QuestDescription`) WHERE `ID` = 43250;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In Search of the Eye', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Pick the locks of the Ancient Chests to find the Raven\'s Eye.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Raven\'s Eye should be somewhere within the courtyard. This is where Ravencrest\'s lieutenants used to plan their strategies in life. Hell, it looks like they still might be doing so in death.nnIt has to be around here somewhere. Your skill at lock picking should prove invaluable.', `QuestDescription`) WHERE `ID` = 43251;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eternal Unrest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Put Cesta Stargazer, Mandrel Nightsbane, and T\'rel Moonblade to rest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My ancient ancestors are buried here in the cemetery to the west. Because of whatever is causing the dead to rise, their souls are now at unrest.nnAll blood elves are descended from high elves, who in turn came from these lands before they were sundered.nnI cannot bring myself to do it. Will you put my ancestors to rest?', `QuestDescription`) WHERE `ID` = 43252;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maw of Souls: Ancient Vrykul Legends', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather a group and take an etching of the Raven\'s Eye Tablet on the ship of the dead, The Naglfar, in the Maw of Souls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our diversionary tactics in Stormheim uncovered intel on something I thought only a myth.nnThere is a legend about a magical jewel the vrykul created long before the time of man. The jewel was said to be able to...nn<Valeera stops herself from continuing while looking around and eyeing you wryly.>nnI do not want to talk about it just yet. Not until we have proof.nnUnfortunately, the only way we are going to get that proof is in the Maw of Souls on the Naglfar... the ship of the dead.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Valeera Sanguinar in the Chamber of Shadows.', `QuestCompletionLog`) WHERE `ID` = 43253;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ritual Ruination', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Fel Bat to the Tomb of Sargeras and steal the Scepter of Sargeras.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Time for main event, friend! Gul\'dan wants to begin his big ritual, cause end times for this world. Calydus confident getting the Scepter will stop that plan.$b$bTake this bat to Tomb of Sargeras, find ritual, steal Scepter. Oh... and get out!$b$bCalydus will help when he can! Good luck, friend!', `QuestDescription`) WHERE `ID` = 43254;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure 061 - Nastrondir', `LogTitle`) WHERE `ID` = 43255;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Beware of the Crooked Tree', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the crooked tree in Bradensbrook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$R, you must be warned. There is great evil in Val\'sharah. I\'ve seen it, and I wish I hadn\'t. If you take my advice, you will stay far away from the crooked tree in Bradensbrook.', `QuestDescription`) WHERE `ID` = 43259;
