UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Nazgrim and Thassarian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your power is great, Deathlord, but power alone will not be sufficient.$b$bIf we are to save this world from the onslaught of the Burning Legion, then you will need powerful allies. The Knights of the Ebon Blade are yours to command, it will be wise to make use of them effectively.$b$bGo and speak with Nazgrim and Thassarian. They will be of great use to you in the fight against the Burning Legion.', `QuestDescription`) WHERE `ID` = 43264;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spread the Word', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting map and complete "Spread the Word."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you have recruited your champions, you can use the Scouting Map to complete vital missions across the Broken Isles.$b$bThe first mission is critical to the growth and power of our order. Send Nazgrim and Thassarian to seek out new candidates for the Ebon Blade.$b$bOur order must grow in strength if we are to defeat the Burning Legion.', `QuestDescription`) WHERE `ID` = 43265;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting the Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Dark Summoner Marogh to summon ghouls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A powerful necromancer has joined the cause of the Ebon Blade.$b$bDark Summoner Marogh has come a long way to us from deep within the realm of the Shadowlands. He will be a powerful ally of the Ebon Blade.$b$bSpeak with Dark Summoner Marogh to begin raising an army of ghouls for the Ebon Blade.', `QuestDescription`) WHERE `ID` = 43266;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Troops in the Field', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Command Table and complete the mission, "Troops in the Field."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s time to send our newly summoned ghouls out into the field. Look at the Command Table and send your champions and troops on a routine scouting mission.', `QuestDescription`) WHERE `ID` = 43267;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tech It Up A Notch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archivist Zubashi in Acherus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archivist Zubashi has been doing a great deal of research on the necropolis we call Acherus.$b$bThrough his studies on the necropolis, he has located a number of potential improvements that can greatly increase the power of the Ebon Hold.$b$bSpeak with Archivist Zubashi now and he will show you what improvements can be made.', `QuestDescription`) WHERE `ID` = 43268;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise, Champions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recruit Calia Menethil and High Priestess Ishanah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As leader of our order, other priests will look to you for guidance. Many will be willing to pledge themselves to you, doing whatever is necessary to bring down the Burning Legion.$B$BAfter your display of power during the cleansing ritual, there will be many who are eager to serve at your side. Seek out those priests, and let them ease the burden of leadership.', `QuestDescription`) WHERE `ID` = 43270;
