UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spread the Word', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Command Map and complete the mission, "Spread the Word".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In the center of the dais is a map of the Broken Isles. From it, you can direct our allies to carry out vital assignments across the world.nnThe first task is critical to the growth of our order - identifying skilled priests whom we can trust to train our order\'s troops.nnThis is a task we can easily entrust to one of our new champions.', `QuestDescription`) WHERE `ID` = 43273;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting the Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Grand Anchorite Gesslar and train a troop of acolytes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our recruiting efforts have paid off. Grand Anchorite Gesslar has pledged his service to our order.$B$BHe has an eye for greatness, and can easily spot a recruit with potential. He takes those selected under his wing, and shapes them into worthy allies.$B$BSpeak to him now and train a troop of acolytes.', `QuestDescription`) WHERE `ID` = 43275;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Troops in the Field', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Command Map and complete the mission, "Troops in Training".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s time to send our newly trained acolytes out into the field. Look at the Command Map and send your champions and troops on a routine scouting mission.', `QuestDescription`) WHERE `ID` = 43276;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tech It Up A Notch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archon Torias in Netherlight Temple.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are very fortunate to have come across Archon Torias.nnHis knowledge will be invaluable as we improve our defenders and fortify Netherlight Temple.', `QuestDescription`) WHERE `ID` = 43277;
