UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Time to Rumble!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with David Globerunner and find out how to participate in the Black Rook Rumble.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Welcome to the Black Rook Rumble!  Many combatants have entered to prove their might in the Black Rook Arena, and now it is your time.', `QuestDescription`) WHERE `ID` = 43303;
