UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Time to Collect', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Sixtrigger\'s Key from Rax Sixtrigger in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hey there, pal. My sources around here say you had a run-in with the Sixtrigger brothers. I\'d imagine you\'re not very happy with them?nnLet\'s just say we\'re not exactly friends either.nnSo I\'ll tell you what. How about I let you in on some intel about their current location? Maybe they might have an unfortunate accident, you follow?nnOh, and bring some friends. They\'re not exactly the easiest of targets.', `QuestDescription`) WHERE `ID` = 43331;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grell in a Handbasket', `LogTitle`) WHERE `ID` = 43332;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'DANGER: Nylaathria the Forgotten', `LogTitle`) WHERE `ID` = 43333;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Coming Storm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Pandaria and speak to the White Tiger at his temple.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You saved us all, my friend! Truly you embody all the elements stand for.$b$bIf the Earthen Ring is to prevail, we will need weapons of great power. I know where to find some. After the Pandaren Campaign, the weapons of the storm god Ra-den were discovered beneath the Throne of Thunder. None have been able to wield them, so great is their power.$b$bThey were placed in the care of the White Tiger, who will give them only to one who is worthy. Come $n! Travel with me to Pandaria and we will prove your worth!', `QuestDescription`) WHERE `ID` = 43334;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Survival Skills', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Show your survival skill by building a campfire from chopped wood, and cooking a steak over an open flame.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The life of a hunter should never be dull. Living in the wild you never know what will happen next, but you survive on skill and instinct.$B$BShow me you have the basic survival skills to live off the land.', `QuestDescription`) WHERE `ID` = 43335;
