UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Codex of Ra', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Guo Lai Halls in the Vale of Eternal Blossoms and collect the Edict of Stone, the Edict of Fire, and the Edict of the Storm. Cleanse the area by slaying mogu spirits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Thunder King conquered Pandaria using power stolen from the Titan Keeper Ra, known as "Ra-den" in the mogu tongue. If you truly seek to wield the relics of the Highkeeper, seek out his ancient edicts among the ruins in the heart of the mogu empire: The Edict of Stone, The Edict of Fire, and the Edict of the Storm.$b$bThese pieces of the codex are scattered amongst the Guo-Lai Halls in the Vale of Eternal Blossoms, one in each wing.', `QuestDescription`) WHERE `ID` = 43338;
