UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Uniting the Isles', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Earn at least Friendly reputation with the factions of the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'We need your help!', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Archmage Khadgar', `PortraitGiverName`) WHERE `ID` = 43341;
