UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Aegis of Aggramar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Secure the Aegis of Aggramar in the Chamber of the Guardian in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that it\'s out of the hands of the Legion, the Aegis should be brought back to Dalaran for safekeeping while the hunt continues for the rest of the Pillars of Creation.nnIt should be safe in the central portal chamber until the time comes when it is needed.', `QuestDescription`) WHERE `ID` = 43349;
