UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Asset Security', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defend Arluin\'s stash from the city guards.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the demons and guards so agitated, I\'m running out of safe places to store contraband. The guards have caught on to one of my favorite havens and will be making off with my goods any minute now.nnHead to my stash and discourage their curiosity. You will need to use a grappling hook to access it- just look for something to latch onto along the ledge.nnI will make sure there is something in it for you when you are done.', `QuestDescription`) WHERE `ID` = 43352;
