UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Hero\'s Weapon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Approach the indicated location before the Forge of the Roaring Mountain and raise your weapon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Grand Master, you have saved our order from the brink of destruction.$b$bYour deeds have shown us that with effort and determination we can overcome any challenge. In light of your example, we have doubled our efforts and developed a technique that will awaken your weapon to its true potential.$b$bPlease, stand before the Forge of the Roaring Mountain and raise your weapon high.', `QuestDescription`) WHERE `ID` = 43359;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Shardmaidens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 6 Shardmaidens in the Shattered Locus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Long have I walked this land and I have seen many forms of corruption.nnThe creatures that wander this hall are twisted by the magics unleashed by the failed arcan\'dor. These dryads have lost their way, and cannot be saved.nnYou must destroy them. End their suffering.', `QuestDescription`) WHERE `ID` = 43360;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fragments of Disaster', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 5 Crystallized Bark.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In the hall beyond rests the bones of the failed arcan\'dor.nnI will take fragments of the crystallized tree and attempt to read them. We must discover the root cause of this destruction.nnOnly then do we have any hope of preventing this disaster from repeating itself.', `QuestDescription`) WHERE `ID` = 43361;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Emerald Nightmare: The Stuff of Dreams', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Purified Life Essence from the Emerald Dream, hidden inside the Emerald Nightmare Raid.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This arcan\'dor is one of an ancient species. They were not bred, but created. In them the arcane and primitive druidic magics merged into something greater than both.nnThe arcane will soon devour it whole.nnWe can restore balance, but it will require wild magic. Magic trapped in another realm.nnYou must enter the Emerald Dream- the pure, unsullied vision of Azeroth - and bring back the essence of life itself.nnOnly then can the arcan\'dor find stability and begin to thrive once more.', `QuestDescription`) WHERE `ID` = 43362;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Winter Veil Gift', `LogTitle`) WHERE `ID` = 43363;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Gently Shaken Gift', `LogTitle`) WHERE `ID` = 43364;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Cycle Continues', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Plant 100 Dream Seeds on corpses.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Yay! The grove is regenerating nicely. Our flower friends thank you for helping them.$B$BWe were able to save most of the grove, but sadly, many living souls were lost as well.$B$BBrightwing is so sad!$B$BBut you can help! Take this bag of Dream Seeds. Plant them onto fresh corpses, and in time, new flowers will grow!$B$BDeath is beautiful, and from death comes rebirth. This is the cycle that must continue!', `QuestDescription`) WHERE `ID` = 43365;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Talked with Mimiron', `LogTitle`) WHERE `ID` = 43366;
