UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mother Ozram', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Mother Ozram.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The fiendish imps in this region are an incessant pain on our allies defending the camps below.$B$BThey are the spawn of a wicked imp-mother named Mother Ozram, who has been seen on a hill to the south.$B$BDestroy her, and we will end her brood as well.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Mother Ozram', `PortraitGiverName`) WHERE `ID` = 43462;
