UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blood for the Wolfe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Fel Blood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have a request in from Winstone Wolfe. He says that he needs a rather large amount of demon blood. He was not specific what for, and I did not ask.nnI am inclined to do this for him with all expediency. The Wolf rarely asks for anything, so when he does, we jump. He gets results, one-hundred percent of the time and then some.nnWe should show him the same professional courtesy.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Valeera Sanguinar in the Chamber of Shadows.', `QuestCompletionLog`) WHERE `ID` = 43468;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where In the World is Mathias?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the "Where In the World is Mathias Shaw?" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Master Mathias Shaw is the leader of the Alliance intelligence organization known as SI:7. And apparently, he is now a dreadlord.nnOr rather, a very clever dreadlord has taken his place while he is being held captive somewhere.nnIt is imperative that we reveal this imposter to the new king of Stormwind. If we fail to do so, then the Alliance will surely be eaten alive from within and the Burning Legion will win this war for a certainty.', `QuestDescription`) WHERE `ID` = 43469;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pruning the Garden', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 World Quests.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In a very real sense, the Uncrowned are gardeners. We snip and trim here and there. One clipping of a single branch may seem nonsensical until you step back and look at the garden as a whole.nnOn the greater theater of the Broken Isles, we must act decisively. The forces that arrayed against Azeroth are moving quickly. We need to prune some very ugly flowers to make our garden beautiful again, wouldn\'t you agree, $n?', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Taoshi in the Chamber of Shadows.', `QuestCompletionLog`) WHERE `ID` = 43470;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Historians', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Historian Llore in the Royal Library of Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, each year I visit Stormwind to help adventurers like you reflect on our shared history. While our eyes must always be trained on the future, we must be mindful of our past. Come visit me in the Stormwind Royal Library and we can speak more.', `QuestDescription`) WHERE `ID` = 43471;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Historians', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Historian Ju\'Pa in the Valley of Spirits of Orgrimmar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, each year I visit Orgrimmar to help adventurers like you reflect on our shared history. While our eyes must always be trained on the future, we must be mindful of our past. Come visit me in the Valley of Spirits and we can speak more.', `QuestDescription`) WHERE `ID` = 43472;
