UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The World is Not Enough', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete any 1 "Rare Elite" World Quest designated by a blue exclamation mark surrounded by a gold dragon on the area maps.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have pruned the garden, it is time to dig up the rotting tree stump in the middle.nnPut another way, we need to make sure to keep the forces of chaos from overwhelming the Broken Isles. Certainly others are helping in this endeavor.nnHowever, I am sure the target you select to eliminate will be the wisest from the standpoint of the Uncrowned.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Taoshi in the Chamber of Shadows.', `QuestCompletionLog`) WHERE `ID` = 43479;
