UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Burning Distraction', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place the Noggenfogger Boom Bombs on your way through Felsoul Hold and then trigger the Detonator to set them off.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'re going to need a distraction if we are to rescue Mathias Shaw from where he\'s being held captive in Felsoul Hold.nnA big one.nnExplosives placed in a few key locations should do nicely. Noggenfogger is playing nice and has donated some bombs to the cause. He might be trying to smooth over relations due to his earlier extortion.nnI can have someone go ahead and mark the best locations. You want to do the honors?', `QuestDescription`) WHERE `ID` = 43485;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cracking the Codex', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Delas Moonfang in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have been studying the Codex of Command that you recovered from Faronaar.$B$BIt is important to Balnazzar, but WHY? What does it say? I\'m sure we could gain valuable knowledge if we could just crack this code.$B$BI have a friend who might be able to help us: a priestess named Delas Moonfang. She has been studying Eredun, the language of the demons.$B$BTake the sigil to her in Dalaran. Tell her I sent you.', `QuestDescription`) WHERE `ID` = 43486;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on Violet Hold: The Fel Lexicon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Fel Lexicon from a powerful prisoner inside Violet Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have been studying the language of the demons, but it has been difficult to get my hands on written material.$B$BI have heard rumor of a book called the Fel Lexicon, written by an ancient scholar who spoke both eredun and draenei. If I could just get my hands on that book, I could learn so much!$B$BI heard that this book might be in the hands of a powerful prisoner inside the Violet Hold.$B$BBring me this book, and my work here will go much faster.', `QuestDescription`) WHERE `ID` = 43487;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blood of Our Enemy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Send your champions on "Blood of Our Enemy" missions against the Burning Legion and collect 5 Flasks of Demon Blood.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have seen demonic artifacts before, $n.$B$BLegion sigils will only reveal themselves in the presence of demon blood.$B$BI sense that time is of the essence. Bring me a large quantity of demon blood, so that I may translate the book as soon as you retrieve it.', `QuestDescription`) WHERE `ID` = 43488;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Felblaze Ingress', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Aponi Brightmane at Felblaze Ingress in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have sobering news, Highlord.$B$BWe have had no word from Chieftain Aponi Brightmane, young Arator, or priestess Delas Moonfang since they departed for Felblaze Ingress.$B$BWe need to know what happened to them.$B$BWe fear the worst.', `QuestDescription`) WHERE `ID` = 43489;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aponi\'s Trail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find 8 pages of Aponi\'s journal, then use them to track her down.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The book is missing several pages. Nearby, you can see signs of a struggle.>$B$B<If you can seek the missing pages on the nearby demons, perhaps you could learn what fate befell your allies.>', `QuestDescription`) WHERE `ID` = 43490;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Allies of the Light', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Save 15 Silver Hand Knights or Conclave Priests, and rescue Arator the Redeemer and Delas Moonfang.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Both Arator and Delas are still somewhere on this forsaken rock, as well as many of our other allies.$B$BWe cannot leave them, $n.', `QuestDescription`) WHERE `ID` = 43491;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Aponi Brightmane', `LogTitle`) WHERE `ID` = 43492;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Hold: Lord Ravencrest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Lord Kur\'talos Ravencrest in Black Rook Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Highlord, news has reached us of a Legion presence at Black Rook Hold.$B$BIt is rumored that the night elf commander, Kur\'talos Ravencrest, amasses an enormous army behind the fortress walls.$B$BTake a group of your most powerful allies, Highlord, and investigate these stories. Lord Ravencrest was a formidable general during Azshara\'s reign, and if the reports are true, then we must know more.', `QuestDescription`) WHERE `ID` = 43493;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Silver Hand Knights', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Commander Born.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Good news, Highlord! We have recruited a paladin trainer named Commander Born.$B$BHe is a hard teacher, but has trained some of the greatest paladin knights in recent times. We are lucky to have his services.$B$BGo speak to him, and train a squad of Silver Hand Knights.', `QuestDescription`) WHERE `ID` = 43494;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Cadraeus', `LogTitle`) WHERE `ID` = 43495;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power Within', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Archmage Kalec at Azurewing Repose in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My apologies for the unannounced intrusion, $n. Do you have a moment?$B$BThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely!$B$BThe very thought demands we find out for sure.$B$BYou are familiar with the ancient blue dragon Senegos in Azsuna, yes? Meet me at his repose once you are able and we will discuss more.', `QuestDescription`) WHERE `ID` = 43496;
