UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power Within', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the "Defending Azurewing Repose" storyline in Azsuna, then meet Archmage Kalec at Azurewing Repose.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My apologies for the unannounced intrusion, $n. Do you have a moment?$B$BThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely!$B$BThe very thought demands we find out for sure.$B$BThe ancient blue dragon in Azsuna known as Senegos lays dying and is key to our journey. You must aid him - I will meet you in his domain as soon as I am able.', `QuestDescription`) WHERE `ID` = 43501;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Change of Seasons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Arcanist Valtrois.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time.nnThe arcan\'dor is preparing to mature. With a final burst of growth, this gift will be fully realized.nnWe must make ready the leyline feed.', `QuestDescription`) WHERE `ID` = 43502;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power Within', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Archmage Kalec at Azurewing Repose in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you have a moment, Conjurer?$B$BThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away deep within. Perhaps even a new form entirely!$B$BThe very thought demands we find out for sure.$B$BYou are familiar with the ancient blue dragon Senegos in Azsuna, yes? Meet me at his repose once you are able and we will discuss more.', `QuestDescription`) WHERE `ID` = 43503;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power Within', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the "Defending Azurewing Repose" storyline in Azsuna, then meet Archmage Kalec at Azurewing Repose.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you have a moment, Conjurer?$B$BThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely!$B$BThe very thought demands we find out for sure.$B$BThe ancient blue dragon in Azsuna known as Senegos lays dying and is key to our journey. You must aid him - I will meet you in his domain as soon as I am able.', `QuestDescription`) WHERE `ID` = 43505;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Black Rook Hold: Greater Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Lord Kur\'talos Ravencrest and retrieve a Greater Demonic Runestone from Dantalionax in the Black Rook Hold Dungeon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The raw power of the runestones will allow Hymdall to temporarily open a tear into demonic worlds, but it\'s not enough.$B$BThe Legion hides its presence in far away worlds with dark magic. Bring a greater runestone so that Hymdall can hone in on our enemies across the cosmos.', `QuestDescription`) WHERE `ID` = 43506;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Looted Priest Altar', `LogTitle`) WHERE `ID` = 43507;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Captive Spymaster', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Taoshi into the Halls of the Eclipse to where Mathias Shaw is being held captive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must move swiftly while the distraction is working. Mathias Shaw is being held in the lower levels of the Halls of the Eclipse directly to the south.nnQuickly, $n, we must go!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet up with Taoshi ahead in the depths of the Halls of the Eclipse.', `QuestCompletionLog`) WHERE `ID` = 43508;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Odyn\'s Challenge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Odyn in the Halls of Valor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Odyn himself sends a message. He and his warriors await worthy contenders within the Halls of Valor.nnDefeat the champions of the Halls of Valor, and claim glory.', `QuestDescription`) WHERE `ID` = 43509;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seal of Fate: Class Hall', `LogTitle`) WHERE `ID` = 43510;
