UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wisdom of Patience', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Await the opening of the Emerald Nightmare, then report back to Senegos in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The horrors you braved in the thicket are only the beginning. Within the Emerald Nightmare you will face the very heart of the corruption that threatens the stability of all life on Azeroth.$B$BBut not just yet.$B$BWe have not yet managed to permeate the magic protecting Xavius\' sinister realm. Once we have, however, you should return here; there is still much to be done.', `QuestDescription`) WHERE `ID` = 43581;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shalassic Park', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ride Su\'esh and defeat $3oa adversaries.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have a Devilsaur.$b$bI think she sees you as the pack leader now. She should obey your commands.$b$bShe looks hungry. Why don\'t you let her off the leash a little bit?', `QuestDescription`) WHERE `ID` = 43582;
