UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Preparing For War', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete "Aiding the Valkyra," "Lost at Sea" and "Enslaved by Sea Giants" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We would do well to bolster our own forces before calling upon our allies to join us in the final conflict against the Legion.$B$BThere still remains much to do in the Broken Isles and victories there will give us the momentum we need to crush the enemy.', `QuestDescription`) WHERE `ID` = 43585;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Maw of Souls: Message to Helya', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Helya inside the Maw of Souls dungeon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We cannot fight on two fronts and succeed.$B$BIf we\'re to give ourselves the room we need to fight off the Legion we need to deliver a decisive victory against Helya. Not her armies, not her lieutenants, but the mother of the underworld herself.$B$BGo to the Maw of Souls and defeat Helya, $n.', `QuestDescription`) WHERE `ID` = 43586;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leyline Feed: Elor\'shan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infuse the leyline feed with Ancient Mana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Infuse the leyline feed with Ancient Mana.', `AreaDescription`) WHERE `ID` = 43587;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leyline Feed: Kel\'balor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defend the Leyline Feed and infuse it with Ancient Mana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<This feed appears to draw power from the leyline in order to become fully operational.$b$bYou should be able to imbue it with mana, but it will take a few minutes to draw enough leyline energy to accept the infusion.$b$bBeware, for creatures may notice the surge of arcane energy...>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Defend the Leyline Feed and infuse it with Ancient Mana.', `AreaDescription`) WHERE `ID` = 43588;
