UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leyline Feed: Ley Station Moonfall', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Broken Leydar Dish and repair the leyline feed.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<This leyline feed appears to be damaged. The large collector at the top is broken.$b$bThe broken piece must be around here somewhere. There are rough scuff marks on the floor that appear to be made by something larger than the creatures inside.$b$bMuch, much larger.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Find the Broken Leydar Dish and repair the leyline feed.', `AreaDescription`) WHERE `ID` = 43590;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leyline Feed: Ley Station Aethenar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 6 Leyline Feed Fragments and infuse the feed with ancient mana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<This leyline appears to be damaged and needs repair.$b$bSeveral large chunks of the main column are missing and arcane energy is crackling in the gaps.$b$bThe elementals nearby seem to pick up debris and absorb it into their bodies as they move around. Maybe they have the missing pieces...>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect 6 Leyline Feed Fragments and infuse the feed with ancient mana.', `AreaDescription`) WHERE `ID` = 43591;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leyline Feed: Falanaar Arcway', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infuse the leyline feed with Ancient Mana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Infuse the leyline feed with Ancient Mana.', `AreaDescription`) WHERE `ID` = 43592;
