UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Honor the Fallen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 8 Ancient Tideskorn Blades from the kvaldir in Helmouth Shallows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Souls are not the only plunder Helya craves, and the kvaldir are ever eager to please.nnAmong their spoils are the venerable blades of fallen heroes who dared stand against Helya\'s minions. These blades belong in a place of honor, not among their wretched kind.nnReclaim the blades, for the honor of the Tideskorn!', `QuestDescription`) WHERE `ID` = 43595;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Piercing the Mists', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Helya in the Maw of Souls dungeon, then return to Havi in Valdisdall', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In a time before memory, the Naglfar was the prize of Helya\'s fleet. It would seem that it has lived on to serve her once more.nnNow, the dread ship sails the sea of souls, and cuts through the mist unseen by the living. The kvaldir must have a way to summon her, and this is what you must seek.nnFind her berth and board the Naglfar. Put an end to the dread ship, and the souls of the Tideskorn may be redeemed.', `QuestDescription`) WHERE `ID` = 43596;
