UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secrets of the Axes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the Broken Isles for the greatest axe wielding warrior you know.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Battlelord, I have a request. Find me inspiration! An axe whose form has seen a truly astounding amount of battle, wielded by one of the world\'s most powerful warriors. Both weapon and owner forged together in the crucible of war.nnFind this hero and their weapon, and convince them to come here.', `QuestDescription`) WHERE `ID` = 43643;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To the Deeps', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Ruins of Vashj\'ir with Erunak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I assure you the legends are true: Sharas\'dal, the Scepter of Tides, was forged around living waters of the Well of Eternity. It gave Azshara dominion over life itself. I have sent shaman throughout the world looking for it, but the only one to ever find it has gone missing.$b$bWavespeaker Adelee said she had tracked the scepter to the Ruins of Vashj\'ir, but we haven\'t heard from her since.$b$b$n! Come with me to the ocean depths. Let\'s track down our missing shaman and get that artifact!', `QuestDescription`) WHERE `ID` = 43644;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wavespeaker\'s Trail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate three clues to the whereabouts of Wavespeaker Adelee within the Ruins of Vashj\'ir.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The shaman we seek is Wavespeaker Adelee. Her research brought her down to these ancient ruins, where she reported naga armies amassing prior to the Legion invasion.$b$bThe last I had heard, she had located Sharas\'dal, the Scepter of Tides - and then she went silent.$b$b$n, Search for clues to her whereabouts among the lower level of the ruins. Beware the naga patrols!', `QuestDescription`) WHERE `ID` = 43645;
