UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fourth Horseman', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain the Fourth Horseman.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Lich King demands too much! Tirion Fordring deserves more than a life of anguish and undeath!$b$bKnow this, Deathlord... I will obey your will, but there will be no redemption for what we are about to do.$b$bThe Silver Hand will never hand Tirion to us. The path to the Fourth Horseman will be soaked in righteous blood!$b$bBlood that will stain our hands forever.$b$bYour will be done, Deathlord. I will begin the preparations to invade Light\'s Hope. If this is what it takes to save our world, so be it!', `QuestDescription`) WHERE `ID` = 43686;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Walking in Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek the aid of the Knights of the Ebon Blade in Acherus above the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If we are to infuse the shard\'s power into the Ashbringer we will need help. We cannot wield such dark magic; however, I know who can...$B$BThe Knights of the Ebon Blade.$B$BI will commission a flight for you to Acherus at once and meet you there - find Aludane Whitecloud in Dalaran when you are ready.', `QuestDescription`) WHERE `ID` = 43687;
