UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Warriors of Light', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Listen as you are honored by the Order of the Silver Hand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have gathered to celebrate our victory over the Burning Legion this day. Highlord, please join us.', `QuestDescription`) WHERE `ID` = 43697;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lumenstone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 50 Lumenstone by sending champions on "Lumenstone" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To prepare for the battle ahead, we will need armor and weapons.$B$BWe have learned of lumenstone, a rare metal that can negate magic... even fel magic.$B$BIt is found in small quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting.$B$BWe should send our champions to target enemies around the Broken Isles - there should be plenty of lumenstone to be found in their stockpiles.', `QuestDescription`) WHERE `ID` = 43698;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Defenders of the World', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 World Quests.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Requests are pouring in from across the Broken Isles for our aid, Highlord.$B$BI know that we are working to aid the priests at Netherlight Temple, but there are many others who need our help.$B$BWe cannot turn our backs on those who need our aid.', `QuestDescription`) WHERE `ID` = 43699;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Light in the Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Netherlight Temple using the priest\'s portal in Dalaran, then defend Netherlight Temple and slay Lord Balnazzar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Highlord, thank goodness you\'ve arrived! The invasion of Netherlight Temple has begun.$B$BOur forces are already waiting on the other side of the portal.$B$BJoin them, and we will close the trap around Lord Balnazzar.', `QuestDescription`) WHERE `ID` = 43700;
