UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Softening the Target', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 50 Nightmare Creatures in Shala\'nir riding the Subdued Nightwing.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Archdruid\'s end draws near. His memory will live on in the hearts of all who knew him.$b$bElothir\'s desperate efforts revealed that Malfurion is being held in Shala\'nir, amidst the roots of Shaladrassil.$b$bMy love. So near, yet so far....$b$bShala\'nir is infested with Nightmare creatures. To rush in would be suicide.$b$bI subdued one of Xavius\' creatures. Use it against him, $n and clear us a path.', `QuestDescription`) WHERE `ID` = 43702;
