UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Down to Business', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Grand Promenade and slay $1oa defenders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'First things first, $n: we must set up our camp.$b$bWe do not have the time or resources for a prolonged siege. It is not like we can starve them out. No, we must be swift and sure as an arrow, piercing their heart in one strike.$b$bThey are drawing up their battle lines within the city, but could attack us while we are setting up our defenses.$b$bVenture forth and show them what the kaldorei have learned from thousands of years of war. Discover their weaknesses so that we may exploit them.', `QuestDescription`) WHERE `ID` = 43810;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lunastre Estate Teleporter Online!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infuse the Telemancy Beacon with Ancient Mana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Use Ancient Mana to reactivate the Telemancy Beacon.', `AreaDescription`) WHERE `ID` = 43811;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Down to Business', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Grand Promenade and slay $1oa defenders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Time to get to business, $n. We cannot afford to tarry.$b$bWhile we are not setting up for a prolonged engagement, we must still have a war camp of some sorts. I do not expect the Nightborne to stay patiently in their city while we plant stakes.$b$bThey are starting to build their defenses. Go in there and see what we are up against. You will strike them from within while we finalize our preparations.', `QuestDescription`) WHERE `ID` = 43812;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sanctum of Order Teleporter Online!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infuse the Telemancy Beacon with Ancient Mana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Use Ancient Mana to reactivate the Telemancy Beacon.', `AreaDescription`) WHERE `ID` = 43813;
