UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the scouting notes to locate and recover the 4 ancient tomes Holt needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. And yet, we barely understand it.nnIf we truly want to unlock all of its potential, we need to learn more about it. I can help with that.nnBefore I can get started though, I need a series of ancient tomes. They may be hard to procure. I asked one of the scouts to seek them out, here are her notes.', `QuestDescription`) WHERE `ID` = 43819;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hidden History', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the scouting notes to locate and recover the 4 ancient tomes Fjornson needs to begin research on your artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You wield ancient steel, strengthened by magics we barely understand.nnIf you truly want to unlock the potential of your weapons, you need to know more of how they were forged, and of the battles they\'ve fought in. I can help with this.nnYour races use books to store their histories, and I will need some of these to piece together the legend of your steel. I asked one of your followers to look into their locations for me. Here are her notes.', `QuestDescription`) WHERE `ID` = 43826;
