UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spy vs. Spy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Spy vs. Spy".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'SI:7 is the espionage and intel branch of the Alliance. They are based out of Stormwind City and headed up by Master Mathias Shaw. As of late, they have been acting, shall we say, peculiar.nnI would like for you to send some of our people out to assess the situation. It might be nothing, but I am not fond of situations that I do not fully understand.nnIf we are going to win this war against the Burning Legion, the last thing we need is for something wholly unexpected to occur.', `QuestDescription`) WHERE `ID` = 43829;
