UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Elixirs of Aid', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect elixir crafting ingredients for Alonsus Faol.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We can never be too prepared for battle. The Legion will strike at any moment, and we must be ready to deal with a multitude of injuries and afflictions.$B$BZabra and Yalia have provided me a list of their most potent potions and battle elixirs than can do everything from restore health to blind the enemy.$B$BWe have an exhaustive list of ingredients that we\'ll need in order to craft a respectable supply.', `QuestDescription`) WHERE `ID` = 43832;
