UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Convincin\' Old Yancey', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Convincin\' Old Yancey".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Avast ye! Th\' time be long overdue that we get some more pirate blood into our ranks.nn<Crackers gives a sudden squawk in agreement.>nnAnd I know just th\' man t\' do it.nnI\'m talkin\' about good old Yancey Grillsen, o\' course. He\'s an old salt down Stranglethorn way.nnSend some o\' your land lovin\' scallywags off t\' round him up.', `QuestDescription`) WHERE `ID` = 43841;
