UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting More Troops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Vicar Eliza.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Word of your leadership has spread rather fast. Priests of all sorts have traveled to the temple to lend their aid.nnWe\'re lucky enough to have caught the eye of Vicar Eliza. She\'s quite the leader in her own right, commanding countless devotees that do her bidding without question. nnSpeak to her now.', `QuestDescription`) WHERE `ID` = 43851;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fancy Lads and Buccaneers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with your Pirate recruiter, Yancey Grillsen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Aye, it warms me heart t\' know that Yancey\'s now part o\' th\' crew.nn<Tethys feeds Crackers some cackle fruit from the table.>nnWhy don\'t you be a good $g lad:lass; and see if he can sponge us up some bilge rats.', `QuestDescription`) WHERE `ID` = 43852;
