UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hitting the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Any death knight worth their salt knows the weapon they wield as if they were born with it.  But you now carry a weapon older than any in this hall.nnIf we truly want to unlock all of its potential, we need to learn more about it. It will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.nnWe should prioritize some of the order\'s resources towards this research. I promise you it will be worth every minute.', `QuestDescription`) WHERE `ID` = 43877;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hitting the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A demon hunter is nothing without blades with which to cut flesh. Yet those you wield are older than even you... and have power we don\'t understand yet.nnIf you truly want to unlock all of their potential, we need to learn more about them. It will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.nnWe should prioritize some of the order\'s resources towards this research. I promise you it will be worth every minute.', `QuestDescription`) WHERE `ID` = 43878;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hitting the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. That\'s where I come in. It\'s my specialty.nnStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.nnWe should prioritize some of the order\'s resources towards this research. I promise you it will be worth every minute.', `QuestDescription`) WHERE `ID` = 43879;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hitting the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. I can help with that.nnStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.nnWe should prioritize some of the order\'s resources towards this research. It will be worth every minute.', `QuestDescription`) WHERE `ID` = 43880;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hitting the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. I am quite good at such things.nnStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.nnWe should prioritize some of the order\'s resources towards this research. It will be worth every minute.', `QuestDescription`) WHERE `ID` = 43881;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nighthold: Vaults', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Trilliax in The Nighthold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Nighthold will be a challenge to infiltrate and conquer. Even the catacombs and vaults are likely to be heavily guarded, but we must make our way in by any route possible.', `QuestDescription`) WHERE `ID` = 43882;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hitting the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a mighty weapon with a long history, one we barely understand. If we truly want to unlock all of its potential, we need to learn more about it. I can get workin\' on that for ya.nnStill, it\'ll take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.nnWe should prioritize some of the order\'s resources towards this research. It will be worth every minute.', `QuestDescription`) WHERE `ID` = 43883;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hitting the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. I can do this for you.nnStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.nnWe should prioritize some of the order\'s resources towards this research. It will be worth every minute.', `QuestDescription`) WHERE `ID` = 43884;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hitting the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your weapons are undeniably powerful, but we know near nothing about\'m.nnIf we want to unlock all of their potential, we need to dig up some dirt on how they work, what they\'ve done... get to know them, ya know? That\'s where I come in. I dig up dirt all the time. I mean, not literally, but... you know what I mean.nnIt will take time and more eyes than just mine to sift through all this. We should prioritize some of the order\'s resources towards this research. It will be worth every minute.', `QuestDescription`) WHERE `ID` = 43885;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Speaking to the Wind', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. We know stories of it, but little about its origins.nnIf we truly want to unlock all of its potential, we need to learn more about it. The winds can help us with this, but we need to know what to ask.nnIt will take more shaman than just myself to learn everything there is to know about this artifact of yours. We should prioritize some of the order\'s resources towards this research. It will be worth every minute.', `QuestDescription`) WHERE `ID` = 43886;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hitting the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. That is a thing that I can do for you.nnStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.nnWe should prioritize some of the order\'s resources towards this research. It will be worth every minute.', `QuestDescription`) WHERE `ID` = 43887;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hitting the Books', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Start a Research Work Order.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You wield ancient steel, strengthened by magics we barely understand.nnIf you truly want to unlock the potential of your weapons, you need to know more of how they were forged, and of the battles they\'ve fought in. I can help with this.nnAny resources that you can prioritize towards this research will be well worth it.', `QuestDescription`) WHERE `ID` = 43888;
