UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Steeds of the Damned', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 5 "Fallen Steeds" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Salanar the Horseman has arrived at Ebon Hold from the Realm of Shadows. He alone has the knowledge and power to conjure the steeds of the Four Horsemen.$b$bSalanar has given us the first list of necessary components to create the steeds. I have organized a number of missions to obtain these items.$b$bUse the mission table to assign your chosen champions to the task.', `QuestDescription`) WHERE `ID` = 43899;
