UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Legion Returns', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Check in with Holgar Stormaxe at the Dranosh\'ar Blockade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Warriors of da Horde! Break out ya axes and sharpen ya spears. Da Burning Legion has returned ta our world!nnWe be shipping outta Bladefist Bay right away. With da full fury of da Horde, we gonna smash der line so hard dat Sargeras is gonna feel it in da Nether!nnGet to da ships. We got demons ta slay!', `QuestDescription`) WHERE `ID` = 43926;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aggregates of Anguish', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 5 "Unholy Attainment" missions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our preparations for conjuring the Steeds of the Damned are nearly complete.$b$bSalanar the Horseman has given us a list of the remaining components. The ritual of conjuring requires five unholy essences known as the Aggregates of Anguish.$b$bI have taken it upon myself to organize the necessary missions to obtain these components.$b$bUse the mission table to assign your chosen champions to the task.', `QuestDescription`) WHERE `ID` = 43928;
