UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A New Path', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Delas Moonfang.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Highlord $n, if I could have a moment of your time?$B$BLong have I followed the path of the Light, and for many years I studied under the Priestesses of the Moon. Yet, I have always felt my education incomplete, and a yearning to know more.$B$BWhen I walked into these halls, I finally felt a spark of what was missing. I believe that a new path lies before me.$B$BI wish to become a paladin of the Silver Hand. Will you allow me to join you?', `QuestDescription`) WHERE `ID` = 43934;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Second Legend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose a second artifact to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Perhaps it\'s time to consider improving your flexibility when it comes to powerful artifacts. There are still others that I think are worth pursuing if you are interested.nnLet me show you what your options are and you can choose one.', `QuestDescription`) WHERE `ID` = 43935;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seeking Refuge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the "Nightfall" storyline in Suramar, then meet Archmage Kalec in Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell.$B$BI believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar.$B$BIf you can convince the Nightfallen to aid us, they may be able to offer the Moon Guard and us both refuge right under the Legion\'s nose.', `QuestDescription`) WHERE `ID` = 43937;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Focusing Our Efforts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the "Nightfall" and "Moon Guard Stronghold" storylines in Suramar, then meet Archmage Kalec in Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell.$B$BI believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar.$B$BAfterward, seek out the Moon Guard in the northern reaches of Suramar. They, too, could be valuable allies in our cause... if they still oppose the Legion as they once did many years ago.', `QuestDescription`) WHERE `ID` = 43938;
