UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Timeworn Artifact', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Timeworn Artifact to King Mrgl Mrgl nearby.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<You\'ve found a strange looking naga artifact on the fallen corpse.nYou saw King Mrgl Mrgl as you were walking around Timeworn Strand. Maybe he knows what to do with it?>', `QuestDescription`) WHERE `ID` = 43942;
