UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Expanding Your Horizons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Aggra to choose a second artifact to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You are a fast study, $ct $n. The elements speak through you - it is rare to have such a connection to the world.$b$bA true shaman must walk many paths. For every role, one must have the right tools at hand. Only the most powerful weapons can lead us to victory against the Legion. Perhaps it is time to seek out another?$b$bSpeak with me and let us discuss your options.', `QuestDescription`) WHERE `ID` = 43945;
