UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Body of Evidence', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the body of the SI:7 operative for clues.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is an urgent matter that requires your attention, $n.$b$bThe body of a woman with a knife in her back has turned up in the sewers.$b$bNormally, such a matter would be less than newsworthy... but this isn\'t your average cutthroat. It\'s an SI:7 operative!$b$bI\'ve got some of our goons guarding the body, but you had better get over there before the word spreads.$b$bIf SI:7 finds out about this... it will be bad for business.', `QuestDescription`) WHERE `ID` = 43958;
