UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hired Help', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Arluin and persuade him to help you.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was fond of Margaux. News of her death weighs heavily on many of us.nn<Vanthir shakes his head sadly.>nnIf we are to carry on, we need to send a strong message. We need those like Durant to know that we are watching, and we will hold them accountable.nnI know someone who could help us.nnHis name is Arluin. To call him a reluctant ally would be generously overstating it. He is cautious, and will not risk himself without compensation.nnYou can find him in the alleys north of the Evermoon Bazaar.', `QuestDescription`) WHERE `ID` = 43969;
