UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Another Weapon of Old', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose a second artifact to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have done well but our foes are powerful and cunning. It would be wise to be prepared for whatever they may unleash upon us. $b$bYou would be wise to consider obtaining another of the weapons of old to aid in our conflict.$b$bLet me know how you\'d like to proceed.', `QuestDescription`) WHERE `ID` = 43980;
