UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Tome Opens Again', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose a second artifact to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve been doing well, friend, but you would be unstoppable if you had another weapon at your side.$b$bHere, let me show you what options remain in the book. If either of these interest you then simply let me know.', `QuestDescription`) WHERE `ID` = 43984;
