UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Protectors', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your druidic powers to commune with protectors at the Feral Stone, the Guardian Stone, the Restoration Stone, and the Balance Stone.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To fully unlock the powers of the Idol, we will need four manifestations of the wilds - an essence of ferocity, essence of regrowth, essence of balance, and essence of tenacity.$B$BTo find these essences, we must consult the protectors of the forest.$B$BGo to the Emerald Dreamway and call upon the powers of the ancient druidic stones. The protectors will only show themselves to those who can prove their connection to the wilds.', `QuestDescription`) WHERE `ID` = 43991;
