UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bringer of the Light', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Discover the purpose of the Mysterious Lightbound Object.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Turalyon lives! For ages I had thought that my old friend had perished on some desolate Legion world. But to know that he yet lives and is in danger is too much to bear.$B$BWe must hurry, $n. We must uncover the object\'s sacred purpose.$B$BThe prophet of whom Turalyon spoke of is undoubtedly the leader of the draenei, Velen. Take the object and journey to the Exodar. It is there that you will find Prophet Velen.$B$BI will open a portal for you now. Take my beacon and use it when you are ready to return.', `QuestDescription`) WHERE `ID` = 44004;
