UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Your Fullest Potential', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Aggra to choose a third artifact to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I see that you walk many paths, as a true shaman should.$b$bTwo mighty artifacts are already in your possession. To seek a third would not be greed: it would be the fulfillment of your destiny, the completion of a circle.$b$bSpeak with me, and together we will unlock your fullest potential.', `QuestDescription`) WHERE `ID` = 44006;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Falling Star', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the Mysterious Lightbound Object.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$ct $n, thank you for coming. I have a matter of some urgency that requires your unique talents.$B$BThe Order of the Silver Hand have reported that an extraordinarily luminescent object has emerged from the Felstorm and is currently falling towards the coast of Suramar. What I find most curious about this occurrence is that the object was reported as having "cut a swath" through the Felstorm itself.$B$BWill you investigate? There is a gryphon awaiting your arrival at Krasus\' Landing.', `QuestDescription`) WHERE `ID` = 44009;
