UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Another Worthy Blade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose a second artifact to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We still have plans prepared to obtain other weapons of incredible power - tools that you may find useful to have on hand as you continue your work.nnI would be happy to go over the remaining options with you so that you may make an informed decision.', `QuestDescription`) WHERE `ID` = 44034;
