UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vote of Confidence', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Ly\'leth at the Waning Crescent.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I will endeavor to protect my son until the votes are cast.nnCoryn Stelleris is a predator even among the nobility. It does not surprise me that he should stoop to such depths to ensure his own success.nnTell Ly\'leth that she has my support. Unequivocally.nnYou may also choose to tell her that Coryn Stelleris will hurt her, if she gives him a chance.nnBe careful.', `QuestDescription`) WHERE `ID` = 44040;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Bloody Truth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Discover the truth behind the hit on the SI:7 agent.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We need to find out who is behind the assassination of Amber Kearnen.$b$bIt won\'t be long before SI:7 realizes that their agent is MIA and comes sniffing around The Hall of Shadows.$b$bHere, take these stylish spy glasses and set them to scan for traces of hemoglobin. I\'ve taken the liberty of calibrating them specifically for Amber Kearnen\'s blood.$b$bFollow the blood trail back to the culprits, but make sure to stay out of sight!$b$bReport back to us when you\'ve got the information we need.', `QuestDescription`) WHERE `ID` = 44041;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Continuing the Legend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose a second artifact to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There are still two paths you may walk - two powerful weapons you might yet obtain to aid you in the fight against the Legion.$B$BI will help you recall your remaining options, of course.', `QuestDescription`) WHERE `ID` = 44043;
