UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wasted Potential', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the teleporter pad and bring Vanthir\'s gift to Thalyssra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have done well for us here, but it is time for you to return to Thalyssra.nnThere is a teleporter pad nearby that has gone unused in recent years. See if you can reroute it and return to her that way.nnOh, and before you go:nn<Vanthir hands you a wrapped bottle of Arcwine.>nnTake this to her, with my thanks for sending you. Let her know that your efforts helped replenish our Arcwine supplies and reunited a mother and child.nnWe are grateful beyond measure. Farewell for now.', `QuestDescription`) WHERE `ID` = 44051;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'And They Will Tremble', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Thalyssra', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There will be consequences for what has transpired this day.nnFor now, you should return to Thalyssra. Tell her that we have avenged Margaux and that the Dusk Lily has announced itself to all of Suramar.nnThere will be many more deaths before this is over, rest assured, but this is a death that will teach others like Durant to tread more carefully in the future.', `QuestDescription`) WHERE `ID` = 44052;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Friends With Benefits', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Thalyssra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Lunastre Attendant, silent as ever, offers you a wax-sealed scroll.$b$bIt reads:$b"Dearest $n,$b$bI asked my attendant to catch you, should things go in my favor.$b$bThe role of Advisor will keep me away from the estate for some time and I settled on a gift for Thalyssra.$b$bI have sent a detachment of attendants to Shal\'Aran with some comfort items. Treat them well- they need someone to wait on and I could think of none better!$b$bGive the others my thanks, and my love,$bAdvisor Ly\'leth Lunastre"', `QuestDescription`) WHERE `ID` = 44053;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demonicide', `LogTitle`) WHERE `ID` = 44054;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'They Have A Pitlord', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Kuglaroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Feltotem are not the first to embrace the temptations of the Burning Legion. And they will not be the last.$b$bBut in their arrogance, they have conjured a pit lord.$b$bWill you join us in battle against this beast? The power of your artifact and skill could prove invaluable against such a creature.', `QuestDescription`) WHERE `ID` = 44055;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A "Noble" Event', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Send champions on missions to investigate the hunt.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The invitation appears to be for an exclusive fox hunt. They plan to hunt Volpin, a rare, elusive fox somewhere in the Broken Isles.  Perhaps we can take advantage of this?nnWe need to gather more information about this hunt, but we should do so without alerting the Nightborne to your plans. Your champions can act in your stead and further  investigate where the hunt will be.', `QuestDescription`) WHERE `ID` = 44057;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Volpin the Elusive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interrupt the fox hunt.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'According to the map, the fox hunt will start at the Feathermane Hunting Grounds in Suramar. If the Nightborne succeed, they will kill Volpin, a fox that is the last of his kind in the Broken Isles.nnTravel to the Hunting Grounds, and interrupt the hunt.', `QuestDescription`) WHERE `ID` = 44058;
