UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Neltharion\'s Lair: Essence of Tenacity', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 1 Essence of Tenacity from Rokmora in Neltharion\'s Lair, then slay Dar\'grul the Underking.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, Archdruid. I hear that you seek the essence of tenacity.$B$BThere is none more unyielding and unbreakable than a creature of stone.$B$BIn Neltharion\'s Lair is a monster known as Rokmora. Slay him, and draw from him the essence that you need.', `QuestDescription`) WHERE `ID` = 44074;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Halls of Valor: Essence of Ferocity', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 1 Essence of Ferocity from Fenryr in the Halls of Valor, then prove your worth to Odyn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To find the essence of ferocity, you must seek a creature who has slain thousands, and is revered by even the gods.$B$BI speak of none other than the wolf, Fenryr, whom you can find hunting in the eternal forests of the Halls of Valor.', `QuestDescription`) WHERE `ID` = 44075;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkheart Thicket: Essence of Regrowth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 1 Essence of Regrowth from Oakheart in Darkheart Thicket, then defeat the Shade of Xavius.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My child, I can think of only one place to capture the essence of regrowth.$B$BDeep within Darkheart Thicket is Oakheart, a loyal ancient defender of the grove. He has recently fallen to the Nightmare\'s corruption, but deep within his heart, he still fights.$B$BGather the essence of this great tree, so that his everliving soul may be used to fuel new life.', `QuestDescription`) WHERE `ID` = 44076;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: Essence of Balance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 1 Essence of Balance from the Wrath of Azshara.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Within the Eye of Azshara in Azsuna, a powerful being known as the Wrath of Azshara grows in strength. It is a blasphemy of nature - an infusion of stolen arcane power, and cannot be allowed to exist.$B$BSlay it. In its aftermath, you may find the essence of balance that you seek.', `QuestDescription`) WHERE `ID` = 44077;
