UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knights of the Ebon Blade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Korgaz Deadaxe.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Korgaz Deadaxe has arrived at Acherus to aid us in recruiting additional death knights. He has an eye for potential.$b$bI cannot emphasize enough that it is of the utmost importance that we replenish our numbers during the battle with the Burning Legion.$b$bThe demon armies are nearly endless and we are few.$b$bSpeak with Korgaz when you are ready to recruit additional death knights.', `QuestDescription`) WHERE `ID` = 44082;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Grimoire of the First Necrolyte', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 13 Skulls of the Executed from powerful humanoid champions throughout Broken Isles, and bring them to the Executioner\'s Altar in the crypt near Morgan\'s Plot in Deadwind Pass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This ancient tome appears to be the spellbook of Sataiel, the first necrolyte.nnWithin its pages of curses and cantrips, you discover instructions for a ritual that Sataiel was concocting to empower Ulthalesh, the Deadwind Harvester. She calls this ritual, "The Rite of the Executioner."nnThe site was chosen and prepared, but Sataiel met her unfortunate end before she could proceed.  Perhaps you can pick up where she left off?nnFirst, you\'ll need some skulls.', `QuestDescription`) WHERE `ID` = 44083;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vengeance for Margaux', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 8 Vineyard Enforcers or Wardens.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Sylverin sputters, pale-faced with rage.>nnHow could they? Margaux did everything they asked of her and more! The arcwine never stopped flowing despite everything they did to us! To her!nnSuch injustice cannot stand. We must take vengeance for Margaux.', `QuestDescription`) WHERE `ID` = 44084;
