UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Fel Hammer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Battlelord Gaardoun on the Fel Hammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Battlelord Gaardoun asked me to retrieve you. He says there is a very important matter that he needs your help with.nnHe requests your presence back on the Fel Hammer as soon as possible.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Return to me on the Fel Hammer as soon as possible, commander.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Battlelord Gaardoun', `PortraitGiverName`) WHERE `ID` = 44087;
