UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Greater Arsenal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Calydus to choose to pursue your final artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The tome speaks of one more weapon that friend can use against our foes. nnDo you wish to seek it?', `QuestDescription`) WHERE `ID` = 44089;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pledge of Loyalty', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Altar Keeper Biehn in Trueshot Lodge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The eagle appears to have a message for you:n$B|cFF660000To: $n|r$b$bI hope this message finds you well.$B$BWord of Ohn\'ahra\'s omen has traveled fast. There are many who wish to pledge their loyalty to the Unseen Path\'s new leader.$B$BReturn to me at Trueshot Lodge, and we can discuss this further.$B$B|cFF660000             |r-Altar Keeper Biehn', `QuestDescription`) WHERE `ID` = 44090;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Protect the Home Front', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Open your map to find an active Legion invasion in Kalimdor or Eastern Kingdoms. Go to the invasion site and stop the demons!', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion hasn\'t just invaded this city. Their evil is spreading across Azeroth, threatening the far corners of our world.$b$bWe must seek them out and stop them, everywhere their darkness touches.$b$bWe\'ve dispatched scouts around the world to watch for Legion activity. As invasions arise, we\'ll mark the locations on your map.$b$bMake them suffer, $n!', `QuestDescription`) WHERE `ID` = 44092;
