UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting Apprentices', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Grand Conjuror Mimic.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Grand Conjuror Mimic has arrived to aid us in bolstering our numbers. She seeks out the most promising apprentices and trains them very quickly. Her former students are some of the most powerful conjurors in the land!$B$BSpeak to her and recruit some of her apprentices to add to our roster.', `QuestDescription`) WHERE `ID` = 44098;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Mutual Friend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Calydus within Dreadscar Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s good to see you are well.nnI\'ve been sent by our mutual friend, Calydus. He is eager to speak with you.nnPlease return to Dreadscar Rift at your earliest convenience.', `QuestDescription`) WHERE `ID` = 44099;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Proper Introductions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Alonsus Faol within Netherlight Temple.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m glad I found you. nnI have a message from Alonsus Faol.nnHe says introductions are in order, and requests your presence within Netherlight Temple at your earliest convenience.', `QuestDescription`) WHERE `ID` = 44100;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supply Dropped', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Challenge and defeat the Grimtotem Champion who is raiding your supplies.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These supplies for the Earthen Ring have not been processed yet. It looks like someone has been rummaging through them and looting whatever can be carried. You have reasons to suspect the Grimtotem tribe, on account of the fact that one of their champions is nearby, visibly pilfering your stuff.$b$bChallenge the Grimtotem to secure your resources!', `QuestDescription`) WHERE `ID` = 44101;
