UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Archdruid of Lore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Elothir in Thas\'talah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Elothir resides in the ancient grove Thas\'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore.$b$bSeek him out and tell him that he is desperately needed here.', `QuestDescription`) WHERE `ID` = 44106;
