UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trading for Dreams', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Nightborne Flask to craft an Ysera\'s Dream Draught.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'From the look of you, I take it you\'re an alchemist, yes?$b$bI\'d be willing to trade my services with you for a price that I deem is fair.$b$bI have been away from Suramar for some time now. I long for an Ysera\'s Dream Draught. To concoct it, you\'ll need some dreamleaf as well as the leaves of a Dreamer\'s Tear.$b$bOne grows not to far from here in the clearing of some ruins. Take my flask, make this drink for me, and I\'ll do as you ask.', `QuestDescription`) WHERE `ID` = 44112;
