UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Welcome to Legion!', `LogTitle`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Welcome to World of Warcraft: Legion! We hope you enjoy all of the new experiences that await you in the Broken Isles, and want to make sure you\'re well-armed to take on the Burning Legion.', `QuestDescription`) WHERE `ID` = 44115;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mystery at Citrine Bay', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Fleet Admiral Tethys at Citrine Bay in Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Burning Legion invades Azeroth, and SI:7 is wasting valuable resources hunting down and assassinating one of their top agents?$b$bSomething isn\'t adding up...$b$bWe need to find out how deep this goes. Why was Amber Kearnen being hunted by her own organization?$b$bThe encrypted letter she was carrying may hold the clues... but we need more information.$b$bThe SI:7 assassins you tailed in Dalaran mentioned Citrine Bay... search Citrine Bay for clues and we\'ll see about getting this letter decrypted.', `QuestDescription`) WHERE `ID` = 44116;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Time Flies When Yer Havin\' Rum!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 10 bottles of Red Blade Rum.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thar be few pirates ye want to cross swords wit\' less than th\' Red Blade! They be salty dogs, indeed!$b$bThat being said... they does have a way wit\' rum! I\'ll level wit\' ye, $n... thar be few rums as jolly as that \'o th\' Red Blade.$b$bSeein\' as ye be headin\' off in search \'o clues, ye might as well brin\' back a few bottles while ye be at it!$b$bBrin\' me back as many bottles as ye can find, and I\'ll reward ye handsomely! Pirates honor, $n!', `QuestDescription`) WHERE `ID` = 44117;
