UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Illidari Allies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with the Illidari representative in the Mage Quarter of Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'At first I was unsure whether it was wise to allow the Illidari inside the city. But they may have just saved all our lives.$b$bI gave the demon hunters leave to establish a temporary camp in the Mage Quarter. I\'d like you to be my personal envoy to them. Thank the Illidari for their assistance and see how they can aid our cause.$b$bJust... keep your eyes open. They have harnessed a terrible power, and we must be ready should they be consumed by the darkness within.', `QuestDescription`) WHERE `ID` = 44120;
