UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into the Fray', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the lead demon hunter at Illidari Stand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely.nnCome, let\'s put that weapon of yours to use. I\'ll figure out our next move while you crush the Legion.', `QuestDescription`) WHERE `ID` = 44137;
