UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Growing Crisis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Valewalker Farodin at the Temple of Fala\'dora. You can travel there using the Portal to Falanaar in Shal\'aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Arcan\'dor is failing.nnThis energy was once bound in its boughs and fueled its growth. There was balance, between life and arcane.nnNow that energy is breaking free. When the heart can no longer hold it, this tree will kill every living thing in this hall.nnI have seen this happen before and I must find a way to stop it from happening again. nnWe must go to the tree that came before. Its bones can guide us.nnMeet me at the temple of Fal\'adora. We will descend together.', `QuestDescription`) WHERE `ID` = 44152;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Light\'s Charge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place Light\'s Heart in your Order Hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '"You did not ask for this burden, but it is what fate has deemed." Turalyon\'s haunting last words still echo in my mind. I worry about the fate of the draenei... about the fate of my friend, Velen; but we must remain vigilant, $n!$B$BFor now, Light\'s Heart remains under your watchful eye. There is one place on Azeroth that I would trust with the safekeeping of the object: your order hall. Take it there, $n. I will remain in Dalaran and continue looking for answers. There must be another way!', `QuestDescription`) WHERE `ID` = 44153;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Rite of the Executioner', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interact with the Pile of Skulls and complete the Rite of the Executioner in the crypt near Morgan\'s Plot in Deadwind Pass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The skulls have been gathered and the ritual area is prepared.nnAll that is left is to perform the incantation, and Ulthalesh will become imbued with the essence of the Executioner.', `QuestDescription`) WHERE `ID` = 44154;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Searching For Clues', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find proof of SI:7 working with The Red Blade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It be no coincidence that we be in Citrine Bay investigatin\' a murder, and we find th\' band \'o pirates known as th\' Red Blade here as well!$b$bAye, this be no coincidence at all, $n... but we be needin\' proof!$b$bYe go on ahead and look fer clues and I\'ll find some scallywags to interrogate.$b$bAye $n, we\'ll get t\' \'th bottom o\' this t\' be sure! Thar be no doubt!', `QuestDescription`) WHERE `ID` = 44155;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Another Arcan\'dor Closes...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Shal\'aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I hope you have a better understanding of what is at stake.nnCome. There is no more for us to do here.nnMeet me in Shal\'aran and we will discuss what steps we may take next.', `QuestDescription`) WHERE `ID` = 44156;
