UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'City Under Siege', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Khadgar at the Chamber of the Guardian in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Khadgar\'s voice erupts from the elemental once again.>$B$BObtaining information on the Pillars of Creation before the Legion could stop us was a considerable victory. It won\'t bring back those we lost on the Broken Shore, but I believe it will help us avenge them.$b$bDalaran has become a focal point of the Legion\'s assault. Your presence here is crucial. If the demons are putting this much effort into attacking the city, it means Dalaran will play a pivotal role in the struggle to save Azeroth.', `QuestDescription`) WHERE `ID` = 44182;
