UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In the Blink of an Eye', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness the teleportation of Dalaran to the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Broken Isles is our destination, $n.$b$bThe spell that will blink Dalaran to its new location is not a simple one. It will take this Council\'s full energy and attention.$b$bAs Jaina is... absent, Kalecgos of the blue dragonflight has offered us his aid.$b$bThe Legion will make every attempt to stop us, but we will not falter. It is time to begin!', `QuestDescription`) WHERE `ID` = 44184;
