UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Workorders for Armaments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a workorder for a shipment of Champion Armaments and Equipment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can get you the best deals on some slightly... used... equipment.', `QuestDescription`) WHERE `ID` = 44195;
