UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seal their Fates', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a work order for a Seal of Broken Fate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ever feel like luck just isn\'t on your side?  Well maybe I can help you with that.  nnThere are some interesting items I\'ve come across in my travels which can be used to swing the dice in your favor, or at least give you another shot at it.  It takes some time, and supplies are hard to come by, but I can get you one of them... for a price?', `QuestDescription`) WHERE `ID` = 44204;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shape Your Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a work order for a Seal of Broken Fate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The whims of the spirits can be guided, I have seen it.nnThere were whispers of an item, a way to change the path of destiny.  I heard dem, and I went looking.  For many years I listened to those whispers on the wind until one day they showed me the way.  This is what I offer you.  It will take some time, and some valuable resources, but I can perform the ritual to allow you to control this power.nnWell?  Are you ready?', `QuestDescription`) WHERE `ID` = 44205;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Ascended', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a request to recruit Ascendants.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These shaman have spent their lives dedicated to the path of Air, Water or Fire.  On your request, we will beseech the elements to Ascend them, becoming a powerful, if short lived, force to deploy in this war against the Legion.nnThe ritual of ascension is not to be requested lightly.', `QuestDescription`) WHERE `ID` = 44206;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Portal Full of Shiny Things', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a work order for Champion armaments and equipment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When I heard the Hall of the Guardian was open again, I said to myself "Minuette, this is your chance!" I rushed over here thinking I\'d be hurled into the front lines.  Imagine it, me, little old me, assaulting Demons with missiles, blinking away from Fel Meteors.  That would be brilliant!nnInstead, they send me over here and say "Hey, open up some portals so we can throw things through, would you?" At least I get to charge something for it.', `QuestDescription`) WHERE `ID` = 44207;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fate and Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a work order for a Seal of Broken Fate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'For years we wondered, we conjectured, that it was possible to control the twisting, slipping, streaming threads of fate and destiny.  These books tell of powerful mages who embraced the manipulation of time.  No no, not like Time Warp, they would laugh at us, think us silly amateurs.  No, they were true Chronomancers.nnThe only spell we\'ve been able to determine is a conjuration.  It calls forth what they termed  a "Seal of Fate".  This allowed them to repeat their actions.  Let us try it out shall we?', `QuestDescription`) WHERE `ID` = 44208;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Might of Dalaran', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Channel the power of Dalaran into the focusing crystal, then unleash it to complete a World Quest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In times of great need, the mages of Dalaran can focus their power into one pure, destructive form.  This is such a time.nnOn request, these mages will channel that power into a focusing crystal, which we will impart to you.  Use it to unleash that power, completing a quest of great value.', `QuestDescription`) WHERE `ID` = 44209;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Might of Dalaran pt2', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Focusing Crystal and use it to complete a world quest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Yes, now once the crystal has been empowered, collect it here, and use it to unleash the power of our mages on a world quest.', `QuestDescription`) WHERE `ID` = 44210;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unseen Armaments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a work order for Champion armaments and equipment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If we gonna win dis war, we need to get these Champions of ours better equipment.  nnIt won\'t be cheap, or easy, but I can get dem for you.', `QuestDescription`) WHERE `ID` = 44211;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unseen Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a work order for a Seal of Broken Fate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our path is a winding, twisting road full of peril.  Yet did you know it can be walked many times?  There is an item of great power available to us.  It allows us another opportunity, a second chance.nnDo you wish to acquire one?', `QuestDescription`) WHERE `ID` = 44212;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'You Will Be Prepared!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Accept a gift from the Illidari.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, your strength and leadership inspires awe in all of us!nnThe Illidari are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.', `QuestDescription`) WHERE `ID` = 44213;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One More Thing...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Head down to the chamber of the Cursed Forge of the Nathrezim on the lower level of the Fel Hammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well done, Slayer. You are truly now the leader of the Illidari. But there\'s one more thing.nnMeet me down at the forge.', `QuestDescription`) WHERE `ID` = 44214;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One More Thing...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Lord Ravenholdt in the Uncrowned Vault.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Firstly, allow me to congratulate you. I know of no one more deserving of the title of Shadowblade. But there\'s one more thing.nnMeet me over near the forge.', `QuestDescription`) WHERE `ID` = 44215;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Armor Fit For A Deathlord', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Accept a gift from the Knights of the Ebon Blade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n is strong! $n is great leader!nnEbon Blade want to give you full set of armor to help with the little demon killing. Get stronger, make demons more dead!', `QuestDescription`) WHERE `ID` = 44217;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion Armaments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a work order for Champion armaments and equipment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This war against the Legion won\'t be won easily.  We will need armaments and equipment for our Champions.  nnGive the order sir, I\'ll get the word out and have a shipment brought in.', `QuestDescription`) WHERE `ID` = 44218;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fate\'s Blessing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a work order for a Seal of Broken Fate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Light\'s blessing is powerful. We use it to mend, to defeat our enemies... we even use it to resurrect our allies. Did you know it can also be used to alter your destiny?  nnThe Silver Hand is able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  nnShall we procure one for you?', `QuestDescription`) WHERE `ID` = 44219;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blessing of the Order', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Send out the call to bring together the Vanguard, then unleash it to complete a World Quest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In times of great need, the Order can rally its mightiest forces into one pure, destructive form.  This is such a time.nnOn request, we will channel our power into a Libram, which we will impart to you.  Use it to unleash that power, completing a quest of great value.', `QuestDescription`) WHERE `ID` = 44220;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion Armaments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a workorder for Champion armaments and equipment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A warrior lives and dies by his weapons and armor.  For a price, we can provide you with a shipment for armaments to equip your Champions with.nnDo we have a deal?', `QuestDescription`) WHERE `ID` = 44221;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Might of the Val\'kyr', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rise the power of the Val\'kyr, then unleash it to complete a World Quest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In times of great need, the Val\'kyr can rally its mightiest forces into one pure, destructive form.  This is such a time.nnOn request, these we will channel our power into a Horn, which we will impart to you.  Use it to unleash that power, completing a quest of great value.', `QuestDescription`) WHERE `ID` = 44222;
