UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unleashing our Wrath', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Channel the power of the Hammer, then unleash it to complete a World Quest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In times of great need, we can rally our  mightiest forces into one pure, destructive form.  This is such a time.nnOn request, these we will channel our power into an item, which we will impart to you.  Use it to unleash that power, completing a quest of great value.', `QuestDescription`) WHERE `ID` = 44224;
