UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unleashing our Wrath', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Begin the ritual to enslave the infernal, then unleash it to complete a World Quest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In times of great need, we can rally our mightiest forces into one pure, destructive form.  This is such a time.nnOn request, these we will begin the ritual to enslave a powerful Infernal in a Demonic Phylactery, which we will impart to you.  Use it to unleash that power, completing a quest of great value.', `QuestDescription`) WHERE `ID` = 44227;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion Armaments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a work order for Champion armaments and equipment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'See Lurr?  He big and strong, but not so smart, not like Murr.  Murr can make Lurr build good things for you, things for your Champions to wear and be smashier.  nnFirst, you give Murr something?', `QuestDescription`) WHERE `ID` = 44228;
