UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion Armaments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Place a workorder for Champion armaments and equipment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'People today see a dead body and they just think its a smelly pile of goo, not me I tell ya. I see it as a little present holding wonderful secrets.  nnFor a price, Ill share those secrets with you too.', `QuestDescription`) WHERE `ID` = 44231;
