UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Illidari Freedom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free Sirius Ebonwing, Cassiel Nightthorn, and Asha Ravensong.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Arduen Soulblade is bleeding from several ghastly wounds. It appears he was left here to die.>$B$BWithin the prison are three of our... <cough>... comrades.$B$BWe were taken by surprise while scouting the area.$B$BI am not long for this world, $n, but please... you can still save them.', `QuestDescription`) WHERE `ID` = 44278;
