UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eye of Azshara: The Frozen Soul', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Frozen Soul Pendant from the Wrath of Azshara.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ah, Deathlord. It is good to see you. I happen to have a fascinating task for you, should you be in the mood for adventure.$b$bI recently came across an obscure reference to an ancient amulet that was created by Queen Azshara herself! It is called the Frozen Soul Pendant and it offers tremendous power to those who channel the power of frost.$b$bI have reason to believe that it may be found somewhere within the Eye of Azshara.$b$bRetrieve the pendant for me, and it will prove most useful in my studies.', `QuestDescription`) WHERE `ID` = 44282;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Emerald Nightmare: Piercing the Veil', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Normal difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius\'s hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....', `QuestDescription`) WHERE `ID` = 44283;
