UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vault of the Wardens: A Masterpiece of Flesh', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Beating Fel-Heart and Demonic Entrails from Vault of the Wardens.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ah, Deathlord! What a pleasant surprise! It is not often that you visit my workshop of blood and flesh.$b$bActually, I have something quite special to show you. I have been developing a new type of abomination that mixes the flesh of demons with that of humans.$b$bMy first prototype, Rottgut, is nearly complete! However I am still missing some of the more difficult-to-find body items.$b$bThe prisoners in the Vault of the Wardens should make fine donors for the parts I require.', `QuestDescription`) WHERE `ID` = 44286;
