UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Goddess Watch Over You', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Archmage Khadgar in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I may have found a "key" to unlock Light\'s Heart, $n.$B$BI was going through some ancient cosmology tomes when I stumbled upon a passage indicating that the prime naaru may have been created by Elune during the great ordering of Light and Shadow.$B$BIf Elune did create Xe\'ra, then it stands to reason that we could use the Tears of Elune to unlock the secrets of Light\'s Heart.$B$BIt\'s a long shot, but we\'ve got nothing left to lose.$B$BMeet me in Dalaran. I will ready the Tears of Elune for you.', `QuestDescription`) WHERE `ID` = 44337;
