UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on Violet Hold: Purple Pain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Repel the Assault on Violet Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Again! It happened again!nnSure, it\'s the Legion that staged the prison breakout this time, but I *told* them it was a bad idea to keep some of the most dangerous beings on Azeroth in a prison inside our city!nnWe can talk about relocating later, I suppose. Right now, we\'ve got some... pacification to tend to.nnCan you help?', `QuestDescription`) WHERE `ID` = 44400;
