UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aggra\'s Guidance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Aggra at the Storm\'s Eye Overlook within the Heart of Azeroth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$ct, have you met the shaman Aggra? Born of a shattered world, she learned the ways of the elements among the Mag\'har orcs of Outland. On the eve of the Cataclysm she took it upon herself to complete Thrall\'s shamanistic training. Our younger initiates are fortunate to have her among us to guide them.$b$bIf you wish to seek out a second artifact, Aggra can assist you. She is training new recruits above us on the Storm\'s Eye Overlook.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Aggralan, known as Aggra.', `PortraitGiverText`) WHERE `ID` = 44406;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Third Legend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Alonsus Faol to pursue a third artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have not one but TWO powerful artifacts to use against the Legion. But can you imagine a world where you have three? Think of what you could do in such a world!nnShall we look at the possibilities?', `QuestDescription`) WHERE `ID` = 44407;
