UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Strange Humming Crystal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Strange Humming Crystal to Khadgar in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<You place the crystal to your ear and hear the disharmonious din of hundreds of voices speaking at once. Perhaps Khadgar might know more about this strange gem.>', `QuestDescription`) WHERE `ID` = 44411;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Enemies Everywhere', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the hidden infiltrators in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hold a moment, $n. While I look into this orb of yours, why don\'t you look into something for me?$b$bI have long suspected an infiltration of Dalaran but after an embarrassing encounter with a local florist I\'ve withheld my accusations until I\'m absolutely certain.$b$bHave you noticed citizens among us that seem just too mundane? Almost inhumanly so? Spies, serving dark masters, watch and wait until our backs are turned. Root them out, but try and keep it quiet.', `QuestDescription`) WHERE `ID` = 44412;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felspawns of Lothros', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Lothros.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These Felspawns are endless! I can\'t cut them down quickly enough to get to the dreadlord within the mausoleum.nnMaster Illidan, will you come with me so we can take down Lothros together?', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Lothros', `PortraitGiverName`) WHERE `ID` = 44414;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Red Axe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Close the Unstable Portals and make your way to Broxigar the Red.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Broxigar the Red is cornered on the bridge. I am not sure he would ever admit that he needs our help, but I feel it only proper to lend him our aid.nnIf you wish to assist our ally, I would be humbled to accompany you in this endeavor.', `QuestDescription`) WHERE `ID` = 44415;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hunter of Night', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Malvingeroth', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A glorious battle indeed!nnIf I am correct, we can expect something a bit more deadly at any moment.nnThe Legion often uses fodder such as these to prepare the way for a more worthy foe.nnMy axe is sharp and ready.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Malvingeroth', `PortraitGiverName`) WHERE `ID` = 44416;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One More Legend', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Odyn to pursue another artifact.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Two is good, but three would be better. You should pursue another artifact to add to your armory.nnWhat say you?', `QuestDescription`) WHERE `ID` = 44417;
