UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Weapons of the Ancients', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Choose a fourth artifact to pursue.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve proven yourself to be a druid without equal, but if we are to succeed in our battles against the Burning Legion you need you to take advantage of every opportunity to stay ahead of our foes.$b$bYou should consider obtaining one final weapon of the Ancients. Its powers will maximize your ability to adapt to whatever the Legion can throw our way.$b$bLet me know how you\'d like to proceed.', `QuestDescription`) WHERE `ID` = 44443;
