UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In the House of Light and Shadow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Tears of Elune to Light\'s Heart in your Order Hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tears of Elune are ready for you, $n. I am uncertain what to do from here. Take the relic back to your order hall and try to use it on Light\'s Heart.$B$BMaybe make them touch? Honestly your guess is as good as mine.$B$BLet\'s hope this works!', `QuestDescription`) WHERE `ID` = 44448;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Advanced Quenching', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft a pair of Hard Leystone Armguards for Alard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have a frost mage at our disposal, testing this method out should be a cinch.$b$bHere are the plans for what I\'d like you to make. Get to work and give me the armguards when you\'re finished.', `QuestDescription`) WHERE `ID` = 44449;
