UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Brotherly Love', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Maiev Shadowsong in Black Rook Prison.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Maiev will be somewhere in the prison. I found her discarded armor on my way here.nnI know the two of you have a history. I trust that will not be a problem.nnLet\'s split up to search the cells more quickly. We must find her.', `QuestDescription`) WHERE `ID` = 44457;
