UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demons Among Them', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Protect the King.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is just as we suspected, $n! The demons thought they could take us by surprise.$B$BQuickly, to arms! Warn the King!', `QuestDescription`) WHERE `ID` = 44463;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Awakenings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness the Awakening of Illidan Stormrage in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Light\'s Heart is to serve as the vessel for Illidan Stormrage\'s rebirth: my last act of service to the Light.$B$BBut Illidan is dead and his soul is lost in the Nether. Before we may attempt to recover his soul, we must prepare the vessel for his return.$B$BAcross two worlds exist echoes of Illidan\'s past. You must venture out and find the echoes.$B$BStart where all life begins, $n: birth. Find Illidan\'s birthplace in Val\'sharah. Awaken the memory.', `QuestDescription`) WHERE `ID` = 44464;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruiting Earthcallers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Felinda Frye.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Felinda Frye has recently joined us at the Heart of Azeroth. She oversees the recruitment and training of our Earthcallers.$b$bI recommend that you speak with her at your soonest convenience, Farseer $n. The Earthcallers are powerful shaman and will greatly bolster our ranks.', `QuestDescription`) WHERE `ID` = 44465;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Unclear Path', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness Illidan\'s Resilience at the Dreamgrove in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Much of Illidan\'s formative years were spent in Val\'sharah, alongside his twin brother, Malfurion.$B$BAs young night elves, the twins vied for the affection of the young priestess, Tyrande, as they underwent the trials of the demi-god, Cenarius.$B$BWe must travel to the Dreamgrove now, where Illidan\'s true path would be forged.', `QuestDescription`) WHERE `ID` = 44466;
