UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Second Sight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your Spectral Sight.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Though young King Anduin is a noble soul, he may lack the conviction of his father. The Alliance needs a leader who will do what needs to be done. The Legion will strike at the first hint of weakness.$B$BEven now, I sense something amiss, $n. I fear that not all is as it seems.$B$BQuickly, use your Spectral Sight. We must know if there are foes among us!', `QuestDescription`) WHERE `ID` = 44471;
