UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Weapon of the Alliance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with the Illidari in the Mage Quarter of Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'At first I was unsure whether it was wise to allow the Illidari inside the city. But you may have just saved all our lives.$b$bYou may establish a camp in the Mage Quarter. The Alliance will have need of your skills if we are to face the Legion.$b$bMake no mistake though. Should your kind give in to the fel energies you toy with, we will treat you like the demons you are becoming.', `QuestDescription`) WHERE `ID` = 44473;
