UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ravencrest\'s Legacy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Experience Ravencrest\'s Legacy at Black Rook Hold in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Years later, as the War of the Ancients raged on and the Burning Legion\'s grip upon this world took hold, Illidan would meet a military leader known as Kur\'talos Ravencrest. He too would see the potential within Illidan, eventually promoting him to captain of the Moon Guard: a powerful group of night elf sorcerers.$B$BWe must experience this memory in Black Rook Hold, located on the western shores of Val\'sharah.', `QuestDescription`) WHERE `ID` = 44479;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In My Father\'s House', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness Illidan\'s Sacrifice in Azshara on the continent of Kalimdor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Most mortals cannot comprehend the truth of the Legion. Those that recognize it, often refuse to accept its meaning. Such knowledge carries a weight that the mortal frame cannot bear. To sacrifice that much of ones self changes the soul.$B$BAmong your greatest heroes, a rare few understood that type of sacrifice. Let us witness it through Illidan\'s eyes.$B$BWe must go to Azshara, on the continent of Kalimdor.', `QuestDescription`) WHERE `ID` = 44480;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Destiny Unfulfilled', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness True Betrayal in Shadowmoon Valley on the fringes of Outland.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.$B$BYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.$B$BWe must travel to Outland to experience Illidan\'s last memory.', `QuestDescription`) WHERE `ID` = 44481;
