UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel-Ravaged Tome', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Much of the elven writing in the tome has been singed by fel fire.$B$BThe head of the curators in Dalaran is renowned for his restoration skills.  Perhaps he can treat the tome to bring it back to legibility.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran.', `QuestCompletionLog`) WHERE `ID` = 44486;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Waterlogged Tome', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Waterlogged Tome to Robert Newhearth in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In spite of its magical nature, the book has been damaged by water.$B$BThe head of the curators in Dalaran is renowned for his abilities.  Perhaps he can restore it.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Bring the Waterlogged Tome to Robert Newhearth in Dalaran.', `QuestCompletionLog`) WHERE `ID` = 44487;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cursed Tome', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Much of the elven writing in the tome has been singed by fel fire.$B$BThe head of the curators in Dalaran is renowned for his restoration skills.  Perhaps he can treat the tome to bring it back to legibility.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran.', `QuestCompletionLog`) WHERE `ID` = 44488;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lyana Darksorrow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Soul Harvester.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your fellow Illidari, Lyana Darksorrow, floats captive in stasis in front of you; her soul slowly draining into the harvester crystal.>nn<In order to release her from stasis, you will need to destroy the soul harvester.>', `QuestDescription`) WHERE `ID` = 44489;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grimwing the Devourer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Grimwing the Devourer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have my thanks for rescuing me from captivity, $n.$b$bHowever, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion.$b$bBefore we can get to him, there is another that must be destroyed.$b$bGrimwing the Devourer is the strongest of the felbats. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears.$b$bThen, return to me with her head. My thirst for vengeance must be quenched.', `QuestDescription`) WHERE `ID` = 44490;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.0 Suramar Collapse Scenario - Run Once', `LogTitle`) WHERE `ID` = 44491;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leyline Apprentice', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Arcanist Valtrois.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Good work finding those additional leyline feeds.nnYou seem rather competent - for an outlander.nnAllow me to share with you a few secrets about the power of the leylines. This should help you in scavenging more ancient mana from the creatures around Suramar. A grisly task, I know - which is why I leave it to you!', `QuestDescription`) WHERE `ID` = 44492;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leyline Proficiency', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Arcanist Valtrois.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our leyline feed grows stronger.nnThe more powerful our feed becomes, the more I learn about ancient mana itself.nnOf course, as my apprentice, you may reap the benefits of my discoveries. Listen well, and I will teach you how to extract power from your enemies more reliably.', `QuestDescription`) WHERE `ID` = 44493;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leyline Master', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Arcanist Valtrois.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You surprise me, outlander. During our first lesson about the ancient leylines, I half-expected you to be lost in daydreams of adventure, or treasure or... some such nonsense.nnBut you have proven an apt student.nnOur leyline feed has grown extremely powerful. Watching it grow has taught me a great deal about the arcane, and the nature of mana.nnI have one final lesson that will help you find even more ancient mana.', `QuestDescription`) WHERE `ID` = 44495;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Destiny Unfulfilled', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness True Betrayal in Shadowmoon Valley on the fringes of Outland.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.$B$BYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.$B$BWe must travel to Outland to experience Illidan\'s last memory.', `QuestDescription`) WHERE `ID` = 44496;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Destiny Unfulfilled', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness True Betrayal in Shadowmoon Valley on the fringes of Outland.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus.$B$BYet, in a strange twist of fate, it was not the Burning Legion who came for him in the end.$B$BWe must travel to Outland to experience Illidan\'s last memory.', `QuestDescription`) WHERE `ID` = 44497;
