UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Author! Author!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Tell Khadgar to begin the ritual to summon the spirit of Alodi, the first Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve reviewed the tome recovered from Karazhan. Though we found references to the Pillars of Creation, one piece of crucial information was omitted from the book... where to find the artifacts.$b$bFortunately, we have access to an expert on the subject.$b$bThe author, Alodi, was the first Guardian of Tirisfal. His spirit is forever bound to the Forge of the Guardian, which has been hidden in our safekeeping. I think the time has come to call him forth.', `QuestDescription`) WHERE `ID` = 44500;
