UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Battle for Broken Shore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the wind rider to the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This wind rider will take you to Broken Shore, $n. May your weapon bring you many kills today.nnThe Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.', `QuestDescription`) WHERE `ID` = 44543;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Earthen Ring', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Advisor Sevel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'At last, I\'ve found you!nnI have a message from Advisor Sevel.nnThe Earthen Ring has need of you, Farseer. Please return to the Heart of Azeroth at your soonest convenience. Advisor Sevel is eagerly awaiting your return.', `QuestDescription`) WHERE `ID` = 44544;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pressing the Assault', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your next assault point on the Broken Isles at the Command Map in your Order Hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<With this Pillar of Creation safely secured, it is time to take advantage of your momentum and continue onward after the next.>$B$B<You recall that your order has gathered information that would aid you in your journey - looking it over once more before setting off would be wise.>', `QuestDescription`) WHERE `ID` = 44545;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crushing the Crown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 12 Crown Chemical Co. Employees and use Snagglebolt\'s Khorium Bomb to destroy a chemical wagon south of Shadowfang Keep in Silverpine Forest, then return to Detective Snap Snagglebolt in Orgrimmar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.$b$bHere\'s an entry I want you to check out: it\'s just south of Shadowfang Keep in Silverpine Forest. That can\'t be good. Get out there and rough \'em up.$b$bOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.', `QuestDescription`) WHERE `ID` = 44546;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Isle Hopping', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your next assault point on the Broken Isles at the Command Map in your Order Hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Victory in hand, you know there are still Pillars of Creation that must be recovered if the Legion is to be defeated once and for all.>$B$B<Your order has identified uncharted regions of the Broken Isles that still house the remaining Pillars - looking over the information would help focus your next effort.>', `QuestDescription`) WHERE `ID` = 44547;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scouring What Remains', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your next assault point on the Broken Isles at the Command Map in your Order Hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Looking around the chamber, you know you are well on your way to gathering all of the Pillars of Creation, but your work is not yet complete.>$B$B<Your order has continued to scour the isles below for anything that might be useful - best to check in with them before embarking once more.>', `QuestDescription`) WHERE `ID` = 44548;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Master of the Isles', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Review your remaining assault point on the Broken Isles at the Command Map in your Order Hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Only one region remains from your order\'s carefully laid plan to assault the Broken Isles and gather the Pillars of Creation.>$B$B<Victory feels close, but studying your order\'s intelligence one last time couldn\'t hurt.>', `QuestDescription`) WHERE `ID` = 44549;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Called to Acherus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Siouxsie the Banshee', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deathlord, your presence has been requested on Acherus.nnThe war against the Burning Legion rages on and the Knights of the Ebon Blade await further orders.nnPlease return to Acherus at your soonest convenience. Siouxsie the Banshee is awaiting your return.', `QuestDescription`) WHERE `ID` = 44550;
