UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Khadgar\'s Discovery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Champion! Please come to the Violet Citadel immediately.$B$BI have made a discovery that I would like to share with you before the Council of Six.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Archmage Khadgar', `PortraitGiverName`) WHERE `ID` = 44555;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Karazhan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Khadgar outside Karazhan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Karazhan is now in the hands of the Legion, $n.$b$bThe fault is mine. In my haste to retrieve Alodi\'s book on the Pillars of Creation, the defenses I put in place to protect the tower were ramshackle at best. The Legion was quick to find a weakness.$b$bThanks to the time Sargeras spent controlling Medivh, he knows the tower\'s secrets as well as I do. Whatever the Dark Titan\'s plan is, we must do everything in our power to stop it.$b$bCome at once! I\'ll meet you outside Karazhan.', `QuestDescription`) WHERE `ID` = 44556;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Finite Numbers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Close $1oa Portals and slay $2oa Demons in Deadwind Pass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It seems not all the protections I put in place have been defeated. The Legion isn\'t able to open portals inside or near the tower... at least, not yet.$b$bThey appear to be bringing reinforcements in through the catacombs running beneath Deadwind Pass. Disable them and you just might buy us the time we need to drive them out of Karazhan.', `QuestDescription`) WHERE `ID` = 44557;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crushing the Crown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 12 Crown Chemical Co. Employees and use Snagglebolt\'s Khorium Bomb to destroy a chemical wagon south of Shadowfang Keep in Silverpine Forest, then return to Inspector Snip Snagglebolt in Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.$b$bHere\'s an entry I want you to check out: it\'s just south of Shadowfang Keep in Silverpine Forest. That can\'t be good. Get out there and rough \'em up.$b$bOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.', `QuestDescription`) WHERE `ID` = 44558;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Follow the Recipe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the other parts of the Crown Chemical Company\'s recipe, then return to Detective Snap Snagglebolt in Orgrimmar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This seems to be part of a recipe for whatever concoction the Crown Chemical Company is cooking up. The other parts must be nearby.', `QuestDescription`) WHERE `ID` = 44559;
