UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seed of Hope', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Reach Honored with The Nightfallen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thalyssra was wise to send you in search of the arcan\'dor, though she underestimates its power.$B$BShe will learn - as will the others.$B$BBut it will take time. And with hunger gnawing at their very souls, the Nightfallen will need your help to survive.', `QuestDescription`) WHERE `ID` = 44561;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Growing Strong', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Reach Revered with The Nightfallen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Magic has long been a vice of the elves. It shaped us, and lifted us out of the darkness - but without balance, it also threatens to unmake us.$B$BThe shal\'dorei are too proud to admit it, but they are the product of indulgence. They live without harmony.$B$BBut I sense potential among the Nightfallen. Losing everything has humbled them. It has made them stronger.$B$BStay the course, $p. Help the Nightfallen rise up.', `QuestDescription`) WHERE `ID` = 44562;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Redemption for the Fallen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Reach Exalted with The Nightfallen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Soon the change of seasons will be upon us, and the Nightfallen will take command of their fate.$B$BYou have given them hope, and set them on the path to redemption. They need you now more than ever.$B$BWe all do.', `QuestDescription`) WHERE `ID` = 44563;
