UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Building an Army', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Thalyssra when you are ready to lead the withered in their first combat training mission.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must keep our eyes on the future. There will come a time when we will need an army.$b$bWe\'ve proven that the withered are not completely beyond redemption. They can be taught, and molded.$b$bI want you to be their combat trainer, $n. Come with me. We can use the nearby ruins as an arena to hone their abilities.', `QuestDescription`) WHERE `ID` = 44636;
