UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In the Blink of an Eye', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness the teleportation of Dalaran to the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The entity speaks with the familiar voice of Archmage Khadgar.>$b$bAzeroth needs you, $n!$B$BAfter scouring Ulduar and Karazhan for answers, we know the key to defeating the Legion: five ancient artifacts called the Pillars of Creation.$b$bTo find them, Dalaran must be moved to the Broken Isles. As our leader Jaina is... absent, Kalecgos of the blue dragonflight has offered the Kirin Tor his aid.$b$bThe Legion is assaulting our current position over Deadwind Pass. Hurry!', `QuestDescription`) WHERE `ID` = 44663;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Will of the Valarjar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 World Quests.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we prepare to launch an attack on the Legion\'s own world, it is important to not give reprieve to our enemies in this one.$B$BAs your armies seek to secure enemy gateways, you would do well to return to the Broken Isles and carry on the battle against those who stand against you.', `QuestDescription`) WHERE `ID` = 44667;
