UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ancient Mana', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather from $1oa Ancient Mana nodes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Without the Nightwell to feed upon, my comrades and I will have to live off the land itself.$B$BAncient mana from the underground leylines can reach the surface in many forms, most commonly as crystals or gems.$B$B<Thalyssra picks up a small stone and, whispering words of power, traces a rune upon it with her fingertip.>$B$BThis stone will glow when ancient mana is nearby. Please gather as much as possible! It will be a precious resource in the weeks to come.', `QuestDescription`) WHERE `ID` = 44672;
