UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leading by Example', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 World Quests.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We cannot let our current situation overshadow the Unseen Path\'s mission to protect the people of Azeroth.$B$BThere are many in this world who could use our help.$B$BAs our leader, you can set the example by aiding those in need.', `QuestDescription`) WHERE `ID` = 44680;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unparalleled Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 World Quests.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Power is all around us, $n, waiting to be harnessed.$B$BYou must venture out into the world and claim it for the council!$B$BWith our First wielding such unparalleled power, our enemies won\'t stand a chance.', `QuestDescription`) WHERE `ID` = 44682;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Holding the Lines', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Secure the Eastern Ley Line and Western Ley Line beneath Karazhan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Karazhan sits upon a confluence of ley lines. It\'s why this location was chosen for the tower in the first place... a fact that has not escaped the Legion\'s notice.$b$bIf the demons are tapping into these lines of power, they must need their energy for something particularly menacing. You must cut off their access to the ley lines if we\'re to have a chance of retaking the tower, $n.', `QuestDescription`) WHERE `ID` = 44683;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Corruption Runs Deep', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover an Essence of Corrupted Soil and an Essence of Corrupted Water from the caverns beneath Deadwind Pass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Everything the Legion touches is marred by fingerprints of their corruption. If I can study the traces of magic they leave behind, perhaps I can discern their plans for Karazhan.$b$bThis vial is specially reinforced to contain fel magic. If you bring me the essences of corrupted soil and water from near their portals, I believe we\'ll be closer to unraveling their scheme.', `QuestDescription`) WHERE `ID` = 44684;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Reclaiming the Ramparts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Plant the Wards at the Eastern, Southern and Northern locations around the tower in Deadwind Pass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the ley lines protected we must move to secure the tower\'s perimeter.$B$BAround the tower are several locations where corruption continues to run rampant. Seek out these locations and secure them with these wards.$B$BWith the progress we\'ve made so far, bolstering our defenses should keep the remaining Legion\'s forces at bay just long enough for us to discover who\'s behind their efforts.', `QuestDescription`) WHERE `ID` = 44685;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thought Collection', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interrogate the Captured Wyrmtongue in the structure just north of the tower in Deadwind Pass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While I examine these samples further, I ask that you seek out one of our patrols in the structure to the north. It appears they\'ve captured one of the demons.$B$BGo, interrogate it. Find out anything you can. And hurry! I\'m afraid time is no longer an ally.', `QuestDescription`) WHERE `ID` = 44686;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Might of the Tirisgarde', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 World Quests.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tirisgarde has received requests from across the Broken Isles for aid in fighting the Burning Legion. While we will continue pursuing Archmage Vargoth, we cannot forget that our primary mission is to repel the demons and protect Azeroth.', `QuestDescription`) WHERE `ID` = 44689;
