UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hungry Work', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Ancient Mana to feed Chief Telemancer Oculeth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must get Chief Telemancer Oculeth back on his feet as soon as possible.$B$BFind ancient mana, any way you can, and feed it to him.', `QuestDescription`) WHERE `ID` = 44691;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One Battle at a Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 World Quests.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Before I  became a demon hunter, I practiced the arcane arts. I still retain some of that knowledge, though the fel makes it all but impossible to use.nnOne thing I can still manage is the occasional glimpse into faraway places. You\'ve seen me use the nether crucible to do this. I\'m afraid that things don\'t look too good.nnThe forces that are arrayed against us are not limited to the Burning Legion. You must act quickly to keep the Broken Isles from being overwhelmed.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Allari the Souleater on the Fel Hammer.', `QuestCompletionLog`) WHERE `ID` = 44694;
