UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stormheim', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Sky Admiral Rogers at the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is good we found you, $n!nnSky Admiral Rogers has sent word for you to meet her in Dalaran. It sounded important. She awaits your presence in the Violet Citadel.nnMake haste!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Lord Grayson Shadowbreaker', `PortraitGiverName`) WHERE `ID` = 44700;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stormheim', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Nathanos Blightcaller at the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is good we found you, $n!nnNathanos Blightcaller, Champion of the Banshee Queen herself, sent for you in Dalaran. He made it sound urgent. He should be waiting for you in the Violet Citadel.nnMake haste!', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Lord Grayson Shadowbreaker', `PortraitGiverName`) WHERE `ID` = 44701;
