UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Breaching the Sanctum', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Oculeth to start the assault.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area.$b$bTake these telemancy orbs. If you find you need support, use them to summon Withered.$b$bWe must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.', `QuestDescription`) WHERE `ID` = 44719;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Call to Action', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Havi at Valdisdall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<As the raven stares into your eyes, a familiar voice fills your mind.>nnChampion, I require your aid. It seems Helya has shown her hand.nnSteel yourself then come to me.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Havi', `PortraitGiverName`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Havi at Valdisdall.', `QuestCompletionLog`) WHERE `ID` = 44720;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Helya\'s Conquest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search Tideskorn Harbor for evidence of Helya\'s forces.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If Helya is making an advance on the Broken Isles, we will need to answer in turn.nnGo to Tideskorn Harbor and scout her forces. We will see if Helya is foolish enough to begin her campaign against me.', `QuestDescription`) WHERE `ID` = 44721;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Disillusioned Defector', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Silgryn at Evermoon Terrace.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The atmosphere in the city has improved little, but we may find this to our advantage today.nnSilgryn asks for you at the Terrace. It seems even Elisande\'s forces are fleeing before her insanity.nnA defector has risen from the ranks and seeks to join our cause.nnSee that this individual is well received, $n. We need all the friends we can get during these dark times.', `QuestDescription`) WHERE `ID` = 44722;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'More Like Me', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Dusk Lily Sigil on Duskwatch Subjugators to identify 5 Deserters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, Outlander.$b$bI am Victoire. I served Elisande while she maintained peace in the city. I fought beside demons and worse for the greater good.$b$bThe massacre at the Waning Crescent made it clear that she no longer serves the Nightborne. She serves only herself.$b$bThere are others who feel as I do. They simply need proof that there is another way.$b$bThe Dusk Lily is not unknown to us- try showing it to those now guarding Astravar Harbor. They have seen the worst of Elisande\'s cruelty.', `QuestDescription`) WHERE `ID` = 44723;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missing Persons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire a Legion Communicator from demons in Astravar Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our new friend brings us some disturbing information.$b$bShe claims to have seen a large number of citizens dragged from Starcaller Retreat in chains. Their destination appears to be Astravar Harbor.$b$bThose taken to the harbor have yet to return, however. Worse yet, the area is now overrun with demons.$b$bI need you to find out where these people went. Infiltrate the harbor and gather any information you can.$b$bStart with the Legion filth- their corpses may point us in the right direction.', `QuestDescription`) WHERE `ID` = 44724;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hostage Situation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Astravar Harbor and join a group of captives being taken to Felsoul Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our own people, sacrificed to the Legion!$b$bWe need to intercept a transport if we intend to put an end to this trade. I\'m afraid this does mean you will be playing the part of a captive, my friend.$b$bBefore voicing your concerns, try to have a little faith.$b$bWe will follow behind in one of Deline\'s boats and break you out once we know where they are going.$b$bGo to the harbor and find a group of captives. Stand among them. Allow yourself to be taken.$b$bWe will not be far.', `QuestDescription`) WHERE `ID` = 44725;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In the Business of Souls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Aargoss in Felsoul Advance.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We will hold our position here while you find and slay the demon responsible for this camp.$b$bEnding Aargoss will not permanently stop this smuggling operation, but it may slow them down long enough for us to find another way to help these people.$b$bGo quickly. He is somewhere atop this ridge.', `QuestDescription`) WHERE `ID` = 44726;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Smuggled!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Release Maribeth and 5 captives in Felsoul Advance.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Please get me out of here!$b$bThe bars are brittle but I am so weak...$b$bThe others! There are so many others! Please help us!', `QuestDescription`) WHERE `ID` = 44727;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSE ME', `LogTitle`) WHERE `ID` = 44728;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trial of Valor: Odyn\'s Favor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gain Odyn\'s favor within the Trial of Valor Raid.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time to deal with that treacherous witch has come. I suspect you may be the one to deal the final blow, but I must be certain.nnSee me in the Halls of Valor and we will test the strength of your will.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Odyn', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Odyn', `PortraitTurnInName`) WHERE `ID` = 44729;
