UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demon in Disguise', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Khadgar in Deadwind Pass.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you were... working your magic on that demon, I was able to make headway in distilling the corrupted essences down to a simpler, more manageable form.$B$BI\'ve asked Khadgar to provide you with the concoction once he\'s had a look, but I must remind you - these essences are quite potent, often dangerous if not handled with the utmost of care.$B$BSpeak with Khadgar when you are ready to begin.', `QuestDescription`) WHERE `ID` = 44764;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stranglethorn Fishing Extravaganza', `LogTitle`) WHERE `ID` = 44765;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Backup Plan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Kalec.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Dalaran may appear to be just a floating city, but it is actually our most powerful magical weapon. It will take time to repair the arcane defenses - time the Legion will use to their great advantage.nnIt is imperative to come up with an interim plan, and quickly! nnArchmage Kalec is very knowledgeable about this sort of thing. Perhaps you should consult with him?', `QuestDescription`) WHERE `ID` = 44766;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Celestial Invitation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Algalon the Observer in a pet battle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, mortal.$B$BFor many years I have continued my observation of this planet. The halls of Ulduar have been hollow and silent, save for the occasional clattering whisper from the darkness. I grew so very bored of it!$B$BThus, I have taken up this "pet battling" you seem so fond of. Truly, an amusing pastime that will sustain my mind for many centuries!$B$BI have been amassing my collection, scouring the stars for tiny beings of cosmic power. Come, let us do battle once more!', `QuestDescription`) WHERE `ID` = 44767;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nyell\'s Workshop', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Master Artificer Nyell.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'From what I\'ve overheard, this is Master Artificer Nyell\'s workshop. His skills in construct creation are unparalleled! nnWhat a shame that he swore fealty to the Legion. I hate to destroy such a renowned craftsman, but we have no choice.nnIf you are lucky, he might even have a spare shield generator sitting around.', `QuestDescription`) WHERE `ID` = 44768;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arming the Populace', `LogTitle`) WHERE `ID` = 44769;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secrets of the Shal\'dorei', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather 8 Ancient Shal\'dorei Scrolls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This workshop includes an extensive library of rare scrolls written by my people. We all benefit by sharing information, do you not agree? nnPerhaps if we bring back such a treasure trove the Tirisgarde will be more welcoming towards me and my kind...nnPlease gather whatever you can.', `QuestDescription`) WHERE `ID` = 44770;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Threat Rises', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Pour Havi some grog.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time I told you another tale. While you listen, would you be so kind as to pour me some grog? I\'ve grown a terrible thirst.nnThe keg is very old and the tap is a bit slow.', `QuestDescription`) WHERE `ID` = 44771;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ch 5 Available Tracking Quest', `LogTitle`) WHERE `ID` = 44772;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Peak of Bones', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Grimwing for a flight to Thorim\'s Peak, then meet Minerva.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While you were gone, we strategized what to do with the harness. We can utilize its power to bind the spirits of deceased drakes to you, raising them under your will as loyal soldiers.$b$bI sent Minerva to Thorim\'s Peak in Stormheim, where she has found a brood of deceased Thorignir. They will be prime targets.$b$bSpeak to Grimwing for a flight to the mountain, then Minerva will fill you in.', `QuestDescription`) WHERE `ID` = 44775;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSE ME', `LogTitle`) WHERE `ID` = 44777;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Backlash', `LogTitle`) WHERE `ID` = 44780;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Council\'s Call', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out the Council of Six in the Violet Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The Council of Six has sought your aid against a \'great threat\'.>$B$B<If they have turned their focus on something outside of the demon hordes pouring out of the Tomb of Sargeras, it must be truly dangerous.>$B$B<But how does the object you found on the Broken Shore fit into all of this? You know only that the Council awaits at the Violet Citadel.>', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Seek out the Council of Six.', `AreaDescription`) WHERE `ID` = 44781;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Away From Prying Eyes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Join the Council of Six in the Purple Parlor above the Violet Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Wars are not won solely with armies charging bravely across the battlefield, $ct.$B$BSometimes, it is the actions of individuals that matter most, fighting battles few ever hear about. That is why - $B$B<Khadgar furrows his brow slightly.>$B$BWe should really discuss this somewhere a tad more private. Let\'s move up to the Purple Parlor, shall we?', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Join the Council of Six in the Purple Parlor.', `AreaDescription`) WHERE `ID` = 44782;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'From Bones They Rise', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Revive $1oa Deceased Thorignir in Thorim\'s Peak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alright, the job is to get the broodmother under our control. But hear me out. A few more drakes would be a boon, right?$b$bWhile we\'re here, why don\'t we use our awesome power over undeath to raise some of her brood as well? Although the peak has claimed their corpses for the ice, I\'m sure the embrace of undeath will be much more welcoming. We must find their frozen corpses and breathe your will into them.', `QuestDescription`) WHERE `ID` = 44783;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Advanced Wanding', `LogTitle`) WHERE `ID` = 44784;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Midterm: Rune Aptitude', `LogTitle`) WHERE `ID` = 44786;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Bonemother', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Light Thorim\'s Beacon at Thorim\'s Peak to raise Daumyr. Defeat her and raise her from death.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s time to call the mother, the true reason we came. She is strong, her sheer will and strength allowing her to face this peak in order to watch over the remains of her brood. While the Thorignir is a grand sight, I like my dragons a little more bony. She must die first.$b$bRemember the pyre where we met? She is its guardian, as the spirit was at the peak. If we light it, she will come.', `QuestDescription`) WHERE `ID` = 44787;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Work Study: Bestiaries of Azsuna', `LogTitle`) WHERE `ID` = 44788;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Holding the Ramparts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Scout the demonic presence atop Black Rook Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With their ground presence weakened the Legion has retaliated with additional forces.nnOur allies managed to track several of these demons to the skies above Black Rook. I fear they intend to establish a foothold.nnTake this hippogryph and scout the ramparts. Should this fear become a reality I ask that you deal with the threat swiftly.', `QuestDescription`) WHERE `ID` = 44789;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trial by Demonfire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Rozzeleth in Meredil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are out of time. I have reports that a pitlord has come to Meredil. nnI have dispatched a strike force. We cannot let this demon flank our army here, nor can we let him find Shal\'Aran. It is time to temper these recruits in a real battle.nnJoin our forces in Meredil, engage the demon, and help us ensure this new army of ours is not lost in its first conflict.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'He seeks to crush the rebellion.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Rozzeleth', `PortraitGiverName`) WHERE `ID` = 44790;
