UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Against Magatha\'s Will', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Magatha Grimtotem, then bring the Doomstone to Farseer Nobundo.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well? What are you waiting for? Hand over the Doomstone.', `QuestDescription`) WHERE `ID` = 44800;
