UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Karazhan: Master of the House', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the listed items and bring them to the cemetery outside Karazhan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Inside the pocket watch is a worn note.nn"The next affair will take place in Morgan\'s Plot, it will cause quite a stir! The following guests will be in attendance:nnLord Ference, his preferred vintage is red.nBaroness Millstipe, she will only attend on the promise of cheese. Strange woman.nBaron Dreuger, a ravenous soul, any well spiced meat should keep him happy.nnAs always, I shall ring the bell should I need you.nn- Medivh"', `QuestDescription`) WHERE `ID` = 44803;
