UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Waning Refuge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Leave Felsoul Advance on Deline\'s Gondola.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have done all we can here.$b$bLet us get everyone into the boat and get out while we still can.$b$bWe have bought time for the others but nothing more.', `QuestDescription`) WHERE `ID` = 44814;
