UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recruitment Drive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ask Aerylia to escort you to Helheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Helya\'s kvaldir have been raiding Azeroth\'s coasts for centuries, and many worthy vrykul who were destined to become my Valarjar were stolen. nnNow that their cursed queen is defeated, the souls held captive in Helheim can finally be freed to join us!nnGo to Helheim with Aerylia. I assure you she will bring you back safely.', `QuestDescription`) WHERE `ID` = 44849;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arming the Army', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search stolen crates for 10 stolen blades and 10 stolen shields.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The recent battles have greatly depleted our supplies, and we will need arms for our new Valarjar. nnThe kvaldir have an abundance of weapons, armor, and other spoils from their raiding stockpiled in stolen crates. nnConfiscate whatever you can!', `QuestDescription`) WHERE `ID` = 44850;
