UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trolling Them', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Remove insulting items from the elven war camps.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My army is disciplined, and they will follow my order not to engage the Sin\'dorei in combat unless I give the command.$b$bHowever, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults.$b$bPlease, $p, we need someone both armies respect to collect these items before fighting breaks out.', `QuestDescription`) WHERE `ID` = 44858;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Liadrin\'s Command', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lady Liadrin in Meredil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Shal\'Aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered.$b$bAnd in all of this, Lady Liadrin has a battery of requests I simply do not have the time to deal with.$b$bWill you go to her? Her growing army is hard to miss in Meredil.', `QuestDescription`) WHERE `ID` = 44859;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trolling Them', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Remove insulting items from the elven war camps.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My army is disciplined, and they will follow my order not to engage the kaldorei in combat unless I give the command.$b$bHowever, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults.$b$bPlease, $p, we need someone both armies respect to collect these items before fighting breaks out.', `QuestDescription`) WHERE `ID` = 44860;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arming the Rebels', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Victoire in Meredil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Nightfallen rebellion is growing in number, but they have not fought a real war in ages.$b$bVictoire and Silgryn are doing their best to train the new arrivals, but could use an experienced hand.$b$bGo to them and show them some of the skills in battle you have picked up in your travels. I want those Nightfallen ready for battle when the time comes.', `QuestDescription`) WHERE `ID` = 44861;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arming the Rebels', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Victoire in Meredil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Nightfallen rebellion is growing in number, but they have not fought a real war in ages.$b$bVictoire and Silgryn are doing their best to train the new arrivals and could use an experienced hand.$b$bGo to them and show them some of the skills in battle you have picked up in your travels. We need those Nightfallen ready for battle when the time comes.', `QuestDescription`) WHERE `ID` = 44862;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clearing the Air', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover a Cardinal Sky Core, a Cardinal Storm Core, and a Cardinal Wind Core for Lunelli. Bring them back to her in Shattrath when you have all three.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ancient weapons require ancient offerings to regain the knowledge on how to construct them.$b$bIf you wish to learn how weapons forged from air are crafted, then you must first battle with beings born from it.$b$bBring me their cores and I will gift you the knowledge you seek.', `QuestDescription`) WHERE `ID` = 44863;
