UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Butler to the Great', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Lay the table, and summon Moroes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A ghostly dinner party awaits, ready for the spread and its dinner guests.', `QuestDescription`) WHERE `ID` = 44865;
