UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trial of Valor: Odyn\'s Judgment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Helya within the Trial of Valor Raid.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve proven worthy to challenge Helya. Now with my blessing, the power to defeat her is yours.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Helya', `PortraitGiverName`), `PortraitTurnInName` = IF(`PortraitTurnInName` IS NULL OR `PortraitTurnInName` = '', 'Odyn', `PortraitTurnInName`) WHERE `ID` = 44868;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Talon Terror', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the portal in the Dreamway to meet Thisalee at the Shrine of Aviana in Mount Hyjal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I just received word that the Shrine of Aviana is under attack by the Burning Legion! While the Druids of the Talon here are taking their time planning and strategizing their defense, our brothers and sisters are being slaughtered where they stand.$b$bI cannot stand idly by while my home shrine is in danger. Please, come with me to save my people.', `QuestDescription`) WHERE `ID` = 44869;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mouths to Feed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Arcanist Valtrois in Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have rescued many refugees, as you can see. Unfortunately this has revealed a new problem.$b$bThe arcan\'dor fruit is our salvation, but it does not bear enough fruit right now to cure everyone. We must rely on mana a little longer to tide the refugees over.$b$bValtrois thinks that she may have a solution. Please go speak with her and see what she plans to do.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Speak with Arcanist Valtrois in Shal\'Aran.', `AreaDescription`) WHERE `ID` = 44870;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.1 World - 850 - Special - Moroes 1', `LogTitle`) WHERE `ID` = 44871;
