UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Oculeth Ex Machina', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Oculeth and teleport to Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have a plan to feed Shal\'Aran.$b$bNow that I am no longer starving for mana I have had time to study ley lines in new regions. I detected an eddy of mana in the ley lines of Azsuna. I have plenty of magic at my disposal, but we must visit the ley line in person in order to properly redirect the energy to Shal\'Aran.$b$bOculeth has graciously offered to teleport us there, but I could use an assistant. Care to join me?', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Speak with Oculeth and teleport to Azsuna.', `AreaDescription`) WHERE `ID` = 44873;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unbeleyvable', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist Arcanist Valtrois with placing ley line taps.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Back to the task at hand!$b$bTake these ley line taps. We can use the resonant energies to properly redirect the flow, but they must be placed in precise locations. I will show you where.$b$bYour friend has agreed to... "supervise" us. Let us hope she just stays out of the way while the professionals take care of this.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Assist Arcanist Valtrois with placing ley line taps.', `AreaDescription`) WHERE `ID` = 44874;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Art of Flow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Protect Arcanist Valtrois while she completes the ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All done, $n! We have but one more step and Shal\'Aran will have all the mana it needs.$b$bNow that I have better access to the ley line below I can break the pool so that it will flow through properly. Given the chaotic state of this ley line it will require all of my concentration to redirect the energy.$b$bI must warn you that we will attract attention while I am doing this. You will need to protect me while I complete the process.$b$bSpeak to me when you are ready.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Protect Arcanist Valtrois while she completes the ritual.', `AreaDescription`) WHERE `ID` = 44875;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Dance With Dragons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Stellagosa to ride back to Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I must say I am impressed, $n.$b$bYou and your friend were able to fix a ley line, and you are not even dragons!$b$bYou both seem exhausted by this ordeal. Allow me to help you get back home.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Speak with Stellagosa to ride back to Shal\'Aran.', `AreaDescription`) WHERE `ID` = 44876;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Attack on the Roost', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Legion invaders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Skylord Shadegrove has been leading the defense of the shrine, but I think he\'s starting to lose hope. Clearly he needs some more firepower behind him!$b$bLet\'s take out these demons and fend off the attack. They\'ll never see it coming!', `QuestDescription`) WHERE `ID` = 44877;
