UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shipwrecked Survivors', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with First Sergeant Steelfang.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It appears that we have allies here on the Broken Shore.$b$bA small band of shipwrecked soldiers have been surviving here since the first assault. Their strength and tenacity will bolster our ranks.$b$bMake your way to their encampment along the beach and bring them here. Tell them that reinforcements have arrived, and the battle against the Burning Legion waits for no one.', `QuestDescription`) WHERE `ID` = 44885;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unwanted Evidence', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Fel Crystal Fragment to Archmage Khadgar in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<You find a shattered remnant of fel crystal clutched in Skovald\'s hand, still glowing with demonic power.$b$bIt seems the god-king didn\'t want it found. Did the crystal contain the message sent to him by Gul\'dan?$b$bIf anyone can glean the meaning of the broken crystal, it\'s Khadgar.>', `QuestDescription`) WHERE `ID` = 44886;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Uncovering Orders', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the Fragment of Spite from Blackrook Hold (Mythic), the Fragment of Power from Violet Hold (Mythic), and the Fragment of Torment from Vault of the Wardens (Mythic).', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It would seem secret orders have been parceled out by the Legion\'s masters. If they\'re determined to conceal their plan from us, it must pose a dire threat.$b$bWe know high-ranking demons and their allies are mobilizing in places of power. Odds are good that they have received similar crystals.$b$bPerhaps you can find one intact, or at least gather enough fragments that we can reassemble one and determine the Legion\'s target.', `QuestDescription`) WHERE `ID` = 44887;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aviana\'s Grace', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Contact Aviana in the Shrine of Aviana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If this was only the distraction, where is the main force? Who else is under attack? We need to figure out who else is in danger! Aviana should know, she\'s got eyes everywhere.$b$bLet\'s go ask her. We should be able to contact her in the back room.', `QuestDescription`) WHERE `ID` = 44888;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Resource Management', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Aerylia to travel to the Path of Suffering on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that you possess Helya\'s Horn, the kvaldir are yours to command. We may as well put them to good use for a change. nnI\'ve dispatched my Val\'kyr, Danica, to the Broken Shore. She has identified a few Legion targets that should be eliminated.nnAerylia will send you there when you are ready to leave.', `QuestDescription`) WHERE `ID` = 44889;
