UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'reuse me', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Viz\'aduum the Watcher in Karazhan on Normal difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Defeat Viz\'aduum the Watcher in Karazhan (Normal).', `QuestDescription`) WHERE `ID` = 44913;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arms: The Thieving Apprentice', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Xylem\'s Tower within Bear\'s Head in Azshara.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we\'ve been unable to track him.nnFortunately, the thief dropped a note from his master, addressing him as one of his "apprentici." I know of only one mage who uses that particular pluralization - Archmage Xylem.nnI\'ll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to.nn|cFF660000Specialization: Arms Warrior|r', `QuestDescription`) WHERE `ID` = 44914;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Professionally Good Looking', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect the Fanciful Hat, Well-Tailored Robes, and Magnificent Mantle from Raethas Dawnseer, Lobos and Phloem in Azshara.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The archmage has recently locked himself away in his tower. If you wish to enter, you\'ll need help from some of his apprentices. I\'m afraid you won\'t get it dressed like that.nnXylem has a thing for... outfits, and his apprentices use them to show rank. If you wish his apprentices to help you, you\'ll need to appear their superior. Such is their desire to impress the archmage, many of his apprentices will battle each other for the best pieces.nnI think you know where this is going.', `QuestDescription`) WHERE `ID` = 44915;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '99.0 [reuse me]', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', '99.0 [reuse me]', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '99.0 [reuse me]', `QuestDescription`) WHERE `ID` = 44916;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Karazhan: The Tower of Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Viz\'aduum the Watcher in Karazhan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your champions discovered that the area surrounding Karazhan is under an invasion from the Legion. This does not bode well.nnClimb the tower, and defeat all in your path.', `QuestDescription`) WHERE `ID` = 44917;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Message From Our Enemies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Listen to Andaris\'s Message in Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n! The messages from Ly\'leth we traced throughout the Terrace - we could not have known at the time, but somebody was watching.$B$BThis crystal was delivered by a courier early this morning. <Pointing to the crystal by her side.>$B$BI am afraid the message contained within is not for the faint of heart. It has not been shown to anyone else, but you deserve to see it for all you have done for us.', `QuestDescription`) WHERE `ID` = 44918;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Challenge From Our Enemies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Andaris at the Lunastre Estate in Suramar City.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Make no mistake. This message cannot be taken lightly. Any threat made against our people will be dealt with swiftly.$B$BWe must travel to the estate at once to discover what has become of Ly\'leth.', `QuestDescription`) WHERE `ID` = 44919;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Order of Incantations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Xylem\'s apprentices in Bear\'s Head to decipher the code to open the barrier to his tower.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The barrier shielding the tower can only be opened by activating the imbued gems in the correct order. The order is only known to Xylem and his inner circle of apprentices. No others have yet been able to decipher the code, and mistakes are met with deadly consequences.nnThe aspiring apprentices spend a lot of their time around the tower. Some may have seen or heard something that might point to a solution.nnLet us hope, for your sake, their information proves valuable.', `QuestDescription`) WHERE `ID` = 44920;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lone Wolf', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Thisalee Crow in Moonglade.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My eyes and ears fly across Azeroth, bringing me back news of many things. My ally Goldrinn took to the barrows of Moonglade in mourning upon the death of Varian Wrynn. He has been untouched in the dream... until now.$b$bDemons have been seen invading the very same barrows, killing many more of our mortal druids in the process. You must go. Save Goldrinn, avenge our people! Take my hatchling Thisalee with you. Her tenacity and bloodlust is welcome in my clutch. You shall have my aid.', `QuestDescription`) WHERE `ID` = 44921;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Inside the Winter Storm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Grapple across from the tower and climb to the top of the mountain path.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There, it looks like there\'s a good spot to launch to right across from here. This path should take you all the way to the top.nnAccording to my  intel, your dragons should be up there. Let\'s just hope that they\'re still in a state to help you.', `QuestDescription`) WHERE `ID` = 44922;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Helarjar Landing: Vrekt', `LogTitle`) WHERE `ID` = 44923;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Archmage Accosted', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Confront Archmage Xylem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the barrier dispelled, Archmage Xylem is finally within reach!nnHopefully he\'ll be cooperative in returning the Iris...', `QuestDescription`) WHERE `ID` = 44924;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Closing the Eye', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with War Councilor Victoria to be teleported to Archmage Xylem\'s location and defeat him.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have received reports from the apprentices at Xylem\'s Tower that they\'ve been able to use the remant of Xylem\'s portal to pinpoint his location.nnWe have orders from the Council of Six to open a portal directly to him, though whatever magic he\'s channeling on the other end is powerful enough to allow us to only keep it open for a brief window.nnThe apprentice, Joanna asked I give you this message before you proceed. Speak to me when you\'re ready.', `QuestDescription`) WHERE `ID` = 44925;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Familiar Axe to Grind', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Show the axe blade to Hoddruc Bladebender at Chiselgrip.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The construction of this blade feels familiar, but you can\'t quite recall where you may have seen something like it before.$b$bPerhaps someone at Chiselgrip might know more about its construction.', `QuestDescription`) WHERE `ID` = 44926;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Worth Its Weight in Steel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather $1oa Axe Blades from orcs and ogres around the Burning Steppes. Return them to Hoddruc in Chiselgrip when you\'ve collected them all.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Listen, ye seem like one who may be interested in getting a copy of those axe plans.$b$bCould probably make a pretty penny at the auction house on it. But I can\'t just hand \'em over to ya, $glad:lass;. Not fer free.$b$bThat axe blade ye brought me, I could use more of those. Good steel in those blades. Don\'t worry, $glad:lass;, I just need a few...$b$bWhat do ye say?', `QuestDescription`) WHERE `ID` = 44927;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Something\'s Not Quite Right...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Remove the disguise of 5 Nightborne Infiltrators.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Something is troubling me, champion.$b$bBeyond these simple japes, the Kirin Tor has had to break up a few fights between the elves. I am worried something - or someone - might be influencing them.$b$bYour disguise was made by the nightborne, yes? It is not unreasonable to assume they can do something similar.$b$bFortunately, Thalyssra has told me much about how the illusion works, and I believe this crystal can remove their disguise.$b$bWhy don\'t you check the camps, just to be safe?', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Remove the disguise of 5 Nightborne Infiltrators.', `AreaDescription`) WHERE `ID` = 44928;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Deadmines: Sea\'in Red', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Bloodied Defias Bandanas for Captain Bramblebeard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Arr, finally! I been stuck up here f\'years with naught company but me own thoughts. Tis good to clap me eyes on another swashbuckling soul. Are ye up for a plot of revenge and skullduggery? These meddlin\' Defias thugs murdered  me and me crew years ago before they took over this cave. I propose a series of counter-murders to bring about balance! Bring me proof ye\'ve dealt with enough of the thieves to clog a bilge pump!', `QuestDescription`) WHERE `ID` = 44930;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSE', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise your Snowfeather Hatchling to level 25.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your snowfeather hatchling looks at you timidly. It appears to be looking to you to help it survive and grow.>', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Erk!', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Snowfeather Hatchling', `PortraitGiverName`) WHERE `ID` = 44931;
