UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Inside the Winter Storm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Grapple across from the tower and climb to the top of the mountain path.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There, it looks like there\'s a good spot to launch to right across from here. This path should take you all the way to the top.nnAccording to my  intel, your dragons should be up there. Let\'s just hope that they\'re still in a state to help you.', `QuestDescription`) WHERE `ID` = 44940;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dances With Ravenbears (UNUSED)', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help the Blackfeather ravenbears perform their tribute ritual.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The chieftain beckons for the ravenbears to gather the tribute and gestures toward the ritual circle outside.>nnCaw! Caw ca-caw!nn<It looks like he wants you to follow.>', `QuestDescription`) WHERE `ID` = 44941;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Now That\'s Just Clawful!', `LogTitle`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'The most audacious makrura by the sea.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Clawdayshus', `PortraitGiverName`) WHERE `ID` = 44943;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aura of Uncertainty', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Khadgar unravel the mystery behind the fragments.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We may not know the Legion\'s intent just yet, but after analyzing your findings we will know soon enough.', `QuestDescription`) WHERE `ID` = 44944;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Raising Your Snowfeather', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise your Snowfeather Hatchling to level 25.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your snowfeather hatchling looks at you timidly. It appears to be looking to you to help it survive and grow.>', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Erk!', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Snowfeather Hatchling', `PortraitGiverName`) WHERE `ID` = 44948;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Smell of Humans', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take your Snowfeather Hatchling to the Gilded Rose in Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<You\'ve noticed that your snowfeather hatchling shakes whenever humans are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of humans, so that it can get used to the smell.>', `QuestDescription`) WHERE `ID` = 44949;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hunting Lesson: Northern Hawk Owls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 3 Northern Hawk Owls in Highmountain with your Snowfeather Hatchling.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your snowfeather hatchling seems to get agitated when you are near other critters, none more so than the hawk owls of Highmountain. It fluffs up its plumage and squawks loudly whenever one is nearby. It appears to have a primal need for predation.> nn<It seems you will need to take your falcosaur out hunting.>', `QuestDescription`) WHERE `ID` = 44950;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tank Chosen', `LogTitle`) WHERE `ID` = 44951;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blackrock Depths: Jewel of the Depths', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Blackrock Depths and obtain a Core of Bael\'Gar, Core of Roccor, Essence of Incendius, and Essence of Magmus. Once you have all four items, combine them at the Black Forge near the entrance to Molten Core at the bottom of Blackrock Depths and bring the Blackrock Ruby back to Wixxrak in Everlook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Welcome to Everlook. Could I interest you in a new weapon of sorts?$b$bYou know, I\'m not just into selling weapons of mass dismemberment here at the shop. I like rare jewels as well.$b$bPerhaps you and I can come to an arrangement of sorts in procuring a jewel I\'ve had my eye on getting for quite some time. I have some great blacksmithing plans here you might be interested in, you know, in trade for your services.$b$bNow, onto the details...', `QuestDescription`) WHERE `ID` = 44952;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Allies in Highmountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 5 World Quests in Highmountain with your Snowfeather Hatchling out.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your snowfeather hatchling emits a deep, chittering growl when you pass near Thunder Totem.> nn<The Highmountain Tribes immediately began attempting to evict the falcosaurs from their territory. It must consider them a threat to the flock, and the growl is probably its attempt to protect you.>nn<Show your falcosaur that you and it can work alongside the Highmountain Tribes.>', `QuestDescription`) WHERE `ID` = 44953;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Snowfeather Team Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 3 Pet Battle World Quests with your Snowfeather Hatchling.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your snowfeather hatchling looks at you and emits a sort of squawking bark. It appears to want to do something together as a team!>nn<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>', `QuestDescription`) WHERE `ID` = 44954;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Visitor in Shal\'Aran', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet the stranger outside Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Someone came to Shal\'Aran while you were in the City. She asked for you specifically.$b$bI did not recognize her face, nor her voice, but she seemed trustworthy and earnest.$b$bShe is just outside the cavern. Meet with her and determine her purpose for coming here.', `QuestDescription`) WHERE `ID` = 44955;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Deadly Prey', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 1 Rare Elite World Quest with your Snowfeather Hatchling out.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<After working together on recent pet battles, your snowfeather falcosaur seems much more interested in your combat abilities. It might learn a thing or two from watching you do battle with a powerful opponent.>', `QuestDescription`) WHERE `ID` = 44956;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hunting Lesson: Spiketail Beaver', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 3 Spiketail Beavers in Highmountain with your Snowfeather Hatchling.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your snowfeather hatchling has been interested in following beaver tracks recently. It must have found a new species to prey upon.>', `QuestDescription`) WHERE `ID` = 44957;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Unfriendly Faction', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 3 PvP World Quests with your Snowfeather Hatchling out.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<When passing the other faction recently, your snowfeather walked right up to them without fear. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>', `QuestDescription`) WHERE `ID` = 44958;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Snowfeather Bonding', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Buy a Tiny Pack from Susana Averoy in Dalaran for your Snowfeather Hatchling.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your snowfeather hatchling keeps getting into your pack and making a mess. It squawks loudly whenever you remove it, and rams you with its head. Maybe you can distract it with a tiny pack of its own?>', `QuestDescription`) WHERE `ID` = 44959;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hunting Lesson: Mudshell Conch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 3 Mudshell Conches in Highmountain with your Snowfeather Hatchling and 2 Flying pets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your snowfeather hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the snails of Highmountain.>', `QuestDescription`) WHERE `ID` = 44960;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Teamwork Lesson: Naraxas', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Naraxas in Neltharion\'s Lair in Highmountain with your Snowfeather Hatchling out.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<While victorious, your snowfeather hatchling squawked and pecked at its allies during some of those last fights. Showing it a good example of teamwork might help.>', `QuestDescription`) WHERE `ID` = 44961;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hunting Lesson: Coralback Fiddler', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 3 Coralback Fiddlers in Highmountain with your Snowfeather Hatchling and 2 Elemental pets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your snowfeather hatchling is particularly wary of the elemental pets in your menagerie. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>', `QuestDescription`) WHERE `ID` = 44962;
