UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Teamwork Lesson: Dresaron', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Dresaron in Darkheart Thicket in Val\'sharah with your Sharptalon Hatchling out.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your sharptalon hatchling does not seem particularly interested in your other pets, and largely ignores them during combat. Showing it a good example of teamwork might help.>', `QuestDescription`) WHERE `ID` = 45011;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Teamwork Lesson: Serpentrix', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Serpentrix in Eye of Azshara in Azsuna with your Bloodgazer Hatchling out.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<While victorious, your bloodgazer hatchling distracted your other pets during crucial moments in combat. Showing it a good example of teamwork might help.>', `QuestDescription`) WHERE `ID` = 45012;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hunting Lesson: Vale Flitter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 3 Vale Flitters in Val\'sharah with your Sharptalon Hatchling and 2 Aquatic pets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your sharptalon hatchling adamantly refuses to go anywhere near a body of water, squawking and scratching the ground whenever you wade in yourself. Perhaps working with some aquatic pets would help it get over this fear. Hunting together against the new prey it has begun stalking may just do the trick.>', `QuestDescription`) WHERE `ID` = 45013;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hunting Lesson: Felspider', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 3 Felspiders in Azsuna with your Bloodgazer Hatchling and 2 Critter pets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Whenever you retire to an inn, your hatchling climbs the furniture and refuses to touch the ground. It will hop unsteadily from object to object, often causing a large mess. You recall that this may be due to a bad experience with fleas. Hunting together with some critter pets against new prey might help it get over this fear.>', `QuestDescription`) WHERE `ID` = 45014;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Teamwork Lesson: Xavius', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Xavius in the Emerald Nightmare with your Sharptalon Hatchling out.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your sharptalon hatchling has taken to hiding in your pack when you approach very powerful creatures in the world. It must learn to remain calm under pressure, even when facing the darkest of nightmares. Showing it an epic example of teamwork against a fearsome foe might help.>', `QuestDescription`) WHERE `ID` = 45015;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Teamwork Lesson: Skorpyron', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Skorpyron in the Nighthold with your Bloodgazer Hatchling out.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your bloodgazer hatchling growls and hisses at large beasts, seemingly without concern for its own safety. It will need to learn to rely on numbers to keep it safe. Showing it an epic example of teamwork against a great beast might help.>', `QuestDescription`) WHERE `ID` = 45016;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sharptalon Team Rumble', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 3 Pet Battle World Quests with your Sharptalon Hatchling and 2 Magic pets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your sharptalon hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>', `QuestDescription`) WHERE `ID` = 45017;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloodgazer Team Rumble', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat 3 Pet Battle World Quests with your Bloodgazer Hatchling and 2 Beast pets.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your bloodgazer hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>', `QuestDescription`) WHERE `ID` = 45018;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sharptalon Reunion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return the Sharptalon Hatchling to the Verdant Cliffs in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your sharptalon hatchling has not been eating recently. It seems to be depressed. Perhaps it is time to return it to its place of origin?>', `QuestDescription`) WHERE `ID` = 45019;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloodgazer Reunion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return the Bloodgazer Hatchling to Alluvanon\'s Delta in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your bloodgazer hatchling refuses to drink. It seems to be depressed. Perhaps it is time to return it to its place of origin?>', `QuestDescription`) WHERE `ID` = 45020;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Answers Unknown', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Jubeka Shadowbreaker within Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Have you noticed a change in Jubeka\'s demeanor? I know she\'s not the warmest of warlocks, but I fear she\'s been more withdrawn than usual.$B$BI imagine her mind lingers on Kanrethad, the council\'s one-time leader. Jubeka was steadfast in her commitment to keeping him banished, until the Burning Legion took her as their prisoner.$B$BHis fate is unknown, and it\'s clearly troubling our friend. The last thing she said to me, was that she felt his presence in Azsuna. Don\'t let her travel this path alone.', `QuestDescription`) WHERE `ID` = 45021;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '3+ Targets Chosen', `LogTitle`) WHERE `ID` = 45022;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hybrid Chosen', `LogTitle`) WHERE `ID` = 45023;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cult Culling', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Head into Felfire Cavern and kill members of the Cult of the Green Flame.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The lure of Kanrethad is strong. Even when not in this world, there are those who wish to be near him at any cost, hoping to share in his power.$B$BA group of these fanatics are here in Faronaar, working tirelessly to bring Kanrethad back, I\'ve learned as much from my prisoner.$B$BWe cannot let them succeed, $n. Find their compound and kill as many of them as you can.$B$BI will remain here and see what else I can learn about their intentions.', `QuestDescription`) WHERE `ID` = 45024;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stealing the Source of Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 5 Fel Crystals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My prisoner is a chatty one, $n. He tells me that the Cult of the Green Flame is harnessing fel energy to fuel their efforts of bringing Kanrethad back from banishment.nnWithin their compound they are powering fel crystals that can hold a great amount of fel magic. Without the proper power to perform their ritual, the occultists will have a tough time succeeding in their task.nnSteal their fel crystals, but don\'t destroy them. We can always find a use for something so powerful.', `QuestDescription`) WHERE `ID` = 45025;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Expending Fel Energy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Harness the power of the Fel Crystals and expend their energy by killing demons within Faronaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Soon Kanrethad\'s banishment will fade, and he will return to our world. nnWe must keep him, and his power, out of the Legion\'s hands at any cost.nnIf my old friend is still in there somewhere, perhaps we can bring him back.nnThe crystals you recovered feed on fel energy. We can use the ravenous crystals to siphon away the magic that consumes Kanrethad.nnBut first, their power must be depleted. To do so, you will need to harness the power of the crystals and use their energy to kill demons.', `QuestDescription`) WHERE `ID` = 45026;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To the Broken Shore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Head to the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It would seem that Kanrethad\'s twisted followers have begun their ritual on the Broken Shore.$B$BWe must act quickly. The Burning Legion cannot be allowed to use Kanrethad as their weapon.$B$BWe have acolytes on standby, ready to perform a ritual of summoning on the Broken Shore when you\'re ready.', `QuestDescription`) WHERE `ID` = 45027;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Fate of Kanrethad', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Fel Crystals to siphon fel energy from Kanrethad.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can feel his presence, Netherlord! Kanrethad is here! His followers have set up camp in the nearby pass, and are performing the ritual to bring him back as we speak.$B$BQuickly, take the fel crystals. Arrange them in a circle around Kanrethad.$B$BIf placed correctly, the crystals should link together and begin to siphon the fel energy.$B$BNow go, before it\'s too late!', `QuestDescription`) WHERE `ID` = 45028;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Talon\'s Vengeance - Intro Complete', `LogTitle`) WHERE `ID` = 45029;
