UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Call of Battle', `LogTitle`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These demons have no honor! Rather than meet us in glorious, open-battle; they hide behind their barricades and siege weapons.nnThe Valarjar have come for the glory of battle and we will not be turned away by cowardly tactics!nnDestroy their cannons and bring down their barriers, so that our valiant Valarjar may face them in the true spirit of battle! When the dust of battle clears, the corpses of demons shall litter the ground... and the Valarjar will stand triumphant!', `QuestDescription`) WHERE `ID` = 45035;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Weapon No More', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Badly Broken Dark Spear to Ko\'Zan at Mossy Pile in Un\'Goro Crater.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The spear you found certainly has the makings of troll designs from other blacksmithing crafts.$b$bPerhaps somebody at one of the camps here in Un\'Goro will know more about it.', `QuestDescription`) WHERE `ID` = 45044;
