UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Infiltration Plans', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the plans to the Council of the Six in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While the text is hard to follow and covered in demonic runes, it appears to be plans to infiltrate Dalaran. The Council of the Six will want to see this.', `QuestDescription`) WHERE `ID` = 45050;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Reverse Blacksmithing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deconstruct the Broken Darkspear.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'And \'ere I thought I\'d never see dis ting again!$b$bAlthough, it don\'t look like it used to. Aw mon, I\'m gonna be in big trouble if I show up wit dis in my hand.$b$bDo ya tink you could help me fix it? I don\'t have da plans for it, cause you see, da first night I spent here, da creatures came up and stole all me tings.$b$bBut whadd\'ya say? Help a bruddah out?$b$bI tink if you can figure out what it\'s made from, den you can fix it and I can write down da details on how it\'s made.', `QuestDescription`) WHERE `ID` = 45051;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Taste of Their Own Medicine', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill creatures around Un\'Goro Crater and retrieve $1oa Stolen Enchanted Thorium Bars, $2oa Mostly Powerful Mojos, $3oa Calcified Diemetradon Scales, and $4oa Bleached Stegodon Spikes. Bring them to Ko\'Zan when you\'re done.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I been at dis camp for some time now, an\' I know for a fact dat dose materials can be found right here in Un\'Goro.$b$bTime ta give da creatures here some payback. Take from dem just like dey took from me! At least, you could do dat for me, right bruddah?$b$bI\'ll just wait here for ya to return wit\' all da stuff.', `QuestDescription`) WHERE `ID` = 45055;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Noressa', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue Noressa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'She is still in there, $n. Noressa, my wife.$b$bShe is in the Promenade while we wait outside, preparing to strike. Who knows what has happened to her?$b$bPlease, friend, I fear the worst. Tell her there is hope outside.$b$bWe had a small house in the south of the Grand Promenade, by the water gardens. She will probably be there during this madness.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Rescue Noressa.', `AreaDescription`) WHERE `ID` = 45056;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Saving My Head', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the forge near Ko\'Zan to recreate the Darkspear.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Seeing as how you\'re a blacksmith, I figured it\'d be best if ya made da spear. You can use dis forge here to do what ya need to to do.$b$bI\'ll start writin\' down what ya do and den we\'ll have us both da spear and da recipe!', `QuestDescription`) WHERE `ID` = 45057;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Release the Wardens!', `LogTitle`) WHERE `ID` = 45058;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scrolls of the Faldrottin', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the scrolls to the Council of the Six in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While it is definitely odd that a demon would carry a scroll of vrykul writings, what is even more interesting are the contents. nnThe writings appear to reference a vrykul prophesy of one who would unite the Tideskorn against the Burning Legion. This information should be brought to the Council of Six immediately.', `QuestDescription`) WHERE `ID` = 45061;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Resisting Arrest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the withered to dismantle the Power Source inside the Soul Engine at Felsoul Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your findings do not disappoint, $n.nnMake your way to the soul engine and use our newly acquired weapons to dismantle the power source.', `QuestDescription`) WHERE `ID` = 45062;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Felsoul Experiments', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Test the withered\'s resistance against fel magic at Felsoul Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Andaris\'s control over the withered poses a real threat. If we are to increase the withered\'s resistance against these effects, we must do so in an environment built from this very magic.nnHead for Felsoul Hold at once. When you arrive, I will send withered to aide in your efforts. It is of the utmost importance you do not leave until you are certain the experiments yield the appropriate results.', `QuestDescription`) WHERE `ID` = 45063;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felborne No More', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $2oa Felborne and their leader, Valthis Ama\'ran, at the Felborne Outpost in Crimson Thicket.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Felborne have begun to expand their grasp beyond the city\'s reach. A camp to the east in the Crimson Thicket is of a particular interest to us. Their outpost leader, Valthis Ama\'ran, serves Andaris directly.$B$BNow is the time to put our withered training and Oculeth\'s device to the test. We cannot allow them to advance any further, $n.$B$BHead for the camp and use the orb to sever the head of the beast. The time has come to begin our advance.', `QuestDescription`) WHERE `ID` = 45064;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Survey the City', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Advanced Telemancy Beacon to survey the Terrace of Order in Suramar City.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Never a dull moment! Well... perhaps this is not entirely true.nnI\'m afraid I must ask you once more to return to the city to gather information. But this is not just any information - this is information extraction!nnI require specific coordinates to allow me to focus my teleportations with extreme accuracy. It will, unfortunately, take a bit of time to dig through the information once retrieved, but no matter. We have plenty else to do in the meantime.', `QuestDescription`) WHERE `ID` = 45065;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Experimental Instability', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather the Telemancy Notes and $3oa Discarded Orbs from Oculeth\'s Test Chamber.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In order to advance our studies I must ask you to recover a few particular items from my long-forgotten chambers.$B$BI assure you it is... mostly safe there, aside from a few unstable elements.$B$BMake your way to my workshop and locate the teleporter. I\'ll disable its cloaking device when you arrive.', `QuestDescription`) WHERE `ID` = 45066;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Telemantic Expanse', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Oculeth in Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Understanding fel magic alone may not be enough, $n.nnSpeak with Oculeth about diversifying our efforts. I hear he\'s got something... unique planned for us.', `QuestDescription`) WHERE `ID` = 45067;
