UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Loot and Plunder!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Burn $1oa Blacksail Booty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m bein\' honest here matey, I\'ve got me own motives fer bein\' here. Last time there was a bit of a debacle. Some drinkin\', some gamblin\', and a bit too much rum if ye catch me meanin\'. Some words were said, some fists were thrown and... honestly it was quite a haze. I\'m not the most welcome pirate here after that.$b$bBut they took me stuff! These lyin\', dirty ol\'... ahem. Could ye just take this torch and... burn their belongin\'s? I\'d be grateful.', `QuestDescription`) WHERE `ID` = 45073;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSE', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Burn $1oa Blacksail Booty.', `LogDescription`) WHERE `ID` = 45079;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crysa\'s Flyers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Crysa in a pet battle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have obtained some of the most exotic species of carrion bird ever seen on Azeroth. Do you think you can stand up to them?', `QuestDescription`) WHERE `ID` = 45083;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trial of Valor: The Lost Army', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather 1000 Valarjar Soul Fragments within the Trial of Valor Raid.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While Helya\'s defeat is your primary objective, I require more of your aid. Helya has gained the ability to steal and corrupt the souls of my Valarjar. Her minions hold these souls, corrupting them. I am certain Helya herself hordes the greatest Valarjar souls to herself. You must recover these lost souls, then return them to me.nnDo this and I will reward you with blessed guard from the hall\'s armory.', `QuestDescription`) WHERE `ID` = 45088;
