UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Ride!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Lead the Four Horsemen in the battle against the Burning Legion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time has come, Deathlord! Our scouts have marked a large amassing of demons not far from here. Lead us to victory, and show these demons the power of undeath!', `QuestDescription`) WHERE `ID` = 45103;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Your Next Assignment...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Create interesting treasures and vignettes for patch 7.2!', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Congratulations on making it through the Intern Expo!nHowever, we\'re not through with you yet! You still have some ntime left, so what better use of your time than to make ntreasures and vignettes on the Broken Shore!', `QuestDescription`) WHERE `ID` = 45104;
