UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Everyone Loves a Good Fight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Compete in 5 Brawls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The note reads:nn"You shouldn\'t have blabbed about the brawlers, especially to those champions. Now that you have though, I suppose it\'s ok that they fight here on occasion, but you better prove yourself a true brawler first!"', `QuestDescription`) WHERE `ID` = 45111;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Your Next Assignment...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Create interesting treasures and vignettes for patch 7.2!', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Congratulations on making it through the Intern Expo!nHowever, we\'re not through with you yet! You still have some ntime left, so what better use of your time than to make ntreasures and vignettes on the Broken Shore!', `QuestDescription`) WHERE `ID` = 45116;
