UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Helya\'s Horn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill enemies in Helheim to empower Helya\'s Horn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, we need to bolster our army by any means necessary. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. nnThey are eternally bound to obey Helya even through her death. If we can call them using her voice, they will follow us instead! nnWe recovered Helya\'s Horn from her corpse. Empower it so you can call the kvaldir when we have need of them.', `QuestDescription`) WHERE `ID` = 45118;
