UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Elemental: The Folly of Levia Laurence', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ask around the city for information on Levia Laurence.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.nnLevia has disappeared, and I\'m gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands.nnShe was last seen at the Scribe\'s Sacellum. Ask around there and see if you can pick up her trail.nn|cFF660000Specialization: Elemental Shaman|r', `QuestDescription`) WHERE `ID` = 45123;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dabbling in the Demonic', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the correct three runes to help Rittsyn Flamescowl complete the spell to stabilize the portal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Levia must have used these runes to aid her ritual. Even if she is as powerful as Modera says, she was a novice in demonic magic, so the runes must have helped stabilize the portal.nnI\'ll need you to find out what runes need to be activated to recreate her ritual. There are several books on runic magic in this room, which she no doubt studied for her ritual.nnOnce you have activated the runes, I will complete the spell.', `QuestDescription`) WHERE `ID` = 45125;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unlikely Seduction', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Agatha.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mo... Modera sent you?nnNo...  you must... leave!  Agatha will be back any moment!nnSave... yourself...', `QuestDescription`) WHERE `ID` = 45126;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel-Crossed Lovers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Archmage Modera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That vile imp mother! If I wasn\'t so weakened I would dive down that pool and give her a piece of my mind!nn<Levia takes a deep breath to regain her composure.>nnIt\'s only a matter of time until Agatha can make use of the power she stole from me. We had best not be here when she does.', `QuestDescription`) WHERE `ID` = 45127;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Glorious Reunion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Aerylia, then report to Odyn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have done well, Battlelord $n. Let us return to Skyhold. Odyn will want to hear of your success here.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Aerylia', `PortraitGiverName`) WHERE `ID` = 45128;
