UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Judgment Awaits', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Highlord\'s Judgment to determine the worth of Silver Hand Recruits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our ongoing offensive within the Broken Shore has drawn the interest of many paladins who wish to fight under your leadership. Some are more worthy than others, but only you can be the judge of that.$B$BThe new recruits are lingering in the camp just outside the chapel, awaiting your judgment.', `QuestDescription`) WHERE `ID` = 45143;
