UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moonfang Family Relics', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover Moonfang family relics from within Shadowfen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As promised, here is the crescent key that will open my family\'s lockboxes, though nothing of value remains.nnI trust whatever you find you\'ll deliver to Delas? Our ancestor\'s things, whatever their worth, should remain in our family.', `QuestDescription`) WHERE `ID` = 45145;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Runic Reading', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Fel Blood from demons throughout the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is something curious about this scroll. It appears to be an empty page to the untrained eye, but I can see a shimmer of runes appear briefly when I hold it up to the light.nnAs with most demonic runes, I will need fel blood to undo the magic that\'s been used to conceal whatever message is within this scroll.', `QuestDescription`) WHERE `ID` = 45146;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felstone Destruction', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Felstone Pendant.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Delas\' mouth drops open as the scroll falls from her hands and onto the floor.>$B$BThis cannot be... the runes... they detail a pact between the Burning Legion and my ancestors. A dark deal that would grant my ancestors protection from demons in this life, but in return, their spirits would belong to the Legion.$B$BThis fel pendant is an embodiment of the pact, and cannot be removed once worn.$B$BQuickly, $n. You must use your artifact to destroy that cursed piece of jewelry!', `QuestDescription`) WHERE `ID` = 45147;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Oath Breaker', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Head to the Broken Shore and slay Oathbinder Zorak.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Many years ago I made a pact with a man I thought not to be unlike myself. His promise of protection seemed too good to be true, but it was a deal I was desperate to make.$B$BIt wasn\'t until I had signed in blood that the dreadlord Zorak revealed himself.$B$BAs long as he lives, my ancestors will remain bound to the Burning Legion, allowing our enemies to amass an army of unwilling soldiers.$B$BHead to the Broken Shore and slay Oathbinder Zorak. His death will break the hold he has over my ancestors.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Oathbinder Zorak', `PortraitGiverName`) WHERE `ID` = 45148;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ending the Crescent Curse', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free Felbound Spirits in Crescent Ruins by destroying their fel pendants.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must do whatever we can to break the curse that befalls my ancestors. nnThe Burning Legion have set up camp within the ruins that house our dead, ready to make good on the dreadful pact that was drafted so long ago.nnEach of my ancestor\'s is burdened with a pendant that binds them to their demonic overlords. It cannot be removed, but as you have shown, with enough power it can be destroyed. nnEnd the curse that plagues my ancestors and set their spirits free!', `QuestDescription`) WHERE `ID` = 45149;
