UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cubic Conundrum', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Mysterious Cube to Dariness the Learned in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<You find a mysterious cube. Its design is unfamiliar, but unmistakably ancient. nnThe cube\'s surface is inlaid with magical runes. Though inert, its properties may be worth investigating.nnPerhaps if you show it to Dariness the Learned in Dalaran, she could tell you more about it.>', `QuestDescription`) WHERE `ID` = 45159;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cubic Currents', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 300 Ancient Mana from Suramar', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'To determine this cube\'s purpose, we need to power it up. Hmm, I have an idea...$b$bThe Nightborne covet a substance you are no doubt familiar with called ancient mana. Should be just the thing for a relic this old. Gather a sufficient quantity and we\'ll attempt to get it working.$b$bBe careful in Suramar! It would be a shame if this curious cube were lost and became a memory once more.', `QuestDescription`) WHERE `ID` = 45160;
