UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Brought the Hammer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Brawler\'s Guild.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your champions found success in the brawl against the Warhammer Council. Bring this "token" to the Brawler\'s Guild as proof.', `QuestDescription`) WHERE `ID` = 45162;
