UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Battle!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Join and win in any battleground.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your champions have returned from exploring the battleground with a report detailing wild adventures and death-defying feats of strength and honor. In these ever shifting battles of conquest, more assistance is always required.nnWill you answer the call?', `QuestDescription`) WHERE `ID` = 45172;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Desperate Times', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Join and win in any battleground.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The conflict continues. As always, your assistance is needed in the great battlegrounds. Join the fray, defeat your enemies, and win glory for your faction.', `QuestDescription`) WHERE `ID` = 45173;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hunt for Illidan Stormrage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Allari the Souleater at Illidari Stand in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Allari the Souleater, an oracle of the Illidari, has been on the hunt for Illidan\'s soul for quite some time. She now believes that she has discovered its location and requires your assistance in its recovery.$B$BFind Allari at Illidari Stand in Azsuna and aid her in any way possible.$B$BIf Sargeras truly plans to use Illidan\'s body as a vessel for his own return then returning Illidan\'s soul to his body is integral in preventing the dark titan from returning to our world!', `QuestDescription`) WHERE `ID` = 45174;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Soul Prism of the Illidari', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Claim 40 Lingering Soul Fragments from the final bosses of Legion dungeons.$B$BHigher difficulty dungeons provide a greater chance and quantity of Lingering Soul Fragments.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alas, I will not burden you with the location of the master\'s soul just yet, $n. First we must craft a soul prism powerful enough to hold the master\'s boundless chaotic energies.$B$BTo do this I require lingering soul fragments from powerful beings found across this world. Bring me enough and I will craft a soul prism capable of holding the soul of the master - at least long enough to transfer into the naaru.', `QuestDescription`) WHERE `ID` = 45175;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Trial of Valor: The Once and Future Lord of Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Helya in the Trials of Valor raid and then use the Soul Prism of the Illidari to claim Illidan\'s Soul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While tracking the master\'s physical body proved challenging, we were able to locate it in the Nighthold of Suramar. Our intelligence reports that Gul\'dan is making final preparations to the Nightwell in order to use its power to usher the soul of Sargeras into Illidan\'s body.$B$BThe only way to stop that from happening is to put Illidan\'s own immortal soul back.$B$BTake the Soul Prism of the Illidari and venture to Helheim. Defeat Helya and use the prism on Illidan\'s soul! Return it to Light\'s Heart.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return the Soul Prism of the Illidari to Light\'s Heart in your Order Hall.', `QuestCompletionLog`) WHERE `ID` = 45176;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nighthold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Light\'s Heart to Khadgar at the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Illidan\'s soul rests safely within Light\'s Heart. Take this vessel and deliver it to Khadgar with the following instructions:$B$BWhen Gul\'dan attempts to tear the sky asunder and bring the dark titan into our world, call forth the power of this vessel and release Illidan\'s soul into his body.$B$BGo now, $n. We do not have much time. The dark ritual will begin soon.', `QuestDescription`) WHERE `ID` = 45177;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Contagion Containment', `LogTitle`) WHERE `ID` = 45178;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Win the Crowd', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Fight and win in the arena.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The letter invites you to fight in one of the greatest events in the history of Azeroth. The grand arena battles, where fighters win glory and honor, and everyone will remember their names. Or at least until the next season.', `QuestDescription`) WHERE `ID` = 45179;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Island of War', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the quests in Ashran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your champions return weary and wounded. They bear a banner which, when placed in your hands, gives you a sense of foreboding, but also a surge of battle lust. They report to you of an island named Ashran, where heroes are constantly waging a war. The tides push back and forth, each side feinting and thrusting, always trying to gain the upper hand.nnAshran needs your help, will you answer the call?', `QuestDescription`) WHERE `ID` = 45180;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.1 Class Hall - Special - PVP - PVP Repeated - Battleground - Tracking Quest', `LogTitle`) WHERE `ID` = 45181;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Frost: The Twisted Twin', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Karam Magespear at the Legerdemain Lounge in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.nnOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.nnFind Karam in the Legerdemain Lounge and see if you can lend a hand.nn|cFF660000Specialization: Frost Mage|r', `QuestDescription`) WHERE `ID` = 45182;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.1 Class Hall - Special - PVP - PVP Repeated - Ashran - Tracking Quest', `LogTitle`) WHERE `ID` = 45183;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.1 Class Hall - Special - PVP - PVP Repeated - Arena - Tracking Quest', `LogTitle`) WHERE `ID` = 45184;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Message from the Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the upper room in the Legerdemain Lounge for a clue to Raest Magespear\'s location.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know my brother has been misguided in the past, but I fear that he may have fallen in with an unthinkable evil. He recently began meeting in secret with a dark cult, hidden amongst the people of Dalaran.nnI travelled here to try to convince him of the error in his ways, but he would not be shaken from his course. Now, he has disappeared. nnWhen I last saw him, Raest was staying in a room upstairs. I was unable to find any clues there, but you might fare better.', `QuestDescription`) WHERE `ID` = 45185;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure 023 - Sargeras Tower 001', `LogTitle`) WHERE `ID` = 45186;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secrets in the Underbelly', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Question the Underbelly Lowlifes in the Underbelly to find more information about Raest Magespear\'s location.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So my brother has gone off to perform some ritual with these cultists? That explains why he left, but still not to where...nnWait! This letter mentions some of these "Nethersworn" cultists seeking reagents in the Underbelly. Perhaps we still may be able to find them if we hurry!', `QuestDescription`) WHERE `ID` = 45187;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wisdom of the Council', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Nethersworn Manifesto to Archmage Karlain in the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m sorry, $n, but I can\'t make heads nor tails of this. Riddles have never exactly been my strength.nnWe should take this cultist\'s writings to the archmage. Perhaps he could shed some light on this.', `QuestDescription`) WHERE `ID` = 45188;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure 024 - Fel River Rock', `LogTitle`) WHERE `ID` = 45189;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where it\'s Thinnest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Karam Magespear at Felbreach Hollow in the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Though I have never heard of this "Nethersworn" cult, what this manifesto speaks of can\'t be good.nnI do have a theory, however. The writing speaks of "the place its skin is thinnest." I think they might be referring to the place where the veil between Azeroth and the Twisting Nether is weakest - the Tomb of Sargeras. nnWith our forces having established a foothold at the Broken Shore, this would be an opportune time for Raest and his cultist allies to reach the tomb. I would suggest you stop them.', `QuestDescription`) WHERE `ID` = 45190;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure 025 - Night Elf Ruins 001', `LogTitle`) WHERE `ID` = 45191;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Runes of Rending', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bypass the wards in Felbreach Hollow and confront Raest Magespear.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My brother and his cultists are engaged in some kind of ritual at the far end of the cave. I tried to intervene, but my brother has left magical wards to block the way.nnIf you can find a way past them, we may be able to stop him in time!', `QuestDescription`) WHERE `ID` = 45192;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'One Step Behind', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Khadgar in the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It looks like Raest is out of our reach, but at least his cultists should prove less of a threat.nnWe should return to the Kirin Tor. They should be able to help us plan our next move.', `QuestDescription`) WHERE `ID` = 45193;
