UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nightborne Apprentice', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Arcanist Ryanna in the Crimson Thicket.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I would be happy to introduce you to my new apprentice if you do not mind traveling a bit. She is currently in the field keeping an eye on an enclave of Felborne resistance fighters who have sworn loyalty to the Legion. nnAs the first nightborne to join the Tirisgarde, I am sure she is eager to prove her skills!', `QuestDescription`) WHERE `ID` = 45207;
