UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Those Scrying Eyes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Inspect $1oa Duskwatch Scrying Orbs in the Terrace of Enlightenment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Until recently, Ly\'leth was sending magical messages to us regularly from within the Nighthold. She took care to hide these messages - only the most vigilant scryers could have detected them.nnThey could not be within the palace... too much interference from the Nightwell...nnOf course! The Terrace of Enlightenment! The Duskwatch must have set up a listening post there.nnCheck the scrying orbs for traces of Ly\'leth\'s messages. We must learn what she was trying to tell us!', `QuestDescription`) WHERE `ID` = 45209;
