UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Karazhan: Cubic Cynosure', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Mana Focus from the Mana Devourer within Karazhan', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Drat! The ancient mana doesn\'t seem to be working. I need to think the problem through, focus and...$b$bWait, that\'s it! Focus! We need to focus the energy of the ancient mana to activate the cube.$b$bI\'ve heard tell of a mana wyrm in Karazhan with the means to focus its powers. Might be just what we need!$b$bWatch out, though. My sources tell me this wyrm is humongous!', `QuestDescription`) WHERE `ID` = 45238;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cubic Coalescing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Activate the Mysterious Cube', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Success! The cube\'s magic has been restored! I\'m excited to see what it does!nnSince you did all the legwork, you should have the honor of activating it. Care to give it a try?', `QuestDescription`) WHERE `ID` = 45239;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Making Preparations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Death Gate near Highlord Darion Mograine, then meet Minerva Ravensorrow.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deathlord, we have uncovered an heirloom of great significance and power. Rimefang\'s harness has appeared in Icecrown Citadel. We must obtain it, rather than let it fall into the hands of others.$b$bI assume you\'d like to retrieve the harness personally? We\'ve sent one of our own, Minerva Ravensorrow, ahead to scout. You\'ve met her before, yes? She has impressed us greatly, and we believe she can become quite powerful under your tutelage.$b$bI will open a death gate for you. It is best you meet her there.', `QuestDescription`) WHERE `ID` = 45240;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'On Daumyr\'s Wings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ride Daumyr to the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time is nigh, $p. With these new dragons in our army, we are prepared for our assault on the Broken Shore. A large detachment of demons have appeared near one of our camps, and there are far too many of them for any of our allies to overcome.$b$bWho better to defeat these demons than those without fear of death? Those with quite the large secret weapon?$b$bTake Daumyr. We will meet you there.', `QuestDescription`) WHERE `ID` = 45243;
