UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Redundancy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Aethas on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A construct progenitor? What a creative solution to our problem!nnWe probably could channel Kathra\'natir\'s power without releasing him now, but I want to add another layer of protection before we try, just in case. I will not have anyone accusing me of subterfuge!nnMeet me on the Broken Shore when you are ready.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Aethas on the Broken Shore.', `QuestCompletionLog`) WHERE `ID` = 45251;
