UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Insurrection: As Strong As Our Will', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with First Arcanist Thalyssra in Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In the wake of Elisande\'s attack, the need is stronger than ever to add to the ranks of the Nightfallen rebellion.$b$bPlans are in motion that may help with this in an unconventional way.$b$BReport to First Arcanist Thalyssra in Shal\'Aran for more details.', `QuestDescription`) WHERE `ID` = 45285;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure 051 - Death Knight Overhang', `LogTitle`) WHERE `ID` = 45286;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Insurrection: Breaking the Nighthold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with First Arcanist Thalyssra in Shal\'Aran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'First Arcanist Thalyssra sends word that her forces are ready. It is time for you to lead the attack against the Nighthold.$b$bReport to Shal\'Aran in Suramar for details.', `QuestDescription`) WHERE `ID` = 45287;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure 052 - Green Ritual Chamber', `LogTitle`) WHERE `ID` = 45288;
