UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Karazhan: Book Wyrms', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Clean up the Karazhan Library.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My incorporeal condition has allowed me to enter the tower safely for the first time. I must say, it\'s a bit of a shambles in there!$b$bI could use some help tackling my cleaning checklist. We should start with the library. All those musty tomes are bound to attract mana wyrms!$b$bPlease shelve any books that have fallen to the floor, or worse, taken flight. And if you find mana wyrms nibbling at the pages... step on them!', `QuestDescription`) WHERE `ID` = 45291;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Karazhan: Rebooting the Cleaner', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Disable the Curator and find the Box of Spare Motivator Crystals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Guardian Medivh created the Curator to watch over Karazhan, but I fear the unit is behaving erratically. Prolonged periods of operation may have caused a malfunction.$B$BPlease go up to the Menagerie and disable the Curator. Also, search the area for a box of spare motivator crystals and return to me.$b$bEven with my basic knowledge I should be able to replace its motivator, and we can enlist the Curator\'s help in cleaning up the tower.', `QuestDescription`) WHERE `ID` = 45292;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Karazhan: New Shoes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the Box of \'New\' Horseshoes to Koren the Blacksmith in Karazhan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thus far my Karazhan cleanup project hasn\'t exactly been a rousing success. Time to try something new.$B$BNew, as in new shoes... horseshoes, that is! A box of horseshoes was left outside the tower. It\'s a problem finding a delivery person willing to set foot inside... mortality rates being what they are.$B$BIf you would, grab the crate and take it to Koren in the stables. Just be careful passing Attumen. The huntsman doesn\'t take kindly to outsiders.', `QuestDescription`) WHERE `ID` = 45293;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Karazhan: High Stress Hiatus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Darius soothe the old casts egos by finding a Positive Review amongst the audience members to simmer tensions between Romulo and Julianne, stealing a Bouquet of Roses from one of the new acts for Tinhead\'s vanity and finding where the understudy stashed Little Red\'s cape in the Chess room.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The new plays in the opera house have been well received by everyone... except cast members of the older shows. Egos are bruised and tensions are running high!$B$BRomulo and Julianne are ready to poison each other.$B$BTinhead is rusting with tears over his lack of adoration.$B$BLittle Red\'s cape was stolen by a disgruntled understudy, who ran off to play chess of all things.$B$BActors, am I right? We need them ready to perform in case the audience demands a revival. Please, help me calm their nerves!', `QuestDescription`) WHERE `ID` = 45294;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Karazhan: Clearing Out the Cobwebs', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Clean out spiders from the Servant\'s Quarters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I admit it... even as a spirit, I am deathly afraid of spiders. All those legs! Dripping fangs! Sticky webs coming out of their...$b$b<Darius does a squirming sort of shimmy that is uncomfortable to watch.>$b$bI\'m sure a world-saving hero like you doesn\'t mind them, though. Which is good, since a whole brood of spiders has taken over the Servant\'s Quarters.$b$bYou\'ll handle this, right? If you don\'t get them all, they\'ll keep multiplying.', `QuestDescription`) WHERE `ID` = 45295;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'No Bones About It', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Charred Bone Fragments to Darius.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Charred Bone Fragments still smolder with ancient power. Darius would be extremely interested in examining them and hearing of your defeat of Nightbane.', `QuestDescription`) WHERE `ID` = 45296;
