UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Taking Charge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Kyra Lightblade and choose to fly down to Mardum.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mardum has been quiet for months. I wonder why the Legion is attacking us now? Could be in retaliation for destroying their battleship on the Broken Shore...nnWe had better head down ourselves and save the day, don\'t you agree?', `QuestDescription`) WHERE `ID` = 45301;
