UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stabilizing Suramar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 world quests in Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Elisande\'s plan has backfired. She thought to stamp out our rebellion by making an example of the Waning Crescent. nnInstead, she ignited the flame of the shal\'dorei better than I ever could.nnWe must maintain a cohesive campaign against Elisande and the Legion by fighting them in every corner of Suramar. nnShow the people that there is still hope - that there are still heroes willing to fight for them!', `QuestDescription`) WHERE `ID` = 45316;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fighting on All Fronts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 5 missions from your Order Hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We are nearly ready to siege the gates. Your efforts here have been monumental, $n.nnBut let us not forget that you are also the $ct. Your forces rely on you to command them. No single person can stand against the Legion.nnContinue your duty. Guide the $cs of Azeroth, and victory will be assured.', `QuestDescription`) WHERE `ID` = 45317;
