UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Operation: Portals', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Close 3 Legion portals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is a serious invasion, but nothing a Slayer like you can\'t handle. Time to put those weapons to work!', `QuestDescription`) WHERE `ID` = 45329;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scouting Party', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Lady S\'theno and 10 Illidari Scouts.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We will have our work cut out for us finding the missing scouts and Lady S\'theno. I suspect that one does not wish to be found.nnDo your best, $n!', `QuestDescription`) WHERE `ID` = 45330;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to Acherus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Highlord Darion Mograine in Acherus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You\'ve grown a lot since we last met, $n. Now that we have the harness, let\'s see if Mograine has a plan to use it.', `QuestDescription`) WHERE `ID` = 45331;
