UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fate of the Nightborne', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Oculeth and meet Thalyssra in the Nighthold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Shortly after your victorious return from the Nighthold, urgent business took Thalyssra back to the palace.$b$bShe has requested that you meet her there.$b$bSpeak to me when you are prepared to join her.', `QuestDescription`) WHERE `ID` = 45372;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Treasure Master Iks\'reeged', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa Felwing Devourers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<TEMP> Board the ship then kill fel bats.', `QuestDescription`) WHERE `ID` = 45379;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Talisman of the Shal\'dorei', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Echoes of Time from Elisande in The Nighthold on Normal Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman\'s power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell\'s power, we could locate the talisman and end this foolish war...', `QuestDescription`) WHERE `ID` = 45381;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Talisman of the Shal\'dorei', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Echoes of Time from Elisande in The Nighthold on Heroic Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman\'s power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell\'s power, we could locate the talisman and end this foolish war...', `QuestDescription`) WHERE `ID` = 45382;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Talisman of the Shal\'dorei', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Echoes of Time from Elisande in The Nighthold on Mythic Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman\'s power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell\'s power, we could locate the talisman and end this foolish war...', `QuestDescription`) WHERE `ID` = 45383;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Must be Prepared!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Lady S\'theno at the Illidari Camp on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion ships are gone, for now. It\'s only a matter of time before they attack again, and we must be prepared.nnWe need to get going on repairs immediately! Lady S\'theno took the lead on the search for parts. That one will do anything to remain on solid ground, ha! nnShe is waiting for you on the Broken Shore.', `QuestDescription`) WHERE `ID` = 45385;
