UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Memento', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Velonara\'s spare hood to Death Hunter Moorgoth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The flowers were... a nice gesture.$b$b<Velonara sniffs one of the black roses.>$b$bI have a spare hood. Nothing fancy, but perhaps Moorgoth would like to have it.$b$bJust don\'t let him get his hopes up or anything. I\'m merely repaying a kindness.$b$bI would appreciate it if you kept all this between us. Giving presents to admirers falls a bit outside the dark ranger rules of conduct.', `QuestDescription`) WHERE `ID` = 45392;
