UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Harnessing Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Andjor Dragontamer and retrieve Rimefang\'s Harness.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These fools are using the power of Rimefang\'s harness to subjugate the frost wyrms. Their leader, Andjor, sits inside on the back of the broodmother and mocks us.$b$bHe should breathe no longer.', `QuestDescription`) WHERE `ID` = 45398;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Severing the Sveldrek', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill and raise $1oa Sveldrek vrykul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So here\'s the order of things, as far as I\'ve been told. Mortal walks into Icecrown. Mortal is brutally defeated. Mortal gets raised as Scourge.$b$bThese fools can\'t expect to trounce in here, do whatever they want, and leave without any consequence. Time to make them truly as mindless as they act.', `QuestDescription`) WHERE `ID` = 45399;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Panic at the Brewery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Almai find Brewmaster Blanche and defend Stormstout Brewery.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We were not prepared for a surprise attack. I fear Brewmaster Blanche has been captured, or worse...nnPlease help me, Grandmaster!', `QuestDescription`) WHERE `ID` = 45404;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Breaching the Sanctum', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Oculeth to start the assault.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area.$b$bTake these telemancy orbs. If you find you need support, use them to summon Withered.$b$bWe must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.', `QuestDescription`) WHERE `ID` = 45405;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Storm\'s Fury', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Burning Legion forces within Shield\'s Rest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'No longer do we have time to prepare, the moment of action is upon us!nnCome with me, little one. With you guiding my aim we shall cleanse this isle by thunder and lightning!', `QuestDescription`) WHERE `ID` = 45406;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Protection: Aid of the Illidari', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Kor\'vas Bloodthorn in the streets of Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thankfully, we are not quite alone in uncovering the Legion\'s plots to infiltrate the city.$B$BKor\'vas Bloodthorn of the Illidari has taken to patrolling the city streets on her own to find the source behind the recent attacks.$B$BI do not entirely trust these \'demon hunters\', but they have at least proved adept at their namesake. I suggest you find her and see what she has uncovered before the Legion strikes once more.nn|cFF660000Specialization: Protection Warrior|r', `QuestDescription`) WHERE `ID` = 45412;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gathering Information', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Question citizens in the Bank of Dalaran to find out what was stolen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion has sent one demon after another to try to break into the Kirin Tor vaults in the city, but we don\'t know what they\'re after.$B$BLooks like they finally made it in.$B$BWe need to find out what was taken, and quickly, before they get a chance to put whatever it is to use.$B$BProbe any survivors for information - I\'ll use my spectral sight to make sure there aren\'t still any straggling demons lurking about.', `QuestDescription`) WHERE `ID` = 45413;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Confirming Suspicions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Prophet Velen in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That heart is the last remaining piece of Highlord Kruul - once one of the Legion\'s best warlords.$B$BMany years ago Kruul\'s armies nearly descended upon the Dark Portal to crush the Azerothian assault on Outland. We Illidari intercepted before he could strike.$B$BI fear that the Legion aims to use the heart to hasten Kruul\'s resurrection in the nether. We must find the Prophet Velen at once - only he can tell us for sure.', `QuestDescription`) WHERE `ID` = 45414;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Between Worlds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Establish a portal to the Twisting Nether at the Stair of Destiny in Outland.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Kruul boasts damnation, but his power has not yet fully manifested. His minions have taken his heart to hasten his rebirth in the nether.$B$BWe do not have much time.$B$BGo to the place of Kruul\'s fall at the Stair of Destiny in desolate Outland, where the link to his soul is strongest. There you must pry open the way to his realm.$B$BI must prepare for the battle to come. Good luck, champion.', `QuestDescription`) WHERE `ID` = 45415;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Highlord\'s Return', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Highlord Kruul in the Twisting Nether. Speak with War Councilor Victoria to get there.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have a missive for you from Kor\'vas, as well as instructions for getting you there.$b$bI can teleport you to them to begin the fight, but you will need some Nethershards to force your way into the Twisting Nether.$b$bWhen you have enough, speak with me and you can begin.', `QuestDescription`) WHERE `ID` = 45416;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nighthold: Lord of the Shadow Council', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Gul\'dan in The Nighthold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we speak, Gul\'dan is using the Nightwell\'s power to pull Sargeras into our world.nnGather your companions and fight your way to the top of The Nighthold.nnI will prepare Light\'s Heart and join you when the time is right.nnTogether, we will put an end to Gul\'dan once and for all.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Gul\'dan', `PortraitGiverName`) WHERE `ID` = 45417;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Eye of Aman\'Thul', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Aid Khadgar in transporting the Eye of Aman\'Thul.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The battle is won, but the war is far from over.nnIn order to stem the tide of demons flooding into Azeroth, we must use the Pillars of Creation to seal the Tomb of Sargeras.nn<Khadgar peers down at the Eye of Aman\'Thul.>nnThat... might be difficult to carry.nnPerhaps I can use the power of the Eye itself to teleport it to Dalaran. I suppose there is only one way to find out!', `QuestDescription`) WHERE `ID` = 45420;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vignette: Dirge of Asgrim', `LogTitle`) WHERE `ID` = 45421;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Edict of the God-King', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat God-King Skovald in Halls of Valor on Mythic difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our scouts send troubling reports from Stormheim.$b$bGod-King Skovald has received a new directive from Gul\'dan. In response, Skovald\'s forces have stepped up their attacks.$b$bWe must know the details of Gul\'dan\'s message, $n.$b$bDespite his new orders, the god-king remains obsessed with the titan keeper Odyn. Intercept Skovald in the Halls of Valor and you may determine what his Legion masters have demanded of him.', `QuestDescription`) WHERE `ID` = 45422;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wailing Critters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Budding Everliving Spore in Wailing Caverns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m glad you\'re here, $n.$B$BTiny wails have been heard in the caverns for some time since Naralex was awakened. At first, we suspected that some deviate critters had survived. Upon further investigation, we found them to be growing and multiplying beyond our wildest expectations. The corpse of Verdan the Everliving may have something to do with it, we\'re not sure. That\'s why we\'re sending you in.$B$BI\'ve also seen suspicious footprints leading into the caverns recently. We may not be alone, be careful.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Muyani at the Wailing Caverns in Northern Barrens.', `QuestCompletionLog`) WHERE `ID` = 45423;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Grovebound', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Rensar Greathoof in the Dreamgrove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now THAT was some good stuff right there. Now that we\'ve taken out the commander, the druids and the ancients should be safe for a while. Revenge was an added bonus.$b$bWe should get back to Rensar and tell him what we accomplished.', `QuestDescription`) WHERE `ID` = 45425;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nature\'s Advance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Rensar Greathoof in the Dreamgrove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, you must return to the Dreamgrove and bring the news of my attack. Tell the other druids that aggressions such as this will continue against us unless we find a way to stop the Legion.$b$bI thank you for the aid. I feel the fel energies leaving my veins, though it may take some time.', `QuestDescription`) WHERE `ID` = 45426;
