UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Brewing Situation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Direct the Stormstout Brewers to distribute Celebration Brew to the temple balcony, in front of the Laughing Crane, and near the troop training grounds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, Grandmaster. I\'m an expert at producing tricky brews, and Almai and I have been working with Stormstout Brewery to craft Storm Brew for the order. nnIn fact, we have already begun production!nnThat calls for a party, don\'t you think? We brought enough of my prized Celebration Brew for everyone!', `QuestDescription`) WHERE `ID` = 45440;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Not Felling Well', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Blanche\'s Still and then give the Curative Brew to 8 Fel-Poisoned Initiates.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Let\'s see... Yseralline Seed for healing, Bruiseweed for curing poison, and Elemental Earth for disease resistance. Oh and just a touch of ground Felwort for attunement. nnYes, I think this will counteract the Legion\'s poison. It will probably taste terrible, but what medicine doesn\'t?nnHurry, Grandmaster $n. Our most stricken friends don\'t have much time left.', `QuestDescription`) WHERE `ID` = 45442;
