UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Alchemist Korlya', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Alchemist Korlya.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The zealots within the Garrison of the Fel are led by Alchemist Korlya. It seems likely that\'s the Felskorn Brewmaster Blanche observed poisoning our brew.nnPlease kill her.', `QuestDescription`) WHERE `ID` = 45449;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Storming the Legion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Tak-tak to travel to the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I did my best to fight the demons off, but there were too many even for my skill...nnAs I lay dying, I overheard the dreadlord commanding a Felskorn alchemist to contaminate my brew and then return to the Broken Shore. nnIf you could acquire some of the poison, I\'m sure we can concoct an antidote!', `QuestDescription`) WHERE `ID` = 45459;
