UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Reluctant Queen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Sigryn before Eyir in Skold-Ashil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Wait, how is it you know about my parentage? Be careful what you say around here, there are those who would hunt me down if they knew my bloodline.nnI don\'t know who you are, nor do I believe I\'m part of any prophecy. However, if you seek to undo the damage my father has wrought on the Tideskorn, then I feel obliged to assist you.nnMeet me in Valdisdall, $c. From there we can make our way to Skold-Ashil and request an audience with Eyir. Perhaps she can shed some light on this prophecy.', `QuestDescription`) WHERE `ID` = 45486;
