UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Let Sleeping Dogs Lie', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Save Goldrinn from the Stormrage Barrow Dens.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You see those big eredar guys? That\'s the barrow that Goldrinn is in! I don\'t know what the Legion is doing to him in there, but I\'m sure we don\'t want them to succeed.$b$bLet\'s get in there and save Goldrinn!', `QuestDescription`) WHERE `ID` = 45498;
