UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Silence the Bonespeakers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Runeseer Faljar in Haustvald.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Sigryn\'s claim to the throne will be challenged by two rivals - Runeseer Faljar of the Bonespeakers and Jarl Velbrand of the Drekirjar.nnI would begin in Haustvald with the Runeseer. He was a close ally of Skovald and is a powerful mystic. With the Bonespeakers at his charge, he would prove a staunch opponent if he cannot be made to yield.nnGo now, and claim your destiny in the name of the Valkyra!', `QuestDescription`) WHERE `ID` = 45522;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Tame the Drekirjar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Jarl Velbrand in Hrydshal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Bonespeaker\'s words trouble me, outsider. The darkness he speaks of, Skovald\'s fel curse, could he have passed it onto me somehow?nnNo, it cannot be so. The Runeseer must be mistaken...nnCome, the next challenger awaits. I will no doubt need your assistance bringing him to heel as well.', `QuestDescription`) WHERE `ID` = 45523;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Forgotten Heir', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Torvald in Vrekt.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My brother... lives?nnThe last time I saw him, the assassins were closing in on him. I can\'t imagine how he defeated them...nnWe should travel to Vrekt. I would look upon my brother with my own eyes.', `QuestDescription`) WHERE `ID` = 45524;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unanswered Questions', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Join Sigryn at the Vault of Eyir in Skold-Ashil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What is done, is done. There are none left to challenge the throne of the Tideskorn. nnMy brother\'s words still haunt me, though. If Eyir knows who ordered my family killed, I deserve to know it.nnCome, let us return.', `QuestDescription`) WHERE `ID` = 45525;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The God-Queen\'s Fury', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with War Councilor Victoria to be teleported to Sigryn\'s location and defeat her.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$ct, the Kirin Tor have found a way to get you into the Halls of Valor to pursue the God-King\'s heir. Archmage Khadgar has asked me to stress upon you the importance of stopping Sigryn, as the prophecies hint that she may still be the key to uniting the Tideskorn against the Legion.nnIt will require an incredible amount of energy to teleport you directly to the Halls, so be sure that you are prepared. It may be some time before we can send you again.nnSpeak to me when you are ready to proceed.', `QuestDescription`) WHERE `ID` = 45526;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Eyir\'s Forgiveness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness Eyir\'s judgment of Sigryn in the Vault of Eyir in Skold-Ashil.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m sorry for everything I\'ve put you through, outsider. After my actions here, I fear all of this may have been in vain.nnCome with me back to Skold-Ashil. There I will accept whatever judgment Eyir  deems fit of me.', `QuestDescription`) WHERE `ID` = 45527;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Befouled Barrows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Close $1oa Legion Portals in the Stormrage Barrow Dens.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You were taking too long, so I took the liberty to scout out the barrows in advance. The Legion has set up portals, pulling more and more demons through them by the second. We need to shut them down so we can save Goldrinn!$b$bI\'m not sure my usual methods are going to do much to take them down, but I think you can do it! I think some nice vine-work is in order.', `QuestDescription`) WHERE `ID` = 45528;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Creeping Fel', `LogTitle`) WHERE `ID` = 45531;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mother\'s Orders', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Mother Mirenda.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That big ugly thing looks like it\'s leading the attack here. Let\'s take her down!', `QuestDescription`) WHERE `ID` = 45532;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Legion Dungeon Reward Quest', `LogTitle`) WHERE `ID` = 45533;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Common Enemy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Khadgar in the Violet Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have one more request to ask of you, outsider.nnReturn to your leaders and report to them what transpired here.  Though your people may never truly be allies with the Tideskorn, know that we have a common enemy - one which my people will fight to the last vrykul. nnWhen the time comes, I hope to see you on the battlefield.', `QuestDescription`) WHERE `ID` = 45534;
