UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pet Battle Challenge: Wailing Caverns', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Budding Everliving Spore in Wailing Caverns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The deviate critters of the Wailing Caverns continue to flourish in the damp darkness, but I\'ve been doing my best to keep their numbers down.$B$BI\'ve found a few pets and supplies while clearing out the caverns, I might be willing to part with a sack of supplies if you can beat my best run.$B$BYou\'ll have to clear out the cavern without healing or reviving any of your pets to best me. Good luck!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Muyani at the Wailing Caverns in Northern Barrens.', `QuestCompletionLog`) WHERE `ID` = 45539;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Call from the Caverns', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Muyani in the skull-shaped rock above Wailing Caverns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh, good, I\'m glad you stopped by. We\'ve heard disturbing rumors of corruption continuing to flourish in the Wailing Caverns. You seem like just the right person to investigate.nnSince Naralex\'s awakening, one of his disciples has been watching over the area to ensure that deviate creatures remain in check. She is the one that has been sending us these dire warnings.nnMeet up with her in the eye of the skull-shaped rock above Wailing Caverns and see if you can help her handle this situation.', `QuestDescription`) WHERE `ID` = 45540;
