UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Barrel Toss', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Storm Brew to destroy 5 Fel Brew Spreaders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion is defending the Felskorn lair with fel emitters. Fortunately we have Storm Brew to spare, so there should be plenty available with which to destroy them. nnTake this barrel, throw it at the spreaders, and watch them go BOOM!', `QuestDescription`) WHERE `ID` = 45545;
