UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Devastating Effects', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate Suramar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Burning Legion will not rest until they have destroyed everything and everyone. Their presence here has had a devastating effect on our lands, and now it seems our wildlife as well. nnI have heard numerous reports of sickly animals in the thicket that surrounds the demon-infested city of Suramar. nnMake your way there and see if the rumors are true.', `QuestDescription`) WHERE `ID` = 45551;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Soothing Wounds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Manaroot that is foraged from leylines within the Crimson Thicket to soothe D\'Bynn\'s wounds.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<D\'Bynn\'s injuries prevent him from moving.>nnPerhaps you can forage something nearby that will soothe the manasaber\'s wounds?', `QuestDescription`) WHERE `ID` = 45552;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Nighthuntress Beckons', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ride D\'Bynn and let him lead you to Nighthuntress Syrene\'s location.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<D\'Bynn becomes alert at the sound of his master\'s voice. Using his muzzle, he nudges your hand with a sense of urgency, inviting you to hop on his back.>', `QuestDescription`) WHERE `ID` = 45553;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Taking Control', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Torturer Relyn and use his Control Orb to free Nighthuntress Syrene.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve been withering away in this cage, prisoner to a wretch called Reyln.nnHe leads a group of nightborne that are using fel magic to corrupt and control the native wildlife.nnThe Burning Legion\'s reach has already spread too far for my liking.nnKill him and recover his control orb, so I can be released from this arcane prison!', `QuestDescription`) WHERE `ID` = 45554;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felbound Beasts', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Nightborne Trappers and free Felbound beasts.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So Reyln is taking orders from Lexera? Why am I not surprised. She seemed far too comfortable with the demons who infested our city.nnWe cannot let her succeed in corrupting Suramar\'s wildlife. I swore to protect the city of Suramar from all enemies, even those within its walls.nnIf you can deal with her trappers, I will do my best to track Nighthuntress Lexera down.', `QuestDescription`) WHERE `ID` = 45555;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ready to Strike', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Nighthuntress Syrenne on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I followed one of the trappers, who unknowingly led me to the Broken Shore. nnLexera was there, surrounded by an army of demons and loyal nightborne.nnI wasn\'t able to get close, but from what I could tell, she and her army of trappers are taming the fel-corrupted beasts.nnIt is an abomination of nature, and she must be stopped!nnMeet me on the Broken Shore and be ready to strike. I will gather additional manaroot. I have a feeling we\'ll need it.', `QuestDescription`) WHERE `ID` = 45556;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unnatural Consequences', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Nighthuntress Lexera.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lexera and her trappers have taken over the valley.nnShe is stronger than she looks, $n, and she fights with the strength of a dreadlord. Do not go in unprepared. nnI can handle these demons. Go, find Lexera, and make her feel the consequences of her unnatural endeavors.', `QuestDescription`) WHERE `ID` = 45557;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Behind Enemy Portals', `LogTitle`) WHERE `ID` = 45559;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Destruction: Rumblings Near Feltotem', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Navarrogg at the Misty Coast in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later.$b$bThe drogbar chieftain, Navarrogg, is handling this personally and we\'d like you to meet him near the Feltotem village.nn|cFF660000Specialization: Destruction Warlock|r', `QuestDescription`) WHERE `ID` = 45560;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seek Me Out', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Look for Maximillian of Northshire in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The letter from Maximillian is written on something which looks to be torn off a ship\'s sail. Included are directions to the beach in northern Highmountain.', `QuestDescription`) WHERE `ID` = 45561;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Kneel and Be Squired!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kneel before Maximillian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You must kneel before me if we are to begin our journey together once more. Kneel, squire, and be squired!', `QuestDescription`) WHERE `ID` = 45562;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Shrouded Coin', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Shrouded Timewarped Coin to Mistweaver Xia on the Timeless Isle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A swirling mist envelops the coin and it begins to float above your hand. The mist briefly parts to reveal a shiny new coin, yet in the next instant the coin appears worn from years of exchange. As the coin settles back in to your hand, visions of jungles and mist shrouded peaks waft into your mind, and through the vision you recognize the four Celestials gathered in the courtyard of an island.', `QuestDescription`) WHERE `ID` = 45563;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Burning Birds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Fel Infusing totems.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Feltotem are experimenting on these falcosaurs! They didn\'t get the results that they wanted and have carelessly left their experiments lying around to further poison the animals.$b$bWe should collect their leftover totems to prevent further corruption and to find out what they were doing.', `QuestDescription`) WHERE `ID` = 45564;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Further Training', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete Maximillian\'s quests and slay "demons" to earn the rank of Squire, First Class.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The journey here was perilous, squire. It was fraught with danger. Storms, demons, storm demons... I shudder at the memory. Of course, I overcame all such dangers at great loss to my person. This is where I need your assistance.nnYou must venture forth--nay, sally forth, and recover my armor, my weapon, and of course my grand steed. Once you have successfully completed these tasks three, will you be promoted to Squire, First Class!', `QuestDescription`) WHERE `ID` = 45565;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Knight\'s Belongings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Fetch Maximillian\'s armor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Amidst the squalls and the crashing waves, my mighty ship swayed and tumbled. Lesser knights would have trembled in terror, frozen stiff. Not me! Nay! Heroically, I stripped my armor off my back and stored it safely in my sack. nnWhy did I strip down to these simple undergarments, you ask? Only an ignorant squire would. I was wary of sinking to the bottom should my ship fall foul of course! Ha ha! nnUnfortunately, the sacks of armor were thrown overboard by the waves.', `QuestDescription`) WHERE `ID` = 45566;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'My Kingdom for a Horse', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return Pimento.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh, woe is me! Soon after making landfall I began exploring, riding my trusty steed Pimento into the heart of a demon infested village to the north. While performing my investigations, I tied Pimento up to go further on foot, only to return and discover a powerful demon had captured her! There he was, riding her like she was his own. Please find her and send her back to me.', `QuestDescription`) WHERE `ID` = 45567;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'They Stole Excaliberto!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Excaliberto and return it to Maximillian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I was scouting the nearby demon village when I was attacked. They took my artifact! Of course, if I leave here, the shore will be undefended. The nearby demons have it. Go, slay them and bring it back to me!', `QuestDescription`) WHERE `ID` = 45568;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In Safer Hands', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Focusing Iris to Archmage Kalec in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is still the matter of the Focusing Iris. Please return it to  your Kirin Tor friends, with my apologies.nnAs for myself, I think I\'m done chasing artifacts for a while. One possession by immortal shadowy evil is enough for me, thank you.', `QuestDescription`) WHERE `ID` = 45570;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Bit of Espionage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Aludane Whitecloud in Krasus\' Landing for a flight to Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the gunpowder in tow, it\'s time to move on to our next plan. Meet us on the Broken Shore. $b$bYou can get a flight directly to our next location from Krasus\' Landing. We will meet you there, $ct.', `QuestDescription`) WHERE `ID` = 45571;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Holding Our Ground', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Repel the Legion threat from Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Though we anticipated a strong Legion presence, our attacks on their camps have angered their forces even further than anticipated. Our forces rally on both land and in the skies above Thunder Totem in an attempt to regain our footing.nnDo what you can to reduce their forces. Once we\'ve secured Thunder Totem we\'ll begin our plan for a final attack.', `QuestDescription`) WHERE `ID` = 45572;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa demons, then reach the top of the ramp.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here we are, $ct. On this island is a cavern full of exceptionally powerful demons and their leaders. If our plan succeeds, these demons will be... "blown to smithereens", as Tethys so nicely put it.$b$bThere\'s no time to explain the plan in full right now, but Tess has agreed to walk you through it. First you must get up to the top of this ramp. Slaughter a few on your way.', `QuestDescription`) WHERE `ID` = 45573;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel Ingredients', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Acquire 5 Vials of Liquid Felflame, 3 Flasks of Fel Blood, and 3 pinches of Demonic Ash.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our scouts have located a Felskorn encampment within the Garrison of the Fel. We will need as many samples of fel poison as we can find if we are to concoct a cure for our stricken monks.nnTake samples of anything that looks remotely useful!', `QuestDescription`) WHERE `ID` = 45574;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Village of the Corruptors', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Feltotem Infusers in Feltotem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Feltotem continue to create these totems for further "experiments". Let us deal with these infusers in the traditional manner.nnTheir deaths will right a great wrong and provide clues as to their ultimate goal.', `QuestDescription`) WHERE `ID` = 45575;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rise Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa demons, then reach the top of the ramp.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here we are, $ct. On this island is a cavern full of exceptionally powerful demons and their leaders. If our plan succeeds, these demons will be... "blown to smithereens", as Tethys so nicely put it.$b$bThere\'s no time to explain the plan in full right now, but Lilian has agreed to walk you through it. First you must get up to the top of this ramp. Slaughter a few on your way.', `QuestDescription`) WHERE `ID` = 45576;
