UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shield Amplification', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Nightborne Soulstone on defeated Felborne within the Weeping Terrace.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It will not hurt to reinforce the Nightborne Soulstone\'s shield just a bit more, and to do that we must infuse it with energy. nnRyanna has assured me that fel essence will work beautifully for our needs. Yes - this method IS rather distasteful. However as the sin\'dorei well know, desperate times call for desperate measures.nnIt is as simple as this: we have an urgent need for magical energy, and our enemies possess it in abundance. nnDo what must be done.', `QuestDescription`) WHERE `ID` = 45586;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Feltotem Menace', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and deal with Tugar Bloodtotem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If I had known Tugar was alive and behind this I would\'ve alerted you sooner! He is a hateful creature, and an easy recruit to the Legion\'s cause.$b$bIf he is truly successful with his fel experiments we need to stop him now. He is taunting us from up there. Let\'s go!', `QuestDescription`) WHERE `ID` = 45587;
