UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lady Remor\'za', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Lady Remor\'za.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our allies reported a coven of extremely powerful Felborne abjurers occupying the Weeping Terrace. nnTheir leader, Lady Remor\'za, and her followers are specialists in ancient nightborne magic and can become nearly invincible to attacks. nnHowever, as mages, we should be able to defeat them using Spellsteal. Let us show them the power of the Tirisgarde!', `QuestDescription`) WHERE `ID` = 45614;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Finders Keepers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Sweep up $oa piles of Arcane Dust in the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Would you look at this place? It\'s a mess! Everywhere you look there\'s just pile after pile of arcane dust!$B$B<Akazamzarak smiles broadly.>$B$BThese poor saps don\'t realize what that stuff\'s worth!$B$BI tell ya what, if you help me summon up some brooms to collect this powdered gold, I\'ll split the profits with you 80/20.', `QuestDescription`) WHERE `ID` = 45615;
