UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Feltotem\'s Fall', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Tugar Bloodtotem. Speak with War Councilor Victoria, she will teleport you to Navarrogg to begin.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our Highmountain contact, Navarrogg, reports that Tugar Bloodtotem has finally resurfaced.$b$bHe\'s sent a message crystal along with some instructions for me.$b$bI can teleport you to Navarrogg and he will take you to Tugar\'s location, but there is one problem.$b$bNavarrogg requires additional magical power to fend off Tugar\'s fel magicks. You will need some Nethershards before you go.', `QuestDescription`) WHERE `ID` = 45627;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'This Time, Leave a Trail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rappel down into the cave, then follow Tess\'s instructions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Are you ready, $ct? I will walk you through every step of the plan. You\'ll be perfectly safe! First thing\'s first: You see that rappel point behind me? That\'s your way down into the cave. Good luck!', `QuestDescription`) WHERE `ID` = 45628;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'This Time, Leave a Trail', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rappel down into the cave, then follow Lilian\'s instructions.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here goes nothing, $ct. If anybody can pull this off, you can! ...Probably. Just use the rappel point behind me to get into the cave.$b$bWhat? Don\'t make that face. I\'ll give you more instructions once you\'re in the cave.', `QuestDescription`) WHERE `ID` = 45629;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Servant to No One', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Test Akazamzarak\'s Servants on 5 people in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I like workin\' with ya, $n. How\'s about we keep this gold train a-rollin\'?$B$BArchmage Khadgar spends an inordinate amount of time sending his servants off to do who knows what. What if an enterprising duo such as ourselves found a cheaper alternative?$B$B<Akazamzarak hands you a small crystal.>$B$BThis bad boy will form a servant right out of thin air - and a few pounds of the dust you swept up.$B$BWhy not take it into town and try her out? See for yourself!', `QuestDescription`) WHERE `ID` = 45630;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Avocation of Antonidas', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the three discs of Antonidas\' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane. Speak with Khadgar about the Tri-Disc of Fire. And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage, I\'ve found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.$b$bIt was a sort of flying disc that could attune itself to the rider\'s magical attunement.$b$bBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.', `QuestDescription`) WHERE `ID` = 45631;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missing in Action: Eitrigg', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Eitrigg.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Are you familiar with Eitrigg? He is the worthy orc warrior who was leading our forces against the Felrage naga nearby.nnUnfortunately the naga captured many of our soldiers during a recent skirmish. Eitrigg went after them and has not returned. I fear something terrible has happened to him.nnPlease try to find him!', `QuestDescription`) WHERE `ID` = 45632;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Operation Felrage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Warlord Kaz\'jatar and Felbeard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I do not like to see naga aligned with the Burning Legion. That is something new and cannot be ignored.nnThe naga warlord, Kaz\'jatar, and his skrog toady, Felbeard, are responsible for the Felrage\'s attacks on our forces.nnWe must teach them that it does not pay to consort with demons!', `QuestDescription`) WHERE `ID` = 45633;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Kvaldir on Call', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Blow Helya\'s Horn and direct the kvaldir to destroy the three Legion portals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You empowered Helya\'s Horn in Helheim, and now is the time to use it. I have located three Legion portals we should eliminate. nnSeek out the vrykul shipwreck on Felrage Strand. Call the kvaldir and have them do what they do best: destroy!', `QuestDescription`) WHERE `ID` = 45634;
