UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Oh Doloria, My Sweet Doloria', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out Doloria in the Legerdermain Lounge in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What ho! We are quite the dashing pair of adventurers, aren\'t we?nnNow that we have secured my belongings, a new path unfolds before us. I did not journey here simply to thwart the demon invasion, no! I came here in search of my beloved, my loved, Doloria. Whilst resting between slaying of dragons, I had a dream, nay, a vision. It told me Doloria had been kidnapped and taken to a floating city in the sky!nnIt must be Dalaran. Quickly squire! Mount up and meet me at Dalaran\'s famous inn. Make haste!', `QuestDescription`) WHERE `ID` = 45644;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Fool\'s Errand', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill "Hill Bandits" to find Doloria\'s stolen "Jewelry" and buy her "release".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh yea sure, I\'m, um, held here against my, you know, will, or something.nnLook bud, between you and me old Max here has no chance, but his heart is in the right place. I keep trying to run away and hide but he keeps finding me! I just don\'t have it in me to upset him with the truth.nnI\'ve got an idea. Why don\'t you go kill some of those really big two headed "Hill Bandits" for me. Let\'s say they stole some jewelery from me, and you can use it to buy my freedom.nnTake your time, don\'t get hurt. Much.', `QuestDescription`) WHERE `ID` = 45645;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mission: Search and Rescue', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue 8 squads of Captured Warriors.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I will make these naga pay for their audacity. nnThey and their skrog lackeys captured our warriors while we were fighting the Legion. They have no honor!nnWe must rescue our fallen soldiers before they are sold as slaves, or worse...', `QuestDescription`) WHERE `ID` = 45647;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Missing in Action: Lord Darius Crowley', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search for Lord Darius Crowley.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Are you familiar with Lord Darius Crowley? He is the worthy Gilnean warrior who was leading our forces against the Felrage naga nearby. nnUnfortunately the naga captured many of our soldiers during a recent skirmish. Lord Darius went after them and has not returned. I fear something terrible has happened to him.nnPlease try to find him!', `QuestDescription`) WHERE `ID` = 45648;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mission: Search and Rescue', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue 8 squads of captured warriors.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I will make these naga pay for their audacity. nnThey and their skrog lackeys captured our warriors while we were fighting the Legion. They have no honor!nnWe must rescue our fallen soldiers before they are sold as slaves, or worse...', `QuestDescription`) WHERE `ID` = 45649;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Operation Felrage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Warlord Kaz\'jatar and Felbeard.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I am very concerned to discover naga aligned with the Burning Legion. That is something new and cannot be ignored.nnThe naga warlord, Kaz\'jatar, and his skrog toady, Felbeard, are responsible for the Felrage\'s attacks on our forces.nnWe must teach them that it does not pay to consort with demons!', `QuestDescription`) WHERE `ID` = 45650;
