UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A "Humble" Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet your visitor at Storm\'s Eye Overlook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$ct, we\'ve received a... visitor. She orders entry, but the guards will not let her pass without approval.$b$bPlease head up to the overlook as soon as you are able.', `QuestDescription`) WHERE `ID` = 45652;
