UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power of Thousands', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take Magatha\'s portal and meet her in Thousand Needles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I know I am not well liked here, and my Grimtotem and I were not invited to join you and your shaman here. However, I come to you with a proposition.$b$bThe Legion is attacking my home. I\'ve lost possession of some things that are... dear to me, and I have nowhere else to turn to. It pains me to ask... but I request your aid. If you help, I offer my people in service against the Legion.', `QuestDescription`) WHERE `ID` = 45706;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Crone\'s Wrath', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat $1oa demons on Darkcloud Pinnacle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These demons come into my home, take my things, and capture my people? They will see my wrath. Destroy them, child. Surely you are capable of at least that.', `QuestDescription`) WHERE `ID` = 45723;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Snakes and Stones', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find either the Doomstone or Arikara on Darkcloud Pinnacle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When the demons attack, they captured two very powerful possessions of mine: my companion Arikara and the Doomstone.$b$bWhile death matters not to Arikara, the Legion surely has ulterior plans for him. And the Doomstone... such an artifact of power belongs in my hands, not theirs. We must split up to find them.$b$bFor the world\'s sake, do be careful. I don\'t need you clumsily destroying everything.', `QuestDescription`) WHERE `ID` = 45724;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Breaking Chains', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free $1oa Captured Grimtotem from Prison Cages.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion shall not make fools of the Grimtotem. Free my people, and we will grace you with our aid in the coming battle.', `QuestDescription`) WHERE `ID` = 45725;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Tainted Marsh', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Drain the fel energies from the spirits of the Blind Marshlands.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I wasn\'t able to scout inside the village yet, however, there are more dangerous experiments going on to the south. They were befouling the unquiet spirits in the marshlands with more fel magic!$b$bI will rework this fel totem to draw out the fel energies they infused in those spirits.$b$bPlease, cure what spirits you can, perhaps it will even give them some peace.$b$bIf you want, I can even send you there!', `QuestDescription`) WHERE `ID` = 45726;
