UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demonic Disruption', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Farseer Nobundo to go to the Broken Shore, then meet Therazane at the Garrison of the Fel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While scouting on the Broken Shore, we have stumbled upon something quite unsettling.$b$bThe Legion is attempting to harness the powers of Azeroth\'s elements. What is more, they are succeeding.$b$bWe must stop them at all costs. I can open a portal for you to meet Therazane at the Garrison of the Fel. She will update you on the situation.', `QuestDescription`) WHERE `ID` = 45763;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Restoring Equilibrium', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 3 Stabilizing Crystals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Kor\'vass sent a report on the status of the Fel Hammer. It suffered major damage, and is now even uglier than before if that\'ss even possible...nnIt hass also begun listing to one side - rather comically, I might add. For some reason, Kor\'vass doesn\'t find this nearly as entertaining as she should.nnAnyway, there are stabilizer crystalss around the Tomb of Sargerass she could use for repairss.nnSay the word and I will direct a squadron of illidari batriderss to accompany you. I\'d come too, but...', `QuestDescription`) WHERE `ID` = 45764;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Brothers and Sisters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Heal $1oa Injured Shaman  in Garrison of the Fel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your people were trying to stop the Legion before you arrived, but flesh is weak and they accumulated too many wounds. Without your aid, they will surely perish at the hands of the demons. Go, help them.', `QuestDescription`) WHERE `ID` = 45765;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Albino Elderhorn', `LogTitle`) WHERE `ID` = 45766;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Elemental Cores', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Fire Power Cores, $2oa Water Power Cores, $3oa Earth Power Cores, and $4oa Air Power Cores.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The eredar here are abusing the power of all of Azeroth\'s elements, forcing them to their command using their fel magics. They succeed to do this through curiosities the Legion has developed, cores of power that correspond to each element.$b$bDo not allow the Legion to continue abusing our world. Kill them and take the sources of their power.', `QuestDescription`) WHERE `ID` = 45767;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Conflagration', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Barastagax the Flameripper.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That fiend! Up on the hill, a demon who calls himself "The Flameripper" is using the power of my realm. Your shaman die as he draws power from the Firelands, mixing the fire of our world with the unholy flame of his.$b$bHe is extremely powerful, Farseer. You must take him down, whatever the cost!', `QuestDescription`) WHERE `ID` = 45769;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stirring in the Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meetup with Lord Grayson Shadowbreaker in Stratholme. Once inside, locate the remains of Lord Rivendare and his mount and perform the ritual to claim it as your own.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must now purify the barding by both material and immaterial means. For the material, we need to travel to Stratholme.$b$bWhen it thrived, before the plague, it produced holy water capable of cleansing even the darkest of magics. There still may be caches of it lying untouched there that we can use.$b$bThen it\'s just a matter of imbuing enough holy power into the barding to make sure it overcomes the will of Rivendare\'s mount, Shadowmane.$b$bTravel to the service gate of Stratholme when you\'re ready.', `QuestDescription`) WHERE `ID` = 45770;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Time for Everything', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Give the Curative Brew to Iron-Body Ponshu.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our order is recovering thanks to your quick actions, Grandmaster. nnThere is just one more monk we need to attend to before it is too late!', `QuestDescription`) WHERE `ID` = 45771;
