UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Speaker Awaits', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Betild Deepanvil in Netherlight Temple.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'High Priest, we\'ve received word from Netherlight Temple of a most curious visitor: Magni Bronzebeard, the very Speaker himself!nnWhat could he want from our order? You\'d best head back to Netherlight, we\'ll hold down the front here.', `QuestDescription`) WHERE `ID` = 45788;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Sunken Vault', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take Brann\'s vessel in Azsuna to the Sunken Vault.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '\'Ello, High Priest. The Speaker has just been telling us of a calling of sorts, coming from deep in the core of Azeroth.nnThe voice is telling \'im there\'s a lost Titan vault out there, near the Maelstrom. We dun know what\'s inside, but he\'s got tha feelin\' it\'s got somethin\' ta do with the Light, and you!nnBrann\'s got a vessel waitin\' for ye, off the coast of Azsuna. Of course, I\'ll be accompanying ye as well, for cataloguing purposes. Can\'t go and let a chance like this go to waste!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Betild Deepanvil in Netherlight Temple.', `QuestCompletionLog`) WHERE `ID` = 45789;
