UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Presence of Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Repel the Legion threat from the Temple of a Thousand Lights, then Slay Portal-Keeper V\'thaal and Zor\'thaduun.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demons appear to be harnessing an ancient power within the Temple itself. They\'ve managed to twist and corrupt these sacred grounds with fel magic.$B$BWe must remove the demonic presence before we press our final advance.', `QuestDescription`) WHERE `ID` = 45795;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Destroying the Nest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Feltotem Caverns and ruin Tugar\'s plot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have to put an end to Tugar\'s plot. These abominations must be destroyed, as well as their source!$b$bI think I know where. A group of neutral drogbar had a settlement nearby, but were pushed out by concerted demon and fel tauren attacks. That must be the place.$b$bGo there and stop their fel monster production at its source!', `QuestDescription`) WHERE `ID` = 45796;
