UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Shrouded Path Through Time', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 5 Timewalking dungeons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.', `QuestDescription`) WHERE `ID` = 45799;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Avocation of Antonidas', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the three discs of Antonidas\' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane. Speak with Khadgar about the Tri-Disc of Fire. And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage, I\'ve found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.$b$bIt was a sort of flying disc that could attune itself to the rider\'s magical attunement.$b$bBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.', `QuestDescription`) WHERE `ID` = 45801;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Avocation of Antonidas', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the three discs of Antonidas\' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane. Speak with Khadgar about the Tri-Disc of Fire. And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage, I\'ve found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.$b$bIt was a sort of flying disc that could attune itself to the rider\'s magical attunement.$b$bBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.', `QuestDescription`) WHERE `ID` = 45802;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Avocation of Antonidas', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover the three discs of Antonidas\' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane. Speak with Khadgar about the Tri-Disc of Fire. And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage, I\'ve found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.$b$bIt was a sort of flying disc that could attune itself to the rider\'s magical attunement.$b$bBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.', `QuestDescription`) WHERE `ID` = 45803;
