UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where Art Thou, My Sweet', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help to maintain Doloria\'s "illusion" and ask around the Inn to see where Doloria disappeared to.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What poor fate! Here we are with the jewelry to buy my beloved\'s freedom, and she has disappeared! We must inquire of the patrons of this fine establishment. Perhaps they know what befell her.', `QuestDescription`) WHERE `ID` = 45813;
