UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Pirate\'s Bay', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet up with Tess Greymane and Tethys at Dead Man\'s Bay in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While we\'ve made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned.$b$bWe\'ve received word of a large cave off the main island, where powerful demons meet to plot our downfall. Tess and Tethys have formulated a plan, but they need your help to see it through.They are waiting for you at Dead Man\'s Bay in Azsuna.', `QuestDescription`) WHERE `ID` = 45833;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stolen Souls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Free 15 stolen souls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Odyn\'s worthy are held captive by soul fonts scattered around the Eternal Battlefield. They were destined to become Valarjar before their futures were stolen.nnNow, you can restore them to their rightful places. Destroy the soul fonts to release them!', `QuestDescription`) WHERE `ID` = 45834;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'False Orders', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Plant the False Orders in the marked locations.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As soon as you take down Prix, word will spread like wildfire amongst the crew in the area. I had Tethys forge some orders in her handwriting that should send them away and buy us some more time.$b$bPlant the orders in the marked locations. You should see the results rather quickly.', `QuestDescription`) WHERE `ID` = 45835;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Jorach\'s Calling', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Lord Jorach Ravenholdt in the Hall of Shadows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'And with that, the first phase of the plan is complete. It\'s best we return to Jorach and bring him the news.', `QuestDescription`) WHERE `ID` = 45836;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Creeping Fel', `LogTitle`) WHERE `ID` = 45837;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on Azsuna', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Repel the Burning Legion forces throughout Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demons strike at the heart of our existence, posing a threat to all who inhabit our lands.$B$BRemove the threat before it is too late.', `QuestDescription`) WHERE `ID` = 45838;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on Stormheim', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Repel the Burning Legion forces throughout Stormheim.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The eternal foe of our world, the Burning Legion, dare to attack the land of Stormheim!nnChampion, now is your call to valor! Find the forces of the Legion and eradicate them!', `QuestDescription`) WHERE `ID` = 45839;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on Highmountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Repel the Burning Legion forces throughout Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In my years I have seen disturbances and threats come and go, but never before have I seen such brazen disregard for life. nnThe demons may scorch our lands and cause suffering amongst our kin, but we must not stand idly by while they threaten what we have fought so hard to create.nnRise to the occasion, $n. The time has come to stand against the Burning Legion!', `QuestDescription`) WHERE `ID` = 45840;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Triumphant Report', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Modera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You should return to your Kirin Tor. I have no doubt they will want to hear the good news!', `QuestDescription`) WHERE `ID` = 45841;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Gift From the Six', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise your weapon and receive the Council of Six\'s gift in the Violet Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, without you some of the Legion\'s strongest agents would still be roaming Azeroth, threatening to undermine all that we\'ve accomplished in this war.$B$BSuch a deed merits more than mere recognition.$B$BIf you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Raise your weapon.', `AreaDescription`) WHERE `ID` = 45842;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Omens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Modera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We won\'t be able to defeat Kruul alone.$B$BOnce the portal has stabilized I will send word so we can bring the Highlord to justice.$B$BIn the meantime, you should inform the Kirin Tor of Vazuun\'s death - and Kruul\'s return.', `QuestDescription`) WHERE `ID` = 45843;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Avocation of Antonidas', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Kalec in the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archmage Kalec has requested your presence back in the Hall of the Guardian. He\'s discovered something he wishes to urgently speak with you about.$b$bPlease see him at your earliest convenience.', `QuestDescription`) WHERE `ID` = 45844;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Burning Within', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Khadgar about the Tri-Disc of Fire. Follow his instructions after you speak with him.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The first piece he spoke of was that of fire. He imbued it while investigating the entrance to the Molten Core.$b$bHowever, the power surging through it was too great to control, so he asked Khadgar to take it to Karazhan and see if there were any books on the subject of controlling fire.$b$bPerhaps you should speak with Khadgar and find out what became of the disc.', `QuestDescription`) WHERE `ID` = 45845;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Chilled to the Core', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The next piece Antonidas made was imbued with frost magic. He wrote about a ritual to channel frost energy into the disc with his fellow Archmage, Cedric, but their combined strengths forced too much energy into the disc.$b$bIf I recall, Cedric is helping oversee the reconstruction of Dalaran near the crater where Dalaran once resided.$b$bHopefully he knows where to find the disc.', `QuestDescription`) WHERE `ID` = 45846;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Close to Home', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Archmage Celindra about the Tri-Disc of the Arcane here in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The third piece of the disc was infused with Antonidas\' own arcane magic. He did this at the height of his power, but like the other two discs, was unable to finish his work on it.$b$bHe wrote that he gave the piece to Archmage Celindra...$b$bIsn\'t she the portal trainer here in Dalaran? She must know where the piece is!$b$bQuickly, go speak with her.', `QuestDescription`) WHERE `ID` = 45847;
