UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ancestors and Enemies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Head to Delas\' ancestral home in Val\'sharah and recover relics from her past.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I want nothing more than to prove myself by joining our offensive on the Broken Shore, but I\'m beginning to doubt my worthiness.$B$BYou see, I found my family\'s sigil among the demonic runes I\'ve been deciphering. Why the Moonfang crest would be known to the Legion is a mystery to me, but I trust you\'ll be able to find what connection lies between my ancestors and my enemies.$B$BWhat\'s left of their village can be found in Val\'sharah.', `QuestDescription`) WHERE `ID` = 45890;
