UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Infernal Phenomena', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interrupt 3 Infernal Rituals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Do you hear that, shaman? The rumble of the earth as it tries to fight against the Legion\'s will. Their half-witted eredar are attempting to bend the forces of Azeroth to their will.$b$bHow dare the Legion think they can corrupt my domain? They have assembled their infernals from Azeroth\'s stone - MY stone! Now they try to bring these new infernals to life.$b$bSabotage their foolish rituals. Crush them! Show them Azeroth\'s true power!', `QuestDescription`) WHERE `ID` = 45971;
