UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arming Dalaran', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Dalaran Spire via Aethas\' portal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Kathra\'natir is powerless to stop us from harnessing his energy within the Nightborne Soulstone. We have been lucky thus far - our allies have kept news of the sabotage from spreading. nnWe should repair Dalaran\'s weapons array immediately while luck is still on our side.nnOh - the weapon platform is a bit inaccessible. I trust you are not afflicted by a fear of heights? I will open a portal.', `QuestDescription`) WHERE `ID` = 46000;
