UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crystal Containment', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Jubeka Shadowbreaker in Dreadscar Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Kanrethad will be safe in my care, but something must be done about these crystals that hold his fel magic.nnIf any should break, the energy inside would find its way back to our friend. I shouldn\'t need to tell you how devastating it would be if that were to happen.nnI will gather the crystals and meet you back at Dreadscar Rift.', `QuestDescription`) WHERE `ID` = 46020;
