UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Urgent Warning', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Tactician Tinderfell', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The soldier is wan and wounded, obviously in tremendous pain.>nnBeen held prisoner... since the assault on... the Broken Shore...nn<She shudders.>nnThe demons... th-they are gathering... preparing...nnHad to escape... to warn you. They must... be stopped!', `QuestDescription`) WHERE `ID` = 46022;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Investigate the Broken Shore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Menace on the Broken Shore".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All of us know the price we paid the last time we set foot upon the Broken Shore.$b$b<Tinderfell turns her eyes to the ground.>$b$bI recommend dispatching a scouting team to investigate the Legion\'s strength. We need to know what we\'re facing in that accursed place.', `QuestDescription`) WHERE `ID` = 46023;
