UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'End of the Risen Threat', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Lord Erdris Thorn. Speak with War Councilor Victoria to be teleported to Jarod Shadowsong\'s location.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Commander Shadowsong sends word that he is prepared to face the late Lord Erdris. I have a letter from him for you.$b$bI\'m prepared to teleport you to his location, but there\'s a snag.$b$bIn order to combat the worst of the fel corruption, you will need to use some Nethershards on the way in. Make sure you have some before speaking with me.', `QuestDescription`) WHERE `ID` = 46035;
