UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Salvation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Manaroot Salve on fel-infected animals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The valley is swarming with fel-corrupted creatures who are beyond saving, yet there still may be some that could use our help.nnTake this manaroot salve and apply it to any animals you see. If the fel magic hasn\'t taken hold, the salve might be able to mend their wounds.', `QuestDescription`) WHERE `ID` = 46060;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Adopt a Tadpole', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Select your favorite Winterfin tadpole and beckon it to follow you.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One day every year, usually in mid-spring, the Winterfin tadpoles are given free reign of the village. I\'m not sure why this tradition persists, as it usually results in heavy damage to the their buildings and food stores.$b$bI usually try not to interfere too much with the goings-on of the tribe, but today, I take exception. Go out and see if you can keep an eye on one of the tadpoles.', `QuestDescription`) WHERE `ID` = 46061;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Tadpole\'s Request', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Winterfin Clams.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Glrrrr! Mrr, mrr, glrrgli!$b$b<Your favorite little tadpole is getting reckless. Maybe he might like some clams?>', `QuestDescription`) WHERE `ID` = 46062;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wailing Dead', `LogTitle`) WHERE `ID` = 46063;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Ways of the World', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Mrrga.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mrrga!$b$b<Your tadpole cowers and hides, as he observes the shadowy figure of a large orca passing through the Westrift.>$b$bMrrga... Mrrga...', `QuestDescription`) WHERE `ID` = 46064;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Impossible Foe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with War Councilor Victoria to be teleported to the Imp Mother\'s Den and defeat Agatha.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n! We have just received word from the Council of Six. They have found Agatha!nnModera asked that she be able to brief you through this image crystal.  nnGood luck!', `QuestDescription`) WHERE `ID` = 46065;
