UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Worthy of the Title', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lord Grayson Shadowbreaker in your order hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Highlord, Lord Grayson Shadowbreaker wishes to speak with you about an important matter.$b$bPlease seek him out at Light\'s Hope Chapel in your order hall at your earliest convenience.', `QuestDescription`) WHERE `ID` = 46069;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Preparations Underway', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you\'re not a leatherworker or don\'t know a leatherworker.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you may or may not recall, I once helped young paladins obtain their first armored mount.$b$bIt was a tedious task that involved months of obtaining materials and sending them all over Azeroth.$b$bThankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord.$b$bIn order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.', `QuestDescription`) WHERE `ID` = 46070;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hammer of Dalaran', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Alard Schmied in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Should we wish to make this barding worthy of the steed who will bear it, we\'ll need to upgrade it. Right now it\'s just good for not getting you kicked off your mount.$b$bSpeak with Alard Schmied in Dalaran. He\'s a fine smith and will know how to modify this barding into something more befitting our needs.', `QuestDescription`) WHERE `ID` = 46071;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Full Fel', `LogTitle`) WHERE `ID` = 46072;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Break Their Garrison', `LogTitle`) WHERE `ID` = 46073;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leather to Legendary', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Have Alard upgrade the barding and return with it to Lord Grayson Shadowbreaker at your order hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Let\'s begin, shall we? I mean, I\'ll be doing all the work, but you get to watch!$b$b<Alard grins a wide smile at you and begins working.>', `QuestDescription`) WHERE `ID` = 46074;
