UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dread Infiltrators', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Lilian Voss in the Hall of Shadows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Shadowblade, we have received a raven with most troubling news.nnOne of our own, an ally that walked our very Hall of Shadows, is not who they seem.nnI believe Lilian has already begun dissecting their corpse. You\'d best hurry.', `QuestDescription`) WHERE `ID` = 46103;
