UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cutting off the Heads', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay the risen squad leaders in Bradensbrook.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Erdris Thorn was a key commander of Ravencrest\'s forces. To hear him confusing us for the Legion fills me with a great sadness. He will be a difficult foe to defeat.nnWe must stop his squad leaders from forming up for a focused assault on Bradensbrook. Defeating them should delay his forces long enough for us to find and deal with him. Let us begin our grim task.', `QuestDescription`) WHERE `ID` = 46106;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Source of the Corruption', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the source of the corruption at Heroes\' Rest and end it.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There was something wrong with those three, they had a fel taint about them that was... unsettling. I believe they were somehow woken later than the other risen. Curse the Legion and their meddling!nnThe reinforcements are streaming out of Black Rook Hold from Heroes\' Rest. We must make our way there and see if we can stop the source of these new troops.', `QuestDescription`) WHERE `ID` = 46107;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knowledge is Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Provide Order Resources to unlock artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon\'s potential.nnThere is a time for slow, steady progress. But today, we must hasten our efforts.nnBy devoting our order\'s resources to studying the weapon\'s history, I believe we can rapidly enhance the value of the power you apply to the artifact.nnShall we begin, $ct?', `QuestDescription`) WHERE `ID` = 46108;
