UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Furthering Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Order Resources to complete a crash course in artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have learned so much already about these artifacts it is incredible. nnOur researchers have been busy preparing notes for you and with a few more resources I am sure they can be used as a crash course in gaining more artifact knowledge. nnThis is only the first step, with more resources we should have additional courses to help you catch up on your studies.', `QuestDescription`) WHERE `ID` = 46125;
