UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thwarting the Twins', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with War Councilor Victoria to be teleported to Raest\'s location and defeat him.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have news from Archmage Karlain! The Kirin Tor have found Raest Magespear and can open up a portal to his location!nnIf you are ready to face him, I can have the mages here open the portal into the Twisting Nether.', `QuestDescription`) WHERE `ID` = 46127;
