UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knowledge is Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Provide Order Resources to unlock artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Boss, you\'ve been working every angle on the Broken Isles, infusing that ancient artifact of yours with power. But those demons won\'t give up, and we really need to unlock more of your weapon\'s potential... and I mean pronto!nnSlow, steady progress is one thing. But today, we need to get busy.nnHere\'s the deal. You fork over our order\'s resources so I can study the weapon\'s history, and I\'ll get you a way to up the value of the power you apply to that artifact.nnHow does that sound, $ct?', `QuestDescription`) WHERE `ID` = 46129;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knowledge is Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Provide Order Resources to unlock artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon\'s potential.nnThere is a time for slow, steady progress. But today, we must hasten our efforts.nnBy devoting our order\'s resources to studying the weapon\'s history, I believe we can rapidly enhance the value of the power you apply to the artifact.nnShall we begin, $ct?', `QuestDescription`) WHERE `ID` = 46130;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knowledge is Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Provide Order Resources to unlock artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You are truly the scourge of the Broken Isles, wresting power from our enemies and infusing it into your ancient artifact. But we must not become complacent! Let us unlock further depths of your weapon\'s potential.nnThere is a time for slow, steady progress. But today, we will redouble our efforts.nnBy devoting our order\'s resources to studying the weapon\'s history, I believe we can rapidly enhance the value of the power you apply to the artifact. And power is intoxicating.nnShall we begin, $ct?', `QuestDescription`) WHERE `ID` = 46131;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knowledge is Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Provide Order Resources to unlock artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Durin\' our campaign on the Broken Isles, ye have infused yer ancient artifact with power. But as the Legion invasion grows stronger, it\'s clear we need to unlock more of yer weapon\'s potential.nnThere\'s a time for slow, steady progress. But today, we\'d best hasten our efforts.nnBy devotin\' our order\'s resources to studyin\' the weapon\'s history, we can rapidly enhance the value of the power ye apply to the artifact.nnWe best get started, $ct!', `QuestDescription`) WHERE `ID` = 46132;
