UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Knowledge is Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Provide Order Resources to unlock artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In the course of trouncing foe after foe in the Broken Isles, you have infused your ancient artifact with power. But the Legion fights without honor, and to defeat them we must unlock even more of your weapon\'s potential.nnSlow, steady progress will wait for another time. Today, we must hasten the path to victory.nnBy devoting our order\'s resources to studying the weapon\'s history, I believe we will rapidly enhance the value of the power you apply to the artifact.nnGlory awaits us, $ct!', `QuestDescription`) WHERE `ID` = 46142;
