UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sterile Surroundings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Netherlight Temple.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the threat of infection dismissed, your allies should be able to press their assault here on the Broken Shore and gain an advantage over the Burning Legion.nnLet\'s leave this place and speak somewhere more... sterile. I hear your order occupies an impressive temple.', `QuestDescription`) WHERE `ID` = 46145;
