UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Furthering Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Order Resources to complete a crash course in artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The amount of power in these artifacts is incredible and we have only scratched the surface. nnOur researchers have been busy preparing notes for you and with a few more resources I am sure they can prepare something to boost your artifact knowledge. nnThis is only the first step, with more resources we should be able to help you catch up even more.', `QuestDescription`) WHERE `ID` = 46154;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Furthering Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Order Resources to complete a crash course in artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Studying these ancient magic and metals has given us great insight into the potential of these weapons.nnJust as these weapons were forged with time and effort so can we forge you instruction on how best to wield and unlock them. With a few more order resources we will have a course completed for you to increase your knowledge.nnThis is only breaking the surface of what we will unlock, and as we break through the layers of lost knowledge it will take time to delve deeper.', `QuestDescription`) WHERE `ID` = 46155;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Furthering Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Order Resources to complete a crash course in artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$gSir:Mam;, thank you and the Tirisgarde for this opportunity. Learning about this weapon of yours has been an absolute joy. nnTo repay your confidence and trust in my abilities I have organized our researchers notes into an easily digestible course. If you have the resources I know we will continue to output even more valuable insights. nnI assure you it has been worth every minute.', `QuestDescription`) WHERE `ID` = 46156;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Furthering Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Order Resources to complete a crash course in artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The amount of power in these artifacts is astounding and we have only just begun our journey. nnOur researchers have been busy preparing notes for you and with a few more resources I am sure they can prepare something to boost your artifact knowledge. nnThis is only the first step, with more resources we should be able to help you catch up even more.', `QuestDescription`) WHERE `ID` = 46157;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Furthering Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver Order Resources to complete a crash course in artifact knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we follow the stories further back there are strong whispers of even greater potential. nnWe have discovered much along the way and we can impart that knowledge. With the help of more order resources we will continue to bring in information from members traveling far and wide.nnThese shaman like you are the key to finally unlocking the full potential of these weapons and soon enough we will be back to the time consuming task of chasing down rumors to discover more.', `QuestDescription`) WHERE `ID` = 46158;
