UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Archmage Accosted', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Confront Archmage Xylem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With the barrier dispelled, Archmage Xylem is finally within reach!nnHopefully he\'ll be cooperative in returning the Iris...', `QuestDescription`) WHERE `ID` = 46176;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Portal Away', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Archmage Kalec in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Xylem may have escaped, but a trace of his portal remains.nnNow that you have freed his apprentices from his corruption, I will set them to work trying to find a way to reach him.  Once I find something, I will alert the Kirin Tor.nnI only ask that when you do confront the Archmage, that you try to spare his life. I believe that the good man he once was still exists beneath the shadow that has taken him.nnFarewell, $n.', `QuestDescription`) WHERE `ID` = 46177;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hiding In Plain Sight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assassinate the infiltrating homunculi.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, Shadowblade.nnI hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead.nnYes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord.nnAnd there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.', `QuestDescription`) WHERE `ID` = 46178;
