UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle for Highmountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Fel Commander Erixtol in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our defenses have grown in strength, yet the Legion continues to press their assault on Thunder Totem. There is but one way to put an end to this madness - we must strike at the heart of their forces together and bring these attacks to an end.', `QuestDescription`) WHERE `ID` = 46182;
