UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Battle for Azsuna', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Fel Commander Xeritas in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The vile demon commanding the assault must be stopped. I can get us close, but once we\'re there I\'ll rely on you and your allies to help bring down the demonic forces.', `QuestDescription`) WHERE `ID` = 46199;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Matter Resolved... For Now...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Archmage Modera in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You should return to the Kirin Tor. I have no doubt they will want to hear of our success. I will find Lord Erdris, and then I will contact you.', `QuestDescription`) WHERE `ID` = 46200;
