UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Conduit No More', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Legion\'s Conduit at the Temple of a Thousand Lights.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One final task remains to sever the Burning Legion\'s connection to other worlds.$B$BI\'ll provide you transportation to get you close to the source of power, but you must deliver the final blow to the conduit.', `QuestDescription`) WHERE `ID` = 46205;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Whispers of a Frightened World', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Magni in Sholazar Basin and hear the warning.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '"Champion! Azeroth needs our help."$b$b<Magni Bronzebeard\'s words echo in your mind, as if rising from somewhere deep and ancient. Azeroth\'s world soul seeks to deliver a warning to the Speaker, but some force is interfering with the message.>$b$b<Magni has urged you to travel to Sholazar Basin, the vibrant heart of frozen Northrend, to aid him.>', `QuestDescription`) WHERE `ID` = 46206;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Trial of Rage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Odyn to begin the Trial of Rage scenario. Complete the scenario and claim your prize.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I wish to extend to you a prestigious invitation.$b$bEvery year I hold a trial for my finest warrior to prove that I command the strongest in this land. I have chosen you to be my champion in this trial.$b$bShould you succeed in completing the trial, I have a prize that will be worthy of your accomplishments awaiting you at the end.$b$bTake what time you need to prepare yourself. Come back and speak with me when you\'re ready to begin.', `QuestDescription`) WHERE `ID` = 46207;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Godly Invitation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Odyn at your order hall in Skyhold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Battlelord $p, Odyn has requested an audience with you back in Skyhold.$b$bPlease meet with him at your earliest convenience.', `QuestDescription`) WHERE `ID` = 46208;
