UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Crystals Not Included', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Argunite Crystals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Turalyon is safe, and we can start to fight back.$b$bFirst things first, we must secure what supplies we can from the crash.$b$bEven though we are blessed by the Light, our ships still rely on crystal technology. From powering our defenses to arming our weapons, we will need to collect as much as we can to fight back against the enemy.$b$bVenture out into the crash and retrieve what crystals you can. While you are out there, keep an eye out for Y\'mera. She was separated from us, and will need help.', `QuestDescription`) WHERE `ID` = 46213;
