UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Secured Surroundings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Nighthuntress Syrenne at Deliverance Point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With Lexera defeated, her band of trappers will quickly disband. Those that refuse will meet my blade.nnThese shores will be free of those who wish to corrupt Azeroth\'s wildlife.nnOur work here is done for now. Let us meet at Deliverance Point. There is more I wish to discuss in secured surroundings.', `QuestDescription`) WHERE `ID` = 46235;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Stonebound Soldiers', `LogTitle`) WHERE `ID` = 46236;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bloodbringer\'s Missive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Mor\'zul Bloodbringer in Dreadscar Rift.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Warlock! We have news from Dreadscar Rift. nnA message arrived by raven from Mor\'zul Bloodbringer, with instructions that you meet him in Dreadscar Rift immediately!', `QuestDescription`) WHERE `ID` = 46237;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'If You Build It', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 5 Felslate, 3 Chaotic Spinel and an Unbending Potion. These can be gathered and crafted using profession skills or purchased on the Auction House.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If we wish to achieve a sustained connection to Xoroth, we\'ll need a particularly resilient portal. Unfortunately, we can\'t just summon this one up from the ground.nnI will need you to gather the requisite materials. Once we have them, I will have the mo\'arg begin construction at once. nnHere\'s the list of what you\'ll need.', `QuestDescription`) WHERE `ID` = 46238;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel to the Core', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect an Overcharged Fel Core from the commander of a Legion Assault on the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While it has become relatively easy for a warlock to open a brief window into the realms of the Legion, a sustained portal requires significantly more power.nnFor this, we will need a power source brimming with fel energy. nnI know that the commanders of the Legion use powerful fel cores to control their warships. If you can defeat the commander of one of these ships, you should be able to take their core.', `QuestDescription`) WHERE `ID` = 46239;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Give Me Fuel, Give Me Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 50 Owlbeast Blood from Owlbeasts within Lostlight Grotto in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A powerful core will not alone be able to power the portal. Like any powerful engine, it will require fuel - though an engine of fel energy must burn life force to thrive.nnWe will need blood potent in magical energy to keep our fel core running and sustain our connection to Xoroth. Fortunately, I have experience in these matters, and I know just the place where we can get some.nnYou\'ll need a jar or something.', `QuestDescription`) WHERE `ID` = 46240;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Minions of Hel\'nurath', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use your Succubus\' Seduction to question Xorothian Cultists within the Dark Stockades in the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The dreadlord Hel\'nurath gifts his lieutenants with calling stones to call and bind the dreadsteeds of Xoroth to their service. I believe one such stone will help us draw out the Wrathsteed. nnSome Xorothian cultists have been spotted helping the Legion\'s efforts on the Broken Shore. It would be safe to assume their leader has one of Hel\'nurath\'s stones.nnYour succubus should be able to entice the truth out of the cultists. Find one who knows of their leader\'s whereabouts.', `QuestDescription`) WHERE `ID` = 46241;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dreadlord\'s Calling', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Xorothian Calling Stone from Zuriwa the Hexxer within the Dark Stockades in the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'According to the cultist, the leader you seek should be in her tower overseeing the operations in the Dark Stockades.', `QuestDescription`) WHERE `ID` = 46242;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wrathsteed of Xoroth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the ritual on the Summoning Platform in Dreadscar Rift to enslave the Wrathsteed.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time has come and the preparations have been made. When you are ready, we will tear a hole into Xoroth, and force the Arax\'ath and the Wrathsteed out of hiding.nnFollow me to the summoning platform. From there we will initiate the ritual.nnPrepare yourself, $n. This will not be an easy undertaking.', `QuestDescription`) WHERE `ID` = 46243;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Altar of the Aegis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Lord Mephistroth and place the Aegis of Aggramar upon the Altar of Eternal Night.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Champion, we are ready to assault the Tomb of Sargeras.nnI studied the writings of Aegwynn, the Guardian who defeated the Dark Titan\'s avatar. She said that if her wards were compromised, a failsafe could be triggered by placing the Aegis of Aggramar upon an altar in the Cathedral of Eternal Night.nnYou are the hero who acquired the Pillars of Creation, $n. Gather your allies and enter the Cathedral. Be warned: Mephistroth will use all his power to stop you from placing the Aegis. You must prevail!', `QuestDescription`) WHERE `ID` = 46244;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Begin Construction', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Construction Table to donate Legionfall War Supplies to the construction of the Mage Tower, Nether Disruptor, or Command Center.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve got the supplies. Now someone needs to decide what to do with \'em.nnHmm. Looks like it\'s your call, being the $ct and all!nnTime to pick a building to focus on.', `QuestDescription`) WHERE `ID` = 46245;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Strike Them Down', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 100 demons on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Felstorm continues to rain demon scum upon these shores. Kil\'jaeden believes his army infinite, his resources inexhaustible.nnWe will show him how wrong he is.nnCut a swath of retribution through their ranks, $ct. Strike down demon after demon, until your weapons are bathed in their blood. And when they cry out for mercy, send them screaming back into the Nether.', `QuestDescription`) WHERE `ID` = 46246;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Defending Broken Isles', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat a Legion Assault in the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In our zeal to reclaim the Broken Shore from the Legion, we cannot allow the rest of this land to fall into the demons\' foul grip.nnKil\'jaeden has dispatched his forces across the Broken Isles, threatening the homelands of the allies you have made. You must answer their call in this hour of need.nnTurn back these demon assaults with haste, $ct. The Armies of Legionfall will see that the Broken Shore remains secured.', `QuestDescription`) WHERE `ID` = 46247;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Self-Fulfilling Prophecy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 8 World Quests on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In my life, I have witnessed many visions. Some filled me with hope... others, with despair.nnVictory over Kil\'jaeden lies within our grasp. I have foreseen it. But visions only show us where our path might lead. They require effort to become reality.nnThat effort falls upon your shoulders, $n. You have done much, but more is needed. Fight on the battlefields of the Broken Shore and forge a destiny free from the Legion\'s grasp!', `QuestDescription`) WHERE `ID` = 46248;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Championing Our Cause', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Successfully complete a Legionfall mission at your Class Order Hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Important work has been done by your order, $ct. Your champions have succeeded time and again in undermining the Legion\'s invasion.nnAs we make preparations for our assault on the Tomb of Sargeras, we need to keep the demons off balance. By pressuring them at every turn, we will expose vulnerabilities that can be exploited to our advantage.nnSend out your order\'s champions, $n. Their missions are vital to the success of our campaign... especially as our confrontation with Kil\'jaeden draws closer.', `QuestDescription`) WHERE `ID` = 46249;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Take Out the Head...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Rare Elite Demon Commanders on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Broken Shore swims with Legion filth, each demon deserving of a swift and merciless end.nnBut some are more insidious than the rest. Powerful combatants rallying others to their perfidious cause.nnStrike down these demon champions and you will fill the hearts of their kin with fear and doubt. Break the Legion\'s spirit and we will break its back.', `QuestDescription`) WHERE `ID` = 46250;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shard Times', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Nethershards on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you have surely noticed, a slain demon leaves behind Nethershards, solidified residual energy from the Twisting Nether. I require a significant quantity of them for an experiment I\'m conducting... $1oa shards, to be precise.$b$bWhy are you looking at me like that? We\'ve had this conversation before. I did the math.$b$bI need exactly $1oa shards. Fewer would be inadequate. More would be absurd.$b$bDon\'t question my methods. Go!', `QuestDescription`) WHERE `ID` = 46251;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Intolerable Infestation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 50 demons in Faronaar or Felsoul Hold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While we purge Legion filth from the Broken Shore, the fiends maintain their hold on nearby lands. Their presence can no longer be tolerated.nnThe fetid strongholds of Faronaar and Felsoul Hold infest Azsuna and Suramar. Choose an attack point and cut a swath through their insidious ranks.nnReturn to me with demon blood on your hands, then we can resume our campaign to drive Kil\'jaeden from the Tomb.', `QuestDescription`) WHERE `ID` = 46252;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pillars of Creation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Pillars of Creation to seal the Tomb of Sargeras.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our campaign on the Broken Shore has reached a turning point. The Armies of Legionfall stand ready to breach the Tomb of Sargeras and seal the Legion\'s gateway to our world.nnThe time to strike is now, $n.nnThe Aegis of Aggramar has been secured in the Cathedral. The echo of Magna Aegwynn said that the other Pillars of Creation are needed to seal the tomb. It is fitting that you have the honor of locking those ancient relics in place and closing down the Felstorm once and for all.', `QuestDescription`) WHERE `ID` = 46253;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'TBD', `LogTitle`) WHERE `ID` = 46254;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'X Unstable Portals Disrupted, 1 World Boss Defeated', `LogTitle`) WHERE `ID` = 46255;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'X Treasures Found, 1 Challenge Attempted', `LogTitle`) WHERE `ID` = 46256;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'REUSE ME', `LogTitle`) WHERE `ID` = 46257;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Calm After the Storm', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Doomstone to Neptulon in the Maelstrom.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You have saved the elements from the Legion\'s control, and for that we thank you. However, it came at a great cost to both your health and your fellow shaman. Many came back to us wounded, dragged along by their fellow shaman.$b$bWe have seen the havoc the Doomstone can wreak. It does not belong in the hands of any being, mortal or otherwise. While you were asleep, the elemental lords and I discussed its fate.$b$bBring it to Neptulon. He will explain.', `QuestDescription`) WHERE `ID` = 46258;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkbinder Dilemma', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Darkbinder Elissath.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ah, Delas sent you. I see.$B$BIt\'s good she didn\'t come herself. It would break her heart to see what is happening to our family.$B$BA demon is defiling our dead in the ruins nearby. She\'s using her fel magic on our ancestors, turning them into mindless horrors that do the bidding of the Burning Legion.$B$BI can\'t deal with the harpies and this demon, but maybe you could help?$B$BGet rid of the darkbinder that torments our dead, and I will grant you access to whatever\'s left of the Moonfang family relics.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Darkbinder Elissath', `PortraitGiverName`) WHERE `ID` = 46259;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Meld Into the Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to the Hall of Shadows, and meet Lord Jorach Ravenholdt.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.', `QuestDescription`) WHERE `ID` = 46260;
