UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return of the Slayer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Kor\'vas aboard the Fel Hammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you\'re anything like me, I\'m sure you\'d prefer to remain here on solid ground.nnUnfortunately, it is probably best to return to the Fel Hammer right away so Kor\'vass can finish the repairss.', `QuestDescription`) WHERE `ID` = 46266;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return of the Battlelord', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Odyn in Skyhold.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Battlelord $n, Odyn will want to hear the tale of your glorious victories here!nnI will assist you in returning to Skyhold when you are ready.', `QuestDescription`) WHERE `ID` = 46267;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Found Memento', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the compass to King Anduin Wrynn in Stormwind Keep.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The trinket\'s fine brass exterior is inlaid with intricate filigree, though much of the detail has been battered by rocks and waves. Clearing away the grime and salt encrusting the clasp, you manage to open it.nnIt is a compass--or was, at least. The glass face is shattered, the needle bent, unmoving.nnSet into the lid is a portrait. The paint is faded and waterlogged, but the subject is unmistakable: the face of a young Anduin Wrynn.>', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Bring the compass to King Anduin Wrynn in Stormwind Keep.', `QuestCompletionLog`) WHERE `ID` = 46268;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'reuse me', `LogTitle`) WHERE `ID` = 46270;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Summons to the Keep', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Genn Greymane at Stormwind Keep.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, $n.nnYour presence has been requested in the royal court. The crown has urgent need of you!nnPlease return to Stormwind at your earliest convenience.nnKing Greymane is anticipating your swift arrival.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet with Genn Greymane at Stormwind Keep.', `QuestCompletionLog`) WHERE `ID` = 46272;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Giver of Quests', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'asdf', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'asdf', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'asdf', `QuestCompletionLog`) WHERE `ID` = 46273;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Consoling the King', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Look for King Anduin Wrynn inside Stormwind Cathedral.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Anduin hasn\'t been the same since you brought him his father\'s compass. He has become listless... distracted.nnWe attempted to console him, to no avail. Yesterday morning, he left the keep without so much as a word.nnI ordered the guards to follow him, of course. He went to pray at the cathedral, where he\'s remained ever since.nnYou brought this melancholy upon him! You must convince the boy to resume his duties. There\'s a war to be won!', `QuestDescription`) WHERE `ID` = 46274;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Kingdom\'s Heart', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Accompany King Anduin on his walk through Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My father was a legend. He oversaw the rebuilding of Stormwind, stood toe-to-toe with dragons, led the Alliance to numerous victories.nnThen, one day, he was just... gone.nnI wear his crown, I hold his title. But I\'ve done nothing to earn them... or the faith of my people.nnI\'ve spent the war sequestered in the keep, surrounded by guards and advisors. I need to walk the streets of Stormwind, to know whether it is hope or fear that beats in the hearts of my people.nnI welcome your company.', `QuestDescription`) WHERE `ID` = 46275;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Contribute to Mage Tower', `LogTitle`) WHERE `ID` = 46277;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Zargrom', `LogTitle`) WHERE `ID` = 46279;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The King\'s Path', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Accompany King Anduin to the Tomb of Sargeras.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that I have seen the Broken Shore and the terror of the Burning Legion first hand, my eyes have been opened to the truth.nnI speak not of the unfathomable evil of the enemy, but of the bravery and sacrifice that such evil brings about in the hearts of our people.nnMy father once told me that every king must carry the weight of his own crown. Mine has never felt heavier than it does at this very moment...nnPlease take me to the place where my father died, so that I may honor his sacrifice.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Accompany King Anduin to the Tomb of Sargeras.', `QuestCompletionLog`) WHERE `ID` = 46282;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '7.2 Broken Shore - Buildings - Mage Tower - Personal Reward Received', `LogTitle`) WHERE `ID` = 46283;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Legionfall Supplies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete World Quests or slay Rare Elites on the Broken Shore to earn Legionfall War Supplies.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If we don\'t build up some respectable fortifications, we\'ll lose our foothold on the Broken Shore.nnThat ain\'t gonna happen on my watch, mate!nnWe started construction on three key structures: the Mage Tower, the Nether Disruptor, and the Command Center. Each will play a key role in helping us pound the tar out of the Burning Legion.nnTo make progress, we need Legionfall War Supplies... and I mean lots of \'em! You bring \'em to me, and I\'ll handle distribution. Got it?', `QuestDescription`) WHERE `ID` = 46286;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Everyone to the Front', `LogTitle`) WHERE `ID` = 46288;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return of the Archmage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Meryl in the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With Dalaran protected once again, we can all breathe a little easier. nnIt is time for us to return to the Hall of the Guardian. I\'m sure Meryl is anxiously awaiting word of our success.', `QuestDescription`) WHERE `ID` = 46290;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Deadmines Strike Back', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Cookies\' Leftovers in the Deadmines.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Breanni sent you? For her, info is always free. Just don\'t call me a snitch.nnI\'ve been hangin\' around the Deadmines for years. For the most part, it\'s a pretty easy livin\'. But a few days ago, I started hearing noises of all sorts comin\' from the mines. If you want to get in unnoticed, I\'ll grab us a mine cart and we can get most of the way down without so much as an awkward glace in our direction.nnJust let me know when you\'re ready to head in.', `QuestDescription`) WHERE `ID` = 46291;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Pet Battle Challenge: Deadmines', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Cookies\' Leftovers in the Deadmines.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Deadmines could still use some cleaning up, seems you didn\'t clear the place out last time.nnWe\'ll use the ol\' mine cart trick again. Cept, we\'re going to put some flair into it. How do you feel about fire? No? Okay, fine. Just let me know when you\'re ready.', `QuestDescription`) WHERE `ID` = 46292;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Deadmines, Part Three?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Marcus "Bagman" Brown outside the Deadmines in Westfall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve heard suspicious rumors of movement in the Deadmines. After everything you pulled off in the Wailing Caverns, you\'d be the perfect person to look into this!nnI have a friend in Westfall. He may not look like much, but he\'s quick as a whip and may have more information on what is happening in Westfall. We\'ve already dealt with the Van Cleefs... twice. So what could be making that sort of ruckus down there?', `QuestDescription`) WHERE `ID` = 46293;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Overwhelming Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $4oa demons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We will find no sanctuary on this world. Even now the full might of the Burning Legion rises to defend Argus.$B$BThe siege camp below overflows with demon filth that stand between us and the weapon trained on the Vindicaar.$B$BThey must be dealt with before it can fully charge, or Argus will be our grave.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Illidan Stormrage at the Crown of Destruction.', `QuestCompletionLog`) WHERE `ID` = 46297;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rare Elite 15', `LogTitle`) WHERE `ID` = 46304;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Thorim\'s Flame', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Convince the Drekirjar Shrine-Keeper to let you take Thorim\'s Flame.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Not too long ago, the Drekirjar and the Thorignir respected each other. This only changed when Skovald came into power. An ancient Drekirjar spirit watches over this peak, which seems to be a sacred graveyard of some sort. He is the keeper of the ceremonial flame, which happens to be exactly what we need to call down the broodmother.$b$bWhy don\'t we go convince him to let us take the flame? I\'m sure he\'ll be nothing but... amiable.', `QuestDescription`) WHERE `ID` = 46305;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leave a Trail', `LogTitle`) WHERE `ID` = 46308;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rare Elite 16', `LogTitle`) WHERE `ID` = 46313;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vengeance: Seeking Kor\'vas', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Kor\'vas Bloodthorn in the streets of Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thankfully, we are not quite alone in uncovering the Legion\'s plots to infiltrate the city.$B$BOne of your Illidari, Kor\'vas Bloodthorn, has taken to patrolling the city streets on her own to find the source behind the recent attacks.$B$BI do not entirely trust your kind, but I will concede that you have at least proved adept at your namesake. I suggest you find Kor\'vas and see what she has uncovered before the Legion strikes once more.nn|cFF660000Specialization: Vengeance Demon Hunter|r', `QuestDescription`) WHERE `ID` = 46314;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prideful Gladiator\'s Leather Armor', `LogTitle`) WHERE `ID` = 46315;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: Kanrethad Ebonlocke', `LogTitle`) WHERE `ID` = 46316;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Talon\'s Call', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Thisalee Crow in the Dreamgrove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion is launching a renewed assault against the Shrine of Aviana in Hyjal!nnThisalee Crow is organizing a counter-offensive, she requests your presence in the Dreamgrove at once.nnWe will handle the offensive here. Good luck, Archdruid!', `QuestDescription`) WHERE `ID` = 46317;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Defense of Aviana', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Assist Thisalee in the defense of the Shrine of Aviana in Hyjal, then return to her in the Dreamgrove.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The situation is dire. The Legion is attacking the Shrine of Aviana in Hyjal, AGAIN! They must be after something specific, but I\'m not sure what.nnUs Druids of the Talon are skilled scouts and infiltrators, but are lacking in... durability. They won\'t be able to hold out for long! We must go to help!', `QuestDescription`) WHERE `ID` = 46318;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'You Can\'t Take the Sky from Me', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deal with Infazzar the Shade, and retrieve the Idol of Aviana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Shrine of Aviana has fallen to the demons, and the Idol of Aviana has been stolen.nnThat idol acts as a link between the Druids of the Talon and the powers of flight granted to us by Aviana.nnThe Druids of the Talon have decided to rebuild a new shrine in a more secure location: here in the Dreamgrove.nnMeanwhile, I\'m going to get our idol back. Meet me in Azsuna, near where we\'ve tracked Infazzar to, if you want to help.', `QuestDescription`) WHERE `ID` = 46319;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hope For a Cure', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to the Spirit of Brewmaster Blanche in the Temple of Five Dawns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hopefully you found enough fel poison samples with which to brew a cure.nnLet\'s meet back to the Temple of Five Dawns!', `QuestDescription`) WHERE `ID` = 46320;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Krasus\' Landing Searched', `LogTitle`) WHERE `ID` = 46321;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Pirate\'s Bay', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet up with Lilian Voss and Tethys at Dead Man\'s Bay in Azsuna.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While we\'ve made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned.$b$bWe\'ve received word of a large cave off the main island, where powerful demons meet to plot our downfall. One of our rogues, Lilian Voss, has formulated a plan with Tethys to take care of them, but they require your aid. They are waiting for you at Dead Man\'s Bay in Azsuna.', `QuestDescription`) WHERE `ID` = 46322;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'What\'s the Cache?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Master Gunner Prix and obtain the Fel-Infused Gunpowder Cache.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our goal is to retrieve a cache of gunpowder which has been infused with some sort of fel power. I don\'t know how the pirates here acquired it, but it is more dangerous than they know. I assure you that it will be more... effective in our hands.$b$bMaster Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.', `QuestDescription`) WHERE `ID` = 46323;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'False Orders', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Plant the False Orders in the marked locations.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must take some precautions. As soon as you assassinate the gunner, the crew will be looking for you. I had Tethys forge some orders in her handwriting that should buy us some time.$b$bPlant the orders in the marked locations. That will take care of the danger.', `QuestDescription`) WHERE `ID` = 46324;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The United Front', `LogTitle`) WHERE `ID` = 46325;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Jorach\'s Calling', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Lord Jorach Ravenholdt in the Hall of Shadows.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'And with that, the first phase of my machination is complete. Let\'s return to Jorach and tell him it is time to continue.', `QuestDescription`) WHERE `ID` = 46326;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bargaining with Shadows', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Ritssyn Flamescowl in the Chamber of the Guardian beneath Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'From the clues you\'ve been able to piece together, it appears that Levia was looking to conduct a ritual in the libraries beneath Dalaran - most likely to summon this "Agatha" she has become so infatuated with. I\'m afraid this is a little out of my area of expertise, so I\'m going to have to call in a favor.nnI\'ll send for assistance from the Council of the Black Harvest. One of their warlocks will meet you in the Chamber of the Guardian to assist with your investigation.nnI hope we\'re not too late.', `QuestDescription`) WHERE `ID` = 46327;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest', `LogTitle`) WHERE `ID` = 46328;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest', `LogTitle`) WHERE `ID` = 46329;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest', `LogTitle`) WHERE `ID` = 46330;
