UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', '[DNT]Shadow Priests - Elune Death Enabled', `LogTitle`) WHERE `ID` = 46332;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Livin\' on the Ledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to the Fel Hammer and speak with Matron Mother Malevolence.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Slayer $p, Matron Mother Malevolence requests an audience with you back at the Fel Hammer. Please see her at your earliest convenience.', `QuestDescription`) WHERE `ID` = 46333;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Fel and Back', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Kyra Lightblade to secure a ride to Felwing Ledge. Then complete the Felwing Ledge scenario.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Mardum has its fair share of secrets, one of which we found not too long after we took control of the Fel Hammer. It\'s a breeding ground of sorts, festering with fel bats.$b$bWe\'ve been capturing the pups and trying to train them up for our efforts against the Legion.$b$bBut the other day, we caught an even greater prize, something worthy of your position, Slayer.$b$bSpeak with Kyra and she\'ll provide you a ride to the ledge.', `QuestDescription`) WHERE `ID` = 46334;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Vault of the Tirisgarde', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find 5 Ancient Artifacts within the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Dalaran\'s weapons are arcane in origin, but that doesn\'t mean we can\'t try something different. nnOur order\'s vaults contain a vast store of magical devices... Why don\'t you take a look around and see if there\'s anything we can use?', `QuestDescription`) WHERE `ID` = 46335;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Golden Ticket', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Read the Golden Letter in Trueshot Lodge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Huntmaster, we\'ve gotten word from the Lodge that there is a letter wrought from golden light sitting on one of the tables, and it\'s got your name on it.nnNo one is sure how it got there, and someone\'s wolf may have tried to open it and gotten a mouth full of singed fur. Seems like it\'s meant only for you.nnWe\'ll hold down the fort here while you investigate.', `QuestDescription`) WHERE `ID` = 46336;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Night of the Wilds', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ask the Herald of Odyn to take you to the Fields of the Eternal Hunt.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The letter is written in a flowing, golden script. You can practically hear Odyn\'s booming voice speak the words as you read it.>nnThe Night of the Wilds is upon us. nnTonight, we will feast in honor of the beasts of legend, and they will rise once more in the Fields of the Eternal Hunt.nnOne among us will set out into the fields to put their spirits to rest once more. nnMy herald awaits you, hunter, if you will join us.', `QuestDescription`) WHERE `ID` = 46337;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Creative Solution', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Talk to Ari.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Nightborne Soulstone may be our best hope if we can come up with a way to safely use it without Kathra\'natir escaping. If he were to get loose in Dalaran...nnWe should consult with our friend, Ari. She will know what modifications need to be done.', `QuestDescription`) WHERE `ID` = 46338;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keymaster Orlis', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Keymaster Orlis and search his body.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Felborne insurgents appear to be guarding a teleporter pad within the glade ahead. I wonder where it leads?nnIt is probably safe to assume that we\'ll need to kill Keymaster Orlis in order to gain access.', `QuestDescription`) WHERE `ID` = 46339;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Gates Are Closed', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Archmage Khadgar at the Violet Citadel in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Sigryn must be reached before she can confront Odyn, but our path is blocked. Odyn will close the Gates of Valor as soon as he becomes aware of Sigryn\'s assault. You will have to find another way into the Halls.nnI have no talent with portals, but your friends at the Kirin Tor seem to be very adept. Go now to them, and find a way though.nnI thank you for what you\'ve done to help Sigryn this far, $c. I only hope we can save her from herself.', `QuestDescription`) WHERE `ID` = 46340;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Tale of Ban-Lu', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Listen to Master Bu\'s story.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh, hello, you must be the new Grandmaster.nn<Master Bu squints at you and sniffs.>nnYou young ones have no patience these days, always running off to fight your great battles.nnNo time for stories, even good ones, eh?nnWhy don\'t you put your fists down for a moment and allow an old man to tell you a tale.nnMaybe buy an old man a drink while you are at it?', `QuestDescription`) WHERE `ID` = 46341;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Broken Peak', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Master Bu at the Peak of Serenity.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Of course, this is no mere story. Ban-Lu served as the personal mount of each of the previous Grandmasters, accompanying them through their travels as a faithful and trusted companion.nnBut... he has not revealed himself since you have become Grandmaster. This is troubling.nnThe last time he was seen was at the Peak of Serenity, after the fall of Grandmaster Hight.nnIt is there that we must begin our search for him.', `QuestDescription`) WHERE `ID` = 46342;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Trail of Ban-Lu', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow the trail of Ban-Lu.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It seems a lifetime ago that Grandmaster Hight was walking these grounds. nnWhile Ban-Lu has served every previous Grandmaster, he and Hight were the greatest of friends.nnFor many years they traveled the land, connecting with its people and maintaining our fragile peace.nnI cannot imagine how deeply Ban-Lu must have been affected by his passing.nnThere must be some clues to his whereabouts around here. Look sharply.', `QuestDescription`) WHERE `ID` = 46343;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Smelly\'s Luckydo', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 3 parts of Smelly\'s Luckydo.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You! Please help! Stupid hozen stole Smelly\'s luckydo! nnNow, Smelly always unlucky. Just turned around and look, pack is on fire.nnNot going to put fire out because then something ELSE unlucky happen. Maybe something worse!nnYou beat up hozen, yes? Get back luckydo? Smelly will help you, any way he can!', `QuestDescription`) WHERE `ID` = 46344;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into the Hornet\'s Nest', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the teleporter pad.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I hope you are up for an adventure. Shall we see where that teleporter goes?', `QuestDescription`) WHERE `ID` = 46345;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Shadow of Ban-Lu', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Master Bu at the Shado-Pan Monastery.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That was good of you to assist Smelly Mountaintop, Grandmaster, and we have learned more about the fate of Ban-lu.nnI won\'t bother you with escorting me to Shado-Pan Monastery. I can manage on my own.nnMeet me there and we\'ll continue our search.', `QuestDescription`) WHERE `ID` = 46346;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Clean-up on Aisle Sha', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Commander Shen-Li with the remaining Sha.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve spoken with the Shado-pan and they are willing to give us information if we can assist them with a task of their own.nnSpeak with Commander Shen-Li. While you\'re assisting them, I shall continue to meditate.', `QuestDescription`) WHERE `ID` = 46347;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The River to Ban-Lu', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Waterspeaker Ryuli to the southeast.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We still do not know where Ban-Lu has gone to, but I do know who might.nnTo the southeast lives a jinyu, Waterspeaker Ryuli.nnPerhaps he has seen Ban-Lu, or can ask him to inquire with the river about where Ban-Lu has been seen recently?nnAll this travel has done a number on my old joints, Grandmaster. I shall rest here a bit longer, and then catch up with you later on.', `QuestDescription`) WHERE `ID` = 46348;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lilies for Ryuli', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Moon Lilies for Waterspeaker Ryuli.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have not seen Ban-Lu, but the waters will surely know where he is.nnThere is a flower that grows in the lakes of the mountain slopes near the Temple of the White Tiger, that only blooms in the presence of someone pure of heart.nnBring me six of these Moon Lilies and I shall use them to speak to the river.', `QuestDescription`) WHERE `ID` = 46349;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Trial of Ban-Lu', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Ban-Lu at the bottom of the waterfall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ah, the ripples I feel in the water are strong! The droplet does not fall far from our location.nnBan-Lu is quite close. nn<Ryuli closes his eyes and releases the lilies into the water. They drift slowly to the east.>nnHe waits for you now, at the bottom of the waterfall to the east.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Return to Ban-Lu at the Shrine of Inner-Light on the Wandering Isle.', `QuestCompletionLog`) WHERE `ID` = 46350;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Keep it Secret, Keep it Safe', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Ari in the Hall of the Guardian.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The shield generator you found is much more than it appears. I do not think my elders would approve of such advanced technology being shared with outlanders...nnAnd yet... We owe you our lives and our freedom. nnYou may use it, with my blessing. Just... please be discreet about its existence, Archmage $n.', `QuestDescription`) WHERE `ID` = 46351;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vindictive Combatant\'s MailArmor', `LogTitle`) WHERE `ID` = 46352;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Master Who?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Master Bu at Morning Breeze Village outside Temple of the Five Dawns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings. I\'ve just received word that Master Bu has returned from a long spirit journey, and is currently resting his feet at Morning Breeze Village outside of the Temple of Five Dawns.nnIt\'s been quite a long time since anyone has seen or heard from him, but he\'s asking to speak to you.nnWe will handle the situation here while you are absent, Grandmaster.', `QuestDescription`) WHERE `ID` = 46353;
