UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Spiders, Huh?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Look for the rumored treasure in the Creeping Grotto.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I feel like they\'re still crawling all over me. I squished one egg and all of a sudden I\'m covered head to toe in baby spiders.nn<Shivers>.nnThat treasure is just sitting there now. The next guy better not be arachnaphlipic... arachnaphonetic? Arachniphant? Afraid of spiders!', `QuestDescription`) WHERE `ID` = 46499;
