UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tomb Raidering', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Look for the rumored treasure outside the Tomb of Sargeras.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I said to myself over and over, "Don\'t go near the citadel. Don\'t go near the citadel." But what did I do? I went to the citadel. Almost had my hands on that sweet treasure chest before I got chased off by a bunch of crazy demons. I made it out of there with just my helmet and my life!', `QuestDescription`) WHERE `ID` = 46509;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ship Graveyard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Look for the rumored treasure deep in the Forlorn Depths.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I haven\'t told you that I was part of the original landing party when we lost almost everything.  I don\'t care what treasure is left there, I\'ll never go back to that beach. Never.', `QuestDescription`) WHERE `ID` = 46510;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We\'re Treasure Hunters', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Look for the rumored treasure on the Felrage Strand.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have a feeling you\'re just using me for tips on where all the best treasure is. From now on I\'m naga tell you anything. Did I say, "naga" just then? I meant to say, I\'m not gonna to tell you naga. I mean nada! Darn it!nnOkay. Seems you got me on this one. I\'ll tell you what, fetch me whatever is in that chest near those naga freaks and I\'ll make it worth your while.', `QuestDescription`) WHERE `ID` = 46511;
