UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Motherlode', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the cave that Excavator Karla told you about.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Pst... Come \'ere! I just got a tip about a cave on this island that is a treasure trove of loot! This could be my biggest score yet.nnProblem is, I uhh... sprained my ankle. Yeah, I would be right there with you battling those demons to get this treasure, but I shouldn\'t be putting any weight on this leg of mine. Shucks.nnHow about you go check on this cave and report back to me. I\'ll mark your map where the cave entrance is. I\'ve been told it\'s pretty hidden, so you\'ve got to look around.', `QuestDescription`) WHERE `ID` = 46666;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Preservation of Nature', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Thisalee Crow near Deliverance Point on Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I fear this attack on Goldrinn is only the beginning, $n. Whoever is ordering these attacks must be found and defeated.$b$bWasn\'t Thisalee with you? She never returned... brash child. I assume she is already on the Broken Shore, trying to track down this commander. Please, find her. Do not let her take this on alone.', `QuestDescription`) WHERE `ID` = 46674;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To Track a Demon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Impsorrow Missives from demons in Impsorrow Approach.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I took the initiative to scout around before I grabbed that wyrmtongue. It seems like their forces are holed up in a camp in Impsorrow Approach. What I\'ve struggled to figure out, however, is who their commander is and if he\'s nearby.$b$bIf he\'s leading from elsewhere, the troops need to have some commands on them. Let\'s go see if we can find any... on their dead bodies!', `QuestDescription`) WHERE `ID` = 46675;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nature\'s Touch', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Heal $1oa Injured Druids in Impsorrow Approach.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Apparently we\'re not the only druids that have run into these demons. The Legion took a ton of captives and brought them back to their camp. Our brothers and sisters lay wounded and hurting...$b$bYou can heal! Let\'s go save them!', `QuestDescription`) WHERE `ID` = 46676;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prick of a Thistle', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Commander Katith\'rax on Darkstone Isle.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Their commander\'s name is Katith\'rax. He\'s the one who organized these attacks, and now the one who leads them. Luckily, it doesn\'t seem as though he\'s far off.$b$bRight off the coast is a small island. Seems as though he hides there, barking orders without getting his hands dirty.$b$bI, on the other hand, enjoy getting my hands a little dirty. Don\'t you?', `QuestDescription`) WHERE `ID` = 46677;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Legend of the Threads', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Eliezer his lost copy of Nights with the Nightborne', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Tailoring is the noblest of professions because clothing is universal. Most dress with nary a thought. If you analyze the legends, some races stand out from all others. $b$bThe Nightborne are masters of style! Much of the brilliance is in their materials--in particular their thread and their looms. We will take advantage of both. Before you gather materials, I need to confirm my list. Find the fashion treatise I brought with me. Perhaps I dropped it by the flight master?', `QuestDescription`) WHERE `ID` = 46678;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Thread of Shadow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Advisor Vandros in the Arcway in Mythic difficulty and extract Shadow Thread from his robes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Vandros of the Nightborne. There is an elf who knows how to dress. Ever since he was a young noble in the Court of Farondis, Vandros has been known for snappy, fashion forward outfits. $b$bI\'ve never been able to see his garments up close but my research tells me that his tailor\'s technique is not so much in the fabric as it is in the thread. It appears to be spun of the very shadows themselves. $b$bYou have your methods to obtain it, I\'m sure. Get his robes and get the thread.', `QuestDescription`) WHERE `ID` = 46679;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Thread of Starlight', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Advisor Melandrus in the Court of Stars and extract Starlight Thread from his bracers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Melandrus of the Nightborne is First Blade of Elisande. Perhaps you\'ve heard of him? He is a great hero to the Nightborne but, to be absolutely honest, he is a mess with regards to style. $b$bHis accoutrements are somewhat better and a particular pair or bracers are rather nice. In fact, the thead that binds them will be absolutely perfect for your pending outfits. Why don\'t you get that for me and we will talk further.', `QuestDescription`) WHERE `ID` = 46680;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Thread of Souls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Grand Magistrix Elisande in the Nighthold and extract Soul Thread from her wraps.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Have you ever had a chance to lay eyes on Elisande, Grand Magistrix of the Nightborne? Stunning! Fashion-forward! Nice posture! $b$bYou\'d do well to take a page from her book! In fact, you\'d tell well to take the thread from her Suramari Soul Wraps! These hold great symbolic value to her people so it\'s doubtful she will give them willingly. $b$bSo be it, take her out and get that thread.', `QuestDescription`) WHERE `ID` = 46681;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Drapings of the Ancients', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Ancient Imbued Silkweave from humanoids in Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, we are going to need a high quality cloth to work with. Thankfully, the weaving quality of nightborne craftspeople from long ago was very good. It is a lost art to some degree but I feel like you can take their masterworks and do even more with it. $b$bSome of the hostiles in these parts still wear Ancient Imbued Silkweave Armor. Start to unstitch the silkweave cloth from any of that armor that you find on Broken Shore.', `QuestDescription`) WHERE `ID` = 46682;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Starweave and Shadowcloth', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Make a bolt of Starweave and a bolt of Shadowcloth.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'At last, you are ready for true tailoring knowledge. I truly think you\'ve earned it. $b$bI\'ve fashioned the materials you\'ve gathered into a satchel of Legendary Tailor\'s Materials. $b$bGo to the Queen\'s Grace Loom and weave two bolts of cloth. With my careful research of fashion, heroes, and legends. I believe the new cloth you will make will echo through the ages. Hurry!', `QuestDescription`) WHERE `ID` = 46683;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Legend of the Elderhide', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Capture Ancient Wisps in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Leatherworking is one of the oldest forms of craftsmanship in the world. Hides of animals were the first clothing. Legends tell of a particular form of leather curing that has been lost to us in modern times. $b$bCombining magic of the earth with some of the finest leathers ever found, this technique has been recreated by yours truly through careful analysis and my understanding of style. $b$bTo begin, you must capture some ancient wisps to channel the exact nature magic for the curing process.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Capture Ancient Wisps.', `AreaDescription`) WHERE `ID` = 46684;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wisp and the Shadow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Shade of Xavius in Darkheart Thicket on Mythic Difficulty and dye his shroud.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, have you heard of the nightmare lord, Xavius, whose shade haunts Darkheart Thicket? I have heard that this shade is sometimes seen wearing a colorless shroud. $b$bThis shroud is steeped in powerful magic and the wisp will draw it out for you. $b$bIf you can fight the shade, take the shroud, and use your skills to dye it, I will show you how to work wonders!', `QuestDescription`) WHERE `ID` = 46685;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wisp and the Sea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Waterlogged Handmaiden\'s Gloves from the Wrath of Azshara on Mythic Difficulty, then treat them.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Queen Azshara and her handmaidens are the subjects of many a tragic tale. Her power and her hubris lead her badly astray but, even so, her handmaidens are loyal to her to this day. There is power in such a thing. $b$bThe Wrath of Azshara is an abomination but, truthfully, it is actually one of her handmaidens who willing gave her life to protect her queen. Few know this. The Ancient Wisp knows this truth and if you take it to battle the Wrath of Azshara, you may find the handmaiden\'s gloves. Restore them.', `QuestDescription`) WHERE `ID` = 46686;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wisp and the Nightmare', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Get the spellsash from Xavius in the Emerald Nightmare and repair it.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Xavius, the Nightmare Lord in Val\'Sharah, derives some of his power from his spellsash. It is enchanted and tied to the world beneath his feet and cannot be removed from his body. $b$bHowever, with the ancient wisp\'s help, the spellsash can be removed if you can but defeat Xavius in combat. Trivial for one of your skill, I\'m sure. $b$bTake the wisp to the Emerald Nightmare, take the spellsash, and use your skills to repair any damage you\'ve caused in the battle.', `QuestDescription`) WHERE `ID` = 46687;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Leather of the Ancients', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa pieces of Ancient Dreadleather from humanoids in Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, we are going to need high quality leather to work with. Ancient Dreadleather is the best hereabouts and local tanning techniques were exceptional in the past. To the untrained eye, it may look like normal dreadleather. That is where the wisp comes in. $b$bMany of your enemies across Broken Shore will have some amount of ancient dreadleather.  As you defeat them, you will start to recognize armor made from it and you can harvest the leather for our purposes.', `QuestDescription`) WHERE `ID` = 46688;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wisp-Touched Elderhide', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Legendary Tanner\'s Kit in Hrul Sharptooth\'s dwelling in Thunder Totem.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Dreadleather, with knowledge carefully reverse-engineered from ancient texts, can be worked into elderhide. It is partly a matter of advanced craftsmanship and partly a simple magic of the earth. $b$bWith the ancient wisps you caught and the materials you\'ve captured and the research I have done, I have put together a Legendary Tanner\'s Kit for you. Take it to the heirloom hides of Hrul Sharptooth in Thunder Totem. The wisp will help you use the kit there to create Elderhide.', `QuestDescription`) WHERE `ID` = 46689;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Legend of the Wardenscale', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Capture the Father of Owls on the Isle of the Watchers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One of my favorite legends is of the Father of Owls on Isle of the Watchers. It is said that his spirit comes to comfort his creatures during times of trouble. $b$bWith the Legion\'s arrival on the Isle of Watchers, many of the owls are being slain so you can find him there. $b$bWe need to "borrow" him for a short time as he has seen many of the battles where famous warriors and villains have worn armor made of Wardenscale. With his spirit, you can identify items we can extract it from and use it for style!', `QuestDescription`) WHERE `ID` = 46690;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Owl and the Traitor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and repair Cordana Felsong\'s Mantle in the Vault of the Wardens in Mythic difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve scoured the tales and legends for armor that might have Wardenscale components and one Cordana Felsong is a name that caught my attention. $b$bEvidently she has a family mantle that has what we need. Kill her and find it on her traitor\'s corpse. The owl will make sure that you spot it. $b$bIt is likely chipped from years of hard use so restore it to prime condition and bring it back to me.', `QuestDescription`) WHERE `ID` = 46691;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Owl and the Dreadlord', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find and restore the Legplates of Mephistroth by defeating him in the Cathedral of Eternal Night in Mythic Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demon Mephistroth is one of the most powerful of the Nathrezim--the dreadlords. I can see in your eyes that you know what I am going to ask you to do. But it is for your own good! You can\'t keep wandering the lands looking like you do. $b$bMost recently, Mephistroth has been dispatched by the Legion to the Cathedral of Eternal Night. No doubt, he will be wearing some legplates that I believe contain Wardenscale. Take them, shine them up, and bring them to me.', `QuestDescription`) WHERE `ID` = 46692;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Owl and the Observer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill Viz\'aduum in the Return to Karazhan dungeon on Mythic difficulty, and retrieve and repair the Bracers of the First War.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve researched some foul creatures in my time but Viz\'aduum the Watcher may top the list. I mean, he is a giant, disgusting, dangerous eyeball! $b$bCurrently he haunts Karazhan--do you know the place? In Medivh\'s time, much of our common knowledge was stored there. Alas, the time has passed... $b$bI digress. Viz\'aduum is in possession of armor from the First War--bracers to be specific--and they are incredibly valuable. It pains me but take them, repair them, and then we must use their wardenscale.', `QuestDescription`) WHERE `ID` = 46693;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mail of the Ancients', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Ancient Gravenscale from humanoids in Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is some wardenscale scattered here and there in the Broken Isles. Various enemies and local monsters seeking to ape the superior races like ourselves will have picked it up and worn it. $b$bThe kind we need is amongst the oldest ever made. It is ancient gravenscale. Keep all that you find and and bring it to me. We will harvest what useful bits we can from it.', `QuestDescription`) WHERE `ID` = 46694;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prime Wardenscale', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Celea in Azsuna and create the Wardenscale where the magic aligns.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I feel like it is finally time for use to create something truly remarkable. To create the armor that will set you apart from the rest, we need to make the best wardenscale. $b$bFind the nightelf, Celea, in Azsuna. She has attuned and sanctified the ground where she waits to focus the magic of our world and only there can you make what we need. Go with speed, $n.', `QuestDescription`) WHERE `ID` = 46695;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Legend of the Four Hammers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Dalaran and find the Legend of the Four Hammers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, we should be honest with each other before we begin. You are a blacksmith by trade and this a noble profession. Yet I value style and fashion. Heavy armor and weapons create a certain bulkiness in a hero\'s profile that I think does no service whatsoever to the cut of one\'s clothes. $b$bFret not--I can at least teach you something about taste in finer materials. $b$bGo to Dalaran and find a book translated by my brother about 3 forgotten heroes. We will find the finest metals ever forged!', `QuestDescription`) WHERE `ID` = 46696;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Godfighter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take White Lightningsteel from Odyn in the Halls of Valor in Mythic difficulty and forge it into a hammer.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Godfighter championed the mortals against what he saw as oppression and abuse by immortal beings. The legends say the gods feared him but he did fall in time. $b$bMy research shows that the gods he fought were the gods of Stormheim. Odyn, in particular. The Godfighter\'s shield took so much damage from lightning bolts that it became lightningsteel. After the Godfighter died, Odyn took the shield and melted it down as a trophy. Get that lightningsteel from him and forge a hammer from it.', `QuestDescription`) WHERE `ID` = 46697;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dragonhunter', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Dargul in Neltharion\'s Lair in Mythic difficulty and create a hammer from his Red-Hot Draconic Slag', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Dragonhunter lived in a time before history was was written and her tale was passed down orally to us. $b$bIt seems that dragons tormented her people and after her village temple was destroyed, she rallied the local tribes, became a queen and killed all of the dragons. She was then banished for some reason and wandered until her death, alone. What proves the story is a piece of draconic slag from left over from a metal idol in her birth village. Dargul the Underking has it now. Forge a hammer from it.', `QuestDescription`) WHERE `ID` = 46698;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hellslayer', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Helya and forge a hammer from the Frostveined Shale in the Trial of Valor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Hellslayer\'s tale is a classic story of revenge. Odyn wished to take the souls of the bravest as champions but Helya sent her kvaldir to take the souls first. The people of Stormheim suffered as their pawns. $b$bThe kvaldir came to the Hellslayer\'s ship at night and killed her son and took his soul to serve Helya for eternity. The Hellslayer took up her axe and the spear of her son and sought vengeance. Finish her quest. Defeat Helya and forge a hammer from the Frostveined Shale.', `QuestDescription`) WHERE `ID` = 46699;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Armor of the Ancients', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain $1oa Ancient Demonsteel from humanoids in Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is not just the hammers and my careful research that we need, $n. We also need a lot of the very highest quality of ancient metal to make the final hammer. $b$bEnemies across Broken Shore that are able to wear armor often collect bits of Ancient Demonsteel here and there. Collect enough of it in your battles for our purposes.', `QuestDescription`) WHERE `ID` = 46700;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hammer of Forgotten Heroes', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Firmament Stone in Highmountain and forge the Hammer of Forgotten Heroes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, this is exciting, I have to admit. I\'ve put everything you\'ve gathered into this chest of supplies and the only place with the power and magic to handle the creation of the final hammer is the Firmament Stone. I believe that blacksmiths of your rarified skills will know it? $b$bI realize that there are dwarf stereotypes out there about smithing but I really don\'t care for all of the banging and heat. Suppose that is why I followed the scholarly path. Good luck to you!', `QuestDescription`) WHERE `ID` = 46701;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Retaliation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill 7 Felborne Insurgents.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Of course I will help you! Although to be honest, I am not certain where a new arcane shield generator can be found these days. So many of our craftspeople have been executed... I will think on it.nnWould you mind helping me as well? I have been observing a nearby group of Felborne for some time. Their activities have become increasingly brazen of late.nnI think it\'s time to teach them how it feels to be violently suppressed.', `QuestDescription`) WHERE `ID` = 46705;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Minion! Kill That One Too!', `LogTitle`) WHERE `ID` = 46707;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ready for Crafted Legendary', `LogTitle`) WHERE `ID` = 46709;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest', `LogTitle`) WHERE `ID` = 46717;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Amal\'thazad\'s Message', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Amal\'thazad in Acherus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Deathlord, Amal\'thazad has requested your presence at Acherus.nnHe has been in contact with the Lich King, and making improvements on the citadel.nnFor his benefit, or yours, I know not.', `QuestDescription`) WHERE `ID` = 46719;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Frozen Memories', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the portal to the top of Acherus, listen to the Lich King\'s plan, then witness his vision in Icecrown.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Close your eyes, Deathlord. Can\'t you feel his presence already?nn<The Lich King\'s icy presence is inside your mind in an instant.>nnStand in the rune circle atop Acherus, Deathlord.nnI will show you what I have seen.nn<The presence fades.>', `QuestDescription`) WHERE `ID` = 46720;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sulfuron Hammer', `LogTitle`) WHERE `ID` = 46721;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nothing Up My Sleeve', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Akazamzarak\'s Hat to perform a magic trick.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now, you may think that a sack of gold would be a good reward for your troubles, but I\'ve got something better in mind for you.nnI\'m gonna teach you my best trick!nnI know, I know, I\'m a very generous goblin.   Let me show you how it\'s done!', `QuestDescription`) WHERE `ID` = 46722;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Down the Rabbit Hole', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter Akazamzarak\'s Hat and find out what\'s happening to his rabbits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alright, bub. I\'m gonna need you to go in there and find out what\'s going wrong.  I\'d go in myself, but... well, it\'s complicated.nnAnyway, we got no time to lose! Just jump in the hat and find out what\'s goin on.nnI\'ll be ready to pull you out once you\'ve got everything handled.', `QuestDescription`) WHERE `ID` = 46723;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champion: The Great Akazamzarak', `LogTitle`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You know, you\'re a useful $gfella:dame; to have around, $n. nnTell ya what, I think I\'ll accompany you on your adventures. Seems to be good gold in it, and I think it\'ll be a good way to scout out some new business opportunities around the Broken Isles.nnWhat do you say?', `QuestDescription`) WHERE `ID` = 46724;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Power Outage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Refill the Fel Hammer\'s Power Core with fel energy.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Kor\'vass asked for a bunch of other stuff, but it won\'t hurt her to learn a bit of patience. Don\'t you agree?nnShe did mentioned that the ship\'ss weaponss array is severely damaged and dangerously low on power. Knowing her, I\'m sure that\'ss an exaggeration.nnI suppose you may as well take this power core I confiscated. You can replenish it from those disgusting Legion geyserss and energy globess floating around the Tomb.', `QuestDescription`) WHERE `ID` = 46725;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Armies of Legionfall', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort Archmage Khadgar at Krasus\' Landing in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thanks to your leadership, the $c order has grown even mightier than I had dared hope. Alongside champions of the other orders, we now have a fighting force capable of driving the Burning Legion from our world.nnIt\'s time to end this invasion! Using the Pillars of Creation, we will dissipate the Felstorm and seal the Tomb of Sargeras.', `QuestDescription`) WHERE `ID` = 46730;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Prophet\'s Gambit', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Prophet Velen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I can feel their presence just ahead. It is as faint as the lightest breeze that once rolled across these hills, but it is not of the Legion, of that I am certain.$B$BWe must see if these Broken are potential allies. It is a great risk, but our numbers are too few to ignore the chance.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Prophet Velen in Krokul Hovel.', `QuestCompletionLog`) WHERE `ID` = 46732;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Legion Expansion Started Tracking Quest', `LogTitle`) WHERE `ID` = 46733;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Assault on Broken Shore', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the Assault on Broken Shore scenario.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It has been a long and costly war, $n. It is time we put an end to it.nnWe will drive the Burning Legion from their seat of power and close their gateway into Azeroth. Our first step is to gain a foothold on the Broken Shore.nnDivided, the Alliance and Horde faced defeat. But united as the Armies of Legionfall, we will claim victory!', `QuestDescription`) WHERE `ID` = 46734;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Contribute to Command Center', `LogTitle`) WHERE `ID` = 46735;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Contribute to Nether Disruptor', `LogTitle`) WHERE `ID` = 46736;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplies From Highmountain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Ransa Greyfeather in Highmountain for your reward.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Champion, your help to our people has far exceeded any of our expectations, and has provided us some much needed breathing space.nnPlease, take these supplies to aid you in the war against the Legion. With your continued aid, we should be able to gather more and prepare them for you.', `QuestDescription`) WHERE `ID` = 46743;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Greater Power for Greater Threats', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Unlock all traits on any of your artifact weapons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, the war against the Legion grows in intensity beyond what we have imagined. It is critical that we increase our strength to match that of our foes.nnIt is imperative that you strengthen your artifact as much as possible. It is the only way you can stay ahead of the threat the Legion poses.', `QuestDescription`) WHERE `ID` = 46744;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplies From the Court', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Veredis Fallon in Azsuna for your reward.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Prince Farondis has asked me to thank you for your continued efforts to aid our lands.nnPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.', `QuestDescription`) WHERE `ID` = 46745;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplies From the Valarjar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Valdemar Stormseeker in Stormheim for your reward.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, little hero.nnThe mighty Odyn has proclaimed that you should receive these gifts of war. At every turn you continue to prove your valor and your efforts to aid the Valarjar have not gone unnoticed. nnFor the Valarjar! For Odyn! For $n!', `QuestDescription`) WHERE `ID` = 46746;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplies From the Dreamweavers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Sylvia Hartshorn in Val\'sharah for your reward.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hero! nnYour dedication to defending Val\'sharah has given us a much needed respite from the vile influence of the Legion. We were able to scavenge some supplies as a result of your efforts. nnHere, take them and know that, should you continue to aid us, we will set aside more rewards such as these as we find them.', `QuestDescription`) WHERE `ID` = 46747;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplies From the Nightfallen', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with First Arcanist Thalyssra in Suramar for your reward.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Outlander, I have some supplies for you. These goods are yours, earned by your continued efforts to our forces here in Suramar.nnI shall set aside similar treasures should you choose to aid our people more.nnYou have my deepest thanks.', `QuestDescription`) WHERE `ID` = 46748;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplies From the Wardens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Marin Bladewing in Azsuna for your reward.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your dedication to our efforts has yielded results. We have supplies for you.nnContinue your dedication and there will be more.', `QuestDescription`) WHERE `ID` = 46749;
