UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Broken Shore: Investigating the Legion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Discover a hidden Legion threat while on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'While we focus efforts on the Broken Shore, we must be careful to guard against other threats. We have been getting disturbing reports on the Legion starting or supporting indirect threats to Azeroth.nnWhile you are on the Broken Shore, please keep an eye out for strange objects or intelligence that could give us a clue as to what and where these threats are.nnI know it is not a lot to go on, we will do our best from here as well.', `QuestDescription`) WHERE `ID` = 46765;
