UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Relieved of Their Valuables', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find $1oa Hidden Wyrmtongue Caches on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Not all demons on this shore stomp around in the open. Some slink about in the shadows, finding more subtle ways to advance the Legion\'s cause.nnI have been observing the behavior of smaller demons, these wyrmtongues. They seem to spend considerable time acquiring objects of power. We cannot allow them to use these items against us.nnThe wyrmtongues stash their goods in chests spread around the Broken Shore. I suggest you relieve them of their ill-gotten gain.', `QuestDescription`) WHERE `ID` = 46769;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Mage Tower', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete the construction of the Mage Tower.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well done $n. In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Mage Tower.nnAll that remains is for you to inspect our work, and complete the construction.', `QuestDescription`) WHERE `ID` = 46772;
