UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fashion History and a Philosophy of Style', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Learn from Eliezer Hammerbeard how to create "flair and drama" in your wardrobe.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, $n. I am a fashion historian and I have astonishing advancements in tailoring, leatherworking, and blacksmithing that I must share with you. Why? $b$bA true legend is only as good as their ability to form an epic silhouette on the battlefield and--let\'s be honest--this is not where you shine. $b$bSpeak to me again if you wish to learn.', `QuestDescription`) WHERE `ID` = 46804;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Deceiver\'s Downfall', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Tomb of Sargeras and defeat Kil\'jaeden.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Once he was as a brother to me. Then he bartered the soul of my world for his own power. Hounded my people across the stars. Twisted my son into a monster.nnNow he has come to oversee the final assault on Azeroth. To end this world as he has countless others.nnKil\'jaeden.nnWe must ensure he does not escape our grasp this time, $n. Storm the tomb. Break the Legion\'s hold. End the Deceiver\'s reign.', `QuestDescription`) WHERE `ID` = 46805;
