UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Delivering Lost Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the artifact researcher in your class order hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The very nature of this ancient night elf tome causes the book to seek out knowledge. This could prove to be a serious boon to your efforts to research your artifact weapon.nnI\'d wager the scholars in your order hall would find it of great use, possibly unlocking new avenues of empowerment.nnI suggest you take it to them immediately. We need every advantage possible against the Legion!', `QuestDescription`) WHERE `ID` = 46809;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'To the Forge It Goes...', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Gladiator\'s Tattered Cloak to the Obliterum Forge in Dalaran and use the forge to obliterate it, then take the result to Marshal Frazer in Greyfang Enclave.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This cloak is too tattered to be usable, but can be obliterated at the Obliterum Forge in Dalaran.', `QuestDescription`) WHERE `ID` = 46810;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Broodmother\'s Wrath', `LogTitle`) WHERE `ID` = 46811;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Draconic Secrets', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Interrogate Trizormu in Wyrmrest Temple in Dragonblight, then follow the Lich King\'s plan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The Lich King\'s icy presence enters your mind once more.>nnArthas never found the prize he sought, Deathlord.nnIt is ours by right.nnThe dragons must know where the resting place of their kin resides.nnFind a member of the bronze flight, the tenders of history. Do not be merciful.nn<The presence fades.>', `QuestDescription`) WHERE `ID` = 46812;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Lost Glacier', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Lost Glacier.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The Lich King\'s presence is overwhelming.>nnDo you know why the red dragonflight seeks to prevent us from finding our prize?nnThe bones of a great red dragon teem with the essence of life, even decades after its passing.nnYou will consume this life essence, blight it, and turn it to undeath.nnAnd then you will raise a dragon.nnFly now into the north. Find this glacier, and your destiny.nn<The presence fades.>', `QuestDescription`) WHERE `ID` = 46813;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Call of the Frostwyrm', `LogTitle`) WHERE `ID` = 46814;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mac\'Aree, Jewel of Argus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Descend to Mac\'Aree with Velen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The shattered ruin below us is all that remains of Mac\'Aree.$b$bWe called it the Jewel of Argus. It was here that my fellows in the triumvirate guided our people to prosperity. That was a long time ago.$b$b<Velen lapses into a moment of silence.>$b$bJoin me on the surface. We will begin our search for the Crown of the Triumvirate.', `QuestDescription`) WHERE `ID` = 46815;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rendezvous', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Signal Crystal to call down a Lightforged Beacon from the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is much to be done before this nightmare can end, but we need to regroup before we draw more attention from the Legion.$B$BI managed to retain a signal crystal during the crash used to call transport beacons from the Xenedar.$B$BWith luck, we should be able to use it to establish a link between here and your forces as well.', `QuestDescription`) WHERE `ID` = 46816;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Infernal Downfall', `LogTitle`) WHERE `ID` = 46817;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Defenseless and Afraid', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect Stolen Pylon Cores from enemies in Triumvirate\'s End and use them to activate 3 Ancient Pylons.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is the battle that raged while I awaited the Genedar. So many ran to join me, but Kil\'jaeden inspired still more to stand in their way.$b$bMy people were slaughtered without mercy.$b$bTo cover our retreat I ordered for this arena\'s defenses to be activated. It is clear that they were unable.$b$bTo turn the tide in this battle, to give these spirits rest, we must do what they could not. Find a way to activate the pylons.', `QuestDescription`) WHERE `ID` = 46818;
