UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aalgen Point', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Heidirk the Scalekeeper at Aalgen Point.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'You wanna hold territory on this chunder puddle of an island, right? Right. That means linkin\' up with camps on the outskirts, mate. nnI know this bloke called Heidirk. Scrappy fella, loves to get into the thick of it. Headed out to the eastern coast with those drakes of his.nnHave a look for him. Remind him he owes me a pint or two!', `QuestDescription`) WHERE `ID` = 46832;
