UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Khazaduum, First of His Name', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Retrieve the Argunite Keystone from the Echo of Khazaduum.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Argunite Matrix that powered this part of Mac\'Aree was shattered by a hulking beast. We had never seen another like him.$b$bHe was called Khazaduum and he was a most faithful servant of the Legion. He volunteered to undergo an experimental transformation to become the first of his kind. His arrival was the end of this battle.$b$bAs a prize he took the Argunite Keystone from the shattered matrix. Take it back and we can finally end this bloodshed.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Khazaduum was the first to undergo a horrific transformation, granting him strength unlike any known to the Eredar at the time.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Echo of Khazaduum', `PortraitGiverName`) WHERE `ID` = 46834;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Whispers of a Frightened World Tracking', `LogTitle`) WHERE `ID` = 46835;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'From Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Walk with High Exarch Turalyon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m afraid it\'s only a matter of time before our presence is known.$B$BWe must begin our preparations at once.', `QuestDescription`) WHERE `ID` = 46839;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Prisoners No More', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Rescue $oa Darkfallen Slaves from the Annihilan Pits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hatuun\'s people have endured arduous times. Their numbers dwindle as those ripped from beyond the walls of their sanctuary become servants to the annihilan lords in the pits just beyond, sentenced to a life of labor, torture and ultimately, death.nnSeek out these captives, release them from their bonds and show our allies we stand as one against the Burning Legion.', `QuestDescription`) WHERE `ID` = 46840;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Threat Reduction', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Kar\'aaz, Xeth\'tal, and Magraloth in the Annihilan Pits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In time, Hatuun and his people will set aside their bitterness and become valuable allies. But their trust must be earned.$b$bHe says their village is beset by a demon called Aggonar and his cruel kin.$B$BWe need these fiends out of the way before we can seek out Alleria and the others.$B$BThe chieftain lent us his horn. Use it to call down his people\'s vengeance upon the demon lieutenants while I carve a path to Aggonar\'s lair.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Turalyon at the Seat of Annihilation.', `QuestCompletionLog`) WHERE `ID` = 46841;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Strike at the Heart', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Aggonar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These pits have long been a blight upon the lives of our new allies. The demons hunt them down and torture the poor souls for sport.$B$B<Turalyon shakes his head with disgust, fixing his gaze upon the beast before him.>$B$BIt is time to make them pay for their cruelty and restore hope to this Light-forsaken place.$b$bWe strike on your mark, $n.', `QuestDescription`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Aggonar', `PortraitGiverName`) WHERE `ID` = 46842;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Return to the Vindicaar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That pit lord won\'t trouble our new allies any longer.$b$b<Turalyon\'s brow furrows.>$b$bUntil another takes its place, at least. If there\'s one thing I\'ve learned in our endless war against the Legion, it\'s to savor victories as you find them.$b$bCome, let us take a moment to regroup back at your vessel. Alleria and I have been waiting a long time for a reunion with our son.', `QuestDescription`) WHERE `ID` = 46843;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Cathedral of Eternal Night: Mistress of Blades', `LogTitle`) WHERE `ID` = 46844;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vengeance Point', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Legion siege on Vengeance Point and report to Izal Whitemoon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'On my way here, I ran across a squad of demon hunters headed northwest to Vengeance Point. You can bet the Legion will try to stop them from establishing a forward position.nnI spoke to an elf named Izal Whitemoon. Not the friendliest sort, but I\'m sure she\'d be grateful if you lent the Illidari a hand... whether she admits it or not.', `QuestDescription`) WHERE `ID` = 46845;
