UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Council\'s Call', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out the Council of Six in the Violet Citadel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'m sorry that I haven\'t kept your apprised of the situation. We needed more actionable information before bringing the matter before you.nnThe Council of the Six has been investigating Legion threats outside of the Broken Shore. I believe this scroll to be the final piece of information we need.nnMeet me in Dalaran at the Violet Citadel. We will need the other members of the Council.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Seek out the Council of Six.', `AreaDescription`) WHERE `ID` = 47000;
