UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Restoration: The Bradensbrook Investigation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to Bradensbrook in Val\'sharah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a "demonic enclave" just south of their walls. There\'s only one enclave they could be talking about, Bradensbrook!nnIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.nn|cFF660000Specialization: Restoration Shaman|r', `QuestDescription`) WHERE `ID` = 47003;
