UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Beast Mastery: Rumblings Near Feltotem', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Navarrogg at the Misty Coast in Highmountain.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later.$b$bThe drogbar chieftain, Navarrogg, is handling this personally and we\'d like you to meet him near the Feltotem village.nn|cFF660000Specialization: Beast Mastery Hunter|r', `QuestDescription`) WHERE `ID` = 47018;
