UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Protection: Aid of the Illidari', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Kor\'vas Bloodthorn in the streets of Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thankfully, we are not quite alone in uncovering the Legion\'s plots to infiltrate the city.$B$BKor\'vas Bloodthorn of the Illidari has taken to patrolling the city streets on her own to find the source behind the recent attacks.$B$BI do not entirely trust these \'demon hunters\', but they have at least proved adept at their namesake. I suggest you find her and see what she has uncovered before the Legion strikes once more.nn|cFF660000Specialization: Protection Paladin|r', `QuestDescription`) WHERE `ID` = 47022;
