UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shadow: The Twisted Twin', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Karam Magespear at the Legerdemain Lounge in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.nnOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.nnFind Karam in the Legerdemain Lounge and see if you can lend a hand.nn|cFF660000Specialization: Shadow Priest|r', `QuestDescription`) WHERE `ID` = 47042;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Havoc: The Thieving Apprentice', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Xylem\'s Tower within Bear\'s Head in Azshara.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we\'ve been unable to track him.nnFortunately, the thief dropped a note from his master, addressing him as one of his "apprentici." I know of only one mage who uses that particular pluralization - Archmage Xylem.nnI\'ll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to.nn|cFF660000Specialization: Havoc Demon Hunter|r', `QuestDescription`) WHERE `ID` = 47043;
