UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Consecrating Ground', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Repair the Argunite Matrix beneath Triumvirate\'s End.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have everything we need.$b$bIn the alcove below you will find the shattered remains of the Argunite Matrix. Replacing the Keystone will restore it to full capacity.$b$bThe pylons you activated will then be able to repel those who still hunt my people. At long last this battle will be over.$b$bI hope it brings them peace.', `QuestDescription`) WHERE `ID` = 47066;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seeking Lost Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the tome at several night elf ruins on the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'During the assault, our forces uncovered an ancient night elf tome. The fact that it survived so long in these harsh lands is quite remarkable.nnIts enchantments have faded over the ages, but I sense the book is almost... hungry, as if reaching out to places where the night elves practiced magic long ago.nnBringing the tome to nearby ruins may reveal secrets that could give us an edge against the Legion.', `QuestDescription`) WHERE `ID` = 47067;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rare Elite 25', `LogTitle`) WHERE `ID` = 47068;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Delivering Lost Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with the artifact researcher in your class order hall.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The very nature of this ancient night elf tome causes the book to seek out knowledge. This could prove to be a serious boon to your efforts to research your artifact weapon.nnI\'d wager the scholars in your order hall would find it of great use, possibly unlocking new avenues of empowerment.nnI suggest you take it to them immediately. We need every advantage possible against the Legion!', `QuestDescription`) WHERE `ID` = 47069;
