UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Walk to Remember', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Escort King Anduin to Soul Ruin at the Broken Shore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It\'s good to have you at my side, $n.nnI\'ve come to the Broken Shore to see, for myself, the price that my father... that the Alliance has paid to protect our world.nnAs long as I am blind to the suffering and sacrifices of my people, I will never be able to lead them to peace.nnTime is short, we should move onward.', `QuestDescription`) WHERE `ID` = 47097;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arkhaan\'s Pain', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 12 Broken in Oronaar Collapse.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Darkness envelops us... the Light has gone from this place...$b$b<Arkhaan mumbles to himself before noticing you are still talking to him.>$b$bArkhaan could not save them. Brothers. Sisters. Whispers twisted them. The Light cannot see them. It turns away from us.$b$bArkhaan failed.$b$b<Arkhaan stares off into space.>', `QuestDescription`) WHERE `ID` = 47100;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arkhaan\'s Prayers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 5 Fragmented Prayers.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<As you near the statue, a somber voice fills your mind.>$b$b"You must resist the shadow\'s pull. Come to me, brothers and sisters. Be whole within the Light.$b$bLet Arkhaan show you the way home."$b$b<The rest of the message is garbled, though the nearby Broken seem to be gnawing on pieces of the statue.>', `QuestDescription`) WHERE `ID` = 47101;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Mysterious Missive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search near the Xenedar for someone with knowledge of the Sealed Missive.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<On the body, you find a missive emblazoned with the seal of the Army of the Light. $b$bIf the messenger was killed to prevent the letter\'s delivery, its contents must be of great import.>', `QuestDescription`) WHERE `ID` = 47102;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Imprisoned Inquisitor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Vindicaar and ask Grand Artificer Romuul about High Inquisitor Raalgar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This report states that the Legion seeks to free an imprisoned Legion inquisitor called Raalgar, a demon from here on Argus who cannot be killed because of a secret magic he alone possesses. $b$bBecause of his immortality, he is held in the Arcatraz in Tempest Keep.$b$bThe Light Mother told us of that naaru stronghold, but I\'ve never set eyes upon it myself, $n. Turalyon mentioned the Vindicaar has some connection to Tempest Keep. Perhaps your ship\'s engineer knows more.', `QuestDescription`) WHERE `ID` = 47104;
