UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lost Souls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Release $1oa Lost Souls.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Never in my life have I beheld such destruction... such misery. The very ground we walk on us paved with the bones of our allies.nnEven now I can see the lost spirits of Alliance soldiers wandering the ruins.nnI cannot leave this place without putting the souls of our brave soldiers to rest. We owe them... I owe them that much.', `QuestDescription`) WHERE `ID` = 47112;
