UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Champions of Legionfall', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to your class order hall and recruit a new champion.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The battle to reclaim the Broken Shore is straining our resources. We cannot afford to relent, lest the Legion undo all that we have accomplished.nnThe members of your order have given much, but more is needed.nnRally your champions and do what you must to bolster their ranks. There may be untapped power in this land that will turn the tide of war in our favor.', `QuestDescription`) WHERE `ID` = 47137;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Mark of the Sentinax', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Marks of the Sentinax.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Sentinax rains down terror upon the Broken Shore, unleashing hordes of demons that menace our forces. The fiends seek to stop us from taking the Tomb.nnThey will fail.nnLure out the strongest among their vile ranks. Slay them and seize the marks they bear. Make the Legion fear our strength!', `QuestDescription`) WHERE `ID` = 47139;
