UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Something Different', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Win a PvP Brawl.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Even the most bloodthirsty combatants eventually grow weary and turn their backs to the unending struggle of war. They seek a new way to test their mettle and destroy their enemies. nnJoin the Brawl in progress and fight your opponents in a limited time event that tosses traditional rules aside.', `QuestDescription`) WHERE `ID` = 47148;
