UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Pulsing Madness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Dispel 5 Void Manifestations.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This Broken still retains some of his sanity, though not all of it.$b$bI can sense some Void influence nearby, but it is isolated to small pockets. Dispelling these manifestations should help our friend here clear his mind.$b$bPerhaps we can use the prayer fragments you found, as they still contain some Light energy.$b$bI will try and make sense of his chattering in the meantime. Maybe we can learn something about what is happening here.', `QuestDescription`) WHERE `ID` = 47180;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Long Overdue', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Mark the Argussian Heartwells for the Vindicaar\'s guns, kill the Legion garrison, and retrieve the Fel Heart of Argus from High Inquisitor Raalgar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have learned much. High Inquisitor Raalgar has moved to a base near the Legion citadel across the mountains. This is where he keeps the Fel Heart of Argus, the source of his immortality, and it is powered by wells leading directly to the core of Argus. $b$bHe is preparing to attack so you will strike first. Mark the location of the wells and I will rain holy fire upon them with the Vindicaar\'s guns. With that connection to the fel on Argus broken, Raalgar can be killed and the Fel Heart retrieved.', `QuestDescription`) WHERE `ID` = 47182;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arkhaan\'s Plan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Follow Arkhaan to Isolon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Arkhaan remembers. He remembers something that will... yes... will save us.$b$bFollow Arkhaan. Isolon calls! We will offer soft words to the Light. The Light will banish the darkness.$b$b<Arkhaan eyes Alleria warily.>$b$bArkhaan will watch that one closely.', `QuestDescription`) WHERE `ID` = 47183;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Arkhaan\'s Peril', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter the Void Tear and deal with Arkhaan.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Whatever called to him, it cannot have good intentions. We need to go in after him.$b$bBefore we step through this portal, $n... ensure you are prepared to fight. The Void\'s influence is rarely peaceful.', `QuestDescription`) WHERE `ID` = 47184;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Invasion Boss Weekly Bonus', `LogTitle`) WHERE `ID` = 47185;
