UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Personal Message', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Prophet Velen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time has come for me to travel to the Broken Shore and see, for myself, the place where my father died.nnIf I am to be the king my father was... the king Stormwind deserves, I must know firsthand the threat my people face.nnPlease tell my advisors that I\'ve gone to the Broken Shore. If I told them myself they\'d only try and stop me.nnI\'ll wait for you at Deliverance Point. Farewell.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak with Prophet Velen.', `QuestCompletionLog`) WHERE `ID` = 47202;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Throwing Shade', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Investigate the Umbra Hollows with Alleria and Locus-Walker.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That was Locus-Walker. He taught me all that I know about the Void, and he still has more to teach me.$b$bIf he is here, then the ethereals\' presence only intrigues me further. I had thought him the only one of his kind, but now that I have seen another tangling with the Void...$b$bCome, we must play his game if we want to learn what he knows. He appears to have gone toward the Umbra Hollows to the north.', `QuestDescription`) WHERE `ID` = 47203;
