UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sources of Darkness', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deactivate 5 Void Harvesters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I think I understand what he was trying to show us, $n.$b$bI feel a surge of power building ahead. They must be cultivating the Void, calling it here.$b$bWe need to stop them before they plunge this entire city into shadow. Find the source and cut it off by any means necessary.$b$bLocus-Walker and I have unfinished business to attend to.', `QuestDescription`) WHERE `ID` = 47217;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Shadowguard Incursion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 15 Shadowguard Ethereals.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you have surely gathered by now, a certain subset of my people have tragically succumbed to the call of the Void.$b$bI had hoped to find more who possess the necessary strength of mind. I am disappointed to find such an utter lack of resistance.$b$bIt cannot be helped. To advance your cause, and mine, we will need to eradicate these weak-willed beings.', `QuestDescription`) WHERE `ID` = 47218;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Vessel Made Ready', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Nhal\'athoth and collect his heart.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'After some consideration, I have decided to allow Alleria another opportunity to pursue her destiny.$b$bI suppose you want to know what that means, mortal.$b$b<Locus-Walker laughs.>$b$bMeet us deep in the Shadowguard camp ahead- my brethren are preparing a summons that will provide adequate energy for Windrunner to begin again.$b$bWitness what happens when you harness the Void\'s power.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Though only a demi-god, Nhal\'athoth\'s presence haunts the dark corners of Mac\'Aree.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Nhal\'athoth', `PortraitGiverName`) WHERE `ID` = 47219;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Beacon in the Dark', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Remnant of Nhal\'athoth to Velen on the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'That was... an intense experience.$b$b<Alleria rubs her forehead.>$b$bIt is difficult to focus. I need you to return to Velen. Give him this.$b$b<She places something cold and dense in your palm.>$b$bI feel as though he should have it, though I am not sure why.$b$bTell him all that we have learned. I am sure Romuul will have been watching our progress. With any luck, a beacon is already headed our way.', `QuestDescription`) WHERE `ID` = 47220;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hand of Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet your escort to the Exodar at Stormwind Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$p,nnWe have won many battles against the Burning Legion, but it is time to end this war once and for all. nnFinal preparations have begun to depart for Argus.nnMake haste to Stormwind Harbor. A ship awaits you there to grant you and your allies passage to Azuremyst.', `QuestDescription`) WHERE `ID` = 47221;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Two If By Sea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Vereesa Windrunner to set sail for the Exodar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Tomb of Sargeras was only the beginning. If we do not destroy the Legion utterly, they will return even stronger.nnWe will travel to Azuremyst by sea to avoid drawing unnecessary attention. The less time the Legion has to react to our assault, the better.nnJust say the word when you are ready to depart.', `QuestDescription`) WHERE `ID` = 47222;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Light\'s Exodus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Prophet Velen in the Vault of Lights in the Exodar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Prophet Velen and the others have gathered within the Vault of Lights below. There is an entrance just down this path.nnWe should find the Prophet at once so that we do not stall the invasion.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Prophet Velen in the Vault of Lights.', `QuestCompletionLog`) WHERE `ID` = 47223;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Vindicaar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Board the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Everything is prepared for our assault. We need only establish the beacon to transport us to the vessel.nnOnce the beacon arrives, place your hand upon its surface to board the Vindicaar, the instrument of our retribution.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Prophet Velen on the Vindicaar.', `QuestCompletionLog`) WHERE `ID` = 47224;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Seat of the Triumvirate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek the Crest of Knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Even with the Sigil of Awakening in hand, the Crown cannot save us until it is whole.$b$bThat is why we must enter the Seat of the Triumvirate, even knowing that L\'ura awaits us there.$b$bThis is a dire task, one that I would not ask if it were not completely necessary.$b$bWe will descend together. Come.', `QuestDescription`) WHERE `ID` = 47238;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Interesting Times', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Historian Ju\'Pa in the Valley of Spirits of Orgrimmar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I don\'t mean to alarm you, but we may be experiencing some... temporal disturbances.nnHave you ever heard the phrase \'I hope the past doesn\'t come back to haunt you?\'nnCome visit me in the Valley of Spirits and we can speak more.', `QuestDescription`) WHERE `ID` = 47251;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Interesting Times', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Historian Llore in the Royal Library of Stormwind.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I don\'t mean to alarm you, but we may be experiencing some... temporal disturbances.nnHave you ever heard the phrase \'I hope the past doesn\'t come back to haunt you?\'nnCome visit me in the Stormwind Royal Library and we can speak more.', `QuestDescription`) WHERE `ID` = 47252;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Originals', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Lord Kazzak in Blasted Lands, Azuregos in Azshara, and the Dragon of Nightmare at one of the portals to the Emerald Dream.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Long ago, great terrors walked our lands, and drove even the smallest to flights of heroism.nnI speak, of course, about Lord Kazzak, Azueregos, and the Dragons of Nightmare.nnLegends have it that so sought after were their treasures, that armies would camp overnight to hunt them down.nnWe have felt disturbances in the timeways, coincidentally located where these giants once roamed. nnWould you mind investigating for us? Strange things happen during this time of year.', `QuestDescription`) WHERE `ID` = 47253;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Originals', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Lord Kazzak in Blasted Lands, Azuregos in Azshara, and the Dragon of Nightmare at one of the portals to the Emerald Dream.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Long ago, great terrors walked our lands, and drove even the smallest to flights of heroism.nnI speak, of course, about Lord Kazzak, Azueregos, and the Dragons of Nightmare.nnLegends have it that so sought after were their treasures, that armies would camp overnight to hunt them down.nnWe have felt disturbances in the timeways, coincidentally located where these giants once roamed. nnWould you mind investigating for us? Strange things happen during this time of year.', `QuestDescription`) WHERE `ID` = 47254;
