UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Vindicaar Matrix Core', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Link Light\'s Judgment into the Vindicaar Matrix Core.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Much has happened on Argus that concerns me but none moreso than Xe\'ra\'s fate. I wonder sometimes if we are doing the right thing? $b$bBut we must carry on. I can rig the Matrix Core that powers the Vindicaar to allow you to call on the power of our guns when you have need of them on the planet. $b$bGo to the Matrix Core in the room at the heart of our ship. Once linked, whatever powers the core has installed now and in the future will be at your disposal.', `QuestDescription`) WHERE `ID` = 47287;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'World Event Dungeon - Hummel', `LogTitle`) WHERE `ID` = 47290;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Whispers of a Frightened World', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Magni in Sholazar Basin and hear the warning.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Champion, Magni needs your help!$b$bThe Speaker has a message for you, perhaps from Azeroth herself. He seems to be having trouble understanding her, but I\'m sure he can explain everything better.$b$bHe said he was in Sholazar Basin, in Northrend. He should be contacting you shortly.', `QuestDescription`) WHERE `ID` = 47330;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest', `LogTitle`) WHERE `ID` = 47331;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shadow of the Triumvirate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Talgath\'s words carry more gravity than I think he knew. In an attempt to hurt me one final time, he has given us the answer.$b$bThe Crest of Knowledge is hidden away in the Seat of the Triumvirate, and it is not unguarded.$b$bIf my suspicions are correct, we may be facing a greater threat than any of us dared imagine.$b$bA dark naaru.$b$bLet us return to the Vindicaar. We will plan our next steps there.', `QuestDescription`) WHERE `ID` = 47416;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - First Chromie Saved', `LogTitle`) WHERE `ID` = 47424;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moonkin Monitoring', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Observe the nearby dancing, moonfiring, and napping Moonkin Hatchlings and see what you can learn.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Makkaw motions for you to observe the other moonkin in the area.>', `QuestDescription`) WHERE `ID` = 47430;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gathering Light', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Turalyon in the Krokul Hovel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alleria and I long for more time with our son, but we cannot afford to wait any longer, $n. We must strike now.$b$bThe Army of the Light is scattered, but not defeated. Any survivors should have stayed near the crash site of the Xenedar. If there is any hope of victory, we must rally them and rescue Xe\'ra.$b$bWith the pit lords dealt with, we should have a safer route to the Xenedar. Meet me in the krokul hovel as soon as you can.', `QuestDescription`) WHERE `ID` = 47431;
