UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sizing Up The Opposition', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Turalyon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Turalyon was no doubt hoping for better news, but I fear I cannot provide it. Attempting to drive into the heart of the Legion now would cost us everything.nnThere must be another way. I do not know what it is, but I trust that we will find it.nnBest not keep Turalyon waiting. We must move forward.', `QuestDescription`) WHERE `ID` = 47473;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bunker Buster', `LogTitle`) WHERE `ID` = 47496;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Khazaduum', `LogTitle`) WHERE `ID` = 47507;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fire At Will', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter a Lightforged Battery and slay $1oa Frenzied Plaguewings.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Look out there, the wings of the bats fill the sky. We must offer what ranged support we can, but our hands are full here.$b$bIt looks like the Legion has not yet destroyed all of the artillery batteries. If you can get to one, you should be able to show those flying fiends the Light.', `QuestDescription`) WHERE `ID` = 47508;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Disturbance Detected: Black Temple', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Relive the assault on the Black Temple.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, right on time, as always.nnGood news first, because they\'re happening at the same time for me anyway. Thanks to the various timewarped objects past and future you discovered, we\'ve figured out how to detect when a new one turns up.  nnThe bad news is, we know our technique works because something has changed in the Black Temple, and it\'s wreaking havoc across the timescape! We need you to ensure the fateful raid turns out exactly like it did before, and to remove the source of this disturbance.', `QuestDescription`) WHERE `ID` = 47523;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Bringing the Big Guns', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate and secure Light\'s Judgment.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Light\'s Judgment has a security feature to prevent it from falling into enemy hands. We can trigger its recall mechanism, which will teleport it back to a vessel.$b$bWith the Xenedar out of commission, the gun should recall to your ship instead. You can make good use of its firepower.$b$bThe process takes time, though, and will likely attract the Legion\'s attention. Be on your guard.', `QuestDescription`) WHERE `ID` = 47526;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Best Prevention', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay $1oa attackers in the Shattered Fields.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you\'ve brought the High Exarch back to us, you are a welcome ally indeed.$b$bMore is needed of you. You see our soldiers out there, fighting against all odds? Defend them. Slay the enemy.$b$bStrong words for a priest, perhaps, but every dead man\'ari is one less blade at our throats.$b$bShow them that the Light protects its chosen even as it scorches the unfaithful.$b$bWhen you are finished, seek out Y\'mera. She will have fewer troops, and more need of your abilities.', `QuestDescription`) WHERE `ID` = 47541;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Siegemaster Voraan', `LogTitle`) WHERE `ID` = 47542;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Day That Chromie Dies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Chromie, then travel to the future to find out how she dies.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh, $n! I was just thinking about you! Talk about being at the right time in the right place!nnI was just reviewing some aberrations in the timeways, when I discovered something... unexpected. Something not-so-great.nnI\'m going to die in the near future. Bad times.nnI was just about to jump ahead and see if I can figure out why, how, who... but I\'d feel better with |5$r like you by my side. Care to join me?', `QuestDescription`) WHERE `ID` = 47543;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rewind', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Chromie again, then travel to the future and gather information from the other Wyrmrest emissaries.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now we know when the attack happens, and vaguely where it\'s coming from. Progress! All we need to do now is to find out more details and stop that attack!nnLet me know when you\'re ready to try again.', `QuestDescription`) WHERE `ID` = 47545;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Many Advantages of Being a Time Dragon', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Chromie a third time, then travel to the future and attempt to save her again.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Well, unfortunately for... whomever is fixated on blasting me into oblivion, I am a fairly skilled master of the timeways! We have the advantage of trying that again, and again, and again, until I\'m not dead anymore.nnWe\'re going to need a little more than a few seconds to stop this attack. How does four hours sound?', `QuestDescription`) WHERE `ID` = 47550;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lessons of Fire and Pain', `LogTitle`) WHERE `ID` = 47551;
