UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Intercepting the Legion\'s Plans', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search the battlefield for Legion troops and kill them to get their Enigmatic Legion Orders. Retrieve the Army of the Light Code Book to decipher the orders.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our scout Skara writes in the missive that she learned of a major Legion initiative. She was after two encoded orders held by Legion troops near us to get the details and this must be when she was killed. The Legion splits their messages into encoded parts so that we cannot read them. $b$bSkara also writes that her partner Brae, a codebreaker, was slain trying to reach our lines with a code book that we will need to translate the Legion\'s orders. It is vital you find the orders and that code book!', `QuestDescription`) WHERE `ID` = 47554;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Smoldering Chronoshard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Smoldering Chronoshard to Wyrmrest to unlock a time portal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This shard of crystal is hot to the touch. The void creature that carried it wasn\'t a wielder of flame in any noticeable way, so perhaps the chronoshard is related to fire in some other way.', `QuestDescription`) WHERE `ID` = 47557;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fel-Touched Chronoshard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Fel-Touched Chronoshard to Wyrmrest to unlock a time portal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This shard of crystal is scarred with deep rivets of green, malevolent energy. Being held by a dreadlord will do that to you.', `QuestDescription`) WHERE `ID` = 47558;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gleaming Chronoshard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Gleaming Chronoshard to Wyrmrest to unlock a time portal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This shard of crystal glitters with a metallic sheen. Based on Chromie\'s reaction, it may be used to connect you to another time and place.', `QuestDescription`) WHERE `ID` = 47559;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Frozen Chronoshard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Frozen Chronoshard to Wyrmrest to unlock a time portal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This shard of crystal is encased in a thin, frigid layer of permafrost. It still has that distinctive lich smell to it.', `QuestDescription`) WHERE `ID` = 47560;
