UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Righteous Fury', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy $1oa Legion Devastators.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The devastators bombarding our forces prevent us from advancing any further. I can only protect us from their blasts for so long.$B$BChampion, you must pierce their lines and remove the barriers protecting the devastators.$B$BIf you can destroy the anchors that maintain the shields, I can cleanse them from afar.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Prophet Velen at the Crown of Destruction.', `QuestCompletionLog`) WHERE `ID` = 47589;
