UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Wanna Buy a Lamp?', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Purchase the Dubious Lamp from Griftah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ey dere, wanna buy a lamp? You be not regrettin\' it.', `QuestDescription`) WHERE `ID` = 47591;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shine Bright Like a Diamond', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Purchase a Certified Organic Lamp Shining Kit from Griftah and use it to shine the Grimy Lamp.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh, I be sorry. Dat lamp look like it could use some shinin\'. I happen to have just da ting.', `QuestDescription`) WHERE `ID` = 47592;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'I\'ll Take Those, Thanks!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain 10,000 Coins of Air for Griftah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'These coins, dey be vanishin\' inta air ya say? Dat be soundin\' perfect, as I have jus the fella ta give dem to.', `QuestDescription`) WHERE `ID` = 47594;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'I Don\'t Need Them, But I\'ll Take Them', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 10,000 Coins of Air for Griftah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'If you wanna collect more, Griftah not gonna argue with dat. Dat bein\' said, I don\'t need dem as much anymore, so I be givin\' you less for dem.', `QuestDescription`), `AreaDescription` = IF(`AreaDescription` IS NULL OR `AreaDescription` = '', 'Collect 9999 Coins of Air for Griftah.', `AreaDescription`) WHERE `ID` = 47595;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Mysterious, Magnificent Al\'Abas', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Al\'Abas.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I see you, puny mortal! I appreciate your concern for my lamp!', `QuestDescription`) WHERE `ID` = 47603;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'In the Land of Magic', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Al\'Abas... again.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I think I see the problem. Your puny eyes are too weak to detect the mana-infused finery that these elves have spread throughout the land. They\'ve been wearing jewelry the entire time, and you simply couldn\'t see it.nnI propose a partnership, my newly minted associate. My lamp currently suffers from an embarrassing lack of magic and could always use more beautiful decorations. I propose a trade. I shall pierce this sinister veil, and you shall give me the spoils of your theft.', `QuestDescription`) WHERE `ID` = 47604;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Coins of Air', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Al\'Abas yet again.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I would be much interested in these magical trinkets that reside in the pockets of the denizens of this land, and humbly offer my services in helping you acquire them, $n. nnHowever, I sadly cannot pay you in the coin of this realm. What I can offer are ephemera - coins of purest air. They\'re better than nothing, though!nnCarry my lamp with you. Drop the treasures you steal within, and I will grant you these coins. Perhaps the former owner of my lamp would have a use for them.', `QuestDescription`) WHERE `ID` = 47605;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Loyalty Is Its Own Reward', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a thousand Coins of Air.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I offer you a challenge, mortal. Obtain a thousand of my coins, and I believe that I can empower my lamp and the vision within.', `QuestDescription`) WHERE `ID` = 47606;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'High Fash-Djinn', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find rare treasures in the pockets of the denizens of the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With my newly empowered lamp, I sense further, more valuable trinkets in the pockets of these elves and demons. Fetch them for me!', `QuestDescription`) WHERE `ID` = 47607;
