UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Vengeance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the siege weapon at the Crown of Destruction.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Army of the Light will not have fallen in vain.$B$BOur forces will assault the main encampment while we destroy their siege weapon.$B$BThis will be but the beginning of our vengeance.', `QuestDescription`) WHERE `ID` = 47627;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Signs of Resistance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Search for signs of resistance.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our forces sustained heavy losses defending the Vindicaar, $n. We require allies.$B$BThe Army of the Light was known to take in survivors of the Legion\'s crusade to bolster their ranks. We must do the same.$B$BI sense the presence of the Legion slaves you freed nearby. I suspect that they have carved out a resistance against their masters.$B$BI would appreciate your company, $p.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Prophet Velen outside the Krokul Hovel.', `QuestCompletionLog`) WHERE `ID` = 47641;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Soul Crystal', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out the lich hidden within the Ruby Dragonshrine\'s tree.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The three shards combine neatly into a large crystal. Once reassembled, the image of a powerful lich appears above the crystal\'s surface.>nn<The lich speaks:>nnKeep the Ruby Shrinewardens occupied. I shall carry out our master\'s attack from within the great tree itself.', `QuestDescription`) WHERE `ID` = 47642;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Ancients\' Wisdom', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out the satyr hidden in the Emerald Dragonshrine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The three ancients left three clues:nn"...the great nightmare..."nn"...by the water..."nn"...within the dragon\'s palm..."nnPerhaps Chromie\'s attacker lies in the place the ancients describe?', `QuestDescription`) WHERE `ID` = 47643;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Demonic Corestone', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Uncover the dreadlord hidden near the entrance to the Obsidian Dragonshrine\'s cave.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Deep within the demonic corestone, the image of a dreadlord speaks ominously:>nnYes, master. It shall be done, at the exact time that you specified. The bronze dragon will see nothing. One shot from outside the Obsidian Dragonshrine is all I require.', `QuestDescription`) WHERE `ID` = 47644;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Voidcallers\' Scroll', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Seek out the creature of void hidden above the Azure Dragonshrine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The scroll pieces combine to form a tattered, but readable message:>nnThe time is nigh. The invocation will take place above the azure shrine. The void will swallow the bronze dragon. Our master has spoken, and we obey.', `QuestDescription`) WHERE `ID` = 47645;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Rope Around', `LogTitle`) WHERE `ID` = 47646;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Light Mother', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Xe\'ra within the Xenedar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must know for sure whether the Light Mother survived, $n.$b$bXe\'ra was weakened by sending her heart to Azeroth, but she is the prime naaru. She is the Light, and she cannot fade.$b$bLet\'s head into the Xenedar and look for her. Light willing, she will return to guide us once more.', `QuestDescription`) WHERE `ID` = 47652;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Light\'s Return', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Turalyon to return to the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Xe\'ra has been saved! We have won an important victory here.$b$bThe Light Mother should be back on the Vindicaar. No doubt she will want to speak with you. There is so much to explain...$b$bRomuul should be able to teleport us back to the ship now. Let me know when you are ready.', `QuestDescription`) WHERE `ID` = 47653;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Seat of the Triumvirate: The Crest of Knowledge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay L\'ura and retrieve the Crest of Knowledge.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have all that we need now, $n.$b$bAlleria Windrunner awaits your arrival at the Seat of the Triumvirate.$b$bDo not go alone, my friend. You will need allies to recover the Crest of Knowledge... and endure what L\'ura has become.$b$bI will prepare the Vindicaar and await your return. Light be with you in that dark place.', `QuestDescription`) WHERE `ID` = 47654;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'DNT', `LogTitle`) WHERE `ID` = 47658;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'DNT', `LogTitle`) WHERE `ID` = 47661;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Timely Summons from Shattrath', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Vormu in Shattrath.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The blazing star holds a peculiar alignment this cycle, calling out across the heavens. Seek out the sage Vormu in Shattrath City, and lend her your aid.', `QuestDescription`) WHERE `ID` = 47663;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gatekeeper\'s Challenge: Cunning', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect a Fragment of Acuity, Wit, and Guile and combine them into a Mark of Cunning.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archimonde expected greatness from his pupils. Only the most imaginative minds, the most adroit of intellects, could ever truly fathom the deepest reaches of our magic.$b$bI doubt you can relate.$b$bThe path to the left will take you to a set of three statues. Use them to collect a Mark of Cunning.$b$bTo preserve the integrity of this trial, I will not be able to provide hints. If you do, by some miracle, happen to succeed, I will formally recognize your... brilliance.', `QuestDescription`) WHERE `ID` = 47685;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Not-So-Humble Beginnings', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Archmage Y\'mera at the Conservatory of the Arcane.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now we may begin our search for the Crown of the Triumvirate. We will start with the fragment Archimonde carried: the Sigil of Awakening.$b$bTo the east and north you will find all that remains of the greatest school of magic on Argus. It was there that Archimonde gained his mastery of the arcane. I can think of no other place he would stow his treasures.$b$bIt will be guarded, no doubt. We will leverage the expertise of Fareeya\'s forces here to follow this trail.', `QuestDescription`) WHERE `ID` = 47686;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gatekeeper\'s Challenge: Mastery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Grand Vizier Jarasum, Arc-Consul Velara, and High Wakener Aargon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archimonde was an individual consumed by the pursuit of power. Only those who could match his lust would fare well under his tutelage.$b$bYou will fight what remains of Archimonde\'s greatest pupils. These three once held such power in their own disciplines that the Conservatory remembers them now.$b$bTheir echoes will try to kill you.$b$bBest all three with all your limbs intact and I will recognize your strength.', `QuestDescription`) WHERE `ID` = 47687;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Invasive Species', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 30 Partially Digested Arcana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We should seek out an alternate source of energy just in case I am wrong about the conduits.$b$bLuckily enough, I think I know where we can find one.$b$bThe panthara native to Argus are solitary creatures, but it seems whatever magic the Wakeners possessed has drawn them here in great numbers.$b$bThis is no time to be gentle with the environment--panthara devour energy to survive.$b$bSlay them and see if you cannot reclaim some of the power they have consumed.', `QuestDescription`) WHERE `ID` = 47688;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Gatekeeper\'s Challenge: Tenacity', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Overcome the Trial of Tenacity.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My master Archimonde was not known for his willingness to suffer indecision.$b$bHe preferred to teach by rewarding frustration with more frustration-- punishment with more punishment. Absolute conviction was required to succeed under him.$b$bAt the opposite end of the Conservatory you will find a large structure. Once inside, your goal is to overcome all the obstacles placed before you.$b$b Emerge unscathed and I will be forced to consider your will strong enough to proceed.', `QuestDescription`) WHERE `ID` = 47689;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Defiler\'s Legacy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Archimonde and retrieve the Sigil of Awakening.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It seems you are not so easily deterred. Very well.$b$bYour deeds qualify you to seek the Sigil. To be clear, I am only permitting you to move on. This does not guarantee your success.$b$bThe greatest of your challenges lies before you.$b$bYou must go to the Praetorium and face Archimonde himself. Only by defeating the master of the Conservatory will you be worthy of the Sigil.$b$bFew have overcome this obstacle. I hope he does not make too much of a mess of you.', `QuestDescription`), `PortraitGiverText` = IF(`PortraitGiverText` IS NULL OR `PortraitGiverText` = '', 'Archimonde did not know he would become the Defiler, but his pursuit of power did not start when Sargeras arrived.', `PortraitGiverText`), `PortraitGiverName` = IF(`PortraitGiverName` IS NULL OR `PortraitGiverName` = '', 'Archimonde', `PortraitGiverName`) WHERE `ID` = 47690;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Non-Prophet Organization', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Velen.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I have complete faith that Velen is nearby. We would know if he had been captured.$b$bAll the same, we must not delay. The Legion has a vested interest in finding him after all he has done to resist them. I shudder to think what they might do, given the chance.$b$bThat is why I am going with you.$b$bWe will find Velen and help him track down the Crest of Knowledge. We must have faith in his mission or all will be lost.', `QuestDescription`) WHERE `ID` = 47691;
