UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Great Gnomeregan Race', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Race to Booty Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ready for the big race today, $n?nnEvery year, gnomes from near and far gather to run all the way from Gnomeregan to Booty Bay!nnIt reminds us that no goal is too tall, even for us!  Whether you run fast or slow, alone or with friends, you\'ll make it as long as you keep trying! So make sure to stretch, then get out there and show the world what we gnomes are made of!', `QuestDescription`) WHERE `ID` = 47709;
