UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aegwynn\'s Path', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Fragment of the Guardian\'s Seal from the Maiden of Vigilance in the Tomb of Sargeras on Normal Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we sealed the tomb, I entrusted the final piece of Sargeras\' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.', `QuestDescription`) WHERE `ID` = 47725;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aegwynn\'s Path', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Fragment of the Guardian\'s Seal from the Maiden of Vigilance in the Tomb of Sargeras on Heroic Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we sealed the tomb, I entrusted the final piece of Sargeras\' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.', `QuestDescription`) WHERE `ID` = 47726;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Aegwynn\'s Path', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Fragment of the Guardian\'s Seal from the Maiden of Vigilance in the Tomb of Sargeras on Mythic Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As we sealed the tomb, I entrusted the final piece of Sargeras\' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.', `QuestDescription`) WHERE `ID` = 47727;
