UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Child of Light and Shadow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Turalyon to revive Xe\'ra.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is time, $n.$b$bXe\'ra is returned to us. We have Light\'s Heart. We have her Chosen One.$b$bCome, let us restore her. Let us forge a bright new path against our foes.$b$bSpeak to me when you are ready to begin.', `QuestDescription`) WHERE `ID` = 47743;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Smoke, Meat, and Pretty Flowers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain some Salted Venison Jerky, Fras\' Special Pipe Blend, and a Marigold Bouquet.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Back of town\'s on lockdown, kid. And yes, I do have a key, but you\'re a stranger.$b$b<Emery pats his pocket gingerly.>$b$bListen, I\'d like to help you out. You\'ve got an honest look to you. Fetch me some venison, some pipe tobacco, and a bundle o\' yellow flowers, and I might be able to make an exception.', `QuestDescription`) WHERE `ID` = 47744;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Yeah, Definitely for the Kids', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the Marigold Bouquet to Orphan Matron Meliana.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I don\'t know if you\'ve ever seen Orphan Matron Meliana before, but she is a goddess come down to humble Lordaeron. Her hair, those cheekbones, and...$b$b...and anyhow, these flowers are for the kids at the orphanage where she works. Tell Meliana that they\'re from me. For the kids.', `QuestDescription`) WHERE `ID` = 47745;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Holing Up', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Refurbished Military Rifle, Basic Cloth Bandages, and Salted Venison Jerky.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Did... did you see that? Prince Arthas just struck that person down in cold blood! Right in the middle of the street!$b$b<Meliana regains her composure.>$b$bI need to protect the children. Please, help us, visitors. I need a gun, bandages, and some venison jerky.$b$bChildren! Everybody, get into the house!', `QuestDescription`) WHERE `ID` = 47746;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fight Plague with Fire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a Flinty Firestarter and some Heavy Straw Rope.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One final request of you, stranger. I\'ve seen what\'s happening outside, and I\'ve heard about this "plague". I don\'t want to go down without a fight.$b$bI have enough rum in the back of this bar to set this whole tavern on fire, but I don\'t have the tools to do it safely. Fetch me a flint and some rope, and I\'ll give you my key to the backstreets of Stratholme.', `QuestDescription`) WHERE `ID` = 47747;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Holing Up Complete', `LogTitle`) WHERE `ID` = 47748;
