UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'For Emery', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Deliver the Salted Venison Jerky to Emery Neill.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We do have plenty of food here, however. If you\'re braving the streets, please deliver this venison to that big dummy at the tavern.$b$bTell him it\'s from the kids.', `QuestDescription`) WHERE `ID` = 47750;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Winter Veil Gift', `LogTitle`) WHERE `ID` = 47751;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lightly Roasted', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use Light\'s Judgment to destroy the rubble blocking the entrance to the Xenedar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Can you hear me, $n? Good.$b$bLight\'s Judgment has been installed on the Vindicaar. We should be able to harness its power immediately.$b$bWe can use it both to clear the rubble blocking the Xenedar as well as destroy our enemies.$b$bAs with any new piece of technology, we should test it out. Thoroughly. I trust you have plenty of targets down there.', `QuestDescription`) WHERE `ID` = 47754;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Death Metal Knight', `LogTitle`) WHERE `ID` = 47767;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Locating the Longshot', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find Baraat the Longshot.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'re going to need a bigger gun if we hope to free Xe\'ra.$b$bOne of the other bunkers crashed closer to the Xenedar. If Baraat was on it, he will have already begun surveying the area. Perhaps he\'s found the main cannon of the ship.$b$bIf you head over that way, make sure he hasn\'t died, will you?', `QuestDescription`) WHERE `ID` = 47771;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sky Ablaze With Cannonfire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Horde Siege Cannon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh! It\'s me! And $n, was it? I remember this!$b$bI seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn\'t USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away.$b$bThink you could take it out for me?', `QuestDescription`) WHERE `ID` = 47772;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sky Ablaze With Cannonfire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Destroy the Alliance Siege Cannon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Oh! It\'s me! And $n, was it? I remember this!$b$bI seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn\'t USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away.$b$bThink you could take it out for me?', `QuestDescription`) WHERE `ID` = 47773;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unsettled Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring $1oa Writhing Essence to Arcanomancer Vridiel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The release of the energy previously trapped in the Nightwell has... complicated the influence of Aman\'Thul scattered about the Broken Isles. Sadly, the results of my previous work have been invalidated, much like the contents of this vial.$b$bI must understand what has caused this change! Please, bring me more samples so that I may continue my work. It goes without saying that you will be the beneficiary of any breakthroughs I may find.', `QuestDescription`) WHERE `ID` = 47790;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Unsettled Power', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring $1oa Writhing Essence to Arcanomancer Vridiel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'It is deeply disconcerting that the power of Aman\'thul grows increasingly unstable. We must pursue this matter further.$b$bIs this volatility the result of the Legion\'s corruption? No, that is too recent an influence. Something else must have...$b$b<Vridiel trails off absentmindedly, not looking directly at you.>', `QuestDescription`) WHERE `ID` = 47791;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Spoiled Sample', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Spoiled Sample to Arcanomancer Vridiel in Dalaran on the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<You pick up a vial of thick, inky liquid. Its contents react to your touch, boiling and popping furiously for a moment before settling down into a persistent glow. The substance resembles arcwine in this form, but the reaction reminds you of the breakdown of obliterum.$b$bYou tuck the vial in your bags. Someone in Dalaran familiar with the obliterum forge might know more.>', `QuestDescription`) WHERE `ID` = 47793;
