UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Worried About My Friends', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Zorathides at the Obsidian Dragonshrine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve heard about some trouble over at the black dragonshrine. I know, I\'m a bronze dragon, but still! I worry about them sometimes! They weren\'t ALWAYS so grumpy.$b$bIf you\'re going there anyways, would you mind taking care of... whatever\'s causing so much of a disturbance?', `QuestDescription`) WHERE `ID` = 47807;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Dead Walk', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Talar Icechill at the Ruby Dragonshrine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Greetings, $r. I know you are here in the service of the bronze, but I have a request of you.$b$bThe Ruby Dragonshrine is plagued by undead. My shrine\'s wardens were unprepared, and we risk losses if an intervention is not done quickly. Would you assist us?', `QuestDescription`) WHERE `ID` = 47808;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkness in the Ley', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay the Void Gargantuan at the Azure Dragonshrine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A strange, dark disturbance perturbs the ley lines in my flight\'s dragonshrine. Do you have the time to investigate?', `QuestDescription`) WHERE `ID` = 47809;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Darkened Dreams', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Thalas Vylethorn at the Emerald Dragonshrine.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The ancients at the Emerald Dragonshrine suffer in their dreams. With Ysera gone, I am shorthanded and unable to investigate the matter myself. Would you help me cleanse the nightmare from the Emerald Dragonshrine?', `QuestDescription`) WHERE `ID` = 47810;
