UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hand of Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet your escort to the Exodar at Bladefist Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$p,nnWe have won many battles against the Burning Legion, but it is time to end this war once and for all. nnFinal preparations have begun to depart for Argus.nnMake haste to Bladefist Bay. A ship awaits you there to grant you and your allies passage to Azuremyst.', `QuestDescription`) WHERE `ID` = 47835;
