UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Argus Roper', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return $1oa Wild Cragscalers to Lead Rider Jerek.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My warriors stand no chance against even the smallest of the Legion\'s forces without our Cragscalers. If you can capture a few and bring them here, my warriors can better defend our people.', `QuestDescription`) WHERE `ID` = 47967;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Scars of the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Recover an Invocation Array, Vindicator Plating, and a Judgment Core.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Army of the Light\'s warframes have won countless battles on Argus. Despite their power, not all who descend into the fray return.nnMy modifications to this frame should give us the edge we need, but several critical components are still missing.nnThere are remains of battles past in Nath\'raxas that we can still scavenge. If you can find the pieces I need, the Legion will feel our fury yet.', `QuestDescription`) WHERE `ID` = 47986;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Preventive Measures', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Talisman of the Prophet to sanctify $1oa fallen Army of the Light warriors.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is no end to the Legion\'s depravity. Every battle won, every world conquered, yields more souls to fuel their war machine.nnThey have not yet defiled all of the fallen warriors in the hold, but I fear it is only a matter of time. Please, take this talisman with you into the hold and use it to sanctify any corpses you encounter.nnThey deserve a better fate.', `QuestDescription`) WHERE `ID` = 47987;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Chaos Theory', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Nath\'raxxan Fleshcarvers, Nath\'raxxan Doomshots, or Ravenous Soulhunters, and $2oa Nathrezim Banelord.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Despite their strength and their numbers, even the Burning Legion requires order to fight. Disrupt that order... and they fall like the rabble they are.nnThe plan is simple. Let chaos reign in their ranks, and the day will be ours.', `QuestDescription`) WHERE `ID` = 47988;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Heralds of Apocalypse', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay Lady Heretica and Mistress Apostriss.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We\'ve been presented with a rare opportunity.nnOur scouts have spotted two shivarra priestesses in the western fel pools enhancing the Legion\'s war effort.nnThe inner circle of Sargeras\' chosen never leave the walls of Antorus. If we take them out, we might be able to sow fear among those closest to the Dark Titan.', `QuestDescription`) WHERE `ID` = 47989;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Touch of Fel', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect an Immaculate Felcore.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our warframe is almost operational! It just needs a good jolt to revitalize its systems.nnWarlocks in the pools below infuse pieces of Argus with fel energy to create living siege weapons. If you can extract one, we can use it to jumpstart the warframe\'s Judgment Core!', `QuestDescription`) WHERE `ID` = 47990;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Machinations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Dismantle $1oa Spires of Woe.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Eredar are adept at manipulating the fel that courses through this world. Those who do not shape it into living weapons build other armaments, like the Spires of Woe.nnThe spires will make it difficult for even a small force to penetrate the main stronghold. We must dismantle enough of them to clear the way before we advance upon it.', `QuestDescription`) WHERE `ID` = 47991;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dawn of Justice', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Lightforged Warframe to take control of the Court of the Avenger.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Thanks to your efforts, our enemy is in disarray and their defenses inoperable.nnWe must take the ground at the spire\'s base and tighten the noose around their commander\'s neck.nnYou have more than earned the honor to take the warframe into battle. We will follow your lead once the way is clear.', `QuestDescription`) WHERE `ID` = 47992;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Lord of the Spire', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat Lord Nath\'raxas.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lord Nath\'raxas rules over this hold as thanks for his role in delivering Argus to the Legion many years ago.nnMake no mistake, he is powerful, but he has also grown overconfident in his seat.nnTake advantage of his hubris and make use of the warframe\'s firepower while you can. We will storm the courtyard shortly!', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Turalyon on the Vindicaar.', `QuestCompletionLog`) WHERE `ID` = 47993;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Forming a Bond', `LogTitle`) WHERE `ID` = 47994;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Overt Ops', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Locate Baraat the Longshot, Grand Vindicator Sorvos, and Blademaster Telaamon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My soldiers are out there, $n.$b$bI need you to find Baraat, Sorvos, and Telaamon. They were in the process of securing this area for Velen when the Legion came down on top of our heads.$b$bInform them that their orders are to regroup with the Prophet at once.$b$bThe time for subtlety has passed. There is a small army between us and them. Do what you must.$b$bLight keep you safe.', `QuestDescription`) WHERE `ID` = 47995;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Limited Supplies', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Petrified Forest and reclaim $1oa Used Vials.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hello, $n. It\'s good to see a fellow alchemist again.$b$bI\'ve been supplying our camp with necessary potions to deal with the demons, but lately I\'ve been running low on supplies. Normally when scouting parties go out, they return with empty vials, but as of late fewer have been returning.$b$bI try to recycle as much as I can, so you see, those vials are precious to me. If you\'d be willing to go out and retrieve them, I could show you what I\'ve been making to help combat the demons.', `QuestDescription`) WHERE `ID` = 48002;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking the Trackers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Feflame Scavengers at the Annihilan Pits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, have I told you about my tracking potion? Our scouts use it to track demons, especially their "fiends".$b$bThose particular creatures tend to consume the astral glory in the area, making it difficult to replenish our stores of the herb.$b$bIf you could help thin their numbers out, it would greatly help us from having to search elsewhere for supplies. You can find many of them in the Annihilan Pits.$b$bI could also teach you the recipe for this potion for your effort.', `QuestDescription`) WHERE `ID` = 48013;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Ascending Alchemy', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Funen $1oa Astral Glory, $2oa Primal Sargerite and an Infernal Alchemist Stone.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve seen other alchemists come through our camp carrying interesting looking trinkets. I believe they refer to them as... "alchemist stones"?$b$bI can sense the power they radiate, but they appear fel-tainted. The herb that grows on this planet is particularly good at cleansing corruption. I use it to purify the primal sargerite that\'s often found amongst the herbs.$b$bI\'m certain that if we used a purified sargerite with one of those stones, we could elevate the power within it.', `QuestDescription`) WHERE `ID` = 48016;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Chromie', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Reach "Timehopper" friendship rank with Chromie in Dragonblight.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n. Is that you?$b$bI\'m convinced that something unusual has happened in the timelines. I need your help!$b$bCome find me at Wyrmrest Temple, in Dragonblight, and I\'ll show you.', `QuestDescription`) WHERE `ID` = 48021;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest', `LogTitle`) WHERE `ID` = 48022;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Glory of Argus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find someone on Argus who might be able to train you on how to handle Astral Glory.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Amazed that anything so pure could continue to grow on this planet, you pick the flower from the ground. You feel a small power radiate from it and then vanish.>$b$b<As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.>', `QuestDescription`) WHERE `ID` = 48027;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Youthful Resistance', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ask Funen about how to handle the younger Astral Glories.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<As you begin to gather the flowers, you realize that some of the younger blooms are still resistant to your approach and refuse to yield. Perhaps Funen might know more about how to handle the herb in its adolescent stages.>', `QuestDescription`) WHERE `ID` = 48028;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Heart of It', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Ask Funen about the shimmering roots of the Astral Glory.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Having handled astral glory for a while now, you\'ve picked up on something interesting about its roots. Tightly wound in a cocoon, small flecks of light permeate through the cracks creating a shimmering effect.>$b$b<Perhaps Funen might be able to expand on the nature of these lights.>', `QuestDescription`) WHERE `ID` = 48029;
