UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Well of Eternity Scene Seen', `LogTitle`) WHERE `ID` = 48033;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Empyrium Deposit Chunk', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find someone on the Vindicaar who might be able to train you on how to mine an empyrium deposit.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<As you swing your pickaxe into the ore, it hits with a resounding thud, sending a small chunk of it to the ground. At this rate, it would take you all day to get a sufficient amount of ore from this deposit.>$b$b<Perhaps someone can give you some insight into how to mine this deposit properly.>', `QuestDescription`) WHERE `ID` = 48034;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Angling For a Better Strike', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Khamir and see if there\'s a better way to mine empyrium deposits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Looking at the empyrium dust from taking down this deposit, you wonder if there\'s a way to prevent part of the deposit from shattering with each impact.>$b$b<Perhaps Khamir will know something further that he can share with you.>', `QuestDescription`) WHERE `ID` = 48035;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Precision Perfected', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Khamir and see if there\'s an even better way to mine empyrium deposits.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<While you\'ve learned to extract as much of the deposit as you can, the core of the deposit is always left unusable. Looking closely, you can see where your strikes were causing fractures in its structure.>$b$b<One more lesson from Khamir might be needed to correct this problem.>', `QuestDescription`) WHERE `ID` = 48036;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Empyrium Seam Chunk', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find someone at the Vindicaar who might be able to train you on how to mine empyrium seams.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<At first you thought the ore to have a mirrored surface, reflecting the starry space above you. After breaking off a chunk, you realize that the ore itself has a starry quality all of its own.>$b$b<Perhaps someone back at the Vindicaar can give you some insight on how to better extract these seams more efficiently.>', `QuestDescription`) WHERE `ID` = 48037;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Don\'t Just Pick At It', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Khamir about a way to extract more ore from empyrium seams.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Even though you\'ve learned to expose the ore, large chunks of it still seem to be embedded in the surrounding rock. Picking those pieces away may not result in the pure form of empyrium that you\'re looking for.>$b$b<Perhaps Khamir can show you a way to remove the ore from these sections of the seam.>', `QuestDescription`) WHERE `ID` = 48038;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Balancing the Break', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Khamir about a way to extract even more ore from empyrium seams.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Getting down to the root of the seam, you\'re left with nothing but small bits and pieces. Collectively though, they would have been enough to work with.>$b$b<Khamir might know a way to prevent this from happening.>', `QuestDescription`) WHERE `ID` = 48039;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tainted Scraps', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find someone at the Vindicaar who might be able to train you on how to skin fiendish leather.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<As you begin to carefully remove the skin from the corpse, you notice it quickly becoming corrupted by the decay of the creature.>$b$b<Pulling away, you were only able to extract a small amount of leather and something foul smelling. Perhaps someone on the Vindicaar might know more about this foul hide.>', `QuestDescription`) WHERE `ID` = 48040;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Larger Cut', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Enstraa about a better way to remove fiendish leather.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<While you\'ve become quicker at removing pieces of the hide, there is still much that is spoiled before you\'re able to remove it.>$b$b<Enstraa might have a better idea of how to remove more of the hide before it becomes tainted.>', `QuestDescription`) WHERE `ID` = 48041;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Order of Operations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Enstraa about a better way to dissect the beasts of Argus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The skins have been more abundant, but you\'re only able to gather a couple teeth and claws before they take on the corruption.>$b$b<Unsure as to how to extract as many teeth and claws as possible, you find yourself wanting to have one last conversation with Enstraa back at the Vindicaar.>', `QuestDescription`) WHERE `ID` = 48042;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Plating Cleared', `LogTitle`) WHERE `ID` = 48043;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'FLAG - Shields Cleared', `LogTitle`) WHERE `ID` = 48044;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Weigh Anchor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Crate of Felslate to Walcott Sutton at Stormwind Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I was hoping to ask you for a small favor. The naval fleet at Stormwind Harbor have been requesting large amounts of felslate to help construct supplies for their ships.$b$bI\'m pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn\'t mind taking that shipment over there to them?$b$bI heard there\'s a portal to Stormwind in the Greyfang Enclave here in Dalaran so it shouldn\'t be a long trip or anything.', `QuestDescription`) WHERE `ID` = 48053;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Weigh Anchor', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Crate of Felslate to Kruda Thunderhand at Bilgewater Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I was hoping to ask you for a small favor. The naval fleet at Bilgewater Harbor have been requesting large amounts of felslate to help construct supplies for their ships.$b$bI\'m pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn\'t mind taking that shipment over there to them?$b$bI heard there\'s a portal to Orgrimmar in the Windrunner\'s Sanctuary here in Dalaran so it shouldn\'t be a long trip or anything.', `QuestDescription`) WHERE `ID` = 48054;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Empyrial Strength', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft an Empyrial Breastplate. You can find the materials from gathering the ore from Argus, from other players, or from the auction house.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I see my armor\'s caught your interest. It\'s made from the finest material on Argus: empyrium. I actually specialize in crafting breastplates.$b$bI could show you how to craft one, but you\'ll need to bring your own supplies, I\'m afraid. Our stores of the ore are low and we need all that we have.$b$bBut here are the plans so you\'ll know what you need to find...', `QuestDescription`) WHERE `ID` = 48055;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Harsh Mistress', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Help Hobart calibrate the Prototype Gravitational Reduction Slippers around Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'So there I was thinkin\' about how to get everyone ready for movin\' around Argul or whatever it\'s called, since I figure its gravity is different than ours, and I come up with a design for a device you slip onto your shoes, or hooves or whatever you\'re wearin\' down there.$b$bNext thing I hear, the gravity on that planet? Completely the same as ours!$b$bRegardless, I figure I could get the prototype workin\'. Mind givin\' me a hand? Maybe when we\'re done you can like, sell \'em to kids or somethin\'.', `QuestDescription`) WHERE `ID` = 48056;
