UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Extraterrestrial Exploration', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Ionized Geographical Recorder at the locations marked on your map. Return to Didi when you\'re finished.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I hear you\'ve been over to that large green planet in the sky already. Swarming with demons too, I hear.$b$bI was thinking maybe we could put together another wormhole generator for it. Make it easier to zip around the planet.$b$bProblem is we need to get readings on the landscape, and I\'d go, but uh... well I need to stay here and run the shop. Can\'t leave it to these bozos to handle.$b$bHere, take this and get some readings for me, will ya?', `QuestDescription`) WHERE `ID` = 48065;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wrench Calls', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet with Didi the Wrench in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, Didi the Wrench is looking for you back in Dalaran. You might want to see what she\'s working on. Pretty fancy stuff from what I heard.', `QuestDescription`) WHERE `ID` = 48069;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Looming Over Me', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Go to the Arinor Gardens and retrieve Khaela\'s Lightweave Loom.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'When I rallied to the Xenedar, I left behind a valuable tool. My lightweave loom. Without it, I\'m forced to labor for much longer to make garments of power for our allies.$b$bBut you are powerful, much more so than I. Perhaps you could do me a favor. Should you happen to be in the Arinor Gardens, could you retrieve my loom and return it to me?$b$bI\'d be more than willing to share my knowledge of sewing lightweave with you.', `QuestDescription`) WHERE `ID` = 48074;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Colorful Key', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Vorel\'s home and unlock his chest using each of the six gems that come from prospecting empyrium. Recover his jewelcrafting book and return to him on the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, I hear you\'re a jewelcrafter. I too am a master cutter, but I fear my designs will be lost to the Legion.$b$bI hurried out of my home with the intention of returning, but I fear that may not be a possibility. You see, I left my most prized possession, a book of jewelcrafting designs.$b$bBut you, you\'re strong, you could fight your way into my home and recover my book!$b$bHowever, I locked it away in a special chest that requires the gems of this land to unlock. You\'ll need one of each to open it.', `QuestDescription`) WHERE `ID` = 48075;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Crowning Achievement', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Craft an Empyrial Crown for Vorel. You can find the materials from gathering and prospecting the ore from Argus, from other players, or from the auction house.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'With my book nearly being lost forever, it occurs to me that I shouldn\'t keep all this knowledge in one place. I would like to pass it along to you, $n.$b$bMy most recent designs are ones that I am particularly proud of. I call them Empyrial Crowns. Each one uses a different combination of gems to render different effects of power.$b$bLet me show you how to construct one and then I\'ll show you how different combinations of gems create different results.', `QuestDescription`) WHERE `ID` = 48076;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Counterbalancing', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Gather Fiendish Leather and Lightweave Cloth and use Enstraa\'s Tanning Oil to create $1oa Purified Fiendish Leather.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'In the past, I was able to make glorious items from the beasts of this land. But then the Legion came and wiped out all those amazing beasts.$b$bNow I\'m forced to use their polluted hides to craft armor for my allies. I have, however, found a way to remove their taint.$b$bThe cloth we use is made from special thread infused with Light energy. I devised an oil which when combined with the cloth purifies the leather and makes it usable.$b$bHere, take my oil and see for yourself.', `QuestDescription`) WHERE `ID` = 48078;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Floating Ruin', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Mac\'Aree.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We knew the Legion to be a formidable foe, but recent events demonstrate that we do not possess the necessary strength to continue. We have come too far to fail at this critical moment.$b$bI know of a relic on Mac\'Aree, my ancient home, that may be our salvation. We must take the Vindicaar beyond the surface of Argus, to the floating ruin suspended above us.$b$bPerhaps there we will find the salvation we so desperately need.', `QuestDescription`) WHERE `ID` = 48081;
