UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Sigil of Awakening', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to the Vindicaar and secure the Sigil of Awakening.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This relic is too powerful to keep it out in the open.$b$bWe must return to the Vindicaar at once. The Prophet will know what to do.$b$bI did want to thank you, $n. Without you this would not be possible. Quoram would have ensured I never got near the Sigil. Perhaps some day I will share that story with you.', `QuestDescription`) WHERE `ID` = 48107;
