UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Burning Heart', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Navigation Console to travel to the Antoran Wastes.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The loss of Xe\'ra is a blow, especially to Turalyon. But even the Light Mother could not be allowed to force destiny upon us.nnI wish Illidan had found another way to refuse her... but I too have had choices imposed upon me by the naaru.nnThis must not distract us from our mission. Now that we have the Army of the Light survivors with us, it is time to press our attack.nnWe need a foothold on the Antoran Wastes from which we can assault the Burning Throne. It is time to deprive Sargeras of his prize!', `QuestDescription`) WHERE `ID` = 48199;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Securing a Foothold', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to the Antoran Wastes and place the Lightforged Beacon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Alleria and I have scouted this area before, alongside some of our best soldiers. We stationed encampments on either side of our current position, but I fear they will have come under heavy attack. They need reinforcements.$b$bOur first order of business is to set up a teleportation beacon directly below the Vindicaar. From there, we will have access to both fronts.$b$bSpeak to Romuul when you are ready to head down to the surface.', `QuestDescription`) WHERE `ID` = 48200;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Reinforce Light\'s Purchase', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Alleria at Light\'s Purchase.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Now that we have established a foothold, we need to rendezvous with our soldiers in the field.$b$bWe have an Army of the Light encampment to the south, near where the Legion is keeping their strongest warriors in some sort of stasis.$b$bAlleria went to scout the area. Find her, and see what information she has gathered.', `QuestDescription`) WHERE `ID` = 48201;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Reinforce the Veiled Den', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Illidan at the Veiled Den.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The foothold you established allows us to check in with our field operatives.$b$bOn our last mission here, we set up a bastion to the northeast. It should be defensible for now, but that could change at any moment.$b$bIllidan has gone ahead to assess the situation. I suggest you go there and see if he needs a hand.', `QuestDescription`) WHERE `ID` = 48202;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Burning Throne', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Crown of the Triumvirate while above the Antoran Wastes to open the way to Antorus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time has come, $n, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment.$b$bWe will fire Light\'s Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion.$b$bAfter all you have done, it is fitting that you have the honor. Activate the Crown of the Triumvirate and let us finish our mission.', `QuestDescription`) WHERE `ID` = 48203;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fragment of the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Take the Glowing Key Fragment to Captain Fareeya.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Your eye is drawn to the faint glow of the crystalline fragment. Examining the piece, you trace the partial pattern of a rune that had been inscribed upon its surface.nnThe fragment appears similar to the argunite crystals used by the Army of the Light to power their armaments. Could this crystal have belonged to the eredar who fought to escape Argus so long ago?nnPerhaps Captain Fareeya would be able to tell you more about the crystal.>', `QuestDescription`) WHERE `ID` = 48230;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Armor of the Triumvirate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Secure the Armor of the Light and bring it to Archivist Ionaa.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This reforged key will grant entry into the armory inside the Seat of the Triumvirate.nnLocked away inside is the Armor of the Triumvirate, crafted in the days before Sargeras brought ruin to our world. We cannot let this armor be stolen by the Void\'s forces.nnOnce the armor is in your possession, please bring it to Archivist Ionaa. He has collected our most sacred relics in the cave just up the path. No doubt he would be very glad to receive it.', `QuestDescription`) WHERE `ID` = 48231;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Power to Reforge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Obtain a stockpile of Dendrite Clusters.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I forged the key using a pristine argunite crystal. Unfortunately, the only ones remaining are used by the Army of the Light\'s defenses.nnHmm... dendrite clusters might be an alternative. They were used by the elite of Mac\'Aree to power simple devices. If enough of the city ruins are still intact, I\'d wager the fallen magi or the broken may still have some in their possession. nnOf course, I would need a great many clusters to reforge the key. It seems you have your work cut out for you.', `QuestDescription`) WHERE `ID` = 48261;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Recovering the Pieces', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Secure the missing key fragments from the ethereals around the Seat of the Triumvirate.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The fragment you found is only one part of the key. I fear the other pieces have fallen into the hands of these ethereal beings you speak of... the Shadowguard. nnWe must recover them all. The Shadowguard leaders and lieutenants in and around the Seat of the Triumvirate may well have the fragments in their possession.nnGet those key fragments, $n... any way you have to.', `QuestDescription`) WHERE `ID` = 48271;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Visions of Fear', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness Argus\' vision with Magni.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I\'ve done it, $Glad:lass;. I\'ve reached him again! nnOh, but it\'s so painful. So painful! He\'s not doin\' well, not one bit!nnYou\'ll have to listen on in with me to understand.', `QuestDescription`) WHERE `ID` = 48272;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Speaker Listens', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Magni in the Krokul Hovel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Magni has sent for you in Krokul Hovel once more. He seems to have made a new breakthrough in trying to reach Argus.nnI suggest you find him immediately. His last vision foretold Aggramar\'s coming, and there is still so much we do not know of Sargeras\' plans.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Magni in the Krokul Hovel.', `QuestCompletionLog`) WHERE `ID` = 48273;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Speaker Seeks', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Magni in the Krokul Hovel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Our forces are ready for battle, but we still do not know where Eonar\'s spirit lies.nnYou should seek Magni out at once and see if you can find her while we still have a chance. If she falls, nothing we muster will be able stand against Sargeras.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Magni in the Krokul Hovel.', `QuestCompletionLog`) WHERE `ID` = 48277;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Visions of Another', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Witness Argus\' vision with Magni.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Whoever\'s tryin\' to reach us now might give us the information we need to find Eonar.nnWe need to see what\'s goin\' on right away!', `QuestDescription`) WHERE `ID` = 48280;
