UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Antoran High Command', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Defeat the Antoran High Command in Antorus, the Burning Throne.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion has spent over 10,000 years planning their invasion of Azeroth. Defeat their leaders so they can never threaten our world again.', `QuestDescription`) WHERE `ID` = 48288;
