UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'We Have a Problem', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet Turalyon at the Conservatory of the Arcane.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We have a problem, $n. The Legion has come to Mac\'Aree.$b$bWhen you claimed the Sigil it was as if we announced our presence to all of Argus. The eyes of Antorus are firmly upon us.$b$bJust wait. It gets worse.$b$bVelen took Captain Fareeya and her forces into the Arinor Gardens area to search for the Crest of Knowledge. To my knowledge, they are all now behind enemy lines.$b$bCome with me to the Conservatory. We need to bring Velen and the others back before it is too late.', `QuestDescription`) WHERE `ID` = 48344;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Talgath\'s Forces', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Slay 12 of Talgath\'s forces.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I must continue to seek the Crest of Knowledge, my friend. Nothing short of the whole Crown of the Triumvirate can turn the tide in the battle we face.$b$bTalgath\'s forces stand between us and that goal. I will need you to clear a path.$b$bWe can let nothing stand in our way. Not even Talgath.', `QuestDescription`) WHERE `ID` = 48345;
