UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Into the Night', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Travel to Argus aboard the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'What we do this day, we do for Azeroth. For the countless souls lost to the Legion\'s foul crusade.nnOnce you are ready we will take the Vindicaar into the very heart of the Legion.nnArgus awaits.', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Speak to Prophet Velen aboard the Vindicaar on Argus.', `QuestCompletionLog`) WHERE `ID` = 48440;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Remnants of Darkfall Ridge', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Darkfall Ridge Supplies".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My riders have talbuk, but my people need supplies. Food. Tools. Weapons.nnFor millennia, we have migrated from one hovel to the next, moving each time the Legion discovered us. Never able to flee with our possessions, we left them behind.nnYou are powerful, your followers are capable, but you do not know Argus. The landscape will dispatch you as mercilessly as the Legion. Recover our supplies from Darkfall Ridge, and I will order my people to guide your forces through the Argus Wastes.', `QuestDescription`) WHERE `ID` = 48441;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nath\'raxas Hold: Preparations', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise 6 Champions to 900 Item Level.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'One of two fates await krokul prisoners taken to Nath\'raxas Hold. Consume the fel, and become a willing soldier in the infinite army, or be mutated into a disfigured abomination. An ur\'zul.nnWhile the Army of the Light occupies the Legion\'s attention, I am presented with an opportunity to save my people. I ask for your aid.nnBefore we begin, your forces must be adequately equipped.', `QuestDescription`) WHERE `ID` = 48442;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Nath\'raxas Hold: Rescue Mission', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Nath\'raxas Breakout".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your forces are adequately equipped for the mission to save my people from Nath\'raxas. Order your champions to bolster my assault, and together we will dismantle the Legion\'s stranglehold over the region.', `QuestDescription`) WHERE `ID` = 48443;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Ruins of Oronaar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Inches from Madness."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Many krokul wander the city below, shrouded in shadow. I will not accept that they are all beyond redemption.nnArkhaan was a leader, once. Some among his followers may still reside in the ruins of Oranaar, straddling the thin divide between reason and oblivion. Enlist the aid of your order. Scour the ruins for any that can be saved.', `QuestDescription`) WHERE `ID` = 48445;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Relics of the Ancient Eredar', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise 6 Champions to 925 Item Level.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I failed Arkhaan. I won\'t fail again. nnIf there is to be any hope of freeing the krokul, the ethereal threat must be removed from Mac\'Aree. L\'ura has been vanquished, but the void clings heavily near the Shadowguard Incursion.nnBefore we commence, ensure your forces are protected from the shadow. Your champions should seek ancient eredar armaments in the nearby ruins.', `QuestDescription`) WHERE `ID` = 48446;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Shadowguard Dispersion', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Shadowguard Dispersion".', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Lend me the aid of your order once again, that we might end the Shadowguard threat permanently. While you confront the Legion, we will face the void. The attack commences once your forces arrive.', `QuestDescription`) WHERE `ID` = 48447;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Hindering the Legion War Machine', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Gambit in the Wastes."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$ct, I could use your help. The Army of the Light is coordinating an attack against the Spirit Crucible, Terminus, and Shaper\'s Rise to cripple the Legion\'s ability to wage war outside of the Antoran Wastes. We do not have enough soldiers to defend our footholds and execute this operation.nnWill you approach the $cs on our behalf? This gambit could succeed with them fighting by our side. We can paralyze the Legion war machine.', `QuestDescription`) WHERE `ID` = 48448;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Strike Back', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Eredar ritualists and Lady Shahrazad in the Petrified Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'As you may have seen, the ritualists in this forest kidnap our people and perform heinous rituals on them. The souls of our fallen now roam as twisted creatures. This sin cannot go unpunished. Kill as many ritualists as you are able, but be sure to strike at the dark demon that leads them.', `QuestDescription`) WHERE `ID` = 48453;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Duskcloak Problem', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa panthara within the Petrified Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Here in this forest, species of talbuk and panthara still roam. However, the balance has been disrupted and now the panthara risk hunting the talbuk to extinction. To ensure their survival, we must decrease the number of panthara.nnDo not let their suffering linger. A swift death is the most merciful.', `QuestDescription`) WHERE `ID` = 48455;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Tracking Quest', `LogTitle`) WHERE `ID` = 48457;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Wranglers', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak to Lead Rider Jerek in the Petrified Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Great evil exists on Argus and our forests house some of the worst of it. My wranglers are at the edge of the forest and are waiting for reinforcements. That would be you.nnSeek out Lead Rider Jerek, he will tell you more.', `QuestDescription`) WHERE `ID` = 48460;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Where They Least Expect It', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Enter an Invasion Point and defeat a Legion Commander.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion\'s fanatical crusade leaves them spread thin. As they focus their defenses on Argus, we are free to tear into their forces on other worlds.nnTravel through an Invasion Point on Argus and show the Legion that there is no hiding from death.', `QuestDescription`) WHERE `ID` = 48461;
