UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Stranger\'s Plea', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Heal $1oa Felbound Drudges.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'My people... enslaved...nnBeaten... within death\'s grasp...nn<The cowled figure weakly raises his arm, handing you a small liquid skin.>nnHelp... us...', `QuestDescription`), `QuestCompletionLog` = IF(`QuestCompletionLog` IS NULL OR `QuestCompletionLog` = '', 'Meet Prophet Velen at the Crown of Destruction.', `QuestCompletionLog`) WHERE `ID` = 48483;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Moment of Respite', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Artificer Shela\'na, Thelbus Wimblenod and High Priestess Ishanah.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'For all we have seen, we must remember not to dwell on the past, but to look forward and prepare for what is to come.nnTake this opportunity to familiarize yourself with the Vindicaar.', `QuestDescription`) WHERE `ID` = 48500;
