UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hand of Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet your escort to the Exodar at Stormwind Harbor.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ever since the Legion invaded the Exodar, the draenei have been hard at work preparing to return to Argus. At long last they have a vessel that can take us there.nnWith the way to that dreadful world open, we simply could not ask for a better opportunity to strike. Prophet Velen called for you quite specifically to join the assault force.nnYou should make your way to Stormwind Harbor right away. Arrangements have been made for a ship there to take you to Azuremyst.', `QuestDescription`) WHERE `ID` = 48506;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Hand of Fate', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Meet your escort to the Exodar at Bladefist Bay.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Ever since the Legion invaded the Exodar, the draenei have been hard at work preparing to return to Argus. At long last they have a vessel that can take us there.nnWith the way to that dreadful world open, we simply could not ask for a better opportunity to strike. Prophet Velen called for you quite specifically to join the assault force.nnYou should make your way to Bladefist Bay right away. Arrangements have been made for a ship there to take you to Azuremyst.', `QuestDescription`) WHERE `ID` = 48507;
