UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Invasion Point Offensive', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 3 Invasion Points.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The invasion points are key to cutting off Legion reinforcements to Argus. Defeating their armies within the lesser portals will allow us to assault larger invasion points and extinguish the Legion presence within.', `QuestDescription`) WHERE `ID` = 48513;
