UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Strike Back', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Kill $1oa Eredar ritualists and Lady Shahrazad in the Petrified Forest.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The scroll details a dark spell which steals the souls from the neighboring Krokul to create a new demon, the Ur\'zul. The scroll is signed by Lady Shahrazad.', `QuestDescription`) WHERE `ID` = 48542;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Woah, Nelly!', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Return to Chieftain Hatuun in Krokul Hovel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$n, you have my thanks. My Wranglers should be able to take it from here. If I can ask one more favor, would you pass a message to Chieftain Hatuun? Tell him the forest is secure once again. I\'m sure he will reward you for all of your effort.nnI\'ll loan you one of my fastest Cragscalers for the trip. Make sure to look both ways before crossing that path outside this forest, there\'s a giant Legion Obliterator that patrols there. Good luck!', `QuestDescription`) WHERE `ID` = 48544;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Offering of Light', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infuse the Essence of Light into the Netherlight Crucible.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'I sense it. The nobility in Xe\'ra\'s heart. Her relentless defiance of the Legion. Let this be her legacy.nnIn building the Vindicaar, we fashioned the Netherlight Crucible to harness the tremendous powers at play on Argus. I believe Xe\'ra\'s essence is one key to that potential.nnYet the Light alone is not enough. Without balance, there can be no harmony, no cohesion.nnInfuse this essence into the crucible, champion. It is the first step in unlocking the strength needed to end the Burning Crusade.', `QuestDescription`) WHERE `ID` = 48559;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'An Offering of Shadow', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Infuse the Essence of Shadow into the Netherlight Crucible.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Can you sense it, $n? The darkness within this essence is palpable.nnIn the past, I might have shunned such power, even denied its very existence. But what have we learned throughout our long struggle, if not that Light and shadow must coexist?nnThis may prove to be exactly what we need to bring balance to the Netherlight Crucible. To give us the edge we need against the Legion.nnInfuse this essence into the crucible, champion. Draw one step closer to realizing your weapon\'s full potential.', `QuestDescription`) WHERE `ID` = 48560;
