UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Take the Edge Off', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Raise 6 Champions to 950 Item Level.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The demons streaming out of Antorus equip themselves at Felfire Armory. We need to deny those weapons. Will your $cs fight alongside the Army of the Light once again?nnBefore the assault, gather materials. My smiths will craft your soldiers more powerful armor. The Legion won\'t give up Felfire without a fight.', `QuestDescription`) WHERE `ID` = 48600;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Felfire Shattering', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Use the Scouting Map and complete the mission, "Assault on Felfire Armory."', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A thin series of stone bridges connects the Burning Breach to Felfire Armory over Fiend\'s Run. The Army of the Light will stem Legion reinforcements while your people deal with the armory itself.nnWork swiftly.', `QuestDescription`) WHERE `ID` = 48601;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Commander\'s Downfall', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete a Greater Invasion Point scenario.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'A champion of the Legion is vulnerable within an invasion point! Track it down and destroy it before it can return to fight on Argus.', `QuestDescription`) WHERE `ID` = 48605;
