UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Fuel of a Doomed World', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Pristine Argunite from Invasion Points, Rare encounters, or treasure chests on Argus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is a rare and precious resource to be found in these wastes, $n.$b$bArgunite was once abundant on Argus. Its magical properties helped eredar civilization thrive. Far better for us to make use of its power than the Legion.$b$bSeek out all the pristine argunite you can, champion. Every bit you recover will aid our cause.', `QuestDescription`) WHERE `ID` = 48799;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Forging a Key to the Past', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Watch as Gaal reforges the Armory Key.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The armory key fragments are gathered, and the dendrite clusters should provide just enough power to reforge the key.$b$bThis should not take long... assuming it works. It has been a long time since I made one of these!', `QuestDescription`) WHERE `ID` = 48803;
