UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Broken Blacksmith', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Find the blacksmith Gaal.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$C, I believe this may be a piece of the key to the Armory of the Triumvirate. We locked it behind us as we made our escape from Argus. The last time I saw it, my second in command, Atalaa, was leading a force to secure the armory. That was so long ago...nnI cannot be certain, but there may be another who would know. The smith who forged the key was called Gaal. With the reports of broken surviving on Krokuun, he may still live.', `QuestDescription`) WHERE `ID` = 48864;
