UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplying Krokuun', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Order Hall Resources.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more supplies, I could offer you another ridgestalker.nnWhat say you, offworlder?', `QuestDescription`) WHERE `ID` = 48910;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Void Inoculation', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 100 Fragments of Condensed Void.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'All entities touched by shadow leave behind traces of void when they are defeated, If you collect enough in your travels through the city, return to me, and I will distill it into its undiluted form. nnWe can save more of my kin.', `QuestDescription`) WHERE `ID` = 48911;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplying the Antoran Campaign', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 10 Invasion Points.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The Legion requires raw materials from conquered words to fuel their crusade. Travel through Legion portals, destroy demons you encounter, and deny them the resources required to maintain their war machine.', `QuestDescription`) WHERE `ID` = 48912;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Sizing Up The Opposition', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Turalyon.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'No doubt your High Exarch will fret at the news that we lack the resources to assault Antorus. He is not used to believing his vaunted Army of the Light to be inadequate.nnHis pride is no concern of mine. While he plots a new strategy, I will bathe the ground in demon blood.nnGo. There is much to be done before we can achieve our final victory.', `QuestDescription`) WHERE `ID` = 48929;
