UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Blood of a Titan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the blood of Argus the Unmaker to Khadgar in Dalaran.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<Before your eyes, a trickle of blood from the fallen titan Argus congeals into a flawless gemstone. Holding it in your palm, you sense an almost unfathomable power emanating from within... along with echoes of pain and sorrow.nnIt is the last remnant of a battle that should not have been winnable. An impossible achievement. Yet, as with all victories, this one came at tremendous cost.nnYou realize immediately to whom you must convey this prize.>', `QuestDescription`) WHERE `ID` = 48954;
