UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Paragon of Argussian Reach', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Toraan the Revered on the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your allies among the Argussian Reach have requested your presence. They wish to reward you for your continued efforts on their behalf.', `QuestDescription`) WHERE `ID` = 48973;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Paragon of the Army of the Light', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Vindicator Jaelaana on the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Your allies in the Army of the Light would like to thank you for your continued support. They await you on the Vindicaar.', `QuestDescription`) WHERE `ID` = 48974;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplies From the Argussian Reach', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Toraan the Revered on the Vindicaar.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '$ct, thanks to your efforts, our forces have been able to locate resources and prevent them from falling into the Legion\'s hands.nnWith your continued assistance, we will be able to provide additional resources.', `QuestDescription`) WHERE `ID` = 48976;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Supplies From the Army of the Light', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Vindicator Jaelaana on the Vindicaar for your reward.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Archenon poros, champion.nnThe Army of the Light wishes to thank you for your aid against the Legion\'s forces on Argus.nnPlease accept these supplies with our gratitude. Your continued support brings us ever closer to our ultimate goal of eradicating the Legion once and for all.', `QuestDescription`) WHERE `ID` = 48977;
