UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Burning Throne', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Speak with Grand Artificer Romuul while above the Antoran Wastes to open the way to Antorus.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The time has come, $n, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment.$b$bWe will fire Light\'s Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion.$b$bAfter all you have done, it is fitting that you have the honor. Speak to Romuul and let us finish our mission.', `QuestDescription`) WHERE `ID` = 49014;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Death of a Titan', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Strike down the soul of Argus in Antorus, the Burning Throne.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'There is no way to express the depth of my sorrow. My rage. What Sargeras has done...$b$bArgus, my home world, holds the soul of a titan. It has been twisted and corrupted beyond redemption, its power harnessed to fuel the Legion\'s infinite army.$b$bWe must do the impossible... breach the depths of Antorus and sever the Legion\'s connection to the world soul.$b$bPlease, $n. End its pain, its suffering. In striking down the dark heart of Argus, we will defeat the Legion... and redeem the soul of my world.', `QuestDescription`) WHERE `ID` = 49015;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Passage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Normal Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks.nnIf we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.', `QuestDescription`) WHERE `ID` = 49032;
