UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Dark Passage', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Heroic Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks.nnIf we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.', `QuestDescription`) WHERE `ID` = 49075;
