UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Moments of Reflection', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring Illidan\'s crystal to the people and places closest to him.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<The crystal calls to you, resonating with sorcerous magic.nnAs you take hold of it, you hear the echo of a message left behind, a duty Illidan entrusted to you.>', `QuestDescription`) WHERE `ID` = 49077;
