UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Heart of Argus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Normal Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet\'s core. Little is known of it, for only the titan\'s most devoted acolytes are given sigils that permit entrance.nnIf we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.', `QuestDescription`) WHERE `ID` = 49133;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Heart of Argus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Heroic Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet\'s core. Little is known of it, for only the titan\'s most devoted acolytes are given sigils that permit entrance.nnIf we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.', `QuestDescription`) WHERE `ID` = 49134;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Heart of Argus', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Mythic Difficulty.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet\'s core. Little is known of it, for only the titan\'s most devoted acolytes are given sigils that permit entrance.nnIf we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.', `QuestDescription`) WHERE `ID` = 49135;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Essence of the Light Mother', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Collect $1oa Vestiges of Light.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'This is a crucial moment, $n. Our campaign must not lose momentum.nnThough she has fallen, I still sense Xe\'ra\'s presence all around us. The Light that shone within her heart can yet be a source of strength for our cause.nnNo doubt the loss of Xe\'ra has deeply wounded Turalyon. I will do what I can to ease his troubled spirit while you gather the vestiges of the naaru that remain.', `QuestDescription`) WHERE `ID` = 49143;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Greater Invasion Point: Pit Lord Vilemus', `LogTitle`) WHERE `ID` = 49196;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Netherlight Crucible', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Imbue a relic with Netherlight Fortification using the Netherlight Crucible.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The crucible thrums with power. Soon our weapons will shine like the stars themselves!nnWe will need that strength if we are to have any hope of defeating the Legion here.nn$n, you have endured great hardship to bring us to this moment. The honor of first tapping the crucible\'s power must be yours.', `QuestDescription`) WHERE `ID` = 49224;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'Invasion Onslaught', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Complete 3 standard Invasion Points.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'We must not yield even a single world to the Legion. Continue our Invasion Point offensive and crush the Legion beneath your heel.', `QuestDescription`) WHERE `ID` = 49293;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Prime Exchange', `LogTitle`) WHERE `ID` = 49445;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Titanic Effort', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring $1oa Wakening Essence to Arcanomancer Vridiel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'Illidan may have forced fate\'s hand, but bringing Argus so near to Azeroth has accelerated the reaction triggered by the Nightwell\'s collapse.nnI believe the Legion\'s actions on Argus are further destabilizing the powers we\'ve drawn upon unknowingly for many years.nnIt is clear that further studies are required.', `QuestDescription`) WHERE `ID` = 49472;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Titanic Effort', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring $1oa Wakening Essence to Arcanomancer Vridiel.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', 'The reaction\'s intensity is accelerating by the day. We may win the fight against the Legion only to lose something very dear to us.nnIs this a portent of some greater upheaval to come? What fate awaits our world, $n?nnI will seek answers at my forge, as I have done all my life. Your answers, I suspect, lie elsewhere.', `QuestDescription`) WHERE `ID` = 49473;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'The Cursed Shard', `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', 'Bring the Cursed Shard to Arcanomancer Vridiel in Dalaran on the Broken Isles.', `LogDescription`), `QuestDescription` = IF(`QuestDescription` IS NULL OR `QuestDescription` = '', '<A unnatural metallic shard catches your eye as it shifts from color to color. At your touch, one end of the shard swells in size before melting away. Droplets hit the ground with a hiss and a noxious stench invades your nostrils.$b$bSomeone in Dalaran who works with metals should be able to tell you more.>', `QuestDescription`) WHERE `ID` = 49474;
UPDATE `quest_template` SET `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', 'A Gently Shaken Gift', `LogTitle`) WHERE `ID` = 50420;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Very good, very good! You\'ve done well, $N. Perhaps the interest that is being shown in you is deserved, after all.$b$bThat\'ll be for the others to decide--assuming your imp doesn\'t overpower you and nip your career in the bud. For now, I\'m satisfied that you\'ll probably survive your first few months as a %C.$b$bA word about the imp, $N. As a $R knows, don\'t let its size fool you, its magic can be very dangerous.', `RewardText`) WHERE `ID` = 1599;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Here in Stormwind, I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.$B$BThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.', `RewardText`) WHERE `ID` = 1641;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Hello again, $N. How goes your studies of the Tome of Divinity?$B$BThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.$B$BBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind.', `RewardText`) WHERE `ID` = 1642;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Oh, hello, luv. How go your adventures? Oh, I\'m so glad to hear you\'re doing well.$B$BOh, me? Thank you for asking--I\'m doing well, all things considered.$B$BThe increase in tradesmen has kind of put a damper on the amount of leather and cloth people are willing to part with these days, so it\'s been tougher to make clothing for the children at the orphanage, but we\'ll manage. By "we" I mean my husband and I. He\'s up in Ironforge trying to seek help from the citizens there.', `RewardText`) WHERE `ID` = 1643;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thank you, $N, thank you so much!$B$BThe children will be so pleased, and you\'ve saved me so much time. I\'ll now be able to focus on the children\'s other needs, and hopefully my John will be able to return home sooner than we thought.$B$BThank you again, $N. I knew I could rely on the charity of others. The Light be with you.', `RewardText`) WHERE `ID` = 1644;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Hello, $N. I\'m assuming by all that armor and weapon of yours, you\'re either here to try and take my land, or the Church finally sent someone to help protect me while my Jordan\'s gone.$B$B Well, let me introduce myself: I\'m Daphne Stilwell. It\'s a pleasure.$B$BNow, you\'re not too late... I\'ve only killed a half dozen of the scum since last sun up. They\'ve been a little slow getting \'round the bend up there, but they probably saw you coming, which means they\'ll probably be here any minute.', `RewardText`) WHERE `ID` = 1650;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'We\'ve done it, $N! Thank you for your help. You were truly amazing out there. I never thought a $C could handle so many enemies at once.$B$BYou\'ve truly shown bravery in the face of overwhelming odds.', `RewardText`) WHERE `ID` = 1651;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'So, we meet again, $N, and you are in high spirits, I see.$B$BThe Stilwell home will be safe for another day, and from your story I see that there was no shortage of danger to be found. Well done.$B$BDaphne and Jordan have helped the Church greatly, and having you protect their property--and their very lives--was the least we could do for them.$B$BFor your valor, you will be rewarded.', `RewardText`) WHERE `ID` = 1652;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Good day, $n. The Light is with you, I trust?$b$bWhat\'s that? You were sent by Duthorian!? My wife, how is she? I knew there was going to be trouble if I left. Please tell me she\'s... oh, thank goodness. I\'m so glad that she\'s safe. The Defias were a threat long before these attacks, but now the King\'s advisors cannot deny it.$b$bWhat else did Duthorian have to say?$b$bYou\'re the one that was sent to protect my wife? Then I thank you again, $n. I couldn\'t think of a better test of valor than that.', `RewardText`) WHERE `ID` = 1653;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Surena was talented, but not enough so to gain mastery of $C magic on her own. It\'s a shame to see talent wasted, but sometimes it is necessary.$B$BI hope my investment in you will bear different results.', `RewardText`) WHERE `ID` = 1688;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Tome of Cabal? Hmm...sounds familiar. I have never seen it here before, though--and believe me, I remember every book I read. $B$BHmm... Ah, yes!$B$BI have seen reference to it in library cataloging books.', `RewardText`) WHERE `ID` = 1758;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You\'ve returned so quickly, $N. And what have you accomplished in your time away from the Cathedral?$B$BHave you helped a noble cause? Perhaps you\'ve learned the value of charity or some more about your obligations to the citizens of Azeroth. Tell me, who have you helped and how... Well, I\'m impressed, $N, those are surely the actions of one who follows the Light and values others above oneself.$B$BSuch sacrifice will always be rewarded in time.', `RewardText`) WHERE `ID` = 1780;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', '*cough*$B$BPleasure to meet you, $R. Don\'t mind my wounds, the good priest here can take care of ol\' Gazin this time. I won\'t be needing the power of that Symbol of Life you\'ve got there... not yet anyway.$B$BSo, Duthorian sent you to speak to me, huh? Fair enough. I\'ll tell you exactly what befell me and my friend Henze. And with any luck, and some skill on your part, perhaps you can still help us all.', `RewardText`) WHERE `ID` = 1781;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thank you, $Gbrother:sister;.$B$BSeeing you wield the Symbol of Life, may I assume Duthorian or Gazin sent you?$B$BI fell to the Defias spell casters while Gazin and I tried to get their plans from them: I was able to hold on long enough to allow Gazin to escape, but in the end, their magics overwhelmed me.$B$BBut you were able to bring me back: the ability to use the Symbol doesn\'t come to just anyone, $N. It bodes well for you that you were able to empower it with your own faith.', `RewardText`) WHERE `ID` = 1786;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Wonderful! You made it, and saved Henze. The Light is with you for sure, $N!', `RewardText`) WHERE `ID` = 1787;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Make haste, $N, more than one life hangs in the balance if you fail.$B$BIf for some reason you fail to help Gazin and Henze, then return to me and I will give you another Symbol of Life for your travels.$B$BDon\'t mistake my aid as simple charity, you must prove yourself worthy like any other $C and continual failure may reflect upon you later.', `RewardText`) WHERE `ID` = 1790;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It has been proven that the Light is with you, $N, but as times grow more dangerous, it becomes important to know what strength lies beneath the flesh. When demons, dragons, or any other evil set foot in your lands, your mettle will be tested. Will you be strong enough?$B$BBravery, regardless of the situation, is as much a part of paladinhood as the Light, your armor, and your weapon. Protecting the weak, and not losing faith are two more lessons you must master while you study in the Cathedral of Light.', `RewardText`) WHERE `ID` = 1793;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'This will do nicely, $N.$B$BAll magical items must begin with an item of high quality. The more effort and skill put into an item, the greater the magics it can hold. Rare and more expensive components hold the magic better. You will not regret having the robes fashioned into the ones we will make for you later on.', `RewardText`) WHERE `ID` = 1796;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', '$N? Ah, of course. Our latest prodigy. The real thing can not live up to the legend, I am afraid. $B$BNo matter, you have come here to learn, not to hear me make jokes to myself.', `RewardText`) WHERE `ID` = 1798;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Oh, so Menara sent you. Fair enough... I suppose you may stay as my guest for the time being. But you must be on some pressing business - perhaps you\'re here seeking lost power? Maybe I\'m mistaken. Maybe corruption isn\'t too far away from you after all.', `RewardText`) WHERE `ID` = 1799;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Well done! The Tome of the Cabal and three pristine--slightly scratched, I suppose--rods of channeling.$B$BThis will be interesting. It\'s been some time since a young $C took on a felhunter to make his own.', `RewardText`) WHERE `ID` = 1804;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It is beautiful here in Stormwind, is it not?$B$BYour timing actually couldn\'t have been better, $N.', `RewardText`) WHERE `ID` = 2998;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Now we teach them those things, and they teach us others. We become one race... almost. We be allies for long time now. So you remember to help them. And Jen\'shan remember to help you.$b$bJen\'shan teach you da ways of the $C--teach you good. You never forget, $C\'s be respected greatly by da tribe. You be havin\' a large role to play in da future... you never forget that.$b$bWhen you feel da need, come to Jen\'shan. She teach you as much as she can when she feel you ready.', `RewardText`) WHERE `ID` = 3082;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Ah, Demisette sent you. Good. Then word does reach far enough to find future students. This pleases me.$B$BIt is typical of our kind, $N, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.$B$BI feel you\'ve learned a great many things, and if you are willing, I would help you create tools to compliment your skills.', `RewardText`) WHERE `ID` = 4738;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Perfect, $N. I\'m glad you could find a miner to help you out so quickly. Or did you do this work yourself? Either way, you\'ve done well. This will be perfect for the thread.$B$BIt will take some time to create the stuff, so you\'ll have to come back--I actually send it off to some princess who we have locked in a tower who\'s only job is to spin gold thread... no, seriously. I mean it... okay, not really.', `RewardText`) WHERE `ID` = 4781;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Good, you\'ve returned, $N. And where is the thread?$B$BAh, I understand. That is acceptable. The goblin and his brother have not failed us yet--I suppose it is understandable that he did not have it prepared right then. So be it... we have other things we can attend to in the meantime.$B$BAre you prepared for the next step?', `RewardText`) WHERE `ID` = 4782;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Excellent, $N. These will do nicely. I will prepare them now while you move on to your last two components. Are you ready?', `RewardText`) WHERE `ID` = 4783;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Excellent, $N! The components are gathered and we are ready.$B$BI trust you will be pleased.', `RewardText`) WHERE `ID` = 4784;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Here you go, $N. And please tell Menara we say hello.$B$BWe expect great things of you. Perhaps when the Legion falls to its knees, your name will be spoken aloud and in praise of your power. I can\'t wait!', `RewardText`) WHERE `ID` = 4785;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It is done, $N. Here you are. Wear it with pride.$B$BYou\'ve worked hard and I see great things in your future. Remember, to defy the corruption that comes with our path takes great will and fortitude. As long as your will is your own, then you shall have great success.', `RewardText`) WHERE `ID` = 4786;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Nicely done, $N!  You gave that demon a lesson he won\'t soon forget. You\'ve shown great power and skill. Now I suppose it\'s time you return to Menara with your cleansed orb so you can put it to good use.$B$BGood luck, $C. Perhaps our paths will cross again.', `RewardText`) WHERE `ID` = 4961;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Ah, the spirit of an infernal. Well done, $N.$B$BWhen I have both the spirit and the cleansed orb, I will merge the two for you, but not until then.', `RewardText`) WHERE `ID` = 4963;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It is done, $N. Simply tell me which you\'d prefer: a staff that would require you to use both hands, or an orb so you may use a dagger or sword as your weapon.$B$BTackling the infernal was a great feat on your part and this reward will fit you nicely. I wish you further success in the arts, $N.', `RewardText`) WHERE `ID` = 4975;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Well done, $N. This will do nicely.$B$BThe only thing left for you to do is to decide on which demon you want me to imprison within the cleansed orb. Do that, and you will have a magnificent new item to wield.', `RewardText`) WHERE `ID` = 4976;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Oh, so Branstock sent ya, did he? Good, good! He\'s right, it is \'bout time you started taking a much larger step into the Light. It\'ll build character and make ya stronger... an\' that\'s what you\'ll need more than anything: strength of body... strength of will.', `RewardText`) WHERE `ID` = 5626;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'A deal is a deal! Quickly, take this and write this down. I don\'t have time! My greatest conjuration is upon us!', `RewardText`) WHERE `ID` = 7603;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'There is risk in dispelling the evil from a scourgestone, for it attracts the attention of undead for countless miles.  But you are strong in the Light, $n, and I do not fear for you...', `RewardText`) WHERE `ID` = 8414;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'This will work so very well.', `RewardText`) WHERE `ID` = 8421;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Good, good.  Maybe they\'ll think twice before slacking next time!  Thanks for the help!', `RewardText`) WHERE `ID` = 37446;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'The forest already whispers of Malfurion\'s return. There are few among us who have not heard of his deeds.$B$BThe trees said he also travels with a companion, one named $n. Are you $Ghe:she;?', `RewardText`) WHERE `ID` = 38142;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', '<The Archdruid\'s deep, shallow breaths rumble across the chamber.>', `RewardText`) WHERE `ID` = 38143;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Excellent. The chambers are clear. Very impressive, $c.', `RewardText`) WHERE `ID` = 38144;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Well done, hero. With my brethren at my side, we will be ready to aid Malfurion.', `RewardText`) WHERE `ID` = 38145;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'In my dreams, I saw the satyr\'s leader. His face was familiar, though I could not see it clearly.$B$BI pray to Elune that it is not too late. I will go to Malfurion at once.', `RewardText`) WHERE `ID` = 38147;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'May peace again fill our sacred grove.', `RewardText`) WHERE `ID` = 38225;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Your arrival was a blessing, friend.$b$bAnde\'thoras-ethil.', `RewardText`) WHERE `ID` = 38235;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thank you, $n! My nephew is returned to me.$B$BHe explains that the source of the madness comes from a powerful totem, deep in our village. $B$BIt makes sense, but who - or WHAT - gave us such a thing?$B$BI will share this knowledge with the druids at once.', `RewardText`) WHERE `ID` = 38246;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'That looks like it\'ll do the job nicely. $B$BLet\'s get in there before we\'re spotted.', `RewardText`) WHERE `ID` = 38312;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You should\'ve seen the look on those vrykuls\' faces when you came sailing over their wall! $B$BI could see that launcher coming in handy in a lot of places. You\'d best hold on to it.', `RewardText`) WHERE `ID` = 38318;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Well, there\'s no stopping you, is there?', `RewardText`) WHERE `ID` = 38342;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Behold, Ysera, the Emerald Queen.', `RewardText`) WHERE `ID` = 38377;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Welcome, traveler.', `RewardText`) WHERE `ID` = 38381;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Cenarius will have my aid once my grove has been made safe.', `RewardText`) WHERE `ID` = 38382;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Excellent. These should do well to protect you from the storm.', `RewardText`) WHERE `ID` = 38405;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Hah! I bet they never saw that coming!$B$BSeems like we\'ve got no shortage of obstacles left, though.', `RewardText`) WHERE `ID` = 38410;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You are here for the trial? I\'m afraid you might be too late.$B$BThis battle with these Felskorn has taken its toll. I am too weak to grant you the power you seek...$B$BBut perhaps you may be able to help...', `RewardText`) WHERE `ID` = 38412;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'The conflict against the furbolgs is abated, for now.', `RewardText`) WHERE `ID` = 38455;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It\'s good to see you, $n. Greymane sent me away to scout this village for more information on the Aegis. $B$BI haven\'t gleaned much so far, other than that the locals here don\'t seem so friendly. Of course, when are they ever?$B$BI hope your search fares better.', `RewardText`) WHERE `ID` = 38473;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Know this, $n. You did the only thing you could.$b$bWhen a mortal has become corrupted by the nightmare, there is no return. Only death will set them free.', `RewardText`) WHERE `ID` = 38582;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Oh, $n...$b$bWhat is becoming of this precious land?', `RewardText`) WHERE `ID` = 38595;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You - you bear the mark of The Dreamer. Elune be praised!$b$bYou\'ve arrived just in time, visitor. Shaladrassil\'s roots are at our doorstep...', `RewardText`) WHERE `ID` = 38641;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'We don\'t need any help, and we don\'t like strangers wanderin\' around on our land.', `RewardText`) WHERE `ID` = 38643;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'All right, I\'ll get those barrels loaded up and delivered to the village in no time.$B$BThank you, $n. There\'ll be a lot of full bellies because of you.', `RewardText`) WHERE `ID` = 38647;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It is as I feared, $r. This corruption is... irreversable.$b$bOur only course of action is to somehow find a way to fight it at its source.', `RewardText`) WHERE `ID` = 38655;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Xavius has stolen our sacred artifact?$b$bElune, forgive me. I have failed you.', `RewardText`) WHERE `ID` = 38662;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'This is dire news indeed, $n.$b$bDraw upon your courage now, friend, for Azeroth needs her heroes more than ever before.', `RewardText`) WHERE `ID` = 38663;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It is not much, but it is better than I could have hoped for. You have our gratitude.', `RewardText`) WHERE `ID` = 38671;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'This shall be remembered as one of the darkest days in the history of our world. But hope remains. Elune\'s light has strengthened our resolve.', `RewardText`) WHERE `ID` = 38743;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'My husband, Malfurion, what has become of him?!$b$bAnswer me!', `RewardText`) WHERE `ID` = 38753;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It\'s so light. So pretty, too! Reminds me of elementium, a bit.$b$bIf you see any more ore like this, try and strike it with the grain. You\'ll waste much less of it.', `RewardText`) WHERE `ID` = 38777;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Look at that! She\'s a lovely one, isn\'t she?$b$bTreat this type of ore with care, $glad:lass;. No fat-muscle shoulder swings necessary - just a gentle tap on the right spot and you\'ll extract much more ore than a beginner.', `RewardText`) WHERE `ID` = 38784;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'This is no natural stone, miner. It stinks of demon\'s blood. Where\'d you find this?$b$bReminds me a bit of old fel iron. Come \'ere, lemme teach you a trick or two on how to properly gather this stuff.', `RewardText`) WHERE `ID` = 38795;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'This came out of a cliffside seam? Remember, ye can\'t mine seams like ye mine deposits. Totally different thing. I\'ll show ye my trick.', `RewardText`) WHERE `ID` = 38796;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Uncle?', `RewardText`) WHERE `ID` = 38922;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thank you. Grisly, eh? I think I\'ll mount it over the door.$B$BI want you to have this, too. Fresh-caught mossgill was Papa\'s favorite.', `RewardText`) WHERE `ID` = 39117;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Xandris has finally paid for his crimes, but his blood will not bring back the innocents he has slain.', `RewardText`) WHERE `ID` = 39383;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'You have my thanks, $c.$b$bIf not for your arrival I would have surely perished here.', `RewardText`) WHERE `ID` = 39384;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It\'s an honor, $n.', `RewardText`) WHERE `ID` = 39735;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'I do not understand, the portals are closed and yet Skovald\'s demonic forces still assault the gates! $B$BWe must find where they are coming from!', `RewardText`) WHERE `ID` = 40003;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'With their fel leaders slain, the God-King\'s forces will scatter. $B$BStill, we are not finished here. So long as the demons continue to assault the gates, Stormheim will not be safe.', `RewardText`) WHERE `ID` = 40004;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'It\'s unfortunate that the God-King escaped, but his defeat has stemmed the flow of the Legion into Stormheim.$B$BNow, the Halls of Valor await you.', `RewardText`) WHERE `ID` = 40005;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Thaon Moonclaw was a great druid and a true protector of this land.$b$bHow can we hope to defeat the Nightmare Lord without him fighting beside us?', `RewardText`) WHERE `ID` = 40573;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'Such violence should not be necessary. Thank you, regardless.', `RewardText`) WHERE `ID` = 41707;
UPDATE `quest_offer_reward` SET `RewardText` = IF(`RewardText` IS NULL OR `RewardText` = '', 'This place remains deadly, but we can now press forward.', `RewardText`) WHERE `ID` = 43702;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'I can\'t wait to hear how my friends react!$B$BThey\'ll never expect it', `CompletionText`) WHERE `ID` = 111;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Tenacious little buggers, aren\'t they?', `CompletionText`) WHERE `ID` = 170;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'How goes the hunt?', `CompletionText`) WHERE `ID` = 183;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'You can\'t find it? My directions were very clear! We don\'t have much time, you\'ve got to hurry! Don\'t come back until you\'ve found the cave.', `CompletionText`) WHERE `ID` = 287;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Hmph!  There  is all this booze down here, but I have strict orders not to touch it.  If only I could get a taste of some of our Thunder Ale...that would sharpen my wits, no lying!', `CompletionText`) WHERE `ID` = 308;
UPDATE `quest_request_items` SET `CompletionText` = IF(`CompletionText` IS NULL OR `CompletionText` = '', 'Hey, $N.  Been to the Grizzled Den yet?  Those Wendigos can be fierce.', `CompletionText`) WHERE `ID` = 313;
