UPDATE `quest_template` SET `LogTitle` = 'The Frozen Flame', `LogDescription` = 'Obtain Felo\'melorn from Lyandra Sunstrider in Icecrown Citadel.', `QuestDescription` = 'It is time we make our move, $n. I can conjure a portal that will take you directly inside but it will take some time before I can make another and join you.$b$bThe Lich King will no doubt sense the magic of your arrival so you will need to move fast to locate Felo\'melorn and secure it.$b$bIf Lyandra has the blade with her then I fear she may not relinquish it easily. Be prepared for anything, $n.', `AreaDescription` = '', `PortraitGiverText` = '', `PortraitGiverName` = '', `PortraitTurnInText` = '', `PortraitTurnInName` = '', `QuestCompletionLog` = '' WHERE `ID` = 11997 AND `LogTitle` IN ('REUSE', 'REUSE ME', 'DEPRECATED');
UPDATE `quest_template` SET `LogTitle` = 'Before the Storm', `LogDescription` = 'Assist Grand Master Hight at the Peak of Serenity.', `QuestDescription` = '$n! I have been looking all over this strange city for you!$b$bGrand Master Hight has requested all senior monks to return to the Peak of Serenity as soon as possible. That means you too, of course.$b$bI\'ll bet a week\'s worth of brew that this has something to do with the assault on the Broken Shore I\'ve heard tales about!', `AreaDescription` = '', `PortraitGiverText` = '', `PortraitGiverName` = '', `PortraitTurnInText` = '', `PortraitTurnInName` = '', `QuestCompletionLog` = '' WHERE `ID` = 12103 AND `LogTitle` IN ('REUSE', 'REUSE ME', 'DEPRECATED');
